pub const EdgeSegmentRetentionWindow = struct {
    allocator: std.mem.Allocator,
    manifest_paths: std.ArrayList([]const u8) = .empty,

    fn init(allocator: std.mem.Allocator) EdgeSegmentRetentionWindow {
        return .{ .allocator = allocator };
    }

    fn appendOwnedManifestPath(self: *EdgeSegmentRetentionWindow, path: []const u8) !void {
        errdefer self.allocator.free(path);
        try self.manifest_paths.append(self.allocator, path);
    }

    pub fn pinnedManifestPaths(self: *const EdgeSegmentRetentionWindow) []const []const u8 {
        return self.manifest_paths.items;
    }

    pub fn deinit(self: *EdgeSegmentRetentionWindow) void {
        for (self.manifest_paths.items) |path| self.allocator.free(path);
        self.manifest_paths.deinit(self.allocator);
    }
};

const ManifestProcessLeaseKind = enum {
    edge_segment,
    node_text_run,

    fn tag(self: ManifestProcessLeaseKind) []const u8 {
        return switch (self) {
            .edge_segment => "edge-segment",
            .node_text_run => "node-text-run",
        };
    }

    fn filePrefix(self: ManifestProcessLeaseKind) []const u8 {
        return switch (self) {
            .edge_segment => "edge",
            .node_text_run => "node-text",
        };
    }
};

