const production_sort_chunk_records: usize = 128 * 1024;
const test_sort_chunk_records: usize = 1024;
const repair_sort_chunk_records: usize = if (builtin.is_test) test_sort_chunk_records else production_sort_chunk_records;
const edge_repair_sort_chunk_records: usize = repair_sort_chunk_records;
const edge_index_repair_key_run_memory_cap: usize = 1024 * 1024;
const repair_spool_mmap_max_bytes: u64 = 64 * 1024 * 1024;
const node_text_repair_sort_chunk_records: usize = repair_sort_chunk_records;
const tombstone_repair_sort_chunk_records: usize = repair_sort_chunk_records;
const edge_segment_id_sort_chunk_records: usize = repair_sort_chunk_records;
const production_node_text_delta_max_records: u64 = 4096;
const test_node_text_delta_max_records: u64 = 256;
const node_text_delta_max_records: u64 = if (builtin.is_test) test_node_text_delta_max_records else production_node_text_delta_max_records;
// Batch single out-of-order appends before publishing an L0 run, so appends
// avoid one-run-per-node manifest churn without rewriting a large delta.
const node_text_single_append_delta_flush_records: u64 = 64;
// GB100 appends 182M nodes in 65,536-node chunks, which is about 2778 L0
// node-text runs. Keep the append manifest above that so bulk ingest stays
// append-only and leaves large run consolidation to explicit maintenance.
const production_node_text_run_manifest_max_entries: usize = 4096;
const test_node_text_run_manifest_max_entries: usize = 16;
const node_text_run_manifest_max_entries: usize = if (builtin.is_test) test_node_text_run_manifest_max_entries else production_node_text_run_manifest_max_entries;
const node_text_run_max_records: u64 = 65_536;
const node_text_run_compaction_tier_ratio: u64 = 4;
const node_text_run_compaction_stack_queue_entries = 64;
const node_text_run_current_max_path_bytes: u64 = 64 * 1024;
const node_text_run_hash_filter_min_records: u64 = 8;
const node_text_run_hash_filter_min_bytes: usize = 64;
const node_text_run_hash_filter_max_bytes: usize = 256 * 1024;
// Run filters are lookup hints stored in the manifest. Writers pick a
// record-count-derived power-of-two length; readers accept any valid length so
// a non-canonical filter can only increase false positives, not hide records.
const node_text_run_hash_filter_target_bytes_per_record: u64 = 1;
const node_text_run_hash_filter_probes: usize = 7;
const node_text_base_hash_filter_min_records: u64 = 32;
const node_text_base_hash_filter_min_bytes: usize = 4 * 1024;
const node_text_base_hash_filter_max_bytes: usize = 32 * 1024 * 1024;
const node_text_base_hash_filter_target_bytes_per_record: u64 = 1;
const segment_bundle_exact_sort_chunk_records: usize = 8192;
const node_index_seen_dense_max_id: u64 = 64 * 1024 * 1024;
const node_index_seen_dense_min_id: u64 = 64 * 1024;
const node_index_seen_dense_ratio: u64 = 16;
const active_node_set_dense_max_id: u64 = 64 * 1024 * 1024;
const active_node_set_dense_min_id: u64 = 64 * 1024;
const active_node_set_dense_ratio: u64 = 16;
const graph_edge_id_set_dense_max_id: u64 = 512 * 1024 * 1024;
const graph_edge_id_set_dense_min_id: u64 = 4096;
const graph_edge_id_set_dense_ratio: u64 = 2;

const RepairIdBitSet = struct {
    bits: std.ArrayList(u8) = .empty,

    fn deinit(self: *RepairIdBitSet, allocator: std.mem.Allocator) void {
        self.bits.deinit(allocator);
    }

    fn put(self: *RepairIdBitSet, allocator: std.mem.Allocator, id: u64) !bool {
        const bit = try bitIndex(id);
        const byte_index_u64 = bit / 8;
        const byte_index = std.math.cast(usize, byte_index_u64) orelse return error.RecordTooLarge;
        if (byte_index >= self.bits.items.len) {
            const old_len = self.bits.items.len;
            const min_len = byte_index + 1;
            const doubled = std.math.mul(usize, @max(old_len, 4096), 2) catch return error.RecordTooLarge;
            const next_len = @max(min_len, doubled);
            try self.bits.resize(allocator, next_len);
            @memset(self.bits.items[old_len..], 0);
        }
        const mask = @as(u8, 1) << @intCast(bit % 8);
        const occupied = (self.bits.items[byte_index] & mask) != 0;
        self.bits.items[byte_index] |= mask;
        return occupied;
    }

    fn contains(self: RepairIdBitSet, id: u64) !bool {
        const bit = try bitIndex(id);
        const byte_index = std.math.cast(usize, bit / 8) orelse return error.RecordTooLarge;
        if (byte_index >= self.bits.items.len) return false;
        const mask = @as(u8, 1) << @intCast(bit % 8);
        return (self.bits.items[byte_index] & mask) != 0;
    }

    fn bitIndex(id: u64) !u64 {
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        return id - 1;
    }
};

const NodeIndexSeenIds = union(enum) {
    dense: Dense,
    sparse: std.AutoHashMap(u64, void),

    const Dense = struct {
        bits: std.DynamicBitSetUnmanaged,
        seen: u64 = 0,
    };

    fn init(allocator: std.mem.Allocator, max_node_id: u64, expected_nodes: u64) !NodeIndexSeenIds {
        if (try shouldUseDense(max_node_id, expected_nodes)) {
            const bit_count = std.math.cast(usize, max_node_id) orelse return error.RecordTooLarge;
            return .{ .dense = .{
                .bits = try std.DynamicBitSetUnmanaged.initEmpty(allocator, bit_count),
            } };
        }

        var sparse = std.AutoHashMap(u64, void).init(allocator);
        errdefer sparse.deinit();
        try sparse.ensureTotalCapacity(@intCast(expected_nodes));
        return .{ .sparse = sparse };
    }

    fn deinit(self: *NodeIndexSeenIds, allocator: std.mem.Allocator) void {
        switch (self.*) {
            .dense => |*dense| dense.bits.deinit(allocator),
            .sparse => |*sparse| sparse.deinit(),
        }
    }

    fn put(self: *NodeIndexSeenIds, id: u64) !bool {
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        switch (self.*) {
            .dense => |*dense| {
                const index = std.math.cast(usize, id - 1) orelse return error.RecordTooLarge;
                if (index >= dense.bits.capacity()) return error.InvalidRecord;
                const found = dense.bits.isSet(index);
                if (!found) {
                    dense.bits.set(index);
                    dense.seen = std.math.add(u64, dense.seen, 1) catch return error.InvalidRecord;
                }
                return found;
            },
            .sparse => |*sparse| return (try sparse.getOrPut(id)).found_existing,
        }
    }

    fn count(self: NodeIndexSeenIds) u64 {
        return switch (self) {
            .dense => |dense| dense.seen,
            .sparse => |sparse| sparse.count(),
        };
    }

    fn shouldUseDense(max_node_id: u64, expected_nodes: u64) !bool {
        if (expected_nodes == 0 or max_node_id == 0 or max_node_id > node_index_seen_dense_max_id) return false;
        const scaled = std.math.mul(u64, expected_nodes, node_index_seen_dense_ratio) catch node_index_seen_dense_max_id;
        return max_node_id <= @max(node_index_seen_dense_min_id, scaled);
    }
};

const NodeTextValidationHash = struct {
    text_hash: u64,
    node_digest: u64,
};

const NodeTextValidationHashes = union(enum) {
    dense: Dense,
    sparse: std.AutoHashMap(u64, NodeTextValidationHash),

    const Dense = struct {
        values: []NodeTextValidationHash,
        present: std.DynamicBitSetUnmanaged,
    };

    fn init(allocator: std.mem.Allocator, max_node_id: u64, expected_nodes: u64) !NodeTextValidationHashes {
        if (try NodeIndexSeenIds.shouldUseDense(max_node_id, expected_nodes)) {
            const count = std.math.cast(usize, max_node_id) orelse return error.RecordTooLarge;
            const values = try allocator.alloc(NodeTextValidationHash, count);
            errdefer allocator.free(values);
            return .{ .dense = .{
                .values = values,
                .present = try std.DynamicBitSetUnmanaged.initEmpty(allocator, count),
            } };
        }

        var sparse = std.AutoHashMap(u64, NodeTextValidationHash).init(allocator);
        errdefer sparse.deinit();
        try sparse.ensureTotalCapacity(@intCast(expected_nodes));
        return .{ .sparse = sparse };
    }

    fn deinit(self: *NodeTextValidationHashes, allocator: std.mem.Allocator) void {
        switch (self.*) {
            .dense => |*dense| {
                dense.present.deinit(allocator);
                allocator.free(dense.values);
            },
            .sparse => |*sparse| sparse.deinit(),
        }
    }

    fn estimatedBytes(self: *const NodeTextValidationHashes) u64 {
        return switch (self.*) {
            .dense => |*dense| blk: {
                const values_bytes: u64 = @intCast(dense.values.len * @sizeOf(NodeTextValidationHash));
                const bit_bytes: u64 = @intCast((dense.present.capacity() + 7) / 8);
                break :blk values_bytes + bit_bytes;
            },
            .sparse => |*sparse| @as(u64, @intCast(sparse.capacity())) * (@sizeOf(u64) + @sizeOf(NodeTextValidationHash)),
        };
    }

    fn put(self: *NodeTextValidationHashes, id: u64, value: NodeTextValidationHash) !void {
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        switch (self.*) {
            .dense => |*dense| {
                const index = std.math.cast(usize, id - 1) orelse return error.RecordTooLarge;
                if (index >= dense.values.len) return error.InvalidRecord;
                dense.values[index] = value;
                dense.present.set(index);
            },
            .sparse => |*sparse| try sparse.put(id, value),
        }
    }

    fn get(self: *const NodeTextValidationHashes, id: u64) !NodeTextValidationHash {
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        return switch (self.*) {
            .dense => |*dense| blk: {
                const index = std.math.cast(usize, id - 1) orelse return error.RecordTooLarge;
                if (index >= dense.values.len or !dense.present.isSet(index)) return error.InvalidRecord;
                break :blk dense.values[index];
            },
            .sparse => |*sparse| sparse.get(id) orelse error.InvalidRecord,
        };
    }
};

const repair_dense_edge_digest_max_id: u64 = 64 * 1024 * 1024;

const RepairEdgeDigestIndex = struct {
    digests: std.ArrayList(u64) = .empty,
    seen_dense: RepairIdBitSet = .{},
    deleted_dense: RepairIdBitSet = .{},
    overflow: std.AutoHashMap(u64, u64),
    overflow_deleted: std.AutoHashMap(u64, void),

    fn init(allocator: std.mem.Allocator) RepairEdgeDigestIndex {
        return .{
            .overflow = std.AutoHashMap(u64, u64).init(allocator),
            .overflow_deleted = std.AutoHashMap(u64, void).init(allocator),
        };
    }

    fn deinit(self: *RepairEdgeDigestIndex, allocator: std.mem.Allocator) void {
        self.overflow_deleted.deinit();
        self.overflow.deinit();
        self.deleted_dense.deinit(allocator);
        self.seen_dense.deinit(allocator);
        self.digests.deinit(allocator);
    }

    fn put(self: *RepairEdgeDigestIndex, allocator: std.mem.Allocator, edge_id: u64, digest: u64, record_count_so_far: usize) !bool {
        if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const dense_limit = try denseLimitForRecordCount(record_count_so_far);
        if (edge_id <= dense_limit) {
            if (self.overflow.contains(edge_id)) return true;
            const occupied = try self.seen_dense.put(allocator, edge_id);
            if (occupied) return true;
            const index = std.math.cast(usize, edge_id - 1) orelse return error.RecordTooLarge;
            if (index >= self.digests.items.len) {
                const old_len = self.digests.items.len;
                const min_len = index + 1;
                const doubled = std.math.mul(usize, @max(old_len, 4096), 2) catch return error.RecordTooLarge;
                const next_len = @max(min_len, doubled);
                try self.digests.resize(allocator, next_len);
            }
            self.digests.items[index] = digest;
            return false;
        }

        const entry = try self.overflow.getOrPut(edge_id);
        if (entry.found_existing) return true;
        entry.value_ptr.* = digest;
        return false;
    }

    fn delete(self: *RepairEdgeDigestIndex, allocator: std.mem.Allocator, edge_id: u64) !?u64 {
        if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        if (edge_id <= repair_dense_edge_digest_max_id) {
            if (try self.seen_dense.contains(edge_id)) {
                if (try self.deleted_dense.put(allocator, edge_id)) return error.InvalidRecord;
                const index = std.math.cast(usize, edge_id - 1) orelse return error.RecordTooLarge;
                if (index >= self.digests.items.len) return error.InvalidRecord;
                return self.digests.items[index];
            }
        }

        const digest = self.overflow.get(edge_id) orelse return null;
        const deleted = try self.overflow_deleted.getOrPut(edge_id);
        if (deleted.found_existing) return error.InvalidRecord;
        return digest;
    }

    fn denseLimitForRecordCount(record_count_so_far: usize) !u64 {
        const count = std.math.add(u64, @intCast(record_count_so_far), 1) catch return error.RecordTooLarge;
        const expanded = std.math.mul(u64, count, 2) catch return error.RecordTooLarge;
        return @min(repair_dense_edge_digest_max_id, @max(@as(u64, 4096), expanded));
    }
};

const RepairEdgeReplayTracker = struct {
    allocator: std.mem.Allocator,
    ids: RepairIdBitSet = .{},
    digests: ?RepairEdgeDigestIndex = null,

    fn init(allocator: std.mem.Allocator) RepairEdgeReplayTracker {
        return .{ .allocator = allocator };
    }

    fn deinit(self: *RepairEdgeReplayTracker) void {
        if (self.digests) |*digests| digests.deinit(self.allocator);
        self.ids.deinit(self.allocator);
    }

    fn put(self: *RepairEdgeReplayTracker, edge_id: u64, digest: u64, record_count_so_far: usize) !bool {
        if (self.digests) |*digests| {
            return digests.put(self.allocator, edge_id, digest, record_count_so_far);
        }
        return self.ids.put(self.allocator, edge_id);
    }

    fn delete(
        self: *RepairEdgeReplayTracker,
        store: Store,
        edge_file: std.Io.File,
        edge_writer: *StorageBufferedWriter,
        edge_id: u64,
        record_count: usize,
    ) !?u64 {
        try self.ensureDigestIndex(store, edge_file, edge_writer, record_count);
        if (self.digests) |*digests| return digests.delete(self.allocator, edge_id);
        return error.InvalidRecord;
    }

    fn ensureDigestIndex(
        self: *RepairEdgeReplayTracker,
        store: Store,
        edge_file: std.Io.File,
        edge_writer: *StorageBufferedWriter,
        record_count: usize,
    ) !void {
        if (self.digests != null) return;

        try edge_writer.flush();
        const expected_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try edge_writer.position() != expected_size) return error.InvalidRecord;
        if (try store.regularFileSize(edge_file) != expected_size) return error.InvalidRecord;

        var digests = RepairEdgeDigestIndex.init(self.allocator);
        errdefer digests.deinit(self.allocator);

        const chunk_records: usize = 8192;
        const chunk_bytes_len = std.math.mul(usize, chunk_records, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        const chunk_bytes = try self.allocator.alloc(u8, chunk_bytes_len);
        defer self.allocator.free(chunk_bytes);

        var read_pos: usize = 0;
        while (read_pos < record_count) {
            const take = @min(chunk_records, record_count - read_pos);
            const byte_count = std.math.mul(usize, take, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
            const offset = std.math.mul(u64, @intCast(read_pos), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
            const n = try edge_file.readPositionalAll(store.io, chunk_bytes[0..byte_count], offset);
            if (n != byte_count) return error.InvalidRecord;

            var cursor: usize = 0;
            var index: usize = 0;
            while (index < take) : (index += 1) {
                const bytes = chunk_bytes[cursor .. cursor + EdgeIndexRecord.encoded_len];
                const record = try EdgeIndexRecord.decodeSlice(bytes);
                const record_ordinal = read_pos + index;
                if (try digests.put(self.allocator, record.edge_id, edgeRecordDigest(record), record_ordinal)) return error.InvalidRecord;
                cursor += EdgeIndexRecord.encoded_len;
            }
            read_pos += take;
        }

        self.ids.deinit(self.allocator);
        self.ids = .{};
        self.digests = digests;
    }
};

const StorageBufferedWriter = struct {
    io: std.Io,
    file: std.Io.File,
    allocator: std.mem.Allocator,
    buffer: []u8,
    len: usize = 0,
    offset: u64 = 0,

    fn init(allocator: std.mem.Allocator, io: std.Io, file: std.Io.File, capacity: usize) !StorageBufferedWriter {
        std.debug.assert(capacity > 0);
        return .{
            .io = io,
            .file = file,
            .allocator = allocator,
            .buffer = try allocator.alloc(u8, capacity),
        };
    }

    fn initAtOffset(allocator: std.mem.Allocator, io: std.Io, file: std.Io.File, capacity: usize, offset: u64) !StorageBufferedWriter {
        var writer = try init(allocator, io, file, capacity);
        writer.offset = offset;
        return writer;
    }

    fn deinit(self: *StorageBufferedWriter) void {
        self.allocator.free(self.buffer);
    }

    fn append(self: *StorageBufferedWriter, bytes: []const u8) !void {
        if (bytes.len > self.buffer.len) {
            try self.flush();
            try self.file.writePositionalAll(self.io, bytes, self.offset);
            self.offset = std.math.add(u64, self.offset, bytes.len) catch return error.InvalidRecord;
            return;
        }
        if (self.len + bytes.len > self.buffer.len) try self.flush();
        @memcpy(self.buffer[self.len .. self.len + bytes.len], bytes);
        self.len += bytes.len;
    }

    fn flush(self: *StorageBufferedWriter) !void {
        if (self.len == 0) return;
        try self.file.writePositionalAll(self.io, self.buffer[0..self.len], self.offset);
        self.offset = std.math.add(u64, self.offset, self.len) catch return error.InvalidRecord;
        self.len = 0;
    }

    fn position(self: StorageBufferedWriter) !u64 {
        return std.math.add(u64, self.offset, self.len) catch return error.InvalidRecord;
    }
};

fn storageWriteBufferCapacity(file_size: u64) !usize {
    const size = std.math.cast(usize, file_size) orelse return error.RecordTooLarge;
    return @min(storage_write_buffer_bytes, size);
}

pub const IndexMeta = struct {
    event_bytes: u64 = 0,
    nodes: u64 = 0,
    edges: u64 = 0,
    node_digest: u64 = 0,
    edge_digest: u64 = 0,
    node_by_text_order_digest: u64 = 0,
    edge_indexed_edges: u64 = 0,
    edge_index_digest: u64 = 0,
    edge_by_id_order_digest: u64 = 0,
    edge_by_src_order_digest: u64 = 0,
    edge_by_dst_order_digest: u64 = 0,
    max_edge_id_seen: u64 = 0,
    edge_by_id_runs: EdgeSegmentIdRunSummary = .{},
    edge_segment_edges: u64 = 0,
    edge_segment_manifest_digest: u64 = 0,
    edge_segment_id_runs: EdgeSegmentIdRunSummary = .{},

    const magic = [_]u8{ 'T', 'K', 'G', 'I' };
    const version: u16 = 9;
    const encoded_len: usize = 200;

    fn encode(self: IndexMeta, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.event_bytes, .little);
        std.mem.writeInt(u64, out[16..24], self.nodes, .little);
        std.mem.writeInt(u64, out[24..32], self.edges, .little);
        std.mem.writeInt(u64, out[32..40], self.node_digest, .little);
        std.mem.writeInt(u64, out[40..48], self.edge_digest, .little);
        std.mem.writeInt(u64, out[48..56], self.node_by_text_order_digest, .little);
        std.mem.writeInt(u64, out[56..64], self.edge_indexed_edges, .little);
        std.mem.writeInt(u64, out[64..72], self.edge_index_digest, .little);
        std.mem.writeInt(u64, out[72..80], self.edge_by_id_order_digest, .little);
        std.mem.writeInt(u64, out[80..88], self.edge_by_src_order_digest, .little);
        std.mem.writeInt(u64, out[88..96], self.edge_by_dst_order_digest, .little);
        std.mem.writeInt(u64, out[96..104], self.max_edge_id_seen, .little);
        std.mem.writeInt(u64, out[104..112], self.edge_by_id_runs.run_count, .little);
        std.mem.writeInt(u64, out[112..120], self.edge_by_id_runs.first_min, .little);
        std.mem.writeInt(u64, out[120..128], self.edge_by_id_runs.first_max, .little);
        std.mem.writeInt(u64, out[128..136], self.edge_by_id_runs.second_min, .little);
        std.mem.writeInt(u64, out[136..144], self.edge_by_id_runs.second_max, .little);
        std.mem.writeInt(u64, out[144..152], self.edge_segment_edges, .little);
        std.mem.writeInt(u64, out[152..160], self.edge_segment_manifest_digest, .little);
        std.mem.writeInt(u64, out[160..168], self.edge_segment_id_runs.run_count, .little);
        std.mem.writeInt(u64, out[168..176], self.edge_segment_id_runs.first_min, .little);
        std.mem.writeInt(u64, out[176..184], self.edge_segment_id_runs.first_max, .little);
        std.mem.writeInt(u64, out[184..192], self.edge_segment_id_runs.second_min, .little);
        std.mem.writeInt(u64, out[192..200], self.edge_segment_id_runs.second_max, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !IndexMeta {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        const edge_by_id_runs = EdgeSegmentIdRunSummary{
            .run_count = std.mem.readInt(u64, bytes[104..112], .little),
            .first_min = std.mem.readInt(u64, bytes[112..120], .little),
            .first_max = std.mem.readInt(u64, bytes[120..128], .little),
            .second_min = std.mem.readInt(u64, bytes[128..136], .little),
            .second_max = std.mem.readInt(u64, bytes[136..144], .little),
        };
        try edge_by_id_runs.validate();
        const edge_segment_id_runs = EdgeSegmentIdRunSummary{
            .run_count = std.mem.readInt(u64, bytes[160..168], .little),
            .first_min = std.mem.readInt(u64, bytes[168..176], .little),
            .first_max = std.mem.readInt(u64, bytes[176..184], .little),
            .second_min = std.mem.readInt(u64, bytes[184..192], .little),
            .second_max = std.mem.readInt(u64, bytes[192..200], .little),
        };
        try edge_segment_id_runs.validate();
        const edge_segment_edges = std.mem.readInt(u64, bytes[144..152], .little);
        if (edge_segment_edges == 0 and
            (std.mem.readInt(u64, bytes[152..160], .little) != 0 or edge_segment_id_runs.run_count != 0))
        {
            return error.InvalidRecord;
        }
        return .{
            .event_bytes = std.mem.readInt(u64, bytes[8..16], .little),
            .nodes = std.mem.readInt(u64, bytes[16..24], .little),
            .edges = std.mem.readInt(u64, bytes[24..32], .little),
            .node_digest = std.mem.readInt(u64, bytes[32..40], .little),
            .edge_digest = std.mem.readInt(u64, bytes[40..48], .little),
            .node_by_text_order_digest = std.mem.readInt(u64, bytes[48..56], .little),
            .edge_indexed_edges = std.mem.readInt(u64, bytes[56..64], .little),
            .edge_index_digest = std.mem.readInt(u64, bytes[64..72], .little),
            .edge_by_id_order_digest = std.mem.readInt(u64, bytes[72..80], .little),
            .edge_by_src_order_digest = std.mem.readInt(u64, bytes[80..88], .little),
            .edge_by_dst_order_digest = std.mem.readInt(u64, bytes[88..96], .little),
            .max_edge_id_seen = std.mem.readInt(u64, bytes[96..104], .little),
            .edge_by_id_runs = edge_by_id_runs,
            .edge_segment_edges = edge_segment_edges,
            .edge_segment_manifest_digest = std.mem.readInt(u64, bytes[152..160], .little),
            .edge_segment_id_runs = edge_segment_id_runs,
        };
    }
};

pub const EdgeIndexOrder = enum(u8) {
    id = 'I',
    src = 'S',
    dst = 'D',
};

const EdgeIndexRelDerivation = struct {
    default_rel: u16,
    exception_count: u8 = 0,
    exception_edge_ids: [2]u64 = .{ 0, 0 },
    exception_rels: [2]u16 = .{ 0, 0 },
};

const EdgeIndexDenseKeyRunSpan = struct {
    run_start: u64,
    count: u64,
    key_base: u64,
    start_base: u64,
    start_step: u64,
    edge_id_base: u64,
    edge_id_base_step: u64,
};

pub const EdgeIndexHeader = struct {
    order: EdgeIndexOrder,
    edge_count: u64,
    edge_digest: u64 = 0,
    order_digest: u64 = 0,
    flags: u16 = 0,
    record_len: u16 = EdgeIndexRecord.encoded_len,
    default_rel: u16 = 0,
    rel_exception_count: u8 = 0,
    key_run_count: u32 = 0,
    key_run_opposite_mod: u64 = 0,
    key_run_edge_id_step: u64 = 0,
    key_run_dense_run_start: u64 = 0,
    key_run_dense_count: u64 = 0,
    key_run_dense_key_base: u64 = 0,
    key_run_dense_start_base: u64 = 0,
    key_run_dense_start_step: u64 = 0,
    key_run_dense_edge_id_base: u64 = 0,
    key_run_dense_edge_id_base_step: u64 = 0,
    rel_exception_edge_ids: [2]u64 = .{ 0, 0 },
    rel_exception_rels: [2]u16 = .{ 0, 0 },

    const magic = [_]u8{ 'T', 'K', 'G', 'X' };
    const version: u16 = 15;
    pub const encoded_len: usize = 112;
    const flag_dense_id: u16 = 1 << 0;
    const flag_derived_rel: u16 = 1 << 1;
    const flag_u32_node_ids: u16 = 1 << 2;
    const flag_u32_edge_ids: u16 = 1 << 3;
    const flag_key_runs: u16 = 1 << 4;
    const flag_key_run_linear_edge_ids: u16 = 1 << 5;
    const flag_key_run_constant_opposite: u16 = 1 << 6;
    const flag_key_run_ring_opposite: u16 = 1 << 7;
    const flag_key_run_uniform_edge_id_step: u16 = 1 << 8;
    const flag_key_run_dense_span: u16 = 1 << 9;

    fn encode(self: EdgeIndexHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        out[8] = @intFromEnum(self.order);
        out[9] = 0;
        std.mem.writeInt(u16, out[10..12], self.flags, .little);
        std.mem.writeInt(u16, out[12..14], self.record_len, .little);
        std.mem.writeInt(u16, out[14..16], self.default_rel, .little);
        std.mem.writeInt(u64, out[16..24], self.edge_count, .little);
        std.mem.writeInt(u64, out[24..32], self.edge_digest, .little);
        std.mem.writeInt(u64, out[32..40], self.order_digest, .little);
        out[40] = self.rel_exception_count;
        std.mem.writeInt(u32, out[41..45], self.key_run_count, .little);
        @memset(out[45..48], 0);
        std.mem.writeInt(u64, out[48..56], self.rel_exception_edge_ids[0], .little);
        std.mem.writeInt(u64, out[56..64], self.rel_exception_edge_ids[1], .little);
        std.mem.writeInt(u16, out[64..66], self.rel_exception_rels[0], .little);
        std.mem.writeInt(u16, out[66..68], self.rel_exception_rels[1], .little);
        @memset(out[68..72], 0);
        std.mem.writeInt(u32, out[72..76], @intCast(self.key_run_opposite_mod), .little);
        std.mem.writeInt(u32, out[76..80], @intCast(self.key_run_edge_id_step), .little);
        std.mem.writeInt(u32, out[80..84], @intCast(self.key_run_dense_run_start), .little);
        std.mem.writeInt(u32, out[84..88], @intCast(self.key_run_dense_count), .little);
        std.mem.writeInt(u32, out[88..92], @intCast(self.key_run_dense_key_base), .little);
        std.mem.writeInt(u32, out[92..96], @intCast(self.key_run_dense_start_base), .little);
        std.mem.writeInt(u32, out[96..100], @intCast(self.key_run_dense_start_step), .little);
        std.mem.writeInt(u32, out[100..104], @intCast(self.key_run_dense_edge_id_base), .little);
        std.mem.writeInt(u32, out[104..108], @intCast(self.key_run_dense_edge_id_base_step), .little);
        @memset(out[108..112], 0);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeIndexHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        const order: EdgeIndexOrder = switch (bytes[8]) {
            'I' => .id,
            'S' => .src,
            'D' => .dst,
            else => return error.InvalidRecord,
        };
        if (bytes[9] != 0) return error.InvalidRecord;
        const header = EdgeIndexHeader{
            .order = order,
            .edge_count = std.mem.readInt(u64, bytes[16..24], .little),
            .edge_digest = std.mem.readInt(u64, bytes[24..32], .little),
            .order_digest = std.mem.readInt(u64, bytes[32..40], .little),
            .flags = std.mem.readInt(u16, bytes[10..12], .little),
            .record_len = std.mem.readInt(u16, bytes[12..14], .little),
            .default_rel = std.mem.readInt(u16, bytes[14..16], .little),
            .rel_exception_count = bytes[40],
            .key_run_count = std.mem.readInt(u32, bytes[41..45], .little),
            .rel_exception_edge_ids = .{
                std.mem.readInt(u64, bytes[48..56], .little),
                std.mem.readInt(u64, bytes[56..64], .little),
            },
            .rel_exception_rels = .{
                std.mem.readInt(u16, bytes[64..66], .little),
                std.mem.readInt(u16, bytes[66..68], .little),
            },
            .key_run_opposite_mod = std.mem.readInt(u32, bytes[72..76], .little),
            .key_run_edge_id_step = std.mem.readInt(u32, bytes[76..80], .little),
            .key_run_dense_run_start = std.mem.readInt(u32, bytes[80..84], .little),
            .key_run_dense_count = std.mem.readInt(u32, bytes[84..88], .little),
            .key_run_dense_key_base = std.mem.readInt(u32, bytes[88..92], .little),
            .key_run_dense_start_base = std.mem.readInt(u32, bytes[92..96], .little),
            .key_run_dense_start_step = std.mem.readInt(u32, bytes[96..100], .little),
            .key_run_dense_edge_id_base = std.mem.readInt(u32, bytes[100..104], .little),
            .key_run_dense_edge_id_base_step = std.mem.readInt(u32, bytes[104..108], .little),
        };
        if (!allZero(bytes[45..48]) or !allZero(bytes[68..72]) or !allZero(bytes[108..112])) return error.InvalidRecord;
        try header.validateShape();
        return header;
    }

    fn validateShape(self: EdgeIndexHeader) !void {
        const known_flags = flag_dense_id | flag_derived_rel | flag_u32_node_ids | flag_u32_edge_ids | flag_key_runs | flag_key_run_linear_edge_ids | flag_key_run_constant_opposite | flag_key_run_ring_opposite | flag_key_run_uniform_edge_id_step | flag_key_run_dense_span;
        if ((self.flags & ~known_flags) != 0) return error.InvalidRecord;
        if (self.hasDenseId() and self.order != .id) return error.InvalidRecord;
        if (self.hasDenseId() and self.hasU32EdgeIds()) return error.InvalidRecord;
        if (self.hasKeyRuns()) {
            if (self.edge_count == 0 or self.key_run_count == 0) return error.InvalidRecord;
            if (self.key_run_count > self.edge_count) return error.InvalidRecord;
            if (self.edge_count > std.math.maxInt(u32) and self.hasU32NodeIds()) return error.InvalidRecord;
            if (self.order == .id) {
                if (!self.hasDenseId()) return error.InvalidRecord;
                if (!self.hasU32NodeIds()) return error.InvalidRecord;
                if (!self.hasKeyRunConstantOpposite()) return error.InvalidRecord;
                if (self.hasKeyRunLinearEdgeIds()) return error.InvalidRecord;
            }
        } else if (self.key_run_count != 0) {
            return error.InvalidRecord;
        }
        if (self.hasKeyRunLinearEdgeIds() and !self.hasKeyRuns()) return error.InvalidRecord;
        if (self.hasKeyRunConstantOpposite() and !self.hasKeyRuns()) return error.InvalidRecord;
        if (self.hasKeyRunRingOpposite()) {
            if (!self.hasKeyRuns() or !self.hasKeyRunConstantOpposite()) return error.InvalidRecord;
            if (self.order == .id) return error.InvalidRecord;
            if (self.key_run_opposite_mod == 0 or self.key_run_opposite_mod > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.hasU32NodeIds() and self.key_run_opposite_mod > std.math.maxInt(u32)) return error.InvalidRecord;
        } else if (self.key_run_opposite_mod != 0) {
            return error.InvalidRecord;
        }
        if (self.hasKeyRunUniformEdgeIdStep()) {
            if (!self.hasKeyRunLinearEdgeIds()) return error.InvalidRecord;
            if (self.key_run_edge_id_step == 0 or self.key_run_edge_id_step > std.math.maxInt(u32)) return error.InvalidRecord;
        } else if (self.key_run_edge_id_step != 0) {
            return error.InvalidRecord;
        }
        if (self.hasKeyRunDenseSpan()) {
            if (!self.hasKeyRunRingOpposite() or !self.hasKeyRunUniformEdgeIdStep()) return error.InvalidRecord;
            if (!self.hasU32NodeIds() or !self.hasU32EdgeIds()) return error.InvalidRecord;
            if (self.key_run_dense_run_start >= self.key_run_count) return error.InvalidRecord;
            if (self.key_run_dense_count == 0 or self.key_run_dense_count > self.key_run_count) return error.InvalidRecord;
            const dense_run_end = std.math.add(u64, self.key_run_dense_run_start, self.key_run_dense_count) catch return error.InvalidRecord;
            if (dense_run_end > self.key_run_count) return error.InvalidRecord;
            if (self.key_run_dense_run_start > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.key_run_dense_count > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.key_run_dense_key_base == 0 or self.key_run_dense_key_base > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.key_run_dense_start_base > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.key_run_dense_start_step == 0 or self.key_run_dense_start_step > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.key_run_dense_edge_id_base == 0 or self.key_run_dense_edge_id_base > std.math.maxInt(u32)) return error.InvalidRecord;
            if (self.key_run_dense_edge_id_base_step == 0 or self.key_run_dense_edge_id_base_step > std.math.maxInt(u32)) return error.InvalidRecord;
            const last_index = self.key_run_dense_count - 1;
            const last_key_delta = std.math.mul(u64, last_index, 1) catch return error.InvalidRecord;
            const last_key = std.math.add(u64, self.key_run_dense_key_base, last_key_delta) catch return error.InvalidRecord;
            if (last_key > self.key_run_opposite_mod or last_key > std.math.maxInt(u32)) return error.InvalidRecord;
            const last_start_delta = std.math.mul(u64, last_index, self.key_run_dense_start_step) catch return error.InvalidRecord;
            const last_start = std.math.add(u64, self.key_run_dense_start_base, last_start_delta) catch return error.InvalidRecord;
            if (last_start >= self.edge_count) return error.InvalidRecord;
            const last_edge_base_delta = std.math.mul(u64, last_index, self.key_run_dense_edge_id_base_step) catch return error.InvalidRecord;
            const last_edge_base = std.math.add(u64, self.key_run_dense_edge_id_base, last_edge_base_delta) catch return error.InvalidRecord;
            if (last_edge_base > std.math.maxInt(u32)) return error.InvalidRecord;
        } else if (self.key_run_dense_run_start != 0 or self.key_run_dense_count != 0 or self.key_run_dense_key_base != 0 or self.key_run_dense_start_base != 0 or self.key_run_dense_start_step != 0 or self.key_run_dense_edge_id_base != 0 or self.key_run_dense_edge_id_base_step != 0) {
            return error.InvalidRecord;
        }
        if (self.hasDerivedRel()) {
            if (relKindFromInt(self.default_rel) == null) return error.InvalidRecord;
            if (self.rel_exception_count > self.rel_exception_edge_ids.len) return error.InvalidRecord;
            var previous_id: u64 = 0;
            for (0..self.rel_exception_edge_ids.len) |i| {
                const id = self.rel_exception_edge_ids[i];
                const rel = self.rel_exception_rels[i];
                if (i < self.rel_exception_count) {
                    if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
                    if (i != 0 and id <= previous_id) return error.InvalidRecord;
                    if (relKindFromInt(rel) == null) return error.InvalidRecord;
                    if (rel == self.default_rel) return error.InvalidRecord;
                    previous_id = id;
                } else {
                    if (id != 0 or rel != 0) return error.InvalidRecord;
                }
            }
        } else {
            if (self.default_rel != 0 or self.rel_exception_count != 0) return error.InvalidRecord;
            if (self.rel_exception_edge_ids[0] != 0 or self.rel_exception_edge_ids[1] != 0) return error.InvalidRecord;
            if (self.rel_exception_rels[0] != 0 or self.rel_exception_rels[1] != 0) return error.InvalidRecord;
        }
        if (self.record_len != self.expectedRecordLen()) return error.InvalidRecord;
    }

    fn hasDenseId(self: EdgeIndexHeader) bool {
        return (self.flags & flag_dense_id) != 0;
    }

    fn hasDerivedRel(self: EdgeIndexHeader) bool {
        return (self.flags & flag_derived_rel) != 0;
    }

    fn hasU32NodeIds(self: EdgeIndexHeader) bool {
        return (self.flags & flag_u32_node_ids) != 0;
    }

    fn hasU32EdgeIds(self: EdgeIndexHeader) bool {
        return (self.flags & flag_u32_edge_ids) != 0;
    }

    fn hasKeyRuns(self: EdgeIndexHeader) bool {
        return (self.flags & flag_key_runs) != 0;
    }

    fn hasKeyRunLinearEdgeIds(self: EdgeIndexHeader) bool {
        return (self.flags & flag_key_run_linear_edge_ids) != 0;
    }

    fn hasKeyRunConstantOpposite(self: EdgeIndexHeader) bool {
        return (self.flags & flag_key_run_constant_opposite) != 0;
    }

    fn hasKeyRunRingOpposite(self: EdgeIndexHeader) bool {
        return (self.flags & flag_key_run_ring_opposite) != 0;
    }

    fn hasKeyRunUniformEdgeIdStep(self: EdgeIndexHeader) bool {
        return (self.flags & flag_key_run_uniform_edge_id_step) != 0;
    }

    fn hasKeyRunDenseSpan(self: EdgeIndexHeader) bool {
        return (self.flags & flag_key_run_dense_span) != 0;
    }

    fn expectedRecordLen(self: EdgeIndexHeader) u16 {
        var len: u16 = EdgeIndexRecord.encoded_len;
        if (self.hasU32NodeIds()) len -= 8;
        if (self.hasKeyRuns()) len -= if (self.hasU32NodeIds()) 4 else 8;
        if (self.hasKeyRunConstantOpposite()) len -= if (self.hasU32NodeIds()) 4 else 8;
        if (self.hasDenseId() or self.hasKeyRunLinearEdgeIds()) {
            len -= 8;
        } else if (self.hasU32EdgeIds()) {
            len -= 4;
        }
        if (self.hasDerivedRel()) len -= 2;
        return len;
    }

    fn relForEdgeId(self: EdgeIndexHeader, edge_id: u64) !u16 {
        try self.validateShape();
        if (!self.hasDerivedRel()) return error.InvalidRecord;
        var pos: usize = 0;
        while (pos < self.rel_exception_count) : (pos += 1) {
            if (edge_id == self.rel_exception_edge_ids[pos]) return self.rel_exception_rels[pos];
        }
        return self.default_rel;
    }

    fn withShape(order: EdgeIndexOrder, edge_count: u64, edge_digest: u64, order_digest: u64, dense_id: bool, u32_node_ids: bool, u32_edge_ids: bool, rel_derivation: ?EdgeIndexRelDerivation) EdgeIndexHeader {
        var header = EdgeIndexHeader{
            .order = order,
            .edge_count = edge_count,
            .edge_digest = edge_digest,
            .order_digest = order_digest,
        };
        if (dense_id) header.flags |= flag_dense_id;
        if (u32_node_ids) header.flags |= flag_u32_node_ids;
        if (!dense_id and u32_edge_ids) header.flags |= flag_u32_edge_ids;
        if (rel_derivation) |derived| {
            header.flags |= flag_derived_rel;
            header.default_rel = derived.default_rel;
            header.rel_exception_count = derived.exception_count;
            header.rel_exception_edge_ids = derived.exception_edge_ids;
            header.rel_exception_rels = derived.exception_rels;
        }
        header.record_len = header.expectedRecordLen();
        return header;
    }

    fn withKeyRuns(self: EdgeIndexHeader, key_run_count: u32, constant_opposite: bool, linear_edge_ids: bool) EdgeIndexHeader {
        var header = self;
        header.flags |= flag_key_runs;
        header.flags &= ~flag_key_run_ring_opposite;
        header.flags &= ~flag_key_run_uniform_edge_id_step;
        header.flags &= ~flag_key_run_dense_span;
        if (constant_opposite) header.flags |= flag_key_run_constant_opposite;
        if (linear_edge_ids) header.flags |= flag_key_run_linear_edge_ids;
        header.key_run_count = key_run_count;
        header.key_run_opposite_mod = 0;
        header.key_run_edge_id_step = 0;
        header.key_run_dense_run_start = 0;
        header.key_run_dense_count = 0;
        header.key_run_dense_key_base = 0;
        header.key_run_dense_start_base = 0;
        header.key_run_dense_start_step = 0;
        header.key_run_dense_edge_id_base = 0;
        header.key_run_dense_edge_id_base_step = 0;
        header.record_len = header.expectedRecordLen();
        return header;
    }

    fn withKeyRunRingOpposite(self: EdgeIndexHeader, opposite_mod: u64) EdgeIndexHeader {
        var header = self;
        header.flags |= flag_key_run_ring_opposite;
        header.key_run_opposite_mod = opposite_mod;
        header.record_len = header.expectedRecordLen();
        return header;
    }

    fn withKeyRunUniformEdgeIdStep(self: EdgeIndexHeader, edge_id_step: u64) EdgeIndexHeader {
        var header = self;
        header.flags |= flag_key_run_uniform_edge_id_step;
        header.key_run_edge_id_step = edge_id_step;
        header.record_len = header.expectedRecordLen();
        return header;
    }

    fn withKeyRunDenseSpan(self: EdgeIndexHeader, dense: EdgeIndexDenseKeyRunSpan) EdgeIndexHeader {
        var header = self;
        header.flags |= flag_key_run_dense_span;
        header.key_run_dense_run_start = dense.run_start;
        header.key_run_dense_count = dense.count;
        header.key_run_dense_key_base = dense.key_base;
        header.key_run_dense_start_base = dense.start_base;
        header.key_run_dense_start_step = dense.start_step;
        header.key_run_dense_edge_id_base = dense.edge_id_base;
        header.key_run_dense_edge_id_base_step = dense.edge_id_base_step;
        header.record_len = header.expectedRecordLen();
        return header;
    }

    fn denseId(edge_count: u64, edge_digest: u64, order_digest: u64) EdgeIndexHeader {
        return withShape(.id, edge_count, edge_digest, order_digest, true, false, false, null);
    }
};

pub const EdgeIndexRecord = struct {
    src: u64,
    dst: u64,
    edge_id: u64,
    rel: u16,

    const encoded_len: usize = 26;
    const dense_id_encoded_len: usize = 18;
    const derived_rel_encoded_len: usize = 24;
    const dense_id_derived_rel_encoded_len: usize = 16;
    const u32_nodes_encoded_len: usize = 18;
    const u32_nodes_dense_id_encoded_len: usize = 10;
    const u32_nodes_derived_rel_encoded_len: usize = 16;
    const u32_nodes_dense_id_derived_rel_encoded_len: usize = 8;
    const u32_nodes_u32_edge_id_derived_rel_encoded_len: usize = 12;

    fn encode(self: EdgeIndexRecord, out: *[encoded_len]u8) void {
        std.mem.writeInt(u64, out[0..8], self.src, .little);
        std.mem.writeInt(u64, out[8..16], self.dst, .little);
        std.mem.writeInt(u64, out[16..24], self.edge_id, .little);
        std.mem.writeInt(u16, out[24..26], self.rel, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeIndexRecord {
        return decodeSlice(bytes);
    }

    fn decodeSlice(bytes: []const u8) !EdgeIndexRecord {
        if (bytes.len != encoded_len) return error.InvalidRecord;
        const rel = std.mem.readInt(u16, bytes[24..26], .little);
        if (relKindFromInt(rel) == null) return error.InvalidRecord;
        const src = std.mem.readInt(u64, bytes[0..8], .little);
        const dst = std.mem.readInt(u64, bytes[8..16], .little);
        const edge_id = std.mem.readInt(u64, bytes[16..24], .little);
        if (edge_id == 0 or src == 0 or dst == 0) return error.InvalidRecord;
        if (edge_id == std.math.maxInt(u64) or src == std.math.maxInt(u64) or dst == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .src = src,
            .dst = dst,
            .edge_id = edge_id,
            .rel = rel,
        };
    }

    fn encodeForHeader(self: EdgeIndexRecord, header: EdgeIndexHeader, index: u64, run: ?EdgeIndexKeyRunRecord, out: []u8) !void {
        try header.validateShape();
        if (out.len != header.record_len) return error.InvalidRecord;
        if (header.hasDenseId()) {
            const expected_edge_id = std.math.add(u64, index, 1) catch return error.InvalidRecord;
            if (self.edge_id != expected_edge_id) return error.InvalidRecord;
        }
        if (header.hasKeyRunLinearEdgeIds()) {
            const current_run = run orelse return error.InvalidRecord;
            if (index < current_run.start) return error.InvalidRecord;
            const delta = index - current_run.start;
            const scaled_delta = std.math.mul(u64, delta, current_run.edge_id_step) catch return error.InvalidRecord;
            const expected_edge_id = std.math.add(u64, current_run.edge_id_base, scaled_delta) catch return error.InvalidRecord;
            if (self.edge_id != expected_edge_id) return error.InvalidRecord;
        }
        if (header.hasDerivedRel() and self.rel != try header.relForEdgeId(self.edge_id)) return error.InvalidRecord;
        const endpoint_len: usize = edgeIndexStoredEndpointLen(header);
        if (header.hasU32NodeIds()) {
            if (self.src > std.math.maxInt(u32) or self.dst > std.math.maxInt(u32)) return error.InvalidRecord;
            if (header.hasKeyRuns()) {
                const stored = switch (header.order) {
                    .id => stored: {
                        const current_run = run orelse return error.InvalidRecord;
                        if (index < current_run.start) return error.InvalidRecord;
                        const delta = index - current_run.start;
                        const expected_src = std.math.add(u64, current_run.key, delta) catch return error.InvalidRecord;
                        const expected_dst = std.math.add(u64, current_run.opposite, delta) catch return error.InvalidRecord;
                        if (self.src != expected_src or self.dst != expected_dst) return error.InvalidRecord;
                        break :stored self.dst;
                    },
                    .src => self.dst,
                    .dst => self.src,
                };
                if (header.order == .id) {
                    if (!header.hasKeyRunConstantOpposite()) return error.InvalidRecord;
                } else if (header.hasKeyRunConstantOpposite()) {
                    const current_run = run orelse return error.InvalidRecord;
                    if (current_run.opposite != stored) return error.InvalidRecord;
                } else {
                    std.mem.writeInt(u32, out[0..4], @intCast(stored), .little);
                }
            } else {
                std.mem.writeInt(u32, out[0..4], @intCast(self.src), .little);
                std.mem.writeInt(u32, out[4..8], @intCast(self.dst), .little);
            }
        } else {
            if (header.hasKeyRuns()) {
                const stored = switch (header.order) {
                    .id => return error.InvalidRecord,
                    .src => self.dst,
                    .dst => self.src,
                };
                if (header.hasKeyRunConstantOpposite()) {
                    const current_run = run orelse return error.InvalidRecord;
                    if (current_run.opposite != stored) return error.InvalidRecord;
                } else {
                    std.mem.writeInt(u64, out[0..8], stored, .little);
                }
            } else {
                std.mem.writeInt(u64, out[0..8], self.src, .little);
                std.mem.writeInt(u64, out[8..16], self.dst, .little);
            }
        }
        if (!header.hasDenseId() and !header.hasKeyRunLinearEdgeIds()) {
            if (header.hasU32EdgeIds()) {
                if (self.edge_id > std.math.maxInt(u32)) return error.InvalidRecord;
                std.mem.writeInt(u32, out[endpoint_len..][0..4], @intCast(self.edge_id), .little);
            } else {
                std.mem.writeInt(u64, out[endpoint_len..][0..8], self.edge_id, .little);
            }
        }
        if (!header.hasDerivedRel()) {
            const edge_id_len: usize = edgeIndexStoredEdgeIdLen(header);
            const rel_offset = endpoint_len + edge_id_len;
            std.mem.writeInt(u16, out[rel_offset..][0..2], self.rel, .little);
        }
    }

    fn decodeSliceAtForHeader(header: EdgeIndexHeader, index: u64, bytes: []const u8, run: ?EdgeIndexKeyRunRecord) !EdgeIndexRecord {
        try header.validateShape();
        if (bytes.len != header.record_len) return error.InvalidRecord;
        const endpoint_len: usize = edgeIndexStoredEndpointLen(header);
        const edge_id = if (header.hasDenseId()) edge_id: {
            break :edge_id std.math.add(u64, index, 1) catch return error.InvalidRecord;
        } else if (header.hasKeyRunLinearEdgeIds()) edge_id: {
            const current_run = run orelse return error.InvalidRecord;
            if (index < current_run.start) return error.InvalidRecord;
            const scaled_delta = std.math.mul(u64, index - current_run.start, current_run.edge_id_step) catch return error.InvalidRecord;
            break :edge_id std.math.add(u64, current_run.edge_id_base, scaled_delta) catch return error.InvalidRecord;
        } else if (header.hasU32EdgeIds()) edge_id: {
            break :edge_id std.mem.readInt(u32, bytes[endpoint_len..][0..4], .little);
        } else edge_id: {
            break :edge_id std.mem.readInt(u64, bytes[endpoint_len..][0..8], .little);
        };
        if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const rel = if (header.hasDerivedRel()) try header.relForEdgeId(edge_id) else rel: {
            const edge_id_len: usize = edgeIndexStoredEdgeIdLen(header);
            const rel_offset = endpoint_len + edge_id_len;
            break :rel std.mem.readInt(u16, bytes[rel_offset..][0..2], .little);
        };
        if (relKindFromInt(rel) == null) return error.InvalidRecord;
        const src: u64, const dst: u64 = if (header.hasKeyRuns()) endpoints: {
            const current_run = run orelse return error.InvalidRecord;
            const key = current_run.key;
            if (header.order == .id) {
                if (index < current_run.start) return error.InvalidRecord;
                const delta = index - current_run.start;
                break :endpoints .{
                    std.math.add(u64, key, delta) catch return error.InvalidRecord,
                    std.math.add(u64, current_run.opposite, delta) catch return error.InvalidRecord,
                };
            }
            const stored: u64 = if (header.hasKeyRunConstantOpposite())
                current_run.opposite
            else if (header.hasU32NodeIds())
                std.mem.readInt(u32, bytes[0..4], .little)
            else
                std.mem.readInt(u64, bytes[0..8], .little);
            break :endpoints switch (header.order) {
                .id => return error.InvalidRecord,
                .src => .{ key, stored },
                .dst => .{ stored, key },
            };
        } else endpoints: {
            break :endpoints .{
                if (header.hasU32NodeIds())
                    std.mem.readInt(u32, bytes[0..4], .little)
                else
                    std.mem.readInt(u64, bytes[0..8], .little),
                if (header.hasU32NodeIds())
                    std.mem.readInt(u32, bytes[4..8], .little)
                else
                    std.mem.readInt(u64, bytes[8..16], .little),
            };
        };
        if (src == 0 or dst == 0) return error.InvalidRecord;
        if (src == std.math.maxInt(u64) or dst == std.math.maxInt(u64)) return error.InvalidRecord;
        if (header.hasU32NodeIds() and (src > std.math.maxInt(u32) or dst > std.math.maxInt(u32))) return error.InvalidRecord;
        return .{
            .src = src,
            .dst = dst,
            .edge_id = edge_id,
            .rel = rel,
        };
    }

    pub fn relKind(self: EdgeIndexRecord) !core.RelKind {
        return relKindFromInt(self.rel) orelse error.InvalidRecord;
    }
};

pub const EdgeOrderRecord = struct {
    src: u64,
    rel: u16,
    edge_id: u64,
    order_key: u64,

    const encoded_len: usize = 26;

    fn encode(self: EdgeOrderRecord, out: *[encoded_len]u8) void {
        std.mem.writeInt(u64, out[0..8], self.src, .little);
        std.mem.writeInt(u16, out[8..10], self.rel, .little);
        std.mem.writeInt(u64, out[10..18], self.edge_id, .little);
        std.mem.writeInt(u64, out[18..26], self.order_key, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeOrderRecord {
        const record = EdgeOrderRecord{
            .src = std.mem.readInt(u64, bytes[0..8], .little),
            .rel = std.mem.readInt(u16, bytes[8..10], .little),
            .edge_id = std.mem.readInt(u64, bytes[10..18], .little),
            .order_key = std.mem.readInt(u64, bytes[18..26], .little),
        };
        if (record.src == 0 or record.src == std.math.maxInt(u64)) return error.InvalidRecord;
        if (record.edge_id == 0 or record.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        if (relKindFromInt(record.rel) == null) return error.InvalidRecord;
        return record;
    }
};

pub const EdgeOrderRecordVisitor = *const fn (context: *anyopaque, record: EdgeOrderRecord) anyerror!void;

const EdgeOrderHeader = struct {
    count: u64 = 0,
    digest: u64 = 0,

    const encoded_len: usize = 16;

    fn encode(self: EdgeOrderHeader, out: *[encoded_len]u8) void {
        std.mem.writeInt(u64, out[0..8], self.count, .little);
        std.mem.writeInt(u64, out[8..16], self.digest, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) EdgeOrderHeader {
        return .{
            .count = std.mem.readInt(u64, bytes[0..8], .little),
            .digest = std.mem.readInt(u64, bytes[8..16], .little),
        };
    }
};

pub const edge_order_header_bytes: u64 = EdgeOrderHeader.encoded_len;

const EdgeIndexKeyRunRecord = struct {
    key: u64,
    start: u64,
    opposite: u64 = 0,
    edge_id_base: u64 = 0,
    edge_id_step: u64 = 0,

    fn encodeForHeader(self: EdgeIndexKeyRunRecord, header: EdgeIndexHeader, out: []u8) !void {
        try header.validateShape();
        if (!header.hasKeyRuns()) return error.InvalidRecord;
        if (out.len != edgeIndexKeyRunRecordLen(header)) return error.InvalidRecord;
        if (self.key == 0 or self.key == std.math.maxInt(u64)) return error.InvalidRecord;
        if (self.start >= header.edge_count) return error.InvalidRecord;
        if (header.hasKeyRunConstantOpposite()) {
            if (self.opposite == 0 or self.opposite == std.math.maxInt(u64)) return error.InvalidRecord;
            if (header.hasKeyRunRingOpposite() and self.opposite != (try edgeIndexRingOppositeForKey(header, self.key))) return error.InvalidRecord;
        } else if (self.opposite != 0) {
            return error.InvalidRecord;
        }
        if (header.hasU32NodeIds()) {
            if (self.key > std.math.maxInt(u32) or self.start > std.math.maxInt(u32) or self.opposite > std.math.maxInt(u32)) return error.InvalidRecord;
            std.mem.writeInt(u32, out[0..4], @intCast(self.key), .little);
            std.mem.writeInt(u32, out[4..8], @intCast(self.start), .little);
            var cursor: usize = 8;
            if (header.hasKeyRunConstantOpposite() and !header.hasKeyRunRingOpposite()) {
                std.mem.writeInt(u32, out[cursor..][0..4], @intCast(self.opposite), .little);
                cursor += 4;
            }
            if (header.hasKeyRunLinearEdgeIds()) {
                if (header.hasU32EdgeIds() and (self.edge_id_base > std.math.maxInt(u32) or self.edge_id_step > std.math.maxInt(u32))) return error.InvalidRecord;
                if (header.hasKeyRunUniformEdgeIdStep() and self.edge_id_step != 0 and self.edge_id_step != header.key_run_edge_id_step) return error.InvalidRecord;
                if (header.hasU32EdgeIds()) {
                    std.mem.writeInt(u32, out[cursor..][0..4], @intCast(self.edge_id_base), .little);
                    cursor += 4;
                } else {
                    std.mem.writeInt(u64, out[cursor..][0..8], self.edge_id_base, .little);
                    cursor += 8;
                }
                if (!header.hasKeyRunUniformEdgeIdStep()) {
                    if (header.hasU32EdgeIds()) {
                        std.mem.writeInt(u32, out[cursor..][0..4], @intCast(self.edge_id_step), .little);
                    } else {
                        std.mem.writeInt(u64, out[cursor..][0..8], self.edge_id_step, .little);
                    }
                }
            } else if (self.edge_id_base != 0 or self.edge_id_step != 0) {
                return error.InvalidRecord;
            }
        } else {
            std.mem.writeInt(u64, out[0..8], self.key, .little);
            std.mem.writeInt(u64, out[8..16], self.start, .little);
            var cursor: usize = 16;
            if (header.hasKeyRunConstantOpposite() and !header.hasKeyRunRingOpposite()) {
                std.mem.writeInt(u64, out[cursor..][0..8], self.opposite, .little);
                cursor += 8;
            }
            if (header.hasKeyRunLinearEdgeIds()) {
                if (header.hasU32EdgeIds() and (self.edge_id_base > std.math.maxInt(u32) or self.edge_id_step > std.math.maxInt(u32))) return error.InvalidRecord;
                if (header.hasKeyRunUniformEdgeIdStep() and self.edge_id_step != 0 and self.edge_id_step != header.key_run_edge_id_step) return error.InvalidRecord;
                if (header.hasU32EdgeIds()) {
                    std.mem.writeInt(u32, out[cursor..][0..4], @intCast(self.edge_id_base), .little);
                    cursor += 4;
                } else {
                    std.mem.writeInt(u64, out[cursor..][0..8], self.edge_id_base, .little);
                    cursor += 8;
                }
                if (!header.hasKeyRunUniformEdgeIdStep()) {
                    if (header.hasU32EdgeIds()) {
                        std.mem.writeInt(u32, out[cursor..][0..4], @intCast(self.edge_id_step), .little);
                    } else {
                        std.mem.writeInt(u64, out[cursor..][0..8], self.edge_id_step, .little);
                    }
                }
            } else if (self.edge_id_base != 0 or self.edge_id_step != 0) {
                return error.InvalidRecord;
            }
        }
    }

    fn decodeSliceForHeader(header: EdgeIndexHeader, bytes: []const u8) !EdgeIndexKeyRunRecord {
        try header.validateShape();
        if (!header.hasKeyRuns()) return error.InvalidRecord;
        if (bytes.len != edgeIndexKeyRunRecordLen(header)) return error.InvalidRecord;
        const key: u64, const start: u64 = .{
            if (header.hasU32NodeIds())
                std.mem.readInt(u32, bytes[0..4], .little)
            else
                std.mem.readInt(u64, bytes[0..8], .little),
            if (header.hasU32NodeIds())
                std.mem.readInt(u32, bytes[4..8], .little)
            else
                std.mem.readInt(u64, bytes[8..16], .little),
        };
        if (key == 0 or key == std.math.maxInt(u64)) return error.InvalidRecord;
        if (start >= header.edge_count) return error.InvalidRecord;
        var cursor: usize = if (header.hasU32NodeIds()) 8 else 16;
        const opposite: u64 = if (header.hasKeyRunConstantOpposite()) opposite: {
            if (header.hasKeyRunRingOpposite()) break :opposite try edgeIndexRingOppositeForKey(header, key);
            const value = if (header.hasU32NodeIds())
                std.mem.readInt(u32, bytes[cursor..][0..4], .little)
            else
                std.mem.readInt(u64, bytes[cursor..][0..8], .little);
            cursor += if (header.hasU32NodeIds()) 4 else 8;
            break :opposite value;
        } else 0;
        const edge_id_base: u64 = if (header.hasKeyRunLinearEdgeIds()) edge_id_base: {
            const value = if (header.hasU32EdgeIds())
                std.mem.readInt(u32, bytes[cursor..][0..4], .little)
            else
                std.mem.readInt(u64, bytes[cursor..][0..8], .little);
            cursor += if (header.hasU32EdgeIds()) 4 else 8;
            break :edge_id_base value;
        } else 0;
        const edge_id_step: u64 = if (header.hasKeyRunLinearEdgeIds()) edge_id_step: {
            if (header.hasKeyRunUniformEdgeIdStep()) break :edge_id_step header.key_run_edge_id_step;
            break :edge_id_step if (header.hasU32EdgeIds())
                std.mem.readInt(u32, bytes[cursor..][0..4], .little)
            else
                std.mem.readInt(u64, bytes[cursor..][0..8], .little);
        } else 0;
        if (header.hasKeyRunConstantOpposite() and (opposite == 0 or opposite == std.math.maxInt(u64))) return error.InvalidRecord;
        if (header.hasKeyRunLinearEdgeIds() and (edge_id_base == 0 or edge_id_base == std.math.maxInt(u64) or edge_id_step == std.math.maxInt(u64))) return error.InvalidRecord;
        return .{ .key = key, .start = start, .opposite = opposite, .edge_id_base = edge_id_base, .edge_id_step = edge_id_step };
    }
};

const EdgeTombstoneHeader = struct {
    count: u64,
    digest: u64 = 0,

    const magic = [_]u8{ 'T', 'K', 'G', 'T' };
    const version: u16 = 2;
    const encoded_len: usize = 24;

    fn encode(self: EdgeTombstoneHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.count, .little);
        std.mem.writeInt(u64, out[16..24], self.digest, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeTombstoneHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        return .{
            .count = std.mem.readInt(u64, bytes[8..16], .little),
            .digest = std.mem.readInt(u64, bytes[16..24], .little),
        };
    }
};

const EdgeTombstoneRecord = struct {
    edge_id: u64,
    edge_digest: u64,

    const encoded_len: usize = 8;

    fn encode(self: EdgeTombstoneRecord, out: *[encoded_len]u8) void {
        std.mem.writeInt(u64, out[0..8], self.edge_id, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeTombstoneRecord {
        return decodeSlice(bytes);
    }

    fn decodeSlice(bytes: []const u8) !EdgeTombstoneRecord {
        if (bytes.len != encoded_len) return error.InvalidRecord;
        const edge_id = std.mem.readInt(u64, bytes[0..8], .little);
        if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .edge_id = edge_id,
            .edge_digest = 0,
        };
    }
};

pub const NodeByIdHeader = struct {
    max_node_id: u64,
    node_count: u64,
    node_digest: u64 = 0,
    flags: u16 = 0,
    record_len: u16 = NodeByIdRecord.encoded_len,
    uniform_kind: u16 = 0,

    const magic = [_]u8{ 'T', 'K', 'G', 'N' };
    const version: u16 = 7;
    const encoded_len: usize = 40;
    const flag_uniform_kind: u16 = 1 << 0;
    const flag_short_text_len: u16 = 1 << 1;
    const flag_derived_text_offset: u16 = 1 << 2;

    fn encode(self: NodeByIdHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.max_node_id, .little);
        std.mem.writeInt(u64, out[16..24], self.node_count, .little);
        std.mem.writeInt(u64, out[24..32], self.node_digest, .little);
        std.mem.writeInt(u16, out[32..34], self.flags, .little);
        std.mem.writeInt(u16, out[34..36], self.record_len, .little);
        std.mem.writeInt(u16, out[36..38], self.uniform_kind, .little);
        std.mem.writeInt(u16, out[38..40], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodeByIdHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[38..40], .little) != 0) return error.InvalidRecord;
        const flags = std.mem.readInt(u16, bytes[32..34], .little);
        const record_len = std.mem.readInt(u16, bytes[34..36], .little);
        const uniform_kind = std.mem.readInt(u16, bytes[36..38], .little);
        const header = NodeByIdHeader{
            .max_node_id = std.mem.readInt(u64, bytes[8..16], .little),
            .node_count = std.mem.readInt(u64, bytes[16..24], .little),
            .node_digest = std.mem.readInt(u64, bytes[24..32], .little),
            .flags = flags,
            .record_len = record_len,
            .uniform_kind = uniform_kind,
        };
        try header.validateShape();
        return header;
    }

    fn validateShape(self: NodeByIdHeader) !void {
        const known_flags = flag_uniform_kind | flag_short_text_len | flag_derived_text_offset;
        if ((self.flags & ~known_flags) != 0) return error.InvalidRecord;
        if (self.hasShortTextLen() and !self.hasUniformKind()) return error.InvalidRecord;
        if (self.hasDerivedTextOffset() and (!self.hasUniformKind() or !self.hasShortTextLen())) return error.InvalidRecord;
        if (self.hasDerivedTextOffset() and self.node_count != self.max_node_id) return error.InvalidRecord;
        if (self.hasUniformKind()) {
            if (nodeKindFromInt(self.uniform_kind) == null) return error.InvalidRecord;
        } else {
            if (self.uniform_kind != 0) return error.InvalidRecord;
        }
        if (self.record_len != self.expectedRecordLen()) return error.InvalidRecord;
        if (self.node_count > self.max_node_id) return error.InvalidRecord;
    }

    fn hasUniformKind(self: NodeByIdHeader) bool {
        return (self.flags & flag_uniform_kind) != 0;
    }

    fn hasShortTextLen(self: NodeByIdHeader) bool {
        return (self.flags & flag_short_text_len) != 0;
    }

    fn hasDerivedTextOffset(self: NodeByIdHeader) bool {
        return (self.flags & flag_derived_text_offset) != 0;
    }

    fn expectedRecordLen(self: NodeByIdHeader) u16 {
        var len: u16 = NodeByIdRecord.encoded_len;
        if (self.hasUniformKind()) len -= 2;
        if (self.hasShortTextLen()) len -= 2;
        if (self.hasDerivedTextOffset()) len -= 6;
        return len;
    }

    fn uniform(kind: core.NodeKind, short_text_len: bool) NodeByIdHeader {
        var header = NodeByIdHeader{
            .max_node_id = 0,
            .node_count = 0,
            .flags = flag_uniform_kind,
            .uniform_kind = @intFromEnum(kind),
        };
        if (short_text_len) header.flags |= flag_short_text_len;
        header.record_len = header.expectedRecordLen();
        return header;
    }
};

pub const NodeByIdRecord = struct {
    id: u64,
    kind: u16,
    text_offset: u64,
    text_len: u32,

    const encoded_len: usize = 12;
    const uniform_encoded_len: usize = 10;
    const uniform_short_text_len_encoded_len: usize = 8;
    const uniform_short_derived_offset_encoded_len: usize = 2;

    fn empty() NodeByIdRecord {
        return .{ .id = 0, .kind = 0, .text_offset = 0, .text_len = 0 };
    }

    fn encode(self: NodeByIdRecord, out: *[encoded_len]u8) !void {
        if (self.id == 0) {
            std.mem.writeInt(u16, out[0..2], 0, .little);
            @memset(out[2..12], 0);
            return;
        }
        std.debug.assert(nodeKindFromInt(self.kind) != null);
        const stored_kind = std.math.add(u16, self.kind, 1) catch std.math.maxInt(u16);
        std.mem.writeInt(u16, out[0..2], stored_kind, .little);
        std.mem.writeInt(u32, out[2..6], self.text_len, .little);
        try writeU48(out[6..12], self.text_offset);
    }

    fn decodeAt(node_id: u64, bytes: *const [encoded_len]u8) !NodeByIdRecord {
        return decodeSliceAt(node_id, bytes);
    }

    fn decodeSliceAt(node_id: u64, bytes: []const u8) !NodeByIdRecord {
        if (bytes.len != encoded_len) return error.InvalidRecord;
        if (node_id == 0 or node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const stored_kind = std.mem.readInt(u16, bytes[0..2], .little);
        const text_len = std.mem.readInt(u32, bytes[2..6], .little);
        const text_offset = readU48(bytes[6..12]);
        if (stored_kind == 0) {
            if (text_offset != 0 or text_len != 0) return error.InvalidRecord;
            return empty();
        }
        const kind = stored_kind - 1;
        if (nodeKindFromInt(kind) == null) return error.InvalidRecord;
        return .{
            .id = node_id,
            .kind = kind,
            .text_offset = text_offset,
            .text_len = text_len,
        };
    }

    fn encodeForHeader(self: NodeByIdRecord, header: NodeByIdHeader, out: []u8) !void {
        try header.validateShape();
        if (out.len != header.record_len) return error.InvalidRecord;
        if (!header.hasUniformKind()) {
            var full: [encoded_len]u8 = undefined;
            try self.encode(&full);
            @memcpy(out, &full);
            return;
        }
        if (header.hasDerivedTextOffset()) {
            if (self.id == 0) return error.InvalidRecord;
            if (self.kind != header.uniform_kind) return error.InvalidRecord;
            const short_len = std.math.cast(u16, self.text_len) orelse return error.RecordTooLarge;
            std.mem.writeInt(u16, out[0..2], short_len, .little);
            return;
        }
        if (self.id == 0) {
            if (header.hasShortTextLen()) {
                std.mem.writeInt(u16, out[0..2], 0, .little);
                @memset(out[2..8], 0);
            } else {
                std.mem.writeInt(u32, out[0..4], 0, .little);
                @memset(out[4..10], 0);
            }
            return;
        }
        if (self.kind != header.uniform_kind) return error.InvalidRecord;
        if (header.hasShortTextLen()) {
            const short_len = std.math.cast(u16, self.text_len) orelse return error.RecordTooLarge;
            std.mem.writeInt(u16, out[0..2], short_len, .little);
            try writeU48(out[2..8], self.text_offset);
        } else {
            std.mem.writeInt(u32, out[0..4], self.text_len, .little);
            try writeU48(out[4..10], self.text_offset);
        }
    }

    fn decodeSliceAtForHeader(header: NodeByIdHeader, node_id: u64, bytes: []const u8) !NodeByIdRecord {
        try header.validateShape();
        if (bytes.len != header.record_len) return error.InvalidRecord;
        if (!header.hasUniformKind()) return decodeSliceAt(node_id, bytes);
        if (node_id == 0 or node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        if (header.hasDerivedTextOffset()) return error.InvalidRecord;
        const text_len: u32 = if (header.hasShortTextLen())
            std.mem.readInt(u16, bytes[0..2], .little)
        else
            std.mem.readInt(u32, bytes[0..4], .little);
        const text_offset = if (header.hasShortTextLen()) readU48(bytes[2..8]) else readU48(bytes[4..10]);
        if (text_len == 0) {
            if (text_offset != 0) return error.InvalidRecord;
            return empty();
        }
        return .{
            .id = node_id,
            .kind = header.uniform_kind,
            .text_offset = text_offset,
            .text_len = text_len,
        };
    }

    pub fn nodeKind(self: NodeByIdRecord) !core.NodeKind {
        return nodeKindFromInt(self.kind) orelse error.InvalidRecord;
    }
};

pub const NodeTextIndexHeader = struct {
    node_count: u64,
    node_digest: u64 = 0,
    order_digest: u64 = 0,
    flags: u16 = 0,
    record_len: u16 = NodeTextIndexRecord.encoded_len,
    uniform_kind: u16 = 0,

    const magic = [_]u8{ 'T', 'K', 'G', 'M' };
    const version: u16 = 9;
    const encoded_len: usize = 40;
    const flag_uniform_kind: u16 = 1 << 0;
    const flag_short_text_len: u16 = 1 << 1;
    const flag_u32_id: u16 = 1 << 2;
    const flag_derived_hash: u16 = 1 << 3;
    const flag_derived_text_span: u16 = 1 << 4;
    const flag_text_hash_unique: u16 = 1 << 5;

    fn encode(self: NodeTextIndexHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.node_count, .little);
        std.mem.writeInt(u64, out[16..24], self.node_digest, .little);
        std.mem.writeInt(u64, out[24..32], self.order_digest, .little);
        std.mem.writeInt(u16, out[32..34], self.flags, .little);
        std.mem.writeInt(u16, out[34..36], self.record_len, .little);
        std.mem.writeInt(u16, out[36..38], self.uniform_kind, .little);
        std.mem.writeInt(u16, out[38..40], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodeTextIndexHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[38..40], .little) != 0) return error.InvalidRecord;
        const header = NodeTextIndexHeader{
            .node_count = std.mem.readInt(u64, bytes[8..16], .little),
            .node_digest = std.mem.readInt(u64, bytes[16..24], .little),
            .order_digest = std.mem.readInt(u64, bytes[24..32], .little),
            .flags = std.mem.readInt(u16, bytes[32..34], .little),
            .record_len = std.mem.readInt(u16, bytes[34..36], .little),
            .uniform_kind = std.mem.readInt(u16, bytes[36..38], .little),
        };
        try header.validateShape();
        return header;
    }

    fn validateShape(self: NodeTextIndexHeader) !void {
        const known_flags = flag_uniform_kind | flag_short_text_len | flag_u32_id | flag_derived_hash | flag_derived_text_span | flag_text_hash_unique;
        if ((self.flags & ~known_flags) != 0) return error.InvalidRecord;
        if (self.hasDerivedTextSpan() and self.hasShortTextLen()) return error.InvalidRecord;
        if (self.hasUniformKind()) {
            if (nodeKindFromInt(self.uniform_kind) == null) return error.InvalidRecord;
        } else {
            if (self.uniform_kind != 0) return error.InvalidRecord;
        }
        if (self.record_len != self.expectedRecordLen()) return error.InvalidRecord;
    }

    fn hasUniformKind(self: NodeTextIndexHeader) bool {
        return (self.flags & flag_uniform_kind) != 0;
    }

    fn hasShortTextLen(self: NodeTextIndexHeader) bool {
        return (self.flags & flag_short_text_len) != 0;
    }

    fn hasU32Id(self: NodeTextIndexHeader) bool {
        return (self.flags & flag_u32_id) != 0;
    }

    fn hasDerivedHash(self: NodeTextIndexHeader) bool {
        return (self.flags & flag_derived_hash) != 0;
    }

    fn hasDerivedTextSpan(self: NodeTextIndexHeader) bool {
        return (self.flags & flag_derived_text_span) != 0;
    }

    fn hasTextHashUnique(self: NodeTextIndexHeader) bool {
        return (self.flags & flag_text_hash_unique) != 0;
    }

    fn setTextHashUnique(self: *NodeTextIndexHeader, enabled: bool) void {
        if (enabled) {
            self.flags |= flag_text_hash_unique;
        } else {
            self.flags &= ~flag_text_hash_unique;
        }
    }

    fn expectedRecordLen(self: NodeTextIndexHeader) u16 {
        var len: u16 = NodeTextIndexRecord.encoded_len;
        if (self.hasDerivedHash()) len -= 8;
        if (self.hasU32Id()) len -= 4;
        if (self.hasUniformKind()) len -= 2;
        if (self.hasDerivedTextSpan()) {
            len -= 10;
        } else if (self.hasShortTextLen()) {
            len -= 2;
        }
        return len;
    }

    fn withShape(node_count: u64, node_digest: u64, order_digest: u64, uniform_kind: ?u16, short_text_len: bool, u32_id: bool, derived_hash: bool, derived_text_span: bool) NodeTextIndexHeader {
        var header = NodeTextIndexHeader{
            .node_count = node_count,
            .node_digest = node_digest,
            .order_digest = order_digest,
        };
        if (uniform_kind) |kind| {
            header.flags |= flag_uniform_kind;
            header.uniform_kind = kind;
        }
        if (short_text_len and !derived_text_span) header.flags |= flag_short_text_len;
        if (u32_id) header.flags |= flag_u32_id;
        if (derived_hash) header.flags |= flag_derived_hash;
        if (derived_text_span) header.flags |= flag_derived_text_span;
        header.record_len = header.expectedRecordLen();
        return header;
    }
};

pub const NodeTextIndexRecord = struct {
    hash: u64,
    id: u64,
    kind: u16,
    text_offset: u64,
    text_len: u32,

    const encoded_len: usize = 28;

    fn encode(self: NodeTextIndexRecord, out: *[encoded_len]u8) !void {
        std.mem.writeInt(u64, out[0..8], self.hash, .little);
        std.mem.writeInt(u64, out[8..16], self.id, .little);
        std.mem.writeInt(u16, out[16..18], self.kind, .little);
        std.mem.writeInt(u32, out[18..22], self.text_len, .little);
        try writeU48(out[22..28], self.text_offset);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodeTextIndexRecord {
        return decodeSlice(bytes);
    }

    fn decodeSlice(bytes: []const u8) !NodeTextIndexRecord {
        if (bytes.len != encoded_len) return error.InvalidRecord;
        const id = std.mem.readInt(u64, bytes[8..16], .little);
        const kind = std.mem.readInt(u16, bytes[16..18], .little);
        if (nodeKindFromInt(kind) == null) return error.InvalidRecord;
        const text_len = std.mem.readInt(u32, bytes[18..22], .little);
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .hash = std.mem.readInt(u64, bytes[0..8], .little),
            .id = id,
            .kind = kind,
            .text_offset = readU48(bytes[22..28]),
            .text_len = text_len,
        };
    }

    fn encodeForHeader(self: NodeTextIndexRecord, header: NodeTextIndexHeader, out: []u8) !void {
        try header.validateShape();
        if (out.len != header.record_len) return error.InvalidRecord;
        var cursor: usize = 0;
        if (!header.hasDerivedHash()) {
            std.mem.writeInt(u64, out[cursor..][0..8], self.hash, .little);
            cursor += 8;
        }
        if (header.hasU32Id()) {
            const short_id = std.math.cast(u32, self.id) orelse return error.RecordTooLarge;
            writeU32(out[cursor .. cursor + 4], short_id);
            cursor += 4;
        } else {
            std.mem.writeInt(u64, out[cursor..][0..8], self.id, .little);
            cursor += 8;
        }
        if (header.hasUniformKind()) {
            if (self.kind != header.uniform_kind) return error.InvalidRecord;
        } else {
            writeU16(out[cursor .. cursor + 2], self.kind);
            cursor += 2;
        }
        if (!header.hasDerivedTextSpan()) {
            if (header.hasShortTextLen()) {
                const short_len = std.math.cast(u16, self.text_len) orelse return error.RecordTooLarge;
                writeU16(out[cursor .. cursor + 2], short_len);
                cursor += 2;
            } else {
                writeU32(out[cursor .. cursor + 4], self.text_len);
                cursor += 4;
            }
            try writeU48(out[cursor .. cursor + 6], self.text_offset);
        }
    }

    fn decodeSliceForHeader(header: NodeTextIndexHeader, bytes: []const u8) !NodeTextIndexRecord {
        try header.validateShape();
        if (bytes.len != header.record_len) return error.InvalidRecord;
        var cursor: usize = 0;
        const hash = if (header.hasDerivedHash()) 0 else hash: {
            const decoded = readU64(bytes[cursor .. cursor + 8]);
            cursor += 8;
            break :hash decoded;
        };
        const id: u64 = if (header.hasU32Id()) id: {
            const decoded = readU32(bytes[cursor .. cursor + 4]);
            cursor += 4;
            break :id decoded;
        } else id: {
            const decoded = readU64(bytes[cursor .. cursor + 8]);
            cursor += 8;
            break :id decoded;
        };
        const kind = if (header.hasUniformKind()) header.uniform_kind else kind: {
            const decoded = readU16(bytes[cursor .. cursor + 2]);
            cursor += 2;
            break :kind decoded;
        };
        if (nodeKindFromInt(kind) == null) return error.InvalidRecord;
        const text_len: u32 = if (header.hasDerivedTextSpan()) 0 else if (header.hasShortTextLen()) len: {
            const decoded = readU16(bytes[cursor .. cursor + 2]);
            cursor += 2;
            break :len decoded;
        } else len: {
            const decoded = readU32(bytes[cursor .. cursor + 4]);
            cursor += 4;
            break :len decoded;
        };
        const text_offset = if (header.hasDerivedTextSpan()) 0 else readU48(bytes[cursor .. cursor + 6]);
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .hash = hash,
            .id = id,
            .kind = kind,
            .text_offset = text_offset,
            .text_len = text_len,
        };
    }

    pub fn nodeKind(self: NodeTextIndexRecord) !core.NodeKind {
        return nodeKindFromInt(self.kind) orelse error.InvalidRecord;
    }
};

const ExternalKeyIndexHeader = struct {
    record_count: u64,
    node_count: u64,
    node_digest: u64,

    const magic = [_]u8{ 'T', 'K', 'E', 'K' };
    const version: u16 = 2;
    const encoded_len: usize = 40;

    fn encode(self: ExternalKeyIndexHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.record_count, .little);
        std.mem.writeInt(u64, out[16..24], self.node_count, .little);
        std.mem.writeInt(u64, out[24..32], self.node_digest, .little);
        std.mem.writeInt(u64, out[32..40], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !ExternalKeyIndexHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u64, bytes[32..40], .little) != 0) return error.InvalidRecord;
        return .{
            .record_count = std.mem.readInt(u64, bytes[8..16], .little),
            .node_count = std.mem.readInt(u64, bytes[16..24], .little),
            .node_digest = std.mem.readInt(u64, bytes[24..32], .little),
        };
    }
};

const ExternalKeyIndexRecord = struct {
    hash: u64,
    node_id: u64,

    const encoded_len: usize = 16;

    fn encode(self: ExternalKeyIndexRecord, out: *[encoded_len]u8) !void {
        if (self.node_id == 0 or self.node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        std.mem.writeInt(u64, out[0..8], self.hash, .little);
        std.mem.writeInt(u64, out[8..16], self.node_id, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !ExternalKeyIndexRecord {
        const node_id = std.mem.readInt(u64, bytes[8..16], .little);
        if (node_id == 0 or node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .hash = std.mem.readInt(u64, bytes[0..8], .little),
            .node_id = node_id,
        };
    }
};

fn externalKeyIndexRecordLessThan(_: void, a: ExternalKeyIndexRecord, b: ExternalKeyIndexRecord) bool {
    if (a.hash != b.hash) return a.hash < b.hash;
    return a.node_id < b.node_id;
}

fn externalKeyHash(external_key: []const u8) u64 {
    return std.hash.Wyhash.hash(0x544B_4558, external_key);
}

fn externalKeyIndexFileSize(record_count: u64) !u64 {
    const records_bytes = std.math.mul(u64, record_count, ExternalKeyIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, ExternalKeyIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn externalKeyIndexRecordOffset(index: u64) !u64 {
    const records_bytes = std.math.mul(u64, index, ExternalKeyIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, ExternalKeyIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

const NodePropertyIndexHeader = struct {
    record_count: u64,
    node_count: u64,
    node_digest: u64,

    const magic = [_]u8{ 'T', 'K', 'P', 'R' };
    const version: u16 = 1;
    const encoded_len: usize = 40;

    fn encode(self: NodePropertyIndexHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.record_count, .little);
        std.mem.writeInt(u64, out[16..24], self.node_count, .little);
        std.mem.writeInt(u64, out[24..32], self.node_digest, .little);
        std.mem.writeInt(u64, out[32..40], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodePropertyIndexHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u64, bytes[32..40], .little) != 0) return error.InvalidRecord;
        return .{
            .record_count = std.mem.readInt(u64, bytes[8..16], .little),
            .node_count = std.mem.readInt(u64, bytes[16..24], .little),
            .node_digest = std.mem.readInt(u64, bytes[24..32], .little),
        };
    }
};

const NodePropertyIndexRecord = struct {
    key_hash: u64,
    value_hash: u64,
    node_id: u64,
    value_type: u8,

    const value_type_string: u8 = 1;
    const value_type_uint: u8 = 2;
    const encoded_len: usize = 32;

    fn encode(self: NodePropertyIndexRecord, out: *[encoded_len]u8) !void {
        if (self.node_id == 0 or self.node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        if (self.value_type != value_type_string and self.value_type != value_type_uint) return error.InvalidRecord;
        std.mem.writeInt(u64, out[0..8], self.key_hash, .little);
        std.mem.writeInt(u64, out[8..16], self.value_hash, .little);
        std.mem.writeInt(u64, out[16..24], self.node_id, .little);
        out[24] = self.value_type;
        @memset(out[25..32], 0);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodePropertyIndexRecord {
        const node_id = std.mem.readInt(u64, bytes[16..24], .little);
        if (node_id == 0 or node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const value_type = bytes[24];
        if (value_type != value_type_string and value_type != value_type_uint) return error.InvalidRecord;
        for (bytes[25..32]) |byte| {
            if (byte != 0) return error.InvalidRecord;
        }
        return .{
            .key_hash = std.mem.readInt(u64, bytes[0..8], .little),
            .value_hash = std.mem.readInt(u64, bytes[8..16], .little),
            .node_id = node_id,
            .value_type = value_type,
        };
    }
};

const NodePropertyIndexEntry = struct {
    record: NodePropertyIndexRecord,
    value: ?[]u8 = null,

    fn deinit(self: *NodePropertyIndexEntry, allocator: std.mem.Allocator) void {
        if (self.value) |value| allocator.free(value);
        self.value = null;
    }
};

fn deinitNodePropertyIndexEntries(entries: []NodePropertyIndexEntry, allocator: std.mem.Allocator) void {
    for (entries) |*entry| entry.deinit(allocator);
}

const PropertyPayloadIndexHeader = struct {
    record_count: u64,
    owner_count: u64,
    owner_digest: u64,

    const magic = [_]u8{ 'T', 'K', 'P', 'X' };
    const version: u16 = 1;
    const encoded_len: usize = 40;

    fn encode(self: PropertyPayloadIndexHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.record_count, .little);
        std.mem.writeInt(u64, out[16..24], self.owner_count, .little);
        std.mem.writeInt(u64, out[24..32], self.owner_digest, .little);
        std.mem.writeInt(u64, out[32..40], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !PropertyPayloadIndexHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u64, bytes[32..40], .little) != 0) return error.InvalidRecord;
        return .{
            .record_count = std.mem.readInt(u64, bytes[8..16], .little),
            .owner_count = std.mem.readInt(u64, bytes[16..24], .little),
            .owner_digest = std.mem.readInt(u64, bytes[24..32], .little),
        };
    }
};

const PropertyPayloadRedoJournalHeader = struct {
    index_len: u64,
    values_len: u64,
    index_digest: u64,
    values_digest: u64,

    const magic = [_]u8{ 'T', 'K', 'P', 'J' };
    const version: u16 = 1;
    const encoded_len: usize = 48;

    fn encode(self: PropertyPayloadRedoJournalHeader, out: *[encoded_len]u8) void {
        @memset(out, 0);
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.index_len, .little);
        std.mem.writeInt(u64, out[16..24], self.values_len, .little);
        std.mem.writeInt(u64, out[24..32], self.index_digest, .little);
        std.mem.writeInt(u64, out[32..40], self.values_digest, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !PropertyPayloadRedoJournalHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (!std.mem.allEqual(u8, bytes[40..48], 0)) return error.InvalidRecord;
        const header = PropertyPayloadRedoJournalHeader{
            .index_len = std.mem.readInt(u64, bytes[8..16], .little),
            .values_len = std.mem.readInt(u64, bytes[16..24], .little),
            .index_digest = std.mem.readInt(u64, bytes[24..32], .little),
            .values_digest = std.mem.readInt(u64, bytes[32..40], .little),
        };
        if (header.index_len < PropertyPayloadIndexHeader.encoded_len or
            header.values_len < NodePropertyValueBlockHeader.encoded_len)
        {
            return error.InvalidRecord;
        }
        return header;
    }
};

const PropertyPayloadIndexRecord = struct {
    key_hash: u64,
    value_hash: u64,
    owner_id: u64,
    owner_kind: u8,
    value_type: u8,

    const owner_kind_node: u8 = 1;
    const owner_kind_edge: u8 = 2;
    const value_type_string: u8 = 1;
    const value_type_uint: u8 = 2;
    const encoded_len: usize = 32;

    fn encode(self: PropertyPayloadIndexRecord, out: *[encoded_len]u8) !void {
        if (self.owner_id == 0 or self.owner_id == std.math.maxInt(u64)) return error.InvalidRecord;
        if (self.owner_kind != owner_kind_node and self.owner_kind != owner_kind_edge) return error.InvalidRecord;
        if (self.value_type != value_type_string and self.value_type != value_type_uint) return error.InvalidRecord;
        std.mem.writeInt(u64, out[0..8], self.key_hash, .little);
        std.mem.writeInt(u64, out[8..16], self.value_hash, .little);
        std.mem.writeInt(u64, out[16..24], self.owner_id, .little);
        out[24] = self.owner_kind;
        out[25] = self.value_type;
        @memset(out[26..32], 0);
    }

    fn decode(bytes: *const [encoded_len]u8) !PropertyPayloadIndexRecord {
        const owner_id = std.mem.readInt(u64, bytes[16..24], .little);
        if (owner_id == 0 or owner_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const owner_kind = bytes[24];
        if (owner_kind != owner_kind_node and owner_kind != owner_kind_edge) return error.InvalidRecord;
        const value_type = bytes[25];
        if (value_type != value_type_string and value_type != value_type_uint) return error.InvalidRecord;
        for (bytes[26..32]) |byte| {
            if (byte != 0) return error.InvalidRecord;
        }
        return .{
            .key_hash = std.mem.readInt(u64, bytes[0..8], .little),
            .value_hash = std.mem.readInt(u64, bytes[8..16], .little),
            .owner_id = owner_id,
            .owner_kind = owner_kind,
            .value_type = value_type,
        };
    }
};

const PropertyPayloadIndexEntry = struct {
    record: PropertyPayloadIndexRecord,
    value: ?[]u8 = null,

    fn deinit(self: *PropertyPayloadIndexEntry, allocator: std.mem.Allocator) void {
        if (self.value) |value| allocator.free(value);
        self.value = null;
    }
};

const property_payload_delta_magic = [_]u8{ 'T', 'K', 'P', 'D' };
const property_payload_delta_version: u16 = 1;
const property_payload_delta_header_len: usize = 32;
const property_payload_delta_entry_len: usize = 40;
const property_payload_delta_digest_seed: u64 = 0x544B_5044;
const property_payload_delta_max_frame_bytes: u32 = 16 * 1024 * 1024;
const property_snapshot_legacy_version: u64 = 0;
const property_snapshot_base_version: u64 = 1 << 62;
const property_snapshot_delta_version_base: u64 = 2 << 62;

const PropertyPayloadDeltaHeader = struct {
    sequence: u64,
    write_count: u32,
    payload_len: u32,
    payload_digest: u64,

    fn encode(self: PropertyPayloadDeltaHeader, out: *[property_payload_delta_header_len]u8) !void {
        if (self.sequence == 0 or self.write_count == 0 or self.payload_len == 0 or self.payload_len > property_payload_delta_max_frame_bytes) return error.InvalidRecord;
        @memcpy(out[0..4], &property_payload_delta_magic);
        writeU16(out[4..6], property_payload_delta_version);
        writeU16(out[6..8], property_payload_delta_header_len);
        writeU64(out[8..16], self.sequence);
        writeU32(out[16..20], self.write_count);
        writeU32(out[20..24], self.payload_len);
        writeU64(out[24..32], self.payload_digest);
    }

    fn decode(bytes: *const [property_payload_delta_header_len]u8) !PropertyPayloadDeltaHeader {
        if (!std.mem.eql(u8, bytes[0..4], &property_payload_delta_magic)) return error.InvalidRecord;
        if (readU16(bytes[4..6]) != property_payload_delta_version or readU16(bytes[6..8]) != property_payload_delta_header_len) return error.InvalidRecord;
        const header = PropertyPayloadDeltaHeader{
            .sequence = readU64(bytes[8..16]),
            .write_count = readU32(bytes[16..20]),
            .payload_len = readU32(bytes[20..24]),
            .payload_digest = readU64(bytes[24..32]),
        };
        if (header.sequence == 0 or header.write_count == 0 or header.payload_len == 0 or header.payload_len > property_payload_delta_max_frame_bytes) return error.InvalidRecord;
        return header;
    }
};

const PropertyPayloadDeltaScan = struct {
    valid_bytes: u64 = 0,
    last_sequence: u64 = 0,
    last_digest: u64 = 0,
    trailing_partial: bool = false,
};

const PropertyPayloadDeltaRecovery = enum {
    no_journal,
    committed,
};

fn deinitPropertyPayloadIndexEntries(entries: []PropertyPayloadIndexEntry, allocator: std.mem.Allocator) void {
    for (entries) |*entry| entry.deinit(allocator);
}

const NodePropertyValueBlockHeader = struct {
    record_count: u64,
    node_count: u64,
    node_digest: u64,
    payload_bytes: u64,
    payload_digest: u64,

    const magic = [_]u8{ 'T', 'K', 'P', 'V' };
    const version: u16 = 1;
    const encoded_len: usize = 56;

    fn encode(self: NodePropertyValueBlockHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.record_count, .little);
        std.mem.writeInt(u64, out[16..24], self.node_count, .little);
        std.mem.writeInt(u64, out[24..32], self.node_digest, .little);
        std.mem.writeInt(u64, out[32..40], self.payload_bytes, .little);
        std.mem.writeInt(u64, out[40..48], self.payload_digest, .little);
        std.mem.writeInt(u64, out[48..56], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodePropertyValueBlockHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u64, bytes[48..56], .little) != 0) return error.InvalidRecord;
        return .{
            .record_count = std.mem.readInt(u64, bytes[8..16], .little),
            .node_count = std.mem.readInt(u64, bytes[16..24], .little),
            .node_digest = std.mem.readInt(u64, bytes[24..32], .little),
            .payload_bytes = std.mem.readInt(u64, bytes[32..40], .little),
            .payload_digest = std.mem.readInt(u64, bytes[40..48], .little),
        };
    }
};

const NodePropertyValueRecord = struct {
    offset: u64,
    len: u32,

    const encoded_len: usize = 16;

    fn encode(self: NodePropertyValueRecord, out: *[encoded_len]u8) void {
        std.mem.writeInt(u64, out[0..8], self.offset, .little);
        std.mem.writeInt(u32, out[8..12], self.len, .little);
        std.mem.writeInt(u32, out[12..16], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !NodePropertyValueRecord {
        if (std.mem.readInt(u32, bytes[12..16], .little) != 0) return error.InvalidRecord;
        return .{
            .offset = std.mem.readInt(u64, bytes[0..8], .little),
            .len = std.mem.readInt(u32, bytes[8..12], .little),
        };
    }
};

const NodePropertyPropsJson = struct {
    name: ?[]const u8 = null,
    status: ?[]const u8 = null,
    claimed_by: ?[]const u8 = null,
    schema_type: ?[]const u8 = null,
    external_key: ?[]const u8 = null,
    content_hash: ?[]const u8 = null,
    summary: ?[]const u8 = null,
    retrieval_hints: ?[]const u8 = null,
    task_event_type: ?[]const u8 = null,
    dependency_relation: ?[]const u8 = null,
    task_recorded_ns: ?u64 = null,
    task_created_ns: ?u64 = null,
    task_completed_ns: ?u64 = null,
    claim_expires_ns: ?u64 = null,
    task_event_ns: ?u64 = null,
    task_root_id: ?u64 = null,
    task_id: ?u64 = null,
};

const EdgeExternalKeyIndexHeader = struct {
    record_count: u64,
    node_count: u64,
    node_digest: u64,
    edge_count: u64,
    edge_digest: u64,

    const magic = [_]u8{ 'T', 'K', 'E', 'K' };
    const version: u16 = 1;
    const encoded_len: usize = 56;

    fn encode(self: EdgeExternalKeyIndexHeader, out: *[encoded_len]u8) void {
        @memcpy(out[0..4], &magic);
        std.mem.writeInt(u16, out[4..6], version, .little);
        std.mem.writeInt(u16, out[6..8], encoded_len, .little);
        std.mem.writeInt(u64, out[8..16], self.record_count, .little);
        std.mem.writeInt(u64, out[16..24], self.node_count, .little);
        std.mem.writeInt(u64, out[24..32], self.node_digest, .little);
        std.mem.writeInt(u64, out[32..40], self.edge_count, .little);
        std.mem.writeInt(u64, out[40..48], self.edge_digest, .little);
        std.mem.writeInt(u64, out[48..56], 0, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeExternalKeyIndexHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[4..6], .little) != version) return error.InvalidRecord;
        if (std.mem.readInt(u16, bytes[6..8], .little) != encoded_len) return error.InvalidRecord;
        if (std.mem.readInt(u64, bytes[48..56], .little) != 0) return error.InvalidRecord;
        return .{
            .record_count = std.mem.readInt(u64, bytes[8..16], .little),
            .node_count = std.mem.readInt(u64, bytes[16..24], .little),
            .node_digest = std.mem.readInt(u64, bytes[24..32], .little),
            .edge_count = std.mem.readInt(u64, bytes[32..40], .little),
            .edge_digest = std.mem.readInt(u64, bytes[40..48], .little),
        };
    }
};

const EdgeExternalKeyIndexRecord = struct {
    hash: u64,
    edge_id: u64,

    const encoded_len: usize = 16;

    fn encode(self: EdgeExternalKeyIndexRecord, out: *[encoded_len]u8) !void {
        if (self.edge_id == 0 or self.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        std.mem.writeInt(u64, out[0..8], self.hash, .little);
        std.mem.writeInt(u64, out[8..16], self.edge_id, .little);
    }

    fn decode(bytes: *const [encoded_len]u8) !EdgeExternalKeyIndexRecord {
        const edge_id = std.mem.readInt(u64, bytes[8..16], .little);
        if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .hash = std.mem.readInt(u64, bytes[0..8], .little),
            .edge_id = edge_id,
        };
    }
};

fn nodePropertyIndexRecordLessThan(_: void, a: NodePropertyIndexRecord, b: NodePropertyIndexRecord) bool {
    if (a.key_hash != b.key_hash) return a.key_hash < b.key_hash;
    if (a.value_type != b.value_type) return a.value_type < b.value_type;
    if (a.value_hash != b.value_hash) return a.value_hash < b.value_hash;
    return a.node_id < b.node_id;
}

fn nodePropertyIndexEntryLessThan(_: void, a: NodePropertyIndexEntry, b: NodePropertyIndexEntry) bool {
    return nodePropertyIndexRecordLessThan({}, a.record, b.record);
}

fn edgeExternalKeyIndexRecordLessThan(_: void, a: EdgeExternalKeyIndexRecord, b: EdgeExternalKeyIndexRecord) bool {
    if (a.hash != b.hash) return a.hash < b.hash;
    return a.edge_id < b.edge_id;
}

fn nodePropertyKeyHash(key: []const u8) u64 {
    return std.hash.Wyhash.hash(0x544B_504B, key);
}

pub fn propertyKeyHashForLookup(key: []const u8) u64 {
    return nodePropertyKeyHash(key);
}

fn nodePropertyValueHash(value: []const u8) u64 {
    return std.hash.Wyhash.hash(0x544B_5056, value);
}

pub fn propertyValueHashForStorage(value: []const u8) u64 {
    return nodePropertyValueHash(value);
}

fn edgeExternalKeyHash(external_key: []const u8) u64 {
    return std.hash.Wyhash.hash(0x544B_454B, external_key);
}

pub fn edgeFactExternalKeyAlloc(allocator: std.mem.Allocator, src_external_key: []const u8, rel: core.RelKind, dst_external_key: []const u8) ![]u8 {
    return try std.fmt.allocPrint(allocator, "edge-fact\x1f{s}\x1f{}\x1f{s}", .{ src_external_key, @intFromEnum(rel), dst_external_key });
}

pub fn orderedEdgeExternalKeyAlloc(allocator: std.mem.Allocator, src_external_key: []const u8, rel: core.RelKind, order_key: u64) ![]u8 {
    return try std.fmt.allocPrint(allocator, "edge-ordered\x1f{s}\x1f{}\x1f{}", .{ src_external_key, @intFromEnum(rel), order_key });
}

fn nodePropertyIndexFileSize(record_count: u64) !u64 {
    const records_bytes = std.math.mul(u64, record_count, NodePropertyIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, NodePropertyIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn nodePropertyIndexRecordOffset(index: u64) !u64 {
    const records_bytes = std.math.mul(u64, index, NodePropertyIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, NodePropertyIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn nodePropertyValueBlockHeaderAndRecordBytes(record_count: u64) !u64 {
    const records_bytes = std.math.mul(u64, record_count, NodePropertyValueRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, NodePropertyValueBlockHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn nodePropertyValueBlockFileSize(record_count: u64, payload_bytes: u64) !u64 {
    const prefix = try nodePropertyValueBlockHeaderAndRecordBytes(record_count);
    return std.math.add(u64, prefix, payload_bytes) catch error.RecordTooLarge;
}

fn nodePropertyValueRecordOffset(index: u64) !u64 {
    const records_bytes = std.math.mul(u64, index, NodePropertyValueRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, NodePropertyValueBlockHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn propertyPayloadIndexFileSize(record_count: u64) !u64 {
    const records_bytes = std.math.mul(u64, record_count, PropertyPayloadIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, PropertyPayloadIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn propertyPayloadIndexRecordOffset(index: u64) !u64 {
    const records_bytes = std.math.mul(u64, index, PropertyPayloadIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, PropertyPayloadIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn edgeExternalKeyIndexFileSize(record_count: u64) !u64 {
    const records_bytes = std.math.mul(u64, record_count, EdgeExternalKeyIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, EdgeExternalKeyIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn edgeExternalKeyIndexRecordOffset(index: u64) !u64 {
    const records_bytes = std.math.mul(u64, index, EdgeExternalKeyIndexRecord.encoded_len) catch return error.RecordTooLarge;
    return std.math.add(u64, EdgeExternalKeyIndexHeader.encoded_len, records_bytes) catch error.RecordTooLarge;
}

fn nodePropertyStringKeySupported(key: []const u8) bool {
    return propertyKeyNameValid(key) and !std.mem.eql(u8, key, "text");
}

fn nodePropertyUintKeySupported(key: []const u8) bool {
    return propertyKeyNameValid(key) and !std.mem.eql(u8, key, "text");
}

fn nodePropertyKeySupported(key: []const u8) bool {
    return nodePropertyStringKeySupported(key) or nodePropertyUintKeySupported(key);
}

fn nodePropertyOverlayStringKeySupported(key: []const u8) bool {
    return nodePropertyStringKeySupported(key);
}

fn edgePropertyOverlayStringKeySupported(key: []const u8) bool {
    return propertyKeyNameValid(key);
}

fn nodePropertyPayloadUintKeySupported(key: []const u8) bool {
    return nodePropertyUintKeySupported(key);
}

fn edgePropertyPayloadUintKeySupported(key: []const u8) bool {
    return propertyKeyNameValid(key);
}

fn propertyKeyNameValid(key: []const u8) bool {
    if (key.len == 0 or key.len > 128) return false;
    for (key) |byte| {
        const ok = std.ascii.isAlphanumeric(byte) or byte == '_' or byte == '-' or byte == ':' or byte == '.';
        if (!ok) return false;
    }
    return true;
}

fn stringPropertyKeySupportedForOwner(owner: PropertyOwner, key: []const u8) bool {
    return switch (owner) {
        .node => nodePropertyOverlayStringKeySupported(key),
        .edge => edgePropertyOverlayStringKeySupported(key),
    };
}

fn uintPropertyKeySupportedForOwner(owner: PropertyOwner, key: []const u8) bool {
    return switch (owner) {
        .node => nodePropertyPayloadUintKeySupported(key),
        .edge => edgePropertyPayloadUintKeySupported(key),
    };
}

fn propertyPayloadOwnerKind(owner: PropertyOwner) u8 {
    return switch (owner) {
        .node => PropertyPayloadIndexRecord.owner_kind_node,
        .edge => PropertyPayloadIndexRecord.owner_kind_edge,
    };
}

fn propertyPayloadOwnerId(owner: PropertyOwner) u64 {
    return switch (owner) {
        .node => |node_id| node_id.toInt(),
        .edge => |edge_id| edge_id.toInt(),
    };
}

fn propertyPayloadOwnerFromParts(owner_kind: u8, owner_id: u64) !PropertyOwner {
    return switch (owner_kind) {
        PropertyPayloadIndexRecord.owner_kind_node => .{ .node = core.NodeId.fromInt(owner_id) },
        PropertyPayloadIndexRecord.owner_kind_edge => .{ .edge = core.EdgeId.fromInt(owner_id) },
        else => error.InvalidRecord,
    };
}

fn propertyPayloadRecordLessThan(_: void, a: PropertyPayloadIndexRecord, b: PropertyPayloadIndexRecord) bool {
    if (a.key_hash != b.key_hash) return a.key_hash < b.key_hash;
    if (a.value_type != b.value_type) return a.value_type < b.value_type;
    if (a.value_hash != b.value_hash) return a.value_hash < b.value_hash;
    if (a.owner_kind != b.owner_kind) return a.owner_kind < b.owner_kind;
    return a.owner_id < b.owner_id;
}

fn propertyPayloadEntryLessThan(_: void, a: PropertyPayloadIndexEntry, b: PropertyPayloadIndexEntry) bool {
    return propertyPayloadRecordLessThan({}, a.record, b.record);
}

fn propertyPayloadEntryMatchesOwnerKey(entry: PropertyPayloadIndexEntry, owner: PropertyOwner, key: []const u8) bool {
    return entry.record.owner_kind == propertyPayloadOwnerKind(owner) and
        entry.record.owner_id == propertyPayloadOwnerId(owner) and
        entry.record.key_hash == nodePropertyKeyHash(key);
}

const PropertyPayloadOwnerKey = struct {
    owner_kind: u8,
    owner_id: u64,
    key_hash: u64,
};

const PropertyPayloadOwnerKeySet = std.AutoHashMap(PropertyPayloadOwnerKey, void);
const PropertyPayloadNodeIdSet = std.AutoHashMap(u64, void);

const PropertyPayloadOwnerFilter = struct {
    owner_kind: u8,
    owner_ids: ?*const PropertyPayloadNodeIdSet = null,

    fn matches(self: PropertyPayloadOwnerFilter, owner_kind: u8, owner_id: u64) bool {
        if (owner_kind != self.owner_kind) return false;
        return if (self.owner_ids) |ids| ids.contains(owner_id) else true;
    }
};

const PropertyPayloadExistingKeyTarget = struct {
    wanted: *const PropertyPayloadOwnerKeySet,
    found: *PropertyPayloadOwnerKeySet,
};

const PropertyPayloadLookupTarget = struct {
    owner_key: PropertyPayloadOwnerKey,
    key_name: []const u8,
    value: ?PropertyPayloadIndexEntry = null,

    fn deinit(self: *PropertyPayloadLookupTarget, allocator: std.mem.Allocator) void {
        if (self.value) |*value| value.deinit(allocator);
        self.value = null;
    }
};

const PropertyPayloadKeyTarget = struct {
    key_hash: u64,
    key_name: []const u8,
    entries: *std.ArrayList(PropertyPayloadIndexEntry),
    positions: *std.AutoHashMap(PropertyPayloadOwnerKey, usize),
    owner_filter: ?PropertyPayloadOwnerFilter = null,
};

const SearchablePropertyByteBudget = struct {
    max_bytes: u64,
    used_bytes: u64 = 0,

    fn afterReplace(self: SearchablePropertyByteBudget, old_len: usize, new_len: usize) !u64 {
        const old_bytes: u64 = @intCast(old_len);
        const new_bytes: u64 = @intCast(new_len);
        if (old_bytes > self.used_bytes) return error.InvalidRecord;
        const without_old = self.used_bytes - old_bytes;
        const next = std.math.add(u64, without_old, new_bytes) catch return error.SearchableMetadataBudgetExceeded;
        if (next > self.max_bytes) return error.SearchableMetadataBudgetExceeded;
        return next;
    }
};

const PropertyPayloadIndexedTarget = struct {
    entries: *std.ArrayList(PropertyPayloadIndexEntry),
    positions: *std.AutoHashMap(PropertyPayloadOwnerKey, usize),
    searchable_byte_budget: ?*SearchablePropertyByteBudget = null,
};

const PropertyPayloadKeyNameMap = std.AutoHashMap(u64, []const u8);

const PropertyPayloadSnapshotTarget = struct {
    key_names: *const PropertyPayloadKeyNameMap,
    entries: *std.ArrayList(PropertySnapshotEntry),
    positions: *std.AutoHashMap(PropertyPayloadOwnerKey, usize),
    owner_filter: PropertyPayloadOwnerFilter,
};

const PropertyPayloadLayerScanTarget = struct {
    context: *anyopaque,
    visit: PropertySnapshotLayerVisitor,
    next_version: *u64,
};

const PropertyPayloadDeltaTarget = union(enum) {
    none,
    all: PropertyPayloadIndexedTarget,
    searchable: PropertyPayloadIndexedTarget,
    key: PropertyPayloadKeyTarget,
    snapshot: PropertyPayloadSnapshotTarget,
    existing_keys: PropertyPayloadExistingKeyTarget,
    lookup: *PropertyPayloadLookupTarget,
    layer_scan: PropertyPayloadLayerScanTarget,
};

fn propertyPayloadOwnerKey(owner: PropertyOwner, key: []const u8) PropertyPayloadOwnerKey {
    return .{
        .owner_kind = propertyPayloadOwnerKind(owner),
        .owner_id = propertyPayloadOwnerId(owner),
        .key_hash = nodePropertyKeyHash(key),
    };
}

fn appendStringPropertyPayloadRecord(entries: *std.ArrayList(PropertyPayloadIndexEntry), allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8, value: []const u8) !void {
    if (value.len == 0) return;
    const owned = try allocator.dupe(u8, value);
    errdefer allocator.free(owned);
    try entries.append(allocator, .{
        .record = .{
            .key_hash = nodePropertyKeyHash(key),
            .value_hash = nodePropertyValueHash(value),
            .owner_id = propertyPayloadOwnerId(owner),
            .owner_kind = propertyPayloadOwnerKind(owner),
            .value_type = PropertyPayloadIndexRecord.value_type_string,
        },
        .value = owned,
    });
}

fn appendUintPropertyPayloadRecord(entries: *std.ArrayList(PropertyPayloadIndexEntry), allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8, value: u64) !void {
    try entries.append(allocator, .{
        .record = .{
            .key_hash = nodePropertyKeyHash(key),
            .value_hash = value,
            .owner_id = propertyPayloadOwnerId(owner),
            .owner_kind = propertyPayloadOwnerKind(owner),
            .value_type = PropertyPayloadIndexRecord.value_type_uint,
        },
    });
}

fn appendNodePropertyRecordForValue(entries: *std.ArrayList(NodePropertyIndexEntry), allocator: std.mem.Allocator, node_id: core.NodeId, key: []const u8, value: ?[]const u8) !void {
    const concrete = value orelse return;
    if (concrete.len == 0) return;
    const owned = try allocator.dupe(u8, concrete);
    errdefer allocator.free(owned);
    try entries.append(allocator, .{
        .record = .{
            .key_hash = nodePropertyKeyHash(key),
            .value_hash = nodePropertyValueHash(concrete),
            .node_id = node_id.toInt(),
            .value_type = NodePropertyIndexRecord.value_type_string,
        },
        .value = owned,
    });
}

fn appendEdgePropertyRecordForValue(entries: *std.ArrayList(NodePropertyIndexEntry), allocator: std.mem.Allocator, edge_id: core.EdgeId, key: []const u8, value: []const u8) !void {
    if (value.len == 0) return;
    const owned = try allocator.dupe(u8, value);
    errdefer allocator.free(owned);
    try entries.append(allocator, .{
        .record = .{
            .key_hash = nodePropertyKeyHash(key),
            .value_hash = nodePropertyValueHash(value),
            .node_id = edge_id.toInt(),
            .value_type = NodePropertyIndexRecord.value_type_string,
        },
        .value = owned,
    });
}

fn appendNodePropertyRecordForUint(entries: *std.ArrayList(NodePropertyIndexEntry), allocator: std.mem.Allocator, node_id: core.NodeId, key: []const u8, value: ?u64) !void {
    const concrete = value orelse return;
    try entries.append(allocator, .{
        .record = .{
            .key_hash = nodePropertyKeyHash(key),
            .value_hash = concrete,
            .node_id = node_id.toInt(),
            .value_type = NodePropertyIndexRecord.value_type_uint,
        },
    });
}

fn appendNodePropertyRecordsFromText(entries: *std.ArrayList(NodePropertyIndexEntry), allocator: std.mem.Allocator, node_id: core.NodeId, text: []const u8) !void {
    _ = entries;
    _ = allocator;
    _ = node_id;
    _ = text;
}

fn nodePropertyValueFromTextAlloc(allocator: std.mem.Allocator, text: []const u8, key: []const u8) !?[]u8 {
    _ = allocator;
    _ = text;
    _ = key;
    return null;
}

