const OwnedNodeTextRunManifestEntry = struct {
    node_count: u64,
    node_digest: u64,
    order_digest: u64,
    min_node_id: u64 = 0,
    max_node_id: u64 = 0,
    min_hash: u64 = 0,
    max_hash: u64 = 0,
    path: []u8,
    path_digest: u64 = 0,
    has_path_digest: bool = false,
    hash_filter: []u8 = &.{},

    fn deinit(self: *OwnedNodeTextRunManifestEntry, allocator: std.mem.Allocator) void {
        allocator.free(self.path);
        allocator.free(self.hash_filter);
    }

    fn header(self: OwnedNodeTextRunManifestEntry) NodeTextIndexHeader {
        return .{
            .node_count = self.node_count,
            .node_digest = self.node_digest,
            .order_digest = self.order_digest,
        };
    }
};

const NodeTextRunManifest = struct {
    const magic = [_]u8{ 'T', 'K', 'N', 'R' };
    const version: u16 = 5;
    const header_len: usize = 40;
    const entry_header_len: usize = 64;

    entries: std.ArrayList(OwnedNodeTextRunManifestEntry) = .empty,
    total_node_count: u64 = 0,
    node_digest: u64 = 0,
    aggregates_valid: bool = false,
    backing: []u8 = &.{},
    io: std.Io = undefined,
    file: ?std.Io.File = null,
    map: ?std.Io.File.MemoryMap = null,

    fn deinit(self: *NodeTextRunManifest, allocator: std.mem.Allocator) void {
        if (self.backing.len == 0) {
            for (self.entries.items) |*entry| entry.deinit(allocator);
        }
        self.entries.deinit(allocator);
        if (self.map) |*map| {
            map.destroy(self.io);
            self.file.?.close(self.io);
        } else {
            allocator.free(self.backing);
        }
    }

    fn totalNodeCount(self: NodeTextRunManifest) u64 {
        if (self.aggregates_valid) return self.total_node_count;
        var total: u64 = 0;
        for (self.entries.items) |entry| {
            total = std.math.add(u64, total, entry.node_count) catch return std.math.maxInt(u64);
        }
        return total;
    }

    fn nodeDigest(self: NodeTextRunManifest) u64 {
        if (self.aggregates_valid) return self.node_digest;
        var digest: u64 = 0;
        for (self.entries.items) |entry| digest ^= entry.node_digest;
        return digest;
    }

    fn combinedOrderDigest(self: NodeTextRunManifest, base: NodeTextIndexHeader, delta: NodeTextIndexHeader) u64 {
        var digest = combinedNodeTextOrderDigest(base, delta);
        if (self.entries.items.len == 0) return digest;
        for (self.entries.items) |run| {
            var bytes: [56]u8 = undefined;
            std.mem.writeInt(u64, bytes[0..8], digest, .little);
            std.mem.writeInt(u64, bytes[8..16], base.node_count, .little);
            std.mem.writeInt(u64, bytes[16..24], delta.node_count, .little);
            std.mem.writeInt(u64, bytes[24..32], run.node_count, .little);
            std.mem.writeInt(u64, bytes[32..40], run.node_digest, .little);
            std.mem.writeInt(u64, bytes[40..48], run.order_digest, .little);
            const path_digest = if (run.has_path_digest) run.path_digest else std.hash.Wyhash.hash(0x544B_4E52, run.path);
            std.mem.writeInt(u64, bytes[48..56], path_digest, .little);
            digest = std.hash.Wyhash.hash(0x544B_4E4D, &bytes);
        }
        return digest;
    }
};

const NodeTextRunManifestCache = struct {
    path: []u8 = &.{},
    manifest: NodeTextRunManifest = .{},
    event_bytes: u64 = 0,
    valid: bool = false,

    fn clear(self: *NodeTextRunManifestCache, allocator: std.mem.Allocator) void {
        if (self.valid) self.manifest.deinit(allocator);
        allocator.free(self.path);
        self.* = .{};
    }
};

