    edge_batch_segment_delta_stats: ?*EdgeBatchSegmentDeltaStats = null,
    node_batch_append_timings: ?*NodeBatchAppendTimings = null,
    node_append_timings: ?*NodeAppendTimings = null,

    pub fn init(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8) !Store {
        return initWithOptions(allocator, io, dir_path, .{});
    }

    pub fn initWithOptions(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8, options: StorageOptions) !Store {
        return initWithOptionsCreate(allocator, io, dir_path, options, true);
    }

    pub fn open(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8) !Store {
        return openWithOptions(allocator, io, dir_path, .{});
    }

    pub fn openWithOptions(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8, options: StorageOptions) !Store {
        return initWithOptionsCreate(allocator, io, dir_path, options, false);
    }

    fn initWithOptionsCreate(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8, options: StorageOptions, create: bool) !Store {
        if (create) {
            try std.Io.Dir.cwd().createDirPath(io, dir_path);
        } else {
            var dir = try std.Io.Dir.cwd().openDir(io, dir_path, .{});
            dir.close(io);
        }
        const owned_dir_path = try allocator.dupe(u8, dir_path);
        errdefer allocator.free(owned_dir_path);
        const events_bin_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "events.bin" });
        errdefer allocator.free(events_bin_path);
        const index_meta_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "index.meta" });
        errdefer allocator.free(index_meta_path);
        const node_by_id_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_by_id.idx" });
        errdefer allocator.free(node_by_id_path);
        const node_texts_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_texts.dat" });
        errdefer allocator.free(node_texts_path);
        const node_by_text_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_by_text.idx" });
        errdefer allocator.free(node_by_text_path);
        const node_by_text_base_filter_path = try std.fmt.allocPrint(allocator, "{s}.filter", .{node_by_text_path});
        errdefer allocator.free(node_by_text_base_filter_path);
        const node_by_text_delta_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_by_text.delta" });
        errdefer allocator.free(node_by_text_delta_path);
        const external_key_index_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "external_keys.idx" });
        errdefer allocator.free(external_key_index_path);
        const node_props_index_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_props.idx" });
        errdefer allocator.free(node_props_index_path);
        const node_props_values_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_props.values" });
        errdefer allocator.free(node_props_values_path);
        const node_props_overlay_index_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_props_overlay.idx" });
        errdefer allocator.free(node_props_overlay_index_path);
        const node_props_overlay_values_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_props_overlay.values" });
        errdefer allocator.free(node_props_overlay_values_path);
        const edge_props_overlay_index_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_props_overlay.idx" });
        errdefer allocator.free(edge_props_overlay_index_path);
        const edge_props_overlay_values_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_props_overlay.values" });
        errdefer allocator.free(edge_props_overlay_values_path);
        const property_payload_index_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "property_payload.idx" });
        errdefer allocator.free(property_payload_index_path);
        const property_payload_values_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "property_payload.values" });
        errdefer allocator.free(property_payload_values_path);
        const property_payload_delta_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "property_payload.delta" });
        errdefer allocator.free(property_payload_delta_path);
        const edge_external_key_index_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_external_keys.idx" });
        errdefer allocator.free(edge_external_key_index_path);
        const node_text_run_manifest_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_text_runs.manifest" });
        errdefer allocator.free(node_text_run_manifest_path);
        const node_text_run_current_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "node_text_runs.current" });
        errdefer allocator.free(node_text_run_current_path);
        const edge_by_id_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_by_id.idx" });
        errdefer allocator.free(edge_by_id_path);
        const edge_by_src_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_by_src.idx" });
        errdefer allocator.free(edge_by_src_path);
        const edge_by_dst_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_by_dst.idx" });
        errdefer allocator.free(edge_by_dst_path);
        const edge_order_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_order.idx" });
        errdefer allocator.free(edge_order_path);
        const edge_tombstones_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_tombstones.idx" });
        errdefer allocator.free(edge_tombstones_path);
        const edge_segment_manifest_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_segment.manifest" });
        errdefer allocator.free(edge_segment_manifest_path);
        const edge_segment_current_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "edge_segment_current" });
        errdefer allocator.free(edge_segment_current_path);
        const catalog_path = try std.fs.path.join(allocator, &.{ owned_dir_path, "catalog.bin" });
        errdefer allocator.free(catalog_path);
        const index_meta_cache = try allocator.create(IndexMetaCache);
        errdefer allocator.destroy(index_meta_cache);
        index_meta_cache.* = .{};
        const node_text_delta_header_cache = try allocator.create(NodeTextDeltaHeaderCache);
        errdefer allocator.destroy(node_text_delta_header_cache);
        node_text_delta_header_cache.* = .{};
        const node_text_delta_run_cache = try allocator.create(NodeTextDeltaRunCache);
        errdefer allocator.destroy(node_text_delta_run_cache);
        node_text_delta_run_cache.* = .{};
        const node_text_run_manifest_cache = try allocator.create(NodeTextRunManifestCache);
        errdefer allocator.destroy(node_text_run_manifest_cache);
        node_text_run_manifest_cache.* = .{};
        const node_text_base_filter_cache = try allocator.create(NodeTextBaseHashFilterCache);
        errdefer allocator.destroy(node_text_base_filter_cache);
        node_text_base_filter_cache.* = .{};
        const store = Store{
            .allocator = allocator,
            .io = io,
            .dir_path = owned_dir_path,
            .events_bin_path = events_bin_path,
            .index_meta_path = index_meta_path,
            .node_by_id_path = node_by_id_path,
            .node_texts_path = node_texts_path,
            .node_by_text_path = node_by_text_path,
            .node_by_text_base_filter_path = node_by_text_base_filter_path,
            .node_by_text_delta_path = node_by_text_delta_path,
            .external_key_index_path = external_key_index_path,
            .node_props_index_path = node_props_index_path,
            .node_props_values_path = node_props_values_path,
            .node_props_overlay_index_path = node_props_overlay_index_path,
            .node_props_overlay_values_path = node_props_overlay_values_path,
            .edge_props_overlay_index_path = edge_props_overlay_index_path,
            .edge_props_overlay_values_path = edge_props_overlay_values_path,
            .property_payload_index_path = property_payload_index_path,
            .property_payload_values_path = property_payload_values_path,
            .property_payload_delta_path = property_payload_delta_path,
            .edge_external_key_index_path = edge_external_key_index_path,
            .node_text_run_manifest_path = node_text_run_manifest_path,
            .node_text_run_current_path = node_text_run_current_path,
            .edge_by_id_path = edge_by_id_path,
            .edge_by_src_path = edge_by_src_path,
            .edge_by_dst_path = edge_by_dst_path,
            .edge_order_path = edge_order_path,
            .edge_tombstones_path = edge_tombstones_path,
            .edge_segment_manifest_path = edge_segment_manifest_path,
            .edge_segment_current_path = edge_segment_current_path,
            .catalog_path = catalog_path,
            .index_meta_cache = index_meta_cache,
            .node_text_delta_header_cache = node_text_delta_header_cache,
            .node_text_delta_run_cache = node_text_delta_run_cache,
            .node_text_run_manifest_cache = node_text_run_manifest_cache,
            .node_text_base_filter_cache = node_text_base_filter_cache,
            .options = options,
        };
        // The allocation-local errdefers above retain ownership until this
        // function returns successfully.  Do not also errdefer store.deinit()
        // here: an open/recovery failure would free every path and cache twice.
        const store_marker_exists = try store.fileExists(store.events_bin_path);
        if (!create) {
            try store.ensureStoreMarkerExists();
        }
        if (!create or store_marker_exists) {
            const node_text_recovery = try store.recoverNodeTextsAppendJournal();
            // The append journal only makes the node_texts.dat mutation
            // durable. It is committed before the canonical event record and
            // derived indexes are published, so a crash can leave a durable
            // text tail that no event references. Reconcile against the event
            // log on this crash-only path; the repair reuse check preserves a
            // fully published append and rewrites node_texts.dat when the
            // committed tail is orphaned.
            if (node_text_recovery == .committed) {
                try store.repairPersistentIndexesFromLog();
            }
        }
        // init is create-or-open at the storage API boundary.  Recover for both
        // entry points so an interrupted property publication cannot be
        // bypassed by a writer that re-enters through initWithOptions().
        try store.recoverPropertyPayloadRedoJournal();
        _ = try store.recoverPropertyPayloadDeltaJournal();
        return store;
    }

    pub fn deinit(self: *Store) void {
        self.index_meta_cache.clear();
        self.allocator.destroy(self.index_meta_cache);
        self.node_text_delta_header_cache.clear();
        self.allocator.destroy(self.node_text_delta_header_cache);
        self.node_text_delta_run_cache.clear();
        self.allocator.destroy(self.node_text_delta_run_cache);
        self.node_text_run_manifest_cache.clear(self.allocator);
        self.allocator.destroy(self.node_text_run_manifest_cache);
        self.node_text_base_filter_cache.clear(self.allocator);
        self.allocator.destroy(self.node_text_base_filter_cache);
        self.allocator.free(self.edge_segment_current_path);
        self.allocator.free(self.catalog_path);
        self.allocator.free(self.edge_segment_manifest_path);
        self.allocator.free(self.edge_order_path);
        self.allocator.free(self.edge_by_dst_path);
        self.allocator.free(self.edge_by_src_path);
        self.allocator.free(self.edge_by_id_path);
        self.allocator.free(self.edge_tombstones_path);
        self.allocator.free(self.node_text_run_current_path);
        self.allocator.free(self.node_text_run_manifest_path);
        self.allocator.free(self.node_by_text_delta_path);
        self.allocator.free(self.external_key_index_path);
        self.allocator.free(self.node_props_index_path);
        self.allocator.free(self.node_props_values_path);
        self.allocator.free(self.node_props_overlay_index_path);
        self.allocator.free(self.node_props_overlay_values_path);
        self.allocator.free(self.edge_props_overlay_index_path);
        self.allocator.free(self.edge_props_overlay_values_path);
        self.allocator.free(self.property_payload_index_path);
        self.allocator.free(self.property_payload_values_path);
        self.allocator.free(self.property_payload_delta_path);
        self.allocator.free(self.edge_external_key_index_path);
        self.allocator.free(self.node_by_text_base_filter_path);
        self.allocator.free(self.node_by_text_path);
        self.allocator.free(self.node_texts_path);
        self.allocator.free(self.node_by_id_path);
        self.allocator.free(self.index_meta_path);
        self.allocator.free(self.events_bin_path);
        self.allocator.free(self.dir_path);
    }

    pub fn createEmpty(self: Store) !void {
        if (!try self.fileExists(self.events_bin_path)) {
            if (try self.anyDerivedGraphCatalogPathExists()) return error.InvalidRecord;
            try std.Io.Dir.cwd().writeFile(self.io, .{
                .sub_path = self.events_bin_path,
                .data = "",
                .flags = .{ .truncate = false },
            });
        }
        if (!self.options.validate_indexes_on_read and try self.fastPersistentIndexesCurrent()) {
            return;
        }
        const stats_out = try self.stats();
        const missing_meta = !try self.fileExists(self.index_meta_path);
        const missing_node_by_id = !try self.fileExists(self.node_by_id_path);
        const missing_node_texts = !try self.fileExists(self.node_texts_path);
        const missing_node_by_text = !try self.fileExists(self.node_by_text_path);
        const missing_node_by_text_delta = !try self.fileExists(self.node_by_text_delta_path);
        const missing_external_key_index = !try self.fileExists(self.external_key_index_path);
        const missing_node_props_index = !try self.fileExists(self.node_props_index_path);
        const missing_node_props_values = !try self.fileExists(self.node_props_values_path);
        const missing_edge_external_key_index = !try self.fileExists(self.edge_external_key_index_path);
        if (missing_node_by_id and stats_out.nodes == 0) {
            try self.writeEmptyNodeIndexes();
        }
        if (missing_node_texts and stats_out.nodes == 0 and !missing_node_by_id) {
            try std.Io.Dir.cwd().writeFile(self.io, .{
                .sub_path = self.node_texts_path,
                .data = "",
                .flags = .{ .truncate = false },
            });
        }
        if (missing_node_by_text and stats_out.nodes == 0 and !missing_node_by_id) {
            try self.writeNodeTextIndex(&.{});
        }
        if (missing_node_by_text_delta and stats_out.nodes == 0 and !missing_node_by_id) {
            try self.writeEmptyNodeTextDelta();
        }
        if (missing_external_key_index and stats_out.nodes == 0 and !missing_node_by_id) {
            try self.writeExternalKeyIndex(&.{}, .{});
        }
        if ((missing_node_props_index or missing_node_props_values) and stats_out.nodes == 0 and !missing_node_by_id) {
            try self.writeNodePropertyIndex(&.{}, .{});
        }
        if (missing_edge_external_key_index and stats_out.edges == 0 and !missing_node_by_id) {
            try self.writeEdgeExternalKeyIndex(&.{}, .{});
        }
        if ((missing_node_by_id or missing_node_texts or missing_node_by_text or missing_node_by_text_delta or missing_node_props_index or missing_node_props_values) and stats_out.nodes != 0) {
            return try self.repairPersistentIndexesFromLog();
        }
        const missing_id = !try self.fileExists(self.edge_by_id_path);
        const missing_src = !try self.fileExists(self.edge_by_src_path);
        const missing_dst = !try self.fileExists(self.edge_by_dst_path);
        const missing_order = !try self.fileExists(self.edge_order_path);
        const missing_tombstones = !try self.fileExists(self.edge_tombstones_path);
        if (missing_id and stats_out.edges == 0) {
            try self.writeEdgeIndex(self.edge_by_id_path, &.{});
        }
        if (missing_src and stats_out.edges == 0) {
            try self.writeEdgeIndex(self.edge_by_src_path, &.{});
        }
        if (missing_dst and stats_out.edges == 0) {
            try self.writeEdgeIndex(self.edge_by_dst_path, &.{});
        }
        if (missing_order) {
            try self.writeEdgeOrderIndex(&.{});
        }
        if (missing_tombstones and stats_out.edges == 0) {
            try self.writeEdgeTombstoneIndex(&.{});
        }
        if ((missing_id or missing_src or missing_dst or missing_tombstones) and stats_out.edges != 0) {
            return try self.repairPersistentIndexesFromLog();
        }
        if (missing_meta) {
            try self.writeIndexMetaFromStats(stats_out);
        }
        if (!try self.persistentIndexesCurrent(stats_out)) {
            try self.repairPersistentIndexesFromLog();
        }

        if (!try self.fileExists(self.catalog_path)) {
            self.writeKernelCatalog() catch {};
        }
    }

    pub fn resetEmptyForTests(self: Store) !void {
        try std.Io.Dir.cwd().writeFile(self.io, .{
            .sub_path = self.events_bin_path,
            .data = "",
            .flags = .{ .truncate = true },
        });
        try self.writeIndexMeta(.{});
        try self.writeEmptyNodeIndexes();
        try self.writeExternalKeyIndex(&.{}, .{});
        try self.writeNodePropertyIndex(&.{}, .{});
        try self.writeEdgeExternalKeyIndex(&.{}, .{});
        std.Io.Dir.cwd().deleteFile(self.io, self.edge_props_overlay_index_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.edge_props_overlay_values_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.property_payload_index_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.property_payload_values_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        const property_payload_redo_journal_path = try self.propertyPayloadRedoJournalPath();
        defer self.allocator.free(property_payload_redo_journal_path);
        std.Io.Dir.cwd().deleteFile(self.io, property_payload_redo_journal_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.property_payload_delta_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        const property_payload_delta_journal_path = try self.propertyPayloadDeltaJournalPath();
        defer self.allocator.free(property_payload_delta_journal_path);
        std.Io.Dir.cwd().deleteFile(self.io, property_payload_delta_journal_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        var node_text_journal_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const node_text_journal_path = try self.nodeTextsAppendJournalPath(&node_text_journal_buffer);
        std.Io.Dir.cwd().deleteFile(self.io, node_text_journal_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        const node_text_journal_tmp_path = try self.tmpPathFor(node_text_journal_path);
        defer self.allocator.free(node_text_journal_tmp_path);
        std.Io.Dir.cwd().deleteFile(self.io, node_text_journal_tmp_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        const primary_text_tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.deflate.tmp", .{self.node_texts_path});
        defer self.allocator.free(primary_text_tmp_path);
        std.Io.Dir.cwd().deleteFile(self.io, primary_text_tmp_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        const primary_text_table_tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.deflate.table.tmp", .{self.node_texts_path});
        defer self.allocator.free(primary_text_table_tmp_path);
        std.Io.Dir.cwd().deleteFile(self.io, primary_text_table_tmp_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        try self.writeEdgeIndex(self.edge_by_id_path, &.{});
        try self.writeEdgeIndex(self.edge_by_src_path, &.{});
        try self.writeEdgeIndex(self.edge_by_dst_path, &.{});
        try self.writeEdgeOrderIndex(&.{});
        try self.writeEdgeTombstoneIndex(&.{});
        std.Io.Dir.cwd().deleteFile(self.io, self.edge_segment_manifest_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.edge_segment_current_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.node_text_run_manifest_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        std.Io.Dir.cwd().deleteFile(self.io, self.node_text_run_current_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        self.invalidateNodeTextRunManifestCache();
    }

    pub fn appendNode(self: Store, node: graph_mod.Node) !void {
        if (node.status != .active) return core.Error.Unsupported;
        if (node.text.len > maxBinaryNodeTextLen()) return error.RecordTooLarge;
        try graph_mod.validateNodeText(node.text);
        try self.reconcileNodeTextsBeforeAppend();
        const validate_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.validateNodeIndexAppendWithRepair(node);
        if (self.node_append_timings) |timings| timings.validate_ns += storageElapsedNs(self.io, validate_start);
        const event_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        const rollback_event_bytes = try self.eventBytes();
        if (self.node_append_timings) |timings| timings.event_bytes_ns += storageElapsedNs(self.io, event_start);
        var published = false;
        var text_appended = false;
        errdefer if (!published) self.rollbackNodeAppendFailure(rollback_event_bytes, text_appended);

        const append_texts_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        const text_span = try self.appendNodeTextBytes(node.text);
        text_appended = true;
        if (self.node_append_timings) |timings| timings.append_texts_ns += storageElapsedNs(self.io, append_texts_start);
        const append_record_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.appendNodeRecord(node, text_span);
        if (self.node_append_timings) |timings| timings.append_record_ns += storageElapsedNs(self.io, append_record_start);
        const indexes_current = self.refreshIndexesAfterCommittedAppend(.node, node, null, text_span);
        if (self.node_append_timings) |timings| timings.nodes += 1;
        published = true;
        // Keep the committed text journal until the whole append transaction,
        // including derived-index publication, has succeeded. If index work
        // fails, rollbackNodeAppendFailure may itself be unable to repair under
        // the same filesystem/allocation fault; the journal must survive as
        // the durable anchor that lets reopen or the next append remove the
        // now-unreferenced text tail.
        if (indexes_current) self.cleanupCommittedNodeTextsAppendJournal();
    }

    pub fn appendNodesBatch(self: Store, nodes: []const graph_mod.Node) !void {
        if (nodes.len == 0) return;
        try self.reconcileNodeTextsBeforeAppend();
        self.appendNodesBatchOnce(nodes) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                const repair_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
                try self.repairPersistentIndexesFromLog();
                if (self.node_batch_append_timings) |timings| {
                    timings.repair_retry_count += 1;
                    timings.repair_ns += storageElapsedNs(self.io, repair_start);
                }
                return try self.appendNodesBatchOnce(nodes);
            },
            else => |e| return e,
        };
    }

    fn appendNodesBatchOnce(self: Store, nodes: []const graph_mod.Node) !void {
        if (self.node_batch_append_timings) |timings| {
            timings.batches += 1;
            timings.nodes += @intCast(nodes.len);
        }

        const read_meta_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        const old_meta = try self.readCurrentIndexMetaForAppend();
        if (self.node_batch_append_timings) |timings| timings.read_meta_ns += storageElapsedNs(self.io, read_meta_start);

        const validate_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.validateNodeBatchAppend(nodes, old_meta);
        if (self.node_batch_append_timings) |timings| timings.validate_ns += storageElapsedNs(self.io, validate_start);

        const event_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        const rollback_event_bytes = try self.eventBytes();
        const event_bytes_ns = if (self.node_batch_append_timings != null) storageElapsedNs(self.io, event_start) else 0;
        var published = false;
        var texts_appended = false;
        errdefer if (!published) self.rollbackNodeAppendFailure(rollback_event_bytes, texts_appended);

        const append_texts_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        const text_spans = try self.appendNodeTextsBatch(nodes);
        texts_appended = true;
        if (self.node_batch_append_timings) |timings| timings.append_texts_ns += storageElapsedNs(self.io, append_texts_start);
        defer self.allocator.free(text_spans);

        const event_records_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.appendNodeBatchRecords(nodes, text_spans, rollback_event_bytes);
        if (self.node_batch_append_timings) |timings| timings.append_event_records_ns += event_bytes_ns + storageElapsedNs(self.io, event_records_start);

        var text_records = std.ArrayList(NodeTextIndexRecord).empty;
        defer text_records.deinit(self.allocator);
        try text_records.ensureTotalCapacity(self.allocator, nodes.len);

        var next_meta = old_meta;
        next_meta.event_bytes = try self.eventBytes();
        const by_id_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.appendNodeByIdIndexRecordsBatch(old_meta, nodes, text_spans, &text_records, &next_meta);
        if (self.node_batch_append_timings) |timings| timings.by_id_index_ns += storageElapsedNs(self.io, by_id_start);

        const batch_node_digest = old_meta.node_digest ^ next_meta.node_digest;
        const node_text_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        if (!try self.publishNodeTextRunBatchIfPossible(old_meta, next_meta, text_records.items, batch_node_digest, .trusted_recent_by_id_append)) {
            if (!try self.writeNodeTextDeltaBatchIfPossible(old_meta, text_records.items, batch_node_digest, next_meta.node_digest)) {
                var manifest = try self.readNodeTextRunManifest(self.allocator);
                defer manifest.deinit(self.allocator);
                const delta_header = try self.readNodeTextDeltaHeader();
                var compacted_old_meta = old_meta;
                if (try self.compactNodeTextRunWindowForMeta(old_meta, manifest.entries.items, delta_header, 0, &.{})) |_| {
                    compacted_old_meta = try self.readIndexMeta();
                } else {
                    const compacted = try self.compactNodeTextOverlaysForMeta(old_meta.nodes, old_meta.node_digest, old_meta.node_by_text_order_digest, &.{});
                    compacted_old_meta.node_by_text_order_digest = compacted.order_digest;
                }
                if (compacted_old_meta.nodes != old_meta.nodes) return error.InvalidRecord;
                if (compacted_old_meta.node_digest != old_meta.node_digest) return error.InvalidRecord;
                if (!try self.publishNodeTextRunBatchIfPossible(compacted_old_meta, next_meta, text_records.items, batch_node_digest, .trusted_recent_by_id_append)) {
                    if (!try self.writeNodeTextDeltaBatchIfPossible(compacted_old_meta, text_records.items, batch_node_digest, next_meta.node_digest)) {
                        const compacted = try self.compactNodeTextOverlaysForMeta(compacted_old_meta.nodes, compacted_old_meta.node_digest, compacted_old_meta.node_by_text_order_digest, &.{});
                        compacted_old_meta.node_by_text_order_digest = compacted.order_digest;
                        try self.writeMergedNodeTextIndexBatch(compacted_old_meta, text_records.items, batch_node_digest, next_meta.node_digest, .trusted_recent_by_id_append);
                    }
                }
            }
        }
        if (self.node_batch_append_timings) |timings| timings.node_text_index_ns += storageElapsedNs(self.io, node_text_start);

        const meta_write_start = if (self.node_batch_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.copyNodeTextOrderDigestFromHeader(&next_meta);
        self.updateExternalKeyIndexForNodeBatch(old_meta, next_meta, nodes) catch {};
        self.updateNodePropertyIndexForNodeBatch(old_meta, next_meta, nodes) catch {};
        try self.writeIndexMeta(next_meta);
        if (self.node_batch_append_timings) |timings| timings.meta_write_ns += storageElapsedNs(self.io, meta_write_start);
        published = true;
        self.cleanupCommittedNodeTextsAppendJournal();
    }

    fn rollbackNodeAppendFailure(self: Store, rollback_event_bytes: u64, texts_appended: bool) void {
        self.rollbackBatchAppend(rollback_event_bytes) catch {};
        if (!texts_appended) return;

        // Node text is published before its canonical event. Both single and
        // batch append retain the committed journal through derived-index
        // publication, so if this best-effort repair fails the durable anchor
        // remains for reopen or the next append instead of stranding an
        // unreachable text suffix.
        self.repairPersistentIndexesFromLog() catch {};
    }

    fn appendNodeRecord(self: Store, node: graph_mod.Node, text_span: TextSpan) !void {
        var payload: [binary_node_payload_len]u8 = undefined;
        _ = try encodeBinaryNodeFixedPayload(&payload, node, text_span);
        var record = std.ArrayList(u8).empty;
        defer record.deinit(self.allocator);
        try appendBinaryRecord(&record, self.allocator, .node, &payload);
        try self.appendRecord(record.items);
    }

    pub fn addNode(self: Store, kind: core.NodeKind, text: []const u8) !core.NodeId {
        var repaired = false;
        while (true) {
            const next_id_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
            const id = self.nextNodeId() catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => {
                    if (repaired) return err;
                    repaired = true;
                    try self.repairPersistentIndexesFromLog();
                    continue;
                },
                else => |e| return e,
            };
            if (self.node_append_timings) |timings| timings.next_id_ns += storageElapsedNs(self.io, next_id_start);
            self.appendNode(.{
                .id = id,
                .kind = kind,
                .text = text,
            }) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => {
                    if (repaired) return err;
                    repaired = true;
                    try self.repairPersistentIndexesFromLog();
                    continue;
                },
                else => |e| return e,
            };
            return id;
        }
    }

    pub fn updateNode(self: Store, node_id: core.NodeId, kind: core.NodeKind, text: []const u8) !NodeRewriteResult {
        if (isReservedNodeId(node_id)) return core.Error.InvalidId;
        try graph_mod.validateNodeText(text);
        if (text.len > maxBinaryNodeTextLen()) return error.RecordTooLarge;
        return try self.rewriteNodeStore(.{ .update = .{ .node_id = node_id, .kind = kind, .text = text } });
    }

    pub fn deleteNode(self: Store, node_id: core.NodeId) !NodeRewriteResult {
        if (isReservedNodeId(node_id)) return core.Error.InvalidId;
        return try self.rewriteNodeStore(.{ .delete = .{ .node_id = node_id } });
    }

    const NodeRewriteAction = union(enum) {
        update: struct {
            node_id: core.NodeId,
            kind: core.NodeKind,
            text: []const u8,
        },
        delete: struct {
            node_id: core.NodeId,
        },

        fn nodeId(self: NodeRewriteAction) core.NodeId {
            return switch (self) {
                .update => |update| update.node_id,
                .delete => |delete| delete.node_id,
            };
        }
    };

    fn rewriteNodeStore(self: Store, action: NodeRewriteAction) !NodeRewriteResult {
        const target_id = action.nodeId();
        var graph = try self.loadGraph();
        defer graph.deinit();
        if (graph.getNode(target_id) == null) return core.Error.NotFound;

        const nonce = store_temp_nonce.fetchAdd(1, .monotonic);
        const tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.rewrite.{d}.tmp", .{ self.dir_path, nonce });
        defer self.allocator.free(tmp_path);
        const backup_path = try std.fmt.allocPrint(self.allocator, "{s}.rewrite.{d}.bak", .{ self.dir_path, nonce });
        defer self.allocator.free(backup_path);
        std.Io.Dir.cwd().deleteTree(self.io, tmp_path) catch {};
        std.Io.Dir.cwd().deleteTree(self.io, backup_path) catch {};
        errdefer std.Io.Dir.cwd().deleteTree(self.io, tmp_path) catch {};
        errdefer std.Io.Dir.cwd().deleteTree(self.io, backup_path) catch {};

        var result = NodeRewriteResult{};
        {
            var rewritten = try Store.initWithOptions(self.allocator, self.io, tmp_path, self.options);
            defer rewritten.deinit();
            try rewritten.createEmpty();

            var rewrite_nodes = std.ArrayList(graph_mod.Node).empty;
            defer {
                for (rewrite_nodes.items) |node| self.allocator.free(node.text);
                rewrite_nodes.deinit(self.allocator);
            }
            try rewrite_nodes.ensureTotalCapacity(self.allocator, graph.nodes.items.len);
            for (graph.nodes.items) |node| {
                var rewritten_kind = node.kind;
                var rewritten_text: []const u8 = node.text;
                var tombstone_text: ?[]u8 = null;
                defer if (tombstone_text) |text| self.allocator.free(text);
                var rewritten_node = graph_mod.Node{
                    .id = node.id,
                    .kind = undefined,
                    .text = undefined,
                };
                if (node.id == target_id) {
                    switch (action) {
                        .update => |update| {
                            rewritten_kind = update.kind;
                            rewritten_text = update.text;
                        },
                        .delete => {
                            rewritten_kind = .edit;
                            tombstone_text = try std.fmt.allocPrint(self.allocator, "__tinykg_deleted_node__ {}", .{node.id.toInt()});
                            rewritten_text = tombstone_text.?;
                        },
                    }
                }
                rewritten_node.kind = rewritten_kind;
                rewritten_node.text = try self.allocator.dupe(u8, rewritten_text);
                errdefer self.allocator.free(rewritten_node.text);
                try rewrite_nodes.append(self.allocator, rewritten_node);
                result.nodes_rewritten += 1;
            }
            try rewritten.appendNodesBatch(rewrite_nodes.items);

            var rewrite_edges = std.ArrayList(graph_mod.Edge).empty;
            defer rewrite_edges.deinit(self.allocator);
            try rewrite_edges.ensureTotalCapacity(self.allocator, graph.edges.items.len);
            var removed_edge_ids = std.AutoHashMap(u64, void).init(self.allocator);
            defer removed_edge_ids.deinit();
            for (graph.edges.items) |edge| {
                if (edge.status != .active) continue;
                const incident_to_deleted = switch (action) {
                    .update => false,
                    .delete => edge.src.toInt() == target_id.toInt() or edge.dst.toInt() == target_id.toInt(),
                };
                if (incident_to_deleted) {
                    try removed_edge_ids.put(edge.id.toInt(), {});
                    result.edges_removed += 1;
                    continue;
                }
                try rewrite_edges.append(self.allocator, edge);
                result.edges_rewritten += 1;
            }
            try rewritten.appendEdgesBatch(rewrite_edges.items);

            var payload_entries = try self.readPropertyPayloadEntriesOrEmpty(self.allocator);
            defer {
                deinitPropertyPayloadIndexEntries(payload_entries.items, self.allocator);
                payload_entries.deinit(self.allocator);
            }
            if (payload_entries.items.len != 0) {
                switch (action) {
                    .update => try rewritten.writePropertyPayload(payload_entries.items),
                    .delete => {
                        // The deleted node and incident edges lose their
                        // properties, but unrelated owners remain canonical.
                        // Dropping the whole payload here used to erase every
                        // task lifecycle/property in the store after deleting
                        // one node. Compact in place, transferring ownership
                        // of retained string values into the surviving prefix.
                        var retained: usize = 0;
                        for (payload_entries.items) |entry| {
                            const remove = (entry.record.owner_kind == PropertyPayloadIndexRecord.owner_kind_node and
                                entry.record.owner_id == target_id.toInt()) or
                                (entry.record.owner_kind == PropertyPayloadIndexRecord.owner_kind_edge and
                                    removed_edge_ids.contains(entry.record.owner_id));
                            if (remove) {
                                var owned = entry;
                                owned.deinit(self.allocator);
                                continue;
                            }
                            payload_entries.items[retained] = entry;
                            retained += 1;
                        }
                        payload_entries.items.len = retained;
                        if (retained != 0) try rewritten.writePropertyPayload(payload_entries.items);
                    },
                }
            }

            // A node-text rewrite replaces the whole directory, but the
            // embedded schema catalog and store-format manifest are canonical
            // control-plane state, not derived indexes. Recreating the target
            // with createEmpty() installs a kernel-only catalog and no
            // manifest; publishing that directory used to silently downgrade
            // a migrated v2/v3 store to "legacy" after any task text update.
            // Preserve both files inside the same COW transaction. Full-text
            // indexes are intentionally omitted because changed node text
            // makes them stale; callers may warm them explicitly.
            try self.copyRewriteControlPlane(&rewritten);
        }

        try std.Io.Dir.rename(.cwd(), self.dir_path, .cwd(), backup_path, self.io);
        var original_moved = true;
        errdefer if (original_moved) {
            std.Io.Dir.rename(.cwd(), backup_path, .cwd(), self.dir_path, self.io) catch {};
        };
        try std.Io.Dir.rename(.cwd(), tmp_path, .cwd(), self.dir_path, self.io);
        original_moved = false;
        // 整目录已换新:进程内 meta 缓存必须失效。缓存钥匙是 events.bin 字节数,
        // 而重写(记录对齐填充)常保字节数不变 → 不清则同进程后续读(如 update-node
        // 换店后的治理属性写)拿旧 digest 撞 InvalidRecord(revise→revise 必挂,存量 bug)。
        self.index_meta_cache.clear();
        try self.syncParentDirForPath(self.dir_path);
        std.Io.Dir.cwd().deleteTree(self.io, backup_path) catch {};
        return result;
    }

    fn copyRewriteControlPlane(self: Store, rewritten: *const Store) !void {
        _ = try self.copyRegularFileForRewrite(self.catalog_path, rewritten.catalog_path);

        const source_manifest = try std.fs.path.join(self.allocator, &.{ self.dir_path, ".tinykg", "store-manifest.json" });
        defer self.allocator.free(source_manifest);
        const target_manifest = try std.fs.path.join(self.allocator, &.{ rewritten.dir_path, ".tinykg", "store-manifest.json" });
        defer self.allocator.free(target_manifest);
        if (try self.copyRegularFileForRewrite(source_manifest, target_manifest)) {
            const target_manifest_dir = std.fs.path.dirname(target_manifest) orelse return error.InvalidRecord;
            try rewritten.syncParentDirForPath(target_manifest_dir);
        }
    }

    fn copyRegularFileForRewrite(self: Store, source_path: []const u8, target_path: []const u8) !bool {
        const stat = std.Io.Dir.cwd().statFile(self.io, source_path, .{ .follow_symlinks = false }) catch |err| switch (err) {
            error.FileNotFound, error.NotDir => return false,
            else => |e| return e,
        };
        if (stat.kind != .file) return error.InvalidRecord;
        try std.Io.Dir.copyFile(std.Io.Dir.cwd(), source_path, std.Io.Dir.cwd(), target_path, self.io, .{
            .replace = true,
            .make_path = true,
        });
        if (selfOptionsNeedSync(self)) {
            var target_file = try std.Io.Dir.cwd().openFile(self.io, target_path, .{ .mode = .read_write });
            defer target_file.close(self.io);
            try target_file.sync(self.io);
        }
        try self.syncParentDirForPath(target_path);
        return true;
    }

    pub fn appendEdge(self: Store, edge: graph_mod.Edge) !void {
        if (edge.status != .active) return core.Error.Unsupported;
        if (try self.appendEdgeSegmentDeltaOnce(edge)) return;
        try self.appendEdgeIndexed(edge);
    }

    pub fn appendEdgeIndexed(self: Store, edge: graph_mod.Edge) !void {
        if (edge.status != .active) return core.Error.Unsupported;
        const keep_segment_current = try self.edgeSegmentCurrentManifestReadable();
        try self.validateEdgeAppendWithRepair(edge);
        try self.appendEdgeRecord(edge);
        _ = self.refreshIndexesAfterCommittedAppend(.edge, null, edge, null);
        if (!keep_segment_current) try self.invalidateEdgeSegmentCurrent();
    }

    pub fn appendEdgeOrderedIndexed(self: Store, edge: graph_mod.Edge, order_key: u64) !void {
        if (order_key == std.math.maxInt(u64)) return error.InvalidRecord;
        try self.appendEdgeIndexed(edge);
        try self.insertEdgeOrderRecord(.{
            .src = edge.src.toInt(),
            .rel = @intFromEnum(edge.rel),
            .edge_id = edge.id.toInt(),
            .order_key = order_key,
        });
    }

    pub fn appendEdgesOrderedBatch(self: Store, edges: []const graph_mod.Edge, order_keys: []const u64) !void {
        if (edges.len != order_keys.len) return error.InvalidRecord;
        if (edges.len == 0) return;
        for (order_keys) |order_key| {
            if (order_key == std.math.maxInt(u64)) return error.InvalidRecord;
        }

        var records = self.readAllEdgeOrderRecords(self.allocator) catch |err| switch (err) {
            error.FileNotFound => std.ArrayList(EdgeOrderRecord).empty,
            else => |e| return e,
        };
        defer records.deinit(self.allocator);
        try records.ensureUnusedCapacity(self.allocator, edges.len);
        for (edges, order_keys) |edge, order_key| {
            const record = EdgeOrderRecord{
                .src = edge.src.toInt(),
                .rel = @intFromEnum(edge.rel),
                .edge_id = edge.id.toInt(),
                .order_key = order_key,
            };
            try validateEdgeOrderRecord(record);
            records.appendAssumeCapacity(record);
        }
        std.mem.sort(EdgeOrderRecord, records.items, {}, edgeOrderRecordLessThan);

        try self.appendEdgesBatch(edges);
        try self.writeEdgeOrderIndex(records.items);
    }

    fn edgeSegmentCurrentManifestReadable(self: Store) !bool {
        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        return true;
    }

    fn appendEdgeSegmentDeltaOnce(self: Store, edge: graph_mod.Edge) !bool {
        const old_meta = self.readCurrentIndexMetaForAppend() catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        const can_segment_delta = self.canAppendEdgeBatchAsSegmentDelta(old_meta, &.{edge}) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        if (!can_segment_delta) return false;

        var edge_records = std.ArrayList(EdgeIndexRecord).empty;
        defer edge_records.deinit(self.allocator);
        try edge_records.ensureTotalCapacity(self.allocator, 1);

        var next_meta = old_meta;
        try self.validateEdgeBatchAppend(&.{edge}, old_meta, &edge_records, &next_meta, true);

        const rollback_event_bytes = try self.eventBytes();
        var published = false;
        errdefer if (!published) self.rollbackBatchAppend(rollback_event_bytes) catch {};

        try self.appendEdgeRecordAt(edge, rollback_event_bytes);
        next_meta.event_bytes = try self.eventBytes();
        next_meta.edge_indexed_edges = old_meta.edge_indexed_edges;
        next_meta.edge_index_digest = old_meta.edge_index_digest;
        try self.publishEdgeBatchSegmentIfManifestCurrent(old_meta, &next_meta, edge_records.items);
        try self.writeIndexMeta(next_meta);
        published = true;
        self.maintainEdgeSegmentsAfterCommittedAppend();
        return true;
    }

    pub fn deleteEdge(self: Store, edge_id: core.EdgeId) !void {
        self.deleteEdgeOnce(edge_id) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                try self.repairPersistentIndexesFromLog();
                return try self.deleteEdgeOnce(edge_id);
            },
            else => |e| return e,
        };
    }

    pub fn deleteEdgesBatch(self: Store, edge_ids: []const core.EdgeId) !void {
        if (edge_ids.len == 0) return;
        self.deleteEdgesBatchOnce(edge_ids) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                try self.repairPersistentIndexesFromLog();
                return try self.deleteEdgesBatchOnce(edge_ids);
            },
            else => |e| return e,
        };
    }

    fn deleteEdgeOnce(self: Store, edge_id: core.EdgeId) !void {
        if (edge_id == .none or edge_id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
        const old_meta = try self.readCurrentIndexMetaForAppend();
        if (!try self.edgeStorageMatchesMeta(old_meta, self.options.validate_indexes_on_read)) return error.InvalidRecord;
        const record = try self.readVisibleEdgeIndexRecordById(edge_id);

        const rollback_event_bytes = try self.eventBytes();
        var published = false;
        errdefer if (!published) self.rollbackBatchAppend(rollback_event_bytes) catch {};

        try self.appendEdgeDeleteRecord(edge_id);

        var next_meta = old_meta;
        if (next_meta.edges == 0) return error.InvalidRecord;
        next_meta.edges -= 1;
        next_meta.edge_digest ^= edgeRecordDigest(record);
        next_meta.event_bytes = try self.eventBytes();
        next_meta.max_edge_id_seen = @max(next_meta.max_edge_id_seen, edge_id.toInt());
        _ = try self.insertEdgeTombstone(record);
        try self.writeIndexMeta(next_meta);
        published = true;
    }

    fn deleteEdgesBatchOnce(self: Store, edge_ids: []const core.EdgeId) !void {
        const old_meta = try self.readCurrentIndexMetaForAppend();
        if (!try self.edgeStorageMatchesMeta(old_meta, self.options.validate_indexes_on_read)) return error.InvalidRecord;
        if (@as(u64, @intCast(edge_ids.len)) > old_meta.edges) return core.Error.InvalidId;

        var existing_tombstones = try self.readAllEdgeTombstones(self.allocator);
        defer existing_tombstones.deinit(self.allocator);

        var batch_tombstones = std.ArrayList(EdgeTombstoneRecord).empty;
        defer batch_tombstones.deinit(self.allocator);
        try batch_tombstones.ensureTotalCapacityPrecise(self.allocator, edge_ids.len);

        var batch_visible_digest: u64 = 0;
        for (edge_ids) |edge_id| {
            if (edge_id == .none or edge_id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
            if (edgeTombstoneSliceContains(existing_tombstones.items, edge_id.toInt())) return core.Error.InvalidId;
            const record = try self.readVisibleEdgeIndexRecordById(edge_id);
            const edge_digest = edgeRecordDigest(record);
            batch_tombstones.appendAssumeCapacity(.{
                .edge_id = record.edge_id,
                .edge_digest = edge_digest,
            });
            batch_visible_digest ^= edge_digest;
        }
        std.mem.sort(EdgeTombstoneRecord, batch_tombstones.items, {}, edgeTombstoneLessThan);
        for (batch_tombstones.items[1..], 1..) |record, i| {
            if (batch_tombstones.items[i - 1].edge_id == record.edge_id) return core.Error.InvalidId;
        }

        const rollback_event_bytes = try self.eventBytes();
        var published = false;
        errdefer if (!published) self.rollbackBatchAppend(rollback_event_bytes) catch {};

        try self.appendEdgeDeleteRecordsAt(edge_ids, rollback_event_bytes);

        var merged_tombstones = std.ArrayList(EdgeTombstoneRecord).empty;
        defer merged_tombstones.deinit(self.allocator);
        try merged_tombstones.ensureTotalCapacityPrecise(self.allocator, existing_tombstones.items.len + batch_tombstones.items.len);
        try mergeEdgeTombstones(existing_tombstones.items, batch_tombstones.items, &merged_tombstones);
        try self.writeEdgeTombstoneIndex(merged_tombstones.items);

        var next_meta = old_meta;
        next_meta.edges -= @intCast(edge_ids.len);
        next_meta.edge_digest ^= batch_visible_digest;
        next_meta.event_bytes = try self.eventBytes();
        for (edge_ids) |edge_id| next_meta.max_edge_id_seen = @max(next_meta.max_edge_id_seen, edge_id.toInt());
        try self.writeIndexMeta(next_meta);
        published = true;
    }

    pub fn appendEdgesBatch(self: Store, edges: []const graph_mod.Edge) !void {
        if (edges.len == 0) return;
        self.appendEdgesBatchOnce(edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                try self.repairPersistentIndexesFromLog();
                return try self.appendEdgesBatchOnce(edges);
            },
            else => |e| return e,
        };
    }

    fn appendEdgesBatchOnce(self: Store, edges: []const graph_mod.Edge) !void {
        const old_meta = try self.readCurrentIndexMetaForAppend();
        var edge_records = std.ArrayList(EdgeIndexRecord).empty;
        defer edge_records.deinit(self.allocator);
        try edge_records.ensureTotalCapacity(self.allocator, edges.len);

        var next_meta = old_meta;
        const segment_delta_append = try self.canAppendEdgeBatchAsSegmentDelta(old_meta, edges);
        try self.validateEdgeBatchAppend(edges, old_meta, &edge_records, &next_meta, segment_delta_append);

        const rollback_event_bytes = try self.eventBytes();
        var published = false;
        errdefer if (!published) self.rollbackBatchAppend(rollback_event_bytes) catch {};

        try self.appendEdgeBatchRecords(edges, rollback_event_bytes);

        next_meta.event_bytes = try self.eventBytes();
        if (segment_delta_append) {
            next_meta.edge_indexed_edges = old_meta.edge_indexed_edges;
            next_meta.edge_index_digest = old_meta.edge_index_digest;
            try self.publishEdgeBatchSegmentIfManifestCurrent(old_meta, &next_meta, edge_records.items);
        } else {
            const id_result = try self.writeMergedEdgeIndexBatch(self.edge_by_id_path, .id, old_meta, edge_records.items, next_meta.edge_index_digest);
            const src_result = try self.writeMergedEdgeIndexBatch(self.edge_by_src_path, .src, old_meta, edge_records.items, next_meta.edge_index_digest);
            const dst_result = try self.writeMergedEdgeIndexBatch(self.edge_by_dst_path, .dst, old_meta, edge_records.items, next_meta.edge_index_digest);
            next_meta.edge_by_id_order_digest = id_result.order_digest;
            next_meta.edge_by_src_order_digest = src_result.order_digest;
            next_meta.edge_by_dst_order_digest = dst_result.order_digest;
            if (id_result.edge_id_runs) |edge_id_runs| {
                next_meta.edge_by_id_runs = edge_id_runs;
            } else {
                try self.copyEdgeOrderDigestsFromHeaders(&next_meta);
            }
            if (!try self.edgeSegmentMetaSummaryReadable(old_meta)) clearEdgeSegmentSummary(&next_meta);
            try self.publishEdgeBatchSegmentIfManifestCurrent(old_meta, &next_meta, edge_records.items);
        }
        try self.writeIndexMeta(next_meta);
        published = true;
        self.maintainEdgeSegmentsAfterCommittedAppend();
    }

    fn appendEdgeRecord(self: Store, edge: graph_mod.Edge) !void {
        var payload = std.ArrayList(u8).empty;
        defer payload.deinit(self.allocator);
        try appendU64(&payload, self.allocator, edge.id.toInt());
        try appendU64(&payload, self.allocator, edge.src.toInt());
        try appendU16(&payload, self.allocator, @intFromEnum(edge.rel));
        try appendU64(&payload, self.allocator, edge.dst.toInt());

        var record = std.ArrayList(u8).empty;
        defer record.deinit(self.allocator);
        try appendBinaryRecord(&record, self.allocator, .edge, payload.items);
        try self.appendRecord(record.items);
    }

    fn appendEdgeRecordAt(self: Store, edge: graph_mod.Edge, expected_offset: u64) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);
        if (try self.regularFileSize(file) != expected_offset) return error.InvalidRecord;

        var record: [binary_edge_record_len]u8 = undefined;
        encodeBinaryEdgeRecord(&record, edge);
        try file.writePositionalAll(self.io, &record, expected_offset);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn appendEdgeDeleteRecord(self: Store, edge_id: core.EdgeId) !void {
        var record: [binary_edge_delete_record_len]u8 = undefined;
        encodeBinaryEdgeDeleteRecord(&record, edge_id);
        try self.appendRecord(&record);
    }

    fn appendEdgeDeleteRecordsAt(self: Store, edge_ids: []const core.EdgeId, expected_offset: u64) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);
        if (try self.regularFileSize(file) != expected_offset) return error.InvalidRecord;

        var offset = expected_offset;
        var record: [binary_edge_delete_record_len]u8 = undefined;
        for (edge_ids) |edge_id| {
            encodeBinaryEdgeDeleteRecord(&record, edge_id);
            try file.writePositionalAll(self.io, &record, offset);
            offset = std.math.add(u64, offset, record.len) catch return error.InvalidRecord;
        }
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    pub fn ensureRawNodeTextsFile(self: Store) !void {
        var texts = try NodeTextsView.open(self);
        var texts_open = true;
        errdefer if (texts_open) texts.deinit();
        if (texts.format == .raw) {
            texts.deinit();
            texts_open = false;
            return;
        }
        const tmp_path = try self.tmpPathFor(self.node_texts_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, storage_write_buffer_bytes);
            defer writer.deinit();
            var buffer = try self.allocator.alloc(u8, storage_write_buffer_bytes);
            defer self.allocator.free(buffer);
            var offset: u64 = 0;
            while (offset < texts.size) {
                const remaining = texts.size - offset;
                const want = @min(buffer.len, std.math.cast(usize, remaining) orelse buffer.len);
                try texts.readInto(offset, buffer[0..want]);
                try writer.append(buffer[0..want]);
                offset = std.math.add(u64, offset, want) catch return error.RecordTooLarge;
            }
            try writer.flush();
            if (try self.regularFileSize(file) != texts.size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        texts.deinit();
        texts_open = false;
        try self.renameReplace(tmp_path, self.node_texts_path);
    }

    pub fn compressNodeTextsFileIfSmaller(self: Store) !void {
        _ = try self.finalizePrimaryTextStorageWithPolicy(.only_if_smaller);
    }

    pub fn compressNodeTextsFileIfSmallerWithResult(self: Store) !NodeTextsCompressionResult {
        return try self.finalizePrimaryTextStorageWithPolicy(.only_if_smaller);
    }

    pub fn finalizePrimaryTextStorage(self: Store) !void {
        _ = try self.finalizePrimaryTextStorageWithResult();
    }

    pub fn finalizePrimaryTextStorageWithResult(self: Store) !NodeTextsCompressionResult {
        return try self.finalizePrimaryTextStorageWithPolicy(.always);
    }

    /// Logical uncompressed byte length of the canonical node-text stream.
    /// Status and search admission paths use this without inflating the file.
    pub fn primaryNodeTextLogicalBytes(self: Store) !u64 {
        var view = try NodeTextsView.open(self);
        defer view.deinit();
        return view.size;
    }

    const PrimaryTextFinalizePolicy = enum {
        always,
        only_if_smaller,
    };

    fn finalizePrimaryTextStorageWithPolicy(self: Store, policy: PrimaryTextFinalizePolicy) !NodeTextsCompressionResult {
        const raw_size = try self.fileSizeOrZero(self.node_texts_path);
        if (raw_size == 0) return .{};

        const tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.deflate.tmp", .{self.node_texts_path});
        defer self.allocator.free(tmp_path);
        const table_tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.deflate.table.tmp", .{self.node_texts_path});
        defer self.allocator.free(table_tmp_path);

        var existing = try NodeTextsView.open(self);
        if (existing.format != .raw) {
            const logical_size = existing.size;
            existing.deinit();
            // The primary file is already committed. Stale checkpoint cleanup
            // must not turn an idempotent finalize into a false failure.
            self.removePrimaryTextFinalizeCheckpoints(tmp_path, table_tmp_path);
            return .{
                .before_bytes = raw_size,
                .after_bytes = raw_size,
                .logical_bytes = logical_size,
            };
        }
        existing.deinit();

        var input_file = try std.Io.Dir.cwd().openFile(self.io, self.node_texts_path, .{});
        var input_file_open = true;
        defer if (input_file_open) input_file.close(self.io);
        var output_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = false,
        });
        var output_file_open = true;
        defer if (output_file_open) output_file.close(self.io);
        var table_file = try std.Io.Dir.cwd().createFile(self.io, table_tmp_path, .{
            .read = true,
            .truncate = false,
        });
        var table_file_open = true;
        defer if (table_file_open) table_file.close(self.io);

        const pending_header = NodeTextsBlockDeflateHeader{ .logical_size = raw_size };
        const block_count = try pending_header.blockCount();
        const table_bytes = std.math.mul(u64, block_count, node_texts_block_deflate_entry_len) catch return error.RecordTooLarge;
        const payload_offset: u64 = node_texts_block_deflate_header_len;
        var input = try self.allocator.alloc(u8, node_texts_block_deflate_block_bytes);
        defer self.allocator.free(input);
        const compressed = try self.allocator.alloc(u8, @as(usize, node_texts_block_deflate_block_bytes) * 2 + 1024);
        defer self.allocator.free(compressed);
        const flate_buffer = try self.allocator.alloc(u8, std.compress.flate.max_window_len);
        defer self.allocator.free(flate_buffer);

        // The sidecar contains stored length + raw block hash for each committed
        // full logical block. Payload is synced before its entry, so an
        // interrupted finalize resumes by validating the source prefix and
        // truncating any uncommitted payload suffix.
        var table_size = try self.regularFileSize(table_file);
        if (table_size % node_texts_deflate_progress_entry_len != 0) {
            table_size -= table_size % node_texts_deflate_progress_entry_len;
            try table_file.setLength(self.io, table_size);
        }
        const full_block_count = raw_size / node_texts_block_deflate_block_bytes;
        var completed_blocks = table_size / node_texts_deflate_progress_entry_len;
        if (completed_blocks > full_block_count) {
            completed_blocks = 0;
            table_size = 0;
            try table_file.setLength(self.io, 0);
            try output_file.setLength(self.io, payload_offset);
        }

        var payload_cursor = payload_offset;
        const progress_scan_entries: usize = 4096;
        var table_scan: [progress_scan_entries * node_texts_deflate_progress_entry_len]u8 = undefined;
        var table_scan_offset: u64 = 0;
        var resume_block_index: u64 = 0;
        var resume_valid = true;
        while (table_scan_offset < table_size) {
            const want: usize = @intCast(@min(@as(u64, table_scan.len), table_size - table_scan_offset));
            const n = try table_file.readPositionalAll(self.io, table_scan[0..want], table_scan_offset);
            if (n != want) return error.InvalidRecord;
            var pos: usize = 0;
            while (pos < want) : (pos += node_texts_deflate_progress_entry_len) {
                const stored_len = readU32(table_scan[pos..][0..node_texts_block_deflate_entry_len]);
                if (stored_len == 0 or stored_len > node_texts_block_deflate_block_bytes) {
                    resume_valid = false;
                    break;
                }
                const raw_hash = readU64(table_scan[pos + node_texts_block_deflate_entry_len ..][0..8]);
                const stored_hash = readU64(table_scan[pos + node_texts_block_deflate_entry_len + 8 ..][0..8]);
                const raw_offset = std.math.mul(u64, resume_block_index, node_texts_block_deflate_block_bytes) catch return error.RecordTooLarge;
                const raw_n = try input_file.readPositionalAll(self.io, input, raw_offset);
                if (raw_n != input.len or std.hash.Wyhash.hash(node_texts_deflate_progress_hash_seed, input) != raw_hash) {
                    resume_valid = false;
                    break;
                }
                const stored_n = try output_file.readPositionalAll(self.io, compressed[0..stored_len], payload_cursor);
                if (stored_n != stored_len or std.hash.Wyhash.hash(node_texts_deflate_progress_hash_seed, compressed[0..stored_len]) != stored_hash) {
                    resume_valid = false;
                    break;
                }
                payload_cursor = std.math.add(u64, payload_cursor, stored_len) catch return error.RecordTooLarge;
                resume_block_index += 1;
            }
            if (!resume_valid) break;
            table_scan_offset += want;
        }
        const output_size = try self.regularFileSize(output_file);
        if (!resume_valid or output_size < payload_cursor) {
            completed_blocks = 0;
            table_size = 0;
            payload_cursor = payload_offset;
            try table_file.setLength(self.io, 0);
            try output_file.setLength(self.io, payload_offset);
        } else if (output_size != payload_cursor) {
            try output_file.setLength(self.io, payload_cursor);
        }

        var logical_offset = std.math.mul(u64, completed_blocks, node_texts_block_deflate_block_bytes) catch return error.RecordTooLarge;
        const full_logical_end = std.math.mul(u64, full_block_count, node_texts_block_deflate_block_bytes) catch return error.RecordTooLarge;
        const checkpoint_blocks: usize = 256;
        var checkpoint_entries: [checkpoint_blocks * node_texts_deflate_progress_entry_len]u8 = undefined;
        var checkpoint_len: usize = 0;
        while (logical_offset < full_logical_end) {
            const n = try input_file.readPositionalAll(self.io, input, logical_offset);
            if (n != input.len) return error.InvalidRecord;
            const compressed_len = deflateNodeTextsBlock(input, compressed, flate_buffer);
            const stored = if (compressed_len < input.len) compressed[0..compressed_len] else input;
            try output_file.writePositionalAll(self.io, stored, payload_cursor);
            writeU32(checkpoint_entries[checkpoint_len..][0..node_texts_block_deflate_entry_len], @intCast(stored.len));
            writeU64(checkpoint_entries[checkpoint_len + node_texts_block_deflate_entry_len ..][0..8], std.hash.Wyhash.hash(node_texts_deflate_progress_hash_seed, input));
            writeU64(checkpoint_entries[checkpoint_len + node_texts_block_deflate_entry_len + 8 ..][0..8], std.hash.Wyhash.hash(node_texts_deflate_progress_hash_seed, stored));
            checkpoint_len += node_texts_deflate_progress_entry_len;
            payload_cursor = std.math.add(u64, payload_cursor, stored.len) catch return error.RecordTooLarge;
            logical_offset = std.math.add(u64, logical_offset, input.len) catch return error.RecordTooLarge;

            if (checkpoint_len == checkpoint_entries.len or logical_offset == full_logical_end) {
                if (selfOptionsNeedSync(self)) try output_file.sync(self.io);
                try table_file.writePositionalAll(self.io, checkpoint_entries[0..checkpoint_len], table_size);
                table_size = std.math.add(u64, table_size, checkpoint_len) catch return error.RecordTooLarge;
                if (selfOptionsNeedSync(self)) try table_file.sync(self.io);
                checkpoint_len = 0;
            }
        }
        if (table_size != std.math.mul(u64, full_block_count, node_texts_deflate_progress_entry_len) catch return error.RecordTooLarge) return error.InvalidRecord;

        var partial_entry: [node_texts_block_deflate_entry_len]u8 = undefined;
        var partial_entry_len: usize = 0;
        if (logical_offset < raw_size) {
            const raw_len: usize = @intCast(raw_size - logical_offset);
            const n = try input_file.readPositionalAll(self.io, input[0..raw_len], logical_offset);
            if (n != raw_len) return error.InvalidRecord;
            const compressed_len = deflateNodeTextsBlock(input[0..raw_len], compressed, flate_buffer);
            const stored = if (compressed_len < raw_len) compressed[0..compressed_len] else input[0..raw_len];
            try output_file.writePositionalAll(self.io, stored, payload_cursor);
            writeU32(&partial_entry, @intCast(stored.len));
            partial_entry_len = partial_entry.len;
            payload_cursor = std.math.add(u64, payload_cursor, stored.len) catch return error.RecordTooLarge;
            logical_offset = raw_size;
        }
        if (logical_offset != raw_size or try self.regularFileSize(input_file) != raw_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try output_file.sync(self.io);

        const table_offset = payload_cursor;
        const final_size = std.math.add(u64, table_offset, table_bytes) catch return error.RecordTooLarge;
        table_scan_offset = 0;
        var table_write_offset = table_offset;
        var block_table_chunk: [progress_scan_entries * node_texts_block_deflate_entry_len]u8 = undefined;
        while (table_scan_offset < table_size) {
            const want: usize = @intCast(@min(@as(u64, table_scan.len), table_size - table_scan_offset));
            const n = try table_file.readPositionalAll(self.io, table_scan[0..want], table_scan_offset);
            if (n != want) return error.InvalidRecord;
            var progress_pos: usize = 0;
            var block_table_len: usize = 0;
            while (progress_pos < want) : (progress_pos += node_texts_deflate_progress_entry_len) {
                @memcpy(block_table_chunk[block_table_len..][0..node_texts_block_deflate_entry_len], table_scan[progress_pos..][0..node_texts_block_deflate_entry_len]);
                block_table_len += node_texts_block_deflate_entry_len;
            }
            try output_file.writePositionalAll(self.io, block_table_chunk[0..block_table_len], table_write_offset);
            table_scan_offset += want;
            table_write_offset += block_table_len;
        }
        if (partial_entry_len != 0) {
            try output_file.writePositionalAll(self.io, partial_entry[0..partial_entry_len], table_write_offset);
            table_write_offset += partial_entry_len;
        }
        if (table_write_offset != final_size) return error.InvalidRecord;
        try output_file.setLength(self.io, final_size);
        const header = NodeTextsBlockDeflateHeader{ .logical_size = raw_size };
        var header_bytes: [node_texts_block_deflate_header_len]u8 = undefined;
        try header.encode(&header_bytes);
        try output_file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try output_file.sync(self.io);
        output_file.close(self.io);
        output_file_open = false;
        table_file.close(self.io);
        table_file_open = false;
        input_file.close(self.io);
        input_file_open = false;
        if (policy == .only_if_smaller and final_size >= raw_size) {
            self.removePrimaryTextFinalizeCheckpoints(tmp_path, table_tmp_path);
            return .{
                .before_bytes = raw_size,
                .after_bytes = raw_size,
                .logical_bytes = raw_size,
            };
        }
        try self.renameReplace(tmp_path, self.node_texts_path);
        // renameReplace is the commit point. A stale resume sidecar is harmless
        // (future runs validate every checkpoint hash), so cleanup after the
        // commit cannot be allowed to report the committed operation as failed.
        self.removePrimaryTextFinalizeCheckpoints(tmp_path, table_tmp_path);
        return .{
            .compressed = true,
            .before_bytes = raw_size,
            .after_bytes = final_size,
            .logical_bytes = raw_size,
        };
    }

    fn removePrimaryTextFinalizeCheckpoints(self: Store, tmp_path: []const u8, table_tmp_path: []const u8) void {
        var removed = false;
        std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return,
        };
        removed = true;
        std.Io.Dir.cwd().deleteFile(self.io, table_tmp_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return,
        };
        if (removed) self.syncParentDirForPath(table_tmp_path) catch {};
    }

    fn deflateNodeTextsBlock(input: []const u8, output: []u8, flate_buffer: []u8) usize {
        var fixed: std.Io.Writer = .fixed(output);
        var compressor = std.compress.flate.Compress.init(&fixed, flate_buffer, .raw, node_texts_block_deflate_level) catch return input.len;
        compressor.writer.writeAll(input) catch return input.len;
        compressor.finish() catch return input.len;
        return fixed.buffered().len;
    }

    fn nodeTextsLogicalSize(self: Store) !u64 {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        return texts.size;
    }

    fn mutateRawNodeTextSlicesInPlace(
        self: Store,
        file: std.Io.File,
        start: u64,
        slices: []const []const u8,
        spans: []TextSpan,
    ) !u64 {
        if (slices.len != spans.len) return error.InvalidRecord;
        var writer = try StorageBufferedWriter.initAtOffset(self.allocator, self.io, file, storage_write_buffer_bytes, start);
        defer writer.deinit();
        for (slices, spans) |text, *span| {
            if (text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
            const text_offset = try writer.position();
            if (text.len != 0) try writer.append(text);
            span.* = .{ .offset = text_offset, .len = @intCast(text.len) };
        }
        try writer.flush();
        const end = try writer.position();
        if (try self.regularFileSize(file) != end) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        return end;
    }

    fn appendRawNodeTextSlices(self: Store, slices: []const []const u8) ![]TextSpan {
        const spans = try self.allocator.alloc(TextSpan, slices.len);
        errdefer self.allocator.free(spans);
        try self.ensureRawNodeTextsFile();
        var texts_file = try std.Io.Dir.cwd().createFile(self.io, self.node_texts_path, .{
            .read = true,
            .truncate = false,
        });
        var texts_file_open = true;
        defer if (texts_file_open) texts_file.close(self.io);
        const texts_start = try self.regularFileSize(texts_file);
        var append_bytes: u64 = 0;
        for (slices) |text| {
            if (text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
            append_bytes = std.math.add(u64, append_bytes, text.len) catch return error.RecordTooLarge;
        }

        var append_journal_active = false;
        if (append_bytes != 0 and selfOptionsNeedSync(self)) {
            try self.writeRawNodeTextsAppendJournal(texts_start);
            append_journal_active = true;
        }
        const texts_end = self.mutateRawNodeTextSlicesInPlace(texts_file, texts_start, slices, spans) catch |operation_err| {
            if (append_journal_active) {
                _ = self.recoverNodeTextsAppendJournal() catch |recovery_err| return recovery_err;
                append_journal_active = false;
            }
            return operation_err;
        };
        if (append_journal_active) {
            try self.commitNodeTextsAppendJournalAfterMutation();
            append_journal_active = false;
        }
        if (texts_start == 0 and texts_end != 0 and self.options.primary_text_write_mode == .normal) {
            texts_file.close(self.io);
            texts_file_open = false;
            try self.finalizePrimaryTextStorage();
        }
        return spans;
    }

    fn appendNodeTextBytes(self: Store, text: []const u8) !TextSpan {
        if (text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        {
            var texts = try NodeTextsView.open(self);
            defer texts.deinit();
            if (texts.format == .block_deflate) {
                var one = [_][]const u8{text};
                const spans = try self.appendCompressedNodeTextSlices(&texts, &one);
                defer self.allocator.free(spans);
                return spans[0];
            }
        }
        var one = [_][]const u8{text};
        const spans = try self.appendRawNodeTextSlices(&one);
        defer self.allocator.free(spans);
        return spans[0];
    }

    fn appendNodeTextsBatch(self: Store, nodes: []const graph_mod.Node) ![]TextSpan {
        {
            var texts = try NodeTextsView.open(self);
            defer texts.deinit();
            if (texts.format == .block_deflate) {
                const spans = try self.allocator.alloc(TextSpan, nodes.len);
                errdefer self.allocator.free(spans);
                var unique_slices = std.ArrayList([]const u8).empty;
                defer unique_slices.deinit(self.allocator);
                var ordinals = try self.allocator.alloc(usize, nodes.len);
                defer self.allocator.free(ordinals);
                var intern = std.StringHashMap(usize).init(self.allocator);
                defer intern.deinit();
                try unique_slices.ensureTotalCapacity(self.allocator, @min(nodes.len, 8192));
                try intern.ensureTotalCapacity(@intCast(@min(nodes.len, 8192)));
                for (nodes, 0..) |node, index| {
                    if (node.text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
                    if (intern.get(node.text)) |ordinal| {
                        ordinals[index] = ordinal;
                        continue;
                    }
                    const ordinal = unique_slices.items.len;
                    try unique_slices.append(self.allocator, node.text);
                    try intern.put(node.text, ordinal);
                    ordinals[index] = ordinal;
                }
                const unique_spans = try self.appendCompressedNodeTextSlices(&texts, unique_slices.items);
                defer self.allocator.free(unique_spans);
                for (ordinals, 0..) |ordinal, index| spans[index] = unique_spans[ordinal];
                return spans;
            }
        }

        const slices = try self.allocator.alloc([]const u8, nodes.len);
        defer self.allocator.free(slices);
        for (nodes, 0..) |node, index| slices[index] = node.text;
        return self.appendRawNodeTextSlices(slices);
    }

    fn reconcileNodeTextsBeforeAppend(self: Store) !void {
        const recovery = try self.recoverNodeTextsAppendJournal();
        if (recovery == .committed) try self.repairPersistentIndexesFromLog();
    }

    fn nodeTextsAppendJournalPath(self: Store, buffer: []u8) ![]const u8 {
        return try std.fmt.bufPrint(buffer, "{s}.append-journal", .{self.node_texts_path});
    }

    fn writeNodeTextsAppendJournal(self: Store, texts: *const NodeTextsView, suffix_offset: u64) !void {
        if (texts.format != .block_deflate or !selfOptionsNeedSync(self)) return error.InvalidRecord;
        const original_size = try self.regularFileSize(texts.file);
        if (suffix_offset < node_texts_block_deflate_header_len or suffix_offset > original_size) return error.InvalidRecord;
        const suffix_len_u64 = original_size - suffix_offset;
        const suffix_len = std.math.cast(usize, suffix_len_u64) orelse return error.RecordTooLarge;
        const suffix = try self.allocator.alloc(u8, suffix_len);
        defer self.allocator.free(suffix);
        const suffix_n = try texts.file.readPositionalAll(self.io, suffix, suffix_offset);
        if (suffix_n != suffix.len) return error.InvalidRecord;

        var original_header: [node_texts_block_deflate_header_len]u8 = undefined;
        const header_n = try texts.file.readPositionalAll(self.io, &original_header, 0);
        if (header_n != original_header.len) return error.InvalidRecord;
        _ = try NodeTextsBlockDeflateHeader.decode(&original_header);

        const journal_header = NodeTextsAppendJournalHeader{
            .original_size = original_size,
            .suffix_offset = suffix_offset,
            .suffix_len = suffix_len_u64,
            .suffix_hash = std.hash.Wyhash.hash(node_texts_append_journal_hash_seed, suffix),
            .original_header = original_header,
        };
        var journal_header_bytes: [node_texts_append_journal_header_len]u8 = undefined;
        try journal_header.encode(&journal_header_bytes);

        var journal_path_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const journal_path = try self.nodeTextsAppendJournalPath(&journal_path_buffer);
        const tmp_path = try self.tmpPathFor(journal_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var journal_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer journal_file.close(self.io);
            try journal_file.writePositionalAll(self.io, &journal_header_bytes, 0);
            if (suffix.len != 0) try journal_file.writePositionalAll(self.io, suffix, node_texts_append_journal_header_len);
            if (selfOptionsNeedSync(self)) try journal_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, journal_path);
    }

    fn writeRawNodeTextsAppendJournal(self: Store, original_size: u64) !void {
        if (!selfOptionsNeedSync(self)) return error.InvalidRecord;
        const journal_header = NodeTextsAppendJournalHeader{
            .original_size = original_size,
            .suffix_offset = original_size,
            .suffix_len = 0,
            .suffix_hash = std.hash.Wyhash.hash(node_texts_append_journal_hash_seed, &.{}),
            .original_header = @splat(0),
            .original_format = .raw,
        };
        var journal_header_bytes: [node_texts_append_journal_header_len]u8 = undefined;
        try journal_header.encode(&journal_header_bytes);

        var journal_path_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const journal_path = try self.nodeTextsAppendJournalPath(&journal_path_buffer);
        const tmp_path = try self.tmpPathFor(journal_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var journal_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer journal_file.close(self.io);
            try journal_file.writePositionalAll(self.io, &journal_header_bytes, 0);
            if (selfOptionsNeedSync(self)) try journal_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, journal_path);
    }

    fn cleanupNodeTextsAppendJournalAfterRecovery(self: Store, journal_path: []const u8) void {
        std.Io.Dir.cwd().deleteFile(self.io, journal_path) catch return;
        self.syncParentDirForPath(journal_path) catch {};
    }

    fn cleanupCommittedNodeTextsAppendJournal(self: Store) void {
        var journal_path_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const journal_path = self.nodeTextsAppendJournalPath(&journal_path_buffer) catch return;
        self.cleanupNodeTextsAppendJournalAfterRecovery(journal_path);
    }

    const NodeTextsAppendRecovery = enum {
        none,
        rolled_back,
        committed,
    };

    fn markNodeTextsAppendJournalCommitted(self: Store) !void {
        var journal_path_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const journal_path = try self.nodeTextsAppendJournalPath(&journal_path_buffer);
        var journal_file = try std.Io.Dir.cwd().openFile(self.io, journal_path, .{ .allow_directory = false });
        var journal_file_open = true;
        defer if (journal_file_open) journal_file.close(self.io);
        const journal_size = try self.regularFileSize(journal_file);
        const journal_len = std.math.cast(usize, journal_size) orelse return error.RecordTooLarge;
        if (journal_len < node_texts_append_journal_header_len) return error.InvalidRecord;
        const journal_bytes = try self.allocator.alloc(u8, journal_len);
        defer self.allocator.free(journal_bytes);
        const journal_n = try journal_file.readPositionalAll(self.io, journal_bytes, 0);
        if (journal_n != journal_bytes.len) return error.InvalidRecord;
        var header_bytes: [node_texts_append_journal_header_len]u8 = undefined;
        @memcpy(&header_bytes, journal_bytes[0..node_texts_append_journal_header_len]);
        var header = try NodeTextsAppendJournalHeader.decode(&header_bytes);
        if (journal_size != std.math.add(u64, node_texts_append_journal_header_len, header.suffix_len) catch return error.InvalidRecord) return error.InvalidRecord;
        if (header.committed) return;
        header.committed = true;
        try header.encode(&header_bytes);
        @memcpy(journal_bytes[0..node_texts_append_journal_header_len], &header_bytes);
        journal_file.close(self.io);
        journal_file_open = false;

        // Never overwrite the only durable undo header in place. A torn
        // committed-marker write would make both rollback and roll-forward
        // impossible. Publish a fully synced current-version (v3) journal
        // with atomic rename; if directory sync fails, recovery can still make
        // the visible rename durable by deleting the committed journal and
        // syncing the directory.
        const tmp_path = try self.tmpPathFor(journal_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var committed_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer committed_file.close(self.io);
            try committed_file.writePositionalAll(self.io, journal_bytes, 0);
            if (selfOptionsNeedSync(self)) try committed_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, journal_path);
    }

    fn commitNodeTextsAppendJournalAfterMutation(self: Store) !void {
        self.markNodeTextsAppendJournalCommitted() catch |commit_err| {
            const recovery = self.recoverNodeTextsAppendJournal() catch |recovery_err| return recovery_err;
            // The data mutation is the durable outcome once the committed
            // marker is visible. Keep that marker until the canonical event
            // is published; recovery will reconcile it if the caller fails.
            if (recovery != .committed) return commit_err;
        };
    }

    fn recoverNodeTextsAppendJournal(self: Store) !NodeTextsAppendRecovery {
        var journal_path_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const journal_path = try self.nodeTextsAppendJournalPath(&journal_path_buffer);
        if (!try self.fileExists(journal_path)) return .none;

        var journal_file = try std.Io.Dir.cwd().openFile(self.io, journal_path, .{});
        var journal_file_open = true;
        defer if (journal_file_open) journal_file.close(self.io);
        const journal_size = try self.regularFileSize(journal_file);
        if (journal_size < node_texts_append_journal_header_len) return error.InvalidRecord;
        var header_bytes: [node_texts_append_journal_header_len]u8 = undefined;
        const header_n = try journal_file.readPositionalAll(self.io, &header_bytes, 0);
        if (header_n != header_bytes.len) return error.InvalidRecord;
        const header = try NodeTextsAppendJournalHeader.decode(&header_bytes);
        if (journal_size != std.math.add(u64, node_texts_append_journal_header_len, header.suffix_len) catch return error.InvalidRecord) return error.InvalidRecord;

        switch (header.original_format) {
            .raw => {
                if (!allZero(&header.original_header)) return error.InvalidRecord;
                if (header.suffix_offset != header.original_size or header.suffix_len != 0) return error.InvalidRecord;
            },
            .block_deflate => {
                const original_header = try NodeTextsBlockDeflateHeader.decode(&header.original_header);
                const table_bytes = try original_header.tableBytes();
                if (header.suffix_offset < node_texts_block_deflate_header_len or header.suffix_offset > header.original_size) return error.InvalidRecord;
                if (header.suffix_len != header.original_size - header.suffix_offset) return error.InvalidRecord;
                if (header.suffix_len < table_bytes or header.suffix_len > table_bytes + node_texts_block_deflate_block_bytes) return error.InvalidRecord;
            },
        }

        const suffix_len = std.math.cast(usize, header.suffix_len) orelse return error.RecordTooLarge;
        const suffix = try self.allocator.alloc(u8, suffix_len);
        defer self.allocator.free(suffix);
        const suffix_n = try journal_file.readPositionalAll(self.io, suffix, node_texts_append_journal_header_len);
        if (suffix_n != suffix.len) return error.InvalidRecord;
        if (std.hash.Wyhash.hash(node_texts_append_journal_hash_seed, suffix) != header.suffix_hash) return error.InvalidRecord;
        journal_file.close(self.io);
        journal_file_open = false;

        // The data file was synced before this checksummed marker. Keep the
        // committed journal until the canonical event is durable. Store-open
        // recovery or an explicit index repair reconciles against events.bin
        // before deleting it, so a text-only append cannot become an orphan.
        if (header.committed) {
            try self.syncParentDirForPath(journal_path);
            return .committed;
        }

        var texts_file = try std.Io.Dir.cwd().openFile(self.io, self.node_texts_path, .{ .mode = .read_write, .allow_directory = false });
        defer texts_file.close(self.io);
        switch (header.original_format) {
            .raw => try texts_file.setLength(self.io, header.original_size),
            .block_deflate => {
                try texts_file.setLength(self.io, header.suffix_offset);
                if (suffix.len != 0) try texts_file.writePositionalAll(self.io, suffix, header.suffix_offset);
                try texts_file.writePositionalAll(self.io, &header.original_header, 0);
                try texts_file.setLength(self.io, header.original_size);
            },
        }
        if (selfOptionsNeedSync(self)) try texts_file.sync(self.io);
        // The rollback is durable now. A leftover undo journal is harmless and
        // idempotent, so cleanup failure must not block store open forever.
        self.cleanupNodeTextsAppendJournalAfterRecovery(journal_path);
        return .rolled_back;
    }

    fn appendCompressedNodeTextSlices(self: Store, texts: *const NodeTextsView, slices: []const []const u8) ![]TextSpan {
        if (texts.format != .block_deflate) return error.InvalidRecord;
        const spans = try self.allocator.alloc(TextSpan, slices.len);
        errdefer self.allocator.free(spans);

        var append_bytes: u64 = 0;
        for (slices, 0..) |text, index| {
            if (text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
            const offset = std.math.add(u64, texts.size, append_bytes) catch return error.RecordTooLarge;
            spans[index] = .{ .offset = offset, .len = @intCast(text.len) };
            append_bytes = std.math.add(u64, append_bytes, text.len) catch return error.RecordTooLarge;
        }
        if (append_bytes == 0) return spans;

        const old_block_count = texts.blocks.len;
        if (old_block_count == 0) return error.InvalidRecord;
        const old_last = texts.blocks[old_block_count - 1];
        const old_payload_end = std.math.add(u64, old_last.physical_offset, old_last.stored_len) catch return error.InvalidRecord;
        const last_has_room = old_last.raw_len < node_texts_block_deflate_block_bytes;
        const truncate_offset = if (last_has_room) old_last.physical_offset else old_payload_end;
        var append_journal_active = false;
        if (selfOptionsNeedSync(self)) {
            try self.writeNodeTextsAppendJournal(texts, truncate_offset);
            append_journal_active = true;
        }
        self.mutateCompressedNodeTextSlicesInPlace(texts, slices, append_bytes) catch |operation_err| {
            if (append_journal_active) {
                _ = self.recoverNodeTextsAppendJournal() catch |recovery_err| return recovery_err;
                append_journal_active = false;
            }
            return operation_err;
        };
        if (append_journal_active) {
            try self.commitNodeTextsAppendJournalAfterMutation();
            append_journal_active = false;
        }
        return spans;
    }

    fn mutateCompressedNodeTextSlicesInPlace(self: Store, texts: *const NodeTextsView, slices: []const []const u8, append_bytes: u64) !void {
        const old_block_count = texts.blocks.len;
        if (old_block_count == 0) return error.InvalidRecord;
        const old_last = texts.blocks[old_block_count - 1];
        const old_payload_end = std.math.add(u64, old_last.physical_offset, old_last.stored_len) catch return error.InvalidRecord;
        const last_has_room = old_last.raw_len < node_texts_block_deflate_block_bytes;
        const rewrite_from_block = if (last_has_room) old_block_count - 1 else old_block_count;
        const truncate_offset = if (last_has_room) old_last.physical_offset else old_payload_end;
        const new_logical_size = std.math.add(u64, texts.size, append_bytes) catch return error.RecordTooLarge;
        const new_header = NodeTextsBlockDeflateHeader{ .logical_size = new_logical_size };
        const new_block_count = try new_header.blockCount();
        const table_bytes = std.math.mul(u64, new_block_count, node_texts_block_deflate_entry_len) catch return error.RecordTooLarge;
        const table_len = std.math.cast(usize, table_bytes) orelse return error.RecordTooLarge;
        const block_table = try self.allocator.alloc(u8, table_len);
        defer self.allocator.free(block_table);

        var block_index: usize = 0;
        while (block_index < rewrite_from_block) : (block_index += 1) {
            var entry_bytes: [node_texts_block_deflate_entry_len]u8 = undefined;
            try texts.blocks[block_index].encode(&entry_bytes);
            const entry_offset = block_index * node_texts_block_deflate_entry_len;
            @memcpy(block_table[entry_offset..][0..node_texts_block_deflate_entry_len], &entry_bytes);
        }

        var pending = try self.allocator.alloc(u8, node_texts_block_deflate_block_bytes);
        defer self.allocator.free(pending);
        var pending_len: usize = 0;
        if (last_has_room) {
            pending_len = old_last.raw_len;
            const last_logical_offset = std.math.mul(u64, @intCast(old_block_count - 1), node_texts_block_deflate_block_bytes) catch return error.InvalidRecord;
            try texts.readInto(last_logical_offset, pending[0..pending_len]);
        }

        const compressed = try self.allocator.alloc(u8, @as(usize, node_texts_block_deflate_block_bytes) * 2 + 1024);
        defer self.allocator.free(compressed);
        const flate_buffer = try self.allocator.alloc(u8, std.compress.flate.max_window_len);
        defer self.allocator.free(flate_buffer);

        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_texts_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);
        try file.setLength(self.io, truncate_offset);
        var payload_cursor = truncate_offset;
        var output_block_index = rewrite_from_block;

        for (slices) |text| {
            var pos: usize = 0;
            while (pos < text.len) {
                const available = @as(usize, node_texts_block_deflate_block_bytes) - pending_len;
                const take = @min(available, text.len - pos);
                @memcpy(pending[pending_len..][0..take], text[pos..][0..take]);
                pending_len += take;
                pos += take;
                if (pending_len == node_texts_block_deflate_block_bytes) {
                    payload_cursor = try self.writeNodeTextsCompressedBlock(&file, pending[0..pending_len], payload_cursor, output_block_index, block_table, compressed, flate_buffer);
                    output_block_index += 1;
                    pending_len = 0;
                }
            }
        }
        if (pending_len != 0) {
            payload_cursor = try self.writeNodeTextsCompressedBlock(&file, pending[0..pending_len], payload_cursor, output_block_index, block_table, compressed, flate_buffer);
            output_block_index += 1;
        }
        if (output_block_index != new_block_count) return error.InvalidRecord;
        try file.writePositionalAll(self.io, block_table, payload_cursor);
        const final_size = std.math.add(u64, payload_cursor, table_bytes) catch return error.RecordTooLarge;
        try file.setLength(self.io, final_size);
        var header_bytes: [node_texts_block_deflate_header_len]u8 = undefined;
        try new_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn writeNodeTextsCompressedBlock(
        self: Store,
        file: *std.Io.File,
        raw: []const u8,
        payload_cursor: u64,
        block_index: usize,
        block_table: []u8,
        compressed: []u8,
        flate_buffer: []u8,
    ) !u64 {
        const compressed_len = deflateNodeTextsBlock(raw, compressed, flate_buffer);
        const use_compressed = compressed_len < raw.len;
        const stored = if (use_compressed) compressed[0..compressed_len] else raw;
        try file.writePositionalAll(self.io, stored, payload_cursor);
        const entry = NodeTextsBlockDeflateEntry{
            .physical_offset = payload_cursor,
            .stored_len = @intCast(stored.len),
            .raw_len = @intCast(raw.len),
            .flags = if (use_compressed) node_texts_block_deflate_flag_compressed else 0,
        };
        var entry_bytes: [node_texts_block_deflate_entry_len]u8 = undefined;
        try entry.encode(&entry_bytes);
        const entry_offset = block_index * node_texts_block_deflate_entry_len;
        @memcpy(block_table[entry_offset..][0..node_texts_block_deflate_entry_len], &entry_bytes);
        return std.math.add(u64, payload_cursor, stored.len) catch return error.RecordTooLarge;
    }

    fn appendNodeBatchRecords(self: Store, nodes: []const graph_mod.Node, text_spans: []const TextSpan, expected_offset: u64) !void {
        if (nodes.len != text_spans.len) return error.InvalidRecord;
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);
        if (try self.regularFileSize(file) != expected_offset) return error.InvalidRecord;

        var writer = try StorageBufferedWriter.initAtOffset(self.allocator, self.io, file, storage_write_buffer_bytes, expected_offset);
        defer writer.deinit();

        var marker_bytes: [BinaryRecordHeader.encoded_len]u8 = undefined;
        encodeBinaryRecordHeader(&marker_bytes, .batch_begin, 0, binaryPayloadChecksum(&.{}));
        try writer.append(&marker_bytes);

        var node_offset: usize = 0;
        while (node_offset < nodes.len) {
            const node_count = @min(nodes.len - node_offset, binary_node_batch_max_count);
            try appendBinaryNodeBatchRecordToWriter(
                &writer,
                self.allocator,
                nodes[node_offset..][0..node_count],
                text_spans[node_offset..][0..node_count],
            );
            node_offset += node_count;
        }

        encodeBinaryRecordHeader(&marker_bytes, .batch_commit, 0, binaryPayloadChecksum(&.{}));
        try writer.append(&marker_bytes);
        try writer.flush();
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn appendEdgeBatchRecords(self: Store, edges: []const graph_mod.Edge, expected_offset: u64) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);
        if (try self.regularFileSize(file) != expected_offset) return error.InvalidRecord;

        var writer = try StorageBufferedWriter.initAtOffset(self.allocator, self.io, file, storage_write_buffer_bytes, expected_offset);
        defer writer.deinit();

        var marker_bytes: [BinaryRecordHeader.encoded_len]u8 = undefined;
        encodeBinaryRecordHeader(&marker_bytes, .batch_begin, 0, binaryPayloadChecksum(&.{}));
        try writer.append(&marker_bytes);

        var edge_offset: usize = 0;
        while (edge_offset < edges.len) {
            const edge_count = @min(edges.len - edge_offset, binary_edge_batch_max_count);
            try appendBinaryEdgeBatchRecordToWriter(&writer, self.allocator, edges[edge_offset..][0..edge_count]);
            edge_offset += edge_count;
        }

        encodeBinaryRecordHeader(&marker_bytes, .batch_commit, 0, binaryPayloadChecksum(&.{}));
        try writer.append(&marker_bytes);
        try writer.flush();
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn appendBatchMarker(self: Store, kind: BinaryRecordKind) !void {
        switch (kind) {
            .batch_begin, .batch_commit => {},
            .node, .node_batch, .edge, .edge_batch, .edge_delete => return core.Error.Unsupported,
        }
        var record = std.ArrayList(u8).empty;
        defer record.deinit(self.allocator);
        try appendBinaryRecord(&record, self.allocator, kind, &.{});
        try self.appendRecord(record.items);
    }

    pub fn nextNodeId(self: Store) !core.NodeId {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{});
        defer file.close(self.io);
        const meta = try self.readCurrentIndexMetaForAppend();
        const header = try self.readNodeByIdHeaderFromFile(file);
        if (header.node_count != meta.nodes) return error.InvalidRecord;
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        if (header.max_node_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const growth_flags: u16 = if (header.hasDerivedTextOffset()) NodeByIdHeader.flag_uniform_kind else header.flags;
        const growth_record_len: u16 = if (header.hasDerivedTextOffset()) NodeByIdRecord.uniform_encoded_len else header.record_len;
        _ = try self.nodeByIdFileSizeForHeaderStore(.{
            .max_node_id = header.max_node_id + 1,
            .node_count = header.node_count,
            .node_digest = header.node_digest,
            .flags = growth_flags,
            .record_len = growth_record_len,
            .uniform_kind = header.uniform_kind,
        });
        return core.NodeId.fromInt(header.max_node_id + 1);
    }

    pub fn nodeIndexLayoutHint(self: Store) !?NodeIndexLayoutHint {
        var file = std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);

        const meta = try self.readCurrentIndexMetaForAppend();
        const header = try self.readNodeByIdHeaderFromFile(file);
        if (header.node_count != meta.nodes) return error.InvalidRecord;
        if (header.node_digest != meta.node_digest) return error.InvalidRecord;
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        const dense_node_id_base: u32 = if (header.node_count != 0 and header.node_count == header.max_node_id and header.max_node_id <= std.math.maxInt(u32))
            1
        else
            0;
        const uniform_kind = if (header.hasUniformKind())
            nodeKindFromInt(header.uniform_kind) orelse return error.InvalidRecord
        else
            null;
        return .{
            .node_count = header.node_count,
            .dense_node_id_base = dense_node_id_base,
            .uniform_kind = uniform_kind,
        };
    }

    pub fn searchableNodeIndexLayoutHint(self: Store) !?NodeIndexLayoutHint {
        const hint = (try self.nodeIndexLayoutHint()) orelse return null;
        if (hint.node_count == 0) return hint;
        const uniform_kind = hint.uniform_kind orelse return null;
        // Deleted-node tombstones are stored as edit nodes with reserved text.
        // A uniform non-edit catalog proves every active node is searchable
        // without scanning text; mixed or edit-only catalogs must be checked
        // by the caller because they may contain tombstones.
        if (uniform_kind == .edit) return null;
        return hint;
    }

    pub fn nextEdgeId(self: Store) !core.EdgeId {
        const meta = try self.readCurrentIndexMetaForAppend();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != .id or header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, .id)) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (header.edge_count != 0) {
            const last = try self.readEdgeIndexRecordAt(file, header, header.edge_count - 1);
            if (meta.max_edge_id_seen < last.edge_id) return error.InvalidRecord;
        }
        if (self.options.validate_indexes_on_read) {
            if (!try self.edgeIndexesValidatedAndMatchMeta(meta)) return error.InvalidRecord;
        }
        const max_edge_id = meta.max_edge_id_seen;
        if (max_edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        return core.EdgeId.fromInt(max_edge_id + 1);
    }

    fn readCurrentIndexMeta(self: Store) !IndexMeta {
        if (!self.options.validate_indexes_on_read and self.index_meta_cache.valid) {
            const meta = self.index_meta_cache.meta;
            if (meta.event_bytes == try self.eventBytes()) return meta;
            self.index_meta_cache.clear();
        }
        const meta = try self.readIndexMeta();
        if (meta.event_bytes != try self.eventBytes()) return error.InvalidRecord;
        if (!self.options.validate_indexes_on_read) {
            self.index_meta_cache.meta = meta;
            self.index_meta_cache.valid = true;
        }
        return meta;
    }

    fn readCurrentIndexMetaForAppend(self: Store) !IndexMeta {
        const meta = try self.readCurrentIndexMeta();
        if (!self.options.validate_indexes_on_read) return meta;
        const stats_out = try self.stats();
        if (meta.nodes != stats_out.nodes) return error.InvalidRecord;
        if (meta.edges != stats_out.edges) return error.InvalidRecord;
        if (meta.node_digest != stats_out.node_digest) return error.InvalidRecord;
        if (meta.edge_digest != stats_out.edge_digest) return error.InvalidRecord;
        return meta;
    }

    pub fn loadGraph(self: Store) !graph_mod.Graph {
        return self.loadGraphDeadline(.none);
    }

    /// Replay the canonical event log without publishing derived indexes,
    /// while honoring a caller-owned query deadline. Read-only recovery paths
    /// must not silently shed their time budget when a derived index is bad.
    pub fn loadGraphDeadline(self: Store, deadline: core.QueryDeadline) !graph_mod.Graph {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        var graph = graph_mod.Graph.init(self.allocator);
        errdefer graph.deinit();

        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        try self.replayBinaryEvents(&graph, file, deadline);
        return graph;
    }

    pub fn loadSnapshot(self: Store) !snapshot_mod.GraphSnapshot {
        const graph = try self.loadGraph();
        var snapshot = try snapshot_mod.GraphSnapshot.init(self.allocator, graph);
        errdefer snapshot.deinit();
        try self.ensurePersistentNodeIndexes(&snapshot.graph);
        try self.ensurePersistentEdgeIndexes(&snapshot.graph);

        const expected = try self.currentIndexMetaFromIndexes(&snapshot.graph);
        const current = self.readIndexMeta() catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => null,
            else => |e| return e,
        };
        if (current == null or !indexMetaEquals(current.?, expected)) {
            try self.writeIndexMeta(expected);
            _ = self.dropRedundantEdgeSegmentOverlayAfterBaseIndexCatchup() catch {};
        }
        return snapshot;
    }

    pub fn repairPersistentIndexesFromLog(self: Store) !void {
        var timings = PersistentRepairTimings{};
        try self.repairPersistentIndexesFromLogWithTimings(&timings);
    }

    pub fn repairPersistentIndexesFromLogWithTimings(self: Store, timings: *PersistentRepairTimings) !void {
        timings.* = .{};
        const node_text_recovery = try self.recoverNodeTextsAppendJournal();
        const truncate_start = storageMonotonicNs(self.io);
        _ = try self.truncateIncompleteBatchTail();
        timings.truncate_ns = storageElapsedNs(self.io, truncate_start);

        const rebuild_start = storageMonotonicNs(self.io);
        try self.rebuildPersistentIndexesFromLogStreamingWithTimings(timings);
        timings.rebuild_total_ns = storageElapsedNs(self.io, rebuild_start);

        const drop_start = storageMonotonicNs(self.io);
        _ = self.dropRedundantEdgeSegmentOverlayAfterBaseIndexCatchup() catch {};
        timings.drop_overlay_ns = storageElapsedNs(self.io, drop_start);
        if (node_text_recovery == .committed) {
            self.cleanupCommittedNodeTextsAppendJournal();
        }
    }

    pub fn validatePersistentIndexes(self: Store) !void {
        var timings = PersistentValidateTimings{};
        try self.validatePersistentIndexesWithTimings(&timings);
    }

    pub fn validatePersistentIndexesWithTimings(self: Store, timings: *PersistentValidateTimings) !void {
        timings.* = .{};
        const stats_start = storageMonotonicNs(self.io);
        const stats_out = try self.stats();
        timings.stats_ns = storageElapsedNs(self.io, stats_start);
        if (!try self.persistentIndexesCurrentWithTimings(stats_out, timings)) return error.InvalidRecord;
    }

    pub fn validatePersistentIndexFiles(self: Store) !void {
        if (!try self.fastPersistentIndexesCurrent()) return error.InvalidRecord;
    }

    fn refreshIndexesAfterCommittedAppend(self: Store, kind: BinaryRecordKind, node: ?graph_mod.Node, edge: ?graph_mod.Edge, node_text_span: ?TextSpan) bool {
        self.tryRefreshIndexesAfterCommittedAppend(kind, node, edge, node_text_span) catch {
            // The append log write already committed the event; surfacing
            // derived-index repair failure here would invite unsafe retries.
            // Report whether repair completed so node append can retain its
            // committed text journal when the indexes are still unusable.
            self.repairPersistentIndexesFromLog() catch return false;
        };
        return true;
    }

    fn tryRefreshIndexesAfterCommittedAppend(self: Store, kind: BinaryRecordKind, node: ?graph_mod.Node, edge: ?graph_mod.Edge, node_text_span: ?TextSpan) !void {
        switch (kind) {
            .node => try self.appendNodeIndexRecord(node.?, node_text_span orelse return error.InvalidRecord),
            .edge => try self.appendEdgeIndexRecord(edge.?),
            .edge_delete => return core.Error.Unsupported,
            .node_batch, .edge_batch, .batch_begin, .batch_commit => return core.Error.Unsupported,
        }
        const meta_start = if (kind == .node and self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.refreshIndexMetaAfterAppend(kind, node, edge);
        if (kind == .node) {
            if (self.node_append_timings) |timings| timings.meta_write_ns += storageElapsedNs(self.io, meta_start);
        }
    }

    fn maintainEdgeSegmentsAfterCommittedAppend(self: Store) void {
        const start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        defer if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.segment_maintenance_calls += 1;
            delta_stats.segment_maintenance_ns += storageElapsedNs(self.io, start);
        };
        _ = self.dropRedundantEdgeSegmentOverlayAfterBaseIndexCatchup() catch {};
        _ = self.autoCompactEdgeSegmentsIfNeeded() catch {};
    }

    fn invalidateEdgeSegmentCurrent(self: Store) !void {
        std.Io.Dir.cwd().deleteFile(self.io, self.edge_segment_current_path) catch |err| switch (err) {
            error.FileNotFound => return,
            else => |e| return e,
        };
        try self.syncParentDirForPath(self.edge_segment_current_path);
    }

    fn invalidateNodeTextRunCurrent(self: Store) !void {
        std.Io.Dir.cwd().deleteFile(self.io, self.node_text_run_current_path) catch |err| switch (err) {
            error.FileNotFound => return,
            else => |e| return e,
        };
        try self.syncParentDirForPath(self.node_text_run_current_path);
    }

    pub fn hasCatalog(self: Store) !bool {
        return self.fileExists(self.catalog_path);
    }

    pub fn readCatalog(self: Store) !?catalog_mod.Catalog {
        var file = std.Io.Dir.cwd().openFile(self.io, self.catalog_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);
        const stat = try file.stat(self.io);
        const size: usize = @intCast(stat.size);
        if (size > catalog_max_bytes) return error.InvalidRecord;
        const bytes = try self.allocator.alloc(u8, size);
        defer self.allocator.free(bytes);
        const read = try file.readPositionalAll(self.io, bytes, 0);
        if (read != bytes.len) return error.InvalidRecord;
        return try catalog_mod.decodeCatalog(self.allocator, bytes);
    }

    pub fn writeCatalog(self: Store, cat: catalog_mod.Catalog) !void {
        const encoded = try catalog_mod.encodeCatalog(self.allocator, cat);
        defer self.allocator.free(encoded);
        const tmp_path = try self.tmpPathFor(self.catalog_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            try file.writePositionalAll(self.io, encoded, 0);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.catalog_path);
    }

    pub fn writeKernelCatalog(self: Store) !void {
        var arena = std.heap.ArenaAllocator.init(self.allocator);
        defer arena.deinit();
        const cat = try catalog_mod.Catalog.kernelOnly(arena.allocator());
        try self.writeCatalog(cat);
    }

    pub fn stats(self: Store) !StoreStats {
        var state = EventCountState.init(self.allocator);
        defer state.deinit();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        try self.countBinaryEvents(file, &state);
        return state.stats;
    }

    /// Count canonical node records without materializing ids, edges, or
    /// node text. Returning `max_nodes + 1` is a deliberate saturation signal
    /// so admission paths can reject a large log immediately.
    pub fn nodeEventCountUpTo(self: Store, max_nodes: u64) !u64 {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        var offset: u64 = 0;
        var count: u64 = 0;
        var in_batch = false;
        while (true) {
            const parsed = try self.readBinaryRecordHeader(file, &offset) orelse break;
            try ensureBinaryPayloadFits(file_size, offset, parsed.payload_len);
            var prefix: [max_binary_count_payload_prefix_len]u8 = undefined;
            var prefix_len: usize = 0;
            try self.readBinaryPayloadPrefixAndValidateChecksum(file, offset, parsed, &prefix, &prefix_len);
            try advanceBinaryOffset(&offset, parsed.payload_len);
            const added: u64 = switch (parsed.kind) {
                .batch_begin => blk: {
                    if (in_batch or parsed.payload_len != 0) return error.InvalidRecord;
                    in_batch = true;
                    break :blk 0;
                },
                .batch_commit => blk: {
                    if (!in_batch or parsed.payload_len != 0) return error.InvalidRecord;
                    in_batch = false;
                    break :blk 0;
                },
                .node => blk: {
                    _ = try validateBinaryNodePayloadForCount(prefix[0..prefix_len], parsed.payload_len);
                    break :blk 1;
                },
                .node_batch => blk: {
                    if (!in_batch) return error.InvalidRecord;
                    break :blk try binaryNodeBatchCountFromPrefix(prefix[0..prefix_len], parsed.payload_len);
                },
                .edge, .edge_batch, .edge_delete => 0,
            };
            count = std.math.add(u64, count, added) catch return error.RecordTooLarge;
            if (count > max_nodes) return std.math.add(u64, max_nodes, 1) catch return error.RecordTooLarge;
            if (offset == file_size and in_batch) return error.InvalidRecord;
        }
        if (in_batch) return error.InvalidRecord;
        return count;
    }

    fn fileExists(self: Store, path: []const u8) !bool {
        var file = std.Io.Dir.cwd().openFile(self.io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            error.NotDir => return false,
            error.IsDir => return false,
            else => |e| return e,
        };
        defer file.close(self.io);
        return (try file.stat(self.io)).kind == .file;
    }

    fn pathExists(self: Store, path: []const u8) !bool {
        var file = std.Io.Dir.cwd().openFile(self.io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            error.NotDir => return false,
            error.IsDir => return true,
            else => |e| return e,
        };
        defer file.close(self.io);
        return true;
    }

    fn anyDerivedGraphCatalogPathExists(self: Store) !bool {
        inline for (&.{
            self.index_meta_path,
            self.node_by_id_path,
            self.node_texts_path,
            self.node_by_text_path,
            self.node_by_text_delta_path,
            self.external_key_index_path,
            self.node_props_index_path,
            self.node_props_values_path,
            self.node_props_overlay_index_path,
            self.node_props_overlay_values_path,
            self.edge_props_overlay_index_path,
            self.edge_props_overlay_values_path,
            self.property_payload_index_path,
            self.property_payload_values_path,
            self.property_payload_delta_path,
            self.edge_external_key_index_path,
            self.node_text_run_manifest_path,
            self.node_text_run_current_path,
            self.edge_by_id_path,
            self.edge_by_src_path,
            self.edge_by_dst_path,
            self.edge_tombstones_path,
            self.catalog_path,
        }) |path| {
            if (try self.pathExists(path)) return true;
        }
        var node_text_journal_buffer: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const node_text_journal_path = try self.nodeTextsAppendJournalPath(&node_text_journal_buffer);
        if (try self.pathExists(node_text_journal_path)) return true;
        const node_text_journal_tmp_path = try self.tmpPathFor(node_text_journal_path);
        defer self.allocator.free(node_text_journal_tmp_path);
        if (try self.pathExists(node_text_journal_tmp_path)) return true;
        const primary_text_tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.deflate.tmp", .{self.node_texts_path});
        defer self.allocator.free(primary_text_tmp_path);
        if (try self.pathExists(primary_text_tmp_path)) return true;
        const primary_text_table_tmp_path = try std.fmt.allocPrint(self.allocator, "{s}.deflate.table.tmp", .{self.node_texts_path});
        defer self.allocator.free(primary_text_table_tmp_path);
        if (try self.pathExists(primary_text_table_tmp_path)) return true;
        return false;
    }

    fn ensureStoreMarkerExists(self: Store) !void {
        if (try self.fileExists(self.events_bin_path)) return;
        return error.FileNotFound;
    }

    fn replayBinaryEvents(self: Store, graph: *graph_mod.Graph, file: std.Io.File, deadline: core.QueryDeadline) !void {
        var offset: u64 = 0;
        const file_size = try self.regularFileSize(file);
        var texts: ?NodeTextsView = null;
        defer if (texts) |*view| view.deinit();
        var in_batch = false;
        while (true) {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const parsed = try self.readBinaryRecordHeader(file, &offset) orelse break;
            try ensureBinaryPayloadFits(file_size, offset, parsed.payload_len);
            const payload = try self.allocator.alloc(u8, parsed.payload_len);
            defer self.allocator.free(payload);
            const payload_len = try file.readPositionalAll(self.io, payload, offset);
            if (payload_len != payload.len) return error.InvalidRecord;
            try advanceBinaryOffset(&offset, payload.len);
            try validateBinaryChecksum(parsed, payload);
            switch (parsed.kind) {
                .batch_begin => {
                    if (in_batch) return error.InvalidRecord;
                    if (payload.len != 0) return error.InvalidRecord;
                    in_batch = true;
                },
                .batch_commit => {
                    if (!in_batch) return error.InvalidRecord;
                    if (payload.len != 0) return error.InvalidRecord;
                    in_batch = false;
                },
                .node => {
                    const parsed_node = try validateBinaryNodePayload(payload);
                    if (texts == null) texts = try NodeTextsView.open(self);
                    const text = try texts.?.readTextAlloc(self.allocator, parsed_node.text_offset, parsed_node.text_len);
                    defer self.allocator.free(text);
                    graph.addNodeWithId(core.NodeId.fromInt(parsed_node.id), parsed_node.kind, text) catch |err| switch (err) {
                        core.Error.InvalidId => return error.InvalidRecord,
                        else => |e| return e,
                    };
                },
                .node_batch => {
                    if (!in_batch) return error.InvalidRecord;
                    var batch_reader = try BinaryNodeBatchReader.init(payload);
                    while (try batch_reader.next()) |parsed_node| {
                        if (deadline.expired()) return core.Error.BudgetExceeded;
                        {
                            if (texts == null) texts = try NodeTextsView.open(self);
                            const text = try texts.?.readTextAlloc(self.allocator, parsed_node.text_offset, parsed_node.text_len);
                            defer self.allocator.free(text);
                            graph.addNodeWithId(core.NodeId.fromInt(parsed_node.id), parsed_node.kind, text) catch |err| switch (err) {
                                core.Error.InvalidId => return error.InvalidRecord,
                                else => |e| return e,
                            };
                        }
                    }
                },
                .edge, .edge_delete => try replayBinaryRecord(graph, parsed.kind, payload, deadline),
                .edge_batch => {
                    if (!in_batch) return error.InvalidRecord;
                    try replayBinaryRecord(graph, parsed.kind, payload, deadline);
                },
            }
            if (deadline.expired()) return core.Error.BudgetExceeded;
        }
        if (in_batch) return error.InvalidRecord;
        if (deadline.expired()) return core.Error.BudgetExceeded;
    }

    fn countBinaryEvents(self: Store, file: std.Io.File, state: *EventCountState) !void {
        var offset: u64 = 0;
        const file_size = try self.regularFileSize(file);
        var texts: ?NodeTextsView = null;
        defer if (texts) |*view| view.deinit();
        var in_batch = false;
        while (true) {
            const parsed = try self.readBinaryRecordHeader(file, &offset) orelse return;
            try ensureBinaryPayloadFits(file_size, offset, parsed.payload_len);
            const payload_offset = offset;
            if (parsed.kind == .node_batch) {
                const payload = try self.readBinaryPayloadAllocAndValidateChecksum(file, offset, parsed);
                defer self.allocator.free(payload);
                try advanceBinaryOffset(&offset, payload.len);
                if (!in_batch) return error.InvalidRecord;
                if (texts == null) texts = try NodeTextsView.open(self);
                var batch_reader = try BinaryNodeBatchReader.init(payload);
                while (try batch_reader.next()) |node| {
                    try state.addNode(node.id, try texts.?.digestStoredNode(node.id, node.kind, node.text_offset, node.text_len));
                }
                if (offset == file_size and in_batch) return error.InvalidRecord;
                continue;
            }
            if (parsed.kind == .edge_batch) {
                const payload = try self.readBinaryPayloadAllocAndValidateChecksum(file, offset, parsed);
                defer self.allocator.free(payload);
                try advanceBinaryOffset(&offset, payload.len);
                if (!in_batch) return error.InvalidRecord;
                const batch = try validateBinaryEdgeBatchHeader(payload);
                var index: u32 = 0;
                while (index < batch.count) : (index += 1) {
                    const edge = try validateBinaryEdgeBatchEdge(payload, batch, index);
                    try state.addEdge(edge.id, edge.src, @intFromEnum(edge.rel), edge.dst);
                }
                if (offset == file_size and in_batch) return error.InvalidRecord;
                continue;
            }
            var prefix: [max_binary_count_payload_prefix_len]u8 = undefined;
            var prefix_len: usize = 0;
            try self.readBinaryPayloadPrefixAndValidateChecksum(file, offset, parsed, &prefix, &prefix_len);
            try advanceBinaryOffset(&offset, parsed.payload_len);
            switch (parsed.kind) {
                .batch_begin => {
                    if (in_batch) return error.InvalidRecord;
                    if (parsed.payload_len != 0) return error.InvalidRecord;
                    in_batch = true;
                },
                .batch_commit => {
                    if (!in_batch) return error.InvalidRecord;
                    if (parsed.payload_len != 0) return error.InvalidRecord;
                    in_batch = false;
                },
                .node => {
                    const node = try validateBinaryNodePayloadForCount(prefix[0..prefix_len], parsed.payload_len);
                    _ = payload_offset;
                    if (texts == null) texts = try NodeTextsView.open(self);
                    try state.addNode(node.id, try texts.?.digestStoredNode(node.id, node.kind, node.text_offset, node.text_len));
                },
                .node_batch => unreachable,
                .edge => {
                    if (prefix_len != binary_edge_payload_len) return error.InvalidRecord;
                    const edge = try validateBinaryEdgePayload(prefix[0..binary_edge_payload_len]);
                    try state.addEdge(edge.id, edge.src, @intFromEnum(edge.rel), edge.dst);
                },
                .edge_delete => {
                    if (prefix_len != binary_edge_delete_payload_len) return error.InvalidRecord;
                    const edge_id = try validateBinaryEdgeDeletePayload(prefix[0..binary_edge_delete_payload_len]);
                    try state.deleteEdge(edge_id.toInt());
                },
                .edge_batch => unreachable,
            }
            if (offset == file_size and in_batch) return error.InvalidRecord;
        }
    }

    fn maxEdgeIdEverSeenInLog(self: Store) !u64 {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        var offset: u64 = 0;
        const file_size = try self.regularFileSize(file);
        var max_edge_id: u64 = 0;
        var in_batch = false;
        while (true) {
            const parsed = try self.readBinaryRecordHeader(file, &offset) orelse break;
            try ensureBinaryPayloadFits(file_size, offset, parsed.payload_len);
            if (parsed.kind == .node_batch) {
                const payload = try self.readBinaryPayloadAllocAndValidateChecksum(file, offset, parsed);
                defer self.allocator.free(payload);
                try advanceBinaryOffset(&offset, payload.len);
                if (!in_batch) return error.InvalidRecord;
                try validateBinaryNodeBatchPayload(payload);
                continue;
            }
            if (parsed.kind == .edge_batch) {
                const payload = try self.readBinaryPayloadAllocAndValidateChecksum(file, offset, parsed);
                defer self.allocator.free(payload);
                try advanceBinaryOffset(&offset, payload.len);
                if (!in_batch) return error.InvalidRecord;
                const batch = try validateBinaryEdgeBatchHeader(payload);
                var index: u32 = 0;
                while (index < batch.count) : (index += 1) {
                    const edge = try validateBinaryEdgeBatchEdge(payload, batch, index);
                    max_edge_id = @max(max_edge_id, edge.id);
                }
                continue;
            }
            var prefix: [max_binary_count_payload_prefix_len]u8 = undefined;
            var prefix_len: usize = 0;
            try self.readBinaryPayloadPrefixAndValidateChecksum(file, offset, parsed, &prefix, &prefix_len);
            try advanceBinaryOffset(&offset, parsed.payload_len);
            switch (parsed.kind) {
                .batch_begin => {
                    if (in_batch or parsed.payload_len != 0) return error.InvalidRecord;
                    in_batch = true;
                },
                .batch_commit => {
                    if (!in_batch or parsed.payload_len != 0) return error.InvalidRecord;
                    in_batch = false;
                },
                .node => {},
                .node_batch => unreachable,
                .edge => {
                    if (prefix_len != binary_edge_payload_len) return error.InvalidRecord;
                    const edge = try validateBinaryEdgePayload(prefix[0..binary_edge_payload_len]);
                    max_edge_id = @max(max_edge_id, edge.id);
                },
                .edge_delete => {
                    if (prefix_len != binary_edge_delete_payload_len) return error.InvalidRecord;
                    const edge_id = (try validateBinaryEdgeDeletePayload(prefix[0..binary_edge_delete_payload_len])).toInt();
                    max_edge_id = @max(max_edge_id, edge_id);
                },
                .edge_batch => unreachable,
            }
        }
        if (in_batch) return error.InvalidRecord;
        return max_edge_id;
    }

    fn regularFileSize(self: Store, file: std.Io.File) !u64 {
        const stat = try file.stat(self.io);
        if (stat.kind != .file) return error.IsDir;
        return stat.size;
    }

    fn readBinaryRecordHeader(self: Store, file: std.Io.File, offset: *u64) !?BinaryRecordHeader {
        var bytes: [BinaryRecordHeader.encoded_len]u8 = undefined;
        const header_len = try file.readPositionalAll(self.io, &bytes, offset.*);
        if (header_len == 0) return null;
        if (header_len != bytes.len) return error.InvalidRecord;
        try advanceBinaryOffset(offset, bytes.len);
        const header = try BinaryRecordHeader.decode(&bytes);
        return header;
    }

    fn advanceBinaryOffset(offset: *u64, amount: usize) !void {
        offset.* = std.math.add(u64, offset.*, amount) catch return error.InvalidRecord;
    }

    fn readBinaryPayloadPrefixAndValidateChecksum(
        self: Store,
        file: std.Io.File,
        payload_offset: u64,
        header: BinaryRecordHeader,
        prefix: *[max_binary_count_payload_prefix_len]u8,
        prefix_len: *usize,
    ) !void {
        var hasher = std.hash.Wyhash.init(0);
        var remaining: usize = header.payload_len;
        var offset = payload_offset;
        prefix_len.* = 0;
        var buffer: [binary_count_read_chunk_len]u8 = undefined;
        while (remaining != 0) {
            const chunk_len = @min(buffer.len, remaining);
            const chunk = buffer[0..chunk_len];
            const read_len = try file.readPositionalAll(self.io, chunk, offset);
            if (read_len != chunk.len) return error.InvalidRecord;
            hasher.update(chunk);
            if (prefix_len.* < prefix.len) {
                const copy_len = @min(chunk.len, prefix.len - prefix_len.*);
                @memcpy(prefix[prefix_len.* .. prefix_len.* + copy_len], chunk[0..copy_len]);
                prefix_len.* += copy_len;
            }
            try advanceBinaryOffset(&offset, chunk.len);
            remaining -= chunk.len;
        }
        try validateBinaryChecksumValue(header, hasher.final());
    }

    fn readBinaryPayloadAllocAndValidateChecksum(self: Store, file: std.Io.File, payload_offset: u64, header: BinaryRecordHeader) ![]u8 {
        const payload = try self.allocator.alloc(u8, header.payload_len);
        errdefer self.allocator.free(payload);
        const read_len = try file.readPositionalAll(self.io, payload, payload_offset);
        if (read_len != payload.len) return error.InvalidRecord;
        try validateBinaryChecksum(header, payload);
        return payload;
    }

    fn binaryPayloadDigest(self: Store, file: std.Io.File, payload_offset: u64, payload_len: u32) !u64 {
        var hasher = std.hash.Wyhash.init(0);
        var remaining: usize = payload_len;
        var offset = payload_offset;
        var buffer: [binary_count_read_chunk_len]u8 = undefined;
        while (remaining != 0) {
            const chunk_len = @min(buffer.len, remaining);
            const chunk = buffer[0..chunk_len];
            const read_len = try file.readPositionalAll(self.io, chunk, offset);
            if (read_len != chunk.len) return error.InvalidRecord;
            hasher.update(chunk);
            try advanceBinaryOffset(&offset, chunk.len);
            remaining -= chunk.len;
        }
        return hasher.final();
    }

    fn appendRecord(self: Store, record: []const u8) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);

        const size = try self.regularFileSize(file);
        try file.writePositionalAll(self.io, record, size);
        if (selfOptionsNeedSync(self)) {
            try file.sync(self.io);
        }
    }

    fn rollbackBatchAppend(self: Store, event_bytes: u64) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);
        try file.setLength(self.io, event_bytes);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.repairPersistentIndexesFromLog();
    }

    fn truncateIncompleteBatchTail(self: Store) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{ .mode = .read_write, .allow_directory = false });
        defer file.close(self.io);

        var offset: u64 = 0;
        const file_size = try self.regularFileSize(file);
        var batch_begin_offset: ?u64 = null;
        while (offset < file_size) {
            const record_start = offset;
            const parsed = self.readBinaryRecordHeader(file, &offset) catch |err| switch (err) {
                error.InvalidRecord => {
                    if (batch_begin_offset) |begin| return try self.truncateEventLogTo(file, begin);
                    return err;
                },
                else => |e| return e,
            } orelse break;
            ensureBinaryPayloadFits(file_size, offset, parsed.payload_len) catch |err| switch (err) {
                error.InvalidRecord => {
                    if (batch_begin_offset) |begin| return try self.truncateEventLogTo(file, begin);
                    return err;
                },
                else => |e| return e,
            };

            const payload = try self.allocator.alloc(u8, parsed.payload_len);
            defer self.allocator.free(payload);
            const payload_len = try file.readPositionalAll(self.io, payload, offset);
            if (payload_len != payload.len) {
                if (batch_begin_offset) |begin| return try self.truncateEventLogTo(file, begin);
                return error.InvalidRecord;
            }
            advanceBinaryOffset(&offset, payload.len) catch return error.InvalidRecord;
            validateBinaryChecksum(parsed, payload) catch |err| switch (err) {
                error.InvalidRecord => {
                    if (batch_begin_offset) |begin| return try self.truncateEventLogTo(file, begin);
                    return err;
                },
                else => |e| return e,
            };
            validateBinaryRecordPayload(parsed.kind, payload) catch |err| switch (err) {
                error.InvalidRecord => {
                    if (batch_begin_offset) |begin| return try self.truncateEventLogTo(file, begin);
                    return err;
                },
                else => |e| return e,
            };

            switch (parsed.kind) {
                .batch_begin => {
                    if (batch_begin_offset != null) return error.InvalidRecord;
                    batch_begin_offset = record_start;
                },
                .batch_commit => {
                    if (batch_begin_offset == null) return error.InvalidRecord;
                    batch_begin_offset = null;
                },
                .node, .node_batch, .edge, .edge_batch, .edge_delete => {},
            }
        }
        if (batch_begin_offset) |begin| return try self.truncateEventLogTo(file, begin);
        return false;
    }

    fn truncateEventLogTo(self: Store, file: std.Io.File, event_bytes: u64) !bool {
        try file.setLength(self.io, event_bytes);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        return true;
    }

    fn rebuildPersistentIndexesFromLogStreaming(self: Store) !void {
        try self.rebuildPersistentIndexesFromLogStreamingWithTimings(null);
    }

    fn rebuildPersistentIndexesFromLogStreamingWithTimings(self: Store, timings: ?*PersistentRepairTimings) !void {
        const reuse_start = storageMonotonicNs(self.io);
        self.rebuildPersistentIndexesFromLogStreamingReuseTexts(true, timings) catch |err| switch (err) {
            error.CannotReuseNodeTexts => {
                if (timings) |t| {
                    t.reuse_failed = true;
                    t.reuse_attempt_ns += storageElapsedNs(self.io, reuse_start);
                }
                const retry_start = storageMonotonicNs(self.io);
                self.rebuildPersistentIndexesFromLogStreamingReuseTexts(false, timings) catch |retry_err| {
                    if (timings) |t| t.retry_rebuild_ns += storageElapsedNs(self.io, retry_start);
                    return retry_err;
                };
                if (timings) |t| t.retry_rebuild_ns += storageElapsedNs(self.io, retry_start);
                return;
            },
            else => |e| return e,
        };
        if (timings) |t| t.reuse_attempt_ns += storageElapsedNs(self.io, reuse_start);
    }

    const RepairNodeTextMaterial = struct {
        offset: u64,
        hash: u64,
        digest: u64,
    };

    const DirectNodeByIdRepair = struct {
        lengths: std.ArrayList(u16) = .empty,
        possible: bool = true,
        expected_id: u64 = 1,
        expected_text_offset: u64 = 0,
        kind: ?core.NodeKind = null,

        fn deinit(self: *DirectNodeByIdRepair, allocator: std.mem.Allocator) void {
            self.lengths.deinit(allocator);
        }

        fn observe(
            self: *DirectNodeByIdRepair,
            allocator: std.mem.Allocator,
            parsed_node: ParsedBinaryNode,
            material: RepairNodeTextMaterial,
        ) !void {
            if (!self.possible) return;
            const short_len = std.math.cast(u16, parsed_node.text_len) orelse {
                self.possible = false;
                return;
            };
            if (parsed_node.id != self.expected_id or material.offset != self.expected_text_offset) {
                self.possible = false;
                return;
            }
            if (self.kind) |kind| {
                if (kind != parsed_node.kind) {
                    self.possible = false;
                    return;
                }
            } else {
                self.kind = parsed_node.kind;
            }
            try self.lengths.append(allocator, short_len);
            self.expected_id += 1;
            self.expected_text_offset = std.math.add(u64, self.expected_text_offset, parsed_node.text_len) catch return error.InvalidRecord;
        }

        fn canRewrite(
            self: DirectNodeByIdRepair,
            kind: core.NodeKind,
            node_count: u64,
            max_node_id: u64,
            node_texts_logical_size: u64,
        ) bool {
            return self.possible and
                self.kind == kind and
                node_count == max_node_id and
                self.lengths.items.len == node_count and
                self.expected_text_offset == node_texts_logical_size;
        }
    };

    fn repairReusedNodeTextOffset(
        reuse_cursor: *u64,
        source_texts_size: u64,
        parsed_offset: u64,
        parsed_len: u32,
    ) !u64 {
        const end = std.math.add(u64, parsed_offset, parsed_len) catch return error.CannotReuseNodeTexts;
        if (end > source_texts_size) return error.CannotReuseNodeTexts;
        reuse_cursor.* = @max(reuse_cursor.*, end);
        return parsed_offset;
    }

    fn repairNodeTextMaterial(
        self: Store,
        source_texts: *const NodeTextsView,
        texts_writer: ?*StorageBufferedWriter,
        reuse_node_texts: bool,
        reuse_cursor: *u64,
        parsed_node: ParsedBinaryNode,
    ) !RepairNodeTextMaterial {
        if (reuse_node_texts) {
            const text_offset = try repairReusedNodeTextOffset(
                reuse_cursor,
                source_texts.size,
                parsed_node.text_offset,
                parsed_node.text_len,
            );
            const digests = try source_texts.hashAndDigestStoredNode(
                parsed_node.id,
                parsed_node.kind,
                parsed_node.text_offset,
                parsed_node.text_len,
            );
            return .{
                .offset = text_offset,
                .hash = digests.text_hash,
                .digest = digests.node_digest,
            };
        }

        const text = try source_texts.readTextAlloc(self.allocator, parsed_node.text_offset, parsed_node.text_len);
        defer self.allocator.free(text);
        const writer = texts_writer orelse return error.InvalidRecord;
        const text_offset = try writer.position();
        try writer.append(text);
        return .{
            .offset = text_offset,
            .hash = nodeTextHash(text),
            .digest = try nodeRecordDigestFromParts(parsed_node.id, parsed_node.kind, text),
        };
    }

    fn rebuildPersistentIndexesFromLogStreamingReuseTexts(self: Store, reuse_node_texts: bool, timings: ?*PersistentRepairTimings) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        var source_texts: ?NodeTextsView = null;
        defer if (source_texts) |*view| view.deinit();

        const texts_tmp_path: ?[]u8 = if (reuse_node_texts) null else try self.tmpPathFor(self.node_texts_path);
        defer if (texts_tmp_path) |path| self.allocator.free(path);
        errdefer if (texts_tmp_path) |path| std.Io.Dir.cwd().deleteFile(self.io, path) catch {};
        const by_id_tmp_path = try self.tmpPathFor(self.node_by_id_path);
        defer self.allocator.free(by_id_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, by_id_tmp_path) catch {};
        const edge_repair_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_edges.tmp", .{self.edge_by_id_path});
        defer self.allocator.free(edge_repair_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, edge_repair_path) catch {};
        const node_text_repair_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_texts.tmp", .{self.node_by_text_path});
        defer self.allocator.free(node_text_repair_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, node_text_repair_path) catch {};
        const tombstone_repair_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_tombstones.tmp", .{self.edge_tombstones_path});
        defer self.allocator.free(tombstone_repair_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tombstone_repair_path) catch {};

        var stats_out = StoreStats{};
        var max_node_id: u64 = 0;
        var max_edge_id_seen: u64 = 0;
        var node_count: u64 = 0;
        var node_digest: u64 = 0;
        var first_node_kind: ?core.NodeKind = null;
        var mixed_node_kind = false;
        var node_text_record_count: usize = 0;
        var edge_record_count: usize = 0;
        var tombstone_count: usize = 0;
        var tombstone_digest: u64 = 0;
        var direct_by_id = DirectNodeByIdRepair{};
        defer direct_by_id.deinit(self.allocator);
        var node_texts_logical_size: u64 = 0;
        var node_by_id_short_text_lens = true;

        {
            var node_ids = RepairIdBitSet{};
            defer node_ids.deinit(self.allocator);
            var edge_tracker = RepairEdgeReplayTracker.init(self.allocator);
            defer edge_tracker.deinit();

            var texts_file: ?std.Io.File = null;
            defer if (texts_file) |open_file| open_file.close(self.io);
            var texts_writer: ?StorageBufferedWriter = null;
            defer if (texts_writer) |*writer| writer.deinit();
            var reuse_texts_cursor: u64 = 0;
            if (!reuse_node_texts) {
                const path = texts_tmp_path orelse return error.InvalidRecord;
                texts_file = try std.Io.Dir.cwd().createFile(self.io, path, .{
                    .read = true,
                    .truncate = true,
                });
                texts_writer = try StorageBufferedWriter.init(self.allocator, self.io, texts_file.?, storage_write_buffer_bytes);
            }
            var text_repair_file = try std.Io.Dir.cwd().createFile(self.io, node_text_repair_path, .{
                .read = true,
                .truncate = true,
            });
            defer text_repair_file.close(self.io);
            var text_repair_writer = try StorageBufferedWriter.init(self.allocator, self.io, text_repair_file, storage_write_buffer_bytes);
            defer text_repair_writer.deinit();
            var index_file = try std.Io.Dir.cwd().createFile(self.io, by_id_tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer index_file.close(self.io);
            try self.writeNodeByIdHeader(index_file, .{ .max_node_id = 0, .node_count = 0 });
            var edge_file = try std.Io.Dir.cwd().createFile(self.io, edge_repair_path, .{
                .read = true,
                .truncate = true,
            });
            defer edge_file.close(self.io);
            var edge_writer = try StorageBufferedWriter.init(self.allocator, self.io, edge_file, storage_write_buffer_bytes);
            defer edge_writer.deinit();
            var tombstone_file = try std.Io.Dir.cwd().createFile(self.io, tombstone_repair_path, .{
                .read = true,
                .truncate = true,
            });
            defer tombstone_file.close(self.io);
            var tombstone_writer = try StorageBufferedWriter.init(self.allocator, self.io, tombstone_file, storage_write_buffer_bytes);
            defer tombstone_writer.deinit();

            var offset: u64 = 0;
            var in_batch = false;
            const replay_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            while (true) {
                const parsed = try self.readBinaryRecordHeader(file, &offset) orelse break;
                try ensureBinaryPayloadFits(file_size, offset, parsed.payload_len);
                const payload = try self.allocator.alloc(u8, parsed.payload_len);
                defer self.allocator.free(payload);
                const payload_len = try file.readPositionalAll(self.io, payload, offset);
                if (payload_len != payload.len) return error.InvalidRecord;
                try advanceBinaryOffset(&offset, payload.len);
                try validateBinaryChecksum(parsed, payload);

                switch (parsed.kind) {
                    .batch_begin => {
                        if (in_batch) return error.InvalidRecord;
                        if (payload.len != 0) return error.InvalidRecord;
                        in_batch = true;
                    },
                    .batch_commit => {
                        if (!in_batch) return error.InvalidRecord;
                        if (payload.len != 0) return error.InvalidRecord;
                        in_batch = false;
                    },
                    .node => {
                        const parsed_node = try validateBinaryNodePayload(payload);
                        if (try node_ids.put(self.allocator, parsed_node.id)) return error.InvalidRecord;
                        const texts = try self.ensureNodeTextsView(&source_texts);
                        const text_material = try self.repairNodeTextMaterial(
                            texts,
                            if (texts_writer) |*writer| writer else null,
                            reuse_node_texts,
                            &reuse_texts_cursor,
                            parsed_node,
                        );
                        try direct_by_id.observe(self.allocator, parsed_node, text_material);

                        max_node_id = @max(max_node_id, parsed_node.id);
                        const node_record = NodeByIdRecord{
                            .id = parsed_node.id,
                            .kind = @intFromEnum(parsed_node.kind),
                            .text_offset = text_material.offset,
                            .text_len = parsed_node.text_len,
                        };
                        if (!nodeRecordHasShortTextLen(node_record)) node_by_id_short_text_lens = false;
                        var node_record_bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
                        try node_record.encode(&node_record_bytes);
                        const record_offset = try nodeByIdRecordOffset(parsed_node.id);
                        try index_file.writePositionalAll(self.io, &node_record_bytes, record_offset);

                        const text_record = NodeTextIndexRecord{
                            .hash = text_material.hash,
                            .id = parsed_node.id,
                            .kind = @intFromEnum(parsed_node.kind),
                            .text_offset = text_material.offset,
                            .text_len = parsed_node.text_len,
                        };
                        var text_record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
                        try text_record.encode(&text_record_bytes);
                        try text_repair_writer.append(&text_record_bytes);
                        node_text_record_count = std.math.add(usize, node_text_record_count, 1) catch return error.InvalidRecord;
                        node_count = std.math.add(u64, node_count, 1) catch return error.InvalidRecord;
                        if (first_node_kind) |kind| {
                            if (kind != parsed_node.kind) mixed_node_kind = true;
                        } else {
                            first_node_kind = parsed_node.kind;
                        }
                        stats_out.nodes = std.math.add(usize, stats_out.nodes, 1) catch return error.InvalidRecord;
                        node_digest ^= text_material.digest;
                        stats_out.node_digest ^= text_material.digest;
                    },
                    .node_batch => {
                        if (!in_batch) return error.InvalidRecord;
                        var batch_reader = try BinaryNodeBatchReader.init(payload);
                        while (try batch_reader.next()) |parsed_node| {
                            if (try node_ids.put(self.allocator, parsed_node.id)) return error.InvalidRecord;
                            {
                                const texts = try self.ensureNodeTextsView(&source_texts);
                                const text_material = try self.repairNodeTextMaterial(
                                    texts,
                                    if (texts_writer) |*writer| writer else null,
                                    reuse_node_texts,
                                    &reuse_texts_cursor,
                                    parsed_node,
                                );
                                try direct_by_id.observe(self.allocator, parsed_node, text_material);

                                max_node_id = @max(max_node_id, parsed_node.id);
                                const node_record = NodeByIdRecord{
                                    .id = parsed_node.id,
                                    .kind = @intFromEnum(parsed_node.kind),
                                    .text_offset = text_material.offset,
                                    .text_len = parsed_node.text_len,
                                };
                                if (!nodeRecordHasShortTextLen(node_record)) node_by_id_short_text_lens = false;
                                var node_record_bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
                                try node_record.encode(&node_record_bytes);
                                const record_offset = try nodeByIdRecordOffset(parsed_node.id);
                                try index_file.writePositionalAll(self.io, &node_record_bytes, record_offset);

                                const text_record = NodeTextIndexRecord{
                                    .hash = text_material.hash,
                                    .id = parsed_node.id,
                                    .kind = @intFromEnum(parsed_node.kind),
                                    .text_offset = text_material.offset,
                                    .text_len = parsed_node.text_len,
                                };
                                var text_record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
                                try text_record.encode(&text_record_bytes);
                                try text_repair_writer.append(&text_record_bytes);
                                node_text_record_count = std.math.add(usize, node_text_record_count, 1) catch return error.InvalidRecord;
                                node_count = std.math.add(u64, node_count, 1) catch return error.InvalidRecord;
                                if (first_node_kind) |kind| {
                                    if (kind != parsed_node.kind) mixed_node_kind = true;
                                } else {
                                    first_node_kind = parsed_node.kind;
                                }
                                stats_out.nodes = std.math.add(usize, stats_out.nodes, 1) catch return error.InvalidRecord;
                                node_digest ^= text_material.digest;
                                stats_out.node_digest ^= text_material.digest;
                            }
                        }
                    },
                    .edge => {
                        const parsed_edge = try validateBinaryEdgePayload(payload);
                        if (!try node_ids.contains(parsed_edge.src)) return error.InvalidRecord;
                        if (!try node_ids.contains(parsed_edge.dst)) return error.InvalidRecord;
                        const record = EdgeIndexRecord{
                            .src = parsed_edge.src,
                            .dst = parsed_edge.dst,
                            .edge_id = parsed_edge.id,
                            .rel = @intFromEnum(parsed_edge.rel),
                        };
                        const record_digest = edgeRecordDigest(record);
                        if (try edge_tracker.put(parsed_edge.id, record_digest, edge_record_count)) return error.InvalidRecord;
                        max_edge_id_seen = @max(max_edge_id_seen, parsed_edge.id);
                        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
                        record.encode(&record_bytes);
                        try edge_writer.append(&record_bytes);
                        edge_record_count = std.math.add(usize, edge_record_count, 1) catch return error.InvalidRecord;
                        stats_out.edges = std.math.add(usize, stats_out.edges, 1) catch return error.InvalidRecord;
                        stats_out.edge_digest ^= record_digest;
                    },
                    .edge_batch => {
                        if (!in_batch) return error.InvalidRecord;
                        const batch = try validateBinaryEdgeBatchHeader(payload);
                        var index: u32 = 0;
                        while (index < batch.count) : (index += 1) {
                            const parsed_edge = try validateBinaryEdgeBatchEdge(payload, batch, index);
                            if (!try node_ids.contains(parsed_edge.src)) return error.InvalidRecord;
                            if (!try node_ids.contains(parsed_edge.dst)) return error.InvalidRecord;
                            const record = EdgeIndexRecord{
                                .src = parsed_edge.src,
                                .dst = parsed_edge.dst,
                                .edge_id = parsed_edge.id,
                                .rel = @intFromEnum(parsed_edge.rel),
                            };
                            const record_digest = edgeRecordDigest(record);
                            if (try edge_tracker.put(parsed_edge.id, record_digest, edge_record_count)) return error.InvalidRecord;
                            max_edge_id_seen = @max(max_edge_id_seen, parsed_edge.id);
                            var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
                            record.encode(&record_bytes);
                            try edge_writer.append(&record_bytes);
                            edge_record_count = std.math.add(usize, edge_record_count, 1) catch return error.InvalidRecord;
                            stats_out.edges = std.math.add(usize, stats_out.edges, 1) catch return error.InvalidRecord;
                            stats_out.edge_digest ^= record_digest;
                        }
                    },
                    .edge_delete => {
                        const edge_id = (try validateBinaryEdgeDeletePayload(payload)).toInt();
                        max_edge_id_seen = @max(max_edge_id_seen, edge_id);
                        const edge_digest = try edge_tracker.delete(self, edge_file, &edge_writer, edge_id, edge_record_count) orelse return error.InvalidRecord;
                        if (stats_out.edges == 0) return error.InvalidRecord;
                        stats_out.edges -= 1;
                        stats_out.edge_digest ^= edge_digest;
                        const tombstone_record = EdgeTombstoneRecord{
                            .edge_id = edge_id,
                            .edge_digest = edge_digest,
                        };
                        var tombstone_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
                        tombstone_record.encode(&tombstone_bytes);
                        try tombstone_writer.append(&tombstone_bytes);
                        tombstone_count = std.math.add(usize, tombstone_count, 1) catch return error.InvalidRecord;
                        tombstone_digest ^= edge_digest;
                    },
                }
            }
            if (in_batch) return error.InvalidRecord;
            if (timings) |t| t.replay_events_ns += storageElapsedNs(self.io, replay_start);

            const node_material_flush_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            if (texts_writer) |*writer| {
                const open_file = texts_file orelse return error.InvalidRecord;
                try writer.flush();
                if (try self.regularFileSize(open_file) != try writer.position()) return error.InvalidRecord;
                node_texts_logical_size = try writer.position();
                if (selfOptionsNeedSync(self)) try open_file.sync(self.io);
            } else {
                if (node_count == 0) return error.CannotReuseNodeTexts;
                const view = source_texts orelse return error.CannotReuseNodeTexts;
                if (reuse_texts_cursor != view.size) return error.CannotReuseNodeTexts;
                node_texts_logical_size = view.size;
            }
            try text_repair_writer.flush();
            const expected_text_repair_size = std.math.mul(u64, @intCast(node_text_record_count), NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
            if (try text_repair_writer.position() != expected_text_repair_size) return error.InvalidRecord;
            if (try self.regularFileSize(text_repair_file) != expected_text_repair_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try text_repair_file.sync(self.io);
            if (timings) |t| t.spool_flush_ns += storageElapsedNs(self.io, node_material_flush_start);

            const node_by_id_finalize_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            var by_id_header = NodeByIdHeader{
                .max_node_id = max_node_id,
                .node_count = node_count,
                .node_digest = node_digest,
            };
            try index_file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(by_id_header));
            try self.writeNodeByIdHeader(index_file, by_id_header);
            if (!mixed_node_kind) {
                if (first_node_kind) |kind| {
                    if (direct_by_id.canRewrite(kind, node_count, max_node_id, node_texts_logical_size)) {
                        try self.rewriteNodeByIdIndexToDerivedDenseLengths(index_file, &by_id_header, kind, direct_by_id.lengths.items);
                    } else {
                        try self.rewriteNodeByIdIndexToUniformRecordsFromTextRepair(index_file, &by_id_header, kind, text_repair_file, node_count, node_by_id_short_text_lens);
                        try self.compactNodeByIdIndexToDerivedTextOffsets(index_file, &by_id_header);
                    }
                }
            }
            if (selfOptionsNeedSync(self)) try index_file.sync(self.io);
            if (timings) |t| t.node_by_id_finalize_ns += storageElapsedNs(self.io, node_by_id_finalize_start);

            const edge_spool_flush_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            try edge_writer.flush();
            const expected_edge_repair_size = std.math.mul(u64, @intCast(edge_record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
            if (try edge_writer.position() != expected_edge_repair_size) return error.InvalidRecord;
            if (try self.regularFileSize(edge_file) != expected_edge_repair_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try edge_file.sync(self.io);
            try tombstone_writer.flush();
            const expected_tombstone_repair_size = std.math.mul(u64, @intCast(tombstone_count), EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
            if (try tombstone_writer.position() != expected_tombstone_repair_size) return error.InvalidRecord;
            if (try self.regularFileSize(tombstone_file) != expected_tombstone_repair_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try tombstone_file.sync(self.io);
            if (timings) |t| {
                t.spool_flush_ns += storageElapsedNs(self.io, edge_spool_flush_start);
                t.nodes = node_count;
                t.edges = @intCast(stats_out.edges);
                t.node_text_records = @intCast(node_text_record_count);
                t.edge_records = @intCast(edge_record_count);
                t.tombstone_records = @intCast(tombstone_count);
            }
        }

        const primary_rename_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        if (texts_tmp_path) |path| {
            try self.renameReplace(path, self.node_texts_path);
        }
        try self.renameReplace(by_id_tmp_path, self.node_by_id_path);
        if (timings) |t| t.primary_rename_ns += storageElapsedNs(self.io, primary_rename_start);

        const compress_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        try self.finalizePrimaryTextStorage();
        if (timings) |t| t.node_texts_compress_ns += storageElapsedNs(self.io, compress_start);

        const node_text_index_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const node_text_publish_shape = NodeTextRepairPublishShape{
            .uniform_kind = if (!mixed_node_kind) blk: {
                const kind = first_node_kind orelse break :blk null;
                break :blk @intFromEnum(kind);
            } else null,
            .u32_id = max_node_id <= std.math.maxInt(u32),
            .derived_hash = false,
            .derived_text_span = true,
        };
        try self.writeNodeTextIndexFromRepairSpool(node_text_repair_path, node_text_record_count, stats_out.node_digest, node_text_publish_shape);
        try self.writeEmptyNodeTextDelta();
        try self.deleteNodeTextRunManifest();
        std.Io.Dir.cwd().deleteFile(self.io, node_text_repair_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        if (timings) |t| t.node_text_index_ns += storageElapsedNs(self.io, node_text_index_start);

        const edge_index_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        try self.writeEdgeIndexesFromRepairSpool(edge_repair_path, edge_record_count, timings);
        std.Io.Dir.cwd().deleteFile(self.io, edge_repair_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        if (timings) |t| t.edge_index_ns += storageElapsedNs(self.io, edge_index_start);

        const tombstone_index_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        try self.writeEdgeTombstoneIndexFromRepairSpool(tombstone_repair_path, tombstone_count, tombstone_digest);
        std.Io.Dir.cwd().deleteFile(self.io, tombstone_repair_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        if (timings) |t| t.tombstone_index_ns += storageElapsedNs(self.io, tombstone_index_start);

        const meta_write_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        var meta = IndexMeta{
            .event_bytes = file_size,
            .nodes = @intCast(stats_out.nodes),
            .edges = @intCast(stats_out.edges),
            .node_digest = stats_out.node_digest,
            .edge_digest = stats_out.edge_digest,
            .edge_indexed_edges = @intCast(edge_record_count),
            .edge_index_digest = stats_out.edge_digest ^ tombstone_digest,
            .max_edge_id_seen = max_edge_id_seen,
        };
        try self.copyNodeTextOrderDigestFromHeader(&meta);
        try self.copyEdgeOrderDigestsFromHeaders(&meta);
        try self.writeIndexMeta(meta);
        try self.rebuildExternalKeyIndex();
        try self.rebuildNodePropertyIndex();
        try self.rebuildEdgeExternalKeyIndex();
        _ = self.dropRedundantEdgeSegmentOverlayAfterBaseIndexCatchup() catch {};
        if (timings) |t| t.meta_write_ns += storageElapsedNs(self.io, meta_write_start);
    }

    pub fn readIndexMeta(self: Store) !IndexMeta {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.index_meta_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        var bytes: [IndexMeta.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        if (file_size != bytes.len) return error.InvalidRecord;
        return IndexMeta.decode(&bytes);
    }

    pub fn eventByteCount(self: Store) !u64 {
        return self.eventBytes();
    }

    pub fn propertyPayloadDeltaByteCount(self: Store) !u64 {
        var file = std.Io.Dir.cwd().openFile(self.io, self.property_payload_delta_path, .{ .allow_directory = false }) catch |err| switch (err) {
            error.FileNotFound => return 0,
            else => |e| return e,
        };
        defer file.close(self.io);
        return self.regularFileSize(file);
    }

    fn writeIndexMeta(self: Store, meta: IndexMeta) !void {
        var bytes: [IndexMeta.encoded_len]u8 = undefined;
        meta.encode(&bytes);
        const tmp_path = try self.tmpPathFor(self.index_meta_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            try file.writePositionalAll(self.io, &bytes, 0);
            if (selfOptionsNeedSync(self)) {
                try file.sync(self.io);
            }
        }
        try self.renameReplace(tmp_path, self.index_meta_path);
        self.index_meta_cache.meta = meta;
        self.index_meta_cache.valid = true;
        if (self.node_text_run_manifest_cache.valid) {
            self.node_text_run_manifest_cache.event_bytes = meta.event_bytes;
        }
    }

    fn currentIndexMeta(self: Store, graph: *const graph_mod.Graph) !IndexMeta {
        const graph_stats = try graphIndexStats(self.allocator, graph);
        return .{
            .event_bytes = try self.eventBytes(),
            .nodes = graph_stats.active_nodes,
            .edges = graph_stats.visible_edges,
            .node_digest = graph_stats.node_digest,
            .edge_digest = graph_stats.edge_digest,
            .node_by_text_order_digest = graph_stats.node_by_text_order_digest,
            .edge_indexed_edges = graph_stats.physical_edges,
            .edge_index_digest = graph_stats.physical_edge_digest,
            .edge_by_id_order_digest = graph_stats.edge_by_id_order_digest,
            .edge_by_src_order_digest = graph_stats.edge_by_src_order_digest,
            .edge_by_dst_order_digest = graph_stats.edge_by_dst_order_digest,
            .max_edge_id_seen = graph_stats.max_edge_id_seen,
        };
    }

    fn currentIndexMetaFromIndexes(self: Store, graph: *const graph_mod.Graph) !IndexMeta {
        const graph_stats = try graphCurrentMetaStats(self.allocator, graph);
        const edge_header = try self.readEdgeIndexHeader(self.edge_by_id_path);
        var meta = IndexMeta{
            .event_bytes = try self.eventBytes(),
            .nodes = graph_stats.active_nodes,
            .edges = graph_stats.visible_edges,
            .node_digest = graph_stats.node_digest,
            .edge_digest = graph_stats.edge_digest,
            .edge_indexed_edges = edge_header.edge_count,
            .edge_index_digest = edge_header.edge_digest,
            .max_edge_id_seen = graph_stats.max_edge_id_seen,
        };
        try self.copyNodeTextOrderDigestFromHeader(&meta);
        try self.copyEdgeOrderDigestsFromHeaders(&meta);
        return meta;
    }

    fn refreshIndexMetaAfterAppend(self: Store, kind: BinaryRecordKind, node: ?graph_mod.Node, edge: ?graph_mod.Edge) !void {
        const current = self.readIndexMeta() catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => null,
            else => |e| return e,
        };
        if (current) |meta| {
            var next = meta;
            next.event_bytes = try self.eventBytes();
            switch (kind) {
                .node => {
                    const appended = node orelse return error.InvalidRecord;
                    next.nodes = std.math.add(u64, next.nodes, 1) catch return error.InvalidRecord;
                    next.node_digest ^= try nodeRecordDigestFromParts(appended.id.toInt(), appended.kind, appended.text);
                    try self.copyNodeTextOrderDigestFromHeader(&next);
                },
                .edge => {
                    const appended = edge orelse return error.InvalidRecord;
                    const digest = edgeRecordDigest(.{
                        .src = appended.src.toInt(),
                        .dst = appended.dst.toInt(),
                        .edge_id = appended.id.toInt(),
                        .rel = @intFromEnum(appended.rel),
                    });
                    next.edges = std.math.add(u64, next.edges, 1) catch return error.InvalidRecord;
                    next.edge_digest ^= digest;
                    next.edge_indexed_edges = std.math.add(u64, next.edge_indexed_edges, 1) catch return error.InvalidRecord;
                    next.edge_index_digest ^= digest;
                    next.max_edge_id_seen = @max(next.max_edge_id_seen, appended.id.toInt());
                    const edge_id_runs = extendEdgeSegmentIdRunSummaryWithEdge(
                        meta.edge_by_id_runs,
                        meta.edge_indexed_edges,
                        appended.id.toInt(),
                    );
                    try self.copyEdgeOrderDigestsFromHeadersWithIdRuns(&next, edge_id_runs);
                    if (!try self.edgeSegmentMetaSummaryReadable(meta)) clearEdgeSegmentSummary(&next);
                },
                .edge_delete => return core.Error.Unsupported,
                .node_batch, .edge_batch, .batch_begin, .batch_commit => return core.Error.Unsupported,
            }
            if (kind == .node) {
                self.updateExternalKeyIndexForNodeAppend(meta, next, node.?) catch {};
                self.updateNodePropertyIndexForNodeAppend(meta, next, node.?) catch {};
            }
            try self.writeIndexMeta(next);
            return;
        }

        const stats_out = try self.stats();
        try self.writeIndexMetaFromStats(stats_out);
    }

    fn writeIndexMetaFromStats(self: Store, stats_out: StoreStats) !void {
        const edge_header = self.readEdgeIndexHeader(self.edge_by_id_path) catch |err| switch (err) {
            error.FileNotFound => EdgeIndexHeader{ .order = .id, .edge_count = @intCast(stats_out.edges), .edge_digest = stats_out.edge_digest },
            else => |e| return e,
        };
        var meta = IndexMeta{
            .event_bytes = try self.eventBytes(),
            .nodes = @intCast(stats_out.nodes),
            .edges = @intCast(stats_out.edges),
            .node_digest = stats_out.node_digest,
            .edge_digest = stats_out.edge_digest,
            .edge_indexed_edges = edge_header.edge_count,
            .edge_index_digest = edge_header.edge_digest,
            .max_edge_id_seen = try self.maxEdgeIdEverSeenInLog(),
        };
        try self.copyNodeTextOrderDigestFromHeader(&meta);
        try self.copyEdgeOrderDigestsFromHeaders(&meta);
        try self.writeIndexMeta(meta);
    }

    fn copyNodeTextOrderDigestFromHeader(self: Store, meta: *IndexMeta) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        const delta_header = try self.readNodeTextDeltaHeader();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (header.node_count + delta_header.node_count + run_count != meta.nodes) return error.InvalidRecord;
        if ((header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != meta.node_digest) return error.InvalidRecord;
        const expected_size = try nodeTextIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        meta.node_by_text_order_digest = combinedNodeTextOrderDigestWithRuns(header, delta_header, manifest.entries.items);
    }

    fn copyEdgeOrderDigestsFromHeaders(self: Store, meta: *IndexMeta) !void {
        try self.copyEdgeOrderDigestsFromHeadersWithIdRuns(meta, null);
    }

    fn copyEdgeOrderDigestsFromHeadersWithIdRuns(self: Store, meta: *IndexMeta, edge_id_runs: ?EdgeSegmentIdRunSummary) !void {
        var id_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer id_file.close(self.io);
        const id_header = try self.readEdgeIndexHeaderFromFile(id_file);
        try validateEdgeHeaderForMeta(id_header, meta.*, .id);
        meta.edge_by_id_order_digest = id_header.order_digest;
        if (edge_id_runs) |runs| {
            if (try self.edgeIdRunSummaryMatchesFile(id_file, id_header, runs)) {
                meta.edge_by_id_runs = runs;
            } else {
                meta.edge_by_id_runs = try self.edgeIdRunSummaryForIndexFile(id_file, id_header);
            }
        } else {
            meta.edge_by_id_runs = try self.edgeIdRunSummaryForIndexFile(id_file, id_header);
        }

        const src_header = try self.readEdgeIndexHeader(self.edge_by_src_path);
        try validateEdgeHeaderForMeta(src_header, meta.*, .src);
        meta.edge_by_src_order_digest = src_header.order_digest;

        const dst_header = try self.readEdgeIndexHeader(self.edge_by_dst_path);
        try validateEdgeHeaderForMeta(dst_header, meta.*, .dst);
        meta.edge_by_dst_order_digest = dst_header.order_digest;
    }

    fn validateEdgeHeaderForMeta(header: EdgeIndexHeader, meta: IndexMeta, order: EdgeIndexOrder) !void {
        if (header.order != order) return error.InvalidRecord;
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
    }

    fn edgeIdRunSummaryForIndexFile(self: Store, file: std.Io.File, header: EdgeIndexHeader) !EdgeSegmentIdRunSummary {
        if (header.order != .id) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;
        if (try denseEdgeIdRunSummaryForHeader(header)) |summary| return summary;
        if (header.edge_count == 0) return .{};
        var builder = EdgeSegmentIdRunBuilder{};
        var previous: u64 = 0;
        var pos: u64 = 0;
        while (pos < header.edge_count) : (pos += 1) {
            const record = try self.readEdgeIndexRecordAt(file, header, pos);
            if (pos != 0 and record.edge_id <= previous) return error.InvalidRecord;
            previous = record.edge_id;
            builder.add(record.edge_id);
        }
        return builder.finish();
    }

    fn persistentIndexesCurrent(self: Store, stats_out: StoreStats) !bool {
        return try self.persistentIndexesCurrentWithTimings(stats_out, null);
    }

    fn persistentIndexesCurrentWithTimings(self: Store, stats_out: StoreStats, timings: ?*PersistentValidateTimings) !bool {
        const meta = self.readCurrentIndexMeta() catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        if (meta.nodes != stats_out.nodes or meta.edges != stats_out.edges) return false;
        if (meta.node_digest != stats_out.node_digest) return false;
        if (meta.edge_digest != stats_out.edge_digest) return false;
        const index_files_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const ok = try self.persistentIndexFilesMatchMetaWithTimings(meta, timings);
        if (timings) |t| t.index_files_ns = storageElapsedNs(self.io, index_files_start);
        return ok;
    }

    fn fastPersistentIndexesCurrent(self: Store) !bool {
        const meta = self.readCurrentIndexMeta() catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        return try self.persistentIndexFilesMatchMetaWithTimings(meta, null);
    }

    fn persistentIndexFilesMatchMeta(self: Store, meta: IndexMeta) !bool {
        return try self.persistentIndexFilesMatchMetaWithTimings(meta, null);
    }

    fn persistentIndexFilesMatchMetaWithTimings(self: Store, meta: IndexMeta, timings: ?*PersistentValidateTimings) !bool {
        const node_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const nodes_ok = self.nodeIndexValidWithTimings(meta.nodes, timings) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => false,
            else => |e| return e,
        };
        if (timings) |t| t.node_index_ns = storageElapsedNs(self.io, node_start);
        if (!nodes_ok) return false;
        const node_text_meta_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const node_text_meta_ok = try self.nodeTextIndexMatchesMeta(meta);
        if (timings) |t| t.node_text_meta_ns = storageElapsedNs(self.io, node_text_meta_start);
        if (!node_text_meta_ok) return false;
        const edge_by_id_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const id_digest = self.edgeIndexValidatedDigest(self.edge_by_id_path, .id, meta.edge_indexed_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        if (timings) |t| t.edge_by_id_ns = storageElapsedNs(self.io, edge_by_id_start);
        const edge_by_src_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const src_digest = self.edgeIndexValidatedDigest(self.edge_by_src_path, .src, meta.edge_indexed_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        if (timings) |t| t.edge_by_src_ns = storageElapsedNs(self.io, edge_by_src_start);
        const edge_by_dst_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const dst_digest = self.edgeIndexValidatedDigest(self.edge_by_dst_path, .dst, meta.edge_indexed_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        if (timings) |t| t.edge_by_dst_ns = storageElapsedNs(self.io, edge_by_dst_start);
        const edge_consistency_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const consistent = id_digest.eql(src_digest) and id_digest.eql(dst_digest);
        if (timings) |t| t.edge_consistency_ns = storageElapsedNs(self.io, edge_consistency_start);
        if (!consistent) return false;
        const edge_tombstone_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const tombstones_ok = self.edgeTombstonesMatchPhysicalIndex(meta) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => false,
            else => |e| return e,
        };
        if (timings) |t| t.edge_tombstone_ns = storageElapsedNs(self.io, edge_tombstone_start);
        if (!tombstones_ok) return false;
        const edge_meta_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const edge_meta_ok = self.validatedEdgeIndexDigestsMatchMeta(meta, id_digest, src_digest, dst_digest) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => false,
            else => |e| return e,
        };
        if (edge_meta_ok) {
            if (timings) |t| t.edge_meta_ns = storageElapsedNs(self.io, edge_meta_start);
            return true;
        }
        const edge_segment_ok = self.edgeSegmentManifestMatchesMetaWithTimings(meta, timings) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => false,
            else => |e| return e,
        };
        if (timings) |t| t.edge_meta_ns = storageElapsedNs(self.io, edge_meta_start);
        return edge_segment_ok;
    }

    fn nodeTextIndexMatchesMeta(self: Store, meta: IndexMeta) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        const delta_header = try self.readNodeTextDeltaHeader();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return false;
        return header.node_count + delta_header.node_count + run_count == meta.nodes and
            (header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) == meta.node_digest and
            combinedNodeTextOrderDigestWithRuns(header, delta_header, manifest.entries.items) == meta.node_by_text_order_digest;
    }

    fn edgeTombstonesMatchPhysicalIndex(self: Store, meta: IndexMeta) !bool {
        var tombstone_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_tombstones_path, .{});
        defer tombstone_file.close(self.io);
        const tombstone_header = try self.readEdgeTombstoneHeaderFromFile(tombstone_file);
        if (tombstone_header.count > meta.edge_indexed_edges) return false;
        if (try self.regularFileSize(tombstone_file) != try edgeTombstoneFileSize(tombstone_header.count)) return false;

        var edge_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer edge_file.close(self.io);
        const edge_header = try self.readEdgeIndexHeaderFromFile(edge_file);
        if (edge_header.order != .id) return false;
        if (edge_header.edge_count != meta.edge_indexed_edges) return false;
        if (edge_header.edge_digest != meta.edge_index_digest) return false;
        if (edge_header.order_digest != meta.edge_by_id_order_digest) return false;
        if (try self.regularFileSize(edge_file) != try edgeIndexFileSizeForHeader(edge_header)) return false;

        var digest: u64 = 0;
        var previous: u64 = 0;
        var edge_scan_pos: u64 = 0;
        var pos: u64 = 0;
        while (pos < tombstone_header.count) : (pos += 1) {
            const tombstone = try self.readEdgeTombstoneRecordAt(tombstone_file, pos);
            if (tombstone.edge_id <= previous) return false;
            previous = tombstone.edge_id;
            var matched = false;
            while (edge_scan_pos < edge_header.edge_count) {
                const edge = try self.readEdgeIndexRecordAt(edge_file, edge_header, edge_scan_pos);
                edge_scan_pos += 1;
                if (edge.edge_id < tombstone.edge_id) continue;
                if (edge.edge_id != tombstone.edge_id) return false;
                digest ^= edgeRecordDigest(edge);
                matched = true;
                break;
            }
            if (!matched) return false;
        }
        return digest == tombstone_header.digest;
    }

    pub fn readEdgeIndexHeader(self: Store, path: []const u8) !EdgeIndexHeader {
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        var bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        const header = try EdgeIndexHeader.decode(&bytes);
        const expected_size = edgeIndexFileSizeForHeader(header) catch return error.InvalidRecord;
        if (file_size != expected_size) return error.InvalidRecord;
        return header;
    }

    fn readEdgeTombstoneIndexHeader(self: Store) !EdgeTombstoneHeader {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_tombstones_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        const header = try self.readEdgeTombstoneHeaderFromFile(file);
        if (file_size != try edgeTombstoneFileSize(header.count)) return error.InvalidRecord;
        return header;
    }

    pub fn edgeTombstoneCount(self: Store) !u64 {
        const header = try self.readEdgeTombstoneIndexHeader();
        return header.count;
    }

    fn visiblePlusTombstoneEdgeCount(self: Store, meta: IndexMeta) !u64 {
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        return std.math.add(u64, meta.edges, tombstone_header.count) catch return error.InvalidRecord;
    }

    const EdgeTombstoneIndexView = struct {
        store: Store,
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        count: u64,

        fn open(store: Store) !EdgeTombstoneIndexView {
            var file = try std.Io.Dir.cwd().openFile(store.io, store.edge_tombstones_path, .{});
            errdefer file.close(store.io);
            const header = try store.readEdgeTombstoneHeaderFromFile(file);
            const expected_size = try edgeTombstoneFileSize(header.count);
            if (try store.regularFileSize(file) != expected_size) return error.InvalidRecord;
            var map = openReadOnlyMemoryMap(store.io, file, expected_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(store.io);
            return .{
                .store = store,
                .file = file,
                .map = map,
                .count = header.count,
            };
        }

        fn deinit(self: *EdgeTombstoneIndexView) void {
            if (self.map) |*map| map.destroy(self.store.io);
            self.file.close(self.store.io);
        }

        fn contains(self: *EdgeTombstoneIndexView, edge_id: u64) !bool {
            var lo: u64 = 0;
            var hi: u64 = self.count;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                const record = try self.readRecordAt(mid);
                if (record.edge_id < edge_id) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            if (lo >= self.count) return false;
            const record = try self.readRecordAt(lo);
            return record.edge_id == edge_id;
        }

        fn readRecordAt(self: *EdgeTombstoneIndexView, index: u64) !EdgeTombstoneRecord {
            if (self.map) |*map| return readEdgeTombstoneRecordFromMap(map, index);
            return self.store.readEdgeTombstoneRecordAt(self.file, index);
        }
    };

    pub const EdgeIndexRecordIterator = struct {
        store: Store,
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        header: EdgeIndexHeader,
        order: EdgeIndexOrder,
        key: u64,
        rel_filter: ?u16 = null,
        tombstones: ?EdgeTombstoneIndexView = null,
        pos: u64,
        end: u64,
        physical_records_scanned: u64 = 0,
        max_physical_records: ?u64 = null,
        done: bool = false,

        pub fn deinit(self: *EdgeIndexRecordIterator) void {
            if (self.tombstones) |*tombstones| tombstones.deinit();
            if (self.map) |*map| map.destroy(self.store.io);
            self.file.close(self.store.io);
        }

        pub fn next(self: *EdgeIndexRecordIterator) !?EdgeIndexRecord {
            while (!self.done and self.pos < self.end) {
                if (self.max_physical_records) |limit| {
                    if (self.physical_records_scanned >= limit) return core.Error.BudgetExceeded;
                }
                const record = try self.readRecordAt(self.pos);
                self.pos += 1;
                self.physical_records_scanned += 1;
                if (edgeIndexRecordKey(record, self.order) != self.key) {
                    self.done = true;
                    return null;
                }
                if (self.rel_filter) |rel| {
                    if (record.rel != rel) {
                        self.done = true;
                        return null;
                    }
                }
                if (self.tombstones) |*tombstones| {
                    if (try tombstones.contains(record.edge_id)) continue;
                }
                return record;
            }
            return null;
        }

        fn readRecordAt(self: *EdgeIndexRecordIterator, index: u64) !EdgeIndexRecord {
            if (self.map) |*map| return readEdgeIndexRecordFromMap(self.header, map, index);
            return self.store.readEdgeIndexRecordAt(self.file, self.header, index);
        }
    };

    pub const VisibleEdgeIndexRecordIterator = struct {
        reader: EdgeIndexRecordReader,
        tombstones: ?EdgeTombstoneIndexView = null,
        pos: u64 = 0,

        pub fn deinit(self: *VisibleEdgeIndexRecordIterator) void {
            if (self.tombstones) |*tombstones| tombstones.deinit();
            self.reader.deinit();
        }

        pub fn next(self: *VisibleEdgeIndexRecordIterator) !?EdgeIndexRecord {
            while (self.pos < self.reader.edge_count) {
                const record = try self.reader.read(self.pos);
                self.pos += 1;
                if (self.tombstones) |*tombstones| {
                    if (try tombstones.contains(record.edge_id)) continue;
                }
                return record;
            }
            return null;
        }
    };

    pub fn visibleEdgeIndexRecordsIterator(self: Store, order: EdgeIndexOrder) !VisibleEdgeIndexRecordIterator {
        const path = switch (order) {
            .id => self.edge_by_id_path,
            .src => self.edge_by_src_path,
            .dst => self.edge_by_dst_path,
        };
        const meta = try self.readCurrentIndexMeta();
        if (self.options.validate_indexes_on_read) {
            if (!try self.edgeIndexesValidatedAndMatchMeta(meta)) return error.InvalidRecord;
        }
        var reader = try self.openEdgeIndexRecordReader(path, order, meta);
        errdefer reader.deinit();
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        var tombstones: ?EdgeTombstoneIndexView = null;
        errdefer if (tombstones) |*view| view.deinit();
        if (tombstone_header.count != 0) tombstones = try EdgeTombstoneIndexView.open(self);
        return .{
            .reader = reader,
            .tombstones = tombstones,
        };
    }

    /// Stream the complete visible edge set, including a published segment
    /// overlay that has not yet been consolidated into the three base edge
    /// indexes. Memory is bounded by the manifest fan-in; callers that need a
    /// different global order can external-sort the fixed-size records.
    pub fn scanVisibleEdgeIndexRecords(
        self: Store,
        allocator: std.mem.Allocator,
        context: *anyopaque,
        visit: EdgeIndexRecordVisitor,
    ) !u64 {
        const meta = try self.readCurrentIndexMeta();
        var count: u64 = 0;
        var digest: u64 = 0;
        var opened = try self.openPublishedEdgeSegmentsForQuery(allocator);
        defer if (opened) |*segments| segments.deinit();
        if (opened) |*segments| {
            const tombstone_header = try self.readEdgeTombstoneIndexHeader();
            var tombstones: ?EdgeTombstoneIndexView = null;
            defer if (tombstones) |*view| view.deinit();
            if (tombstone_header.count != 0 and segments.coverage != .visible_full) {
                tombstones = try EdgeTombstoneIndexView.open(self);
            }

            if (segments.coverage == .delta) {
                var base = try self.openEdgeIndexRecordReader(self.edge_by_src_path, .src, meta);
                defer base.deinit();
                var stream = BaseAndSegmentMergeStream.initWithVirtualFiltered(
                    allocator,
                    &base,
                    &segments.segments.segments,
                    &segments.segments.virtual_edges,
                    .forward,
                    if (tombstones) |*view| view else null,
                );
                defer stream.deinit();
                try stream.reset();
                while (try stream.next()) |edge| {
                    const record = EdgeIndexRecord{
                        .src = edge.src.toInt(),
                        .dst = edge.dst.toInt(),
                        .edge_id = edge.edge_id.toInt(),
                        .rel = @intFromEnum(edge.rel),
                    };
                    try visit(context, record);
                    count = std.math.add(u64, count, 1) catch return error.RecordTooLarge;
                    digest ^= edgeRecordDigest(record);
                }
            } else {
                var stream = if (tombstones) |*view|
                    EdgeSegmentMergeStream.initWithVirtualFiltered(
                        allocator,
                        &segments.segments.segments,
                        &segments.segments.virtual_edges,
                        .forward,
                        view,
                    )
                else
                    EdgeSegmentMergeStream.initWithVirtual(
                        allocator,
                        &segments.segments.segments,
                        &segments.segments.virtual_edges,
                        .forward,
                    );
                defer stream.deinit();
                try stream.reset();
                while (try stream.next()) |edge| {
                    const record = EdgeIndexRecord{
                        .src = edge.src.toInt(),
                        .dst = edge.dst.toInt(),
                        .edge_id = edge.edge_id.toInt(),
                        .rel = @intFromEnum(edge.rel),
                    };
                    try visit(context, record);
                    count = std.math.add(u64, count, 1) catch return error.RecordTooLarge;
                    digest ^= edgeRecordDigest(record);
                }
            }
        } else {
            var records = try self.visibleEdgeIndexRecordsIterator(.src);
            defer records.deinit();
            while (try records.next()) |record| {
                try visit(context, record);
                count = std.math.add(u64, count, 1) catch return error.RecordTooLarge;
                digest ^= edgeRecordDigest(record);
            }
        }
        if (count != meta.edges or digest != meta.edge_digest) return error.InvalidRecord;
        return count;
    }

    pub fn edgeIndexRecordsByNodeIterator(self: Store, order: EdgeIndexOrder, node_id: core.NodeId) !EdgeIndexRecordIterator {
        return self.edgeIndexRecordsByNodeAndRelationIterator(order, node_id, null);
    }

    pub fn edgeIndexRecordsByNodeAndRelationIterator(self: Store, order: EdgeIndexOrder, node_id: core.NodeId, rel_filter: ?core.RelKind) !EdgeIndexRecordIterator {
        if (isReservedNodeId(node_id)) return core.Error.InvalidId;
        const path = switch (order) {
            .id => return core.Error.Unsupported,
            .src => self.edge_by_src_path,
            .dst => self.edge_by_dst_path,
        };
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        errdefer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order) return error.InvalidRecord;
        const meta = try self.readCurrentIndexMeta();
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, order)) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read) {
            if (!try self.edgeIndexesValidatedAndMatchMeta(meta)) return error.InvalidRecord;
        }
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        var tombstones: ?EdgeTombstoneIndexView = null;
        errdefer if (tombstones) |*view| view.deinit();
        if (tombstone_header.count != 0) tombstones = try EdgeTombstoneIndexView.open(self);

        var map = openReadOnlyMemoryMap(self.io, file, expected_size) catch null;
        errdefer if (map) |*mapped| mapped.destroy(self.io);

        const key = node_id.toInt();
        const rel_value: ?u16 = if (rel_filter) |rel| @intFromEnum(rel) else null;
        var lo: u64 = 0;
        var end: u64 = header.edge_count;
        if (header.hasKeyRuns()) {
            const bounds = if (map) |*mapped|
                try edgeIndexKeyRunBoundsForKeyFromMap(header, mapped, key)
            else
                try self.edgeIndexKeyRunBoundsForKeyAt(file, header, key);
            if (bounds) |range| {
                lo = range.start;
                end = range.end;
            } else {
                lo = 0;
                end = 0;
            }
        }
        if (!header.hasKeyRuns() or rel_value != null) {
            var hi: u64 = end;
            while (lo < hi) {
                const mid = lo + (hi - lo) / 2;
                const record = if (map) |*mapped|
                    try readEdgeIndexRecordFromMap(header, mapped, mid)
                else
                    try self.readEdgeIndexRecordAt(file, header, mid);
                const before_target = if (rel_value) |rel|
                    edgeIndexRecordNodeRelLessThan(record, order, key, rel)
                else
                    edgeIndexRecordKey(record, order) < key;
                if (before_target) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
        }

        return .{
            .store = self,
            .file = file,
            .map = map,
            .header = header,
            .order = order,
            .key = key,
            .rel_filter = rel_value,
            .tombstones = tombstones,
            .pos = lo,
            .end = end,
        };
    }

    pub fn readEdgeIndexRecordsByNode(self: Store, allocator: std.mem.Allocator, order: EdgeIndexOrder, node_id: core.NodeId) !std.ArrayList(EdgeIndexRecord) {
        return self.readEdgeIndexRecordsByNodeLimited(allocator, order, node_id, (core.QueryBudget{}).max_visited_edges);
    }

    pub fn readEdgeIndexRecordsByNodeOrdered(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId) !std.ArrayList(EdgeIndexRecord) {
        var order_map = try self.readEdgeOrderMap(allocator);
        defer order_map.deinit();
        return self.readEdgeIndexRecordsByNodeOrderedWithOrderMap(allocator, node_id, &order_map);
    }

    pub fn readEdgeIndexRecordsByNodeOrderedWithOrderMap(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId, order_map: *std.AutoHashMap(u64, u64)) !std.ArrayList(EdgeIndexRecord) {
        var records = try self.readVisibleEdgeIndexRecordsByNodeForOrderedTraversal(allocator, node_id);
        errdefer records.deinit(allocator);
        if (order_map.count() != 0) {
            std.mem.sort(EdgeIndexRecord, records.items, order_map, edgeIndexRecordOptionalOrderLessThan);
        } else {
            std.mem.sort(EdgeIndexRecord, records.items, {}, edgeIndexByIdLessThan);
        }
        return records;
    }

    /// Read the physical visible adjacency for one endpoint. This is the
    /// storage-level source of truth for base indexes plus published segment
    /// overlays; query-only virtual edges (for example deferred `based_on`)
    /// are intentionally outside this API.
    pub fn readVisibleEdgeIndexRecordsByNode(
        self: Store,
        allocator: std.mem.Allocator,
        order: EdgeIndexOrder,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
    ) !std.ArrayList(EdgeIndexRecord) {
        return self.readVisibleEdgeIndexRecordsByNodeLimited(
            allocator,
            order,
            node_id,
            rel_filter,
            (core.QueryBudget{}).max_visited_edges,
        );
    }

    pub fn readVisibleEdgeIndexRecordsByNodeLimited(
        self: Store,
        allocator: std.mem.Allocator,
        order: EdgeIndexOrder,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_records: usize,
    ) !std.ArrayList(EdgeIndexRecord) {
        const CollectContext = struct {
            allocator: std.mem.Allocator,
            records: *std.ArrayList(EdgeIndexRecord),

            fn visit(context: *@This(), record: EdgeIndexRecord) !bool {
                try context.records.append(context.allocator, record);
                return false;
            }
        };
        var records = std.ArrayList(EdgeIndexRecord).empty;
        errdefer records.deinit(allocator);
        var context = CollectContext{ .allocator = allocator, .records = &records };
        _ = try self.forEachVisibleEdgeIndexRecordByNode(
            allocator,
            order,
            node_id,
            rel_filter,
            max_records,
            &context,
            CollectContext.visit,
        );
        return records;
    }

    pub fn forEachVisibleEdgeIndexRecordByNode(
        self: Store,
        allocator: std.mem.Allocator,
        order: EdgeIndexOrder,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_records: usize,
        context: anytype,
        comptime callback: fn (@TypeOf(context), EdgeIndexRecord) anyerror!bool,
    ) !bool {
        return self.forEachVisibleEdgeIndexRecordByNodeMaybeRetained(
            allocator,
            null,
            order,
            node_id,
            rel_filter,
            max_records,
            context,
            callback,
        );
    }

    pub fn forEachVisibleEdgeIndexRecordByNodeRetained(
        self: Store,
        allocator: std.mem.Allocator,
        registry: *EdgeSegmentRetentionRegistry,
        order: EdgeIndexOrder,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_records: usize,
        context: anytype,
        comptime callback: fn (@TypeOf(context), EdgeIndexRecord) anyerror!bool,
    ) !bool {
        return self.forEachVisibleEdgeIndexRecordByNodeMaybeRetained(
            allocator,
            registry,
            order,
            node_id,
            rel_filter,
            max_records,
            context,
            callback,
        );
    }

    fn forEachVisibleEdgeIndexRecordByNodeMaybeRetained(
        self: Store,
        allocator: std.mem.Allocator,
        registry: ?*EdgeSegmentRetentionRegistry,
        order: EdgeIndexOrder,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_records: usize,
        context: anytype,
        comptime callback: fn (@TypeOf(context), EdgeIndexRecord) anyerror!bool,
    ) !bool {
        const direction: segment_mod.Direction = switch (order) {
            .src => .forward,
            .dst => .reverse,
            .id => return core.Error.Unsupported,
        };
        var segments_for_query = if (registry) |retention_registry|
            try self.openPublishedEdgeSegmentsForQueryForNodeRetained(allocator, retention_registry, direction, node_id)
        else
            try self.openPublishedEdgeSegmentsForQueryForNode(allocator, direction, node_id);
        defer if (segments_for_query) |*opened| opened.deinit();

        var emitted: usize = 0;
        const scan_limit = @max(max_records, (core.QueryBudget{}).max_visited_edges);
        const base_scan_limit = std.math.cast(u64, scan_limit) orelse std.math.maxInt(u64);
        if (segments_for_query) |*opened| {
            if (opened.coverage == .delta) {
                var base = try self.edgeIndexRecordsByNodeAndRelationIterator(order, node_id, rel_filter);
                defer base.deinit();
                base.max_physical_records = base_scan_limit;
                while (try base.next()) |record| {
                    if (emitted >= max_records) return core.Error.BudgetExceeded;
                    emitted += 1;
                    if (try callback(context, record)) return true;
                }
            }
            const SegmentContext = struct {
                inner: @TypeOf(context),
                emitted: *usize,
                max_records: usize,

                fn visit(segment_context: *@This(), edge: segment_mod.EdgeRecord) !bool {
                    if (segment_context.emitted.* >= segment_context.max_records) return core.Error.BudgetExceeded;
                    segment_context.emitted.* += 1;
                    return callback(segment_context.inner, .{
                        .src = edge.src.toInt(),
                        .dst = edge.dst.toInt(),
                        .edge_id = edge.edge_id.toInt(),
                        .rel = @intFromEnum(edge.rel),
                    });
                }
            };
            var segment_context = SegmentContext{
                .inner = context,
                .emitted = &emitted,
                .max_records = max_records,
            };
            // Segment tombstone filtering happens inside the storage wrapper,
            // so its physical-edge budget cannot represent this API's visible
            // record budget. Keep the two limits independent: callbacks count
            // visible records above, while the scan cap still bounds work on a
            // tombstone-heavy adjacency.
            return if (opened.coverage == .visible_full)
                try opened.segments.forEachNeighbor(direction, node_id, rel_filter, scan_limit, &segment_context, SegmentContext.visit)
            else
                try self.forEachOpenedPublishedEdgeSegmentNeighbor(&opened.segments, direction, node_id, rel_filter, scan_limit, &segment_context, SegmentContext.visit);
        }

        var base = try self.edgeIndexRecordsByNodeAndRelationIterator(order, node_id, rel_filter);
        defer base.deinit();
        base.max_physical_records = base_scan_limit;
        while (try base.next()) |record| {
            if (emitted >= max_records) return core.Error.BudgetExceeded;
            emitted += 1;
            if (try callback(context, record)) return true;
        }
        return false;
    }

    /// Ordered traversal sorts this physical adjacency with the edge-order
    /// sidecar after loading; keep the compatibility name for those callers.
    pub fn readVisibleEdgeIndexRecordsByNodeForOrderedTraversal(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId) !std.ArrayList(EdgeIndexRecord) {
        return self.readVisibleEdgeIndexRecordsByNode(allocator, .src, node_id, null);
    }

    pub fn readEdgeIndexRecordsByNodeLimited(self: Store, allocator: std.mem.Allocator, order: EdgeIndexOrder, node_id: core.NodeId, max_records: usize) !std.ArrayList(EdgeIndexRecord) {
        var iter = try self.edgeIndexRecordsByNodeIterator(order, node_id);
        defer iter.deinit();
        var out = std.ArrayList(EdgeIndexRecord).empty;
        errdefer out.deinit(allocator);
        while (try iter.next()) |record| {
            if (out.items.len >= max_records) return core.Error.BudgetExceeded;
            try out.append(allocator, record);
        }
        return out;
    }

    pub fn readEdgeOrderRecordsByNode(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId) !std.ArrayList(EdgeOrderRecord) {
        if (isReservedNodeId(node_id)) return core.Error.InvalidId;
        var all = self.readAllEdgeOrderRecords(allocator) catch |err| switch (err) {
            error.FileNotFound => return std.ArrayList(EdgeOrderRecord).empty,
            else => |e| return e,
        };
        errdefer all.deinit(allocator);
        var out = std.ArrayList(EdgeOrderRecord).empty;
        errdefer out.deinit(allocator);
        for (all.items) |record| {
            if (record.src == node_id.toInt()) try out.append(allocator, record);
        }
        all.deinit(allocator);
        return out;
    }

    pub fn readEdgeOrderMap(self: Store, allocator: std.mem.Allocator) !std.AutoHashMap(u64, u64) {
        var order_map = std.AutoHashMap(u64, u64).init(allocator);
        errdefer order_map.deinit();
        var records = self.readAllEdgeOrderRecords(allocator) catch |err| switch (err) {
            error.FileNotFound => return order_map,
            else => |e| return e,
        };
        defer records.deinit(allocator);
        try order_map.ensureTotalCapacity(@intCast(records.items.len));
        for (records.items) |record| order_map.putAssumeCapacity(record.edge_id, record.order_key);
        return order_map;
    }

    /// Validate and stream the ordered-edge sidecar without materializing an
    /// O(ordered edges) map. Migration uses this both to publish the target
    /// sidecar once and to feed authoritative order_key values into its
    /// external property sort.
    pub fn scanEdgeOrderRecords(self: Store, context: *anyopaque, visit: EdgeOrderRecordVisitor) !u64 {
        var file = std.Io.Dir.cwd().openFile(self.io, self.edge_order_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return 0,
            else => |e| return e,
        };
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size < EdgeOrderHeader.encoded_len) return error.InvalidRecord;
        var header_bytes: [EdgeOrderHeader.encoded_len]u8 = undefined;
        if (try file.readPositionalAll(self.io, &header_bytes, 0) != header_bytes.len) return error.InvalidRecord;
        const header = EdgeOrderHeader.decode(&header_bytes);
        const payload_bytes = std.math.mul(u64, header.count, EdgeOrderRecord.encoded_len) catch return error.InvalidRecord;
        if (file_size != std.math.add(u64, EdgeOrderHeader.encoded_len, payload_bytes) catch return error.InvalidRecord) return error.InvalidRecord;

        var digest: u64 = 0;
        var pos: u64 = EdgeOrderHeader.encoded_len;
        var previous: ?EdgeOrderRecord = null;
        var index: u64 = 0;
        while (index < header.count) : (index += 1) {
            var record_bytes: [EdgeOrderRecord.encoded_len]u8 = undefined;
            if (try file.readPositionalAll(self.io, &record_bytes, pos) != record_bytes.len) return error.InvalidRecord;
            pos = std.math.add(u64, pos, EdgeOrderRecord.encoded_len) catch return error.InvalidRecord;
            const record = try EdgeOrderRecord.decode(&record_bytes);
            if (previous) |prior| {
                if (!edgeOrderRecordLessThan({}, prior, record)) return error.InvalidRecord;
                if (prior.edge_id == record.edge_id) return error.InvalidRecord;
            }
            digest ^= edgeOrderRecordDigest(record);
            try visit(context, record);
            previous = record;
        }
        if (digest != header.digest) return error.InvalidRecord;
        return header.count;
    }

    /// Replace this store's order sidecar by streaming a source sidecar and
    /// remapping relation ids. The target file is published atomically after
    /// the complete source digest and target ordering have been validated.
    pub fn replaceEdgeOrderIndexRemappedFrom(
        self: Store,
        source: Store,
        rel_remap: []const u16,
        invalid_rel: u16,
    ) !u64 {
        return self.replaceEdgeOrderIndexFrom(source, rel_remap, invalid_rel, false);
    }

    /// Copy the authoritative order sidecar for edges that survived a COW
    /// rewrite.  Deleted edges may still have stale sidecar records; they are
    /// omitted, while every surviving record must exactly match the target
    /// edge identity and endpoints.
    pub fn replaceEdgeOrderIndexFromPresentEdges(self: Store, source: Store) !u64 {
        return self.replaceEdgeOrderIndexFrom(source, null, std.math.maxInt(u16), true);
    }

    fn replaceEdgeOrderIndexFrom(
        self: Store,
        source: Store,
        rel_remap: ?[]const u16,
        invalid_rel: u16,
        present_only: bool,
    ) !u64 {
        const tmp_path = try self.tmpPathFor(self.edge_order_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var count: u64 = 0;
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.initAtOffset(
                self.allocator,
                self.io,
                file,
                storage_write_buffer_bytes,
                EdgeOrderHeader.encoded_len,
            );
            defer writer.deinit();
            const CopyContext = struct {
                writer: *StorageBufferedWriter,
                target: Store,
                rel_remap: ?[]const u16,
                invalid_rel: u16,
                present_only: bool,
                previous: ?EdgeOrderRecord = null,
                count: u64 = 0,
                digest: u64 = 0,

                fn visit(raw_context: *anyopaque, source_record: EdgeOrderRecord) anyerror!void {
                    const context: *@This() = @ptrCast(@alignCast(raw_context));
                    const target_rel = if (context.rel_remap) |remap| blk: {
                        if (source_record.rel >= remap.len) return error.InvalidRecord;
                        const remapped = remap[source_record.rel];
                        if (remapped == context.invalid_rel or relKindFromInt(remapped) == null) return error.InvalidRecord;
                        break :blk remapped;
                    } else source_record.rel;
                    var target_record = source_record;
                    target_record.rel = target_rel;
                    try validateEdgeOrderRecord(target_record);
                    if (context.present_only) {
                        const target_edge = context.target.readVisibleEdgeIndexRecordById(.fromInt(target_record.edge_id)) catch |err| switch (err) {
                            core.Error.NotFound, core.Error.InvalidId => return,
                            else => |e| return e,
                        };
                        if (target_edge.src != target_record.src or
                            target_edge.rel != target_record.rel) return error.InvalidRecord;
                    }
                    if (context.previous) |prior| {
                        if (!edgeOrderRecordLessThan({}, prior, target_record)) return error.InvalidRecord;
                        if (prior.edge_id == target_record.edge_id) return error.InvalidRecord;
                    }
                    var bytes: [EdgeOrderRecord.encoded_len]u8 = undefined;
                    target_record.encode(&bytes);
                    try context.writer.append(&bytes);
                    context.count = std.math.add(u64, context.count, 1) catch return error.RecordTooLarge;
                    context.digest ^= edgeOrderRecordDigest(target_record);
                    context.previous = target_record;
                }
            };
            var context = CopyContext{
                .writer = &writer,
                .target = self,
                .rel_remap = rel_remap,
                .invalid_rel = invalid_rel,
                .present_only = present_only,
            };
            const source_count = try source.scanEdgeOrderRecords(&context, CopyContext.visit);
            if (context.count > source_count or (!present_only and source_count != context.count)) return error.InvalidRecord;
            try writer.flush();
            var header_bytes: [EdgeOrderHeader.encoded_len]u8 = undefined;
            (EdgeOrderHeader{ .count = context.count, .digest = context.digest }).encode(&header_bytes);
            try file.writePositionalAll(self.io, &header_bytes, 0);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
            count = context.count;
        }
        try self.renameReplace(tmp_path, self.edge_order_path);
        return count;
    }

    /// 批量 upsert order 记录(按 edge_id 替换旧值;一次读全表+写回)。
    /// markdown re-import 修复用:路径 2 复用的旧投影边保留陈旧 order_key → 与新边撞车
    /// (schema_duplicate_order_key)→ render 乱序;复用点已知该位置的新 key,批量改写。
    pub fn upsertEdgeOrderRecordsBatch(self: Store, allocator: std.mem.Allocator, updates: []const EdgeOrderRecord) !void {
        if (updates.len == 0) return;
        for (updates) |u| try validateEdgeOrderRecord(u);
        var records = self.readAllEdgeOrderRecords(allocator) catch |err| switch (err) {
            error.FileNotFound => std.ArrayList(EdgeOrderRecord).empty,
            else => |e| return e,
        };
        defer records.deinit(allocator);
        var updated_ids = std.AutoHashMap(u64, u64).init(allocator); // edge_id → new order_key
        defer updated_ids.deinit();
        for (updates) |u| try updated_ids.put(u.edge_id, u.order_key);
        var missing = std.AutoHashMap(u64, void).init(allocator);
        defer missing.deinit();
        for (updates) |u| try missing.put(u.edge_id, {});
        for (records.items) |*r| {
            if (updated_ids.get(r.edge_id)) |nk| {
                r.order_key = nk;
                _ = missing.remove(r.edge_id);
            }
        }
        // 旧边此前无 order 记录(如非 ordered append 的历史边)→ 补插。
        for (updates) |u| {
            if (missing.contains(u.edge_id)) try records.append(allocator, u);
        }
        std.mem.sort(EdgeOrderRecord, records.items, {}, edgeOrderRecordLessThan);
        try self.writeEdgeOrderIndex(records.items);
    }

    fn insertEdgeOrderRecord(self: Store, record: EdgeOrderRecord) !void {
        try validateEdgeOrderRecord(record);
        var records = self.readAllEdgeOrderRecords(self.allocator) catch |err| switch (err) {
            error.FileNotFound => std.ArrayList(EdgeOrderRecord).empty,
            else => |e| return e,
        };
        defer records.deinit(self.allocator);
        try records.append(self.allocator, record);
        std.mem.sort(EdgeOrderRecord, records.items, {}, edgeOrderRecordLessThan);
        try self.writeEdgeOrderIndex(records.items);
    }

    /// 测试用:读全 order 索引(order_key 撞车回归锁直接断言索引内容)。
    pub fn readAllEdgeOrderRecordsForTest(self: Store, allocator: std.mem.Allocator) !std.ArrayList(EdgeOrderRecord) {
        return self.readAllEdgeOrderRecords(allocator);
    }

    fn readAllEdgeOrderRecords(self: Store, allocator: std.mem.Allocator) !std.ArrayList(EdgeOrderRecord) {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_order_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size < EdgeOrderHeader.encoded_len) return error.InvalidRecord;
        var header_bytes: [EdgeOrderHeader.encoded_len]u8 = undefined;
        const header_read = try file.readPositionalAll(self.io, &header_bytes, 0);
        if (header_read != header_bytes.len) return error.InvalidRecord;
        const header = EdgeOrderHeader.decode(&header_bytes);
        const payload_bytes = std.math.mul(u64, header.count, EdgeOrderRecord.encoded_len) catch return error.InvalidRecord;
        const expected_size = EdgeOrderHeader.encoded_len + payload_bytes;
        if (file_size != expected_size) return error.InvalidRecord;
        var records = std.ArrayList(EdgeOrderRecord).empty;
        errdefer records.deinit(allocator);
        try records.ensureTotalCapacityPrecise(allocator, @intCast(header.count));
        var digest: u64 = 0;
        var pos: u64 = EdgeOrderHeader.encoded_len;
        var previous: ?EdgeOrderRecord = null;
        var index: u64 = 0;
        while (index < header.count) : (index += 1) {
            var record_bytes: [EdgeOrderRecord.encoded_len]u8 = undefined;
            const n = try file.readPositionalAll(self.io, &record_bytes, pos);
            if (n != record_bytes.len) return error.InvalidRecord;
            pos += EdgeOrderRecord.encoded_len;
            const record = try EdgeOrderRecord.decode(&record_bytes);
            if (previous) |prev| {
                if (!edgeOrderRecordLessThan({}, prev, record)) return error.InvalidRecord;
                if (prev.edge_id == record.edge_id) return error.InvalidRecord;
            }
            digest ^= edgeOrderRecordDigest(record);
            records.appendAssumeCapacity(record);
            previous = record;
        }
        if (digest != header.digest) return error.InvalidRecord;
        return records;
    }

    pub fn readNodeById(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId) !?StoredNode {
        const id = node_id.toInt();
        if (isReservedNodeId(node_id)) return core.Error.InvalidId;
        const meta = try self.readCurrentIndexMeta();
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        var view = try NodeByIdIndexView.open(self, meta);
        defer view.deinit();
        const record = (try view.readOptionalRecord(id)) orelse return null;
        return try self.readStoredNodeFromRecord(allocator, record);
    }

    pub fn lookupNodeByExternalKey(self: Store, allocator: std.mem.Allocator, external_key: []const u8, kind_filter: ?core.NodeKind) !?core.NodeId {
        var hits = try self.lookupNodeIdsByStringProperty(allocator, "external_key", external_key, kind_filter, 1);
        defer hits.deinit(allocator);
        if (hits.items.len == 0) return null;
        return hits.items[0];
    }

    pub fn buildNodeExternalKeyLookupCache(self: Store, allocator: std.mem.Allocator) !NodeExternalKeyLookupCache {
        var cache = NodeExternalKeyLookupCache{
            .allocator = allocator,
            .entries = std.StringHashMap(std.ArrayList(NodeExternalKeyLookupEntry)).init(allocator),
        };
        errdefer cache.deinit();
        var iterator = try self.nodeRecordsIterator(null);
        defer iterator.deinit();
        while (try iterator.next(allocator)) |node| {
            defer {
                var mutable = node;
                mutable.deinit(allocator);
            }
            const external_key = try self.getNodeStringProperty(allocator, node.id, "external_key");
            defer if (external_key) |key| allocator.free(key);
            const key = external_key orelse continue;
            if (cache.entries.getPtr(key)) |entries| {
                try entries.append(allocator, .{ .id = node.id, .kind = node.kind });
            } else {
                const owned_key = try allocator.dupe(u8, key);
                errdefer allocator.free(owned_key);
                var entries: std.ArrayList(NodeExternalKeyLookupEntry) = .empty;
                errdefer entries.deinit(allocator);
                try entries.append(allocator, .{ .id = node.id, .kind = node.kind });
                try cache.entries.putNoClobber(owned_key, entries);
            }
        }
        return cache;
    }

    pub fn lookupNodeByExternalKeyCached(self: Store, allocator: std.mem.Allocator, external_key: []const u8, kind_filter: ?core.NodeKind, cache: *NodeExternalKeyLookupCache) !?core.NodeId {
        _ = self;
        _ = allocator;
        if (external_key.len == 0) return null;
        const entries = cache.entries.get(external_key) orelse return null;
        for (entries.items) |entry| {
            if (kind_filter) |filter| {
                if (entry.kind != filter) continue;
            }
            return entry.id;
        }
        return null;
    }

    fn lookupNodeByExternalKeyFromCurrentIndex(self: Store, allocator: std.mem.Allocator, external_key: []const u8, kind_filter: ?core.NodeKind) !?core.NodeId {
        if (external_key.len == 0) return null;
        const meta = try self.readCurrentIndexMeta();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.external_key_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readExternalKeyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest) return error.InvalidRecord;
        const expected_size = try externalKeyIndexFileSize(header.record_count);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        const key_hash = externalKeyHash(external_key);
        const first = try self.externalKeyIndexLowerBound(file, header, key_hash);
        var index = first;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readExternalKeyIndexRecordAt(file, index);
            if (record.hash != key_hash) break;
            const node_id: core.NodeId = .fromInt(record.node_id);
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            const stored_key = try self.getNodeStringProperty(allocator, node_id, "external_key");
            defer if (stored_key) |key| allocator.free(key);
            if (stored_key) |key| if (std.mem.eql(u8, key, external_key)) return node_id;
        }
        return null;
    }

    pub fn rebuildExternalKeyIndex(self: Store) !void {
        const meta = try self.readCurrentIndexMeta();
        var records = std.ArrayList(ExternalKeyIndexRecord).empty;
        defer records.deinit(self.allocator);
        var payload_entries = try self.readPropertyPayloadEntriesOrEmpty(self.allocator);
        defer {
            deinitPropertyPayloadIndexEntries(payload_entries.items, self.allocator);
            payload_entries.deinit(self.allocator);
        }
        var iterator = try self.nodeRecordsIterator(null);
        defer iterator.deinit();
        while (try iterator.next(self.allocator)) |node| {
            defer {
                var mutable = node;
                mutable.deinit(self.allocator);
            }
            if (propertyPayloadStringValue(payload_entries.items, .{ .node = node.id }, "external_key")) |key| {
                try records.append(self.allocator, .{
                    .hash = externalKeyHash(key),
                    .node_id = node.id.toInt(),
                });
            }
        }
        try self.writeExternalKeyIndex(records.items, meta);
    }

    fn readExternalKeyIndexHeaderFromFile(self: Store, file: std.Io.File) !ExternalKeyIndexHeader {
        var bytes: [ExternalKeyIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return ExternalKeyIndexHeader.decode(&bytes);
    }

    fn readExternalKeyIndexRecordAt(self: Store, file: std.Io.File, index: u64) !ExternalKeyIndexRecord {
        var bytes: [ExternalKeyIndexRecord.encoded_len]u8 = undefined;
        const offset = try externalKeyIndexRecordOffset(index);
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return ExternalKeyIndexRecord.decode(&bytes);
    }

    fn externalKeyIndexLowerBound(self: Store, file: std.Io.File, header: ExternalKeyIndexHeader, key_hash: u64) !u64 {
        var lo: u64 = 0;
        var hi: u64 = header.record_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readExternalKeyIndexRecordAt(file, mid);
            if (record.hash < key_hash) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn writeExternalKeyIndex(self: Store, records: []ExternalKeyIndexRecord, meta: IndexMeta) !void {
        std.mem.sort(ExternalKeyIndexRecord, records, {}, externalKeyIndexRecordLessThan);
        const tmp_path = try self.tmpPathFor(self.external_key_index_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try externalKeyIndexFileSize(@intCast(records.len))));
            defer writer.deinit();
            const header = ExternalKeyIndexHeader{
                .record_count = @intCast(records.len),
                .node_count = meta.nodes,
                .node_digest = meta.node_digest,
            };
            var header_bytes: [ExternalKeyIndexHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            var previous: ?ExternalKeyIndexRecord = null;
            for (records) |record| {
                if (previous) |prev| {
                    if (!externalKeyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
                }
                var record_bytes: [ExternalKeyIndexRecord.encoded_len]u8 = undefined;
                try record.encode(&record_bytes);
                try writer.append(&record_bytes);
                previous = record;
            }
            try writer.flush();
            if (try self.regularFileSize(file) != try externalKeyIndexFileSize(@intCast(records.len))) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.external_key_index_path);
    }

    fn readExternalKeyIndexRecordsForMeta(self: Store, allocator: std.mem.Allocator, meta: IndexMeta) !std.ArrayList(ExternalKeyIndexRecord) {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.external_key_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readExternalKeyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try externalKeyIndexFileSize(header.record_count)) return error.InvalidRecord;
        var records = std.ArrayList(ExternalKeyIndexRecord).empty;
        errdefer records.deinit(allocator);
        try records.ensureTotalCapacity(allocator, std.math.cast(usize, header.record_count) orelse return error.RecordTooLarge);
        var previous: ?ExternalKeyIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readExternalKeyIndexRecordAt(file, index);
            if (previous) |prev| {
                if (!externalKeyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            records.appendAssumeCapacity(record);
            previous = record;
        }
        return records;
    }

    fn updateExternalKeyIndexForNodeAppend(self: Store, old_meta: IndexMeta, next_meta: IndexMeta, node: graph_mod.Node) !void {
        _ = self;
        _ = old_meta;
        _ = next_meta;
        _ = node;
    }

    fn updateExternalKeyIndexForNodeBatch(self: Store, old_meta: IndexMeta, next_meta: IndexMeta, nodes: []const graph_mod.Node) !void {
        _ = self;
        _ = old_meta;
        _ = next_meta;
        _ = nodes;
    }

    pub fn lookupNodeIdsByStringProperty(self: Store, allocator: std.mem.Allocator, key: []const u8, value: []const u8, kind_filter: ?core.NodeKind, max_nodes: usize) !std.ArrayList(core.NodeId) {
        var derived = derived: {
            break :derived self.lookupNodeIdsByStringPropertyFromCurrentIndex(allocator, key, value, kind_filter, max_nodes) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => {
                    try self.rebuildNodePropertyIndex();
                    break :derived try self.lookupNodeIdsByStringPropertyFromCurrentIndex(allocator, key, value, kind_filter, max_nodes);
                },
                else => |e| return e,
            };
        };
        defer derived.deinit(allocator);
        var overlay = try self.readNodePropertyOverlayEntriesForKeyOrEmpty(
            allocator,
            self.node_props_overlay_index_path,
            self.node_props_overlay_values_path,
            key,
        );
        defer {
            deinitNodePropertyIndexEntries(overlay.items, allocator);
            overlay.deinit(allocator);
        }
        var payload_overlay = try self.readPropertyPayloadEntriesForKeyOrEmpty(allocator, key);
        defer {
            deinitPropertyPayloadIndexEntries(payload_overlay.items, allocator);
            payload_overlay.deinit(allocator);
        }
        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        var seen = std.AutoHashMap(u64, void).init(allocator);
        defer seen.deinit();
        for (derived.items) |node_id| {
            if (out.items.len >= max_nodes) break;
            if (propertyPayloadStringValue(payload_overlay.items, .{ .node = node_id }, key)) |payload_value| {
                if (!std.mem.eql(u8, payload_value, value)) continue;
            } else if (nodePropertyOverlayStringValue(overlay.items, node_id, key)) |overlay_value| {
                if (!std.mem.eql(u8, overlay_value, value)) continue;
            }
            try appendUniqueNodeId(allocator, &out, &seen, node_id);
        }
        try self.appendNodeIdsByStringPropertyPayloadOverlay(allocator, &out, &seen, payload_overlay.items, key, value, kind_filter, max_nodes);
        try self.appendNodeIdsByStringPropertyOverlay(allocator, &out, &seen, overlay.items, payload_overlay.items, key, value, kind_filter, max_nodes);
        return out;
    }

    /// seen-set 去重(Linus 严重4:线性查重让 100K cap 的 property lookup 变 O(n²))。
    fn appendUniqueNodeId(allocator: std.mem.Allocator, out: *std.ArrayList(core.NodeId), seen: *std.AutoHashMap(u64, void), node_id: core.NodeId) !void {
        const gop = try seen.getOrPut(node_id.toInt());
        if (gop.found_existing) return;
        try out.append(allocator, node_id);
    }

    fn edgeIdLessThan(_: void, a: core.EdgeId, b: core.EdgeId) bool {
        return a.toInt() < b.toInt();
    }

    fn appendUniqueEdgeId(allocator: std.mem.Allocator, out: *std.ArrayList(core.EdgeId), edge_id: core.EdgeId) !void {
        for (out.items) |existing| {
            if (existing == edge_id) return;
        }
        try out.append(allocator, edge_id);
    }

    fn nodePropertyOverlayEntryMatchesNodeKey(entry: NodePropertyIndexEntry, node_id: core.NodeId, key: []const u8) bool {
        return entry.record.node_id == node_id.toInt() and
            entry.record.value_type == NodePropertyIndexRecord.value_type_string and
            entry.record.key_hash == nodePropertyKeyHash(key);
    }

    fn nodePropertyOverlayStringValue(entries: []const NodePropertyIndexEntry, node_id: core.NodeId, key: []const u8) ?[]const u8 {
        for (entries) |entry| {
            if (nodePropertyOverlayEntryMatchesNodeKey(entry, node_id, key)) {
                return entry.value;
            }
        }
        return null;
    }

    fn appendNodeIdsByStringPropertyOverlay(self: Store, allocator: std.mem.Allocator, out: *std.ArrayList(core.NodeId), seen: *std.AutoHashMap(u64, void), entries: []const NodePropertyIndexEntry, payload_entries: []const PropertyPayloadIndexEntry, key: []const u8, value: []const u8, kind_filter: ?core.NodeKind, max_nodes: usize) !void {
        if (max_nodes == 0 or value.len == 0 or !nodePropertyOverlayStringKeySupported(key)) return;
        const key_hash = nodePropertyKeyHash(key);
        const value_hash = nodePropertyValueHash(value);
        for (entries) |entry| {
            if (out.items.len >= max_nodes) break;
            if (entry.record.key_hash != key_hash or entry.record.value_type != NodePropertyIndexRecord.value_type_string or entry.record.value_hash != value_hash) continue;
            const concrete = entry.value orelse return error.InvalidRecord;
            if (!std.mem.eql(u8, concrete, value)) continue;
            const node_id: core.NodeId = .fromInt(entry.record.node_id);
            if (propertyPayloadStringValue(payload_entries, .{ .node = node_id }, key) != null) continue;
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            try appendUniqueNodeId(allocator, out, seen, node_id);
        }
    }

    fn appendNodeIdsByStringPropertyPayloadOverlay(self: Store, allocator: std.mem.Allocator, out: *std.ArrayList(core.NodeId), seen: *std.AutoHashMap(u64, void), entries: []const PropertyPayloadIndexEntry, key: []const u8, value: []const u8, kind_filter: ?core.NodeKind, max_nodes: usize) !void {
        if (max_nodes == 0 or value.len == 0 or !nodePropertyOverlayStringKeySupported(key)) return;
        const key_hash = nodePropertyKeyHash(key);
        const value_hash = nodePropertyValueHash(value);
        for (entries) |entry| {
            if (out.items.len >= max_nodes) break;
            if (entry.record.owner_kind != PropertyPayloadIndexRecord.owner_kind_node) continue;
            if (entry.record.key_hash != key_hash or entry.record.value_type != PropertyPayloadIndexRecord.value_type_string or entry.record.value_hash != value_hash) continue;
            const concrete = entry.value orelse return error.InvalidRecord;
            if (!std.mem.eql(u8, concrete, value)) continue;
            const node_id: core.NodeId = .fromInt(entry.record.owner_id);
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            try appendUniqueNodeId(allocator, out, seen, node_id);
        }
    }

    pub fn lookupEdgeIdsByStringProperty(self: Store, allocator: std.mem.Allocator, key: []const u8, value: []const u8, max_edges: usize) !std.ArrayList(core.EdgeId) {
        var out = std.ArrayList(core.EdgeId).empty;
        errdefer out.deinit(allocator);
        if (max_edges == 0 or value.len == 0 or !edgePropertyOverlayStringKeySupported(key)) return out;

        var payload_entries = try self.readPropertyPayloadEntriesForKeyOrEmpty(allocator, key);
        defer {
            deinitPropertyPayloadIndexEntries(payload_entries.items, allocator);
            payload_entries.deinit(allocator);
        }

        const key_hash = nodePropertyKeyHash(key);
        const value_hash = nodePropertyValueHash(value);
        for (payload_entries.items) |entry| {
            if (out.items.len >= max_edges) break;
            if (entry.record.owner_kind != PropertyPayloadIndexRecord.owner_kind_edge) continue;
            if (entry.record.key_hash != key_hash or entry.record.value_type != PropertyPayloadIndexRecord.value_type_string or entry.record.value_hash != value_hash) continue;
            const concrete = entry.value orelse return error.InvalidRecord;
            if (!std.mem.eql(u8, concrete, value)) continue;
            const edge_id: core.EdgeId = .fromInt(entry.record.owner_id);
            if (!try self.visibleEdgeIdExists(edge_id)) continue;
            try appendUniqueEdgeId(allocator, &out, edge_id);
        }

        var legacy_entries = try self.readNodePropertyOverlayEntriesForKeyOrEmpty(
            allocator,
            self.edge_props_overlay_index_path,
            self.edge_props_overlay_values_path,
            key,
        );
        defer {
            deinitNodePropertyIndexEntries(legacy_entries.items, allocator);
            legacy_entries.deinit(allocator);
        }
        for (legacy_entries.items) |entry| {
            if (out.items.len >= max_edges) break;
            if (entry.record.key_hash != key_hash or entry.record.value_type != NodePropertyIndexRecord.value_type_string or entry.record.value_hash != value_hash) continue;
            const concrete = entry.value orelse return error.InvalidRecord;
            if (!std.mem.eql(u8, concrete, value)) continue;
            const edge_id: core.EdgeId = .fromInt(entry.record.node_id);
            if (propertyPayloadStringValue(payload_entries.items, .{ .edge = edge_id }, key) != null) continue;
            if (!try self.visibleEdgeIdExists(edge_id)) continue;
            try appendUniqueEdgeId(allocator, &out, edge_id);
        }
        std.mem.sort(core.EdgeId, out.items, {}, edgeIdLessThan);
        return out;
    }

    fn lookupNodeIdsByStringPropertyFromCurrentIndex(self: Store, allocator: std.mem.Allocator, key: []const u8, value: []const u8, kind_filter: ?core.NodeKind, max_nodes: usize) !std.ArrayList(core.NodeId) {
        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        if (max_nodes == 0 or value.len == 0 or !nodePropertyStringKeySupported(key)) return out;
        const meta = try self.readCurrentIndexMeta();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;
        var values_file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != meta.nodes or values_header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

        const key_hash = nodePropertyKeyHash(key);
        const value_hash = nodePropertyValueHash(value);
        const first = try self.nodePropertyIndexLowerBound(file, header, key_hash, NodePropertyIndexRecord.value_type_string, value_hash);
        var index = first;
        while (index < header.record_count and out.items.len < max_nodes) : (index += 1) {
            const record = try self.readNodePropertyIndexRecordAt(file, index);
            if (record.key_hash != key_hash or record.value_type != NodePropertyIndexRecord.value_type_string or record.value_hash != value_hash) break;
            const node_id: core.NodeId = .fromInt(record.node_id);
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            const payload_value = try self.readNodePropertyValuePayloadAt(allocator, values_file, values_header, index, record);
            defer if (payload_value) |concrete| allocator.free(concrete);
            if (payload_value) |concrete| {
                if (std.mem.eql(u8, concrete, value)) try out.append(allocator, node_id);
            }
        }
        return out;
    }

    pub fn lookupNodeIdsByUintProperty(self: Store, allocator: std.mem.Allocator, key: []const u8, value: u64, kind_filter: ?core.NodeKind, max_nodes: usize) !std.ArrayList(core.NodeId) {
        var derived = self.lookupNodeIdsByUintPropertyFromCurrentIndex(allocator, key, value, kind_filter, max_nodes) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => blk: {
                try self.rebuildNodePropertyIndex();
                break :blk try self.lookupNodeIdsByUintPropertyFromCurrentIndex(allocator, key, value, kind_filter, max_nodes);
            },
            else => |e| return e,
        };
        defer derived.deinit(allocator);

        var payload_overlay = try self.readPropertyPayloadEntriesForKeyOrEmpty(allocator, key);
        defer {
            deinitPropertyPayloadIndexEntries(payload_overlay.items, allocator);
            payload_overlay.deinit(allocator);
        }

        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        var seen = std.AutoHashMap(u64, void).init(allocator);
        defer seen.deinit();
        for (derived.items) |node_id| {
            if (out.items.len >= max_nodes) break;
            if (propertyPayloadUintValue(payload_overlay.items, .{ .node = node_id }, key)) |payload_value| {
                if (payload_value != value) continue;
            }
            try appendUniqueNodeId(allocator, &out, &seen, node_id);
        }
        try self.appendNodeIdsByUintPropertyPayloadOverlay(allocator, &out, &seen, payload_overlay.items, key, .{ .min = value, .max = value }, kind_filter, max_nodes);
        return out;
    }

    fn lookupNodeIdsByUintPropertyFromCurrentIndex(self: Store, allocator: std.mem.Allocator, key: []const u8, value: u64, kind_filter: ?core.NodeKind, max_nodes: usize) !std.ArrayList(core.NodeId) {
        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        if (max_nodes == 0 or !nodePropertyUintKeySupported(key)) return out;
        const meta = try self.readCurrentIndexMeta();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;

        const key_hash = nodePropertyKeyHash(key);
        const first = try self.nodePropertyIndexLowerBound(file, header, key_hash, NodePropertyIndexRecord.value_type_uint, value);
        var index = first;
        while (index < header.record_count and out.items.len < max_nodes) : (index += 1) {
            const record = try self.readNodePropertyIndexRecordAt(file, index);
            if (record.key_hash != key_hash or record.value_type != NodePropertyIndexRecord.value_type_uint or record.value_hash != value) break;
            const node_id: core.NodeId = .fromInt(record.node_id);
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            if (nodePropertyUintValueFromText(allocator, node.text, key)) |concrete| {
                if (concrete == value) try out.append(allocator, node_id);
            }
        }
        return out;
    }

    pub const UintPropertyRange = struct {
        min: ?u64 = null,
        min_inclusive: bool = true,
        max: ?u64 = null,
        max_inclusive: bool = true,

        fn contains(self: UintPropertyRange, value: u64) bool {
            if (self.min) |min| {
                if (self.min_inclusive) {
                    if (value < min) return false;
                } else if (value <= min) return false;
            }
            if (self.max) |max| {
                if (self.max_inclusive) {
                    if (value > max) return false;
                } else if (value >= max) return false;
            }
            return true;
        }
    };

    pub fn lookupNodeIdsByUintPropertyRange(self: Store, allocator: std.mem.Allocator, key: []const u8, range: UintPropertyRange, kind_filter: ?core.NodeKind, max_nodes: usize) !std.ArrayList(core.NodeId) {
        var derived = self.lookupNodeIdsByUintPropertyRangeFromCurrentIndex(allocator, key, range, kind_filter, max_nodes) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => blk: {
                try self.rebuildNodePropertyIndex();
                break :blk try self.lookupNodeIdsByUintPropertyRangeFromCurrentIndex(allocator, key, range, kind_filter, max_nodes);
            },
            else => |e| return e,
        };
        defer derived.deinit(allocator);

        var payload_overlay = try self.readPropertyPayloadEntriesForKeyOrEmpty(allocator, key);
        defer {
            deinitPropertyPayloadIndexEntries(payload_overlay.items, allocator);
            payload_overlay.deinit(allocator);
        }

        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        var seen = std.AutoHashMap(u64, void).init(allocator);
        defer seen.deinit();
        for (derived.items) |node_id| {
            if (out.items.len >= max_nodes) break;
            if (propertyPayloadUintValue(payload_overlay.items, .{ .node = node_id }, key)) |payload_value| {
                if (!range.contains(payload_value)) continue;
            }
            try appendUniqueNodeId(allocator, &out, &seen, node_id);
        }
        try self.appendNodeIdsByUintPropertyPayloadOverlay(allocator, &out, &seen, payload_overlay.items, key, range, kind_filter, max_nodes);
        return out;
    }

    fn lookupNodeIdsByUintPropertyRangeFromCurrentIndex(self: Store, allocator: std.mem.Allocator, key: []const u8, range: UintPropertyRange, kind_filter: ?core.NodeKind, max_nodes: usize) !std.ArrayList(core.NodeId) {
        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        if (max_nodes == 0 or !nodePropertyUintKeySupported(key)) return out;
        if (range.min != null and range.max != null and range.min.? > range.max.?) return out;
        if (range.min != null and range.max != null and range.min.? == range.max.? and (!range.min_inclusive or !range.max_inclusive)) return out;
        const meta = try self.readCurrentIndexMeta();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;

        const key_hash = nodePropertyKeyHash(key);
        const start_value = range.min orelse 0;
        const first = try self.nodePropertyIndexLowerBound(file, header, key_hash, NodePropertyIndexRecord.value_type_uint, start_value);
        var index = first;
        while (index < header.record_count and out.items.len < max_nodes) : (index += 1) {
            const record = try self.readNodePropertyIndexRecordAt(file, index);
            if (record.key_hash != key_hash or record.value_type != NodePropertyIndexRecord.value_type_uint) break;
            const value = record.value_hash;
            if (range.max) |max| {
                if (range.max_inclusive) {
                    if (value > max) break;
                } else if (value >= max) break;
            }
            if (!range.contains(value)) continue;
            const node_id: core.NodeId = .fromInt(record.node_id);
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            if (nodePropertyUintValueFromText(allocator, node.text, key)) |concrete| {
                if (range.contains(concrete)) try out.append(allocator, node_id);
            }
        }
        return out;
    }

    fn appendNodeIdsByUintPropertyPayloadOverlay(self: Store, allocator: std.mem.Allocator, out: *std.ArrayList(core.NodeId), seen: *std.AutoHashMap(u64, void), entries: []const PropertyPayloadIndexEntry, key: []const u8, range: UintPropertyRange, kind_filter: ?core.NodeKind, max_nodes: usize) !void {
        if (max_nodes == 0 or !nodePropertyPayloadUintKeySupported(key)) return;
        const key_hash = nodePropertyKeyHash(key);
        for (entries) |entry| {
            if (out.items.len >= max_nodes) break;
            if (entry.record.owner_kind != PropertyPayloadIndexRecord.owner_kind_node) continue;
            if (entry.record.key_hash != key_hash or entry.record.value_type != PropertyPayloadIndexRecord.value_type_uint) continue;
            if (!range.contains(entry.record.value_hash)) continue;
            const node_id: core.NodeId = .fromInt(entry.record.owner_id);
            var node = (try self.readNodeById(allocator, node_id)) orelse continue;
            defer node.deinit(allocator);
            if (kind_filter) |filter| {
                if (node.kind != filter) continue;
            }
            try appendUniqueNodeId(allocator, out, seen, node_id);
        }
    }

    pub fn rebuildNodePropertyIndex(self: Store) !void {
        const meta = try self.readCurrentIndexMeta();
        var entries = std.ArrayList(NodePropertyIndexEntry).empty;
        defer {
            deinitNodePropertyIndexEntries(entries.items, self.allocator);
            entries.deinit(self.allocator);
        }
        var iterator = try self.nodeRecordsIterator(null);
        defer iterator.deinit();
        while (try iterator.next(self.allocator)) |node| {
            defer {
                var mutable = node;
                mutable.deinit(self.allocator);
            }
            try appendNodePropertyRecordsFromText(&entries, self.allocator, node.id, node.text);
        }
        try self.writeNodePropertyIndex(entries.items, meta);
    }

    fn readNodePropertyIndexHeaderFromFile(self: Store, file: std.Io.File) !NodePropertyIndexHeader {
        var bytes: [NodePropertyIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return NodePropertyIndexHeader.decode(&bytes);
    }

    fn readNodePropertyIndexRecordAt(self: Store, file: std.Io.File, index: u64) !NodePropertyIndexRecord {
        var bytes: [NodePropertyIndexRecord.encoded_len]u8 = undefined;
        const offset = try nodePropertyIndexRecordOffset(index);
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return NodePropertyIndexRecord.decode(&bytes);
    }

    fn readNodePropertyValueBlockHeaderFromFile(self: Store, file: std.Io.File) !NodePropertyValueBlockHeader {
        var bytes: [NodePropertyValueBlockHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return NodePropertyValueBlockHeader.decode(&bytes);
    }

    fn readNodePropertyValueRecordAt(self: Store, file: std.Io.File, index: u64) !NodePropertyValueRecord {
        var bytes: [NodePropertyValueRecord.encoded_len]u8 = undefined;
        const offset = try nodePropertyValueRecordOffset(index);
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return NodePropertyValueRecord.decode(&bytes);
    }

    fn readNodePropertyValuePayloadAt(self: Store, allocator: std.mem.Allocator, file: std.Io.File, header: NodePropertyValueBlockHeader, index: u64, record: NodePropertyIndexRecord) !?[]u8 {
        const value_record = try self.readNodePropertyValueRecordAt(file, index);
        if (record.value_type == NodePropertyIndexRecord.value_type_uint) {
            if (value_record.offset != 0 or value_record.len != 0) return error.InvalidRecord;
            return null;
        }
        if (record.value_type != NodePropertyIndexRecord.value_type_string) return error.InvalidRecord;
        if (value_record.len == 0) return error.InvalidRecord;
        const value_end = std.math.add(u64, value_record.offset, value_record.len) catch return error.InvalidRecord;
        if (value_end > header.payload_bytes) return error.InvalidRecord;
        const payload_start = try nodePropertyValueBlockHeaderAndRecordBytes(header.record_count);
        const file_offset = std.math.add(u64, payload_start, value_record.offset) catch return error.InvalidRecord;
        const value = try allocator.alloc(u8, value_record.len);
        errdefer allocator.free(value);
        const n = try file.readPositionalAll(self.io, value, file_offset);
        if (n != value.len) return error.InvalidRecord;
        if (nodePropertyValueHash(value) != record.value_hash) return error.InvalidRecord;
        return value;
    }

    fn readPropertyPayloadIndexHeaderFromFile(self: Store, file: std.Io.File) !PropertyPayloadIndexHeader {
        var bytes: [PropertyPayloadIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return PropertyPayloadIndexHeader.decode(&bytes);
    }

    fn readPropertyPayloadIndexRecordAt(self: Store, file: std.Io.File, index: u64) !PropertyPayloadIndexRecord {
        var bytes: [PropertyPayloadIndexRecord.encoded_len]u8 = undefined;
        const offset = try propertyPayloadIndexRecordOffset(index);
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return PropertyPayloadIndexRecord.decode(&bytes);
    }

    fn propertyPayloadKeyHashLowerBound(self: Store, file: std.Io.File, record_count: u64, key_hash: u64) !u64 {
        var lo: u64 = 0;
        var hi = record_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readPropertyPayloadIndexRecordAt(file, mid);
            if (record.key_hash < key_hash) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn validatePropertyPayloadIndexOrderIfStrict(self: Store, file: std.Io.File, header: PropertyPayloadIndexHeader) !void {
        return self.validatePropertyPayloadIndexOrderIfStrictDeadline(file, header, .none);
    }

    fn validatePropertyPayloadIndexOrderIfStrictDeadline(
        self: Store,
        file: std.Io.File,
        header: PropertyPayloadIndexHeader,
        deadline: core.QueryDeadline,
    ) !void {
        if (!self.options.validate_indexes_on_read) return;
        var previous: ?PropertyPayloadIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const record = try self.readPropertyPayloadIndexRecordAt(file, index);
            if (previous) |prev| {
                if (!propertyPayloadRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            previous = record;
        }
    }

    fn readPropertyPayloadValuePayloadAt(self: Store, allocator: std.mem.Allocator, file: std.Io.File, header: NodePropertyValueBlockHeader, index: u64, record: PropertyPayloadIndexRecord) !?[]u8 {
        const value_record = try self.readNodePropertyValueRecordAt(file, index);
        if (record.value_type == PropertyPayloadIndexRecord.value_type_uint) {
            if (value_record.offset != 0 or value_record.len != 0) return error.InvalidRecord;
            return null;
        }
        if (record.value_type != PropertyPayloadIndexRecord.value_type_string) return error.InvalidRecord;
        if (value_record.len == 0) return error.InvalidRecord;
        const value_end = std.math.add(u64, value_record.offset, value_record.len) catch return error.InvalidRecord;
        if (value_end > header.payload_bytes) return error.InvalidRecord;
        const payload_start = try nodePropertyValueBlockHeaderAndRecordBytes(header.record_count);
        const file_offset = std.math.add(u64, payload_start, value_record.offset) catch return error.InvalidRecord;
        const value = try allocator.alloc(u8, value_record.len);
        errdefer allocator.free(value);
        const n = try file.readPositionalAll(self.io, value, file_offset);
        if (n != value.len) return error.InvalidRecord;
        if (nodePropertyValueHash(value) != record.value_hash) return error.InvalidRecord;
        return value;
    }

    fn nodePropertyIndexLowerBound(self: Store, file: std.Io.File, header: NodePropertyIndexHeader, key_hash: u64, value_type: u8, value_hash: u64) !u64 {
        var lo: u64 = 0;
        var hi: u64 = header.record_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readNodePropertyIndexRecordAt(file, mid);
            if (record.key_hash < key_hash or
                (record.key_hash == key_hash and record.value_type < value_type) or
                (record.key_hash == key_hash and record.value_type == value_type and record.value_hash < value_hash))
            {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn writeNodePropertyIndex(self: Store, entries: []NodePropertyIndexEntry, meta: IndexMeta) !void {
        try self.writeNodePropertyIndexFiles(self.node_props_index_path, self.node_props_values_path, entries, meta);
    }

    fn writeNodePropertyIndexFiles(self: Store, index_path: []const u8, values_path: []const u8, entries: []NodePropertyIndexEntry, meta: IndexMeta) !void {
        std.mem.sort(NodePropertyIndexEntry, entries, {}, nodePropertyIndexEntryLessThan);
        const tmp_path = try self.tmpPathFor(index_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try nodePropertyIndexFileSize(@intCast(entries.len))));
            defer writer.deinit();
            const header = NodePropertyIndexHeader{
                .record_count = @intCast(entries.len),
                .node_count = meta.nodes,
                .node_digest = meta.node_digest,
            };
            var header_bytes: [NodePropertyIndexHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            var previous: ?NodePropertyIndexRecord = null;
            for (entries) |entry| {
                const record = entry.record;
                if (previous) |prev| {
                    if (!nodePropertyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
                }
                var record_bytes: [NodePropertyIndexRecord.encoded_len]u8 = undefined;
                try record.encode(&record_bytes);
                try writer.append(&record_bytes);
                previous = record;
            }
            try writer.flush();
            if (try self.regularFileSize(file) != try nodePropertyIndexFileSize(@intCast(entries.len))) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.writeNodePropertyValueBlock(values_path, entries, meta);
        try self.renameReplace(tmp_path, index_path);
    }

    fn writeNodePropertyValueBlock(self: Store, values_path: []const u8, entries: []const NodePropertyIndexEntry, meta: IndexMeta) !void {
        const tmp_path = try self.tmpPathFor(values_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        const value_records = try self.allocator.alloc(NodePropertyValueRecord, entries.len);
        defer self.allocator.free(value_records);
        var payload_bytes: u64 = 0;
        var payload_digest: u64 = 0;
        var digest_bytes: [8]u8 = undefined;
        for (entries, 0..) |entry, i| {
            if (entry.record.value_type == NodePropertyIndexRecord.value_type_string) {
                const value = entry.value orelse return error.InvalidRecord;
                if (value.len == 0 or nodePropertyValueHash(value) != entry.record.value_hash) return error.InvalidRecord;
                const len_u32 = std.math.cast(u32, value.len) orelse return error.RecordTooLarge;
                value_records[i] = .{ .offset = payload_bytes, .len = len_u32 };
                std.mem.writeInt(u64, &digest_bytes, entry.record.key_hash, .little);
                payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, &digest_bytes);
                std.mem.writeInt(u64, &digest_bytes, entry.record.value_hash, .little);
                payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, &digest_bytes);
                payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, value);
                payload_bytes = std.math.add(u64, payload_bytes, value.len) catch return error.RecordTooLarge;
            } else if (entry.record.value_type == NodePropertyIndexRecord.value_type_uint) {
                if (entry.value != null) return error.InvalidRecord;
                value_records[i] = .{ .offset = 0, .len = 0 };
            } else {
                return error.InvalidRecord;
            }
        }
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            const file_size = try nodePropertyValueBlockFileSize(@intCast(entries.len), payload_bytes);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(file_size));
            defer writer.deinit();
            const header = NodePropertyValueBlockHeader{
                .record_count = @intCast(entries.len),
                .node_count = meta.nodes,
                .node_digest = meta.node_digest,
                .payload_bytes = payload_bytes,
                .payload_digest = payload_digest,
            };
            var header_bytes: [NodePropertyValueBlockHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            var value_record_bytes: [NodePropertyValueRecord.encoded_len]u8 = undefined;
            for (value_records) |record| {
                record.encode(&value_record_bytes);
                try writer.append(&value_record_bytes);
            }
            for (entries) |entry| {
                if (entry.record.value_type == NodePropertyIndexRecord.value_type_string) {
                    try writer.append(entry.value.?);
                }
            }
            try writer.flush();
            if (try self.regularFileSize(file) != file_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, values_path);
    }

    fn encodePropertyPayloadDeltaFrame(self: Store, allocator: std.mem.Allocator, sequence: u64, writes: []const PropertyPayloadWrite) ![]u8 {
        _ = self;
        if (writes.len == 0) return error.InvalidRecord;
        var payload = std.ArrayList(u8).empty;
        defer payload.deinit(allocator);
        var frame_keys = PropertyPayloadOwnerKeySet.init(allocator);
        defer frame_keys.deinit();
        try frame_keys.ensureTotalCapacity(std.math.cast(u32, writes.len) orelse return error.RecordTooLarge);
        for (writes) |write| {
            const key_len = std.math.cast(u16, write.key.len) orelse return error.RecordTooLarge;
            if (!propertyKeyNameValid(write.key)) return error.InvalidRecord;
            const frame_key = try frame_keys.getOrPut(propertyPayloadOwnerKey(write.owner, write.key));
            if (frame_key.found_existing) return error.InvalidRecord;
            const value_len: u32 = switch (write.value) {
                .string => |value| std.math.cast(u32, value.len) orelse return error.RecordTooLarge,
                .uint => 0,
            };
            const value_hash: u64 = switch (write.value) {
                .string => |value| blk: {
                    if (value.len == 0) return error.InvalidRecord;
                    break :blk nodePropertyValueHash(value);
                },
                .uint => |value| value,
            };
            var entry_bytes: [property_payload_delta_entry_len]u8 = [_]u8{0} ** property_payload_delta_entry_len;
            entry_bytes[0] = propertyPayloadOwnerKind(write.owner);
            entry_bytes[1] = switch (write.value) {
                .string => PropertyPayloadIndexRecord.value_type_string,
                .uint => PropertyPayloadIndexRecord.value_type_uint,
            };
            writeU16(entry_bytes[2..4], key_len);
            writeU32(entry_bytes[4..8], value_len);
            writeU64(entry_bytes[8..16], propertyPayloadOwnerId(write.owner));
            writeU64(entry_bytes[16..24], nodePropertyKeyHash(write.key));
            writeU64(entry_bytes[24..32], value_hash);
            try payload.appendSlice(allocator, &entry_bytes);
            try payload.appendSlice(allocator, write.key);
            switch (write.value) {
                .string => |value| try payload.appendSlice(allocator, value),
                .uint => {},
            }
        }
        const payload_len = std.math.cast(u32, payload.items.len) orelse return error.RecordTooLarge;
        if (payload_len > property_payload_delta_max_frame_bytes) return error.RecordTooLarge;
        const frame_len = std.math.add(usize, property_payload_delta_header_len, payload.items.len) catch return error.RecordTooLarge;
        const frame = try allocator.alloc(u8, frame_len);
        errdefer allocator.free(frame);
        const header = PropertyPayloadDeltaHeader{
            .sequence = sequence,
            .write_count = std.math.cast(u32, writes.len) orelse return error.RecordTooLarge,
            .payload_len = payload_len,
            .payload_digest = std.hash.Wyhash.hash(property_payload_delta_digest_seed, payload.items),
        };
        var header_bytes: [property_payload_delta_header_len]u8 = undefined;
        try header.encode(&header_bytes);
        @memcpy(frame[0..property_payload_delta_header_len], &header_bytes);
        @memcpy(frame[property_payload_delta_header_len..], payload.items);
        return frame;
    }

    fn applyPropertyPayloadDeltaEntryIndexed(
        allocator: std.mem.Allocator,
        target: PropertyPayloadIndexedTarget,
        record: PropertyPayloadIndexRecord,
        string_value: ?[]const u8,
    ) !void {
        const owner_key = PropertyPayloadOwnerKey{
            .owner_kind = record.owner_kind,
            .owner_id = record.owner_id,
            .key_hash = record.key_hash,
        };
        const existing_index = target.positions.get(owner_key);
        const old_len = if (existing_index) |index| blk: {
            if (index >= target.entries.items.len) return error.InvalidRecord;
            break :blk if (target.entries.items[index].value) |value| value.len else 0;
        } else 0;
        const next_budget_bytes = if (target.searchable_byte_budget) |budget|
            try budget.afterReplace(old_len, if (string_value) |value| value.len else 0)
        else
            0;
        const owned = if (string_value) |value| try allocator.dupe(u8, value) else null;
        errdefer if (owned) |value| allocator.free(value);
        if (existing_index) |index| {
            target.entries.items[index].deinit(allocator);
            target.entries.items[index] = .{ .record = record, .value = owned };
            if (target.searchable_byte_budget) |budget| budget.used_bytes = next_budget_bytes;
            return;
        }

        try target.entries.ensureUnusedCapacity(allocator, 1);
        const position = try target.positions.getOrPut(owner_key);
        if (position.found_existing) return error.InvalidRecord;
        position.value_ptr.* = target.entries.items.len;
        target.entries.appendAssumeCapacity(.{ .record = record, .value = owned });
        if (target.searchable_byte_budget) |budget| budget.used_bytes = next_budget_bytes;
    }

    fn applyPropertyPayloadDeltaEntryToSnapshot(
        allocator: std.mem.Allocator,
        target: PropertyPayloadSnapshotTarget,
        record: PropertyPayloadIndexRecord,
        string_value: ?[]const u8,
    ) !void {
        if (!target.owner_filter.matches(record.owner_kind, record.owner_id)) return;
        const value_kind: PropertySnapshotValueKind = switch (record.value_type) {
            PropertyPayloadIndexRecord.value_type_string => .string,
            PropertyPayloadIndexRecord.value_type_uint => .uint,
            else => return error.InvalidRecord,
        };
        const owned = if (value_kind == .string)
            try allocator.dupe(u8, string_value orelse return error.InvalidRecord)
        else
            &.{};
        errdefer if (value_kind == .string) allocator.free(owned);
        const replacement = PropertySnapshotEntry{
            .owner = try propertyPayloadOwnerFromParts(record.owner_kind, record.owner_id),
            .key_hash = record.key_hash,
            .value_kind = value_kind,
            .string_len = if (value_kind == .string) @intCast(owned.len) else 0,
            .string_value = owned,
            .uint_value = if (value_kind == .uint) record.value_hash else 0,
        };
        const owner_key = PropertyPayloadOwnerKey{
            .owner_kind = record.owner_kind,
            .owner_id = record.owner_id,
            .key_hash = record.key_hash,
        };
        if (target.positions.get(owner_key)) |position| {
            if (position >= target.entries.items.len) return error.InvalidRecord;
            if (target.entries.items[position].value_kind == .string) allocator.free(target.entries.items[position].string_value);
            target.entries.items[position] = replacement;
            return;
        }
        try target.entries.ensureUnusedCapacity(allocator, 1);
        const position = try target.positions.getOrPut(owner_key);
        if (position.found_existing) return error.InvalidRecord;
        position.value_ptr.* = target.entries.items.len;
        target.entries.appendAssumeCapacity(replacement);
    }

    fn parsePropertyPayloadDeltaPayload(
        allocator: std.mem.Allocator,
        header: PropertyPayloadDeltaHeader,
        payload: []const u8,
        target: PropertyPayloadDeltaTarget,
    ) !void {
        if (payload.len != header.payload_len or std.hash.Wyhash.hash(property_payload_delta_digest_seed, payload) != header.payload_digest) return error.InvalidRecord;
        const min_entry_bytes = property_payload_delta_entry_len + 1;
        if (header.write_count > payload.len / min_entry_bytes) return error.InvalidRecord;
        var frame_keys = PropertyPayloadOwnerKeySet.init(allocator);
        defer frame_keys.deinit();
        try frame_keys.ensureTotalCapacity(header.write_count);
        var offset: usize = 0;
        var write_index: u32 = 0;
        while (write_index < header.write_count) : (write_index += 1) {
            if (payload.len - offset < property_payload_delta_entry_len) return error.InvalidRecord;
            const raw = payload[offset..][0..property_payload_delta_entry_len];
            offset += property_payload_delta_entry_len;
            if (!allZero(raw[32..40])) return error.InvalidRecord;
            const owner_kind = raw[0];
            const value_type = raw[1];
            const key_len = readU16(raw[2..4]);
            const value_len = readU32(raw[4..8]);
            const owner_id = readU64(raw[8..16]);
            const key_hash = readU64(raw[16..24]);
            const value_hash = readU64(raw[24..32]);
            if ((owner_kind != PropertyPayloadIndexRecord.owner_kind_node and owner_kind != PropertyPayloadIndexRecord.owner_kind_edge) or
                (value_type != PropertyPayloadIndexRecord.value_type_string and value_type != PropertyPayloadIndexRecord.value_type_uint) or
                owner_id == 0 or owner_id == std.math.maxInt(u64) or key_len == 0)
            {
                return error.InvalidRecord;
            }
            const body_len = std.math.add(usize, key_len, value_len) catch return error.InvalidRecord;
            if (payload.len - offset < body_len) return error.InvalidRecord;
            const key = payload[offset..][0..key_len];
            const string_value = payload[offset + key_len .. offset + body_len];
            offset += body_len;
            if (!propertyKeyNameValid(key) or nodePropertyKeyHash(key) != key_hash) return error.InvalidRecord;
            const owner: PropertyOwner = if (owner_kind == PropertyPayloadIndexRecord.owner_kind_node)
                .{ .node = .fromInt(owner_id) }
            else
                .{ .edge = .fromInt(owner_id) };
            const frame_key = try frame_keys.getOrPut(.{
                .owner_kind = owner_kind,
                .owner_id = owner_id,
                .key_hash = key_hash,
            });
            if (frame_key.found_existing) return error.InvalidRecord;
            if (value_type == PropertyPayloadIndexRecord.value_type_string) {
                if (value_len == 0 or nodePropertyValueHash(string_value) != value_hash or !stringPropertyKeySupportedForOwner(owner, key)) return error.InvalidRecord;
            } else if (value_len != 0 or !uintPropertyKeySupportedForOwner(owner, key)) {
                return error.InvalidRecord;
            }
            const record = PropertyPayloadIndexRecord{
                .key_hash = key_hash,
                .value_hash = value_hash,
                .owner_id = owner_id,
                .owner_kind = owner_kind,
                .value_type = value_type,
            };
            switch (target) {
                .none => {},
                .all => |out| try applyPropertyPayloadDeltaEntryIndexed(
                    allocator,
                    out,
                    record,
                    if (value_type == PropertyPayloadIndexRecord.value_type_string) string_value else null,
                ),
                .searchable => |out| {
                    if (owner_kind == PropertyPayloadIndexRecord.owner_kind_node and
                        value_type == PropertyPayloadIndexRecord.value_type_string and
                        (std.mem.eql(u8, key, "name") or std.mem.eql(u8, key, "summary")))
                    {
                        try applyPropertyPayloadDeltaEntryIndexed(allocator, out, record, string_value);
                    }
                },
                .key => |lookup| {
                    if (lookup.key_hash == key_hash and std.mem.eql(u8, lookup.key_name, key)) {
                        if (lookup.owner_filter) |filter| {
                            if (!filter.matches(owner_kind, owner_id)) continue;
                        }
                        try applyPropertyPayloadDeltaEntryIndexed(
                            allocator,
                            .{ .entries = lookup.entries, .positions = lookup.positions },
                            record,
                            if (value_type == PropertyPayloadIndexRecord.value_type_string) string_value else null,
                        );
                    }
                },
                .snapshot => |lookup| {
                    const expected_name = lookup.key_names.get(key_hash) orelse continue;
                    if (!std.mem.eql(u8, expected_name, key)) continue;
                    try applyPropertyPayloadDeltaEntryToSnapshot(allocator, lookup, record, if (value_type == PropertyPayloadIndexRecord.value_type_string) string_value else null);
                },
                .existing_keys => |lookup| {
                    const owner_key = PropertyPayloadOwnerKey{
                        .owner_kind = owner_kind,
                        .owner_id = owner_id,
                        .key_hash = key_hash,
                    };
                    if (lookup.wanted.contains(owner_key)) try lookup.found.put(owner_key, {});
                },
                .lookup => |lookup| {
                    if (lookup.owner_key.owner_kind == owner_kind and
                        lookup.owner_key.owner_id == owner_id and
                        lookup.owner_key.key_hash == key_hash and
                        std.mem.eql(u8, lookup.key_name, key))
                    {
                        if (lookup.value) |*previous| previous.deinit(allocator);
                        const owned = if (value_type == PropertyPayloadIndexRecord.value_type_string)
                            try allocator.dupe(u8, string_value)
                        else
                            null;
                        lookup.value = .{ .record = record, .value = owned };
                    }
                },
                .layer_scan => |scan| {
                    if (scan.next_version.* == std.math.maxInt(u64)) return error.RecordTooLarge;
                    const version = scan.next_version.*;
                    scan.next_version.* += 1;
                    try scan.visit(scan.context, .{
                        .owner = owner,
                        .key_hash = key_hash,
                        .version = version,
                        .value_kind = if (value_type == PropertyPayloadIndexRecord.value_type_string) .string else .uint,
                        .string_value = if (value_type == PropertyPayloadIndexRecord.value_type_string) string_value else &.{},
                        .uint_value = if (value_type == PropertyPayloadIndexRecord.value_type_uint) value_hash else 0,
                    });
                },
            }
        }
        if (offset != payload.len) return error.InvalidRecord;
    }

    fn scanPropertyPayloadDelta(
        self: Store,
        allocator: std.mem.Allocator,
        target: PropertyPayloadDeltaTarget,
        allow_partial_tail: bool,
    ) !PropertyPayloadDeltaScan {
        return self.scanPropertyPayloadDeltaLimited(allocator, target, allow_partial_tail, null, .none);
    }

    fn scanPropertyPayloadDeltaLimited(
        self: Store,
        allocator: std.mem.Allocator,
        target: PropertyPayloadDeltaTarget,
        allow_partial_tail: bool,
        max_scan_bytes: ?u64,
        deadline: core.QueryDeadline,
    ) !PropertyPayloadDeltaScan {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        var file = std.Io.Dir.cwd().openFile(self.io, self.property_payload_delta_path, .{ .allow_directory = false }) catch |err| switch (err) {
            error.FileNotFound => return .{},
            else => |e| return e,
        };
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        // Capture and admit the complete scan range before reading the first
        // frame. A caller that promises bounded fallback I/O must never walk
        // a giant append-only delta and reject only after doing the work.
        // Later concurrent appends are outside this fixed snapshot range.
        if (max_scan_bytes) |limit| {
            if (file_size > limit) return error.SearchableMetadataBudgetExceeded;
        }
        var scan = PropertyPayloadDeltaScan{};
        while (scan.valid_bytes < file_size) {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const remaining = file_size - scan.valid_bytes;
            if (remaining < property_payload_delta_header_len) {
                if (!allow_partial_tail) return error.InvalidRecord;
                scan.trailing_partial = true;
                return scan;
            }
            var header_bytes: [property_payload_delta_header_len]u8 = undefined;
            const header_n = try file.readPositionalAll(self.io, &header_bytes, scan.valid_bytes);
            if (header_n != header_bytes.len) return error.InvalidRecord;
            const header = PropertyPayloadDeltaHeader.decode(&header_bytes) catch |err| {
                if (!allow_partial_tail) return err;
                scan.trailing_partial = true;
                return scan;
            };
            const frame_len = std.math.add(u64, property_payload_delta_header_len, header.payload_len) catch return error.InvalidRecord;
            if (remaining < frame_len) {
                if (!allow_partial_tail) return error.InvalidRecord;
                scan.trailing_partial = true;
                return scan;
            }
            if (header.sequence != std.math.add(u64, scan.last_sequence, 1) catch return error.InvalidRecord) {
                if (!allow_partial_tail) return error.InvalidRecord;
                scan.trailing_partial = true;
                return scan;
            }
            const payload = try allocator.alloc(u8, header.payload_len);
            defer allocator.free(payload);
            const payload_offset = std.math.add(u64, scan.valid_bytes, property_payload_delta_header_len) catch return error.InvalidRecord;
            const payload_n = try file.readPositionalAll(self.io, payload, payload_offset);
            if (payload_n != payload.len) return error.InvalidRecord;
            parsePropertyPayloadDeltaPayload(allocator, header, payload, target) catch |err| {
                if (!allow_partial_tail) return err;
                scan.trailing_partial = true;
                return scan;
            };
            scan.valid_bytes = std.math.add(u64, scan.valid_bytes, frame_len) catch return error.InvalidRecord;
            scan.last_sequence = header.sequence;
            scan.last_digest = header.payload_digest;
        }
        return scan;
    }

    fn propertyPayloadDeltaJournalPath(self: Store) ![]u8 {
        return try std.fmt.allocPrint(self.allocator, "{s}.redo", .{self.property_payload_delta_path});
    }

    fn writePropertyPayloadDeltaJournal(self: Store, frame: []const u8) !void {
        const journal_path = try self.propertyPayloadDeltaJournalPath();
        defer self.allocator.free(journal_path);
        const tmp_path = try self.tmpPathFor(journal_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            try file.writePositionalAll(self.io, frame, 0);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, journal_path);
    }

    fn deletePropertyPayloadDeltaJournal(self: Store) !void {
        const journal_path = try self.propertyPayloadDeltaJournalPath();
        defer self.allocator.free(journal_path);
        try std.Io.Dir.cwd().deleteFile(self.io, journal_path);
        try self.syncParentDirForPath(journal_path);
    }

    fn appendPropertyPayloadDeltaFrame(self: Store, frame: []const u8, expected_offset: u64) !void {
        const existed = try self.fileExists(self.property_payload_delta_path);
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, self.property_payload_delta_path, .{ .read = true, .truncate = false });
            defer file.close(self.io);
            if (try self.regularFileSize(file) != expected_offset) return error.InvalidRecord;
            try file.writePositionalAll(self.io, frame, expected_offset);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        if (!existed) try self.syncParentDirForPath(self.property_payload_delta_path);
    }

    fn recoverPropertyPayloadDeltaJournal(self: Store) !PropertyPayloadDeltaRecovery {
        const journal_path = try self.propertyPayloadDeltaJournalPath();
        defer self.allocator.free(journal_path);
        const frame = std.Io.Dir.cwd().readFileAlloc(self.io, journal_path, self.allocator, .limited(property_payload_delta_header_len + property_payload_delta_max_frame_bytes)) catch |err| switch (err) {
            // With no redo there is no interrupted append to recover. Do not
            // eagerly walk the complete append-only delta on every Store.open:
            // every property read, write and compaction path validates the
            // full frame sequence before returning data or mutating it. This
            // keeps corruption fail-closed at first use without making an
            // unrelated node/edge-only CLI command pay O(delta) startup I/O.
            error.FileNotFound => return .no_journal,
            else => |e| return e,
        };
        defer self.allocator.free(frame);
        if (frame.len < property_payload_delta_header_len) return error.InvalidRecord;
        var header_bytes: [property_payload_delta_header_len]u8 = undefined;
        @memcpy(&header_bytes, frame[0..property_payload_delta_header_len]);
        const header = try PropertyPayloadDeltaHeader.decode(&header_bytes);
        if (frame.len != property_payload_delta_header_len + header.payload_len) return error.InvalidRecord;
        try parsePropertyPayloadDeltaPayload(self.allocator, header, frame[property_payload_delta_header_len..], .none);

        var scan = try self.scanPropertyPayloadDelta(self.allocator, .none, true);
        if (scan.trailing_partial) {
            if (header.sequence != std.math.add(u64, scan.last_sequence, 1) catch return error.InvalidRecord) return error.InvalidRecord;
            {
                var delta = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_delta_path, .{ .mode = .read_write, .allow_directory = false });
                defer delta.close(self.io);
                const delta_len = try self.regularFileSize(delta);
                if (delta_len < scan.valid_bytes) return error.InvalidRecord;
                const tail_len_u64 = delta_len - scan.valid_bytes;
                if (tail_len_u64 > frame.len) return error.InvalidRecord;
                const tail_len: usize = @intCast(tail_len_u64);
                const tail = try self.allocator.alloc(u8, tail_len);
                defer self.allocator.free(tail);
                const tail_n = try delta.readPositionalAll(self.io, tail, scan.valid_bytes);
                if (tail_n != tail.len or !std.mem.eql(u8, tail, frame[0..tail.len])) return error.InvalidRecord;
                try delta.setLength(self.io, scan.valid_bytes);
                if (selfOptionsNeedSync(self)) try delta.sync(self.io);
            }
            scan.trailing_partial = false;
        }
        if (scan.last_sequence == header.sequence) {
            if (scan.last_digest != header.payload_digest or scan.valid_bytes < frame.len) return error.InvalidRecord;
            var delta = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_delta_path, .{ .mode = .read_write, .allow_directory = false });
            defer delta.close(self.io);
            const frame_offset = scan.valid_bytes - frame.len;
            const published = try self.allocator.alloc(u8, frame.len);
            defer self.allocator.free(published);
            const published_n = try delta.readPositionalAll(self.io, published, frame_offset);
            if (published_n != published.len or !std.mem.eql(u8, published, frame)) return error.InvalidRecord;
            // A prior append may have returned from fsync with an error after
            // all bytes reached the page cache.  Exact byte equality proves
            // identity, not durability: retry fsync before deleting the only
            // durable redo copy.
            if (selfOptionsNeedSync(self)) try delta.sync(self.io);
        } else {
            if (header.sequence != std.math.add(u64, scan.last_sequence, 1) catch return error.InvalidRecord) return error.InvalidRecord;
            try self.appendPropertyPayloadDeltaFrame(frame, scan.valid_bytes);
        }
        // Recovery is not complete until the redo name is durably removed.
        // Leaving it behind is normally harmless while the matching delta is
        // still present, but compaction may subsequently publish the merged
        // base and unlink that delta.  A stale redo would then be replayed
        // against an empty delta (or reject the store when its sequence is
        // greater than one).  Propagate cleanup failure so maintenance cannot
        // cross that unsafe boundary.
        try self.deletePropertyPayloadDeltaJournal();
        return .committed;
    }

    fn publishPropertyPayloadDelta(
        self: Store,
        allocator: std.mem.Allocator,
        writes: []const PropertyPayloadWrite,
        scan: PropertyPayloadDeltaScan,
    ) !void {
        if (scan.trailing_partial) return error.InvalidRecord;
        const sequence = std.math.add(u64, scan.last_sequence, 1) catch return error.RecordTooLarge;
        const frame = try self.encodePropertyPayloadDeltaFrame(allocator, sequence, writes);
        defer allocator.free(frame);
        try self.writePropertyPayloadDeltaJournal(frame);
        self.appendPropertyPayloadDeltaFrame(frame, scan.valid_bytes) catch |err| {
            const recovery = self.recoverPropertyPayloadDeltaJournal() catch |recovery_err| return recovery_err;
            if (recovery == .committed) return;
            return err;
        };
        // A deletion whose parent-directory sync fails is not safely
        // ignorable: the redo name can reappear after a crash.  If a caller
        // then compacts and removes the matching delta, that resurrected redo
        // is no longer idempotent against the empty sequence.  Surface the
        // post-commit cleanup error so one-shot CLI writers stop before
        // entering maintenance; Store.open recovery remains retryable.
        try self.deletePropertyPayloadDeltaJournal();
    }

    fn propertyPayloadRedoJournalPath(self: Store) ![]u8 {
        return try std.fmt.allocPrint(self.allocator, "{s}.redo", .{self.property_payload_index_path});
    }

    fn appendFileToJournal(
        self: Store,
        source: std.Io.File,
        source_len: u64,
        writer: *StorageBufferedWriter,
        hasher: *std.hash.Wyhash,
    ) !void {
        var offset: u64 = 0;
        var buffer: [storage_write_buffer_bytes]u8 = undefined;
        while (offset < source_len) {
            const remaining = source_len - offset;
            const chunk_len: usize = @intCast(@min(remaining, buffer.len));
            const chunk = buffer[0..chunk_len];
            const n = try source.readPositionalAll(self.io, chunk, offset);
            if (n != chunk.len) return error.InvalidRecord;
            hasher.update(chunk);
            try writer.append(chunk);
            offset = std.math.add(u64, offset, chunk.len) catch return error.RecordTooLarge;
        }
    }

    fn writePropertyPayloadRedoJournal(self: Store, index_stage_path: []const u8, values_stage_path: []const u8) !void {
        var index_file = try std.Io.Dir.cwd().openFile(self.io, index_stage_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const index_len = try self.regularFileSize(index_file);
        var values_file = try std.Io.Dir.cwd().openFile(self.io, values_stage_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_len = try self.regularFileSize(values_file);
        const body_len = std.math.add(u64, index_len, values_len) catch return error.RecordTooLarge;
        const journal_len = std.math.add(u64, PropertyPayloadRedoJournalHeader.encoded_len, body_len) catch return error.RecordTooLarge;

        const journal_path = try self.propertyPayloadRedoJournalPath();
        defer self.allocator.free(journal_path);
        const tmp_path = try self.tmpPathFor(journal_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var journal_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer journal_file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, journal_file, try storageWriteBufferCapacity(journal_len));
            defer writer.deinit();
            var placeholder: [PropertyPayloadRedoJournalHeader.encoded_len]u8 = [_]u8{0} ** PropertyPayloadRedoJournalHeader.encoded_len;
            try writer.append(&placeholder);
            var index_hasher = std.hash.Wyhash.init(0x544B_504A);
            var values_hasher = std.hash.Wyhash.init(0x544B_504A);
            try self.appendFileToJournal(index_file, index_len, &writer, &index_hasher);
            try self.appendFileToJournal(values_file, values_len, &writer, &values_hasher);
            try writer.flush();

            const header = PropertyPayloadRedoJournalHeader{
                .index_len = index_len,
                .values_len = values_len,
                .index_digest = index_hasher.final(),
                .values_digest = values_hasher.final(),
            };
            var header_bytes: [PropertyPayloadRedoJournalHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try journal_file.writePositionalAll(self.io, &header_bytes, 0);
            if (try self.regularFileSize(journal_file) != journal_len) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try journal_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, journal_path);
    }

    fn restorePropertyPayloadJournalRange(
        self: Store,
        journal_file: std.Io.File,
        journal_offset: u64,
        byte_len: u64,
        expected_digest: u64,
        stage_path: []const u8,
    ) !void {
        var stage_file = try std.Io.Dir.cwd().createFile(self.io, stage_path, .{ .read = true, .truncate = true });
        defer stage_file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, stage_file, try storageWriteBufferCapacity(byte_len));
        defer writer.deinit();
        var hasher = std.hash.Wyhash.init(0x544B_504A);
        var copied: u64 = 0;
        var buffer: [storage_write_buffer_bytes]u8 = undefined;
        while (copied < byte_len) {
            const remaining = byte_len - copied;
            const chunk_len: usize = @intCast(@min(remaining, buffer.len));
            const chunk = buffer[0..chunk_len];
            const offset = std.math.add(u64, journal_offset, copied) catch return error.InvalidRecord;
            const n = try journal_file.readPositionalAll(self.io, chunk, offset);
            if (n != chunk.len) return error.InvalidRecord;
            hasher.update(chunk);
            try writer.append(chunk);
            copied = std.math.add(u64, copied, chunk.len) catch return error.RecordTooLarge;
        }
        try writer.flush();
        if (hasher.final() != expected_digest) return error.InvalidRecord;
        if (try self.regularFileSize(stage_file) != byte_len) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try stage_file.sync(self.io);
    }

    fn recoverPropertyPayloadRedoJournal(self: Store) !void {
        const journal_path = try self.propertyPayloadRedoJournalPath();
        defer self.allocator.free(journal_path);
        var journal_file = std.Io.Dir.cwd().openFile(self.io, journal_path, .{ .allow_directory = false }) catch |err| switch (err) {
            error.FileNotFound => return,
            else => |e| return e,
        };
        var journal_file_open = true;
        defer if (journal_file_open) journal_file.close(self.io);
        const journal_size = try self.regularFileSize(journal_file);
        var header_bytes: [PropertyPayloadRedoJournalHeader.encoded_len]u8 = undefined;
        const header_n = try journal_file.readPositionalAll(self.io, &header_bytes, 0);
        if (header_n != header_bytes.len) return error.InvalidRecord;
        const header = try PropertyPayloadRedoJournalHeader.decode(&header_bytes);
        const body_len = std.math.add(u64, header.index_len, header.values_len) catch return error.InvalidRecord;
        const expected_size = std.math.add(u64, PropertyPayloadRedoJournalHeader.encoded_len, body_len) catch return error.InvalidRecord;
        if (journal_size != expected_size) return error.InvalidRecord;

        const index_tmp_path = try self.tmpPathFor(self.property_payload_index_path);
        defer self.allocator.free(index_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, index_tmp_path) catch {};
        const values_tmp_path = try self.tmpPathFor(self.property_payload_values_path);
        defer self.allocator.free(values_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, values_tmp_path) catch {};
        try self.restorePropertyPayloadJournalRange(
            journal_file,
            PropertyPayloadRedoJournalHeader.encoded_len,
            header.index_len,
            header.index_digest,
            index_tmp_path,
        );
        const values_offset = std.math.add(u64, PropertyPayloadRedoJournalHeader.encoded_len, header.index_len) catch return error.InvalidRecord;
        try self.restorePropertyPayloadJournalRange(
            journal_file,
            values_offset,
            header.values_len,
            header.values_digest,
            values_tmp_path,
        );
        journal_file.close(self.io);
        journal_file_open = false;
        var validated = try self.readPropertyPayloadEntriesFromFiles(self.allocator, index_tmp_path, values_tmp_path);
        defer {
            deinitPropertyPayloadIndexEntries(validated.items, self.allocator);
            validated.deinit(self.allocator);
        }
        try self.renameReplace(values_tmp_path, self.property_payload_values_path);
        try self.renameReplace(index_tmp_path, self.property_payload_index_path);
        try std.Io.Dir.cwd().deleteFile(self.io, journal_path);
        try self.syncParentDirForPath(journal_path);
    }

    fn deletePropertyPayloadRedoJournal(self: Store) !void {
        const journal_path = try self.propertyPayloadRedoJournalPath();
        defer self.allocator.free(journal_path);
        try std.Io.Dir.cwd().deleteFile(self.io, journal_path);
        try self.syncParentDirForPath(journal_path);
    }

    fn writePropertyPayloadIndexFiles(self: Store, index_path: []const u8, values_path: []const u8, entries: []PropertyPayloadIndexEntry) !void {
        std.mem.sort(PropertyPayloadIndexEntry, entries, {}, propertyPayloadEntryLessThan);
        const index_tmp_path = try self.tmpPathFor(index_path);
        defer self.allocator.free(index_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, index_tmp_path) catch {};
        const values_tmp_path = try self.tmpPathFor(values_path);
        defer self.allocator.free(values_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, values_tmp_path) catch {};

        try self.writePropertyPayloadIndexStage(index_tmp_path, entries);
        try self.writePropertyPayloadValueStage(values_tmp_path, entries);
        try self.writePropertyPayloadRedoJournal(index_tmp_path, values_tmp_path);

        // Once the redo journal is durable, either this writer or Store.open
        // can finish the pair.  The journal is deleted only after both names
        // refer to the same generation.
        try self.renameReplace(values_tmp_path, values_path);
        try self.renameReplace(index_tmp_path, index_path);
        // Do not let this Store instance continue after a cleanup failure.
        // Although replaying this redo is idempotent against the base that was
        // just published, a later compaction or delta append in the same
        // process could advance the store.  A resurrected stale redo would
        // then roll that newer base back on the next open.  Propagating the
        // post-commit error keeps the old delta intact and makes recovery
        // retryable without acknowledged-data loss.
        try self.deletePropertyPayloadRedoJournal();
    }

    fn writePropertyPayloadIndexStage(self: Store, path: []const u8, entries: []const PropertyPayloadIndexEntry) !void {
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        const file_size = try propertyPayloadIndexFileSize(@intCast(entries.len));
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(file_size));
        defer writer.deinit();
        const header = PropertyPayloadIndexHeader{
            .record_count = @intCast(entries.len),
            .owner_count = 0,
            .owner_digest = 0,
        };
        var header_bytes: [PropertyPayloadIndexHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try writer.append(&header_bytes);
        var previous: ?PropertyPayloadIndexRecord = null;
        for (entries) |entry| {
            const record = entry.record;
            if (previous) |prev| {
                if (!propertyPayloadRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            var record_bytes: [PropertyPayloadIndexRecord.encoded_len]u8 = undefined;
            try record.encode(&record_bytes);
            try writer.append(&record_bytes);
            previous = record;
        }
        try writer.flush();
        if (try self.regularFileSize(file) != file_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn writePropertyPayloadValueStage(self: Store, path: []const u8, entries: []const PropertyPayloadIndexEntry) !void {
        const value_records = try self.allocator.alloc(NodePropertyValueRecord, entries.len);
        defer self.allocator.free(value_records);
        var payload_bytes: u64 = 0;
        var payload_digest: u64 = 0;
        var digest_bytes: [8]u8 = undefined;
        for (entries, 0..) |entry, i| {
            if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_string) {
                const value = entry.value orelse return error.InvalidRecord;
                if (value.len == 0 or nodePropertyValueHash(value) != entry.record.value_hash) return error.InvalidRecord;
                const len_u32 = std.math.cast(u32, value.len) orelse return error.RecordTooLarge;
                value_records[i] = .{ .offset = payload_bytes, .len = len_u32 };
                std.mem.writeInt(u64, &digest_bytes, entry.record.key_hash, .little);
                payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, &digest_bytes);
                std.mem.writeInt(u64, &digest_bytes, entry.record.value_hash, .little);
                payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, &digest_bytes);
                payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, value);
                payload_bytes = std.math.add(u64, payload_bytes, value.len) catch return error.RecordTooLarge;
            } else if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_uint) {
                if (entry.value != null) return error.InvalidRecord;
                value_records[i] = .{ .offset = 0, .len = 0 };
            } else {
                return error.InvalidRecord;
            }
        }
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        const file_size = try nodePropertyValueBlockFileSize(@intCast(entries.len), payload_bytes);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(file_size));
        defer writer.deinit();
        const header = NodePropertyValueBlockHeader{
            .record_count = @intCast(entries.len),
            .node_count = 0,
            .node_digest = 0,
            .payload_bytes = payload_bytes,
            .payload_digest = payload_digest,
        };
        var header_bytes: [NodePropertyValueBlockHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try writer.append(&header_bytes);
        var value_record_bytes: [NodePropertyValueRecord.encoded_len]u8 = undefined;
        for (value_records) |record| {
            record.encode(&value_record_bytes);
            try writer.append(&value_record_bytes);
        }
        for (entries) |entry| {
            if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_string) {
                try writer.append(entry.value.?);
            }
        }
        try writer.flush();
        if (try self.regularFileSize(file) != file_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn readNodePropertyIndexEntriesForMeta(self: Store, allocator: std.mem.Allocator, meta: IndexMeta) !std.ArrayList(NodePropertyIndexEntry) {
        return try self.readNodePropertyIndexEntriesFromFiles(allocator, self.node_props_index_path, self.node_props_values_path, meta);
    }

    fn readNodePropertyIndexEntriesFromFiles(self: Store, allocator: std.mem.Allocator, index_path: []const u8, values_path: []const u8, meta: IndexMeta) !std.ArrayList(NodePropertyIndexEntry) {
        var file = try std.Io.Dir.cwd().openFile(self.io, index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;
        var entries = std.ArrayList(NodePropertyIndexEntry).empty;
        errdefer {
            deinitNodePropertyIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        try entries.ensureTotalCapacity(allocator, std.math.cast(usize, header.record_count) orelse return error.RecordTooLarge);
        var values_file = try std.Io.Dir.cwd().openFile(self.io, values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != meta.nodes or values_header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;
        var previous: ?NodePropertyIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readNodePropertyIndexRecordAt(file, index);
            if (previous) |prev| {
                if (!nodePropertyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            const value = try self.readNodePropertyValuePayloadAt(allocator, values_file, values_header, index, record);
            entries.appendAssumeCapacity(.{ .record = record, .value = value });
            previous = record;
        }
        return entries;
    }

    fn readPropertyPayloadEntriesFromFiles(self: Store, allocator: std.mem.Allocator, index_path: []const u8, values_path: []const u8) !std.ArrayList(PropertyPayloadIndexEntry) {
        var file = try std.Io.Dir.cwd().openFile(self.io, index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readPropertyPayloadIndexHeaderFromFile(file);
        if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;
        var entries = std.ArrayList(PropertyPayloadIndexEntry).empty;
        errdefer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        try entries.ensureTotalCapacity(allocator, std.math.cast(usize, header.record_count) orelse return error.RecordTooLarge);
        var values_file = try std.Io.Dir.cwd().openFile(self.io, values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;
        var previous: ?PropertyPayloadIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readPropertyPayloadIndexRecordAt(file, index);
            if (previous) |prev| {
                if (!propertyPayloadRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            const value = try self.readPropertyPayloadValuePayloadAt(allocator, values_file, values_header, index, record);
            entries.appendAssumeCapacity(.{ .record = record, .value = value });
            previous = record;
        }
        return entries;
    }

    fn nodePropertyOverlayMeta() IndexMeta {
        return .{};
    }

    fn readNodePropertyOverlayEntriesOrEmpty(self: Store, allocator: std.mem.Allocator) !std.ArrayList(NodePropertyIndexEntry) {
        const has_index = try self.fileExists(self.node_props_overlay_index_path);
        const has_values = try self.fileExists(self.node_props_overlay_values_path);
        if (!has_index and !has_values) return std.ArrayList(NodePropertyIndexEntry).empty;
        if (has_index != has_values) return error.InvalidRecord;
        return try self.readNodePropertyIndexEntriesFromFiles(allocator, self.node_props_overlay_index_path, self.node_props_overlay_values_path, nodePropertyOverlayMeta());
    }

    fn readNodePropertyOverlayEntriesForKeyOrEmpty(
        self: Store,
        allocator: std.mem.Allocator,
        index_path: []const u8,
        values_path: []const u8,
        key: []const u8,
    ) !std.ArrayList(NodePropertyIndexEntry) {
        return try self.readNodePropertyOverlayEntriesForKeyOwnersOrEmpty(allocator, index_path, values_path, key, null);
    }

    fn readNodePropertyOverlayEntriesForKeyOwnersOrEmpty(
        self: Store,
        allocator: std.mem.Allocator,
        index_path: []const u8,
        values_path: []const u8,
        key: []const u8,
        wanted_node_ids: ?*const PropertyPayloadNodeIdSet,
    ) !std.ArrayList(NodePropertyIndexEntry) {
        const has_index = try self.fileExists(index_path);
        const has_values = try self.fileExists(values_path);
        if (!has_index and !has_values) return std.ArrayList(NodePropertyIndexEntry).empty;
        if (has_index != has_values) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().openFile(self.io, index_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(index_file);
        if (header.node_count != 0 or header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(index_file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;

        var values_file = try std.Io.Dir.cwd().openFile(self.io, values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

        var entries = std.ArrayList(NodePropertyIndexEntry).empty;
        errdefer {
            deinitNodePropertyIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        const key_hash = nodePropertyKeyHash(key);
        var index = try self.nodePropertyIndexLowerBound(index_file, header, key_hash, 0, 0);
        while (index < header.record_count) : (index += 1) {
            const record = try self.readNodePropertyIndexRecordAt(index_file, index);
            if (record.key_hash != key_hash) break;
            if (wanted_node_ids) |wanted| {
                if (!wanted.contains(record.node_id)) continue;
            }
            const value = try self.readNodePropertyValuePayloadAt(allocator, values_file, values_header, index, record);
            errdefer if (value) |owned| allocator.free(owned);
            try entries.append(allocator, .{ .record = record, .value = value });
        }
        return entries;
    }

    fn writeNodePropertyOverlay(self: Store, entries: []NodePropertyIndexEntry) !void {
        try self.writeNodePropertyIndexFiles(self.node_props_overlay_index_path, self.node_props_overlay_values_path, entries, nodePropertyOverlayMeta());
    }

    fn readEdgePropertyOverlayEntriesOrEmpty(self: Store, allocator: std.mem.Allocator) !std.ArrayList(NodePropertyIndexEntry) {
        const has_index = try self.fileExists(self.edge_props_overlay_index_path);
        const has_values = try self.fileExists(self.edge_props_overlay_values_path);
        if (!has_index and !has_values) return std.ArrayList(NodePropertyIndexEntry).empty;
        if (has_index != has_values) return error.InvalidRecord;
        return try self.readNodePropertyIndexEntriesFromFiles(allocator, self.edge_props_overlay_index_path, self.edge_props_overlay_values_path, nodePropertyOverlayMeta());
    }

    fn writeEdgePropertyOverlay(self: Store, entries: []NodePropertyIndexEntry) !void {
        try self.writeNodePropertyIndexFiles(self.edge_props_overlay_index_path, self.edge_props_overlay_values_path, entries, nodePropertyOverlayMeta());
    }

    fn readPropertyPayloadEntriesOrEmpty(self: Store, allocator: std.mem.Allocator) !std.ArrayList(PropertyPayloadIndexEntry) {
        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        var entries = if (!has_index and !has_values)
            std.ArrayList(PropertyPayloadIndexEntry).empty
        else blk: {
            if (has_index != has_values) return error.InvalidRecord;
            break :blk try self.readPropertyPayloadEntriesFromFiles(allocator, self.property_payload_index_path, self.property_payload_values_path);
        };
        errdefer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        var positions = std.AutoHashMap(PropertyPayloadOwnerKey, usize).init(allocator);
        defer positions.deinit();
        try positions.ensureTotalCapacity(std.math.cast(u32, entries.items.len) orelse return error.RecordTooLarge);
        for (entries.items, 0..) |entry, index| {
            const position = try positions.getOrPut(.{
                .owner_kind = entry.record.owner_kind,
                .owner_id = entry.record.owner_id,
                .key_hash = entry.record.key_hash,
            });
            if (position.found_existing) return error.InvalidRecord;
            position.value_ptr.* = index;
        }
        _ = try self.scanPropertyPayloadDelta(allocator, .{ .all = .{
            .entries = &entries,
            .positions = &positions,
        } }, false);
        std.mem.sort(PropertyPayloadIndexEntry, entries.items, {}, propertyPayloadEntryLessThan);
        return entries;
    }

    /// Read only one persisted property key. The immutable base is ordered by
    /// key hash, so unrelated values (which may be very large blobs) are never
    /// materialized. Delta frames still have to be validated sequentially,
    /// but only exact persisted key names are retained and latest-wins updates
    /// are applied in O(1) per matching owner instead of rescanning the list.
    fn readPropertyPayloadEntriesForKeyOrEmpty(self: Store, allocator: std.mem.Allocator, key: []const u8) !std.ArrayList(PropertyPayloadIndexEntry) {
        return try self.readPropertyPayloadEntriesForKeyOwnersOrEmpty(allocator, key, null, true);
    }

    fn readPropertyPayloadEntriesForKeyOwnersOrEmpty(
        self: Store,
        allocator: std.mem.Allocator,
        key: []const u8,
        owner_filter: ?PropertyPayloadOwnerFilter,
        include_delta: bool,
    ) !std.ArrayList(PropertyPayloadIndexEntry) {
        var entries = std.ArrayList(PropertyPayloadIndexEntry).empty;
        errdefer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        var positions = std.AutoHashMap(PropertyPayloadOwnerKey, usize).init(allocator);
        defer positions.deinit();

        const key_hash = nodePropertyKeyHash(key);
        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (has_index != has_values) return error.InvalidRecord;
        if (has_index) {
            var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
            defer index_file.close(self.io);
            const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
            if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;
            try self.validatePropertyPayloadIndexOrderIfStrict(index_file, header);

            var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
            defer values_file.close(self.io);
            const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
            if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

            var index = try self.propertyPayloadKeyHashLowerBound(index_file, header.record_count, key_hash);
            while (index < header.record_count) : (index += 1) {
                const record = try self.readPropertyPayloadIndexRecordAt(index_file, index);
                if (record.key_hash != key_hash) break;
                if (owner_filter) |filter| {
                    if (!filter.matches(record.owner_kind, record.owner_id)) continue;
                }
                const owner_key = PropertyPayloadOwnerKey{
                    .owner_kind = record.owner_kind,
                    .owner_id = record.owner_id,
                    .key_hash = record.key_hash,
                };
                const position = try positions.getOrPut(owner_key);
                if (position.found_existing) return error.InvalidRecord;
                const value = try self.readPropertyPayloadValuePayloadAt(allocator, values_file, values_header, index, record);
                errdefer if (value) |owned| allocator.free(owned);
                try entries.append(allocator, .{ .record = record, .value = value });
                position.value_ptr.* = entries.items.len - 1;
            }
        }

        if (include_delta) {
            _ = try self.scanPropertyPayloadDelta(allocator, .{ .key = .{
                .key_hash = key_hash,
                .key_name = key,
                .entries = &entries,
                .positions = &positions,
                .owner_filter = owner_filter,
            } }, false);
        }
        std.mem.sort(PropertyPayloadIndexEntry, entries.items, {}, propertyPayloadEntryLessThan);
        return entries;
    }

    /// Materialize only node `name`/`summary` values.  Full-text stale-index
    /// fallback must not allocate unrelated property blobs merely to compute
    /// its metadata digest or snapshot.
    fn readSearchablePropertyPayloadEntriesOrEmpty(
        self: Store,
        allocator: std.mem.Allocator,
        byte_budget: ?*SearchablePropertyByteBudget,
        delta_scan_byte_budget: ?u64,
        deadline: core.QueryDeadline,
    ) !std.ArrayList(PropertyPayloadIndexEntry) {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        var entries = std.ArrayList(PropertyPayloadIndexEntry).empty;
        errdefer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        var positions = std.AutoHashMap(PropertyPayloadOwnerKey, usize).init(allocator);
        defer positions.deinit();
        // The common steady state has an immutable base and no delta. Keep
        // metadata digest/snapshot reads within their tiny allocation budget;
        // the owner-key map is needed only when latest-wins delta records can
        // actually replace base entries. `pathExists` intentionally preserves
        // directories/other invalid path kinds so the scan below still fails
        // closed instead of treating corruption as an absent delta.
        const has_delta = try self.pathExists(self.property_payload_delta_path);

        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (has_index != has_values) return error.InvalidRecord;
        if (has_index) {
            var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
            defer index_file.close(self.io);
            const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
            if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;
            try self.validatePropertyPayloadIndexOrderIfStrictDeadline(index_file, header, deadline);

            var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
            defer values_file.close(self.io);
            const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
            if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

            // The immutable index is ordered by key hash.  Stale-text checks
            // need only `name` and `summary`; walking every unrelated
            // lifecycle/blob property made a quick search-open O(all
            // properties).  Probe the two contiguous ranges directly while
            // retaining the same record/value validation for every selected
            // entry.  Full-file validation remains the responsibility of
            // maintenance and readers that actually consume the other keys.
            const searchable_hashes = [_]u64{
                nodePropertyKeyHash("name"),
                nodePropertyKeyHash("summary"),
            };
            if (searchable_hashes[0] == searchable_hashes[1]) return error.InvalidRecord;
            for (searchable_hashes) |key_hash| {
                var previous: ?PropertyPayloadIndexRecord = null;
                var index = try self.propertyPayloadKeyHashLowerBound(index_file, header.record_count, key_hash);
                while (index < header.record_count) : (index += 1) {
                    if (deadline.expired()) return core.Error.BudgetExceeded;
                    const record = try self.readPropertyPayloadIndexRecordAt(index_file, index);
                    if (record.key_hash != key_hash) break;
                    if (previous) |prev| {
                        if (!propertyPayloadRecordLessThan({}, prev, record)) return error.InvalidRecord;
                    }
                    const value_record = try self.readNodePropertyValueRecordAt(values_file, index);
                    if (record.value_type == PropertyPayloadIndexRecord.value_type_uint) {
                        if (value_record.offset != 0 or value_record.len != 0) return error.InvalidRecord;
                    } else if (record.value_type == PropertyPayloadIndexRecord.value_type_string) {
                        if (value_record.len == 0) return error.InvalidRecord;
                        const payload_end = std.math.add(u64, value_record.offset, value_record.len) catch return error.InvalidRecord;
                        if (payload_end > values_header.payload_bytes) return error.InvalidRecord;
                        if (record.owner_kind == PropertyPayloadIndexRecord.owner_kind_node) {
                            const next_budget_bytes = if (byte_budget) |budget|
                                try budget.afterReplace(0, @intCast(value_record.len))
                            else
                                0;
                            const value = (try self.readPropertyPayloadValuePayloadAt(allocator, values_file, values_header, index, record)) orelse return error.InvalidRecord;
                            errdefer allocator.free(value);
                            const position = if (has_delta) try positions.getOrPut(.{
                                .owner_kind = record.owner_kind,
                                .owner_id = record.owner_id,
                                .key_hash = record.key_hash,
                            }) else null;
                            if (position) |entry| {
                                if (entry.found_existing) return error.InvalidRecord;
                            }
                            try entries.append(allocator, .{ .record = record, .value = value });
                            if (position) |entry| entry.value_ptr.* = entries.items.len - 1;
                            if (byte_budget) |budget| budget.used_bytes = next_budget_bytes;
                        }
                    } else {
                        return error.InvalidRecord;
                    }
                    previous = record;
                }
            }
        }

        if (has_delta) {
            _ = try self.scanPropertyPayloadDeltaLimited(allocator, .{ .searchable = .{
                .entries = &entries,
                .positions = &positions,
                .searchable_byte_budget = byte_budget,
            } }, false, delta_scan_byte_budget, deadline);
        }
        std.mem.sort(PropertyPayloadIndexEntry, entries.items, {}, propertyPayloadEntryLessThan);
        return entries;
    }

    fn addSearchableNodeMetadataDigest(
        digest: *u64,
        seed: u64,
        owner_id: u64,
        key_hash: u64,
        value_hash: u64,
        value: []const u8,
    ) void {
        var entry_hasher = std.hash.Wyhash.init(seed);
        var bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &bytes, owner_id, .little);
        entry_hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, key_hash, .little);
        entry_hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, value_hash, .little);
        entry_hasher.update(&bytes);
        entry_hasher.update(value);
        // Records are stored in multiple ordered physical layers, but the
        // stale anchor should not depend on traversal order. Hash each full
        // association first, then combine record digests commutatively.
        // Hashing tuple fields independently would make swapping two values
        // between owners invisible because every component still appears in
        // the same XOR multiset.
        digest.* ^= entry_hasher.final();
    }

    fn addSearchableNodeMetadataDigestFromValueFile(
        self: Store,
        digest: *u64,
        seed: u64,
        owner_id: u64,
        key_hash: u64,
        value_hash: u64,
        file: std.Io.File,
        file_offset: u64,
        value_len: u32,
        deadline: core.QueryDeadline,
    ) !void {
        var entry_hasher = std.hash.Wyhash.init(seed);
        var bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &bytes, owner_id, .little);
        entry_hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, key_hash, .little);
        entry_hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, value_hash, .little);
        entry_hasher.update(&bytes);

        var value_hasher = std.hash.Wyhash.init(0x544B_5056);
        var scratch: [16 * 1024]u8 = undefined;
        var consumed: u64 = 0;
        while (consumed < value_len) {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const remaining = @as(u64, value_len) - consumed;
            const take: usize = @intCast(@min(remaining, scratch.len));
            const offset = std.math.add(u64, file_offset, consumed) catch return error.InvalidRecord;
            const n = try file.readPositionalAll(self.io, scratch[0..take], offset);
            if (n != take) return error.InvalidRecord;
            value_hasher.update(scratch[0..take]);
            entry_hasher.update(scratch[0..take]);
            consumed += take;
        }
        if (value_hasher.final() != value_hash) return error.InvalidRecord;
        digest.* ^= entry_hasher.final();
    }

    fn searchableNodeCanonicalBaseMetadataDigest(
        self: Store,
        overridden: ?*const std.AutoHashMap(PropertyPayloadOwnerKey, usize),
        deadline: core.QueryDeadline,
    ) !u64 {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (!has_index and !has_values) return 0;
        if (has_index != has_values) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
        if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;
        try self.validatePropertyPayloadIndexOrderIfStrictDeadline(index_file, header, deadline);

        var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;
        const payload_start = try nodePropertyValueBlockHeaderAndRecordBytes(values_header.record_count);

        const searchable_hashes = [_]u64{
            nodePropertyKeyHash("name"),
            nodePropertyKeyHash("summary"),
        };
        if (searchable_hashes[0] == searchable_hashes[1]) return error.InvalidRecord;
        var digest: u64 = 0;
        for (searchable_hashes) |key_hash| {
            var previous: ?PropertyPayloadIndexRecord = null;
            var index = try self.propertyPayloadKeyHashLowerBound(index_file, header.record_count, key_hash);
            while (index < header.record_count) : (index += 1) {
                if (deadline.expired()) return core.Error.BudgetExceeded;
                const record = try self.readPropertyPayloadIndexRecordAt(index_file, index);
                if (record.key_hash != key_hash) break;
                if (previous) |prev| {
                    if (!propertyPayloadRecordLessThan({}, prev, record)) return error.InvalidRecord;
                }
                const value_record = try self.readNodePropertyValueRecordAt(values_file, index);
                if (record.value_type == PropertyPayloadIndexRecord.value_type_uint) {
                    if (value_record.offset != 0 or value_record.len != 0) return error.InvalidRecord;
                } else if (record.value_type == PropertyPayloadIndexRecord.value_type_string) {
                    if (value_record.len == 0) return error.InvalidRecord;
                    const payload_end = std.math.add(u64, value_record.offset, value_record.len) catch return error.InvalidRecord;
                    if (payload_end > values_header.payload_bytes) return error.InvalidRecord;
                    if (record.owner_kind == PropertyPayloadIndexRecord.owner_kind_node) {
                        const file_offset = std.math.add(u64, payload_start, value_record.offset) catch return error.InvalidRecord;
                        var ignored_digest: u64 = 0;
                        const digest_target = if (overridden) |positions|
                            if (positions.contains(.{
                                .owner_kind = record.owner_kind,
                                .owner_id = record.owner_id,
                                .key_hash = record.key_hash,
                            })) &ignored_digest else &digest
                        else
                            &digest;
                        try self.addSearchableNodeMetadataDigestFromValueFile(
                            digest_target,
                            0x544B_534D,
                            record.owner_id,
                            record.key_hash,
                            record.value_hash,
                            values_file,
                            file_offset,
                            value_record.len,
                            deadline,
                        );
                    }
                } else {
                    return error.InvalidRecord;
                }
                previous = record;
            }
        }
        return digest;
    }

    fn searchableNodeLegacyMetadataDigest(self: Store, deadline: core.QueryDeadline) !u64 {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        const has_index = try self.fileExists(self.node_props_overlay_index_path);
        const has_values = try self.fileExists(self.node_props_overlay_values_path);
        if (!has_index and !has_values) return 0;
        if (has_index != has_values) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_overlay_index_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(index_file);
        if (header.node_count != 0 or header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(index_file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;

        var values_file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_overlay_values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;
        const payload_start = try nodePropertyValueBlockHeaderAndRecordBytes(values_header.record_count);

        const searchable_hashes = [_]u64{
            nodePropertyKeyHash("name"),
            nodePropertyKeyHash("summary"),
        };
        if (searchable_hashes[0] == searchable_hashes[1]) return error.InvalidRecord;
        var digest: u64 = 0;
        for (searchable_hashes) |key_hash| {
            var previous: ?NodePropertyIndexRecord = null;
            var index = try self.nodePropertyIndexLowerBound(index_file, header, key_hash, 0, 0);
            while (index < header.record_count) : (index += 1) {
                if (deadline.expired()) return core.Error.BudgetExceeded;
                const record = try self.readNodePropertyIndexRecordAt(index_file, index);
                if (record.key_hash != key_hash) break;
                if (previous) |prev| {
                    if (!nodePropertyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
                }
                if (record.value_type == NodePropertyIndexRecord.value_type_uint) {
                    const value_record = try self.readNodePropertyValueRecordAt(values_file, index);
                    if (value_record.offset != 0 or value_record.len != 0) return error.InvalidRecord;
                } else if (record.value_type == NodePropertyIndexRecord.value_type_string) {
                    const value_record = try self.readNodePropertyValueRecordAt(values_file, index);
                    if (value_record.len == 0) return error.InvalidRecord;
                    const payload_end = std.math.add(u64, value_record.offset, value_record.len) catch return error.InvalidRecord;
                    if (payload_end > values_header.payload_bytes) return error.InvalidRecord;
                    const file_offset = std.math.add(u64, payload_start, value_record.offset) catch return error.InvalidRecord;
                    // Domain-separate the legacy layer so an identical value
                    // present in both physical layers cannot XOR-cancel the
                    // whole metadata anchor to zero.
                    try self.addSearchableNodeMetadataDigestFromValueFile(
                        &digest,
                        0x544B_534C,
                        record.node_id,
                        record.key_hash,
                        record.value_hash,
                        values_file,
                        file_offset,
                        value_record.len,
                        deadline,
                    );
                } else {
                    return error.InvalidRecord;
                }
                previous = record;
            }
        }
        return digest;
    }

    pub fn searchableNodeMetadataDigest(self: Store, allocator: std.mem.Allocator) !u64 {
        return self.searchableNodeMetadataDigestInternal(allocator, null, .none);
    }

    /// Digest the searchable property view while bounding the append-only
    /// delta scan and honoring the caller's query deadline. Explicit
    /// maintenance and validation continue to use the unbounded variant.
    pub fn searchableNodeMetadataDigestLimitedDeadline(
        self: Store,
        allocator: std.mem.Allocator,
        max_delta_scan_bytes: u64,
        deadline: core.QueryDeadline,
    ) !u64 {
        return self.searchableNodeMetadataDigestInternal(allocator, max_delta_scan_bytes, deadline);
    }

    fn searchableNodeMetadataDigestInternal(
        self: Store,
        allocator: std.mem.Allocator,
        max_delta_scan_bytes: ?u64,
        deadline: core.QueryDeadline,
    ) !u64 {
        // Hash immutable value ranges directly from disk instead of owning
        // every base name/summary merely to prove that a large text index is
        // current. An append-only delta still needs a latest-wins owner map,
        // but its working set is proportional only to the bounded delta, not
        // to the complete immutable base.
        if (!try self.pathExists(self.property_payload_delta_path)) {
            return (try self.searchableNodeCanonicalBaseMetadataDigest(null, deadline)) ^
                (try self.searchableNodeLegacyMetadataDigest(deadline));
        }

        var entries = std.ArrayList(PropertyPayloadIndexEntry).empty;
        defer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        var positions = std.AutoHashMap(PropertyPayloadOwnerKey, usize).init(allocator);
        defer positions.deinit();
        _ = try self.scanPropertyPayloadDeltaLimited(
            allocator,
            .{ .searchable = .{
                .entries = &entries,
                .positions = &positions,
            } },
            false,
            max_delta_scan_bytes,
            deadline,
        );

        var digest = try self.searchableNodeCanonicalBaseMetadataDigest(&positions, deadline);
        for (entries.items) |entry| {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const record = entry.record;
            if (record.owner_kind != PropertyPayloadIndexRecord.owner_kind_node or
                record.value_type != PropertyPayloadIndexRecord.value_type_string) return error.InvalidRecord;
            const value = entry.value orelse return error.InvalidRecord;
            addSearchableNodeMetadataDigest(&digest, 0x544B_534D, record.owner_id, record.key_hash, record.value_hash, value);
        }
        // Layer-domain separation avoids duplicate-value XOR cancellation.
        digest ^= try self.searchableNodeLegacyMetadataDigest(deadline);
        return digest;
    }

    fn writePropertyPayload(self: Store, entries: []PropertyPayloadIndexEntry) !void {
        try self.writePropertyPayloadIndexFiles(self.property_payload_index_path, self.property_payload_values_path, entries);
    }

    fn deinitPropertySnapshotList(entries: *std.ArrayList(PropertySnapshotEntry), allocator: std.mem.Allocator) void {
        for (entries.items) |entry| {
            if (entry.value_kind == .string) allocator.free(entry.string_value);
        }
        entries.deinit(allocator);
    }

    fn appendSearchableNodeOverlaySnapshot(
        self: Store,
        allocator: std.mem.Allocator,
        out: *std.ArrayList(PropertySnapshotEntry),
        effective_positions: *std.AutoHashMap(PropertyPayloadOwnerKey, usize),
        byte_budget: ?*SearchablePropertyByteBudget,
        deadline: core.QueryDeadline,
    ) !void {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        const has_index = try self.fileExists(self.node_props_overlay_index_path);
        const has_values = try self.fileExists(self.node_props_overlay_values_path);
        if (!has_index and !has_values) return;
        if (has_index != has_values) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_overlay_index_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(index_file);
        if (header.node_count != 0 or header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(index_file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;

        var values_file = try std.Io.Dir.cwd().openFile(self.io, self.node_props_overlay_values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

        const searchable_hashes = [_]u64{
            nodePropertyKeyHash("name"),
            nodePropertyKeyHash("summary"),
        };
        if (searchable_hashes[0] == searchable_hashes[1]) return error.InvalidRecord;
        for (searchable_hashes) |key_hash| {
            var previous: ?NodePropertyIndexRecord = null;
            var index = try self.nodePropertyIndexLowerBound(index_file, header, key_hash, 0, 0);
            while (index < header.record_count) : (index += 1) {
                if (deadline.expired()) return core.Error.BudgetExceeded;
                const record = try self.readNodePropertyIndexRecordAt(index_file, index);
                if (record.key_hash != key_hash) break;
                if (previous) |prev| {
                    if (!nodePropertyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
                }
                const value_record = try self.readNodePropertyValueRecordAt(values_file, index);
                if (record.value_type == NodePropertyIndexRecord.value_type_uint) {
                    if (value_record.offset != 0 or value_record.len != 0) return error.InvalidRecord;
                } else if (record.value_type == NodePropertyIndexRecord.value_type_string) {
                    if (value_record.len == 0) return error.InvalidRecord;
                    const payload_end = std.math.add(u64, value_record.offset, value_record.len) catch return error.InvalidRecord;
                    if (payload_end > values_header.payload_bytes) return error.InvalidRecord;
                    // The append-friendly property payload is the canonical
                    // overlay.  Historical stores may still carry the same
                    // owner/key in node_props_overlay; point reads prefer the
                    // canonical value, so the full-text snapshot and its byte
                    // budget must do the same instead of materializing both.
                    const owner_key = PropertyPayloadOwnerKey{
                        .owner_kind = PropertyPayloadIndexRecord.owner_kind_node,
                        .owner_id = record.node_id,
                        .key_hash = record.key_hash,
                    };
                    if (effective_positions.contains(owner_key)) {
                        previous = record;
                        continue;
                    }
                    const next_budget_bytes = if (byte_budget) |budget|
                        try budget.afterReplace(0, @intCast(value_record.len))
                    else
                        0;
                    const value = (try self.readNodePropertyValuePayloadAt(allocator, values_file, values_header, index, record)) orelse return error.InvalidRecord;
                    errdefer allocator.free(value);
                    try out.append(allocator, .{
                        .owner = .{ .node = core.NodeId.fromInt(record.node_id) },
                        .key_hash = record.key_hash,
                        .value_kind = .string,
                        .string_len = @intCast(value.len),
                        .string_value = value,
                    });
                    try effective_positions.putNoClobber(owner_key, out.items.len - 1);
                    if (byte_budget) |budget| budget.used_bytes = next_budget_bytes;
                } else {
                    return error.InvalidRecord;
                }
                previous = record;
            }
        }
    }

    fn appendSearchablePropertyPayloadSnapshot(
        self: Store,
        allocator: std.mem.Allocator,
        out: *std.ArrayList(PropertySnapshotEntry),
        byte_budget: ?*SearchablePropertyByteBudget,
        delta_scan_byte_budget: ?u64,
        deadline: core.QueryDeadline,
    ) !void {
        var entries = try self.readSearchablePropertyPayloadEntriesOrEmpty(allocator, byte_budget, delta_scan_byte_budget, deadline);
        defer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        try out.ensureUnusedCapacity(allocator, entries.items.len);
        for (entries.items) |*entry| {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const value = entry.value orelse return error.InvalidRecord;
            out.appendAssumeCapacity(.{
                .owner = .{ .node = core.NodeId.fromInt(entry.record.owner_id) },
                .key_hash = entry.record.key_hash,
                .value_kind = .string,
                .string_len = @intCast(value.len),
                .string_value = value,
            });
            entry.value = null;
        }
    }

    /// Snapshot only the node metadata consumed by full-text indexing.  The
    /// general property snapshot includes edge fields and arbitrary payloads;
    /// materializing those on a stale-search fallback can turn a bounded node
    /// scan into an unrelated O(all property bytes) allocation.
    pub fn loadSearchableNodeMetadataSnapshot(self: Store, allocator: std.mem.Allocator) !PropertySnapshot {
        return try self.loadSearchableNodeMetadataSnapshotInternal(allocator, null, null, .none);
    }

    /// Same snapshot with a hard cap on owned string bytes.  Stale full-text
    /// fallback uses this before building an ephemeral BM25 index so bounded
    /// node text cannot be paired with unbounded `name`/`summary` allocation.
    pub fn loadSearchableNodeMetadataSnapshotLimited(
        self: Store,
        allocator: std.mem.Allocator,
        max_string_bytes: u64,
    ) !PropertySnapshot {
        var budget = SearchablePropertyByteBudget{ .max_bytes = max_string_bytes };
        return try self.loadSearchableNodeMetadataSnapshotInternal(allocator, &budget, null, .none);
    }

    /// Bound both owned searchable strings and canonical property-delta scan
    /// bytes while honoring the caller's query deadline.
    pub fn loadSearchableNodeMetadataSnapshotWithLimitsDeadline(
        self: Store,
        allocator: std.mem.Allocator,
        max_string_bytes: u64,
        max_delta_scan_bytes: u64,
        deadline: core.QueryDeadline,
    ) !PropertySnapshot {
        var budget = SearchablePropertyByteBudget{ .max_bytes = max_string_bytes };
        return try self.loadSearchableNodeMetadataSnapshotInternal(allocator, &budget, max_delta_scan_bytes, deadline);
    }

    fn loadSearchableNodeMetadataSnapshotInternal(
        self: Store,
        allocator: std.mem.Allocator,
        byte_budget: ?*SearchablePropertyByteBudget,
        delta_scan_byte_budget: ?u64,
        deadline: core.QueryDeadline,
    ) !PropertySnapshot {
        if (deadline.expired()) return core.Error.BudgetExceeded;
        var out = std.ArrayList(PropertySnapshotEntry).empty;
        errdefer deinitPropertySnapshotList(&out, allocator);
        // Load the canonical payload first.  Legacy node_props_overlay is a
        // fallback only; this ordering makes precedence explicit, avoids
        // duplicate live values, and keeps the hard byte budget aligned with
        // the effective metadata consumed by point reads and text indexing.
        try self.appendSearchablePropertyPayloadSnapshot(allocator, &out, byte_budget, delta_scan_byte_budget, deadline);
        const has_legacy_index = try self.fileExists(self.node_props_overlay_index_path);
        const has_legacy_values = try self.fileExists(self.node_props_overlay_values_path);
        if (has_legacy_index != has_legacy_values) return error.InvalidRecord;
        if (!has_legacy_index) return .{ .entries = try out.toOwnedSlice(allocator) };
        var canonical_positions = std.AutoHashMap(PropertyPayloadOwnerKey, usize).init(allocator);
        defer canonical_positions.deinit();
        try canonical_positions.ensureTotalCapacity(std.math.cast(u32, out.items.len) orelse return error.RecordTooLarge);
        for (out.items, 0..) |entry, index| {
            if (deadline.expired()) return core.Error.BudgetExceeded;
            const node_id = switch (entry.owner) {
                .node => |id| id,
                .edge => return error.InvalidRecord,
            };
            const position = try canonical_positions.getOrPut(.{
                .owner_kind = PropertyPayloadIndexRecord.owner_kind_node,
                .owner_id = node_id.toInt(),
                .key_hash = entry.key_hash,
            });
            if (position.found_existing) return error.InvalidRecord;
            position.value_ptr.* = index;
        }
        try self.appendSearchableNodeOverlaySnapshot(allocator, &out, &canonical_positions, byte_budget, deadline);
        return .{ .entries = try out.toOwnedSlice(allocator) };
    }

    /// Materialize only the requested node-sidecar keys. This is the bounded
    /// read primitive for callers (notably task DAG walks) that need the same
    /// small property family for many nodes: each key probes the immutable
    /// base and validates the append-only delta once, rather than every node
    /// independently rescanning all property history.
    pub fn loadNodePropertySnapshotForKeys(self: Store, allocator: std.mem.Allocator, keys: []const []const u8) !PropertySnapshot {
        return try self.loadPropertySnapshotForKeysFiltered(
            allocator,
            keys,
            PropertyPayloadIndexRecord.owner_kind_node,
            self.node_props_overlay_index_path,
            self.node_props_overlay_values_path,
            null,
        );
    }

    pub fn loadNodePropertySnapshotForNodeIds(
        self: Store,
        allocator: std.mem.Allocator,
        node_ids: []const core.NodeId,
        keys: []const []const u8,
    ) !PropertySnapshot {
        var wanted_node_ids = PropertyPayloadNodeIdSet.init(allocator);
        defer wanted_node_ids.deinit();
        try wanted_node_ids.ensureTotalCapacity(std.math.cast(u32, node_ids.len) orelse return error.RecordTooLarge);
        for (node_ids) |node_id| {
            if (node_id == .none or node_id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
            try wanted_node_ids.put(node_id.toInt(), {});
        }
        return try self.loadPropertySnapshotForKeysFiltered(
            allocator,
            keys,
            PropertyPayloadIndexRecord.owner_kind_node,
            self.node_props_overlay_index_path,
            self.node_props_overlay_values_path,
            &wanted_node_ids,
        );
    }

    /// Bounded edge-property snapshot for migration and batch validation.  It
    /// probes only requested key ranges and retains only requested owners while
    /// still validating every append-only delta frame once.
    pub fn loadEdgePropertySnapshotForEdgeIds(
        self: Store,
        allocator: std.mem.Allocator,
        edge_ids: []const core.EdgeId,
        keys: []const []const u8,
    ) !PropertySnapshot {
        var wanted_edge_ids = PropertyPayloadNodeIdSet.init(allocator);
        defer wanted_edge_ids.deinit();
        try wanted_edge_ids.ensureTotalCapacity(std.math.cast(u32, edge_ids.len) orelse return error.RecordTooLarge);
        for (edge_ids) |edge_id| {
            if (edge_id == .none or edge_id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
            try wanted_edge_ids.put(edge_id.toInt(), {});
        }
        return try self.loadPropertySnapshotForKeysFiltered(
            allocator,
            keys,
            PropertyPayloadIndexRecord.owner_kind_edge,
            self.edge_props_overlay_index_path,
            self.edge_props_overlay_values_path,
            &wanted_edge_ids,
        );
    }

    fn loadPropertySnapshotForKeysFiltered(
        self: Store,
        allocator: std.mem.Allocator,
        keys: []const []const u8,
        owner_kind: u8,
        legacy_index_path: []const u8,
        legacy_values_path: []const u8,
        wanted_owner_ids: ?*const PropertyPayloadNodeIdSet,
    ) !PropertySnapshot {
        if (owner_kind != PropertyPayloadIndexRecord.owner_kind_node and
            owner_kind != PropertyPayloadIndexRecord.owner_kind_edge) return error.InvalidRecord;
        const owner_filter = PropertyPayloadOwnerFilter{
            .owner_kind = owner_kind,
            .owner_ids = wanted_owner_ids,
        };
        var out = std.ArrayList(PropertySnapshotEntry).empty;
        errdefer deinitPropertySnapshotList(&out, allocator);
        var positions = std.AutoHashMap(PropertyPayloadOwnerKey, usize).init(allocator);
        defer positions.deinit();
        var key_hashes = PropertyPayloadKeyNameMap.init(allocator);
        defer key_hashes.deinit();

        for (keys) |key| {
            if (!propertyKeyNameValid(key) or
                (owner_kind == PropertyPayloadIndexRecord.owner_kind_node and std.mem.eql(u8, key, "text"))) return error.InvalidRecord;
            const key_hash = nodePropertyKeyHash(key);
            const key_entry = try key_hashes.getOrPut(key_hash);
            if (key_entry.found_existing) return error.InvalidRecord;
            key_entry.value_ptr.* = key;

            var legacy = try self.readNodePropertyOverlayEntriesForKeyOwnersOrEmpty(
                allocator,
                legacy_index_path,
                legacy_values_path,
                key,
                wanted_owner_ids,
            );
            defer {
                deinitNodePropertyIndexEntries(legacy.items, allocator);
                legacy.deinit(allocator);
            }
            for (legacy.items) |*entry| {
                const owner_key = PropertyPayloadOwnerKey{
                    .owner_kind = owner_kind,
                    .owner_id = entry.record.node_id,
                    .key_hash = entry.record.key_hash,
                };
                const position = try positions.getOrPut(owner_key);
                if (position.found_existing) return error.InvalidRecord;
                const value_kind: PropertySnapshotValueKind = switch (entry.record.value_type) {
                    NodePropertyIndexRecord.value_type_string => .string,
                    NodePropertyIndexRecord.value_type_uint => .uint,
                    else => return error.InvalidRecord,
                };
                try out.append(allocator, .{
                    .owner = try propertyPayloadOwnerFromParts(owner_kind, entry.record.node_id),
                    .key_hash = entry.record.key_hash,
                    .value_kind = value_kind,
                    .string_len = if (value_kind == .string) @intCast((entry.value orelse return error.InvalidRecord).len) else 0,
                    .string_value = if (value_kind == .string) entry.value.? else &.{},
                    .uint_value = if (value_kind == .uint) entry.record.value_hash else 0,
                });
                if (value_kind == .string) entry.value = null;
                position.value_ptr.* = out.items.len - 1;
            }

            var payload = try self.readPropertyPayloadEntriesForKeyOwnersOrEmpty(allocator, key, owner_filter, false);
            defer {
                deinitPropertyPayloadIndexEntries(payload.items, allocator);
                payload.deinit(allocator);
            }
            for (payload.items) |*entry| {
                if (entry.record.owner_kind != owner_kind) return error.InvalidRecord;
                const owner_key = PropertyPayloadOwnerKey{
                    .owner_kind = entry.record.owner_kind,
                    .owner_id = entry.record.owner_id,
                    .key_hash = entry.record.key_hash,
                };
                const value_kind: PropertySnapshotValueKind = switch (entry.record.value_type) {
                    PropertyPayloadIndexRecord.value_type_string => .string,
                    PropertyPayloadIndexRecord.value_type_uint => .uint,
                    else => return error.InvalidRecord,
                };
                const replacement = PropertySnapshotEntry{
                    .owner = try propertyPayloadOwnerFromParts(owner_kind, entry.record.owner_id),
                    .key_hash = entry.record.key_hash,
                    .value_kind = value_kind,
                    .string_len = if (value_kind == .string) @intCast((entry.value orelse return error.InvalidRecord).len) else 0,
                    .string_value = if (value_kind == .string) entry.value.? else &.{},
                    .uint_value = if (value_kind == .uint) entry.record.value_hash else 0,
                };
                if (positions.get(owner_key)) |position| {
                    if (position >= out.items.len) return error.InvalidRecord;
                    if (out.items[position].value_kind == .string) allocator.free(out.items[position].string_value);
                    out.items[position] = replacement;
                } else {
                    try out.ensureUnusedCapacity(allocator, 1);
                    const position = try positions.getOrPut(owner_key);
                    if (position.found_existing) return error.InvalidRecord;
                    position.value_ptr.* = out.items.len;
                    out.appendAssumeCapacity(replacement);
                }
                if (value_kind == .string) entry.value = null;
            }
        }
        // All requested lifecycle/metadata keys share one validated delta
        // pass.  This is the hot path for task-frontier and effective-status
        // queries; scanning once per key made latency grow as keys*history.
        _ = try self.scanPropertyPayloadDelta(allocator, .{ .snapshot = .{
            .key_names = &key_hashes,
            .entries = &out,
            .positions = &positions,
            .owner_filter = owner_filter,
        } }, false);
        return .{ .entries = try out.toOwnedSlice(allocator) };
    }

    fn scanLegacyPropertySnapshotLayer(
        self: Store,
        allocator: std.mem.Allocator,
        index_path: []const u8,
        values_path: []const u8,
        owner_kind: u8,
        context: *anyopaque,
        visit: PropertySnapshotLayerVisitor,
    ) !void {
        const has_index = try self.fileExists(index_path);
        const has_values = try self.fileExists(values_path);
        if (!has_index and !has_values) return;
        if (has_index != has_values) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().openFile(self.io, index_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const header = try self.readNodePropertyIndexHeaderFromFile(index_file);
        if (header.node_count != 0 or header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(index_file) != try nodePropertyIndexFileSize(header.record_count)) return error.InvalidRecord;

        var values_file = try std.Io.Dir.cwd().openFile(self.io, values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

        var previous: ?NodePropertyIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readNodePropertyIndexRecordAt(index_file, index);
            if (previous) |prev| {
                if (!nodePropertyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            const value = try self.readNodePropertyValuePayloadAt(allocator, values_file, values_header, index, record);
            defer if (value) |owned| allocator.free(owned);
            const value_kind: PropertySnapshotValueKind = switch (record.value_type) {
                NodePropertyIndexRecord.value_type_string => .string,
                NodePropertyIndexRecord.value_type_uint => .uint,
                else => return error.InvalidRecord,
            };
            try visit(context, .{
                .owner = try propertyPayloadOwnerFromParts(owner_kind, record.node_id),
                .key_hash = record.key_hash,
                .version = property_snapshot_legacy_version,
                .value_kind = value_kind,
                .string_value = if (value_kind == .string) value orelse return error.InvalidRecord else &.{},
                .uint_value = if (value_kind == .uint) record.value_hash else 0,
            });
            previous = record;
        }
    }

    fn scanCanonicalPropertySnapshotLayer(
        self: Store,
        allocator: std.mem.Allocator,
        context: *anyopaque,
        visit: PropertySnapshotLayerVisitor,
    ) !void {
        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (!has_index and !has_values) return;
        if (has_index != has_values) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
        defer index_file.close(self.io);
        const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
        if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;

        var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
        defer values_file.close(self.io);
        const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
        if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
        if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

        var previous: ?PropertyPayloadIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readPropertyPayloadIndexRecordAt(index_file, index);
            if (previous) |prev| {
                if (!propertyPayloadRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            const value = try self.readPropertyPayloadValuePayloadAt(allocator, values_file, values_header, index, record);
            defer if (value) |owned| allocator.free(owned);
            const value_kind: PropertySnapshotValueKind = switch (record.value_type) {
                PropertyPayloadIndexRecord.value_type_string => .string,
                PropertyPayloadIndexRecord.value_type_uint => .uint,
                else => return error.InvalidRecord,
            };
            try visit(context, .{
                .owner = try propertyPayloadOwnerFromParts(record.owner_kind, record.owner_id),
                .key_hash = record.key_hash,
                .version = property_snapshot_base_version,
                .value_kind = value_kind,
                .string_value = if (value_kind == .string) value orelse return error.InvalidRecord else &.{},
                .uint_value = if (value_kind == .uint) record.value_hash else 0,
            });
            previous = record;
        }
    }

    /// Stream every physical property layer once with explicit precedence.
    /// This validates the legacy overlays, canonical base, and append-only
    /// delta without retaining an all-store owner map. The visitor may spool
    /// fixed-size metadata and values to disk, then external-sort to obtain a
    /// bounded effective snapshot.
    pub fn scanPropertySnapshotLayers(
        self: Store,
        allocator: std.mem.Allocator,
        context: *anyopaque,
        visit: PropertySnapshotLayerVisitor,
    ) !void {
        try self.scanLegacyPropertySnapshotLayer(
            allocator,
            self.node_props_overlay_index_path,
            self.node_props_overlay_values_path,
            PropertyPayloadIndexRecord.owner_kind_node,
            context,
            visit,
        );
        try self.scanLegacyPropertySnapshotLayer(
            allocator,
            self.edge_props_overlay_index_path,
            self.edge_props_overlay_values_path,
            PropertyPayloadIndexRecord.owner_kind_edge,
            context,
            visit,
        );
        try self.scanCanonicalPropertySnapshotLayer(allocator, context, visit);
        var next_version = property_snapshot_delta_version_base;
        _ = try self.scanPropertyPayloadDelta(allocator, .{ .layer_scan = .{
            .context = context,
            .visit = visit,
            .next_version = &next_version,
        } }, false);
    }

    pub fn loadPropertySnapshot(self: Store, allocator: std.mem.Allocator) !PropertySnapshot {
        var out = std.ArrayList(PropertySnapshotEntry).empty;
        errdefer deinitPropertySnapshotList(&out, allocator);

        var node_overlay = try self.readNodePropertyOverlayEntriesOrEmpty(allocator);
        defer {
            deinitNodePropertyIndexEntries(node_overlay.items, allocator);
            node_overlay.deinit(allocator);
        }
        try out.ensureUnusedCapacity(allocator, node_overlay.items.len);
        for (node_overlay.items) |entry| {
            const string_value = if (entry.record.value_type == NodePropertyIndexRecord.value_type_string)
                try allocator.dupe(u8, entry.value orelse return error.InvalidRecord)
            else
                &.{};
            errdefer if (entry.record.value_type == NodePropertyIndexRecord.value_type_string) allocator.free(string_value);
            out.appendAssumeCapacity(.{
                .owner = .{ .node = core.NodeId.fromInt(entry.record.node_id) },
                .key_hash = entry.record.key_hash,
                .value_kind = if (entry.record.value_type == NodePropertyIndexRecord.value_type_uint) .uint else .string,
                .string_len = if (entry.record.value_type == NodePropertyIndexRecord.value_type_string)
                    @intCast(string_value.len)
                else
                    0,
                .string_value = string_value,
                .uint_value = if (entry.record.value_type == NodePropertyIndexRecord.value_type_uint) entry.record.value_hash else 0,
            });
        }

        var edge_overlay = try self.readEdgePropertyOverlayEntriesOrEmpty(allocator);
        defer {
            deinitNodePropertyIndexEntries(edge_overlay.items, allocator);
            edge_overlay.deinit(allocator);
        }
        try out.ensureUnusedCapacity(allocator, edge_overlay.items.len);
        for (edge_overlay.items) |entry| {
            const string_value = if (entry.record.value_type == NodePropertyIndexRecord.value_type_string)
                try allocator.dupe(u8, entry.value orelse return error.InvalidRecord)
            else
                &.{};
            errdefer if (entry.record.value_type == NodePropertyIndexRecord.value_type_string) allocator.free(string_value);
            out.appendAssumeCapacity(.{
                .owner = .{ .edge = core.EdgeId.fromInt(entry.record.node_id) },
                .key_hash = entry.record.key_hash,
                .value_kind = if (entry.record.value_type == NodePropertyIndexRecord.value_type_uint) .uint else .string,
                .string_len = if (entry.record.value_type == NodePropertyIndexRecord.value_type_string)
                    @intCast(string_value.len)
                else
                    0,
                .string_value = string_value,
                .uint_value = if (entry.record.value_type == NodePropertyIndexRecord.value_type_uint) entry.record.value_hash else 0,
            });
        }

        var payload = try self.readPropertyPayloadEntriesOrEmpty(allocator);
        defer {
            deinitPropertyPayloadIndexEntries(payload.items, allocator);
            payload.deinit(allocator);
        }
        try out.ensureUnusedCapacity(allocator, payload.items.len);
        for (payload.items) |entry| {
            const owner: PropertyOwner = switch (entry.record.owner_kind) {
                PropertyPayloadIndexRecord.owner_kind_node => .{ .node = core.NodeId.fromInt(entry.record.owner_id) },
                PropertyPayloadIndexRecord.owner_kind_edge => .{ .edge = core.EdgeId.fromInt(entry.record.owner_id) },
                else => return error.InvalidRecord,
            };
            const string_value = if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_string)
                try allocator.dupe(u8, entry.value orelse return error.InvalidRecord)
            else
                &.{};
            errdefer if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_string) allocator.free(string_value);
            out.appendAssumeCapacity(.{
                .owner = owner,
                .key_hash = entry.record.key_hash,
                .value_kind = if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_uint) .uint else .string,
                .string_len = if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_string)
                    @intCast(string_value.len)
                else
                    0,
                .string_value = string_value,
                .uint_value = if (entry.record.value_type == PropertyPayloadIndexRecord.value_type_uint) entry.record.value_hash else 0,
            });
        }

        return .{ .entries = try out.toOwnedSlice(allocator) };
    }

    pub fn appendPropertiesBatch(self: Store, allocator: std.mem.Allocator, writes: []const PropertyPayloadWrite) !void {
        if (writes.len == 0) return;
        var entries = try self.readPropertyPayloadEntriesOrEmpty(allocator);
        defer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }

        var seen = std.AutoHashMap(PropertyPayloadOwnerKey, void).init(allocator);
        defer seen.deinit();
        const expected_count = std.math.add(usize, entries.items.len, writes.len) catch return error.RecordTooLarge;
        try seen.ensureTotalCapacity(std.math.cast(u32, expected_count) orelse return error.RecordTooLarge);
        for (entries.items) |entry| {
            try seen.put(.{
                .owner_kind = entry.record.owner_kind,
                .owner_id = entry.record.owner_id,
                .key_hash = entry.record.key_hash,
            }, {});
        }

        for (writes) |write| {
            const key = propertyPayloadOwnerKey(write.owner, write.key);
            const seen_entry = try seen.getOrPut(key);
            if (seen_entry.found_existing) return error.InvalidRecord;
            switch (write.value) {
                .string => |value| {
                    if (!stringPropertyKeySupportedForOwner(write.owner, write.key) or value.len == 0) return error.InvalidRecord;
                    try appendStringPropertyPayloadRecord(&entries, allocator, write.owner, write.key, value);
                },
                .uint => |value| {
                    if (!uintPropertyKeySupportedForOwner(write.owner, write.key)) return error.InvalidRecord;
                    try appendUintPropertyPayloadRecord(&entries, allocator, write.owner, write.key, value);
                },
            }
        }

        try self.writePropertyPayload(entries.items);
    }

    /// Publish a canonical property base from a bounded sorted stream. This is
    /// intentionally restricted to an empty COW target: replacing a live base
    /// would discard concurrent deltas and violate the Store writer contract.
    /// The two-file base is still committed through the normal redo journal.
    pub fn replaceEmptyPropertyPayloadFromSortedStream(
        self: Store,
        expected_count: u64,
        context: *anyopaque,
        next: SortedPropertyPayloadNext,
    ) !void {
        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (has_index != has_values) return error.InvalidRecord;
        if (has_index) {
            var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
            defer index_file.close(self.io);
            const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
            if (header.record_count != 0 or header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(0)) return error.InvalidRecord;
            var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
            defer values_file.close(self.io);
            const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
            if (values_header.record_count != 0 or values_header.node_count != 0 or values_header.node_digest != 0 or
                values_header.payload_bytes != 0 or values_header.payload_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(0, 0)) return error.InvalidRecord;
        }
        const delta_scan = try self.scanPropertyPayloadDelta(self.allocator, .none, false);
        if (delta_scan.valid_bytes != 0 or delta_scan.last_sequence != 0) return error.InvalidRecord;
        const RejectNonEmpty = struct {
            fn visit(_: *anyopaque, _: PropertySnapshotLayerEntry) anyerror!void {
                return error.InvalidRecord;
            }
        };
        var empty_context: u8 = 0;
        try self.scanPropertySnapshotLayers(self.allocator, &empty_context, RejectNonEmpty.visit);

        const index_stage_path = try self.tmpPathFor(self.property_payload_index_path);
        defer self.allocator.free(index_stage_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, index_stage_path) catch {};
        const values_stage_path = try self.tmpPathFor(self.property_payload_values_path);
        defer self.allocator.free(values_stage_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, values_stage_path) catch {};

        var record_count: u64 = 0;
        var payload_bytes: u64 = 0;
        var payload_digest: u64 = 0;
        {
            var index_file = try std.Io.Dir.cwd().createFile(self.io, index_stage_path, .{ .read = true, .truncate = true });
            defer index_file.close(self.io);
            var values_file = try std.Io.Dir.cwd().createFile(self.io, values_stage_path, .{ .read = true, .truncate = true });
            defer values_file.close(self.io);
            var index_writer = try StorageBufferedWriter.initAtOffset(
                self.allocator,
                self.io,
                index_file,
                storage_write_buffer_bytes,
                PropertyPayloadIndexHeader.encoded_len,
            );
            defer index_writer.deinit();
            var value_record_writer = try StorageBufferedWriter.initAtOffset(
                self.allocator,
                self.io,
                values_file,
                storage_write_buffer_bytes,
                NodePropertyValueBlockHeader.encoded_len,
            );
            defer value_record_writer.deinit();
            const payload_offset = std.math.add(
                u64,
                NodePropertyValueBlockHeader.encoded_len,
                std.math.mul(u64, expected_count, NodePropertyValueRecord.encoded_len) catch return error.RecordTooLarge,
            ) catch return error.RecordTooLarge;
            var value_writer = try StorageBufferedWriter.initAtOffset(
                self.allocator,
                self.io,
                values_file,
                storage_write_buffer_bytes,
                payload_offset,
            );
            defer value_writer.deinit();

            var previous: ?PropertyPayloadIndexRecord = null;
            var digest_bytes: [8]u8 = undefined;
            while (try next(context)) |entry| {
                // payload_offset reserves exactly expected_count value-record
                // slots. Reject an over-producing stream before either writer
                // can enter the payload region reserved for string bytes.
                if (record_count >= expected_count) return error.InvalidRecord;
                const owner_id = propertyPayloadOwnerId(entry.owner);
                const owner_kind = propertyPayloadOwnerKind(entry.owner);
                const value_type: u8 = switch (entry.value) {
                    .string => PropertyPayloadIndexRecord.value_type_string,
                    .uint => PropertyPayloadIndexRecord.value_type_uint,
                };
                const value_hash: u64 = switch (entry.value) {
                    .string => |value| blk: {
                        if (value.len == 0) return error.InvalidRecord;
                        break :blk nodePropertyValueHash(value);
                    },
                    .uint => |value| value,
                };
                const record = PropertyPayloadIndexRecord{
                    .key_hash = entry.key_hash,
                    .value_hash = value_hash,
                    .owner_id = owner_id,
                    .owner_kind = owner_kind,
                    .value_type = value_type,
                };
                if (previous) |prior| {
                    if (!propertyPayloadRecordLessThan({}, prior, record)) return error.InvalidRecord;
                }
                var record_bytes: [PropertyPayloadIndexRecord.encoded_len]u8 = undefined;
                try record.encode(&record_bytes);
                try index_writer.append(&record_bytes);

                var value_record: NodePropertyValueRecord = .{ .offset = 0, .len = 0 };
                switch (entry.value) {
                    .string => |value| {
                        value_record = .{
                            .offset = payload_bytes,
                            .len = std.math.cast(u32, value.len) orelse return error.RecordTooLarge,
                        };
                        std.mem.writeInt(u64, &digest_bytes, entry.key_hash, .little);
                        payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, &digest_bytes);
                        std.mem.writeInt(u64, &digest_bytes, value_hash, .little);
                        payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, &digest_bytes);
                        payload_digest ^= std.hash.Wyhash.hash(0x544B_5056, value);
                        try value_writer.append(value);
                        payload_bytes = std.math.add(u64, payload_bytes, value.len) catch return error.RecordTooLarge;
                    },
                    .uint => {},
                }
                var value_record_bytes: [NodePropertyValueRecord.encoded_len]u8 = undefined;
                value_record.encode(&value_record_bytes);
                try value_record_writer.append(&value_record_bytes);
                record_count = std.math.add(u64, record_count, 1) catch return error.RecordTooLarge;
                previous = record;
            }
            if (record_count != expected_count) return error.InvalidRecord;
            try index_writer.flush();
            try value_record_writer.flush();
            try value_writer.flush();

            var index_header_bytes: [PropertyPayloadIndexHeader.encoded_len]u8 = undefined;
            (PropertyPayloadIndexHeader{
                .record_count = record_count,
                .owner_count = 0,
                .owner_digest = 0,
            }).encode(&index_header_bytes);
            try index_file.writePositionalAll(self.io, &index_header_bytes, 0);
            var values_header_bytes: [NodePropertyValueBlockHeader.encoded_len]u8 = undefined;
            (NodePropertyValueBlockHeader{
                .record_count = record_count,
                .node_count = 0,
                .node_digest = 0,
                .payload_bytes = payload_bytes,
                .payload_digest = payload_digest,
            }).encode(&values_header_bytes);
            try values_file.writePositionalAll(self.io, &values_header_bytes, 0);

            if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(record_count)) return error.InvalidRecord;
            if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(record_count, payload_bytes)) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) {
                try index_file.sync(self.io);
                try values_file.sync(self.io);
            }
        }

        try self.writePropertyPayloadRedoJournal(index_stage_path, values_stage_path);
        try self.renameReplace(values_stage_path, self.property_payload_values_path);
        try self.renameReplace(index_stage_path, self.property_payload_index_path);
        try self.deletePropertyPayloadRedoJournal();
    }

    fn validatePropertyPayloadWrite(self: Store, allocator: std.mem.Allocator, write: PropertyPayloadWrite) !void {
        switch (write.value) {
            .string => |value| {
                if (!stringPropertyKeySupportedForOwner(write.owner, write.key) or value.len == 0) return error.InvalidRecord;
            },
            .uint => {
                if (!uintPropertyKeySupportedForOwner(write.owner, write.key)) return error.InvalidRecord;
            },
        }
        switch (write.owner) {
            .node => |node_id| {
                var node = (try self.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
                node.deinit(allocator);
            },
            .edge => |edge_id| if (!try self.visibleEdgeIdExists(edge_id)) return core.Error.InvalidId,
        }
    }

    fn countExistingPropertyPayloadKeys(
        self: Store,
        allocator: std.mem.Allocator,
        wanted: *const PropertyPayloadOwnerKeySet,
        delta_scan: *PropertyPayloadDeltaScan,
    ) !usize {
        var found = PropertyPayloadOwnerKeySet.init(allocator);
        defer found.deinit();
        try found.ensureTotalCapacity(@intCast(wanted.count()));

        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (has_index != has_values) return error.InvalidRecord;
        if (has_index) {
            var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
            defer index_file.close(self.io);
            const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
            if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;
            try self.validatePropertyPayloadIndexOrderIfStrict(index_file, header);

            var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
            defer values_file.close(self.io);
            const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
            if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

            var wanted_it = wanted.keyIterator();
            while (wanted_it.next()) |wanted_key| {
                var index = try self.propertyPayloadKeyHashLowerBound(index_file, header.record_count, wanted_key.key_hash);
                while (index < header.record_count) : (index += 1) {
                    const record = try self.readPropertyPayloadIndexRecordAt(index_file, index);
                    if (record.key_hash != wanted_key.key_hash) break;
                    if (record.owner_kind == wanted_key.owner_kind and record.owner_id == wanted_key.owner_id) {
                        try found.put(wanted_key.*, {});
                        break;
                    }
                }
            }
        }

        delta_scan.* = try self.scanPropertyPayloadDelta(allocator, .{ .existing_keys = .{ .wanted = wanted, .found = &found } }, false);
        return found.count();
    }

    /// Replace or insert several property values with one crash-safe delta
    /// publication.  The immutable base pair is only probed by key and is not
    /// rewritten; write amplification is therefore proportional to this batch.
    /// Duplicate owner/key writes are rejected before any durable mutation.
    pub fn upsertPropertiesBatch(self: Store, allocator: std.mem.Allocator, writes: []const PropertyPayloadWrite) !PropertyPayloadUpsertResult {
        if (writes.len == 0) return .{};

        var write_keys = PropertyPayloadOwnerKeySet.init(allocator);
        defer write_keys.deinit();
        try write_keys.ensureTotalCapacity(std.math.cast(u32, writes.len) orelse return error.RecordTooLarge);
        for (writes) |write| {
            try self.validatePropertyPayloadWrite(allocator, write);
            const entry = try write_keys.getOrPut(propertyPayloadOwnerKey(write.owner, write.key));
            if (entry.found_existing) return error.InvalidRecord;
        }

        // The existing-key pass already validates and walks the complete
        // delta. Reuse its tail/sequence as the append precondition instead of
        // immediately rescanning an ever-growing journal a second time.
        // Raw Store callers still owe the documented external writer lock;
        // CLI lifecycle commands hold it across this whole operation.
        var delta_scan: PropertyPayloadDeltaScan = undefined;
        const replaced = try self.countExistingPropertyPayloadKeys(allocator, &write_keys, &delta_scan);
        try self.publishPropertyPayloadDelta(allocator, writes, delta_scan);
        return .{
            .writes_applied = writes.len,
            .entries_replaced = replaced,
            .payload_publish_count = 1,
        };
    }

    /// Merge the append-only property delta into the immutable base pair.
    /// Callers must provide the same external writer exclusion used by other
    /// Store maintenance operations (the CLI holds CliStoreLock).  Publishing
    /// the new base before unlinking the delta is deliberate: a crash in that
    /// window merely replays identical latest-wins values, while deleting the
    /// delta first could lose committed updates.
    pub fn compactPropertyPayloadDelta(self: Store, allocator: std.mem.Allocator) !PropertyPayloadCompactionResult {
        _ = try self.recoverPropertyPayloadDeltaJournal();
        const scan = try self.scanPropertyPayloadDelta(allocator, .none, false);
        if (scan.valid_bytes == 0) return .{};

        var entries = try self.readPropertyPayloadEntriesOrEmpty(allocator);
        defer {
            deinitPropertyPayloadIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        try self.writePropertyPayload(entries.items);
        const cleanup_pending = !self.cleanupPropertyPayloadDeltaAfterCompaction();
        return .{
            .compacted = true,
            .cleanup_pending = cleanup_pending,
            .delta_bytes = scan.valid_bytes,
            .delta_frames = scan.last_sequence,
            .live_entries = @intCast(entries.items.len),
        };
    }

    /// The merged base pair is already the committed source of truth. A
    /// retained delta only replays the same latest-wins values, so unlink or
    /// parent-sync failure is retryable garbage collection rather than a
    /// failed compaction.
    fn cleanupPropertyPayloadDeltaAfterCompaction(self: Store) bool {
        std.Io.Dir.cwd().deleteFile(self.io, self.property_payload_delta_path) catch return false;
        self.syncParentDirForPath(self.property_payload_delta_path) catch return false;
        return true;
    }

    fn readPropertyPayloadEntryForKey(
        self: Store,
        allocator: std.mem.Allocator,
        owner: PropertyOwner,
        key: []const u8,
    ) !?PropertyPayloadIndexEntry {
        var lookup = PropertyPayloadLookupTarget{
            .owner_key = propertyPayloadOwnerKey(owner, key),
            .key_name = key,
        };
        errdefer lookup.deinit(allocator);

        const has_index = try self.fileExists(self.property_payload_index_path);
        const has_values = try self.fileExists(self.property_payload_values_path);
        if (has_index != has_values) return error.InvalidRecord;
        if (has_index) {
            var index_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_index_path, .{ .allow_directory = false });
            defer index_file.close(self.io);
            const header = try self.readPropertyPayloadIndexHeaderFromFile(index_file);
            if (header.owner_count != 0 or header.owner_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(index_file) != try propertyPayloadIndexFileSize(header.record_count)) return error.InvalidRecord;
            try self.validatePropertyPayloadIndexOrderIfStrict(index_file, header);

            var values_file = try std.Io.Dir.cwd().openFile(self.io, self.property_payload_values_path, .{ .allow_directory = false });
            defer values_file.close(self.io);
            const values_header = try self.readNodePropertyValueBlockHeaderFromFile(values_file);
            if (values_header.record_count != header.record_count or values_header.node_count != 0 or values_header.node_digest != 0) return error.InvalidRecord;
            if (try self.regularFileSize(values_file) != try nodePropertyValueBlockFileSize(values_header.record_count, values_header.payload_bytes)) return error.InvalidRecord;

            var index = try self.propertyPayloadKeyHashLowerBound(index_file, header.record_count, lookup.owner_key.key_hash);
            while (index < header.record_count) : (index += 1) {
                const record = try self.readPropertyPayloadIndexRecordAt(index_file, index);
                if (record.key_hash != lookup.owner_key.key_hash) break;
                if (record.owner_kind != lookup.owner_key.owner_kind or record.owner_id != lookup.owner_key.owner_id) continue;
                if (lookup.value != null) return error.InvalidRecord;
                const value = try self.readPropertyPayloadValuePayloadAt(allocator, values_file, values_header, index, record);
                lookup.value = .{ .record = record, .value = value };
            }
        }

        _ = try self.scanPropertyPayloadDelta(allocator, .{ .lookup = &lookup }, false);
        const result = lookup.value;
        lookup.value = null;
        return result;
    }

    fn propertyPayloadStringValue(entries: []const PropertyPayloadIndexEntry, owner: PropertyOwner, key: []const u8) ?[]const u8 {
        for (entries) |entry| {
            if (!propertyPayloadEntryMatchesOwnerKey(entry, owner, key)) continue;
            if (entry.record.value_type != PropertyPayloadIndexRecord.value_type_string) continue;
            return entry.value;
        }
        return null;
    }

    fn propertyPayloadUintValue(entries: []const PropertyPayloadIndexEntry, owner: PropertyOwner, key: []const u8) ?u64 {
        for (entries) |entry| {
            if (!propertyPayloadEntryMatchesOwnerKey(entry, owner, key)) continue;
            if (entry.record.value_type != PropertyPayloadIndexRecord.value_type_uint) continue;
            if (entry.value != null) return null;
            return entry.record.value_hash;
        }
        return null;
    }

    fn setStringPropertyPayload(self: Store, allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8, value: []const u8) !void {
        _ = try self.upsertPropertiesBatch(allocator, &.{.{
            .owner = owner,
            .key = key,
            .value = .{ .string = value },
        }});
    }

    fn setUintPropertyPayload(self: Store, allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8, value: u64) !void {
        _ = try self.upsertPropertiesBatch(allocator, &.{.{
            .owner = owner,
            .key = key,
            .value = .{ .uint = value },
        }});
    }

    pub fn setNodeStringProperty(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId, key: []const u8, value: []const u8) !void {
        if (!nodePropertyOverlayStringKeySupported(key)) return error.InvalidRecord;
        try self.setStringPropertyPayload(allocator, .{ .node = node_id }, key, value);
    }

    pub fn getNodeStringProperty(self: Store, allocator: std.mem.Allocator, node_id: core.NodeId, key: []const u8) !?[]u8 {
        if (!nodePropertyStringKeySupported(key)) return null;
        var node = (try self.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
        defer node.deinit(allocator);
        if (nodePropertyOverlayStringKeySupported(key)) {
            var payload_entry = try self.readPropertyPayloadEntryForKey(allocator, .{ .node = node_id }, key);
            defer if (payload_entry) |*entry| entry.deinit(allocator);
            if (payload_entry) |*entry| {
                if (entry.record.value_type != PropertyPayloadIndexRecord.value_type_string) return error.InvalidRecord;
                const value = entry.value orelse return error.InvalidRecord;
                entry.value = null;
                return value;
            }
            var entries = try self.readNodePropertyOverlayEntriesOrEmpty(allocator);
            defer {
                deinitNodePropertyIndexEntries(entries.items, allocator);
                entries.deinit(allocator);
            }
            if (nodePropertyOverlayStringValue(entries.items, node_id, key)) |value| return try allocator.dupe(u8, value);
        }
        return try nodePropertyValueFromTextAlloc(allocator, node.text, key);
    }

    fn edgePropertyOverlayEntryMatchesEdgeKey(entry: NodePropertyIndexEntry, edge_id: core.EdgeId, key: []const u8) bool {
        return entry.record.node_id == edge_id.toInt() and
            entry.record.key_hash == nodePropertyKeyHash(key) and
            entry.record.value_type == NodePropertyIndexRecord.value_type_string;
    }

    pub fn setEdgeStringProperty(self: Store, allocator: std.mem.Allocator, edge_id: core.EdgeId, key: []const u8, value: []const u8) !void {
        if (!edgePropertyOverlayStringKeySupported(key)) return error.InvalidRecord;
        try self.setStringPropertyPayload(allocator, .{ .edge = edge_id }, key, value);
    }

    pub fn getEdgeStringProperty(self: Store, allocator: std.mem.Allocator, edge_id: core.EdgeId, key: []const u8) !?[]u8 {
        if (!edgePropertyOverlayStringKeySupported(key)) return null;
        _ = try self.readVisibleEdgeIndexRecordById(edge_id);
        var payload_entry = try self.readPropertyPayloadEntryForKey(allocator, .{ .edge = edge_id }, key);
        defer if (payload_entry) |*entry| entry.deinit(allocator);
        if (payload_entry) |*entry| {
            if (entry.record.value_type != PropertyPayloadIndexRecord.value_type_string) return error.InvalidRecord;
            const value = entry.value orelse return error.InvalidRecord;
            entry.value = null;
            return value;
        }
        var entries = try self.readEdgePropertyOverlayEntriesOrEmpty(allocator);
        defer {
            deinitNodePropertyIndexEntries(entries.items, allocator);
            entries.deinit(allocator);
        }
        for (entries.items) |entry| {
            if (!edgePropertyOverlayEntryMatchesEdgeKey(entry, edge_id, key)) continue;
            const value = entry.value orelse return error.InvalidRecord;
            return try allocator.dupe(u8, value);
        }
        return null;
    }

    pub fn setUintProperty(self: Store, allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8, value: u64) !void {
        try self.setUintPropertyPayload(allocator, owner, key, value);
    }

    pub fn getUintProperty(self: Store, allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8) !?u64 {
        if (!uintPropertyKeySupportedForOwner(owner, key)) return null;
        switch (owner) {
            .node => |node_id| {
                var node = (try self.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
                node.deinit(allocator);
            },
            .edge => |edge_id| _ = try self.readVisibleEdgeIndexRecordById(edge_id),
        }
        var entry = try self.readPropertyPayloadEntryForKey(allocator, owner, key) orelse return null;
        defer entry.deinit(allocator);
        if (entry.record.value_type != PropertyPayloadIndexRecord.value_type_uint or entry.value != null) return error.InvalidRecord;
        return entry.record.value_hash;
    }

    pub fn setStringProperty(self: Store, allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8, value: []const u8) !void {
        switch (owner) {
            .node => |node_id| try self.setNodeStringProperty(allocator, node_id, key, value),
            .edge => |edge_id| try self.setEdgeStringProperty(allocator, edge_id, key, value),
        }
    }

    pub fn getStringProperty(self: Store, allocator: std.mem.Allocator, owner: PropertyOwner, key: []const u8) !?[]u8 {
        return switch (owner) {
            .node => |node_id| try self.getNodeStringProperty(allocator, node_id, key),
            .edge => |edge_id| try self.getEdgeStringProperty(allocator, edge_id, key),
        };
    }

    fn updateNodePropertyIndexForNodeAppend(self: Store, old_meta: IndexMeta, next_meta: IndexMeta, node: graph_mod.Node) !void {
        var new_entries = std.ArrayList(NodePropertyIndexEntry).empty;
        defer {
            deinitNodePropertyIndexEntries(new_entries.items, self.allocator);
            new_entries.deinit(self.allocator);
        }
        try appendNodePropertyRecordsFromText(&new_entries, self.allocator, node.id, node.text);
        if (new_entries.items.len == 0) return;
        var entries = try self.readNodePropertyIndexEntriesForMeta(self.allocator, old_meta);
        defer {
            deinitNodePropertyIndexEntries(entries.items, self.allocator);
            entries.deinit(self.allocator);
        }
        try entries.appendSlice(self.allocator, new_entries.items);
        new_entries.items.len = 0;
        try self.writeNodePropertyIndex(entries.items, next_meta);
    }

    fn updateNodePropertyIndexForNodeBatch(self: Store, old_meta: IndexMeta, next_meta: IndexMeta, nodes: []const graph_mod.Node) !void {
        var entries = try self.readNodePropertyIndexEntriesForMeta(self.allocator, old_meta);
        defer {
            deinitNodePropertyIndexEntries(entries.items, self.allocator);
            entries.deinit(self.allocator);
        }
        const before = entries.items.len;
        for (nodes) |node| try appendNodePropertyRecordsFromText(&entries, self.allocator, node.id, node.text);
        if (entries.items.len != before) try self.writeNodePropertyIndex(entries.items, next_meta);
    }

    pub fn lookupEdgeByExternalKey(self: Store, allocator: std.mem.Allocator, external_key: []const u8) !?core.EdgeId {
        const indexed = self.lookupEdgeByExternalKeyFromCurrentIndex(allocator, external_key) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => blk: {
                try self.rebuildEdgeExternalKeyIndex();
                break :blk try self.lookupEdgeByExternalKeyFromCurrentIndex(allocator, external_key);
            },
            else => |e| return e,
        };
        if (indexed) |edge_id| return edge_id;
        return try self.scanEdgeByExternalKey(allocator, external_key);
    }

    pub fn buildEdgeExternalKeyLookupCache(self: Store, allocator: std.mem.Allocator) !EdgeExternalKeyLookupCache {
        var node_keys = try self.nodeExternalKeyMap(allocator);
        errdefer {
            var iterator = node_keys.iterator();
            while (iterator.next()) |entry| allocator.free(entry.value_ptr.*);
            node_keys.deinit();
        }
        var order_map = try self.edgeOrderMap(allocator);
        errdefer order_map.deinit();
        return .{
            .allocator = allocator,
            .node_keys = node_keys,
            .order_map = order_map,
        };
    }

    pub fn lookupEdgeByExternalKeyCached(self: Store, allocator: std.mem.Allocator, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !?core.EdgeId {
        if (try self.lookupEdgeRecordByExternalKeyCached(allocator, external_key, cache)) |record| return .fromInt(record.edge_id);
        return null;
    }

    pub fn lookupEdgeRecordByExternalKeyCached(self: Store, allocator: std.mem.Allocator, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !?EdgeIndexRecord {
        const indexed = self.lookupEdgeByExternalKeyFromCurrentIndexCached(allocator, external_key, cache) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => blk: {
                try self.rebuildEdgeExternalKeyIndex();
                break :blk try self.lookupEdgeByExternalKeyFromCurrentIndexCached(allocator, external_key, cache);
            },
            else => |e| return e,
        };
        if (indexed) |edge| return edge;
        return try self.scanEdgeRecordByExternalKeyCached(allocator, external_key, cache);
    }

    pub fn lookupFactEdgeByNodeExternalKeys(self: Store, allocator: std.mem.Allocator, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) !?core.EdgeId {
        const external_key = try self.factEdgeExternalKeyForNodesAlloc(allocator, src, rel, dst);
        defer if (external_key) |key| allocator.free(key);
        if (external_key) |key| {
            if (try self.lookupEdgeByExternalKey(allocator, key)) |edge_id| return edge_id;
        } else {
            return null;
        }
        var records = try self.readVisibleEdgeIndexRecordsByNodeForOrderedTraversal(allocator, src);
        defer records.deinit(allocator);
        for (records.items) |record| {
            if (record.rel == @intFromEnum(rel) and record.dst == dst.toInt()) return .fromInt(record.edge_id);
        }
        return null;
    }

    pub fn refreshFactEdgeExternalKeyIndexAfterAppend(self: Store, edge: graph_mod.Edge) !void {
        const current_meta = try self.readCurrentIndexMeta();
        const record = EdgeIndexRecord{
            .src = edge.src.toInt(),
            .dst = edge.dst.toInt(),
            .edge_id = edge.id.toInt(),
            .rel = @intFromEnum(edge.rel),
        };
        const edge_digest = edgeRecordDigest(record);
        if (current_meta.edge_indexed_edges == 0) return error.InvalidRecord;
        if (current_meta.edges == 0) return error.InvalidRecord;
        var previous_meta = current_meta;
        previous_meta.edges -= 1;
        previous_meta.edge_digest ^= edge_digest;
        previous_meta.edge_indexed_edges -= 1;
        previous_meta.edge_index_digest ^= edge_digest;
        var records = try self.readEdgeExternalKeyIndexRecordsForMeta(self.allocator, previous_meta);
        defer records.deinit(self.allocator);
        var node_keys = try self.nodeExternalKeyMap(self.allocator);
        defer {
            var iterator = node_keys.iterator();
            while (iterator.next()) |entry| self.allocator.free(entry.value_ptr.*);
            node_keys.deinit();
        }
        const before = records.items.len;
        try self.appendFactEdgeExternalKeyRecordForEdge(&records, node_keys, record);
        if (records.items.len == before) return;
        try self.writeEdgeExternalKeyIndex(records.items, current_meta);
    }

    fn lookupEdgeByExternalKeyFromCurrentIndex(self: Store, allocator: std.mem.Allocator, external_key: []const u8) !?core.EdgeId {
        if (external_key.len == 0) return null;
        const meta = try self.readCurrentIndexMeta();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_external_key_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readEdgeExternalKeyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest or
            header.edge_count != meta.edge_indexed_edges or header.edge_digest != meta.edge_index_digest)
        {
            return error.InvalidRecord;
        }
        if (try self.regularFileSize(file) != try edgeExternalKeyIndexFileSize(header.record_count)) return error.InvalidRecord;

        const key_hash = edgeExternalKeyHash(external_key);
        const first = try self.edgeExternalKeyIndexLowerBound(file, header, key_hash);
        var index: u64 = first;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readEdgeExternalKeyIndexRecordAt(file, index);
            if (record.hash != key_hash) break;
            if (try self.edgeMatchesExternalKey(allocator, record.edge_id, external_key)) return .fromInt(record.edge_id);
        }
        return null;
    }

    fn lookupEdgeByExternalKeyFromCurrentIndexCached(self: Store, allocator: std.mem.Allocator, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !?EdgeIndexRecord {
        if (external_key.len == 0) return null;
        const meta = try self.readCurrentIndexMeta();
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_external_key_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readEdgeExternalKeyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest or
            header.edge_count != meta.edge_indexed_edges or header.edge_digest != meta.edge_index_digest)
        {
            return error.InvalidRecord;
        }
        if (try self.regularFileSize(file) != try edgeExternalKeyIndexFileSize(header.record_count)) return error.InvalidRecord;

        const key_hash = edgeExternalKeyHash(external_key);
        const first = try self.edgeExternalKeyIndexLowerBound(file, header, key_hash);
        var index: u64 = first;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readEdgeExternalKeyIndexRecordAt(file, index);
            if (record.hash != key_hash) break;
            if (try self.edgeRecordMatchesExternalKeyCached(allocator, record.edge_id, external_key, cache)) |edge| return edge;
        }
        return null;
    }

    fn scanEdgeByExternalKey(self: Store, allocator: std.mem.Allocator, external_key: []const u8) !?core.EdgeId {
        var cache = try self.buildEdgeExternalKeyLookupCache(allocator);
        defer cache.deinit();
        if (try self.scanEdgeRecordByExternalKeyCached(allocator, external_key, &cache)) |edge| return .fromInt(edge.edge_id);
        return null;
    }

    fn scanEdgeRecordByExternalKeyCached(self: Store, allocator: std.mem.Allocator, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !?EdgeIndexRecord {
        if (external_key.len == 0) return null;
        const ScanContext = struct {
            store: Store,
            allocator: std.mem.Allocator,
            external_key: []const u8,
            cache: *EdgeExternalKeyLookupCache,
            found: ?EdgeIndexRecord = null,

            fn visit(raw_context: *anyopaque, edge: EdgeIndexRecord) anyerror!void {
                const context: *@This() = @ptrCast(@alignCast(raw_context));
                // Keep consuming the stream after a match. The terminal
                // count/digest check is part of the storage integrity
                // contract, not an optional cost of an unsuccessful lookup.
                if (context.found != null) return;
                context.found = try context.store.edgeRecordMatchesExternalKeyCachedRecord(
                    context.allocator,
                    edge,
                    context.external_key,
                    context.cache,
                );
            }
        };
        var context = ScanContext{
            .store = self,
            .allocator = allocator,
            .external_key = external_key,
            .cache = cache,
        };
        _ = try self.scanVisibleEdgeIndexRecords(allocator, &context, ScanContext.visit);
        return context.found;
    }

    fn factEdgeExternalKeyForNodesAlloc(self: Store, allocator: std.mem.Allocator, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) !?[]u8 {
        var src_node = (try self.readNodeById(allocator, src)) orelse return null;
        defer src_node.deinit(allocator);
        var dst_node = (try self.readNodeById(allocator, dst)) orelse return null;
        defer dst_node.deinit(allocator);
        const src_key = try self.getNodeStringProperty(allocator, src, "external_key");
        defer if (src_key) |key| allocator.free(key);
        const dst_key = try self.getNodeStringProperty(allocator, dst, "external_key");
        defer if (dst_key) |key| allocator.free(key);
        if (src_key == null or dst_key == null) return null;
        return try edgeFactExternalKeyAlloc(allocator, src_key.?, rel, dst_key.?);
    }

    fn edgeMatchesExternalKey(self: Store, allocator: std.mem.Allocator, edge_id: u64, external_key: []const u8) !bool {
        const edge = self.readVisibleEdgeIndexRecordById(.fromInt(edge_id)) catch |err| switch (err) {
            core.Error.InvalidId => return false,
            else => |e| return e,
        };
        var order_map = try self.edgeOrderMap(allocator);
        defer order_map.deinit();
        var node_keys = try self.nodeExternalKeyMap(allocator);
        defer {
            var iterator = node_keys.iterator();
            while (iterator.next()) |entry| allocator.free(entry.value_ptr.*);
            node_keys.deinit();
        }
        const src_key = node_keys.get(edge.src) orelse return false;
        const rel: core.RelKind = @enumFromInt(edge.rel);
        if (order_map.get(edge.edge_id)) |order_key| {
            const key = try orderedEdgeExternalKeyAlloc(allocator, src_key, rel, order_key);
            defer allocator.free(key);
            return std.mem.eql(u8, key, external_key);
        }
        const dst_key = node_keys.get(edge.dst) orelse return false;
        const key = try edgeFactExternalKeyAlloc(allocator, src_key, rel, dst_key);
        defer allocator.free(key);
        return std.mem.eql(u8, key, external_key);
    }

    fn edgeMatchesExternalKeyCached(self: Store, allocator: std.mem.Allocator, edge_id: u64, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !bool {
        return (try self.edgeRecordMatchesExternalKeyCached(allocator, edge_id, external_key, cache)) != null;
    }

    fn edgeRecordMatchesExternalKeyCached(self: Store, allocator: std.mem.Allocator, edge_id: u64, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !?EdgeIndexRecord {
        const edge = self.readVisibleEdgeIndexRecordById(.fromInt(edge_id)) catch |err| switch (err) {
            core.Error.InvalidId => return null,
            else => |e| return e,
        };
        return try self.edgeRecordMatchesExternalKeyCachedRecord(allocator, edge, external_key, cache);
    }

    fn edgeRecordMatchesExternalKeyCachedRecord(self: Store, allocator: std.mem.Allocator, edge: EdgeIndexRecord, external_key: []const u8, cache: *EdgeExternalKeyLookupCache) !?EdgeIndexRecord {
        _ = self;
        const src_key = cache.node_keys.get(edge.src) orelse return null;
        const rel: core.RelKind = @enumFromInt(edge.rel);
        if (cache.order_map.get(edge.edge_id)) |order_key| {
            const key = try orderedEdgeExternalKeyAlloc(allocator, src_key, rel, order_key);
            defer allocator.free(key);
            if (std.mem.eql(u8, key, external_key)) return edge;
            return null;
        }
        const dst_key = cache.node_keys.get(edge.dst) orelse return null;
        const key = try edgeFactExternalKeyAlloc(allocator, src_key, rel, dst_key);
        defer allocator.free(key);
        if (std.mem.eql(u8, key, external_key)) return edge;
        return null;
    }

    pub fn rebuildEdgeExternalKeyIndex(self: Store) !void {
        const meta = try self.readCurrentIndexMeta();
        var records = std.ArrayList(EdgeExternalKeyIndexRecord).empty;
        defer records.deinit(self.allocator);
        var node_keys = try self.nodeExternalKeyMap(self.allocator);
        defer {
            var iterator = node_keys.iterator();
            while (iterator.next()) |entry| self.allocator.free(entry.value_ptr.*);
            node_keys.deinit();
        }
        var order_map = try self.edgeOrderMap(self.allocator);
        defer order_map.deinit();
        const RebuildContext = struct {
            store: Store,
            records: *std.ArrayList(EdgeExternalKeyIndexRecord),
            node_keys: std.AutoHashMap(u64, []u8),
            order_map: std.AutoHashMap(u64, u64),

            fn visit(raw_context: *anyopaque, edge: EdgeIndexRecord) anyerror!void {
                const context: *@This() = @ptrCast(@alignCast(raw_context));
                try context.store.appendEdgeExternalKeyRecordsForEdge(context.records, context.node_keys, context.order_map, edge);
            }
        };
        var context = RebuildContext{
            .store = self,
            .records = &records,
            .node_keys = node_keys,
            .order_map = order_map,
        };
        _ = try self.scanVisibleEdgeIndexRecords(self.allocator, &context, RebuildContext.visit);
        try self.writeEdgeExternalKeyIndex(records.items, meta);
    }

    fn nodeExternalKeyMap(self: Store, allocator: std.mem.Allocator) !std.AutoHashMap(u64, []u8) {
        var out = std.AutoHashMap(u64, []u8).init(allocator);
        errdefer {
            var iterator = out.iterator();
            while (iterator.next()) |entry| allocator.free(entry.value_ptr.*);
            out.deinit();
        }
        var payload_entries = try self.readPropertyPayloadEntriesOrEmpty(allocator);
        defer {
            deinitPropertyPayloadIndexEntries(payload_entries.items, allocator);
            payload_entries.deinit(allocator);
        }
        var iterator = try self.nodeRecordsIterator(null);
        defer iterator.deinit();
        while (try iterator.next(allocator)) |node| {
            defer {
                var mutable = node;
                mutable.deinit(allocator);
            }
            if (propertyPayloadStringValue(payload_entries.items, .{ .node = node.id }, "external_key")) |external_key| {
                const owned_key = try allocator.dupe(u8, external_key);
                errdefer allocator.free(owned_key);
                try out.put(node.id.toInt(), owned_key);
            }
        }
        return out;
    }

    fn edgeOrderMap(self: Store, allocator: std.mem.Allocator) !std.AutoHashMap(u64, u64) {
        var out = std.AutoHashMap(u64, u64).init(allocator);
        errdefer out.deinit();
        var order_records = self.readAllEdgeOrderRecords(allocator) catch |err| switch (err) {
            error.FileNotFound => return out,
            else => |e| return e,
        };
        defer order_records.deinit(allocator);
        for (order_records.items) |record| try out.put(record.edge_id, record.order_key);
        return out;
    }

    fn appendEdgeExternalKeyRecordsForEdge(
        self: Store,
        records: *std.ArrayList(EdgeExternalKeyIndexRecord),
        node_keys: std.AutoHashMap(u64, []u8),
        order_map: std.AutoHashMap(u64, u64),
        edge: EdgeIndexRecord,
    ) !void {
        const src_key = node_keys.get(edge.src) orelse return;
        const rel: core.RelKind = @enumFromInt(edge.rel);
        if (order_map.get(edge.edge_id)) |order_key| {
            const key = try orderedEdgeExternalKeyAlloc(self.allocator, src_key, rel, order_key);
            defer self.allocator.free(key);
            try records.append(self.allocator, .{
                .hash = edgeExternalKeyHash(key),
                .edge_id = edge.edge_id,
            });
            return;
        }
        const dst_key = node_keys.get(edge.dst) orelse return;
        const key = try edgeFactExternalKeyAlloc(self.allocator, src_key, rel, dst_key);
        defer self.allocator.free(key);
        try records.append(self.allocator, .{
            .hash = edgeExternalKeyHash(key),
            .edge_id = edge.edge_id,
        });
    }

    fn appendFactEdgeExternalKeyRecordForEdge(
        self: Store,
        records: *std.ArrayList(EdgeExternalKeyIndexRecord),
        node_keys: std.AutoHashMap(u64, []u8),
        edge: EdgeIndexRecord,
    ) !void {
        const src_key = node_keys.get(edge.src) orelse return;
        const dst_key = node_keys.get(edge.dst) orelse return;
        const rel: core.RelKind = @enumFromInt(edge.rel);
        const key = try edgeFactExternalKeyAlloc(self.allocator, src_key, rel, dst_key);
        defer self.allocator.free(key);
        try records.append(self.allocator, .{
            .hash = edgeExternalKeyHash(key),
            .edge_id = edge.edge_id,
        });
    }

    fn readEdgeExternalKeyIndexHeaderFromFile(self: Store, file: std.Io.File) !EdgeExternalKeyIndexHeader {
        var bytes: [EdgeExternalKeyIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return EdgeExternalKeyIndexHeader.decode(&bytes);
    }

    fn readEdgeExternalKeyIndexRecordAt(self: Store, file: std.Io.File, index: u64) !EdgeExternalKeyIndexRecord {
        var bytes: [EdgeExternalKeyIndexRecord.encoded_len]u8 = undefined;
        const offset = try edgeExternalKeyIndexRecordOffset(index);
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return EdgeExternalKeyIndexRecord.decode(&bytes);
    }

    fn edgeExternalKeyIndexLowerBound(self: Store, file: std.Io.File, header: EdgeExternalKeyIndexHeader, key_hash: u64) !u64 {
        var lo: u64 = 0;
        var hi: u64 = header.record_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readEdgeExternalKeyIndexRecordAt(file, mid);
            if (record.hash < key_hash) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn writeEdgeExternalKeyIndex(self: Store, records: []EdgeExternalKeyIndexRecord, meta: IndexMeta) !void {
        std.mem.sort(EdgeExternalKeyIndexRecord, records, {}, edgeExternalKeyIndexRecordLessThan);
        const tmp_path = try self.tmpPathFor(self.edge_external_key_index_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try edgeExternalKeyIndexFileSize(@intCast(records.len))));
            defer writer.deinit();
            const header = EdgeExternalKeyIndexHeader{
                .record_count = @intCast(records.len),
                .node_count = meta.nodes,
                .node_digest = meta.node_digest,
                .edge_count = meta.edge_indexed_edges,
                .edge_digest = meta.edge_index_digest,
            };
            var header_bytes: [EdgeExternalKeyIndexHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            var previous: ?EdgeExternalKeyIndexRecord = null;
            for (records) |record| {
                if (previous) |prev| {
                    if (!edgeExternalKeyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
                }
                var record_bytes: [EdgeExternalKeyIndexRecord.encoded_len]u8 = undefined;
                try record.encode(&record_bytes);
                try writer.append(&record_bytes);
                previous = record;
            }
            try writer.flush();
            if (try self.regularFileSize(file) != try edgeExternalKeyIndexFileSize(@intCast(records.len))) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.edge_external_key_index_path);
    }

    fn readEdgeExternalKeyIndexRecordsForMeta(self: Store, allocator: std.mem.Allocator, meta: IndexMeta) !std.ArrayList(EdgeExternalKeyIndexRecord) {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_external_key_index_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readEdgeExternalKeyIndexHeaderFromFile(file);
        if (header.node_count != meta.nodes or header.node_digest != meta.node_digest or
            header.edge_count != meta.edge_indexed_edges or header.edge_digest != meta.edge_index_digest)
        {
            return error.InvalidRecord;
        }
        if (try self.regularFileSize(file) != try edgeExternalKeyIndexFileSize(header.record_count)) return error.InvalidRecord;
        var records = std.ArrayList(EdgeExternalKeyIndexRecord).empty;
        errdefer records.deinit(allocator);
        try records.ensureTotalCapacity(allocator, std.math.cast(usize, header.record_count) orelse return error.RecordTooLarge);
        var previous: ?EdgeExternalKeyIndexRecord = null;
        var index: u64 = 0;
        while (index < header.record_count) : (index += 1) {
            const record = try self.readEdgeExternalKeyIndexRecordAt(file, index);
            if (previous) |prev| {
                if (!edgeExternalKeyIndexRecordLessThan({}, prev, record)) return error.InvalidRecord;
            }
            records.appendAssumeCapacity(record);
            previous = record;
        }
        return records;
    }

    pub fn nodeExistsById(self: Store, node_id: core.NodeId) !bool {
        if (isReservedNodeId(node_id)) return core.Error.InvalidId;
        var view = try self.openNodeByIdIndexView();
        defer view.deinit();
        return try view.nodeExists(node_id);
    }

    pub fn openNodeByIdIndexView(self: Store) !NodeByIdIndexView {
        const meta = try self.readCurrentIndexMeta();
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        return try NodeByIdIndexView.open(self, meta);
    }

    pub fn openNodeRecordView(self: Store) !NodeRecordView {
        const meta = try self.readCurrentIndexMeta();
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        return try NodeRecordView.open(self, meta);
    }

    pub fn nodeRecordsIterator(self: Store, kind_filter: ?core.NodeKind) !NodeRecordIterator {
        return .{
            .view = try self.openNodeRecordView(),
            .kind_filter = kind_filter,
        };
    }

    pub fn lookupNodesByText(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8) !std.ArrayList(StoredNode) {
        const max_nodes = (core.QueryBudget{}).max_visited_nodes;
        var view = try self.openNodeTextLookupView(allocator);
        defer view.deinit();
        var ids = try view.lookupIdsInto(allocator, kind_filter, text, try boundedSentinelCap(max_nodes), .empty);
        defer ids.deinit(allocator);
        if (ids.items.len > max_nodes) return core.Error.BudgetExceeded;
        return try self.materializeTextLookupIdsWithViews(allocator, view.meta, kind_filter, text, ids.items, &view.node_view, &view.texts_view);
    }

    pub fn lookupNodesByTextLimited(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize) !std.ArrayList(StoredNode) {
        if (max_nodes == 0) return .empty;
        if (max_nodes == 1) {
            var lookup = try self.lookupFirstIdByTextLazy(allocator, kind_filter, text, null);
            defer lookup.deinit();
            const id = lookup.id orelse return .empty;
            var single = [_]core.NodeId{id};
            return try self.materializeTextLookupIdsWithViews(allocator, lookup.meta, kind_filter, text, single[0..], &lookup.node_view, &lookup.texts_view);
        }
        var view = try self.openNodeTextLookupView(allocator);
        defer view.deinit();
        var ids = try view.lookupIdsInto(allocator, kind_filter, text, max_nodes, .empty);
        defer ids.deinit(allocator);
        return try self.materializeTextLookupIdsWithViews(allocator, view.meta, kind_filter, text, ids.items, &view.node_view, &view.texts_view);
    }

    pub fn lookupNodesByTextLimitedWithTimings(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize, timings: *NodeTextLookupTimings) !std.ArrayList(StoredNode) {
        if (max_nodes == 0) return .empty;
        if (max_nodes == 1) {
            var lookup = try self.lookupFirstIdByTextLazy(allocator, kind_filter, text, timings);
            defer lookup.deinit();
            const id = lookup.id orelse return .empty;
            var single = [_]core.NodeId{id};
            const materialize_start = self.monotonicNs();
            const nodes = try self.materializeTextLookupIdsWithViews(allocator, lookup.meta, kind_filter, text, single[0..], &lookup.node_view, &lookup.texts_view);
            timings.materialize_ns += self.elapsedNs(materialize_start);
            return nodes;
        }
        var view = try self.openNodeTextLookupView(allocator);
        defer view.deinit();
        var ids = try view.lookupIdsIntoWithTimings(allocator, kind_filter, text, max_nodes, .empty, timings);
        defer ids.deinit(allocator);
        const materialize_start = self.monotonicNs();
        const nodes = try self.materializeTextLookupIdsWithViews(allocator, view.meta, kind_filter, text, ids.items, &view.node_view, &view.texts_view);
        timings.materialize_ns += self.elapsedNs(materialize_start);
        return nodes;
    }

    fn materializeTextLookupIdsWithViews(
        self: Store,
        allocator: std.mem.Allocator,
        meta: IndexMeta,
        kind_filter: ?core.NodeKind,
        text: []const u8,
        ids: []const core.NodeId,
        node_view: *?NodeByIdIndexView,
        texts_view: *?NodeTextsView,
    ) !std.ArrayList(StoredNode) {
        _ = texts_view;
        var out = std.ArrayList(StoredNode).empty;
        errdefer {
            for (out.items) |*node| node.deinit(allocator);
            out.deinit(allocator);
        }
        try out.ensureTotalCapacity(allocator, ids.len);
        if (ids.len == 0) return out;
        const nodes = try ensureNodeByIdIndexView(self, meta, node_view);
        for (ids) |id| {
            const record = (try nodes.readOptionalRecord(id.toInt())) orelse return error.InvalidRecord;
            if (record.id != id.toInt()) return error.InvalidRecord;
            const kind = try record.nodeKind();
            if (kind_filter) |filter| {
                if (kind != filter) return error.InvalidRecord;
            }
            const owned_text = try allocator.dupe(u8, text);
            errdefer allocator.free(owned_text);
            try out.append(allocator, .{
                .id = id,
                .kind = kind,
                .text = owned_text,
            });
        }
        return out;
    }

    pub fn lookupNodeIdsByTextLimited(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize) !std.ArrayList(core.NodeId) {
        return try self.lookupNodeIdsByTextLimitedWithMaybeTimings(allocator, kind_filter, text, max_nodes, null);
    }

    pub fn lookupNodeIdsByTextLimitedWithTimings(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize, timings: *NodeTextLookupTimings) !std.ArrayList(core.NodeId) {
        return try self.lookupNodeIdsByTextLimitedWithMaybeTimings(allocator, kind_filter, text, max_nodes, timings);
    }

    pub fn lookupFirstNodeIdByText(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8) !?core.NodeId {
        var lookup = try self.lookupFirstIdByTextLazy(allocator, kind_filter, text, null);
        defer lookup.deinit();
        return lookup.id;
    }

    pub fn lookupFirstNodeIdByTextWithTimings(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, timings: *NodeTextLookupTimings) !?core.NodeId {
        var lookup = try self.lookupFirstIdByTextLazy(allocator, kind_filter, text, timings);
        const id = lookup.id;
        const cleanup_start = self.monotonicNs();
        lookup.deinit();
        timings.cleanup_ns += self.elapsedNs(cleanup_start);
        return id;
    }

    fn lookupNodeIdsByTextLimitedWithMaybeTimings(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize, timings: ?*NodeTextLookupTimings) !std.ArrayList(core.NodeId) {
        var out = std.ArrayList(core.NodeId).empty;
        if (max_nodes == 0) return out;

        if (max_nodes == 1) {
            var lookup = try self.lookupFirstIdByTextLazy(allocator, kind_filter, text, timings);
            defer lookup.deinit();
            if (lookup.id) |id| {
                try out.append(allocator, id);
            }
            return out;
        }
        var view = try self.openNodeTextLookupView(allocator);
        defer view.deinit();
        return try view.lookupIdsIntoWithTimings(allocator, kind_filter, text, max_nodes, out, timings);
    }

    const LazyFirstNodeTextLookup = struct {
        id: ?core.NodeId = null,
        meta: IndexMeta,
        node_view: ?NodeByIdIndexView = null,
        texts_view: ?NodeTextsView = null,

        fn deinit(self: *LazyFirstNodeTextLookup) void {
            if (self.texts_view) |*view| view.deinit();
            if (self.node_view) |*view| view.deinit();
        }
    };

    fn lookupFirstIdByTextLazy(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, timings: ?*NodeTextLookupTimings) !LazyFirstNodeTextLookup {
        _ = allocator;
        const meta_start = if (timings != null) self.monotonicNs() else 0;
        const meta = try self.readCurrentIndexMeta();
        if (timings) |t| t.lazy_open_meta_ns += self.elapsedNs(meta_start);
        const hash_start = if (timings != null) self.monotonicNs() else 0;
        const hash = nodeTextHash(text);
        if (timings) |t| t.hash_ns += self.elapsedNs(hash_start);

        if (!self.options.validate_indexes_on_read) {
            const base_filter_opt = try self.cachedNodeTextBaseHashFilter(null);
            if (base_filter_opt) |base_filter| {
                if (try self.nodeTextBaseFilterMatchesCurrentBase(base_filter.header) and !nodeTextRunHashFilterMayContain(base_filter.filter, hash)) {
                    if (timings) |t| t.first_base_filter_skip_count += 1;
                    return try self.lookupFirstIdByTextLazyAfterBaseMiss(kind_filter, text, hash, meta, base_filter.header, timings);
                }
            }
        }

        const base_open_start = if (timings != null) self.monotonicNs() else 0;
        var base = try OpenNodeTextLookupRun.open(self, self.node_by_text_path, null, 0, &.{});
        if (timings) |t| t.lazy_open_base_ns += self.elapsedNs(base_open_start);
        defer base.deinit();

        if (nodeTextBaseHeaderCoversMeta(base.header, meta)) {
            const validate_start = if (timings != null) self.monotonicNs() else 0;
            if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
            if (timings) |t| t.lazy_open_validate_ns += self.elapsedNs(validate_start);

            var lookup = LazyFirstNodeTextLookup{
                .meta = meta,
            };
            errdefer lookup.deinit();
            if (timings) |t| t.first_base_probe_count += 1;
            try self.collectFirstNodeTextLookupRun(
                base.borrowed(),
                meta,
                hash,
                kind_filter,
                text,
                &lookup.id,
                &lookup.node_view,
                &lookup.texts_view,
                timings,
            );
            if (lookup.id != null) {
                if (timings) |t| t.first_base_hit_count += 1;
            }
            return lookup;
        }

        const delta_header_start = if (timings != null) self.monotonicNs() else 0;
        const delta_header = try self.readNodeTextDeltaHeader();
        if (timings) |t| t.lazy_open_delta_header_ns += self.elapsedNs(delta_header_start);

        const manifest_start = if (timings != null) self.monotonicNs() else 0;
        var empty_manifest = NodeTextRunManifest{};
        const manifest = (try self.cachedNodeTextRunManifestForMeta(meta)) orelse &empty_manifest;
        if (timings) |t| t.lazy_open_manifest_ns += self.elapsedNs(manifest_start);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;

        const validate_start = if (timings != null) self.monotonicNs() else 0;
        if (base.header.node_count + delta_header.node_count + run_count != meta.nodes) return error.InvalidRecord;
        if ((base.header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != meta.node_digest) return error.InvalidRecord;
        if (manifest.combinedOrderDigest(base.header, delta_header) != meta.node_by_text_order_digest) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        if (timings) |t| t.lazy_open_validate_ns += self.elapsedNs(validate_start);

        var lookup = LazyFirstNodeTextLookup{
            .meta = meta,
        };
        errdefer lookup.deinit();
        if (timings) |t| t.first_base_probe_count += 1;
        try self.collectFirstNodeTextLookupRun(
            base.borrowed(),
            meta,
            hash,
            kind_filter,
            text,
            &lookup.id,
            &lookup.node_view,
            &lookup.texts_view,
            timings,
        );
        const base_missed = lookup.id == null;
        if (!base_missed) {
            if (timings) |t| t.first_base_hit_count += 1;
        }

        if (delta_header.node_count != 0 and
            (lookup.id == null or self.options.validate_indexes_on_read or lookup.id.?.toInt() != 1))
        {
            const delta_open_start = if (timings != null) self.monotonicNs() else 0;
            var owned_delta: ?OpenNodeTextLookupRun = null;
            const delta = (try self.cachedNodeTextDeltaRun(delta_header)) orelse blk: {
                owned_delta = try OpenNodeTextLookupRun.open(self, self.node_by_text_delta_path, delta_header, 0, &.{});
                break :blk owned_delta.?.borrowed();
            };
            if (timings) |t| t.lazy_open_delta_ns += self.elapsedNs(delta_open_start);
            defer if (owned_delta) |*run| run.deinit();
            const before_delta = lookup.id;
            if (timings) |t| t.first_delta_probe_count += 1;
            try self.collectFirstNodeTextLookupRun(
                delta,
                meta,
                hash,
                kind_filter,
                text,
                &lookup.id,
                &lookup.node_view,
                &lookup.texts_view,
                timings,
            );
            if (lookup.id != before_delta) {
                if (timings) |t| {
                    t.first_delta_hit_count += 1;
                    if (base_missed) t.first_base_miss_before_later_hit_count += 1;
                }
            }
        }

        for (manifest.entries.items, 0..) |entry, entry_index| {
            if (!self.options.validate_indexes_on_read and !nodeTextRunManifestEntryMayContainHash(entry, hash)) {
                if (timings) |t| t.range_skip_count += 1;
                continue;
            }
            if (lookup.id) |current| {
                if (!self.options.validate_indexes_on_read) {
                    if (current.toInt() == 1) {
                        if (timings) |t| t.range_skip_count += @intCast(manifest.entries.items.len - entry_index);
                        break;
                    }
                    if (current.toInt() <= entry.min_node_id) {
                        if (timings) |t| t.range_skip_count += 1;
                        continue;
                    }
                }
            }
            const run_open_start = if (timings != null) self.monotonicNs() else 0;
            var run = try OpenNodeTextLookupRun.openBorrowedHashFilter(self, entry.path, entry.header(), entry.min_node_id, entry.hash_filter);
            if (timings) |t| t.lazy_open_runs_ns += self.elapsedNs(run_open_start);
            defer run.deinit();
            const before_run = lookup.id;
            if (timings) |t| t.first_run_probe_count += 1;
            try self.collectFirstNodeTextLookupRun(
                run.borrowed(),
                meta,
                hash,
                kind_filter,
                text,
                &lookup.id,
                &lookup.node_view,
                &lookup.texts_view,
                timings,
            );
            if (lookup.id != before_run) {
                if (timings) |t| {
                    t.first_run_hit_count += 1;
                    if (base_missed) t.first_base_miss_before_later_hit_count += 1;
                }
            }
        }
        return lookup;
    }

    fn lookupFirstIdByTextLazyAfterBaseMiss(self: Store, kind_filter: ?core.NodeKind, text: []const u8, hash: u64, meta: IndexMeta, base_header: NodeTextIndexHeader, timings: ?*NodeTextLookupTimings) !LazyFirstNodeTextLookup {
        if (nodeTextBaseHeaderCoversMeta(base_header, meta)) {
            return .{ .meta = meta };
        }

        const delta_header_start = if (timings != null) self.monotonicNs() else 0;
        const delta_header = try self.readNodeTextDeltaHeader();
        if (timings) |t| t.lazy_open_delta_header_ns += self.elapsedNs(delta_header_start);

        const manifest_start = if (timings != null) self.monotonicNs() else 0;
        var empty_manifest = NodeTextRunManifest{};
        const manifest = (try self.cachedNodeTextRunManifestForMeta(meta)) orelse &empty_manifest;
        if (timings) |t| t.lazy_open_manifest_ns += self.elapsedNs(manifest_start);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;

        const validate_start = if (timings != null) self.monotonicNs() else 0;
        if (base_header.node_count + delta_header.node_count + run_count != meta.nodes) return error.InvalidRecord;
        if ((base_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != meta.node_digest) return error.InvalidRecord;
        if (manifest.combinedOrderDigest(base_header, delta_header) != meta.node_by_text_order_digest) return error.InvalidRecord;
        if (timings) |t| t.lazy_open_validate_ns += self.elapsedNs(validate_start);

        var lookup = LazyFirstNodeTextLookup{
            .meta = meta,
        };
        errdefer lookup.deinit();
        const base_missed = true;

        if (delta_header.node_count != 0) {
            const delta_open_start = if (timings != null) self.monotonicNs() else 0;
            var owned_delta: ?OpenNodeTextLookupRun = null;
            const delta = (try self.cachedNodeTextDeltaRun(delta_header)) orelse blk: {
                owned_delta = try OpenNodeTextLookupRun.open(self, self.node_by_text_delta_path, delta_header, 0, &.{});
                break :blk owned_delta.?.borrowed();
            };
            if (timings) |t| t.lazy_open_delta_ns += self.elapsedNs(delta_open_start);
            defer if (owned_delta) |*run| run.deinit();
            const before_delta = lookup.id;
            if (timings) |t| t.first_delta_probe_count += 1;
            try self.collectFirstNodeTextLookupRun(
                delta,
                meta,
                hash,
                kind_filter,
                text,
                &lookup.id,
                &lookup.node_view,
                &lookup.texts_view,
                timings,
            );
            if (lookup.id != before_delta) {
                if (timings) |t| {
                    t.first_delta_hit_count += 1;
                    if (base_missed) t.first_base_miss_before_later_hit_count += 1;
                }
            }
        }

        for (manifest.entries.items, 0..) |entry, entry_index| {
            if (!nodeTextRunManifestEntryMayContainHash(entry, hash)) {
                if (timings) |t| t.range_skip_count += 1;
                continue;
            }
            if (lookup.id) |current| {
                if (current.toInt() == 1) {
                    if (timings) |t| t.range_skip_count += @intCast(manifest.entries.items.len - entry_index);
                    break;
                }
                if (current.toInt() <= entry.min_node_id) {
                    if (timings) |t| t.range_skip_count += 1;
                    continue;
                }
            }
            const run_open_start = if (timings != null) self.monotonicNs() else 0;
            var run = try OpenNodeTextLookupRun.openBorrowedHashFilter(self, entry.path, entry.header(), entry.min_node_id, entry.hash_filter);
            if (timings) |t| t.lazy_open_runs_ns += self.elapsedNs(run_open_start);
            defer run.deinit();
            const before_run = lookup.id;
            if (timings) |t| t.first_run_probe_count += 1;
            try self.collectFirstNodeTextLookupRun(
                run.borrowed(),
                meta,
                hash,
                kind_filter,
                text,
                &lookup.id,
                &lookup.node_view,
                &lookup.texts_view,
                timings,
            );
            if (lookup.id != before_run) {
                if (timings) |t| {
                    t.first_run_hit_count += 1;
                    if (base_missed) t.first_base_miss_before_later_hit_count += 1;
                }
            }
        }
        return lookup;
    }

    fn remainingNodeTextRunsSkippedFromIndex(runs_len: usize, run_index: usize) u64 {
        return @intCast(runs_len - run_index);
    }

    pub fn openNodeTextLookupView(self: Store, allocator: std.mem.Allocator) !NodeTextLookupView {
        return self.openNodeTextLookupViewMaybeRetained(allocator, null, null);
    }

    pub fn openNodeTextLookupViewWithTimings(self: Store, allocator: std.mem.Allocator, timings: *NodeTextLookupOpenTimings) !NodeTextLookupView {
        return self.openNodeTextLookupViewMaybeRetained(allocator, null, timings);
    }

    pub fn openNodeTextLookupViewRetained(self: Store, allocator: std.mem.Allocator, registry: *NodeTextRunRetentionRegistry) !NodeTextLookupView {
        return self.openNodeTextLookupViewMaybeRetained(allocator, registry, null);
    }

    fn openNodeTextLookupViewMaybeRetained(self: Store, allocator: std.mem.Allocator, retention_registry: ?*NodeTextRunRetentionRegistry, timings: ?*NodeTextLookupOpenTimings) !NodeTextLookupView {
        const meta_start = if (timings != null) self.monotonicNs() else 0;
        const meta = try self.readCurrentIndexMeta();
        if (timings) |t| t.meta_ns += self.elapsedNs(meta_start);

        const base_open_start = if (timings != null) self.monotonicNs() else 0;
        var base = try OpenNodeTextLookupRun.open(self, self.node_by_text_path, null, 0, &.{});
        if (timings) |t| t.base_open_ns += self.elapsedNs(base_open_start);
        errdefer base.deinit();

        if (nodeTextBaseHeaderCoversMeta(base.header, meta)) {
            const validate_start = if (timings != null) self.monotonicNs() else 0;
            if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
            if (timings) |t| t.validate_ns += self.elapsedNs(validate_start);
            return .{
                .store = self,
                .allocator = allocator,
                .meta = meta,
                .base = base,
                .overlay_record_count = 0,
            };
        }

        const delta_header_start = if (timings != null) self.monotonicNs() else 0;
        const delta_header = try self.readNodeTextDeltaHeader();
        if (timings) |t| t.delta_header_ns += self.elapsedNs(delta_header_start);

        var retention_window: ?NodeTextRunRegisteredRetentionWindow = null;
        errdefer if (retention_window) |*window| window.deinit();
        const manifest_start = if (timings != null) self.monotonicNs() else 0;
        var manifest = if (retention_registry) |registry| blk: {
            retention_window = try self.openRegisteredNodeTextRunRetentionWindow(registry);
            if (retention_window.?.manifest_path) |manifest_path| {
                break :blk try self.readNodeTextRunManifestFile(allocator, manifest_path);
            }
            break :blk NodeTextRunManifest{};
        } else try self.readNodeTextRunManifest(allocator);
        if (timings) |t| t.manifest_ns += self.elapsedNs(manifest_start);
        errdefer manifest.deinit(allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (timings) |t| t.run_entries = @intCast(manifest.entries.items.len);

        const validate_start = if (timings != null) self.monotonicNs() else 0;
        if (base.header.node_count + delta_header.node_count + run_count != meta.nodes) return error.InvalidRecord;
        if ((base.header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != meta.node_digest) return error.InvalidRecord;
        if (manifest.combinedOrderDigest(base.header, delta_header) != meta.node_by_text_order_digest) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        if (timings) |t| t.validate_ns += self.elapsedNs(validate_start);

        var delta: ?OpenNodeTextLookupRun = null;
        errdefer if (delta) |*run| run.deinit();
        if (delta_header.node_count != 0) {
            const delta_open_start = if (timings != null) self.monotonicNs() else 0;
            delta = try OpenNodeTextLookupRun.open(self, self.node_by_text_delta_path, delta_header, 0, &.{});
            if (timings) |t| t.delta_open_ns += self.elapsedNs(delta_open_start);
        }

        var runs = std.ArrayList(NodeTextLookupViewRun).empty;
        errdefer {
            for (runs.items) |*run| run.deinit();
            runs.deinit(allocator);
        }
        const runs_open_start = if (timings != null) self.monotonicNs() else 0;
        try runs.ensureTotalCapacity(allocator, manifest.entries.items.len);
        var runs_open_count: u64 = 0;
        for (manifest.entries.items) |entry| {
            var run = NodeTextLookupViewRun{};
            if (self.options.validate_indexes_on_read) {
                run.opened = try OpenNodeTextLookupRun.open(self, entry.path, entry.header(), entry.min_node_id, entry.hash_filter);
                runs_open_count += 1;
            }
            runs.appendAssumeCapacity(run);
        }
        if (timings) |t| {
            t.runs_open_ns += self.elapsedNs(runs_open_start);
            t.runs_open_count = runs_open_count;
        }

        return .{
            .store = self,
            .allocator = allocator,
            .meta = meta,
            .base = base,
            .delta = delta,
            .runs = runs,
            .run_manifest = manifest,
            .overlay_record_count = try std.math.add(u64, delta_header.node_count, run_count),
            .retention_window = retention_window,
        };
    }

    const OpenNodeTextLookupRun = struct {
        store: Store,
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        header: NodeTextIndexHeader,
        min_node_id: u64 = 0,
        hash_filter: []const u8 = &.{},
        owned_hash_filter: []u8 = &.{},

        fn open(store: Store, path: []const u8, expected_header: ?NodeTextIndexHeader, min_node_id: u64, hash_filter: []const u8) !OpenNodeTextLookupRun {
            return openWithHashFilterOwnership(store, path, expected_header, min_node_id, hash_filter, true);
        }

        fn openBorrowedHashFilter(store: Store, path: []const u8, expected_header: ?NodeTextIndexHeader, min_node_id: u64, hash_filter: []const u8) !OpenNodeTextLookupRun {
            return openWithHashFilterOwnership(store, path, expected_header, min_node_id, hash_filter, false);
        }

        fn openWithHashFilterOwnership(store: Store, path: []const u8, expected_header: ?NodeTextIndexHeader, min_node_id: u64, hash_filter: []const u8, copy_hash_filter: bool) !OpenNodeTextLookupRun {
            var file = try std.Io.Dir.cwd().openFile(store.io, path, .{});
            errdefer file.close(store.io);
            const header = try store.readNodeTextIndexHeaderFromFile(file);
            if (expected_header) |expected| {
                if (header.node_count != expected.node_count or
                    header.node_digest != expected.node_digest or
                    header.order_digest != expected.order_digest) return error.InvalidRecord;
            }
            const expected_size = try nodeTextIndexFileSizeForHeader(header);
            if (try store.regularFileSize(file) != expected_size) return error.InvalidRecord;
            var map = openReadOnlyMemoryMap(store.io, file, expected_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(store.io);
            var owned_hash_filter: []u8 = &.{};
            const run_hash_filter = if (copy_hash_filter and hash_filter.len != 0) blk: {
                owned_hash_filter = try store.allocator.dupe(u8, hash_filter);
                break :blk owned_hash_filter;
            } else hash_filter;
            errdefer store.allocator.free(owned_hash_filter);
            return .{
                .store = store,
                .file = file,
                .map = map,
                .header = header,
                .min_node_id = min_node_id,
                .hash_filter = run_hash_filter,
                .owned_hash_filter = owned_hash_filter,
            };
        }

        fn deinit(self: *OpenNodeTextLookupRun) void {
            if (self.map) |*map| map.destroy(self.store.io);
            self.file.close(self.store.io);
            self.store.allocator.free(self.owned_hash_filter);
        }

        fn borrowed(self: *const OpenNodeTextLookupRun) NodeTextLookupRun {
            return .{
                .file = self.file,
                .map = if (self.map) |*mapped| mapped else null,
                .header = self.header,
                .min_node_id = self.min_node_id,
                .hash_filter = self.hash_filter,
            };
        }
    };

    const NodeTextDeltaRunCache = struct {
        run: ?OpenNodeTextLookupRun = null,

        fn clear(self: *NodeTextDeltaRunCache) void {
            if (self.run) |*run| run.deinit();
            self.* = .{};
        }
    };

    const NodeTextLookupViewRun = struct {
        opened: ?OpenNodeTextLookupRun = null,

        fn deinit(self: *NodeTextLookupViewRun) void {
            if (self.opened) |*run| run.deinit();
            self.* = .{};
        }
    };

    pub const NodeTextLookupView = struct {
        store: Store,
        allocator: std.mem.Allocator,
        meta: IndexMeta,
        base: OpenNodeTextLookupRun,
        delta: ?OpenNodeTextLookupRun = null,
        runs: std.ArrayList(NodeTextLookupViewRun) = .empty,
        run_manifest: NodeTextRunManifest = .{},
        overlay_record_count: u64 = 0,
        node_view: ?NodeByIdIndexView = null,
        texts_view: ?NodeTextsView = null,
        retention_window: ?NodeTextRunRegisteredRetentionWindow = null,

        pub fn deinit(self: *NodeTextLookupView) void {
            if (self.texts_view) |*view| view.deinit();
            if (self.node_view) |*view| view.deinit();
            for (self.runs.items) |*run| run.deinit();
            self.runs.deinit(self.allocator);
            if (self.delta) |*run| run.deinit();
            self.base.deinit();
            self.run_manifest.deinit(self.allocator);
            if (self.retention_window) |*window| window.deinit();
            self.retention_window = null;
        }

        pub fn lookupIds(self: *NodeTextLookupView, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize) !std.ArrayList(core.NodeId) {
            const out = std.ArrayList(core.NodeId).empty;
            if (max_nodes == 0) return out;
            return try self.lookupIdsInto(allocator, kind_filter, text, max_nodes, out);
        }

        pub fn lookupIdsWithTimings(self: *NodeTextLookupView, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize, timings: *NodeTextLookupTimings) !std.ArrayList(core.NodeId) {
            const out = std.ArrayList(core.NodeId).empty;
            if (max_nodes == 0) return out;
            return try self.lookupIdsIntoWithTimings(allocator, kind_filter, text, max_nodes, out, timings);
        }

        pub fn lookupFirstId(self: *NodeTextLookupView, kind_filter: ?core.NodeKind, text: []const u8) !?core.NodeId {
            return try self.lookupFirstIdWithMaybeTimings(kind_filter, text, null);
        }

        pub fn lookupFirstIdWithTimings(self: *NodeTextLookupView, kind_filter: ?core.NodeKind, text: []const u8, timings: *NodeTextLookupTimings) !?core.NodeId {
            return try self.lookupFirstIdWithMaybeTimings(kind_filter, text, timings);
        }

        fn lookupFirstIdWithMaybeTimings(self: *NodeTextLookupView, kind_filter: ?core.NodeKind, text: []const u8, timings: ?*NodeTextLookupTimings) !?core.NodeId {
            const hash_start = if (timings != null) self.store.monotonicNs() else 0;
            const hash = nodeTextHash(text);
            if (timings) |t| t.hash_ns += self.store.elapsedNs(hash_start);
            var best: ?core.NodeId = null;
            try self.store.collectFirstNodeTextLookupRun(
                self.base.borrowed(),
                self.meta,
                hash,
                kind_filter,
                text,
                &best,
                &self.node_view,
                &self.texts_view,
                timings,
            );
            if (self.delta) |*delta_run| {
                if (best == null or best.?.toInt() != 1) {
                    try self.store.collectFirstNodeTextLookupRun(
                        delta_run.borrowed(),
                        self.meta,
                        hash,
                        kind_filter,
                        text,
                        &best,
                        &self.node_view,
                        &self.texts_view,
                        timings,
                    );
                }
            }
            for (self.runs.items, 0..) |_, run_index| {
                const entry = self.run_manifest.entries.items[run_index];
                if (best) |current| {
                    if (current.toInt() == 1) {
                        if (timings) |t| t.range_skip_count += remainingNodeTextRunsSkippedFromIndex(self.runs.items.len, run_index);
                        break;
                    }
                    if (current.toInt() <= entry.min_node_id) {
                        if (timings) |t| t.range_skip_count += 1;
                        continue;
                    }
                }
                if (!self.store.options.validate_indexes_on_read and !nodeTextRunManifestEntryMayContainHash(entry, hash)) {
                    if (timings) |t| t.range_skip_count += 1;
                    continue;
                }
                const run = try self.openRun(run_index, timings);
                try self.store.collectFirstNodeTextLookupRun(
                    run,
                    self.meta,
                    hash,
                    kind_filter,
                    text,
                    &best,
                    &self.node_view,
                    &self.texts_view,
                    timings,
                );
            }
            return best;
        }

        fn lookupIdsInto(self: *NodeTextLookupView, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize, out_init: std.ArrayList(core.NodeId)) !std.ArrayList(core.NodeId) {
            return try self.lookupIdsIntoWithTimings(allocator, kind_filter, text, max_nodes, out_init, null);
        }

        fn lookupIdsIntoWithTimings(self: *NodeTextLookupView, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, text: []const u8, max_nodes: usize, out_init: std.ArrayList(core.NodeId), timings: ?*NodeTextLookupTimings) !std.ArrayList(core.NodeId) {
            var out = out_init;
            errdefer out.deinit(allocator);
            if (max_nodes == 1) {
                if (try self.lookupFirstIdWithMaybeTimings(kind_filter, text, timings)) |id| {
                    try out.append(allocator, id);
                }
                return out;
            }
            const hash_start = if (timings != null) self.store.monotonicNs() else 0;
            const hash = nodeTextHash(text);
            if (timings) |t| t.hash_ns += self.store.elapsedNs(hash_start);
            const overlay_collect_cap = std.math.cast(usize, self.overlay_record_count) orelse return core.Error.BudgetExceeded;
            const collect_cap = std.math.add(usize, max_nodes, overlay_collect_cap) catch return core.Error.BudgetExceeded;
            try self.store.collectNodeTextLookupRun(
                allocator,
                self.base.borrowed(),
                self.meta,
                hash,
                kind_filter,
                text,
                max_nodes,
                &out,
                &self.node_view,
                &self.texts_view,
                timings,
            );
            if (self.delta) |*delta_run| {
                try self.store.collectNodeTextLookupRun(
                    allocator,
                    delta_run.borrowed(),
                    self.meta,
                    hash,
                    kind_filter,
                    text,
                    collect_cap,
                    &out,
                    &self.node_view,
                    &self.texts_view,
                    timings,
                );
            }
            for (self.runs.items, 0..) |_, run_index| {
                const entry = self.run_manifest.entries.items[run_index];
                if (!self.store.options.validate_indexes_on_read and !nodeTextRunManifestEntryMayContainHash(entry, hash)) {
                    if (timings) |t| t.range_skip_count += 1;
                    continue;
                }
                const run = try self.openRun(run_index, timings);
                try self.store.collectNodeTextLookupRun(
                    allocator,
                    run,
                    self.meta,
                    hash,
                    kind_filter,
                    text,
                    collect_cap,
                    &out,
                    &self.node_view,
                    &self.texts_view,
                    timings,
                );
            }
            std.mem.sort(core.NodeId, out.items, {}, nodeIdLessThan);
            if (out.items.len > max_nodes) {
                out.shrinkRetainingCapacity(max_nodes);
            }
            return out;
        }

        fn openRun(self: *NodeTextLookupView, run_index: usize, timings: ?*NodeTextLookupTimings) !NodeTextLookupRun {
            if (self.runs.items[run_index].opened == null) {
                const entry = self.run_manifest.entries.items[run_index];
                const run_open_start = if (timings != null) self.store.monotonicNs() else 0;
                self.runs.items[run_index].opened = try OpenNodeTextLookupRun.openBorrowedHashFilter(
                    self.store,
                    entry.path,
                    entry.header(),
                    entry.min_node_id,
                    entry.hash_filter,
                );
                if (timings) |t| t.lazy_open_runs_ns += self.store.elapsedNs(run_open_start);
            }
            return self.runs.items[run_index].opened.?.borrowed();
        }
    };

    const NodeTextLookupRun = struct {
        file: std.Io.File,
        map: ?*const std.Io.File.MemoryMap = null,
        header: NodeTextIndexHeader,
        min_node_id: u64 = 0,
        hash_filter: []const u8 = &.{},
    };

    pub const NodeTextLookupTimings = struct {
        lazy_open_meta_ns: u128 = 0,
        lazy_open_delta_header_ns: u128 = 0,
        lazy_open_manifest_ns: u128 = 0,
        lazy_open_base_ns: u128 = 0,
        lazy_open_validate_ns: u128 = 0,
        lazy_open_delta_ns: u128 = 0,
        lazy_open_runs_ns: u128 = 0,
        search_texts_view_ns: u128 = 0,
        search_node_view_ns: u128 = 0,
        hash_ns: u128 = 0,
        lower_bound_ns: u128 = 0,
        lower_bound_probe_count: u64 = 0,
        lower_bound_max_run_ns: u128 = 0,
        lower_bound_max_run_records: u64 = 0,
        lower_bound_max_run_record_len: u16 = 0,
        lower_bound_max_run_flags: u16 = 0,
        lower_bound_max_run_filter_bytes: u64 = 0,
        lower_bound_max_run_min_node_id: u64 = 0,
        scan_ns: u128 = 0,
        scan_record_count: u64 = 0,
        span_view_ns: u128 = 0,
        record_decode_ns: u128 = 0,
        text_view_ns: u128 = 0,
        text_match_ns: u128 = 0,
        text_compare_ns: u128 = 0,
        by_id_validate_ns: u128 = 0,
        materialize_ns: u128 = 0,
        cleanup_ns: u128 = 0,
        run_count: u64 = 0,
        range_skip_count: u64 = 0,
        first_base_probe_count: u64 = 0,
        first_delta_probe_count: u64 = 0,
        first_run_probe_count: u64 = 0,
        first_base_hit_count: u64 = 0,
        first_delta_hit_count: u64 = 0,
        first_run_hit_count: u64 = 0,
        first_base_miss_before_later_hit_count: u64 = 0,
        first_base_filter_skip_count: u64 = 0,

        fn recordLowerBoundRun(self: *NodeTextLookupTimings, elapsed_ns: u128, run: NodeTextLookupRun) void {
            self.lower_bound_ns += elapsed_ns;
            if (elapsed_ns > self.lower_bound_max_run_ns) {
                self.lower_bound_max_run_ns = elapsed_ns;
                self.lower_bound_max_run_records = run.header.node_count;
                self.lower_bound_max_run_record_len = run.header.record_len;
                self.lower_bound_max_run_flags = run.header.flags;
                self.lower_bound_max_run_filter_bytes = @intCast(run.hash_filter.len);
                self.lower_bound_max_run_min_node_id = run.min_node_id;
            }
        }
    };

    pub const NodeTextLookupOpenTimings = struct {
        meta_ns: u128 = 0,
        delta_header_ns: u128 = 0,
        manifest_ns: u128 = 0,
        base_open_ns: u128 = 0,
        validate_ns: u128 = 0,
        delta_open_ns: u128 = 0,
        runs_open_ns: u128 = 0,
        run_entries: u64 = 0,
        runs_open_count: u64 = 0,
    };

    fn cachedNodeTextDeltaRun(self: Store, expected_header: NodeTextIndexHeader) !?NodeTextLookupRun {
        if (self.options.validate_indexes_on_read or expected_header.node_count == 0) return null;
        if (self.node_text_delta_run_cache.run) |*run| {
            if (nodeTextHeaderMatchesBaseFilter(expected_header, run.header)) {
                return run.borrowed();
            }
            self.node_text_delta_run_cache.clear();
        }
        self.node_text_delta_run_cache.run = try OpenNodeTextLookupRun.open(self, self.node_by_text_delta_path, expected_header, 0, &.{});
        return self.node_text_delta_run_cache.run.?.borrowed();
    }

    fn refreshNodeTextDeltaRunCache(self: Store, expected_header: NodeTextIndexHeader) void {
        self.node_text_delta_run_cache.clear();
        if (self.options.validate_indexes_on_read or expected_header.node_count == 0) return;
        self.node_text_delta_run_cache.run = OpenNodeTextLookupRun.open(self, self.node_by_text_delta_path, expected_header, 0, &.{}) catch null;
    }

    fn monotonicNs(self: Store) u128 {
        const timestamp = std.Io.Clock.awake.now(self.io).nanoseconds;
        return if (timestamp < 0) 0 else @intCast(timestamp);
    }

    fn elapsedNs(self: Store, start: u128) u128 {
        const now = self.monotonicNs();
        return if (now >= start) now - start else 0;
    }

    fn collectNodeTextLookupRun(
        self: Store,
        allocator: std.mem.Allocator,
        run: NodeTextLookupRun,
        meta: IndexMeta,
        hash: u64,
        kind_filter: ?core.NodeKind,
        text: []const u8,
        max_collect: usize,
        out: *std.ArrayList(core.NodeId),
        node_view: *?NodeByIdIndexView,
        texts_view: *?NodeTextsView,
        timings: ?*NodeTextLookupTimings,
    ) !void {
        if (max_collect == 0 or out.items.len >= max_collect) return;
        if (!self.options.validate_indexes_on_read and !nodeTextLookupRunMayContainHash(run, hash)) {
            if (timings) |t| t.range_skip_count += 1;
            return;
        }
        if (timings) |t| t.run_count += 1;
        const texts_view_start = if (timings != null) self.monotonicNs() else 0;
        const texts_for_hash = if (run.header.hasDerivedHash()) try ensureNodeTextsView(self, texts_view) else null;
        if (timings) |t| t.search_texts_view_ns += self.elapsedNs(texts_view_start);
        const need_full_search_decode = self.options.validate_indexes_on_read or run.header.hasDerivedHash();
        const node_view_start = if (timings != null) self.monotonicNs() else 0;
        const nodes_for_search = if (need_full_search_decode and run.header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, meta, node_view) else null;
        if (timings) |t| t.search_node_view_ns += self.elapsedNs(node_view_start);
        const lower_bound_start = if (timings != null) self.monotonicNs() else 0;
        var pos = try self.findNodeTextHashLowerBound(run.file, run.map, run.header, hash, texts_for_hash, nodes_for_search, timings);
        if (timings) |t| {
            const lower_bound_ns = self.elapsedNs(lower_bound_start);
            t.recordLowerBoundRun(lower_bound_ns, run);
        }
        const scan_start = if (timings != null) self.monotonicNs() else 0;
        while (pos < run.header.node_count and out.items.len < max_collect) : (pos += 1) {
            if (timings) |t| t.scan_record_count += 1;
            const span_view_start = if (timings != null) self.monotonicNs() else 0;
            const nodes_for_span = if (run.header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, meta, node_view) else null;
            if (timings) |t| t.span_view_ns += self.elapsedNs(span_view_start);
            const record_decode_start = if (timings != null) self.monotonicNs() else 0;
            const record = if (run.map) |mapped|
                try readNodeTextIndexRecordFromMapForHeaderWithTextsAndNodes(run.header, mapped, pos, texts_for_hash, nodes_for_span)
            else
                try self.readNodeTextIndexRecordAtForHeaderWithTextsAndNodes(run.file, run.header, pos, texts_for_hash, nodes_for_span);
            if (timings) |t| t.record_decode_ns += self.elapsedNs(record_decode_start);
            if (record.hash != hash) break;
            const kind = try record.nodeKind();
            if (kind_filter) |filter| {
                if (kind != filter) continue;
            }
            if (record.text_len != text.len) continue;
            const text_view_start = if (timings != null) self.monotonicNs() else 0;
            if (!run.header.hasTextHashUnique() or self.options.validate_indexes_on_read) {
                const texts = try ensureNodeTextsView(self, texts_view);
                if (timings) |t| t.text_view_ns += self.elapsedNs(text_view_start);
                const text_match_start = if (timings != null) self.monotonicNs() else 0;
                const text_compare_start = if (timings != null) self.monotonicNs() else 0;
                const matches = try texts.matches(record.text_offset, record.text_len, text);
                if (timings) |t| t.text_compare_ns += self.elapsedNs(text_compare_start);
                if (timings) |t| t.text_match_ns += self.elapsedNs(text_match_start);
                if (!matches) continue;
            } else if (timings) |t| {
                t.text_view_ns += self.elapsedNs(text_view_start);
            }
            if (run.header.hasDerivedTextSpan()) {
                const expected_len = std.math.cast(u32, text.len) orelse return error.InvalidRecord;
                if (record.text_len != expected_len) return error.InvalidRecord;
            } else {
                const by_id_validate_start = if (timings != null) self.monotonicNs() else 0;
                const by_id = try (try ensureNodeByIdIndexView(self, meta, node_view)).readRecord(record.id);
                try validateNodeTextLookupRecord(record, by_id, kind, text.len);
                if (timings) |t| t.by_id_validate_ns += self.elapsedNs(by_id_validate_start);
            }
            try out.append(allocator, core.NodeId.fromInt(record.id));
        }
        if (timings) |t| t.scan_ns += self.elapsedNs(scan_start);
    }

    fn collectFirstNodeTextLookupRun(
        self: Store,
        run: NodeTextLookupRun,
        meta: IndexMeta,
        hash: u64,
        kind_filter: ?core.NodeKind,
        text: []const u8,
        best: *?core.NodeId,
        node_view: *?NodeByIdIndexView,
        texts_view: *?NodeTextsView,
        timings: ?*NodeTextLookupTimings,
    ) !void {
        if (best.*) |current| {
            if (run.min_node_id != 0 and current.toInt() <= run.min_node_id) return;
        }
        if (!self.options.validate_indexes_on_read and !nodeTextLookupRunMayContainHash(run, hash)) {
            if (timings) |t| t.range_skip_count += 1;
            return;
        }
        if (timings) |t| t.run_count += 1;
        const texts_view_start = if (timings != null) self.monotonicNs() else 0;
        const texts_for_hash = if (run.header.hasDerivedHash()) try ensureNodeTextsView(self, texts_view) else null;
        if (timings) |t| t.search_texts_view_ns += self.elapsedNs(texts_view_start);
        const need_full_search_decode = self.options.validate_indexes_on_read or run.header.hasDerivedHash();
        const node_view_start = if (timings != null) self.monotonicNs() else 0;
        const nodes_for_search = if (need_full_search_decode and run.header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, meta, node_view) else null;
        if (timings) |t| t.search_node_view_ns += self.elapsedNs(node_view_start);
        const lower_bound_start = if (timings != null) self.monotonicNs() else 0;
        var pos = try self.findNodeTextHashLowerBound(run.file, run.map, run.header, hash, texts_for_hash, nodes_for_search, timings);
        if (timings) |t| {
            const lower_bound_ns = self.elapsedNs(lower_bound_start);
            t.recordLowerBoundRun(lower_bound_ns, run);
        }
        const scan_start = if (timings != null) self.monotonicNs() else 0;
        while (pos < run.header.node_count) : (pos += 1) {
            if (timings) |t| t.scan_record_count += 1;
            const span_view_start = if (timings != null) self.monotonicNs() else 0;
            const nodes_for_span = if (run.header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, meta, node_view) else null;
            if (timings) |t| t.span_view_ns += self.elapsedNs(span_view_start);
            const record_decode_start = if (timings != null) self.monotonicNs() else 0;
            const record = if (run.map) |mapped|
                try readNodeTextIndexRecordFromMapForHeaderWithTextsAndNodes(run.header, mapped, pos, texts_for_hash, nodes_for_span)
            else
                try self.readNodeTextIndexRecordAtForHeaderWithTextsAndNodes(run.file, run.header, pos, texts_for_hash, nodes_for_span);
            if (timings) |t| t.record_decode_ns += self.elapsedNs(record_decode_start);
            if (record.hash != hash) break;
            if (best.*) |current| {
                if (record.id >= current.toInt()) break;
            }
            const kind = try record.nodeKind();
            if (kind_filter) |filter| {
                if (kind != filter) continue;
            }
            if (record.text_len != text.len) continue;
            const text_view_start = if (timings != null) self.monotonicNs() else 0;
            if (!run.header.hasTextHashUnique() or self.options.validate_indexes_on_read) {
                const texts = try ensureNodeTextsView(self, texts_view);
                if (timings) |t| t.text_view_ns += self.elapsedNs(text_view_start);
                const text_match_start = if (timings != null) self.monotonicNs() else 0;
                const text_compare_start = if (timings != null) self.monotonicNs() else 0;
                const matches = try texts.matches(record.text_offset, record.text_len, text);
                if (timings) |t| t.text_compare_ns += self.elapsedNs(text_compare_start);
                if (timings) |t| t.text_match_ns += self.elapsedNs(text_match_start);
                if (!matches) continue;
            } else if (timings) |t| {
                t.text_view_ns += self.elapsedNs(text_view_start);
            }
            if (run.header.hasDerivedTextSpan()) {
                const expected_len = std.math.cast(u32, text.len) orelse return error.InvalidRecord;
                if (record.text_len != expected_len) return error.InvalidRecord;
            } else {
                const by_id_validate_start = if (timings != null) self.monotonicNs() else 0;
                const by_id = try (try ensureNodeByIdIndexView(self, meta, node_view)).readRecord(record.id);
                try validateNodeTextLookupRecord(record, by_id, kind, text.len);
                if (timings) |t| t.by_id_validate_ns += self.elapsedNs(by_id_validate_start);
            }
            best.* = core.NodeId.fromInt(record.id);
        }
        if (timings) |t| t.scan_ns += self.elapsedNs(scan_start);
    }

    fn findNodeTextHashLowerBound(
        self: Store,
        file: std.Io.File,
        map: ?*const std.Io.File.MemoryMap,
        header: NodeTextIndexHeader,
        hash: u64,
        texts_view: ?*const NodeTextsView,
        node_view: ?*const NodeByIdIndexView,
        timings: ?*NodeTextLookupTimings,
    ) !u64 {
        var lo: u64 = 0;
        var hi: u64 = header.node_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (timings) |t| t.lower_bound_probe_count += 1;
            const record_hash = if (map) |mapped|
                try self.readNodeTextIndexRecordHashFromMapForHeader(header, mapped, mid, texts_view, node_view)
            else
                try self.readNodeTextIndexRecordHashAtForHeader(file, header, mid, texts_view, node_view);
            if (record_hash < hash) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn boundedSentinelCap(max_nodes: usize) !usize {
        return std.math.add(usize, max_nodes, 1) catch return core.Error.BudgetExceeded;
    }

    pub fn scanNodeIds(self: Store, allocator: std.mem.Allocator, kind_filter: ?core.NodeKind, max_ids: usize) !std.ArrayList(core.NodeId) {
        var out = std.ArrayList(core.NodeId).empty;
        errdefer out.deinit(allocator);
        if (max_ids == 0) return out;

        var iter = try self.nodeIdsIterator(kind_filter);
        defer iter.deinit();
        while (out.items.len < max_ids) {
            const node_id = (try iter.next()) orelse break;
            try out.append(allocator, node_id);
        }
        return out;
    }

    pub const NodeIdIterator = struct {
        store: Store,
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        kind_filter: ?core.NodeKind,
        header: NodeByIdHeader,
        next_id: u64,
        max_node_id: u64,
        expected_nodes: u64,
        seen_nodes: u64 = 0,

        pub fn deinit(self: *NodeIdIterator) void {
            if (self.map) |*map| map.destroy(self.store.io);
            self.file.close(self.store.io);
        }

        pub fn next(self: *NodeIdIterator) !?core.NodeId {
            while (self.next_id <= self.max_node_id) : (self.next_id += 1) {
                const id = self.next_id;
                const record = if (self.map) |*map|
                    try readNodeByIdRecordFromMap(self.header, map, id)
                else
                    try self.store.readNodeByIdRecordAt(self.file, self.header, id);
                if (record.id == 0) continue;
                if (record.id != id) return error.InvalidRecord;
                if (self.seen_nodes >= self.expected_nodes) return error.InvalidRecord;
                self.seen_nodes += 1;
                if (self.kind_filter) |filter| {
                    if ((try record.nodeKind()) != filter) continue;
                }
                self.next_id += 1;
                return core.NodeId.fromInt(record.id);
            }
            if (self.seen_nodes != self.expected_nodes) return error.InvalidRecord;
            return null;
        }
    };

    pub const NodeByIdIndexView = struct {
        store: Store,
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        header: NodeByIdHeader,
        max_node_id: u64,
        node_count: u64,

        fn open(store: Store, meta: IndexMeta) !NodeByIdIndexView {
            var file = try std.Io.Dir.cwd().openFile(store.io, store.node_by_id_path, .{});
            errdefer file.close(store.io);
            const header = try store.readNodeByIdHeaderFromFile(file);
            if (header.node_count != meta.nodes) return error.InvalidRecord;
            if (header.node_digest != meta.node_digest) return error.InvalidRecord;
            if (header.node_count > header.max_node_id) return error.InvalidRecord;
            const expected_size = try store.nodeByIdFileSizeForHeaderStore(header);
            if (try store.regularFileSize(file) != expected_size) return error.InvalidRecord;
            var map = openReadOnlyMemoryMap(store.io, file, expected_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(store.io);
            return .{
                .store = store,
                .file = file,
                .map = map,
                .header = header,
                .max_node_id = header.max_node_id,
                .node_count = header.node_count,
            };
        }

        pub fn deinit(self: *NodeByIdIndexView) void {
            if (self.map) |*map| map.destroy(self.store.io);
            self.file.close(self.store.io);
        }

        pub fn nodeExists(self: *const NodeByIdIndexView, node_id: core.NodeId) !bool {
            if (isReservedNodeId(node_id)) return core.Error.InvalidId;
            return (try self.readOptionalRecord(node_id.toInt())) != null;
        }

        pub fn nodeKind(self: *const NodeByIdIndexView, node_id: core.NodeId) !?core.NodeKind {
            if (isReservedNodeId(node_id)) return core.Error.InvalidId;
            const record = (try self.readOptionalRecord(node_id.toInt())) orelse return null;
            return try record.nodeKind();
        }

        fn readRecord(self: *const NodeByIdIndexView, node_id: u64) !NodeByIdRecord {
            if (node_id == 0 or node_id > self.max_node_id) return error.InvalidRecord;
            if (self.map) |*map| return readNodeByIdRecordFromMap(self.header, map, node_id);
            return self.store.readNodeByIdRecordAt(self.file, self.header, node_id);
        }

        fn readOptionalRecord(self: *const NodeByIdIndexView, node_id: u64) !?NodeByIdRecord {
            if (node_id == 0) return error.InvalidRecord;
            if (node_id > self.max_node_id) return null;
            const record = try self.readRecord(node_id);
            if (record.id == 0) {
                if (self.node_count == self.max_node_id) return error.InvalidRecord;
                return null;
            }
            if (record.id != node_id) return error.InvalidRecord;
            return record;
        }
    };

    const EdgeBatchNodeExistenceCache = struct {
        const Entry = struct {
            id: u64 = 0,
            exists: bool = false,
        };

        entries: [edge_batch_node_cache_slots]Entry = [_]Entry{.{}} ** edge_batch_node_cache_slots,

        fn nodeExists(self: *EdgeBatchNodeExistenceCache, view: *const NodeByIdIndexView, node_id: u64) !bool {
            const slot = node_id & (edge_batch_node_cache_slots - 1);
            const entry = &self.entries[@intCast(slot)];
            if (entry.id == node_id) return entry.exists;
            const exists = try view.nodeExists(core.NodeId.fromInt(node_id));
            entry.* = .{ .id = node_id, .exists = exists };
            return exists;
        }
    };

    fn ensureNodeByIdIndexView(self: Store, meta: IndexMeta, view: *?NodeByIdIndexView) !*NodeByIdIndexView {
        if (view.* == null) view.* = try NodeByIdIndexView.open(self, meta);
        return &view.*.?;
    }

    const NodeTextsStorageFormat = enum {
        raw,
        block_deflate,
    };

    const node_texts_block_deflate_magic = [_]u8{ 'T', 'K', 'N', 'Z' };
    pub const node_texts_block_deflate_version: u16 = 5;
    const node_texts_block_deflate_header_len: usize = 16;
    const node_texts_block_deflate_entry_len: usize = 4;
    pub const node_texts_block_deflate_block_bytes: u32 = 256 * 1024;
    pub const node_texts_raw_mmap_max_bytes: u64 = 64 * 1024 * 1024;
    const node_texts_block_deflate_flag_compressed: u16 = 1 << 0;
    const node_texts_append_journal_magic = [_]u8{ 'T', 'K', 'N', 'A' };
    const node_texts_append_journal_version: u16 = 3;
    const node_texts_append_journal_checksummed_version: u16 = 2;
    const node_texts_append_journal_legacy_version: u16 = 1;
    const node_texts_append_journal_header_len: usize = 64;
    const node_texts_append_journal_hash_seed: u64 = 0x544B_4E41;
    const node_texts_append_journal_header_hash_seed: u64 = 0x544B_4E48;
    const node_texts_deflate_progress_entry_len: usize = 20;
    const node_texts_deflate_progress_hash_seed: u64 = 0x544B_4E50;
    // Keep synchronous ingestion at level 3. Level 6 saves only a few percent
    // of node_texts bytes on GB10 but makes the append path several times
    // slower; deeper compression belongs in an offline maintenance pass.
    pub const node_texts_block_deflate_level_number: u8 = 3;
    pub const node_texts_block_deflate_level = std.compress.flate.Compress.Options.level_3;

    const NodeTextsAppendJournalHeader = struct {
        original_size: u64,
        suffix_offset: u64,
        suffix_len: u64,
        suffix_hash: u64,
        original_header: [node_texts_block_deflate_header_len]u8,
        original_format: NodeTextsStorageFormat = .block_deflate,
        committed: bool = false,

        fn decode(bytes: *const [node_texts_append_journal_header_len]u8) !NodeTextsAppendJournalHeader {
            if (!std.mem.eql(u8, bytes[0..4], &node_texts_append_journal_magic)) return error.InvalidRecord;
            const version = readU16(bytes[4..6]);
            if (version != node_texts_append_journal_version and
                version != node_texts_append_journal_checksummed_version and
                version != node_texts_append_journal_legacy_version) return error.InvalidRecord;
            if (readU16(bytes[6..8]) != node_texts_append_journal_header_len) return error.InvalidRecord;
            if (bytes[56] > 1) return error.InvalidRecord;
            if (version == node_texts_append_journal_legacy_version) {
                if (!allZero(bytes[57..64])) return error.InvalidRecord;
            } else {
                var digest_bytes: [8]u8 = undefined;
                writeU64(&digest_bytes, std.hash.Wyhash.hash(node_texts_append_journal_header_hash_seed, bytes[0..57]));
                if (!std.mem.eql(u8, bytes[57..64], digest_bytes[0..7])) return error.InvalidRecord;
            }
            var original_header: [node_texts_block_deflate_header_len]u8 = undefined;
            @memcpy(&original_header, bytes[40..56]);
            const original_format: NodeTextsStorageFormat = if (version == node_texts_append_journal_version and allZero(&original_header))
                .raw
            else
                .block_deflate;
            return .{
                .original_size = readU64(bytes[8..16]),
                .suffix_offset = readU64(bytes[16..24]),
                .suffix_len = readU64(bytes[24..32]),
                .suffix_hash = readU64(bytes[32..40]),
                .original_header = original_header,
                .original_format = original_format,
                .committed = bytes[56] == 1,
            };
        }

        fn encode(self: NodeTextsAppendJournalHeader, out: *[node_texts_append_journal_header_len]u8) !void {
            if (self.suffix_offset > self.original_size or self.suffix_len != self.original_size - self.suffix_offset) return error.InvalidRecord;
            switch (self.original_format) {
                .raw => {
                    if (self.suffix_offset != self.original_size or self.suffix_len != 0) return error.InvalidRecord;
                    if (self.suffix_hash != std.hash.Wyhash.hash(node_texts_append_journal_hash_seed, &.{})) return error.InvalidRecord;
                    if (!allZero(&self.original_header)) return error.InvalidRecord;
                },
                .block_deflate => {
                    if (self.original_size < node_texts_block_deflate_header_len) return error.InvalidRecord;
                    _ = try NodeTextsBlockDeflateHeader.decode(&self.original_header);
                },
            }
            @memcpy(out[0..4], &node_texts_append_journal_magic);
            writeU16(out[4..6], node_texts_append_journal_version);
            writeU16(out[6..8], node_texts_append_journal_header_len);
            writeU64(out[8..16], self.original_size);
            writeU64(out[16..24], self.suffix_offset);
            writeU64(out[24..32], self.suffix_len);
            writeU64(out[32..40], self.suffix_hash);
            @memcpy(out[40..56], &self.original_header);
            out[56] = @intFromBool(self.committed);
            var digest_bytes: [8]u8 = undefined;
            writeU64(&digest_bytes, std.hash.Wyhash.hash(node_texts_append_journal_header_hash_seed, out[0..57]));
            @memcpy(out[57..64], digest_bytes[0..7]);
        }
    };

    const NodeTextsBlockDeflateHeader = struct {
        logical_size: u64,

        fn decode(bytes: *const [node_texts_block_deflate_header_len]u8) !NodeTextsBlockDeflateHeader {
            if (!std.mem.eql(u8, bytes[0..4], &node_texts_block_deflate_magic)) return error.InvalidRecord;
            if (readU16(bytes[4..6]) != node_texts_block_deflate_version) return error.InvalidRecord;
            if (readU16(bytes[6..8]) != node_texts_block_deflate_header_len) return error.InvalidRecord;
            const header = NodeTextsBlockDeflateHeader{
                .logical_size = readU64(bytes[8..16]),
            };
            try header.validate();
            return header;
        }

        fn encode(self: NodeTextsBlockDeflateHeader, out: *[node_texts_block_deflate_header_len]u8) !void {
            try self.validate();
            @memcpy(out[0..4], &node_texts_block_deflate_magic);
            writeU16(out[4..6], node_texts_block_deflate_version);
            writeU16(out[6..8], node_texts_block_deflate_header_len);
            writeU64(out[8..16], self.logical_size);
        }

        fn validate(self: NodeTextsBlockDeflateHeader) !void {
            if (self.logical_size == 0) return error.InvalidRecord;
            _ = try self.blockCount();
        }

        fn blockCount(self: NodeTextsBlockDeflateHeader) !u32 {
            const rounded_size = std.math.add(u64, self.logical_size, node_texts_block_deflate_block_bytes - 1) catch return error.InvalidRecord;
            const count = rounded_size / node_texts_block_deflate_block_bytes;
            if (count == 0) return error.InvalidRecord;
            return std.math.cast(u32, count) orelse return error.InvalidRecord;
        }

        fn tableBytes(self: NodeTextsBlockDeflateHeader) !u64 {
            return std.math.mul(u64, try self.blockCount(), node_texts_block_deflate_entry_len) catch return error.InvalidRecord;
        }

        fn tableOffset(self: NodeTextsBlockDeflateHeader, physical_size: u64) !u64 {
            const table_bytes = try self.tableBytes();
            if (physical_size < node_texts_block_deflate_header_len or table_bytes > physical_size - node_texts_block_deflate_header_len) return error.InvalidRecord;
            const table_offset = physical_size - table_bytes;
            if (table_offset < node_texts_block_deflate_header_len) return error.InvalidRecord;
            return table_offset;
        }

        fn payloadOffset(_: NodeTextsBlockDeflateHeader) u64 {
            return node_texts_block_deflate_header_len;
        }

        fn rawLenForBlock(self: NodeTextsBlockDeflateHeader, block_index: usize) !u32 {
            const block_count = try self.blockCount();
            if (block_index >= block_count) return error.InvalidRecord;
            const logical_offset = std.math.mul(u64, @intCast(block_index), node_texts_block_deflate_block_bytes) catch return error.InvalidRecord;
            const remaining = self.logical_size - logical_offset;
            return @intCast(@min(remaining, node_texts_block_deflate_block_bytes));
        }
    };

    const NodeTextsBlockDeflateEntry = struct {
        physical_offset: u64,
        stored_len: u32,
        raw_len: u32,
        flags: u16,

        fn decode(bytes: *const [node_texts_block_deflate_entry_len]u8, physical_offset: u64, raw_len: u32) !NodeTextsBlockDeflateEntry {
            const stored_len = readU32(bytes[0..4]);
            const entry = NodeTextsBlockDeflateEntry{
                .physical_offset = physical_offset,
                .stored_len = stored_len,
                .raw_len = raw_len,
                .flags = if (stored_len < raw_len) node_texts_block_deflate_flag_compressed else 0,
            };
            try entry.validate();
            return entry;
        }

        fn encode(self: NodeTextsBlockDeflateEntry, out: *[node_texts_block_deflate_entry_len]u8) !void {
            try self.validate();
            writeU32(out[0..4], self.stored_len);
        }

        fn validate(self: NodeTextsBlockDeflateEntry) !void {
            if (self.physical_offset == 0 or self.stored_len == 0 or self.raw_len == 0) return error.InvalidRecord;
            if (self.raw_len > node_texts_block_deflate_block_bytes) return error.InvalidRecord;
            if ((self.flags & ~node_texts_block_deflate_flag_compressed) != 0) return error.InvalidRecord;
            if ((self.flags & node_texts_block_deflate_flag_compressed) == 0 and self.stored_len != self.raw_len) return error.InvalidRecord;
        }
    };

    const NodeTextsBlockCache = struct {
        block_index: ?usize = null,
        bytes: []u8 = &.{},

        fn deinit(self: *NodeTextsBlockCache, allocator: std.mem.Allocator) void {
            allocator.free(self.bytes);
            self.* = .{};
        }
    };

    const NodeTextsView = struct {
        store: Store,
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        size: u64,
        format: NodeTextsStorageFormat = .raw,
        blocks: []NodeTextsBlockDeflateEntry = &.{},
        block_cache: ?*NodeTextsBlockCache = null,

        fn open(store: Store) !NodeTextsView {
            _ = try store.recoverNodeTextsAppendJournal();
            var file = try std.Io.Dir.cwd().openFile(store.io, store.node_texts_path, .{});
            errdefer file.close(store.io);
            const physical_size = try store.regularFileSize(file);
            if (physical_size >= node_texts_block_deflate_header_len) {
                var header_bytes: [node_texts_block_deflate_header_len]u8 = undefined;
                const n = try file.readPositionalAll(store.io, &header_bytes, 0);
                if (n != header_bytes.len) return error.InvalidRecord;
                const header_slice = header_bytes[0..];
                if (std.mem.eql(u8, header_slice[0..4], &node_texts_block_deflate_magic) and
                    readU16(header_slice[4..6]) == node_texts_block_deflate_version and
                    readU16(header_slice[6..8]) == node_texts_block_deflate_header_len)
                {
                    const header = try NodeTextsBlockDeflateHeader.decode(header_slice[0..node_texts_block_deflate_header_len]);
                    const block_count = try header.blockCount();
                    const payload_offset = header.payloadOffset();
                    const table_offset = try header.tableOffset(physical_size);
                    if (payload_offset > table_offset) return error.InvalidRecord;
                    const blocks = try store.allocator.alloc(NodeTextsBlockDeflateEntry, block_count);
                    errdefer store.allocator.free(blocks);
                    const table_bytes_len = std.math.cast(usize, try header.tableBytes()) orelse return error.RecordTooLarge;
                    const table_bytes = try store.allocator.alloc(u8, table_bytes_len);
                    defer store.allocator.free(table_bytes);
                    const table_n = try file.readPositionalAll(store.io, table_bytes, table_offset);
                    if (table_n != table_bytes.len) return error.InvalidRecord;
                    const block_cache = try store.allocator.create(NodeTextsBlockCache);
                    errdefer store.allocator.destroy(block_cache);
                    block_cache.* = .{};
                    var payload_cursor = payload_offset;
                    var logical_cursor: u64 = 0;
                    var i: usize = 0;
                    while (i < blocks.len) : (i += 1) {
                        const entry_offset = i * node_texts_block_deflate_entry_len;
                        const entry_slice = table_bytes[entry_offset..][0..node_texts_block_deflate_entry_len];
                        const entry = try NodeTextsBlockDeflateEntry.decode(entry_slice[0..node_texts_block_deflate_entry_len], payload_cursor, try header.rawLenForBlock(i));
                        if (entry.physical_offset != payload_cursor) return error.InvalidRecord;
                        if (entry.physical_offset > table_offset or entry.stored_len > table_offset - entry.physical_offset) return error.InvalidRecord;
                        blocks[i] = entry;
                        payload_cursor = std.math.add(u64, payload_cursor, entry.stored_len) catch return error.InvalidRecord;
                        logical_cursor = std.math.add(u64, logical_cursor, entry.raw_len) catch return error.InvalidRecord;
                    }
                    if (payload_cursor != table_offset) return error.InvalidRecord;
                    if (logical_cursor != header.logical_size) return error.InvalidRecord;
                    return .{
                        .store = store,
                        .file = file,
                        .size = header.logical_size,
                        .format = .block_deflate,
                        .blocks = blocks,
                        .block_cache = block_cache,
                    };
                }
            }
            var map = if (physical_size == 0 or physical_size > node_texts_raw_mmap_max_bytes)
                null
            else
                openReadOnlyMemoryMap(store.io, file, physical_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(store.io);
            return .{
                .store = store,
                .file = file,
                .map = map,
                .size = physical_size,
            };
        }

        fn deinit(self: *NodeTextsView) void {
            if (self.block_cache) |cache| {
                cache.deinit(self.store.allocator);
                self.store.allocator.destroy(cache);
            }
            self.store.allocator.free(self.blocks);
            if (self.map) |*map| map.destroy(self.store.io);
            self.file.close(self.store.io);
        }

        fn mappedBytes(self: *const NodeTextsView, offset: u64, len: u32) !?[]const u8 {
            if (offset > self.size or len > self.size - offset) return error.InvalidRecord;
            if (self.format != .raw) return null;
            if (self.map) |*map| {
                const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
                const end = std.math.add(usize, start, len) catch return error.InvalidRecord;
                if (end > map.memory.len) return error.InvalidRecord;
                return map.memory[start..end];
            }
            return null;
        }

        fn borrowedBytes(self: *const NodeTextsView, offset: u64, len: u32) !?[]const u8 {
            if (try self.mappedBytes(offset, len)) |bytes| return bytes;
            if (offset > self.size or len > self.size - offset) return error.InvalidRecord;
            if (len == 0) return &.{};
            if (self.format != .block_deflate) return null;

            const block_index_u64 = offset / node_texts_block_deflate_block_bytes;
            const block_index = std.math.cast(usize, block_index_u64) orelse return error.RecordTooLarge;
            if (block_index >= self.blocks.len) return error.InvalidRecord;
            const entry = self.blocks[block_index];
            const in_block_offset: usize = @intCast(offset % node_texts_block_deflate_block_bytes);
            if (in_block_offset > entry.raw_len) return error.InvalidRecord;
            if (len > @as(usize, entry.raw_len) - in_block_offset) return null;

            const block = try self.readCompressedBlock(block_index, entry);
            return block[in_block_offset..][0..len];
        }

        fn shouldCacheValidationHashes(self: *const NodeTextsView) bool {
            return self.format != .raw or self.map == null;
        }

        fn matches(self: *const NodeTextsView, offset: u64, len: u32, text: []const u8) !bool {
            if (len != text.len) return false;
            if (try self.mappedBytes(offset, len)) |bytes| return std.mem.eql(u8, bytes, text);
            return self.matchesPositional(offset, len, text);
        }

        fn matchesPositional(self: *const NodeTextsView, offset: u64, len: u32, text: []const u8) !bool {
            if (offset > self.size or len > self.size - offset) return error.InvalidRecord;
            var buf: [4096]u8 = undefined;
            var remaining: usize = len;
            var read_offset = offset;
            var text_pos: usize = 0;
            while (remaining > 0) {
                const chunk_len = @min(remaining, buf.len);
                try self.readInto(read_offset, buf[0..chunk_len]);
                if (!std.mem.eql(u8, buf[0..chunk_len], text[text_pos .. text_pos + chunk_len])) return false;
                remaining -= chunk_len;
                read_offset += chunk_len;
                text_pos += chunk_len;
            }
            return true;
        }

        fn hashMatches(self: *const NodeTextsView, record: NodeTextIndexRecord) !bool {
            return (try self.hashStoredText(record.text_offset, record.text_len)) == record.hash;
        }

        fn hashStoredText(self: *const NodeTextsView, text_offset: u64, text_len: u32) !u64 {
            var hasher = std.hash.Wyhash.init(0);
            if (try self.mappedBytes(text_offset, text_len)) |bytes| {
                hasher.update(bytes);
            } else {
                var buf: [4096]u8 = undefined;
                var remaining: usize = text_len;
                var offset = text_offset;
                while (remaining > 0) {
                    const chunk_len = @min(remaining, buf.len);
                    try self.readInto(offset, buf[0..chunk_len]);
                    hasher.update(buf[0..chunk_len]);
                    remaining -= chunk_len;
                    offset += chunk_len;
                }
            }
            return hasher.final();
        }

        fn digestStoredNode(self: *const NodeTextsView, id: u64, kind: core.NodeKind, offset: u64, len: u32) !u64 {
            var fixed: [node_record_digest_fixed_len]u8 = undefined;
            std.mem.writeInt(u64, fixed[0..8], id, .little);
            std.mem.writeInt(u16, fixed[8..10], @intFromEnum(kind), .little);
            std.mem.writeInt(u32, fixed[10..14], len, .little);
            var hasher = std.hash.Wyhash.init(0);
            hasher.update(&fixed);

            if (try self.mappedBytes(offset, len)) |bytes| {
                hasher.update(bytes);
            } else {
                var remaining: usize = len;
                var read_offset = offset;
                var buf: [4096]u8 = undefined;
                while (remaining != 0) {
                    const chunk_len = @min(remaining, buf.len);
                    try self.readInto(read_offset, buf[0..chunk_len]);
                    hasher.update(buf[0..chunk_len]);
                    remaining -= chunk_len;
                    read_offset += chunk_len;
                }
            }
            return hasher.final();
        }

        const StoredNodeTextHashDigest = struct {
            text_hash: u64,
            node_digest: u64,
        };

        fn hashAndDigestStoredNode(self: *const NodeTextsView, id: u64, kind: core.NodeKind, offset: u64, len: u32) !StoredNodeTextHashDigest {
            var fixed: [node_record_digest_fixed_len]u8 = undefined;
            std.mem.writeInt(u64, fixed[0..8], id, .little);
            std.mem.writeInt(u16, fixed[8..10], @intFromEnum(kind), .little);
            std.mem.writeInt(u32, fixed[10..14], len, .little);

            var text_hasher = std.hash.Wyhash.init(0);
            var node_hasher = std.hash.Wyhash.init(0);
            node_hasher.update(&fixed);
            if (try self.mappedBytes(offset, len)) |bytes| {
                text_hasher.update(bytes);
                node_hasher.update(bytes);
            } else {
                var remaining: usize = len;
                var read_offset = offset;
                var buf: [4096]u8 = undefined;
                while (remaining != 0) {
                    const chunk_len = @min(remaining, buf.len);
                    try self.readInto(read_offset, buf[0..chunk_len]);
                    text_hasher.update(buf[0..chunk_len]);
                    node_hasher.update(buf[0..chunk_len]);
                    remaining -= chunk_len;
                    read_offset += chunk_len;
                }
            }
            return .{
                .text_hash = text_hasher.final(),
                .node_digest = node_hasher.final(),
            };
        }

        fn validationHash(self: *const NodeTextsView, id: u64, kind: core.NodeKind, offset: u64, len: u32) !NodeTextValidationHash {
            const computed = try self.hashAndDigestStoredNode(id, kind, offset, len);
            return .{
                .text_hash = computed.text_hash,
                .node_digest = computed.node_digest,
            };
        }

        fn readStoredNode(self: *const NodeTextsView, allocator: std.mem.Allocator, record: NodeByIdRecord) !StoredNode {
            const kind = try record.nodeKind();
            const text = try self.readTextAlloc(allocator, record.text_offset, record.text_len);
            errdefer allocator.free(text);
            return .{
                .id = core.NodeId.fromInt(record.id),
                .kind = kind,
                .text = text,
            };
        }

        fn readTextAlloc(self: *const NodeTextsView, allocator: std.mem.Allocator, offset: u64, len: u32) ![]u8 {
            const text = try allocator.alloc(u8, len);
            errdefer allocator.free(text);
            if (try self.mappedBytes(offset, len)) |bytes| {
                @memcpy(text, bytes);
            } else {
                try self.readInto(offset, text);
            }
            return text;
        }

        fn readInto(self: *const NodeTextsView, offset: u64, out: []u8) !void {
            if (offset > self.size or out.len > self.size - offset) return error.InvalidRecord;
            if (out.len == 0) return;
            if (try self.mappedBytes(offset, @intCast(out.len))) |bytes| {
                @memcpy(out, bytes);
                return;
            }
            switch (self.format) {
                .raw => {
                    const n = try self.file.readPositionalAll(self.store.io, out, offset);
                    if (n != out.len) return error.InvalidRecord;
                },
                .block_deflate => try self.readCompressedInto(offset, out),
            }
        }

        fn readCompressedInto(self: *const NodeTextsView, offset: u64, out: []u8) !void {
            var remaining = out.len;
            var logical_offset = offset;
            var out_pos: usize = 0;
            while (remaining > 0) {
                const block_index_u64 = logical_offset / node_texts_block_deflate_block_bytes;
                const block_index = std.math.cast(usize, block_index_u64) orelse return error.RecordTooLarge;
                if (block_index >= self.blocks.len) return error.InvalidRecord;
                const entry = self.blocks[block_index];
                const in_block_offset: usize = @intCast(logical_offset % node_texts_block_deflate_block_bytes);
                if (in_block_offset >= entry.raw_len) return error.InvalidRecord;
                const take = @min(remaining, @as(usize, entry.raw_len) - in_block_offset);
                const block = try self.readCompressedBlock(block_index, entry);
                @memcpy(out[out_pos..][0..take], block[in_block_offset..][0..take]);
                remaining -= take;
                logical_offset += take;
                out_pos += take;
            }
        }

        fn readCompressedBlock(self: *const NodeTextsView, block_index: usize, entry: NodeTextsBlockDeflateEntry) ![]const u8 {
            const cache = self.block_cache orelse return error.InvalidRecord;
            if (cache.block_index == block_index) return cache.bytes;

            const raw_len = std.math.cast(usize, entry.raw_len) orelse return error.RecordTooLarge;
            const stored_len = std.math.cast(usize, entry.stored_len) orelse return error.RecordTooLarge;
            var compressed_owned: ?[]u8 = null;
            defer if (compressed_owned) |buffer| self.store.allocator.free(buffer);
            const compressed: []const u8 = blk: {
                if (self.map) |*map| {
                    const start = std.math.cast(usize, entry.physical_offset) orelse return error.RecordTooLarge;
                    const end = std.math.add(usize, start, stored_len) catch return error.InvalidRecord;
                    if (end > map.memory.len) return error.InvalidRecord;
                    break :blk map.memory[start..end];
                }
                const buffer = try self.store.allocator.alloc(u8, stored_len);
                errdefer self.store.allocator.free(buffer);
                const n = try self.file.readPositionalAll(self.store.io, buffer, entry.physical_offset);
                if (n != buffer.len) return error.InvalidRecord;
                compressed_owned = buffer;
                break :blk buffer;
            };

            const out = try self.store.allocator.alloc(u8, raw_len);
            errdefer self.store.allocator.free(out);
            if ((entry.flags & node_texts_block_deflate_flag_compressed) == 0) {
                if (stored_len != raw_len) return error.InvalidRecord;
                @memcpy(out, compressed);
            } else {
                var input_reader: std.Io.Reader = .fixed(compressed);
                const flate_buffer = try self.store.allocator.alloc(u8, std.compress.flate.max_window_len);
                defer self.store.allocator.free(flate_buffer);
                var decompressor = std.compress.flate.Decompress.init(&input_reader, .raw, flate_buffer);
                try decompressor.reader.readSliceAll(out);
            }
            self.store.allocator.free(cache.bytes);
            cache.bytes = out;
            cache.block_index = block_index;
            return cache.bytes;
        }
    };

    fn ensureNodeTextsView(self: Store, view: *?NodeTextsView) !*NodeTextsView {
        if (view.* == null) view.* = try NodeTextsView.open(self);
        return &view.*.?;
    }

    pub const NodeRecordView = struct {
        by_id: NodeByIdIndexView,
        texts: NodeTextsView,

        pub const NodeRef = struct {
            id: core.NodeId,
            kind: core.NodeKind,
            text_offset: u64,
            text_len: u32,
            text_bytes: ?[]const u8 = null,
        };

        fn open(store: Store, meta: IndexMeta) !NodeRecordView {
            var by_id = try NodeByIdIndexView.open(store, meta);
            errdefer by_id.deinit();
            var texts = try NodeTextsView.open(store);
            errdefer texts.deinit();
            return .{
                .by_id = by_id,
                .texts = texts,
            };
        }

        pub fn deinit(self: *NodeRecordView) void {
            self.texts.deinit();
            self.by_id.deinit();
        }

        pub fn readNodeById(self: *const NodeRecordView, allocator: std.mem.Allocator, node_id: core.NodeId) !?StoredNode {
            if (isReservedNodeId(node_id)) return core.Error.InvalidId;
            const record = (try self.by_id.readOptionalRecord(node_id.toInt())) orelse return null;
            return try self.texts.readStoredNode(allocator, record);
        }

        pub fn readNodeRefById(self: *const NodeRecordView, node_id: core.NodeId) !?NodeRef {
            if (isReservedNodeId(node_id)) return core.Error.InvalidId;
            const record = (try self.by_id.readOptionalRecord(node_id.toInt())) orelse return null;
            return try self.nodeRefFromRecord(record);
        }

        fn nodeRefFromRecord(self: *const NodeRecordView, record: NodeByIdRecord) !NodeRef {
            return .{
                .id = core.NodeId.fromInt(record.id),
                .kind = try record.nodeKind(),
                .text_offset = record.text_offset,
                .text_len = record.text_len,
                .text_bytes = try self.texts.mappedBytes(record.text_offset, record.text_len),
            };
        }

        pub fn readNodeRefTextAlloc(self: *const NodeRecordView, allocator: std.mem.Allocator, node_ref: NodeRef) ![]u8 {
            if (node_ref.text_bytes) |bytes| return allocator.dupe(u8, bytes);
            return self.texts.readTextAlloc(allocator, node_ref.text_offset, node_ref.text_len);
        }

        pub fn readNodeRefTextBorrowed(self: *const NodeRecordView, node_ref: NodeRef) !?[]const u8 {
            if (node_ref.text_bytes) |bytes| return bytes;
            return self.texts.borrowedBytes(node_ref.text_offset, node_ref.text_len);
        }

        pub fn matchNode(self: *const NodeRecordView, node_id: core.NodeId, kind_filter: ?core.NodeKind, text_eq: ?[]const u8) !?bool {
            if (isReservedNodeId(node_id)) return core.Error.InvalidId;
            const record = (try self.by_id.readOptionalRecord(node_id.toInt())) orelse return null;
            if (kind_filter) |filter| {
                if ((try record.nodeKind()) != filter) return false;
            }
            if (text_eq) |text| {
                if (!try self.texts.matches(record.text_offset, record.text_len, text)) return false;
            }
            return true;
        }
    };

    pub const NodeRecordIterator = struct {
        view: NodeRecordView,
        kind_filter: ?core.NodeKind,
        next_id: u64 = 1,
        seen_nodes: u64 = 0,

        pub fn deinit(self: *NodeRecordIterator) void {
            self.view.deinit();
        }

        pub fn next(self: *NodeRecordIterator, allocator: std.mem.Allocator) !?StoredNode {
            while (self.next_id <= self.view.by_id.max_node_id) : (self.next_id += 1) {
                const id = self.next_id;
                const record = try self.view.by_id.readRecord(id);
                if (record.id == 0) continue;
                if (record.id != id) return error.InvalidRecord;
                if (self.seen_nodes >= self.view.by_id.node_count) return error.InvalidRecord;
                self.seen_nodes += 1;
                if (self.kind_filter) |filter| {
                    if ((try record.nodeKind()) != filter) continue;
                }
                self.next_id += 1;
                return try self.view.texts.readStoredNode(allocator, record);
            }
            if (self.seen_nodes != self.view.by_id.node_count) return error.InvalidRecord;
            return null;
        }

        pub fn nextRef(self: *NodeRecordIterator) !?NodeRecordView.NodeRef {
            while (self.next_id <= self.view.by_id.max_node_id) : (self.next_id += 1) {
                const id = self.next_id;
                const record = try self.view.by_id.readRecord(id);
                if (record.id == 0) continue;
                if (record.id != id) return error.InvalidRecord;
                if (self.seen_nodes >= self.view.by_id.node_count) return error.InvalidRecord;
                self.seen_nodes += 1;
                if (self.kind_filter) |filter| {
                    if ((try record.nodeKind()) != filter) continue;
                }
                self.next_id += 1;
                return try self.view.nodeRefFromRecord(record);
            }
            if (self.seen_nodes != self.view.by_id.node_count) return error.InvalidRecord;
            return null;
        }

        pub fn readRefTextAlloc(self: *const NodeRecordIterator, allocator: std.mem.Allocator, node_ref: NodeRecordView.NodeRef) ![]u8 {
            return self.view.readNodeRefTextAlloc(allocator, node_ref);
        }

        pub fn readRefTextBorrowed(self: *const NodeRecordIterator, node_ref: NodeRecordView.NodeRef) !?[]const u8 {
            return self.view.readNodeRefTextBorrowed(node_ref);
        }
    };

    pub fn nodeIdsIterator(self: Store, kind_filter: ?core.NodeKind) !NodeIdIterator {
        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{});
        errdefer index_file.close(self.io);
        const meta = try self.readCurrentIndexMeta();
        const header = try self.readNodeByIdHeaderFromFile(index_file);
        if (header.node_count != meta.nodes) return error.InvalidRecord;
        if (header.node_digest != meta.node_digest) return error.InvalidRecord;
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(header);
        if (try self.regularFileSize(index_file) != expected_size) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;

        var map = openReadOnlyMemoryMap(self.io, index_file, expected_size) catch null;
        errdefer if (map) |*mapped| mapped.destroy(self.io);

        return .{
            .store = self,
            .file = index_file,
            .map = map,
            .kind_filter = kind_filter,
            .header = header,
            .next_id = 1,
            .max_node_id = header.max_node_id,
            .expected_nodes = header.node_count,
        };
    }

    fn readNodeByIdHeaderFromFile(self: Store, file: std.Io.File) !NodeByIdHeader {
        var bytes: [NodeByIdHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return NodeByIdHeader.decode(&bytes);
    }

    fn readNodeByIdRecordAt(self: Store, file: std.Io.File, header: NodeByIdHeader, node_id: u64) !NodeByIdRecord {
        if (node_id == 0) return error.InvalidRecord;
        try header.validateShape();
        if (header.hasDerivedTextOffset()) {
            if (node_id > header.max_node_id) return error.InvalidRecord;
            const text_len = try self.readDerivedNodeByIdTextLenAt(file, header, node_id);
            const text_offset = try self.deriveNodeByIdTextOffsetFromFile(file, header, node_id);
            return .{
                .id = node_id,
                .kind = header.uniform_kind,
                .text_offset = text_offset,
                .text_len = text_len,
            };
        }
        var bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
        const record_bytes = bytes[0..header.record_len];
        const offset = try nodeByIdRecordOffsetForHeader(header, node_id);
        const n = try file.readPositionalAll(self.io, record_bytes, offset);
        if (n != record_bytes.len) return error.InvalidRecord;
        return NodeByIdRecord.decodeSliceAtForHeader(header, node_id, record_bytes);
    }

    fn readNodeByIdRecordFromMap(header: NodeByIdHeader, map: *const std.Io.File.MemoryMap, node_id: u64) !NodeByIdRecord {
        if (node_id == 0) return error.InvalidRecord;
        try header.validateShape();
        if (header.hasDerivedTextOffset()) {
            if (node_id > header.max_node_id) return error.InvalidRecord;
            const text_len = try readDerivedNodeByIdTextLenFromMap(header, map, node_id);
            const text_offset = try deriveNodeByIdTextOffsetFromMap(header, map, node_id);
            return .{
                .id = node_id,
                .kind = header.uniform_kind,
                .text_offset = text_offset,
                .text_len = text_len,
            };
        }
        const offset = try nodeByIdRecordOffsetForHeader(header, node_id);
        const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
        const end = std.math.add(usize, start, header.record_len) catch return error.InvalidRecord;
        if (end > map.memory.len) return error.InvalidRecord;
        return NodeByIdRecord.decodeSliceAtForHeader(header, node_id, map.memory[start..end]);
    }

    fn readDerivedNodeByIdTextLenAt(self: Store, file: std.Io.File, header: NodeByIdHeader, node_id: u64) !u32 {
        var len_bytes: [2]u8 = undefined;
        const offset = try nodeByIdRecordOffsetForHeader(header, node_id);
        if (try file.readPositionalAll(self.io, &len_bytes, offset) != len_bytes.len) return error.InvalidRecord;
        return readU16(&len_bytes);
    }

    fn deriveNodeByIdTextOffsetFromFile(self: Store, file: std.Io.File, header: NodeByIdHeader, node_id: u64) !u64 {
        const block = try nodeByIdTextOffsetCheckpointBlock(node_id);
        var checkpoint_bytes: [8]u8 = undefined;
        const checkpoint_offset = try nodeByIdTextOffsetCheckpointOffset(header, block);
        if (try file.readPositionalAll(self.io, &checkpoint_bytes, checkpoint_offset) != checkpoint_bytes.len) return error.InvalidRecord;
        var text_offset = readU64(&checkpoint_bytes);
        var id = block * node_by_id_text_offset_checkpoint_stride + 1;
        while (id < node_id) : (id += 1) {
            text_offset = std.math.add(u64, text_offset, try self.readDerivedNodeByIdTextLenAt(file, header, id)) catch return error.InvalidRecord;
        }
        return text_offset;
    }

    fn readNodeRecordById(self: Store, node_id: u64) !NodeByIdRecord {
        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{});
        defer index_file.close(self.io);
        const header = try self.readNodeByIdHeaderFromFile(index_file);
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(header);
        if (try self.regularFileSize(index_file) != expected_size) return error.InvalidRecord;
        if (node_id == 0 or node_id > header.max_node_id) return error.InvalidRecord;
        const record = try self.readNodeByIdRecordAt(index_file, header, node_id);
        if (record.id != node_id) return error.InvalidRecord;
        return record;
    }

    fn readNodeTextIndexHeaderFromFile(self: Store, file: std.Io.File) !NodeTextIndexHeader {
        var bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return NodeTextIndexHeader.decode(&bytes);
    }

    fn readNodeTextIndexRecordAt(self: Store, file: std.Io.File, index: u64) !NodeTextIndexRecord {
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        return self.readNodeTextIndexRecordAtForHeader(file, header, index);
    }

    fn readNodeTextIndexRecordAtForHeader(self: Store, file: std.Io.File, header: NodeTextIndexHeader, index: u64) !NodeTextIndexRecord {
        return self.readNodeTextIndexRecordAtForHeaderWithTextsAndNodes(file, header, index, null, null);
    }

    fn readNodeTextIndexRecordAtForHeaderWithTexts(
        self: Store,
        file: std.Io.File,
        header: NodeTextIndexHeader,
        index: u64,
        texts_view: ?*const NodeTextsView,
    ) !NodeTextIndexRecord {
        return self.readNodeTextIndexRecordAtForHeaderWithTextsAndNodes(file, header, index, texts_view, null);
    }

    fn readNodeTextIndexRecordAtForHeaderWithTextsAndNodes(
        self: Store,
        file: std.Io.File,
        header: NodeTextIndexHeader,
        index: u64,
        texts_view: ?*const NodeTextsView,
        node_view: ?*const NodeByIdIndexView,
    ) !NodeTextIndexRecord {
        try header.validateShape();
        var bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        const record_bytes = bytes[0..header.record_len];
        const offset = try nodeTextIndexRecordOffsetForHeader(header, index);
        const n = try file.readPositionalAll(self.io, record_bytes, offset);
        if (n != record_bytes.len) return error.InvalidRecord;
        const record = try NodeTextIndexRecord.decodeSliceForHeader(header, record_bytes);
        return self.finishNodeTextIndexRecordDecode(header, record, texts_view, node_view);
    }

    fn readNodeTextIndexRecordHashAtForHeader(
        self: Store,
        file: std.Io.File,
        header: NodeTextIndexHeader,
        index: u64,
        texts_view: ?*const NodeTextsView,
        node_view: ?*const NodeByIdIndexView,
    ) !u64 {
        try header.validateShape();
        var bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        const record_bytes = bytes[0..header.record_len];
        const offset = try nodeTextIndexRecordOffsetForHeader(header, index);
        const n = try file.readPositionalAll(self.io, record_bytes, offset);
        if (n != record_bytes.len) return error.InvalidRecord;
        const record = try NodeTextIndexRecord.decodeSliceForHeader(header, record_bytes);
        if (!header.hasDerivedHash() and !self.options.validate_indexes_on_read) return record.hash;
        return (try self.finishNodeTextIndexRecordDecode(header, record, texts_view, node_view)).hash;
    }

    fn readNodeTextIndexRecordAtForValidation(
        self: Store,
        file: std.Io.File,
        header: NodeTextIndexHeader,
        index: u64,
        node_view: ?*const NodeByIdIndexView,
    ) !NodeTextIndexRecord {
        try header.validateShape();
        if (index >= header.node_count) return error.InvalidRecord;
        var bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        const record_bytes = bytes[0..header.record_len];
        const offset = try nodeTextIndexRecordOffsetForHeader(header, index);
        const n = try file.readPositionalAll(self.io, record_bytes, offset);
        if (n != record_bytes.len) return error.InvalidRecord;
        var record = try NodeTextIndexRecord.decodeSliceForHeader(header, record_bytes);
        if (header.hasDerivedTextSpan()) {
            const by_id = if (node_view) |nodes|
                try nodes.readRecord(record.id)
            else
                try self.readNodeRecordById(record.id);
            if (by_id.id != record.id) return error.InvalidRecord;
            if (by_id.kind != record.kind) return error.InvalidRecord;
            record.text_offset = by_id.text_offset;
            record.text_len = by_id.text_len;
        }
        return record;
    }

    fn finishNodeTextIndexRecordDecode(
        self: Store,
        header: NodeTextIndexHeader,
        decoded_record: NodeTextIndexRecord,
        texts_view: ?*const NodeTextsView,
        node_view: ?*const NodeByIdIndexView,
    ) !NodeTextIndexRecord {
        var record = decoded_record;
        if (header.hasDerivedTextSpan()) {
            const by_id = if (node_view) |nodes|
                try nodes.readRecord(record.id)
            else
                try self.readNodeRecordById(record.id);
            if (by_id.id != record.id) return error.InvalidRecord;
            if (by_id.kind != record.kind) return error.InvalidRecord;
            record.text_offset = by_id.text_offset;
            record.text_len = by_id.text_len;
        }
        if (!header.hasDerivedHash()) return record;
        if (texts_view) |texts| {
            record.hash = try texts.hashStoredText(record.text_offset, record.text_len);
            return record;
        }
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        record.hash = try texts.hashStoredText(record.text_offset, record.text_len);
        return record;
    }

    fn readNodeTextIndexRecordHashFromMapForHeader(
        self: Store,
        header: NodeTextIndexHeader,
        map: *const std.Io.File.MemoryMap,
        index: u64,
        texts_view: ?*const NodeTextsView,
        node_view: ?*const NodeByIdIndexView,
    ) !u64 {
        try header.validateShape();
        const offset = try nodeTextIndexRecordOffsetForHeader(header, index);
        const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
        const end = std.math.add(usize, start, header.record_len) catch return error.InvalidRecord;
        if (end > map.memory.len) return error.InvalidRecord;
        const record = try NodeTextIndexRecord.decodeSliceForHeader(header, map.memory[start..end]);
        if (!header.hasDerivedHash() and !self.options.validate_indexes_on_read) return record.hash;
        return (try self.finishNodeTextIndexRecordDecode(header, record, texts_view, node_view)).hash;
    }

    fn readNodeTextIndexRecordFromMap(map: *const std.Io.File.MemoryMap, index: u64) !NodeTextIndexRecord {
        if (map.memory.len < NodeTextIndexHeader.encoded_len) return error.InvalidRecord;
        const header_bytes: *const [NodeTextIndexHeader.encoded_len]u8 = map.memory[0..NodeTextIndexHeader.encoded_len];
        const header = try NodeTextIndexHeader.decode(header_bytes);
        return readNodeTextIndexRecordFromMapForHeader(header, map, index);
    }

    fn readNodeTextIndexRecordFromMapForHeader(header: NodeTextIndexHeader, map: *const std.Io.File.MemoryMap, index: u64) !NodeTextIndexRecord {
        return readNodeTextIndexRecordFromMapForHeaderWithTextsAndNodes(header, map, index, null, null);
    }

    fn readNodeTextIndexRecordFromMapForHeaderWithTexts(
        header: NodeTextIndexHeader,
        map: *const std.Io.File.MemoryMap,
        index: u64,
        texts_view: ?*const NodeTextsView,
    ) !NodeTextIndexRecord {
        return readNodeTextIndexRecordFromMapForHeaderWithTextsAndNodes(header, map, index, texts_view, null);
    }

    fn readNodeTextIndexRecordFromMapForHeaderWithTextsAndNodes(
        header: NodeTextIndexHeader,
        map: *const std.Io.File.MemoryMap,
        index: u64,
        texts_view: ?*const NodeTextsView,
        node_view: ?*const NodeByIdIndexView,
    ) !NodeTextIndexRecord {
        try header.validateShape();
        const offset = try nodeTextIndexRecordOffsetForHeader(header, index);
        const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
        const end = std.math.add(usize, start, header.record_len) catch return error.InvalidRecord;
        if (end > map.memory.len) return error.InvalidRecord;
        var record = try NodeTextIndexRecord.decodeSliceForHeader(header, map.memory[start..end]);
        if (header.hasDerivedTextSpan()) {
            const nodes = node_view orelse return error.InvalidRecord;
            const by_id = try nodes.readRecord(record.id);
            if (by_id.id != record.id) return error.InvalidRecord;
            if (by_id.kind != record.kind) return error.InvalidRecord;
            record.text_offset = by_id.text_offset;
            record.text_len = by_id.text_len;
        }
        if (header.hasDerivedHash()) {
            const texts = texts_view orelse return error.InvalidRecord;
            record.hash = try texts.hashStoredText(record.text_offset, record.text_len);
        }
        return record;
    }

    fn readNodeTextRunManifest(self: Store, allocator: std.mem.Allocator) !NodeTextRunManifest {
        if (try self.readNodeTextRunCurrentPath(allocator)) |manifest_path| {
            defer allocator.free(manifest_path);
            return self.readNodeTextRunManifestFile(allocator, manifest_path) catch |err| switch (err) {
                error.FileNotFound => error.InvalidRecord,
                else => |e| e,
            };
        }
        return NodeTextRunManifest{};
    }

    fn cachedNodeTextRunManifestForMeta(self: Store, meta: IndexMeta) !?*const NodeTextRunManifest {
        if (!self.options.validate_indexes_on_read and
            self.node_text_run_manifest_cache.valid and
            self.node_text_run_manifest_cache.event_bytes == meta.event_bytes)
        {
            return &self.node_text_run_manifest_cache.manifest;
        }
        return self.cachedNodeTextRunManifestWithEventBytes(meta.event_bytes);
    }

    fn cachedNodeTextRunManifest(self: Store) !?*const NodeTextRunManifest {
        return self.cachedNodeTextRunManifestWithEventBytes(null);
    }

    fn cachedNodeTextRunManifestWithEventBytes(self: Store, event_bytes: ?u64) !?*const NodeTextRunManifest {
        const manifest_path = (try self.readNodeTextRunCurrentPath(self.allocator)) orelse {
            self.node_text_run_manifest_cache.clear(self.allocator);
            return null;
        };
        defer self.allocator.free(manifest_path);

        if (self.node_text_run_manifest_cache.valid and std.mem.eql(u8, self.node_text_run_manifest_cache.path, manifest_path)) {
            if (event_bytes) |bytes| self.node_text_run_manifest_cache.event_bytes = bytes;
            return &self.node_text_run_manifest_cache.manifest;
        }

        try self.replaceNodeTextRunManifestCache(manifest_path);
        if (event_bytes) |bytes| self.node_text_run_manifest_cache.event_bytes = bytes;
        return &self.node_text_run_manifest_cache.manifest;
    }

    fn replaceNodeTextRunManifestCache(self: Store, manifest_path: []const u8) !void {
        self.node_text_run_manifest_cache.clear(self.allocator);
        self.node_text_run_manifest_cache.path = try self.allocator.dupe(u8, manifest_path);
        errdefer self.node_text_run_manifest_cache.clear(self.allocator);
        self.node_text_run_manifest_cache.manifest = self.readNodeTextRunManifestFile(self.allocator, manifest_path) catch |err| switch (err) {
            error.FileNotFound => return error.InvalidRecord,
            else => |e| return e,
        };
        self.node_text_run_manifest_cache.valid = true;
    }

    fn warmNodeTextRunManifestCache(self: Store, manifest_path: []const u8) void {
        self.replaceNodeTextRunManifestCache(manifest_path) catch {
            self.invalidateNodeTextRunManifestCache();
        };
    }

    fn invalidateNodeTextRunManifestCache(self: Store) void {
        self.node_text_run_manifest_cache.clear(self.allocator);
    }

    fn nodeTextHeaderMatchesBaseFilter(expected: NodeTextIndexHeader, actual: NodeTextIndexHeader) bool {
        return expected.node_count == actual.node_count and
            expected.node_digest == actual.node_digest and
            expected.order_digest == actual.order_digest and
            expected.flags == actual.flags and
            expected.record_len == actual.record_len and
            expected.uniform_kind == actual.uniform_kind;
    }

    fn cachedNodeTextBaseHashFilter(self: Store, expected_header: ?NodeTextIndexHeader) !?*const NodeTextBaseHashFilter {
        if (self.node_text_base_filter_cache.valid) {
            if (expected_header == null or nodeTextHeaderMatchesBaseFilter(expected_header.?, self.node_text_base_filter_cache.filter.header)) {
                return &self.node_text_base_filter_cache.filter;
            }
            self.node_text_base_filter_cache.clear(self.allocator);
        }
        if (self.node_text_base_filter_cache.known_absent) return null;
        var loaded = (try self.readCurrentNodeTextBaseHashFilter(expected_header)) orelse {
            self.node_text_base_filter_cache.known_absent = true;
            return null;
        };
        errdefer loaded.deinit(self.allocator);
        self.node_text_base_filter_cache.clear(self.allocator);
        self.node_text_base_filter_cache.filter = loaded;
        self.node_text_base_filter_cache.valid = true;
        loaded = .{ .header = .{ .node_count = 0 } };
        return &self.node_text_base_filter_cache.filter;
    }

    fn nodeTextBaseFilterMatchesCurrentBase(self: Store, filter_header: NodeTextIndexHeader) !bool {
        var file = std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .allow_directory = false }) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer file.close(self.io);
        const current_header = try self.readNodeTextIndexHeaderFromFile(file);
        if (!nodeTextHeaderMatchesBaseFilter(filter_header, current_header)) return false;
        if (try self.regularFileSize(file) != try nodeTextIndexFileSizeForHeader(current_header)) return error.InvalidRecord;
        return true;
    }

    fn readCurrentNodeTextBaseHashFilter(self: Store, expected_header: ?NodeTextIndexHeader) !?NodeTextBaseHashFilter {
        var file = std.Io.Dir.cwd().openFile(self.io, self.node_by_text_base_filter_path, .{ .allow_directory = false }) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size < NodeTextBaseHashFilterHeader.encoded_len) return null;
        var header_bytes: [NodeTextBaseHashFilterHeader.encoded_len]u8 = undefined;
        const header_n = try file.readPositionalAll(self.io, &header_bytes, 0);
        if (header_n != header_bytes.len) return null;
        const sidecar_header = NodeTextBaseHashFilterHeader.decode(&header_bytes) catch return null;
        if (expected_header) |expected| {
            if (!nodeTextHeaderMatchesBaseFilter(expected, sidecar_header.node_text_header)) return null;
        }
        const expected_size = std.math.add(u64, NodeTextBaseHashFilterHeader.encoded_len, sidecar_header.filter_len) catch return null;
        if (file_size != expected_size) return null;
        const filter_len = std.math.cast(usize, sidecar_header.filter_len) orelse return null;
        const filter = try self.allocator.alloc(u8, filter_len);
        errdefer self.allocator.free(filter);
        const filter_n = try file.readPositionalAll(self.io, filter, NodeTextBaseHashFilterHeader.encoded_len);
        if (filter_n != filter.len) {
            self.allocator.free(filter);
            return null;
        }
        if (nodeTextHashFilterDigest(filter) != sidecar_header.filter_digest) {
            self.allocator.free(filter);
            return null;
        }
        return NodeTextBaseHashFilter{
            .header = sidecar_header.node_text_header,
            .filter = filter,
        };
    }

    fn ensureNodeTextBaseHashFilter(self: Store, expected_header: NodeTextIndexHeader) !void {
        const filter_len = nodeTextBaseHashFilterLenForRecords(expected_header.node_count);
        if (filter_len == 0) {
            std.Io.Dir.cwd().deleteFile(self.io, self.node_by_text_base_filter_path) catch |err| switch (err) {
                error.FileNotFound => {},
                else => |e| return e,
            };
            self.node_text_base_filter_cache.clear(self.allocator);
            return;
        }
        if (try self.cachedNodeTextBaseHashFilter(expected_header)) |_| {
            return;
        }
        try self.writeNodeTextBaseHashFilter(expected_header);
    }

    fn ensureCurrentNodeTextBaseHashFilter(self: Store) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        if (try self.regularFileSize(file) != try nodeTextIndexFileSizeForHeader(header)) return error.InvalidRecord;
        try self.ensureNodeTextBaseHashFilter(header);
    }

    fn writeNodeTextBaseHashFilter(self: Store, expected_header: NodeTextIndexHeader) !void {
        const filter_len = nodeTextBaseHashFilterLenForRecords(expected_header.node_count);
        if (filter_len == 0) return;
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .allow_directory = false });
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        if (!nodeTextHeaderMatchesBaseFilter(expected_header, header)) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try nodeTextIndexFileSizeForHeader(header)) return error.InvalidRecord;

        const filter = try self.allocator.alloc(u8, filter_len);
        defer self.allocator.free(filter);
        @memset(filter, 0);

        var texts: ?NodeTextsView = null;
        defer if (texts) |*view| view.deinit();
        var nodes: ?NodeByIdIndexView = null;
        defer if (nodes) |*view| view.deinit();
        const texts_for_hash = if (header.hasDerivedHash()) blk: {
            texts = try NodeTextsView.open(self);
            break :blk &texts.?;
        } else null;
        const nodes_for_hash = if (header.hasDerivedHash() and header.hasDerivedTextSpan()) blk: {
            const meta = try self.readIndexMeta();
            nodes = try NodeByIdIndexView.open(self, meta);
            break :blk &nodes.?;
        } else null;

        var pos: u64 = 0;
        while (pos < header.node_count) : (pos += 1) {
            nodeTextRunHashFilterSet(filter, try self.readNodeTextIndexRecordHashAtForHeader(file, header, pos, texts_for_hash, nodes_for_hash));
        }

        const tmp_path = try self.tmpPathFor(self.node_by_text_base_filter_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var out_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer out_file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, out_file, try storageWriteBufferCapacity(NodeTextBaseHashFilterHeader.encoded_len + filter.len));
            defer writer.deinit();
            const sidecar_header = NodeTextBaseHashFilterHeader{
                .node_text_header = header,
                .filter_len = @intCast(filter.len),
                .filter_digest = nodeTextHashFilterDigest(filter),
            };
            var header_bytes: [NodeTextBaseHashFilterHeader.encoded_len]u8 = undefined;
            try sidecar_header.encode(&header_bytes);
            try writer.append(&header_bytes);
            try writer.append(filter);
            try writer.flush();
            if (selfOptionsNeedSync(self)) try out_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_by_text_base_filter_path);
        self.node_text_base_filter_cache.clear(self.allocator);
        const cached_filter = try self.readCurrentNodeTextBaseHashFilter(header);
        if (cached_filter) |loaded_filter| {
            self.node_text_base_filter_cache.filter = loaded_filter;
            self.node_text_base_filter_cache.valid = true;
        }
    }

    fn readNodeTextRunManifestFile(self: Store, allocator: std.mem.Allocator, manifest_path: []const u8) !NodeTextRunManifest {
        var file = try std.Io.Dir.cwd().openFile(self.io, manifest_path, .{});
        var file_owned = true;
        defer if (file_owned) file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size < NodeTextRunManifest.header_len) return error.InvalidRecord;
        const backing_size = std.math.cast(usize, file_size) orelse return error.RecordTooLarge;
        var map = openReadOnlyMemoryMap(self.io, file, file_size) catch null;
        errdefer if (map) |*mapped| mapped.destroy(self.io);
        const backing = if (map) |*mapped| mapped.memory else blk: {
            const bytes = try allocator.alloc(u8, backing_size);
            errdefer allocator.free(bytes);
            if (try file.readPositionalAll(self.io, bytes, 0) != bytes.len) return error.InvalidRecord;
            break :blk bytes;
        };
        const header_bytes: *const [NodeTextRunManifest.header_len]u8 = backing[0..NodeTextRunManifest.header_len];
        const header = try decodeNodeTextRunManifestHeader(header_bytes);
        if (header.run_count > node_text_run_manifest_max_entries) return error.InvalidRecord;

        var manifest = NodeTextRunManifest{
            .total_node_count = header.total_nodes,
            .node_digest = header.node_digest,
            .aggregates_valid = true,
            .backing = backing,
            .io = self.io,
            .file = if (map != null) file else null,
            .map = map,
        };
        if (map != null) {
            file_owned = false;
            map = null;
        }
        errdefer manifest.deinit(allocator);
        try manifest.entries.ensureTotalCapacity(allocator, header.run_count);
        var offset: u64 = NodeTextRunManifest.header_len;
        var total_count: u64 = 0;
        var total_digest: u64 = 0;
        var pos: usize = 0;
        while (pos < header.run_count) : (pos += 1) {
            const entry_end = std.math.add(u64, offset, NodeTextRunManifest.entry_header_len) catch return error.InvalidRecord;
            if (entry_end > file_size) return error.InvalidRecord;
            const entry_start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
            const entry_bytes: *const [NodeTextRunManifest.entry_header_len]u8 = backing[entry_start..][0..NodeTextRunManifest.entry_header_len];
            const entry = try decodeNodeTextRunManifestEntryHeader(entry_bytes);
            if (entry.node_count == 0 or entry.node_count > node_text_run_max_records) return error.InvalidRecord;
            if (entry.path_len == 0 or entry.path_len > node_text_run_current_max_path_bytes) return error.InvalidRecord;
            offset = entry_end;
            const path_end = std.math.add(u64, offset, entry.path_len) catch return error.InvalidRecord;
            if (path_end > file_size) return error.InvalidRecord;
            const path_start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
            const path_end_usize = std.math.cast(usize, path_end) orelse return error.RecordTooLarge;
            const path = backing[path_start..path_end_usize];
            offset = path_end;
            if (!nodeTextRunHashFilterLenValid(entry.hash_filter_len)) return error.InvalidRecord;
            const filter_end = std.math.add(u64, offset, entry.hash_filter_len) catch return error.InvalidRecord;
            if (filter_end > file_size) return error.InvalidRecord;
            const filter_start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
            const filter_end_usize = std.math.cast(usize, filter_end) orelse return error.RecordTooLarge;
            const hash_filter = backing[filter_start..filter_end_usize];
            offset = filter_end;
            total_count = std.math.add(u64, total_count, entry.node_count) catch return error.InvalidRecord;
            total_digest ^= entry.node_digest;
            manifest.entries.appendAssumeCapacity(.{
                .node_count = entry.node_count,
                .node_digest = entry.node_digest,
                .order_digest = entry.order_digest,
                .min_node_id = entry.min_node_id,
                .max_node_id = entry.max_node_id,
                .min_hash = entry.min_hash,
                .max_hash = entry.max_hash,
                .path = path,
                .path_digest = std.hash.Wyhash.hash(0x544B_4E52, path),
                .has_path_digest = true,
                .hash_filter = hash_filter,
            });
        }
        if (offset != file_size) return error.InvalidRecord;
        if (total_count != header.total_nodes) return error.InvalidRecord;
        if (total_digest != header.node_digest) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read and nodeTextRunManifestContentDigestOwned(manifest.entries.items) != header.content_digest) return error.InvalidRecord;
        if (self.isNodeTextRunManifestEpochPath(manifest_path)) {
            const expected_path = try self.nodeTextRunManifestEpochPath(total_count, nodeTextRunManifestEpochDigestOwned(manifest.entries.items));
            defer self.allocator.free(expected_path);
            if (!std.mem.eql(u8, manifest_path, expected_path)) return error.InvalidRecord;
        }
        return manifest;
    }

    fn writeNodeTextRunManifestEntries(self: Store, entries: []const NodeTextRunManifestEntry) !void {
        return self.writeNodeTextRunManifestEntriesExcept(entries, &.{});
    }

    fn writeNodeTextRunManifestEntriesExcept(self: Store, entries: []const NodeTextRunManifestEntry, pinned_manifest_paths: []const []const u8) !void {
        if (entries.len > node_text_run_manifest_max_entries) return core.Error.BudgetExceeded;
        const total_nodes = try nodeTextRunManifestTotalNodes(entries);
        const epoch_digest = nodeTextRunManifestEpochDigest(entries);
        const epoch_path = try self.nodeTextRunManifestEpochPath(total_nodes, epoch_digest);
        defer self.allocator.free(epoch_path);
        const previous_epoch_path = try self.readNodeTextRunCurrentPath(self.allocator);
        defer if (previous_epoch_path) |path| self.allocator.free(path);

        // Once CURRENT is renamed, `epoch_path` is live even if the following
        // parent-directory sync reports an error. Never arm an errdefer that
        // can remove a possibly published manifest. An unreferenced epoch from
        // an earlier failure is harmless and the normal GC pass can reclaim it.
        try self.writeNodeTextRunManifestFile(epoch_path, entries);
        try self.writeNodeTextRunCurrent(epoch_path);
        self.warmNodeTextRunManifestCache(epoch_path);
        if (previous_epoch_path) |path| {
            if (!std.mem.eql(u8, path, epoch_path)) {
                // CURRENT already names the new epoch. Retiring its predecessor
                // is post-commit GC and must not turn a successful publication
                // into an error or unwind callers that own newly referenced runs.
                self.deleteSupersededNodeTextRunManifestEpochExcept(path, pinned_manifest_paths) catch {};
            }
        }
    }

    fn deleteSupersededNodeTextRunManifestEpochExcept(self: Store, manifest_path: []const u8, pinned_manifest_paths: []const []const u8) !void {
        if (!self.isNodeTextRunManifestEpochPath(manifest_path)) return;
        if (manifestPathListContains(pinned_manifest_paths, manifest_path)) return;
        if (try self.nodeTextRunManifestEpochHasActiveProcessLease(manifest_path)) return;
        std.Io.Dir.cwd().deleteFile(self.io, manifest_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
    }

    fn isNodeTextRunManifestEpochPath(self: Store, manifest_path: []const u8) bool {
        const manifest_dir = std.fs.path.dirname(manifest_path) orelse return false;
        if (!std.mem.eql(u8, manifest_dir, self.dir_path)) return false;
        const manifest_leaf = std.fs.path.basename(self.node_text_run_manifest_path);
        const path_leaf = std.fs.path.basename(manifest_path);
        return path_leaf.len > manifest_leaf.len and
            std.mem.startsWith(u8, path_leaf, manifest_leaf) and
            path_leaf[manifest_leaf.len] == '.';
    }

    fn nodeTextRunManifestEpochHasActiveProcessLease(self: Store, manifest_path: []const u8) !bool {
        const process_paths = try self.activeProcessLeaseManifestPaths(.node_text_run, self.allocator);
        defer freeOwnedManifestPathList(self.allocator, process_paths);
        return manifestPathListContains(process_paths, manifest_path);
    }

    fn manifestPathListContains(paths: []const []const u8, needle: []const u8) bool {
        for (paths) |path| {
            if (std.mem.eql(u8, path, needle)) return true;
        }
        return false;
    }

    fn nodeTextRunManifestTotalNodes(entries: []const NodeTextRunManifestEntry) !u64 {
        var total: u64 = 0;
        for (entries) |entry| {
            total = std.math.add(u64, total, entry.node_count) catch return error.RecordTooLarge;
        }
        return total;
    }

    fn nodeTextRunManifestEpochDigest(entries: []const NodeTextRunManifestEntry) u64 {
        return nodeTextRunManifestDigestFields(entries, false);
    }

    fn nodeTextRunManifestEpochPath(self: Store, total_nodes: u64, digest: u64) ![]u8 {
        return std.fmt.allocPrint(self.allocator, "{s}.{d}.{x}", .{ self.node_text_run_manifest_path, total_nodes, digest });
    }

    fn writeNodeTextRunManifestFile(self: Store, manifest_path: []const u8, entries: []const NodeTextRunManifestEntry) !void {
        const tmp_path = try self.tmpPathFor(manifest_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, storage_write_buffer_bytes);
            defer writer.deinit();

            var header: [NodeTextRunManifest.header_len]u8 = undefined;
            try encodeNodeTextRunManifestHeader(entries, &header);
            try writer.append(&header);

            var entry_header: [NodeTextRunManifest.entry_header_len]u8 = undefined;
            for (entries) |entry| {
                try encodeNodeTextRunManifestEntryHeader(entry, &entry_header);
                try writer.append(&entry_header);
                try writer.append(entry.path);
                try writer.append(entry.hash_filter);
            }
            try writer.flush();
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, manifest_path);
    }

    fn writeNodeTextRunCurrent(self: Store, manifest_path: []const u8) !void {
        if (manifest_path.len == 0 or manifest_path.len > node_text_run_current_max_path_bytes) return error.RecordTooLarge;
        const tmp_path = try self.tmpPathFor(self.node_text_run_current_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            try file.writePositionalAll(self.io, manifest_path, 0);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_text_run_current_path);
        self.invalidateNodeTextRunManifestCache();
    }

    fn readNodeTextRunCurrentPath(self: Store, allocator: std.mem.Allocator) !?[]u8 {
        var file = std.Io.Dir.cwd().openFile(self.io, self.node_text_run_current_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size == 0 or file_size > node_text_run_current_max_path_bytes) return error.InvalidRecord;
        const path_len = std.math.cast(usize, file_size) orelse return error.InvalidRecord;
        const path = try allocator.alloc(u8, path_len);
        errdefer allocator.free(path);
        const n = try file.readPositionalAll(self.io, path, 0);
        if (n != path.len) return error.InvalidRecord;
        return path;
    }

    fn readEdgeIndexRecordById(self: Store, edge_id: core.EdgeId) !EdgeIndexRecord {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer file.close(self.io);
        const meta = try self.readCurrentIndexMeta();
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != .id) return error.InvalidRecord;
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, .id)) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        const id = edge_id.toInt();
        const record = try self.readEdgeIndexRecordByIdFromOpenFile(file, header, id);
        if (try self.edgeTombstoneContains(id)) return core.Error.InvalidId;
        return record;
    }

    fn readVisibleEdgeIndexRecordById(self: Store, edge_id: core.EdgeId) !EdgeIndexRecord {
        const base_record: ?EdgeIndexRecord = self.readEdgeIndexRecordById(edge_id) catch |err| switch (err) {
            core.Error.InvalidId => null,
            else => |e| return e,
        };
        if (base_record) |record| return record;
        const raw_id = edge_id.toInt();
        if (raw_id == 0 or raw_id == std.math.maxInt(u64) or try self.edgeTombstoneContains(raw_id)) return core.Error.InvalidId;
        var opened = (try self.openPublishedEdgeSegmentsForQuery(self.allocator)) orelse return core.Error.InvalidId;
        defer opened.deinit();
        var stream = EdgeSegmentMergeStream.initWithVirtual(
            self.allocator,
            &opened.segments.segments,
            &opened.segments.virtual_edges,
            .forward,
        );
        defer stream.deinit();
        try stream.reset();
        while (try stream.next()) |edge| {
            if (edge.edge_id.toInt() != raw_id) continue;
            return .{
                .src = edge.src.toInt(),
                .dst = edge.dst.toInt(),
                .edge_id = raw_id,
                .rel = @intFromEnum(edge.rel),
            };
        }
        return core.Error.InvalidId;
    }

    pub fn readEdgeById(self: Store, edge_id: core.EdgeId) !graph_mod.Edge {
        const record = try self.readVisibleEdgeIndexRecordById(edge_id);
        return .{
            .id = .fromInt(record.edge_id),
            .src = .fromInt(record.src),
            .rel = @enumFromInt(record.rel),
            .dst = .fromInt(record.dst),
        };
    }

    pub fn loadEdgeRefs(self: Store, allocator: std.mem.Allocator) ![]StoredEdgeRef {
        var out = std.ArrayList(StoredEdgeRef).empty;
        errdefer out.deinit(allocator);
        const meta = try self.readCurrentIndexMeta();
        try out.ensureTotalCapacityPrecise(allocator, std.math.cast(usize, meta.edges) orelse return error.RecordTooLarge);
        const Context = struct {
            allocator: std.mem.Allocator,
            refs: *std.ArrayList(StoredEdgeRef),

            fn visit(raw: *anyopaque, record: EdgeIndexRecord) !void {
                const context: *@This() = @ptrCast(@alignCast(raw));
                try context.refs.append(context.allocator, .{
                    .src = core.NodeId.fromInt(record.src),
                    .dst = core.NodeId.fromInt(record.dst),
                    .edge_id = core.EdgeId.fromInt(record.edge_id),
                    .rel = try record.relKind(),
                });
            }
        };
        var context = Context{ .allocator = allocator, .refs = &out };
        _ = try self.scanVisibleEdgeIndexRecords(allocator, &context, Context.visit);
        return try out.toOwnedSlice(allocator);
    }

    fn readEdgeIndexRecordByIdFromOpenFile(self: Store, file: std.Io.File, header: EdgeIndexHeader, id: u64) !EdgeIndexRecord {
        if (header.order != .id) return error.InvalidRecord;
        if (id == 0 or id == std.math.maxInt(u64)) return core.Error.InvalidId;
        var lo: u64 = 0;
        var hi: u64 = header.edge_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readEdgeIndexRecordAt(file, header, mid);
            if (record.edge_id < id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= header.edge_count) return core.Error.InvalidId;
        const record = try self.readEdgeIndexRecordAt(file, header, lo);
        if (record.edge_id != id) return core.Error.InvalidId;
        return record;
    }

    fn readAllEdgeTombstones(self: Store, allocator: std.mem.Allocator) !std.ArrayList(EdgeTombstoneRecord) {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_tombstones_path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeTombstoneHeaderFromFile(file);
        const expected_size = try edgeTombstoneFileSize(header.count);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        var edge_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer edge_file.close(self.io);
        const edge_header = try self.readEdgeIndexHeaderFromFile(edge_file);
        if (edge_header.order != .id) return error.InvalidRecord;
        if (try self.regularFileSize(edge_file) != try edgeIndexFileSizeForHeader(edge_header)) return error.InvalidRecord;
        var out = std.ArrayList(EdgeTombstoneRecord).empty;
        errdefer out.deinit(allocator);
        try out.ensureTotalCapacity(allocator, @intCast(header.count));
        var digest: u64 = 0;
        var previous: u64 = 0;
        var pos: u64 = 0;
        while (pos < header.count) : (pos += 1) {
            var record = try self.readEdgeTombstoneRecordAt(file, pos);
            if (record.edge_id <= previous) return error.InvalidRecord;
            previous = record.edge_id;
            record.edge_digest = edgeRecordDigest(try self.readEdgeIndexRecordByIdFromOpenFile(edge_file, edge_header, record.edge_id));
            digest ^= record.edge_digest;
            out.appendAssumeCapacity(record);
        }
        if (digest != header.digest) return error.InvalidRecord;
        return out;
    }

    fn edgeTombstoneContains(self: Store, edge_id: u64) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_tombstones_path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeTombstoneHeaderFromFile(file);
        const expected_size = try edgeTombstoneFileSize(header.count);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        var lo: u64 = 0;
        var hi: u64 = header.count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readEdgeTombstoneRecordAt(file, mid);
            if (record.edge_id < edge_id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= header.count) return false;
        const record = try self.readEdgeTombstoneRecordAt(file, lo);
        return record.edge_id == edge_id;
    }

    fn insertEdgeTombstone(self: Store, record: EdgeIndexRecord) !EdgeTombstoneHeader {
        const tombstone = EdgeTombstoneRecord{
            .edge_id = record.edge_id,
            .edge_digest = edgeRecordDigest(record),
        };
        return self.insertEdgeTombstoneStreaming(tombstone);
    }

    fn insertEdgeTombstoneStreaming(self: Store, tombstone: EdgeTombstoneRecord) !EdgeTombstoneHeader {
        if (tombstone.edge_id == 0 or tombstone.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_tombstones_path, .{});
        defer old_file.close(self.io);
        const old_header = try self.readEdgeTombstoneHeaderFromFile(old_file);
        const old_size = try edgeTombstoneFileSize(old_header.count);
        if (try self.regularFileSize(old_file) != old_size) return error.InvalidRecord;
        const new_count = std.math.add(u64, old_header.count, 1) catch return error.InvalidRecord;

        const tmp_path = try self.tmpPathFor(self.edge_tombstones_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var new_header = EdgeTombstoneHeader{ .count = new_count, .digest = 0 };
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(try edgeTombstoneFileSize(new_count)));
            defer writer.deinit();

            var header_bytes: [EdgeTombstoneHeader.encoded_len]u8 = undefined;
            const placeholder_header = EdgeTombstoneHeader{ .count = new_count, .digest = 0 };
            placeholder_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var record_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
            var new_digest: u64 = old_header.digest;
            var previous: u64 = 0;
            var inserted = false;
            var written: u64 = 0;
            var pos: u64 = 0;
            while (pos < old_header.count) : (pos += 1) {
                const old_record = try self.readEdgeTombstoneRecordAt(old_file, pos);
                if (old_record.edge_id <= previous) return error.InvalidRecord;
                if (!inserted and tombstone.edge_id < old_record.edge_id) {
                    tombstone.encode(&record_bytes);
                    try writer.append(&record_bytes);
                    new_digest ^= tombstone.edge_digest;
                    written += 1;
                    previous = tombstone.edge_id;
                    inserted = true;
                }
                if (old_record.edge_id <= previous) return if (old_record.edge_id == tombstone.edge_id) core.Error.InvalidId else error.InvalidRecord;
                old_record.encode(&record_bytes);
                try writer.append(&record_bytes);
                written += 1;
                previous = old_record.edge_id;
            }
            if (!inserted) {
                if (tombstone.edge_id <= previous) return if (tombstone.edge_id == previous) core.Error.InvalidId else error.InvalidRecord;
                tombstone.encode(&record_bytes);
                try writer.append(&record_bytes);
                new_digest ^= tombstone.edge_digest;
                written += 1;
            }
            if (written != new_count) return error.InvalidRecord;
            new_header.digest = new_digest;
            try writer.flush();
            if (try writer.position() != try edgeTombstoneFileSize(new_count)) return error.InvalidRecord;
            new_header.encode(&header_bytes);
            try new_file.writePositionalAll(self.io, &header_bytes, 0);
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.edge_tombstones_path);
        return new_header;
    }

    fn readStoredNodeFromRecord(self: Store, allocator: std.mem.Allocator, record: NodeByIdRecord) !StoredNode {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        return texts.readStoredNode(allocator, record);
    }

    fn readEdgeIndexHeaderFromFile(self: Store, file: std.Io.File) !EdgeIndexHeader {
        var bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return EdgeIndexHeader.decode(&bytes);
    }

    fn readEdgeTombstoneHeaderFromFile(self: Store, file: std.Io.File) !EdgeTombstoneHeader {
        var bytes: [EdgeTombstoneHeader.encoded_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, 0);
        if (n != bytes.len) return error.InvalidRecord;
        return EdgeTombstoneHeader.decode(&bytes);
    }

    fn readEdgeIndexRecordAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, index: u64) !EdgeIndexRecord {
        try header.validateShape();
        const run: ?EdgeIndexKeyRunRecord = if (header.hasKeyRuns())
            try self.readEdgeIndexKeyRunForRecordAt(file, header, index)
        else
            null;
        var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        const record_bytes = bytes[0..header.record_len];
        const offset = try edgeIndexRecordOffsetForHeader(header, index);
        const n = try file.readPositionalAll(self.io, record_bytes, offset);
        if (n != record_bytes.len) return error.InvalidRecord;
        return EdgeIndexRecord.decodeSliceAtForHeader(header, index, record_bytes, run);
    }

    fn readEdgeTombstoneRecordAt(self: Store, file: std.Io.File, index: u64) !EdgeTombstoneRecord {
        var bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
        const offset = try edgeTombstoneRecordOffset(index);
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return EdgeTombstoneRecord.decode(&bytes);
    }

    fn readEdgeIndexRecordFromMap(header: EdgeIndexHeader, map: *const std.Io.File.MemoryMap, index: u64) !EdgeIndexRecord {
        try header.validateShape();
        const run: ?EdgeIndexKeyRunRecord = if (header.hasKeyRuns())
            try readEdgeIndexKeyRunForRecordFromMap(header, map, index)
        else
            null;
        const offset = try edgeIndexRecordOffsetForHeader(header, index);
        const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
        const end = std.math.add(usize, start, header.record_len) catch return error.InvalidRecord;
        if (end > map.memory.len) return error.InvalidRecord;
        return EdgeIndexRecord.decodeSliceAtForHeader(header, index, map.memory[start..end], run);
    }

    fn readEdgeIndexKeyRunAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, run_index: u64) !EdgeIndexKeyRunRecord {
        if (!header.hasKeyRuns() or run_index >= header.key_run_count) return error.InvalidRecord;
        const dense_end = if (header.hasKeyRunDenseSpan())
            try std.math.add(u64, header.key_run_dense_run_start, header.key_run_dense_count)
        else
            0;
        if (header.hasKeyRunDenseSpan() and run_index >= header.key_run_dense_run_start and run_index < dense_end) {
            return edgeIndexDenseKeyRunSpanRecordForIndex(header, run_index);
        }
        var bytes: [40]u8 = undefined;
        const run_bytes = bytes[0..edgeIndexKeyRunRecordLen(header)];
        const offset = try edgeIndexKeyRunOffsetForHeader(header, run_index);
        const n = try file.readPositionalAll(self.io, run_bytes, offset);
        if (n != run_bytes.len) return error.InvalidRecord;
        return EdgeIndexKeyRunRecord.decodeSliceForHeader(header, run_bytes);
    }

    fn readEdgeIndexKeyRunForRecordAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, index: u64) !EdgeIndexKeyRunRecord {
        const run_index = try self.edgeIndexKeyRunIndexForRecordAt(file, header, index);
        const run = try self.readEdgeIndexKeyRunAt(file, header, run_index);
        if (run_index == 0 and run.start != 0) return error.InvalidRecord;
        if (run_index + 1 < header.key_run_count) {
            const next = try self.readEdgeIndexKeyRunAt(file, header, run_index + 1);
            try validateAdjacentEdgeIndexKeyRuns(header, run, next);
            if (index >= next.start) return error.InvalidRecord;
        }
        return run;
    }

    fn edgeIndexKeyRunIndexForRecordAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, index: u64) !u64 {
        if (!header.hasKeyRuns() or index >= header.edge_count) return error.InvalidRecord;
        var lo: u64 = 0;
        var hi: u64 = header.key_run_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const run = try self.readEdgeIndexKeyRunAt(file, header, mid);
            if (run.start <= index) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo == 0) return error.InvalidRecord;
        return lo - 1;
    }

    fn readEdgeIndexKeyRunFromMap(header: EdgeIndexHeader, map: *const std.Io.File.MemoryMap, run_index: u64) !EdgeIndexKeyRunRecord {
        if (!header.hasKeyRuns() or run_index >= header.key_run_count) return error.InvalidRecord;
        const dense_end = if (header.hasKeyRunDenseSpan())
            try std.math.add(u64, header.key_run_dense_run_start, header.key_run_dense_count)
        else
            0;
        if (header.hasKeyRunDenseSpan() and run_index >= header.key_run_dense_run_start and run_index < dense_end) {
            return edgeIndexDenseKeyRunSpanRecordForIndex(header, run_index);
        }
        const offset = try edgeIndexKeyRunOffsetForHeader(header, run_index);
        const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
        const end = std.math.add(usize, start, edgeIndexKeyRunRecordLen(header)) catch return error.InvalidRecord;
        if (end > map.memory.len) return error.InvalidRecord;
        return EdgeIndexKeyRunRecord.decodeSliceForHeader(header, map.memory[start..end]);
    }

    fn readEdgeIndexKeyRunForRecordFromMap(header: EdgeIndexHeader, map: *const std.Io.File.MemoryMap, index: u64) !EdgeIndexKeyRunRecord {
        const run_index = try edgeIndexKeyRunIndexForRecordFromMap(header, map, index);
        const run = try readEdgeIndexKeyRunFromMap(header, map, run_index);
        if (run_index == 0 and run.start != 0) return error.InvalidRecord;
        if (run_index + 1 < header.key_run_count) {
            const next = try readEdgeIndexKeyRunFromMap(header, map, run_index + 1);
            try validateAdjacentEdgeIndexKeyRuns(header, run, next);
            if (index >= next.start) return error.InvalidRecord;
        }
        return run;
    }

    fn edgeIndexKeyRunIndexForRecordFromMap(header: EdgeIndexHeader, map: *const std.Io.File.MemoryMap, index: u64) !u64 {
        if (!header.hasKeyRuns() or index >= header.edge_count) return error.InvalidRecord;
        var lo: u64 = 0;
        var hi: u64 = header.key_run_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const run = try readEdgeIndexKeyRunFromMap(header, map, mid);
            if (run.start <= index) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo == 0) return error.InvalidRecord;
        return lo - 1;
    }

    const EdgeIndexKeyRunBounds = struct {
        start: u64,
        end: u64,
    };

    fn edgeIndexKeyRunBoundsForKeyAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, key: u64) !?EdgeIndexKeyRunBounds {
        if (!header.hasKeyRuns()) return error.InvalidRecord;
        if (header.order == .id) return error.InvalidRecord;
        var lo: u64 = 0;
        var hi: u64 = header.key_run_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const run = try self.readEdgeIndexKeyRunAt(file, header, mid);
            if (run.key < key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= header.key_run_count) return null;
        const run = try self.readEdgeIndexKeyRunAt(file, header, lo);
        if (run.key != key) return null;
        if (lo == 0 and run.start != 0) return error.InvalidRecord;
        var last = run;
        var run_index = lo + 1;
        while (run_index < header.key_run_count) : (run_index += 1) {
            const next = try self.readEdgeIndexKeyRunAt(file, header, run_index);
            try validateAdjacentEdgeIndexKeyRuns(header, last, next);
            if (next.key != key) break;
            last = next;
        }
        const end = if (run_index < header.key_run_count) end: {
            const next = try self.readEdgeIndexKeyRunAt(file, header, run_index);
            break :end next.start;
        } else header.edge_count;
        return .{ .start = run.start, .end = end };
    }

    fn edgeIndexKeyRunBoundsForKeyFromMap(header: EdgeIndexHeader, map: *const std.Io.File.MemoryMap, key: u64) !?EdgeIndexKeyRunBounds {
        if (!header.hasKeyRuns()) return error.InvalidRecord;
        if (header.order == .id) return error.InvalidRecord;
        var lo: u64 = 0;
        var hi: u64 = header.key_run_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const run = try readEdgeIndexKeyRunFromMap(header, map, mid);
            if (run.key < key) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        if (lo >= header.key_run_count) return null;
        const run = try readEdgeIndexKeyRunFromMap(header, map, lo);
        if (run.key != key) return null;
        if (lo == 0 and run.start != 0) return error.InvalidRecord;
        var last = run;
        var run_index = lo + 1;
        while (run_index < header.key_run_count) : (run_index += 1) {
            const next = try readEdgeIndexKeyRunFromMap(header, map, run_index);
            try validateAdjacentEdgeIndexKeyRuns(header, last, next);
            if (next.key != key) break;
            last = next;
        }
        const end = if (run_index < header.key_run_count) end: {
            const next = try readEdgeIndexKeyRunFromMap(header, map, run_index);
            break :end next.start;
        } else header.edge_count;
        return .{ .start = run.start, .end = end };
    }

    const EdgeIndexSequentialRecordReader = struct {
        store: Store,
        file: std.Io.File,
        header: EdgeIndexHeader,
        run_index: u64 = 0,
        current_run: ?EdgeIndexKeyRunRecord = null,
        next_run: ?EdgeIndexKeyRunRecord = null,

        fn init(store: Store, file: std.Io.File, header: EdgeIndexHeader) !EdgeIndexSequentialRecordReader {
            var out = EdgeIndexSequentialRecordReader{
                .store = store,
                .file = file,
                .header = header,
            };
            if (header.hasKeyRuns()) {
                out.current_run = try store.readEdgeIndexKeyRunAt(file, header, 0);
                if (out.current_run.?.start != 0) return error.InvalidRecord;
                if (header.key_run_count > 1) {
                    out.next_run = try store.readEdgeIndexKeyRunAt(file, header, 1);
                    try validateAdjacentEdgeIndexKeyRuns(header, out.current_run.?, out.next_run.?);
                }
            }
            return out;
        }

        fn read(self: *EdgeIndexSequentialRecordReader, index: u64) !EdgeIndexRecord {
            if (!self.header.hasKeyRuns()) return self.store.readEdgeIndexRecordAt(self.file, self.header, index);
            if (index >= self.header.edge_count) return error.InvalidRecord;
            while (self.next_run) |next| {
                if (index < next.start) break;
                self.current_run = next;
                self.run_index += 1;
                if (self.run_index + 1 < self.header.key_run_count) {
                    self.next_run = try self.store.readEdgeIndexKeyRunAt(self.file, self.header, self.run_index + 1);
                    try validateAdjacentEdgeIndexKeyRuns(self.header, self.current_run.?, self.next_run.?);
                } else {
                    self.next_run = null;
                }
            }
            const run = self.current_run orelse return error.InvalidRecord;
            if (index < run.start) return error.InvalidRecord;

            var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
            const record_bytes = bytes[0..self.header.record_len];
            const offset = try edgeIndexRecordOffsetForHeader(self.header, index);
            const n = try self.file.readPositionalAll(self.store.io, record_bytes, offset);
            if (n != record_bytes.len) return error.InvalidRecord;
            return EdgeIndexRecord.decodeSliceAtForHeader(self.header, index, record_bytes, run);
        }
    };

    const ExplicitEdgeIndexSequentialReader = struct {
        allocator: std.mem.Allocator,
        io: std.Io,
        file: std.Io.File,
        header: EdgeIndexHeader,
        buffer: []u8,
        file_offset: u64,
        cursor: usize = 0,
        len: usize = 0,
        next_index: u64 = 0,

        fn init(allocator: std.mem.Allocator, io: std.Io, file: std.Io.File, header: EdgeIndexHeader) !ExplicitEdgeIndexSequentialReader {
            if (header.hasKeyRuns()) return error.InvalidRecord;
            const body_bytes = std.math.mul(u64, header.edge_count, header.record_len) catch return error.RecordTooLarge;
            const buffer = try allocator.alloc(u8, try storageWriteBufferCapacity(body_bytes));
            return .{
                .allocator = allocator,
                .io = io,
                .file = file,
                .header = header,
                .buffer = buffer,
                .file_offset = EdgeIndexHeader.encoded_len,
            };
        }

        fn deinit(self: *ExplicitEdgeIndexSequentialReader) void {
            self.allocator.free(self.buffer);
            self.buffer = &.{};
        }

        fn refill(self: *ExplicitEdgeIndexSequentialReader) !void {
            const n = try self.file.readPositionalAll(self.io, self.buffer, self.file_offset);
            if (n == 0) return error.InvalidRecord;
            self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
            self.cursor = 0;
            self.len = n;
        }

        fn readRecordBytes(self: *ExplicitEdgeIndexSequentialReader, out: []u8) !void {
            var written: usize = 0;
            while (written < out.len) {
                if (self.cursor == self.len) try self.refill();
                const available = self.len - self.cursor;
                const take = @min(available, out.len - written);
                @memcpy(out[written .. written + take], self.buffer[self.cursor .. self.cursor + take]);
                self.cursor += take;
                written += take;
            }
        }

        fn next(self: *ExplicitEdgeIndexSequentialReader) !?EdgeIndexRecord {
            if (self.next_index >= self.header.edge_count) return null;
            var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
            const encoded = bytes[0..self.header.record_len];
            try self.readRecordBytes(encoded);
            const record = try EdgeIndexRecord.decodeSliceAtForHeader(self.header, self.next_index, encoded, null);
            self.next_index += 1;
            return record;
        }
    };

    fn readEdgeTombstoneRecordFromMap(map: *const std.Io.File.MemoryMap, index: u64) !EdgeTombstoneRecord {
        const offset = try edgeTombstoneRecordOffset(index);
        const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
        const end = std.math.add(usize, start, EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
        if (end > map.memory.len) return error.InvalidRecord;
        return EdgeTombstoneRecord.decodeSlice(map.memory[start..end]);
    }

    fn openReadOnlyMemoryMap(io: std.Io, file: std.Io.File, file_size: u64) !std.Io.File.MemoryMap {
        const len = std.math.cast(usize, file_size) orelse return error.RecordTooLarge;
        return read_only_memory_map.create(io, file, len);
    }

    fn readAllEdgeIndexRecords(self: Store, allocator: std.mem.Allocator, path: []const u8, order: EdgeIndexOrder) !std.ArrayList(EdgeIndexRecord) {
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var out = std.ArrayList(EdgeIndexRecord).empty;
        errdefer out.deinit(allocator);
        var reader = try EdgeIndexSequentialRecordReader.init(self, file, header);
        var pos: u64 = 0;
        while (pos < header.edge_count) : (pos += 1) {
            try out.append(allocator, try reader.read(pos));
        }
        return out;
    }

    fn openEdgeIndexRecordReader(self: Store, path: []const u8, order: EdgeIndexOrder, meta: IndexMeta) !EdgeIndexRecordReader {
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        errdefer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order) return error.InvalidRecord;
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, order)) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var map = openReadOnlyMemoryMap(self.io, file, expected_size) catch null;
        errdefer if (map) |*mapped| mapped.destroy(self.io);
        return .{
            .store = self,
            .file = file,
            .map = map,
            .header = header,
            .edge_count = header.edge_count,
        };
    }

    pub fn publishEdgeAdjacencySegment(self: Store, segment_dir_path: []const u8) !u64 {
        const meta = try self.readCurrentIndexMeta();
        if (!try self.edgeIndexesMatchMeta(meta)) return error.InvalidRecord;

        var segment = try segment_mod.ImmutableAdjacencySegment.initEmpty(self.allocator, self.io, segment_dir_path);
        errdefer segment.deinit();

        const forward_summary = blk: {
            var reader = try self.openEdgeIndexRecordReader(self.edge_by_src_path, .src, meta);
            defer reader.deinit();
            break :blk try segment.writeOrderedRecordReaderSummary(.forward, reader.edge_count, &reader, edgeIndexReaderRecordToSegmentEdge);
        };

        const reverse_summary = blk: {
            var reader = try self.openEdgeIndexRecordReader(self.edge_by_dst_path, .dst, meta);
            defer reader.deinit();
            break :blk try segment.writeOrderedRecordReaderSummary(.reverse, reader.edge_count, &reader, edgeIndexReaderRecordToSegmentEdge);
        };
        const written_summary = try segment_mod.ImmutableAdjacencySegment.summarizeWrittenEdgeStreams(forward_summary, reverse_summary);
        const edge_id_summary = written_summary.edge_id_summary;
        const endpoint_summary = written_summary.endpoint_summary;
        const edge_id_index = blk: {
            var reader = try self.openEdgeIndexRecordReader(self.edge_by_id_path, .id, meta);
            defer reader.deinit();
            break :blk try self.writeEdgeSegmentIdIndexFromEdgeIndexReader(segment_dir_path, &reader, edge_id_summary);
        };
        const manifest_summary = try self.writeEdgeSegmentManifest(segment_dir_path, written_summary.edge_digest, edge_id_summary, endpoint_summary, edge_id_index.edge_id_order_digest, edge_id_index.edge_id_runs);
        var next_meta = meta;
        setEdgeSegmentSummary(&next_meta, manifest_summary);
        try self.writeIndexMeta(next_meta);
        segment.deinit();
        return meta.edge_indexed_edges;
    }

    pub fn publishSegmentBundle(self: Store, root_dir: []const u8) !void {
        const meta = try self.readCurrentIndexMeta();
        if (meta.nodes == 0 or meta.edges == 0) return error.InvalidRecord;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        if (!try self.nodeTextIndexMatchesMeta(meta)) return error.InvalidRecord;
        if (!try self.edgeIndexBaseHeadersMatchMeta(meta)) return error.InvalidRecord;
        const expected_physical_edges = std.math.add(u64, meta.edges, tombstone_header.count) catch return error.InvalidRecord;
        const wal_checkpoint_bytes = try self.eventBytes();
        if (try self.segmentBundleMatchesCurrent(root_dir, meta, wal_checkpoint_bytes)) return;
        var reusable_node_snapshot = try self.pinSegmentBundleSnapshotWithReusableNode(root_dir, meta);
        defer if (reusable_node_snapshot) |*snapshot| snapshot.deinit(self.allocator);
        const reusable_node_entry: ?segment_manifest.Entry = if (reusable_node_snapshot) |snapshot|
            try segmentManifestUniqueEntry(snapshot, .node)
        else
            null;

        try std.Io.Dir.cwd().createDirPath(self.io, root_dir);
        if (reusable_node_snapshot) |snapshot| {
            if (try self.publishSegmentBundleEdgeDeltaIfPossible(root_dir, meta, wal_checkpoint_bytes, snapshot)) return;
        }

        var tombstones: ?EdgeTombstoneIndexView = null;
        defer if (tombstones) |*view| view.deinit();
        if (tombstone_header.count != 0) tombstones = try EdgeTombstoneIndexView.open(self);
        const tombstone_view = if (tombstones) |*view| view else null;

        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => EdgeSegmentManifest{},
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        const manifest_edges = manifest.totalEdgeCount();
        var covered_physical_edges: ?u64 = null;
        const use_base_indexes = if (manifest_edges == 0) true else blk: {
            covered_physical_edges = try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges);
            if (covered_physical_edges == null) {
                if (!try self.edgeIndexesMatchMeta(meta)) return error.InvalidRecord;
                break :blk true;
            }
            break :blk false;
        };
        if (use_base_indexes) {
            if (!try self.edgeIndexesMatchMeta(meta)) return error.InvalidRecord;
            var forward_reader = try self.openEdgeIndexRecordReader(self.edge_by_src_path, .src, meta);
            defer forward_reader.deinit();
            var reverse_reader = try self.openEdgeIndexRecordReader(self.edge_by_dst_path, .dst, meta);
            defer reverse_reader.deinit();
            if (tombstone_view == null and meta.edge_indexed_edges == meta.edges) {
                return try self.publishSegmentBundleEdgeReaders(
                    root_dir,
                    meta,
                    wal_checkpoint_bytes,
                    reusable_node_entry,
                    &forward_reader,
                    edgeIndexReaderRecordToSegmentEdge,
                    &reverse_reader,
                    edgeIndexReaderRecordToSegmentEdge,
                );
            }
            var forward_stream = StoreEdgeRecordStream{ .reader = &forward_reader, .tombstones = tombstone_view };
            var reverse_stream = StoreEdgeRecordStream{ .reader = &reverse_reader, .tombstones = tombstone_view };
            return try self.publishSegmentBundleEdgeStreams(
                root_dir,
                meta,
                wal_checkpoint_bytes,
                reusable_node_entry,
                &forward_stream,
                StoreEdgeRecordStream.reset,
                StoreEdgeRecordStream.next,
                &reverse_stream,
                StoreEdgeRecordStream.reset,
                StoreEdgeRecordStream.next,
            );
        }

        const physical_edges = covered_physical_edges.?;
        if (physical_edges != expected_physical_edges) return error.InvalidRecord;
        var segments = try PublishedEdgeSegments.openFromManifest(self.allocator, self.io, manifest.entries.items);
        defer segments.deinit();
        const physical_digest = meta.edge_digest ^ tombstone_header.digest;
        const segment_digest = try segments.edgeDigest();
        if (manifest_edges == physical_edges) {
            if (segment_digest != physical_digest) return error.InvalidRecord;
        } else if ((meta.edge_index_digest ^ segment_digest) != physical_digest) return error.InvalidRecord;
        if (manifest_edges == physical_edges) {
            var forward_stream = EdgeSegmentMergeStream.initWithVirtualFiltered(self.allocator, &segments.segments, &segments.virtual_edges, .forward, tombstone_view);
            defer forward_stream.deinit();
            var reverse_stream = EdgeSegmentMergeStream.initWithVirtualFiltered(self.allocator, &segments.segments, &segments.virtual_edges, .reverse, tombstone_view);
            defer reverse_stream.deinit();
            return try self.publishSegmentBundleEdgeStreams(
                root_dir,
                meta,
                wal_checkpoint_bytes,
                reusable_node_entry,
                &forward_stream,
                EdgeSegmentMergeStream.reset,
                EdgeSegmentMergeStream.next,
                &reverse_stream,
                EdgeSegmentMergeStream.reset,
                EdgeSegmentMergeStream.next,
            );
        }

        var forward_reader = try self.openEdgeIndexRecordReader(self.edge_by_src_path, .src, meta);
        defer forward_reader.deinit();
        var reverse_reader = try self.openEdgeIndexRecordReader(self.edge_by_dst_path, .dst, meta);
        defer reverse_reader.deinit();
        var forward_stream = BaseAndSegmentMergeStream.initWithVirtualFiltered(self.allocator, &forward_reader, &segments.segments, &segments.virtual_edges, .forward, tombstone_view);
        defer forward_stream.deinit();
        var reverse_stream = BaseAndSegmentMergeStream.initWithVirtualFiltered(self.allocator, &reverse_reader, &segments.segments, &segments.virtual_edges, .reverse, tombstone_view);
        defer reverse_stream.deinit();
        try self.publishSegmentBundleEdgeStreams(
            root_dir,
            meta,
            wal_checkpoint_bytes,
            reusable_node_entry,
            &forward_stream,
            BaseAndSegmentMergeStream.reset,
            BaseAndSegmentMergeStream.next,
            &reverse_stream,
            BaseAndSegmentMergeStream.reset,
            BaseAndSegmentMergeStream.next,
        );
    }

    fn publishSegmentBundleEdgeStreams(
        self: Store,
        root_dir: []const u8,
        meta: IndexMeta,
        wal_checkpoint_bytes: u64,
        reusable_node_entry: ?segment_manifest.Entry,
        forward_context: anytype,
        comptime forward_reset: fn (@TypeOf(forward_context)) anyerror!void,
        comptime forward_next: fn (@TypeOf(forward_context)) anyerror!?segment_mod.EdgeRecord,
        reverse_context: anytype,
        comptime reverse_reset: fn (@TypeOf(reverse_context)) anyerror!void,
        comptime reverse_next: fn (@TypeOf(reverse_context)) anyerror!?segment_mod.EdgeRecord,
    ) !void {
        if (reusable_node_entry) |node_entry| {
            return try segment_bundle.publishTrustedOrderedEdgeStreamsWithNodeEntry(
                self.allocator,
                self.io,
                root_dir,
                node_entry,
                meta.edges,
                wal_checkpoint_bytes,
                forward_context,
                forward_reset,
                forward_next,
                reverse_context,
                reverse_reset,
                reverse_next,
            );
        }

        var texts_stream = try StoreTextsFileStream.init(self.allocator, self);
        defer texts_stream.deinit();
        var by_id_stream = try StoreCatalogByIdStream.init(self, meta);
        defer by_id_stream.deinit();
        var exact_runs = try StoreSegmentBundleExactRuns.build(self, root_dir, meta);
        defer exact_runs.deinit();
        var exact_stream = StoreSegmentBundleExactStream.init(self.allocator, self, exact_runs.paths.items);
        defer exact_stream.deinit();
        try segment_bundle.publishTrustedOrderedCatalogAndEdgeStreams(
            self.allocator,
            self.io,
            root_dir,
            meta.nodes,
            meta.node_digest,
            &texts_stream,
            StoreTextsFileStream.reset,
            StoreTextsFileStream.next,
            &by_id_stream,
            StoreCatalogByIdStream.reset,
            StoreCatalogByIdStream.next,
            &exact_stream,
            StoreSegmentBundleExactStream.reset,
            StoreSegmentBundleExactStream.next,
            meta.edges,
            wal_checkpoint_bytes,
            forward_context,
            forward_reset,
            forward_next,
            reverse_context,
            reverse_reset,
            reverse_next,
        );
    }

    fn publishSegmentBundleEdgeReaders(
        self: Store,
        root_dir: []const u8,
        meta: IndexMeta,
        wal_checkpoint_bytes: u64,
        reusable_node_entry: ?segment_manifest.Entry,
        forward_context: anytype,
        comptime forward_read: fn (@TypeOf(forward_context), u64) anyerror!segment_mod.EdgeRecord,
        reverse_context: anytype,
        comptime reverse_read: fn (@TypeOf(reverse_context), u64) anyerror!segment_mod.EdgeRecord,
    ) !void {
        if (reusable_node_entry) |node_entry| {
            return try segment_bundle.publishTrustedOrderedEdgeReadersWithNodeEntry(
                self.allocator,
                self.io,
                root_dir,
                node_entry,
                meta.edges,
                wal_checkpoint_bytes,
                forward_context,
                forward_read,
                reverse_context,
                reverse_read,
            );
        }

        var texts_stream = try StoreTextsFileStream.init(self.allocator, self);
        defer texts_stream.deinit();
        var by_id_stream = try StoreCatalogByIdStream.init(self, meta);
        defer by_id_stream.deinit();
        var exact_runs = try StoreSegmentBundleExactRuns.build(self, root_dir, meta);
        defer exact_runs.deinit();
        var exact_stream = StoreSegmentBundleExactStream.init(self.allocator, self, exact_runs.paths.items);
        defer exact_stream.deinit();
        try segment_bundle.publishTrustedOrderedCatalogAndEdgeReaders(
            self.allocator,
            self.io,
            root_dir,
            meta.nodes,
            meta.node_digest,
            &texts_stream,
            StoreTextsFileStream.reset,
            StoreTextsFileStream.next,
            &by_id_stream,
            StoreCatalogByIdStream.reset,
            StoreCatalogByIdStream.next,
            &exact_stream,
            StoreSegmentBundleExactStream.reset,
            StoreSegmentBundleExactStream.next,
            meta.edges,
            wal_checkpoint_bytes,
            forward_context,
            forward_read,
            reverse_context,
            reverse_read,
        );
    }

    fn segmentBundleMatchesCurrent(self: Store, root_dir: []const u8, meta: IndexMeta, wal_checkpoint_bytes: u64) !bool {
        if (meta.event_bytes != wal_checkpoint_bytes) return false;

        const manifest_dir = try std.fs.path.join(self.allocator, &.{ root_dir, segment_bundle.manifest_leaf });
        defer self.allocator.free(manifest_dir);

        var manifest_store = try segment_manifest.Store.init(self.allocator, self.io, manifest_dir);
        defer manifest_store.deinit();
        var snapshot = manifest_store.pinCurrent() catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer snapshot.deinit(self.allocator);

        if (snapshot.wal_checkpoint_bytes != wal_checkpoint_bytes) return false;

        var node_seen = false;
        var edge_seen = false;
        var edge_count: u64 = 0;
        var edge_digest: u64 = 0;
        for (snapshot.entries.items) |entry| switch (entry.kind) {
            .node => {
                if (node_seen) return false;
                if (entry.node_count != meta.nodes) return false;
                if (entry.node_digest != meta.node_digest) return false;
                const summary = entry.node_catalog_summary orelse return false;
                if (summary.node_count != meta.nodes) return false;
                node_seen = true;
            },
            .edge => {
                edge_count = std.math.add(u64, edge_count, entry.edge_count) catch return false;
                edge_digest ^= entry.segment_digest;
                edge_seen = true;
            },
            else => return false,
        };
        return node_seen and edge_seen and edge_count == meta.edges and edge_digest == meta.edge_digest;
    }

    fn pinSegmentBundleSnapshotWithReusableNode(self: Store, root_dir: []const u8, meta: IndexMeta) !?segment_manifest.Snapshot {
        const manifest_dir = try std.fs.path.join(self.allocator, &.{ root_dir, segment_bundle.manifest_leaf });
        defer self.allocator.free(manifest_dir);

        var manifest_store = try segment_manifest.Store.init(self.allocator, self.io, manifest_dir);
        defer manifest_store.deinit();
        var snapshot = manifest_store.pinCurrent() catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        errdefer snapshot.deinit(self.allocator);

        const node_entry = segmentManifestUniqueEntry(snapshot, .node) catch |err| switch (err) {
            error.InvalidRecord => {
                snapshot.deinit(self.allocator);
                return null;
            },
            else => |e| return e,
        };
        if (!segmentManifestHasEdgeEntry(snapshot)) {
            snapshot.deinit(self.allocator);
            return null;
        }
        if (node_entry.node_count != meta.nodes or node_entry.node_digest != meta.node_digest) {
            snapshot.deinit(self.allocator);
            return null;
        }
        const summary = node_entry.node_catalog_summary orelse {
            snapshot.deinit(self.allocator);
            return null;
        };
        if (summary.node_count != meta.nodes) {
            snapshot.deinit(self.allocator);
            return null;
        }
        var catalog = segment_node_index.openTrustedFromManifestEntry(self.allocator, self.io, root_dir, node_entry) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                snapshot.deinit(self.allocator);
                return null;
            },
            else => |e| return e,
        };
        catalog.deinit();
        return snapshot;
    }

    fn publishSegmentBundleEdgeDeltaIfPossible(
        self: Store,
        root_dir: []const u8,
        meta: IndexMeta,
        wal_checkpoint_bytes: u64,
        snapshot: segment_manifest.Snapshot,
    ) !bool {
        if (snapshot.wal_checkpoint_bytes >= wal_checkpoint_bytes) return false;

        const node_entry = segmentManifestUniqueEntry(snapshot, .node) catch |err| switch (err) {
            error.InvalidRecord => return false,
        };
        const existing_edge_entries = segmentManifestEdgeEntries(self.allocator, snapshot) catch |err| switch (err) {
            error.InvalidRecord => return false,
            else => |e| return e,
        };
        defer self.allocator.free(existing_edge_entries);
        const compact_threshold = self.options.auto_compact_edge_segment_entries;
        if (compact_threshold != 0 and existing_edge_entries.len >= compact_threshold) return false;

        var tail = try self.readEdgeAppendTailSpool(snapshot.wal_checkpoint_bytes, wal_checkpoint_bytes);
        defer tail.deinit(self);
        if (tail.count == 0) return false;
        if (tail.count > meta.edges) return false;

        const old_edge_count = std.math.sub(u64, meta.edges, @intCast(tail.count)) catch return false;
        if (try segmentManifestEdgeCount(existing_edge_entries) != old_edge_count) return false;
        if (segmentManifestEdgeDigest(existing_edge_entries) != (meta.edge_digest ^ tail.digest)) return false;

        if (tail.count <= edge_repair_sort_chunk_records) {
            var forward_records = std.ArrayList(EdgeIndexRecord).empty;
            defer forward_records.deinit(self.allocator);
            var reverse_order = std.ArrayList(u32).empty;
            defer reverse_order.deinit(self.allocator);
            try self.readEdgeTailSortedChunksFromSpool(tail.path.?, tail.count, &forward_records, &reverse_order);

            var forward_stream = EdgeSortedRecordSliceStream.init(forward_records.items);
            var reverse_stream = EdgeSortedRecordOrderStream.init(forward_records.items, reverse_order.items);
            try segment_bundle.publishEdgeDeltaWithExistingEntriesStreams(
                self.allocator,
                self.io,
                root_dir,
                node_entry,
                existing_edge_entries,
                @intCast(tail.count),
                wal_checkpoint_bytes,
                &forward_stream,
                EdgeSortedRecordSliceStream.reset,
                EdgeSortedRecordSliceStream.next,
                &reverse_stream,
                EdgeSortedRecordOrderStream.reset,
                EdgeSortedRecordOrderStream.next,
            );
            return true;
        }

        var forward_runs = try self.buildEdgeSortedRunsFromSpool(root_dir, "forward", .src, tail.path.?, tail.count, tail.nonce);
        defer forward_runs.deinit();
        var reverse_runs = try self.buildEdgeSortedRunsFromSpool(root_dir, "reverse", .dst, tail.path.?, tail.count, tail.nonce);
        defer reverse_runs.deinit();
        var forward_stream = EdgeSortedRunStream.init(self.allocator, self, .src, forward_runs.paths.items);
        defer forward_stream.deinit();
        var reverse_stream = EdgeSortedRunStream.init(self.allocator, self, .dst, reverse_runs.paths.items);
        defer reverse_stream.deinit();
        try segment_bundle.publishEdgeDeltaWithExistingEntriesStreams(
            self.allocator,
            self.io,
            root_dir,
            node_entry,
            existing_edge_entries,
            @intCast(tail.count),
            wal_checkpoint_bytes,
            &forward_stream,
            EdgeSortedRunStream.reset,
            EdgeSortedRunStream.next,
            &reverse_stream,
            EdgeSortedRunStream.reset,
            EdgeSortedRunStream.next,
        );
        return true;
    }

    const EdgeAppendTailSpool = struct {
        path: ?[]u8 = null,
        count: usize = 0,
        digest: u64 = 0,
        nonce: u64 = 0,

        fn deinit(self: *EdgeAppendTailSpool, store: Store) void {
            if (self.path) |path| {
                std.Io.Dir.cwd().deleteFile(store.io, path) catch {};
                store.allocator.free(path);
                self.path = null;
            }
            self.count = 0;
            self.digest = 0;
            self.nonce = 0;
        }
    };

    fn readEdgeAppendTailSpool(self: Store, checkpoint_bytes: u64, end_bytes: u64) !EdgeAppendTailSpool {
        if (checkpoint_bytes >= end_bytes) return .{};

        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (end_bytes > file_size or checkpoint_bytes > end_bytes) return error.InvalidRecord;

        const pid = currentProcessIdForTempPath();
        const nonce = store_temp_nonce.fetchAdd(1, .monotonic);
        const spool_path = try std.fmt.allocPrint(self.allocator, "{s}.edge_tail.{d}.{d}.{d}.{d}.spool.tmp", .{
            self.events_bin_path,
            checkpoint_bytes,
            end_bytes,
            pid,
            nonce,
        });
        var keep_spool_path = false;
        defer if (!keep_spool_path) {
            std.Io.Dir.cwd().deleteFile(self.io, spool_path) catch {};
            self.allocator.free(spool_path);
        };

        var spool_file = try std.Io.Dir.cwd().createFile(self.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer spool_file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, spool_file, storage_write_buffer_bytes);
        defer writer.deinit();

        var offset = checkpoint_bytes;
        var in_batch = false;
        var count: usize = 0;
        var digest: u64 = 0;
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        while (offset < end_bytes) {
            const parsed = try self.readBinaryRecordHeader(file, &offset) orelse return error.InvalidRecord;
            try ensureBinaryPayloadFits(file_size, offset, parsed.payload_len);
            if (@as(u64, parsed.payload_len) > end_bytes - offset) return error.InvalidRecord;
            switch (parsed.kind) {
                .batch_begin => {
                    if (in_batch or parsed.payload_len != 0) {
                        return .{};
                    }
                    try validateBinaryChecksumValue(parsed, binaryPayloadChecksum(&.{}));
                    in_batch = true;
                },
                .batch_commit => {
                    if (!in_batch or parsed.payload_len != 0) {
                        return .{};
                    }
                    try validateBinaryChecksumValue(parsed, binaryPayloadChecksum(&.{}));
                    in_batch = false;
                },
                .edge => {
                    if (parsed.payload_len != binary_edge_payload_len) {
                        return .{};
                    }
                    var payload: [binary_edge_payload_len]u8 = undefined;
                    const read_len = try file.readPositionalAll(self.io, &payload, offset);
                    if (read_len != payload.len) return error.InvalidRecord;
                    try validateBinaryChecksum(parsed, &payload);
                    const parsed_edge = try validateBinaryEdgePayload(&payload);
                    const record = EdgeIndexRecord{
                        .src = parsed_edge.src,
                        .dst = parsed_edge.dst,
                        .edge_id = parsed_edge.id,
                        .rel = @intFromEnum(parsed_edge.rel),
                    };
                    record.encode(&record_bytes);
                    try writer.append(&record_bytes);
                    count = std.math.add(usize, count, 1) catch return error.RecordTooLarge;
                    digest ^= edgeRecordDigest(record);
                },
                .edge_batch => {
                    if (!in_batch) return .{};
                    const payload = try self.readBinaryPayloadAllocAndValidateChecksum(file, offset, parsed);
                    defer self.allocator.free(payload);
                    const batch = try validateBinaryEdgeBatchHeader(payload);
                    var index: u32 = 0;
                    while (index < batch.count) : (index += 1) {
                        const parsed_edge = try validateBinaryEdgeBatchEdge(payload, batch, index);
                        const record = EdgeIndexRecord{
                            .src = parsed_edge.src,
                            .dst = parsed_edge.dst,
                            .edge_id = parsed_edge.id,
                            .rel = @intFromEnum(parsed_edge.rel),
                        };
                        record.encode(&record_bytes);
                        try writer.append(&record_bytes);
                        count = std.math.add(usize, count, 1) catch return error.RecordTooLarge;
                        digest ^= edgeRecordDigest(record);
                    }
                },
                .node, .node_batch, .edge_delete => {
                    return .{};
                },
            }
            try advanceBinaryOffset(&offset, parsed.payload_len);
        }
        if (offset != end_bytes or in_batch) {
            return .{};
        }
        if (count == 0) return .{};

        try writer.flush();
        const expected_size = std.math.mul(u64, @intCast(count), EdgeIndexRecord.encoded_len) catch return error.RecordTooLarge;
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try spool_file.sync(self.io);

        keep_spool_path = true;
        return .{
            .path = spool_path,
            .count = count,
            .digest = digest,
            .nonce = nonce,
        };
    }

    const EdgeSortedRunSet = struct {
        allocator: std.mem.Allocator,
        store: Store,
        paths: std.ArrayList([]u8) = .empty,

        fn deinit(self: *EdgeSortedRunSet) void {
            for (self.paths.items) |path| {
                std.Io.Dir.cwd().deleteFile(self.store.io, path) catch {};
                self.allocator.free(path);
            }
            self.paths.deinit(self.allocator);
        }
    };

    fn readEdgeTailSortedChunksFromSpool(
        self: Store,
        spool_path: []const u8,
        record_count: usize,
        forward_records: *std.ArrayList(EdgeIndexRecord),
        reverse_order: *std.ArrayList(u32),
    ) !void {
        if (record_count == 0 or record_count > edge_repair_sort_chunk_records) return error.InvalidRecord;
        if (record_count > std.math.maxInt(u32)) return error.InvalidRecord;
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        try forward_records.ensureTotalCapacityPrecise(self.allocator, record_count);
        try reverse_order.ensureTotalCapacityPrecise(self.allocator, record_count);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, record_count, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord);
        defer self.allocator.free(chunk_bytes);

        try self.readEdgeRepairSpoolChunk(spool_file, 0, record_count, chunk_bytes, forward_records);
        sortEdgeIndexRecords(.src, forward_records.items);
        try validateSortedRepairEdgeRecords(.src, forward_records.items);
        for (forward_records.items, 0..) |_, index| reverse_order.appendAssumeCapacity(@intCast(index));
        sortEdgeIndexRecordOrder(.dst, forward_records.items, reverse_order.items);
        try validateSortedRepairEdgeRecordOrder(.dst, forward_records.items, reverse_order.items);
    }

    fn buildEdgeSortedRunsFromSpool(
        self: Store,
        root_dir: []const u8,
        label: []const u8,
        order: EdgeIndexOrder,
        spool_path: []const u8,
        record_count: usize,
        nonce: u64,
    ) !EdgeSortedRunSet {
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var runs = EdgeSortedRunSet{ .allocator = self.allocator, .store = self };
        errdefer runs.deinit();

        var chunk = std.ArrayList(EdgeIndexRecord).empty;
        defer chunk.deinit(self.allocator);
        const max_chunk_records = @min(record_count, edge_repair_sort_chunk_records);
        try chunk.ensureTotalCapacityPrecise(self.allocator, max_chunk_records);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, max_chunk_records, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord);
        defer self.allocator.free(chunk_bytes);

        var read_pos: usize = 0;
        while (read_pos < record_count) {
            chunk.clearRetainingCapacity();
            const take = @min(edge_repair_sort_chunk_records, record_count - read_pos);
            try self.readEdgeRepairSpoolChunk(spool_file, read_pos, take, chunk_bytes, &chunk);
            sortEdgeIndexRecords(order, chunk.items);
            const pid = currentProcessIdForTempPath();
            const run_path = try std.fmt.allocPrint(self.allocator, "{s}/.edge-tail-{s}-{c}-{d}-{d}-{d}.tmp", .{
                root_dir,
                label,
                @intFromEnum(order),
                pid,
                nonce,
                runs.paths.items.len,
            });
            var run_path_owned = true;
            errdefer {
                std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
                if (run_path_owned) self.allocator.free(run_path);
            }
            try self.writeRepairEdgeRun(run_path, chunk.items);
            try runs.paths.append(self.allocator, run_path);
            run_path_owned = false;
            read_pos += take;
        }
        if (runs.paths.items.len == 0) return error.InvalidRecord;
        return runs;
    }

    fn publishEdgeBatchSegmentIfManifestCurrent(self: Store, old_meta: IndexMeta, next_meta: *IndexMeta, batch_records: []EdgeIndexRecord) !void {
        if (batch_records.len == 0) return;
        const manifest_read_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        var manifest_found = true;
        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => blk: {
                manifest_found = false;
                break :blk EdgeSegmentManifest{};
            },
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.segment_publish_manifest_read_ns += storageElapsedNs(self.io, manifest_read_start);
        }
        if (!manifest_found and (next_meta.edge_indexed_edges != old_meta.edge_indexed_edges or old_meta.edge_indexed_edges < implicit_edge_delta_segment_min_base_edges)) return;
        if (try self.edgeSegmentManifestCoveredPhysicalEdges(old_meta, manifest.totalEdgeCount()) == null) return;

        const publish_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        if (batch_records.len == 1) {
            const record = batch_records[0];
            const edge_id = record.edge_id;
            const rel = try record.relKind();
            var entries = std.ArrayList(EdgeSegmentManifestEntry).empty;
            defer entries.deinit(self.allocator);
            try entries.ensureTotalCapacity(self.allocator, manifest.entries.items.len + 1);
            for (manifest.entries.items) |entry| {
                entries.appendAssumeCapacity(.{
                    .edge_count = entry.edge_count,
                    .edge_digest = entry.edge_digest,
                    .edge_id_range = entry.edge_id_range,
                    .edge_id_digest = entry.edge_id_digest,
                    .edge_id_order_digest = entry.edge_id_order_digest,
                    .edge_id_runs = entry.edge_id_runs,
                    .src_node_range = entry.src_node_range,
                    .dst_node_range = entry.dst_node_range,
                    .singleton_rel = entry.singleton_rel,
                    .path = entry.path,
                });
            }
            const new_entry = EdgeSegmentManifestEntry{
                .edge_count = 1,
                .edge_digest = edgeRecordDigest(record),
                .edge_id_range = .{ .min = edge_id, .max = edge_id },
                .edge_id_digest = edgeSegmentIdDigest(edge_id),
                .edge_id_runs = .{ .run_count = 1, .first_min = edge_id, .first_max = edge_id },
                .src_node_range = .{ .min = record.src, .max = record.src },
                .dst_node_range = .{ .min = record.dst, .max = record.dst },
                .singleton_rel = rel,
                .path = "",
            };
            if (entries.items.len == 0 or !try extendVirtualEdgeRun(&entries.items[entries.items.len - 1], new_entry)) {
                entries.appendAssumeCapacity(new_entry);
            }
            const manifest_write_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
            try self.writeEdgeSegmentManifestEntries(entries.items);
            setEdgeSegmentSummary(next_meta, try self.edgeSegmentManifestSummary(entries.items));
            if (self.edge_batch_segment_delta_stats) |delta_stats| {
                delta_stats.segment_publish_manifest_write_ns += storageElapsedNs(self.io, manifest_write_start);
                delta_stats.segment_publish_batches += 1;
                delta_stats.segment_publish_edges += 1;
                delta_stats.segment_publish_ns += storageElapsedNs(self.io, publish_start);
            }
            return;
        }
        const segment_path = try self.edgeBatchSegmentPath(old_meta, next_meta.*);
        defer self.allocator.free(segment_path);
        if (try self.pathExists(segment_path)) return error.AlreadyExists;
        var segment_unpublished = true;
        errdefer if (segment_unpublished) std.Io.Dir.cwd().deleteTree(self.io, segment_path) catch {};
        const segment_write_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        const batch_edge_id_index = try self.writeEdgeBatchSegment(segment_path, batch_records);
        if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.segment_publish_segment_write_ns += storageElapsedNs(self.io, segment_write_start);
        }

        var entries = std.ArrayList(EdgeSegmentManifestEntry).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, manifest.entries.items.len + 1);
        for (manifest.entries.items) |entry| {
            entries.appendAssumeCapacity(.{
                .edge_count = entry.edge_count,
                .edge_digest = entry.edge_digest,
                .edge_id_range = entry.edge_id_range,
                .edge_id_digest = entry.edge_id_digest,
                .edge_id_order_digest = entry.edge_id_order_digest,
                .edge_id_runs = entry.edge_id_runs,
                .src_node_range = entry.src_node_range,
                .dst_node_range = entry.dst_node_range,
                .singleton_rel = entry.singleton_rel,
                .path = entry.path,
            });
        }
        entries.appendAssumeCapacity(.{
            .edge_count = @intCast(batch_records.len),
            .edge_digest = batch_edge_id_index.edge_digest,
            .edge_id_range = batch_edge_id_index.edge_id_summary.range,
            .edge_id_digest = batch_edge_id_index.edge_id_summary.digest,
            .edge_id_order_digest = batch_edge_id_index.edge_id_order_digest,
            .edge_id_runs = batch_edge_id_index.edge_id_runs,
            .src_node_range = batch_edge_id_index.endpoint_summary.src_range,
            .dst_node_range = batch_edge_id_index.endpoint_summary.dst_range,
            .path = segment_path,
        });
        const manifest_write_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        // The CURRENT rename is an irreversible commit point. From here on,
        // preserve the segment on every error; an unreferenced segment can be
        // collected later, while deleting a possibly referenced one corrupts
        // the published manifest.
        segment_unpublished = false;
        try self.writeEdgeSegmentManifestEntries(entries.items);
        setEdgeSegmentSummary(next_meta, try self.edgeSegmentManifestSummary(entries.items));
        if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.segment_publish_manifest_write_ns += storageElapsedNs(self.io, manifest_write_start);
        }
        if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.segment_publish_batches += 1;
            delta_stats.segment_publish_edges += @intCast(batch_records.len);
            delta_stats.segment_publish_ns += storageElapsedNs(self.io, publish_start);
        }
    }

    fn edgeBatchSegmentPath(self: Store, old_meta: IndexMeta, next_meta: IndexMeta) ![]u8 {
        const parent = try std.fs.path.join(self.allocator, &.{ self.dir_path, "edge_segments" });
        defer self.allocator.free(parent);
        try std.Io.Dir.cwd().createDirPath(self.io, parent);
        const leaf = try std.fmt.allocPrint(self.allocator, "l0-{}-{}-{}", .{ old_meta.edge_indexed_edges, next_meta.edge_indexed_edges, next_meta.event_bytes });
        defer self.allocator.free(leaf);
        return try std.fs.path.join(self.allocator, &.{ parent, leaf });
    }

    const EdgeSegmentIdIndexSummary = struct {
        edge_digest: u64,
        edge_id_summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
        endpoint_summary: segment_mod.ImmutableAdjacencySegment.EndpointSummary,
        edge_id_order_digest: u64,
        edge_id_runs: EdgeSegmentIdRunSummary,
    };

    fn writeEdgeBatchSegment(self: Store, segment_dir_path: []const u8, batch_records: []EdgeIndexRecord) !EdgeSegmentIdIndexSummary {
        var segment = try segment_mod.ImmutableAdjacencySegment.initEmpty(self.allocator, self.io, segment_dir_path);
        errdefer segment.deinit();

        sortEdgeIndexRecords(.src, batch_records);
        const forward_summary = try segment.writeOrderedRecordsSummary(.forward, EdgeIndexRecord, batch_records, edgeIndexRecordToSegmentEdge);
        sortEdgeIndexRecords(.dst, batch_records);
        const reverse_summary = try segment.writeOrderedRecordsSummary(.reverse, EdgeIndexRecord, batch_records, edgeIndexRecordToSegmentEdge);

        const written_summary = try segment_mod.ImmutableAdjacencySegment.summarizeWrittenEdgeStreams(forward_summary, reverse_summary);
        const edge_id_summary = written_summary.edge_id_summary;
        const endpoint_summary = written_summary.endpoint_summary;
        sortEdgeIndexRecords(.id, batch_records);
        const edge_id_order_digest = edgeSegmentIdIndexOrderDigest(batch_records);
        const edge_id_index = try self.writeEdgeSegmentIdIndexFromRecords(segment_dir_path, batch_records, edge_id_summary, edge_id_order_digest);
        segment.deinit();
        return .{
            .edge_digest = written_summary.edge_digest,
            .edge_id_summary = edge_id_summary,
            .endpoint_summary = endpoint_summary,
            .edge_id_order_digest = edge_id_index.edge_id_order_digest,
            .edge_id_runs = edge_id_index.edge_id_runs,
        };
    }

    pub fn compactPublishedEdgeSegments(self: Store, segment_dir_path: []const u8) !u64 {
        if (try self.pathExists(segment_dir_path)) return error.AlreadyExists;
        var manifest = try self.readEdgeSegmentManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const meta = try self.readCurrentIndexMeta();
        const manifest_edges = manifest.totalEdgeCount();
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        const covered_physical_edges = try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges);
        if (covered_physical_edges == null and !try self.edgeSegmentManifestCoversVisibleEdges(meta, manifest_edges)) {
            if (try self.edgeIndexesMatchMeta(meta)) {
                return try self.publishEdgeAdjacencySegment(segment_dir_path);
            }
            return error.InvalidRecord;
        }
        const source_edges = covered_physical_edges orelse meta.edges;
        const filters_tombstones = tombstone_header.count != 0 and covered_physical_edges != null;
        const total_edges = if (filters_tombstones) meta.edges else source_edges;
        const delta_overlay = covered_physical_edges != null and manifest_edges != source_edges;

        var segments = try PublishedEdgeSegments.openFromManifest(self.allocator, self.io, manifest.entries.items);
        defer segments.deinit();
        if (!filters_tombstones and tombstone_header.count != 0 and manifest_edges == meta.edges) {
            if (try segments.edgeDigest() != meta.edge_digest) return error.InvalidRecord;
        }

        var tombstones: ?EdgeTombstoneIndexView = null;
        defer if (tombstones) |*view| view.deinit();
        if (filters_tombstones) tombstones = try EdgeTombstoneIndexView.open(self);
        const tombstone_view = if (tombstones) |*view| view else null;

        var segment = try segment_mod.ImmutableAdjacencySegment.initEmpty(self.allocator, self.io, segment_dir_path);
        errdefer segment.deinit();
        var segment_unpublished = true;
        errdefer if (segment_unpublished) std.Io.Dir.cwd().deleteTree(self.io, segment_dir_path) catch {};

        var forward_summary: segment_mod.ImmutableAdjacencySegment.WrittenEdgeStreamSummary = undefined;
        var reverse_summary: segment_mod.ImmutableAdjacencySegment.WrittenEdgeStreamSummary = undefined;
        if (delta_overlay) {
            {
                var reader = try self.openEdgeIndexRecordReader(self.edge_by_src_path, .src, meta);
                defer reader.deinit();
                var stream = BaseAndSegmentMergeStream.initWithVirtualFiltered(self.allocator, &reader, &segments.segments, &segments.virtual_edges, .forward, tombstone_view);
                defer stream.deinit();
                forward_summary = try segment.writeTrustedOrderedEdgeStreamSummary(.forward, total_edges, &stream, BaseAndSegmentMergeStream.reset, BaseAndSegmentMergeStream.next);
            }
            {
                var reader = try self.openEdgeIndexRecordReader(self.edge_by_dst_path, .dst, meta);
                defer reader.deinit();
                var stream = BaseAndSegmentMergeStream.initWithVirtualFiltered(self.allocator, &reader, &segments.segments, &segments.virtual_edges, .reverse, tombstone_view);
                defer stream.deinit();
                reverse_summary = try segment.writeTrustedOrderedEdgeStreamSummary(.reverse, total_edges, &stream, BaseAndSegmentMergeStream.reset, BaseAndSegmentMergeStream.next);
            }
        } else {
            {
                var stream = EdgeSegmentMergeStream.initWithVirtualFiltered(self.allocator, &segments.segments, &segments.virtual_edges, .forward, tombstone_view);
                defer stream.deinit();
                forward_summary = try segment.writeTrustedOrderedEdgeStreamSummary(.forward, total_edges, &stream, EdgeSegmentMergeStream.reset, EdgeSegmentMergeStream.next);
            }
            {
                var stream = EdgeSegmentMergeStream.initWithVirtualFiltered(self.allocator, &segments.segments, &segments.virtual_edges, .reverse, tombstone_view);
                defer stream.deinit();
                reverse_summary = try segment.writeTrustedOrderedEdgeStreamSummary(.reverse, total_edges, &stream, EdgeSegmentMergeStream.reset, EdgeSegmentMergeStream.next);
            }
        }

        const written_summary = try segment_mod.ImmutableAdjacencySegment.summarizeWrittenEdgeStreams(forward_summary, reverse_summary);
        const edge_id_summary = written_summary.edge_id_summary;
        const endpoint_summary = written_summary.endpoint_summary;
        try segment.openWrittenViewsWithSummaries(forward_summary, reverse_summary);
        const edge_id_index = try self.writeEdgeSegmentIdIndexFromSegment(segment_dir_path, &segment, edge_id_summary);
        segment_unpublished = false;
        const manifest_summary = try self.writeEdgeSegmentManifest(segment_dir_path, written_summary.edge_digest, edge_id_summary, endpoint_summary, edge_id_index.edge_id_order_digest, edge_id_index.edge_id_runs);
        try self.updateIndexMetaEdgeSegmentSummary(manifest_summary);
        segment.deinit();
        return total_edges;
    }

    pub fn gcUnreferencedEdgeSegments(self: Store) !EdgeSegmentGcResult {
        return self.gcUnreferencedEdgeSegmentsExcept(&.{});
    }

    pub fn currentEdgeSegmentManifestPath(self: Store, allocator: std.mem.Allocator) !?[]u8 {
        return self.readEdgeSegmentCurrentPath(allocator);
    }

    pub fn openEdgeSegmentRetentionWindow(self: Store, allocator: std.mem.Allocator) !EdgeSegmentRetentionWindow {
        var window = EdgeSegmentRetentionWindow.init(allocator);
        errdefer window.deinit();
        if (try self.currentEdgeSegmentManifestPath(allocator)) |path| {
            try window.appendOwnedManifestPath(path);
        }
        return window;
    }

    pub fn openRegisteredEdgeSegmentRetentionWindow(self: Store, registry: *EdgeSegmentRetentionRegistry) !EdgeSegmentRegisteredRetentionWindow {
        var acquired = (try self.acquireCurrentManifestProcessLease(registry.allocator, .edge_segment)) orelse
            return .{ .registry = registry };
        errdefer acquired.deinit();
        const retained_path = try registry.retainOwnedManifestPath(acquired.takeManifestPath());
        return .{
            .registry = registry,
            .manifest_path = retained_path,
            .process_lease = acquired.takeProcessLease(),
        };
    }

    pub fn gcUnreferencedEdgeSegmentsRetainingRegistry(self: Store, registry: *const EdgeSegmentRetentionRegistry) !EdgeSegmentGcResult {
        const pinned_paths = try registry.activeManifestPaths(self.allocator);
        defer self.allocator.free(pinned_paths);
        return self.gcUnreferencedEdgeSegmentsExcept(pinned_paths);
    }

    pub fn gcUnreferencedEdgeSegmentsWithProcessLeases(self: Store) !EdgeSegmentGcResult {
        return self.gcUnreferencedEdgeSegmentsExceptAndProcessLeases(&.{});
    }

    fn dropRedundantEdgeSegmentOverlayAfterBaseIndexCatchup(self: Store) !bool {
        const meta = try self.readCurrentIndexMeta();
        if (meta.edge_segment_edges != 0) return false;
        if (meta.edge_indexed_edges != try self.visiblePlusTombstoneEdgeCount(meta)) return false;

        const current_manifest_path = try self.readEdgeSegmentCurrentPath(self.allocator);
        defer if (current_manifest_path) |path| self.allocator.free(path);
        const current_path = current_manifest_path orelse return false;

        var manifest = self.readEdgeSegmentManifestFile(self.allocator, current_path) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        try self.validateEdgeSegmentManifestPath(self.allocator, current_path, manifest.entries.items);
        for (manifest.entries.items) |entry| {
            if (edgeSegmentManifestEntryIsVirtual(entry)) continue;
            if (!try self.edgeSegmentPathIsImplicitL0(entry.path)) return false;
        }

        // Withdraw CURRENT before sampling leases. A reader publishes its
        // lease between two CURRENT reads; after this durable unlink, every
        // reader that accepted `current_path` must already have a visible
        // lease, while a later reader will fail its second read and never use
        // the old files. Sampling first would leave a race where a reader
        // stabilizes the old CURRENT after the sample and loses its segment.
        std.Io.Dir.cwd().deleteFile(self.io, self.edge_segment_current_path) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        try self.syncParentDirForPath(self.edge_segment_current_path);

        const protected_paths = try self.pinnedManifestPathsWithProcessLeases(.edge_segment, self.allocator, &.{});
        defer freeOwnedManifestPathList(self.allocator, protected_paths);
        for (protected_paths) |path| {
            if (std.mem.eql(u8, path, current_path)) {
                // Keep the old epoch discoverable for a later cleanup pass.
                // The temporary withdrawal above closed the acquisition race;
                // republishing now is safe because every accepted reader has
                // a lease that the next pass will sample after withdrawing it
                // again. A crash before this point only leaks redundant files.
                try self.writeEdgeSegmentCurrent(current_path);
                return false;
            }
        }

        for (manifest.entries.items) |entry| {
            if (try self.pathExists(entry.path)) {
                std.Io.Dir.cwd().deleteTree(self.io, entry.path) catch |err| switch (err) {
                    // CURRENT is already durably withdrawn and the base index
                    // covers these edges. Windows can still deny unlink while
                    // an mmap/AV handle drains; leaving unreferenced garbage
                    // for the normal GC pass is safe, while failing here would
                    // report an error after the logical commit point.
                    error.AccessDenied => {},
                    else => |e| return e,
                };
            }
        }
        std.Io.Dir.cwd().deleteFile(self.io, current_path) catch |err| switch (err) {
            error.FileNotFound, error.AccessDenied => {},
            else => |e| return e,
        };
        return true;
    }

    fn edgeSegmentPathIsImplicitL0(self: Store, path: []const u8) !bool {
        const parent = try std.fs.path.join(self.allocator, &.{ self.dir_path, "edge_segments" });
        defer self.allocator.free(parent);
        const dirname = std.fs.path.dirname(path) orelse return false;
        return std.mem.eql(u8, dirname, parent) and std.mem.startsWith(u8, std.fs.path.basename(path), "l0-");
    }

    pub fn gcUnreferencedEdgeSegmentsExceptAndProcessLeases(self: Store, pinned_manifest_paths: []const []const u8) !EdgeSegmentGcResult {
        const protected_paths = try self.pinnedManifestPathsWithProcessLeases(.edge_segment, self.allocator, pinned_manifest_paths);
        defer freeOwnedManifestPathList(self.allocator, protected_paths);
        return self.gcUnreferencedEdgeSegmentsExcept(protected_paths);
    }

    pub fn currentNodeTextRunManifestPath(self: Store, allocator: std.mem.Allocator) !?[]u8 {
        return self.readNodeTextRunCurrentPath(allocator);
    }

    pub fn openRegisteredNodeTextRunRetentionWindow(self: Store, registry: *NodeTextRunRetentionRegistry) !NodeTextRunRegisteredRetentionWindow {
        var acquired = (try self.acquireCurrentManifestProcessLease(registry.allocator, .node_text_run)) orelse
            return .{ .registry = registry };
        errdefer acquired.deinit();
        const retained_path = try registry.retainOwnedManifestPath(acquired.takeManifestPath());
        return .{
            .registry = registry,
            .manifest_path = retained_path,
            .process_lease = acquired.takeProcessLease(),
        };
    }

    pub fn gcUnreferencedNodeTextRunsRetainingRegistry(self: Store, registry: *const NodeTextRunRetentionRegistry) !NodeTextRunGcResult {
        const pinned_paths = try registry.activeManifestPaths(self.allocator);
        defer self.allocator.free(pinned_paths);
        return self.gcUnreferencedNodeTextRunsExcept(pinned_paths);
    }

    pub fn gcUnreferencedNodeTextRunsWithProcessLeases(self: Store) !NodeTextRunGcResult {
        return self.gcUnreferencedNodeTextRunsExceptAndProcessLeases(&.{});
    }

    pub fn gcUnreferencedNodeTextRunsExceptAndProcessLeases(self: Store, pinned_manifest_paths: []const []const u8) !NodeTextRunGcResult {
        const protected_paths = try self.pinnedManifestPathsWithProcessLeases(.node_text_run, self.allocator, pinned_manifest_paths);
        defer freeOwnedManifestPathList(self.allocator, protected_paths);
        return self.gcUnreferencedNodeTextRunsExcept(protected_paths);
    }

    fn manifestProcessLeaseDirPath(self: Store, allocator: std.mem.Allocator) ![]u8 {
        return try std.fs.path.join(allocator, &.{ self.dir_path, ".tinykg_leases" });
    }

    fn currentManifestPathForProcessLease(
        self: Store,
        allocator: std.mem.Allocator,
        kind: ManifestProcessLeaseKind,
    ) !?[]u8 {
        return switch (kind) {
            .edge_segment => try self.currentEdgeSegmentManifestPath(allocator),
            .node_text_run => try self.currentNodeTextRunManifestPath(allocator),
        };
    }

    fn acquireCurrentManifestProcessLease(
        self: Store,
        allocator: std.mem.Allocator,
        kind: ManifestProcessLeaseKind,
    ) !?AcquiredManifestProcessLease {
        // Reading CURRENT and publishing the lease are not one atomic action.
        // Re-read CURRENT after the lease is visible: if a publisher moved it
        // in between, that publisher may already have reclaimed the old epoch.
        // A stable match means every later reclaimer must observe this lease;
        // a changing writer is bounded so a reader cannot spin forever.
        for (0..manifest_process_lease_acquire_max_attempts) |_| {
            const candidate = (try self.currentManifestPathForProcessLease(allocator, kind)) orelse return null;
            if (try self.acquireManifestProcessLeaseCandidate(allocator, kind, candidate)) |acquired| return acquired;
        }
        return error.WouldBlock;
    }

    /// Consumes `candidate` on every path. Split out so the publication race
    /// has a deterministic regression test: a stale pre-read candidate must
    /// never escape merely because its lease file was published successfully.
    fn acquireManifestProcessLeaseCandidate(
        self: Store,
        allocator: std.mem.Allocator,
        kind: ManifestProcessLeaseKind,
        candidate: []u8,
    ) !?AcquiredManifestProcessLease {
        var candidate_owned = true;
        defer if (candidate_owned) allocator.free(candidate);

        var process_lease = try self.createManifestProcessLease(kind, candidate);
        var lease_owned = true;
        defer if (lease_owned) process_lease.deinit();

        const observed = try self.currentManifestPathForProcessLease(allocator, kind);
        defer if (observed) |path| allocator.free(path);
        if (observed == null or !std.mem.eql(u8, candidate, observed.?)) return null;

        candidate_owned = false;
        lease_owned = false;
        return .{
            .path_allocator = allocator,
            .manifest_path = candidate,
            .process_lease = process_lease,
        };
    }

    fn createManifestProcessLease(self: Store, kind: ManifestProcessLeaseKind, manifest_path: []const u8) !ManifestProcessLease {
        const lease_dir_path = try self.manifestProcessLeaseDirPath(self.allocator);
        defer self.allocator.free(lease_dir_path);
        try std.Io.Dir.cwd().createDirPath(self.io, lease_dir_path);

        const pid = currentProcessIdForTempPath();
        const nonce = manifest_process_lease_nonce.fetchAdd(1, .monotonic);
        const manifest_hash = std.hash.Wyhash.hash(0, manifest_path);
        const leaf = try std.fmt.allocPrint(self.allocator, "{s}-{d}-{x}-{x}.lease", .{ kind.filePrefix(), pid, manifest_hash, nonce });
        defer self.allocator.free(leaf);
        const lease_path = try std.fs.path.join(self.allocator, &.{ lease_dir_path, leaf });
        errdefer self.allocator.free(lease_path);

        const content = try std.fmt.allocPrint(
            self.allocator,
            "tinykg-manifest-lease-v1\nkind={s}\npid={d}\nmanifest={s}\n",
            .{ kind.tag(), pid, manifest_path },
        );
        defer self.allocator.free(content);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, lease_path) catch {};
        const lease_tmp_path = try self.tmpPathFor(lease_path);
        defer self.allocator.free(lease_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, lease_tmp_path) catch {};
        try std.Io.Dir.cwd().writeFile(self.io, .{
            .sub_path = lease_tmp_path,
            .data = content,
            .flags = .{ .truncate = true },
        });
        try self.renameReplace(lease_tmp_path, lease_path);
        return .{ .allocator = self.allocator, .io = self.io, .path = lease_path };
    }

    fn activeProcessLeaseManifestPaths(self: Store, kind: ManifestProcessLeaseKind, allocator: std.mem.Allocator) ![]const []const u8 {
        const lease_dir_path = try self.manifestProcessLeaseDirPath(self.allocator);
        defer self.allocator.free(lease_dir_path);

        var leases_dir = std.Io.Dir.cwd().openDir(self.io, lease_dir_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => {
                var empty = std.ArrayList([]const u8).empty;
                return try empty.toOwnedSlice(allocator);
            },
            else => |e| return e,
        };
        defer leases_dir.close(self.io);

        var paths = std.ArrayList([]const u8).empty;
        errdefer freeOwnedManifestPathArrayList(allocator, &paths);
        var iter = leases_dir.iterate();
        while (try iter.next(self.io)) |entry| {
            if (entry.kind != .file) continue;
            const lease_path = try std.fs.path.join(self.allocator, &.{ lease_dir_path, entry.name });
            defer self.allocator.free(lease_path);
            const content = std.Io.Dir.cwd().readFileAlloc(self.io, lease_path, self.allocator, .limited(8192)) catch |err| switch (err) {
                error.FileNotFound => continue,
                error.StreamTooLong => {
                    std.Io.Dir.cwd().deleteFile(self.io, lease_path) catch {};
                    continue;
                },
                else => |e| return e,
            };
            defer self.allocator.free(content);
            const lease = parseManifestProcessLease(content) orelse {
                std.Io.Dir.cwd().deleteFile(self.io, lease_path) catch {};
                continue;
            };
            if (!processIdIsAlive(lease.pid)) {
                std.Io.Dir.cwd().deleteFile(self.io, lease_path) catch {};
                continue;
            }
            if (lease.kind != kind) continue;
            const owned_manifest_path = try allocator.dupe(u8, lease.manifest_path);
            errdefer allocator.free(owned_manifest_path);
            try paths.append(allocator, owned_manifest_path);
        }
        return try paths.toOwnedSlice(allocator);
    }

    fn pinnedManifestPathsWithProcessLeases(
        self: Store,
        kind: ManifestProcessLeaseKind,
        allocator: std.mem.Allocator,
        pinned_manifest_paths: []const []const u8,
    ) ![]const []const u8 {
        var protected_paths = std.ArrayList([]const u8).empty;
        errdefer freeOwnedManifestPathArrayList(allocator, &protected_paths);

        try protected_paths.ensureTotalCapacity(allocator, pinned_manifest_paths.len);
        for (pinned_manifest_paths) |path| {
            const owned_path = try allocator.dupe(u8, path);
            protected_paths.appendAssumeCapacity(owned_path);
        }

        const process_paths = try self.activeProcessLeaseManifestPaths(kind, allocator);
        defer freeOwnedManifestPathList(allocator, process_paths);
        try protected_paths.ensureUnusedCapacity(allocator, process_paths.len);
        for (process_paths) |path| {
            const owned_path = try allocator.dupe(u8, path);
            protected_paths.appendAssumeCapacity(owned_path);
        }
        return try protected_paths.toOwnedSlice(allocator);
    }

    pub fn gcUnreferencedEdgeSegmentsExcept(self: Store, pinned_manifest_paths: []const []const u8) !EdgeSegmentGcResult {
        const current_manifest_path = try self.readEdgeSegmentCurrentPath(self.allocator);
        defer if (current_manifest_path) |path| self.allocator.free(path);

        var live_paths = std.StringHashMap(void).init(self.allocator);
        defer live_paths.deinit();

        var protected_manifest_paths = std.StringHashMap(void).init(self.allocator);
        defer protected_manifest_paths.deinit();
        try protected_manifest_paths.ensureTotalCapacity(@intCast(pinned_manifest_paths.len + 1));
        if (current_manifest_path) |path| try protected_manifest_paths.put(path, {});
        for (pinned_manifest_paths) |path| {
            try protected_manifest_paths.put(path, {});
        }

        var pinned_manifests = std.ArrayList(EdgeSegmentManifest).empty;
        defer {
            for (pinned_manifests.items) |*manifest| manifest.deinit(self.allocator);
            pinned_manifests.deinit(self.allocator);
        }

        if (current_manifest_path) |path| {
            var manifest = try (self.readEdgeSegmentManifestFile(self.allocator, path) catch |err| switch (err) {
                error.FileNotFound => error.InvalidRecord,
                else => |e| e,
            });
            errdefer manifest.deinit(self.allocator);
            try self.validateEdgeSegmentManifestPath(self.allocator, path, manifest.entries.items);
            try addEdgeSegmentManifestLivePaths(&live_paths, manifest.entries.items);
            try pinned_manifests.append(self.allocator, manifest);
            manifest = .{};
        }
        for (pinned_manifest_paths) |path| {
            if (current_manifest_path) |current| {
                if (std.mem.eql(u8, path, current)) continue;
            }
            var manifest = try self.readEdgeSegmentManifestFile(self.allocator, path);
            errdefer manifest.deinit(self.allocator);
            try self.validateEdgeSegmentManifestPath(self.allocator, path, manifest.entries.items);
            try addEdgeSegmentManifestLivePaths(&live_paths, manifest.entries.items);
            try pinned_manifests.append(self.allocator, manifest);
            manifest = .{};
        }

        const segments_dir_path = try std.fs.path.join(self.allocator, &.{ self.dir_path, "edge_segments" });
        defer self.allocator.free(segments_dir_path);
        var result = EdgeSegmentGcResult{};
        var dir = std.Io.Dir.cwd().openDir(self.io, segments_dir_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => null,
            else => |e| return e,
        };
        if (dir) |*segments_dir| {
            defer segments_dir.close(self.io);
            var iter = segments_dir.iterate();
            while (try iter.next(self.io)) |entry| {
                if (entry.kind != .directory) continue;
                const full_path = try std.fs.path.join(self.allocator, &.{ segments_dir_path, entry.name });
                defer self.allocator.free(full_path);
                if (live_paths.contains(full_path)) continue;
                try std.Io.Dir.cwd().deleteTree(self.io, full_path);
                result.deleted_segments = std.math.add(u64, result.deleted_segments, 1) catch return error.RecordTooLarge;
            }
        }
        result.deleted_manifests = try self.gcUnreferencedEdgeSegmentManifestsExcept(&protected_manifest_paths);
        return result;
    }

    fn gcUnreferencedEdgeSegmentManifests(self: Store) !u64 {
        var protected_manifest_paths = std.StringHashMap(void).init(self.allocator);
        defer protected_manifest_paths.deinit();
        const current_manifest_path = try self.readEdgeSegmentCurrentPath(self.allocator);
        defer if (current_manifest_path) |path| self.allocator.free(path);
        if (current_manifest_path) |path| try protected_manifest_paths.put(path, {});
        return self.gcUnreferencedEdgeSegmentManifestsExcept(&protected_manifest_paths);
    }

    fn gcUnreferencedEdgeSegmentManifestsExcept(self: Store, protected_manifest_paths: *const std.StringHashMap(void)) !u64 {
        const manifest_leaf = std.fs.path.basename(self.edge_segment_manifest_path);
        const epoch_prefix = try std.fmt.allocPrint(self.allocator, "{s}.", .{manifest_leaf});
        defer self.allocator.free(epoch_prefix);

        var store_dir = try std.Io.Dir.cwd().openDir(self.io, self.dir_path, .{ .iterate = true });
        defer store_dir.close(self.io);

        var deleted: u64 = 0;
        var iter = store_dir.iterate();
        while (try iter.next(self.io)) |entry| {
            if (entry.kind != .file) continue;
            if (!isEdgeSegmentManifestEpochLeaf(entry.name, epoch_prefix)) continue;
            const full_path = try std.fs.path.join(self.allocator, &.{ self.dir_path, entry.name });
            defer self.allocator.free(full_path);
            if (protected_manifest_paths.contains(full_path)) continue;
            try std.Io.Dir.cwd().deleteFile(self.io, full_path);
            deleted = std.math.add(u64, deleted, 1) catch return error.RecordTooLarge;
        }
        return deleted;
    }

    pub fn autoCompactEdgeSegmentsIfNeeded(self: Store) !bool {
        const threshold = self.options.auto_compact_edge_segment_entries;
        if (threshold == 0) return false;

        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        if (manifest.entries.items.len <= 1 or manifest.entries.items.len < threshold) return false;

        const meta = try self.readCurrentIndexMeta();
        const manifest_edges = manifest.totalEdgeCount();
        const physical_edges = (try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges)) orelse return false;
        if (manifest_edges == physical_edges) return false;

        const batch_limit = if (self.options.auto_compact_edge_segment_batch_entries == 0)
            manifest.entries.items.len
        else
            @min(manifest.entries.items.len, @as(usize, self.options.auto_compact_edge_segment_batch_entries));
        if (batch_limit <= 1) return false;

        const window = (try selectEdgeSegmentCompactionWindow(self.allocator, manifest.entries.items, batch_limit, 0)) orelse return false;
        const compact_entries = manifest.entries.items[window.start..][0..window.count];
        const compact_digest = try self.edgeSegmentManifestOwnedDigest(compact_entries);
        const segment_dir_path = try self.edgeAutoCompactedSegmentPath(window.edge_count, window.count, compact_digest);
        defer self.allocator.free(segment_dir_path);
        if (try self.pathExists(segment_dir_path)) return false;

        _ = try self.compactEdgeSegmentManifestRange(segment_dir_path, manifest.entries.items, window.start, window.count, window.edge_count);
        if (self.options.auto_gc_edge_segments) _ = try self.gcUnreferencedEdgeSegmentsWithProcessLeases();
        return true;
    }

    pub fn compactEdgeSegmentsBudgeted(self: Store, budget: EdgeSegmentMaintenanceBudget) !EdgeSegmentMaintenanceResult {
        return self.compactEdgeSegmentsBudgetedExcept(budget, &.{});
    }

    pub fn compactEdgeSegmentsBudgetedRetainingRegistry(self: Store, budget: EdgeSegmentMaintenanceBudget, registry: *const EdgeSegmentRetentionRegistry) !EdgeSegmentMaintenanceResult {
        const pinned_paths = try registry.activeManifestPaths(self.allocator);
        defer self.allocator.free(pinned_paths);
        return self.compactEdgeSegmentsBudgetedExcept(budget, pinned_paths);
    }

    pub fn compactEdgeSegmentsBudgetedWithProcessLeases(self: Store, budget: EdgeSegmentMaintenanceBudget) !EdgeSegmentMaintenanceResult {
        return self.compactEdgeSegmentsBudgetedExceptAndProcessLeases(budget, &.{});
    }

    pub fn compactEdgeSegmentsBudgetedExceptAndProcessLeases(
        self: Store,
        budget: EdgeSegmentMaintenanceBudget,
        pinned_manifest_paths: []const []const u8,
    ) !EdgeSegmentMaintenanceResult {
        const protected_paths = try self.pinnedManifestPathsWithProcessLeases(.edge_segment, self.allocator, pinned_manifest_paths);
        defer freeOwnedManifestPathList(self.allocator, protected_paths);
        return self.compactEdgeSegmentsBudgetedExcept(budget, protected_paths);
    }

    pub fn compactEdgeSegmentsBudgetedExcept(self: Store, budget: EdgeSegmentMaintenanceBudget, pinned_manifest_paths: []const []const u8) !EdgeSegmentMaintenanceResult {
        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => return .{ .compacted = false },
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);

        const entries_before = manifest.entries.items.len;
        if (entries_before <= 1) return .{
            .compacted = false,
            .manifest_entries_before = entries_before,
            .manifest_entries_after = entries_before,
        };

        const meta = try self.readCurrentIndexMeta();
        const manifest_edges = manifest.totalEdgeCount();
        _ = (try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges)) orelse return .{
            .compacted = false,
            .manifest_entries_before = entries_before,
            .manifest_entries_after = entries_before,
        };

        const max_segments = if (budget.max_segments == 0) entries_before else @min(entries_before, budget.max_segments);
        const window = (try selectEdgeSegmentCompactionWindow(self.allocator, manifest.entries.items, max_segments, budget.max_edges)) orelse return .{
            .compacted = false,
            .manifest_entries_before = entries_before,
            .manifest_entries_after = entries_before,
        };

        const compact_entries = manifest.entries.items[window.start..][0..window.count];
        const compact_digest = try self.edgeSegmentManifestOwnedDigest(compact_entries);
        const segment_dir_path = try self.edgeAutoCompactedSegmentPath(window.edge_count, window.count, compact_digest);
        defer self.allocator.free(segment_dir_path);
        if (try self.pathExists(segment_dir_path)) return .{
            .compacted = false,
            .manifest_entries_before = entries_before,
            .manifest_entries_after = entries_before,
        };

        _ = try self.compactEdgeSegmentManifestRange(segment_dir_path, manifest.entries.items, window.start, window.count, window.edge_count);
        const gc_result = if (self.options.auto_gc_edge_segments) try self.gcUnreferencedEdgeSegmentsExcept(pinned_manifest_paths) else EdgeSegmentGcResult{};
        return .{
            .compacted = true,
            .compacted_edges = window.edge_count,
            .compacted_segments = window.count,
            .gc_deleted_segments = gc_result.deleted_segments,
            .gc_deleted_manifests = gc_result.deleted_manifests,
            .manifest_entries_before = entries_before,
            .manifest_entries_after = entries_before - window.count + 1,
        };
    }

    fn selectEdgeSegmentCompactionWindow(
        allocator: std.mem.Allocator,
        entries: []const OwnedEdgeSegmentManifestEntry,
        max_segments: usize,
        max_edges: u64,
    ) !?EdgeSegmentCompactionWindow {
        if (entries.len <= 1 or max_segments <= 1) return null;

        var min_queue = std.ArrayList(usize).empty;
        var max_queue = std.ArrayList(usize).empty;
        const queue_capacity = if (max_segments >= entries.len) entries.len else max_segments + 1;
        var stack_queue_storage: [edge_segment_compaction_stack_queue_entries * 2]usize = undefined;
        var fixed_queue_allocator = std.heap.FixedBufferAllocator.init(std.mem.sliceAsBytes(stack_queue_storage[0..]));
        const queue_allocator = if (queue_capacity <= edge_segment_compaction_stack_queue_entries)
            fixed_queue_allocator.allocator()
        else
            allocator;
        defer min_queue.deinit(queue_allocator);
        defer max_queue.deinit(queue_allocator);
        try min_queue.ensureTotalCapacity(queue_allocator, queue_capacity);
        try max_queue.ensureTotalCapacity(queue_allocator, queue_capacity);
        var min_head: usize = 0;
        var max_head: usize = 0;

        var best: ?EdgeSegmentCompactionWindow = null;
        var start: usize = 0;
        var edge_count: u64 = 0;
        for (entries, 0..) |entry, end| {
            edge_count = std.math.add(u64, edge_count, entry.edge_count) catch return error.RecordTooLarge;
            while (min_queue.items.len > min_head and entries[min_queue.items[min_queue.items.len - 1]].edge_count >= entry.edge_count) {
                _ = min_queue.pop();
            }
            compactSlidingIndexQueueIfFull(&min_queue, &min_head);
            min_queue.appendAssumeCapacity(end);
            while (max_queue.items.len > max_head and entries[max_queue.items[max_queue.items.len - 1]].edge_count <= entry.edge_count) {
                _ = max_queue.pop();
            }
            compactSlidingIndexQueueIfFull(&max_queue, &max_head);
            max_queue.appendAssumeCapacity(end);

            while (start <= end and (end - start + 1 > max_segments or (max_edges != 0 and edge_count > max_edges))) {
                if (min_queue.items[min_head] == start) min_head += 1;
                if (max_queue.items[max_head] == start) max_head += 1;
                edge_count -= entries[start].edge_count;
                start += 1;
            }

            const candidate_count = if (start <= end) end - start + 1 else 0;
            if (candidate_count <= 1) continue;
            const candidate = EdgeSegmentCompactionWindow{
                .start = start,
                .count = candidate_count,
                .edge_count = edge_count,
                .min_segment_edges = entries[min_queue.items[min_head]].edge_count,
                .max_segment_edges = entries[max_queue.items[max_head]].edge_count,
            };
            if (best == null or edgeSegmentCompactionWindowLessThan(best.?, candidate)) {
                best = candidate;
            }
        }
        return best;
    }

    fn compactSlidingIndexQueueIfFull(queue: *std.ArrayList(usize), head: *usize) void {
        if (queue.items.len < queue.capacity or head.* == 0) return;
        const live = queue.items[head.*..];
        std.mem.copyForwards(usize, queue.items[0..live.len], live);
        queue.shrinkRetainingCapacity(live.len);
        head.* = 0;
    }

    fn edgeSegmentWindowIsSameTier(window: EdgeSegmentCompactionWindow) bool {
        if (window.min_segment_edges == 0) return false;
        const max_same_tier = std.math.mul(u64, window.min_segment_edges, edge_segment_compaction_tier_ratio) catch std.math.maxInt(u64);
        return window.max_segment_edges <= max_same_tier;
    }

    fn edgeSegmentCompactionWindowLessThan(a: EdgeSegmentCompactionWindow, b: EdgeSegmentCompactionWindow) bool {
        const a_same_tier = edgeSegmentWindowIsSameTier(a);
        const b_same_tier = edgeSegmentWindowIsSameTier(b);
        if (a_same_tier != b_same_tier) return b_same_tier;
        if (a.edge_count != b.edge_count) return a.edge_count < b.edge_count;
        if (a.count != b.count) return a.count < b.count;
        return a.start < b.start;
    }

    fn compactEdgeSegmentManifestSuffix(
        self: Store,
        segment_dir_path: []const u8,
        entries: []const OwnedEdgeSegmentManifestEntry,
        compact_count: usize,
        compacted_edges: u64,
    ) !u64 {
        if (compact_count > entries.len) return error.InvalidRecord;
        return self.compactEdgeSegmentManifestRange(segment_dir_path, entries, entries.len - compact_count, compact_count, compacted_edges);
    }

    fn compactEdgeSegmentManifestRange(
        self: Store,
        segment_dir_path: []const u8,
        entries: []const OwnedEdgeSegmentManifestEntry,
        compact_start: usize,
        compact_count: usize,
        compacted_edges: u64,
    ) !u64 {
        if (compact_count == entries.len and compact_start == 0) return try self.compactEdgeSegmentManifestEntries(segment_dir_path, entries, compacted_edges);
        if (compact_count <= 1 or compact_count > entries.len or compact_start > entries.len - compact_count) return error.InvalidRecord;
        if (try self.pathExists(segment_dir_path)) return error.AlreadyExists;

        var segments = try PublishedEdgeSegments.openFromManifest(self.allocator, self.io, entries[compact_start..][0..compact_count]);
        defer segments.deinit();

        var segment = try segment_mod.ImmutableAdjacencySegment.initEmpty(self.allocator, self.io, segment_dir_path);
        errdefer segment.deinit();
        var segment_unpublished = true;
        errdefer if (segment_unpublished) std.Io.Dir.cwd().deleteTree(self.io, segment_dir_path) catch {};

        const forward_summary = blk: {
            var stream = EdgeSegmentMergeStream.initWithVirtual(self.allocator, &segments.segments, &segments.virtual_edges, .forward);
            defer stream.deinit();
            break :blk try segment.writeTrustedOrderedEdgeStreamSummary(.forward, compacted_edges, &stream, EdgeSegmentMergeStream.reset, EdgeSegmentMergeStream.next);
        };
        const reverse_summary = blk: {
            var stream = EdgeSegmentMergeStream.initWithVirtual(self.allocator, &segments.segments, &segments.virtual_edges, .reverse);
            defer stream.deinit();
            break :blk try segment.writeTrustedOrderedEdgeStreamSummary(.reverse, compacted_edges, &stream, EdgeSegmentMergeStream.reset, EdgeSegmentMergeStream.next);
        };
        var next_entries = std.ArrayList(EdgeSegmentManifestEntry).empty;
        defer next_entries.deinit(self.allocator);
        try next_entries.ensureTotalCapacity(self.allocator, entries.len - compact_count + 1);
        for (entries[0..compact_start]) |entry| {
            next_entries.appendAssumeCapacity(.{
                .edge_count = entry.edge_count,
                .edge_digest = entry.edge_digest,
                .edge_id_range = entry.edge_id_range,
                .edge_id_digest = entry.edge_id_digest,
                .edge_id_order_digest = entry.edge_id_order_digest,
                .edge_id_runs = entry.edge_id_runs,
                .src_node_range = entry.src_node_range,
                .dst_node_range = entry.dst_node_range,
                .singleton_rel = entry.singleton_rel,
                .path = entry.path,
            });
        }
        const written_summary = try segment_mod.ImmutableAdjacencySegment.summarizeWrittenEdgeStreams(forward_summary, reverse_summary);
        const edge_id_summary = written_summary.edge_id_summary;
        const endpoint_summary = written_summary.endpoint_summary;
        const edge_id_index = try self.writeEdgeSegmentIdIndexFromManifestEntries(segment_dir_path, entries[compact_start .. compact_start + compact_count], edge_id_summary);
        next_entries.appendAssumeCapacity(.{
            .edge_count = compacted_edges,
            .edge_digest = written_summary.edge_digest,
            .edge_id_range = edge_id_summary.range,
            .edge_id_digest = edge_id_summary.digest,
            .edge_id_order_digest = edge_id_index.edge_id_order_digest,
            .edge_id_runs = edge_id_index.edge_id_runs,
            .src_node_range = endpoint_summary.src_range,
            .dst_node_range = endpoint_summary.dst_range,
            .path = segment_dir_path,
        });
        for (entries[compact_start + compact_count ..]) |entry| {
            next_entries.appendAssumeCapacity(.{
                .edge_count = entry.edge_count,
                .edge_digest = entry.edge_digest,
                .edge_id_range = entry.edge_id_range,
                .edge_id_digest = entry.edge_id_digest,
                .edge_id_order_digest = entry.edge_id_order_digest,
                .edge_id_runs = entry.edge_id_runs,
                .src_node_range = entry.src_node_range,
                .dst_node_range = entry.dst_node_range,
                .singleton_rel = entry.singleton_rel,
                .path = entry.path,
            });
        }
        segment_unpublished = false;
        try self.writeEdgeSegmentManifestEntries(next_entries.items);
        try self.updateIndexMetaEdgeSegmentSummary(try self.edgeSegmentManifestSummary(next_entries.items));
        segment.deinit();
        return compacted_edges;
    }

    fn compactEdgeSegmentManifestEntries(
        self: Store,
        segment_dir_path: []const u8,
        entries: []const OwnedEdgeSegmentManifestEntry,
        total_edges: u64,
    ) !u64 {
        if (try self.pathExists(segment_dir_path)) return error.AlreadyExists;
        var segments = try PublishedEdgeSegments.openFromManifest(self.allocator, self.io, entries);
        defer segments.deinit();

        var segment = try segment_mod.ImmutableAdjacencySegment.initEmpty(self.allocator, self.io, segment_dir_path);
        errdefer segment.deinit();
        var segment_unpublished = true;
        errdefer if (segment_unpublished) std.Io.Dir.cwd().deleteTree(self.io, segment_dir_path) catch {};

        const forward_summary = blk: {
            var stream = EdgeSegmentMergeStream.initWithVirtual(self.allocator, &segments.segments, &segments.virtual_edges, .forward);
            defer stream.deinit();
            break :blk try segment.writeTrustedOrderedEdgeStreamSummary(.forward, total_edges, &stream, EdgeSegmentMergeStream.reset, EdgeSegmentMergeStream.next);
        };
        const reverse_summary = blk: {
            var stream = EdgeSegmentMergeStream.initWithVirtual(self.allocator, &segments.segments, &segments.virtual_edges, .reverse);
            defer stream.deinit();
            break :blk try segment.writeTrustedOrderedEdgeStreamSummary(.reverse, total_edges, &stream, EdgeSegmentMergeStream.reset, EdgeSegmentMergeStream.next);
        };

        const written_summary = try segment_mod.ImmutableAdjacencySegment.summarizeWrittenEdgeStreams(forward_summary, reverse_summary);
        const edge_id_summary = written_summary.edge_id_summary;
        const endpoint_summary = written_summary.endpoint_summary;
        const edge_id_index = try self.writeEdgeSegmentIdIndexFromManifestEntries(segment_dir_path, entries, edge_id_summary);
        segment_unpublished = false;
        const manifest_summary = try self.writeEdgeSegmentManifest(segment_dir_path, written_summary.edge_digest, edge_id_summary, endpoint_summary, edge_id_index.edge_id_order_digest, edge_id_index.edge_id_runs);
        try self.updateIndexMetaEdgeSegmentSummary(manifest_summary);
        segment.deinit();
        return total_edges;
    }

    fn edgeAutoCompactedSegmentPath(self: Store, total_edges: u64, segment_count: usize, manifest_digest: u64) ![]u8 {
        const parent = try std.fs.path.join(self.allocator, &.{ self.dir_path, "edge_segments" });
        defer self.allocator.free(parent);
        try std.Io.Dir.cwd().createDirPath(self.io, parent);
        const event_bytes = try self.eventBytes();
        const leaf = try std.fmt.allocPrint(self.allocator, "auto-compact-{}-{}-{}-{x}", .{ total_edges, event_bytes, segment_count, manifest_digest });
        defer self.allocator.free(leaf);
        return try std.fs.path.join(self.allocator, &.{ parent, leaf });
    }

    fn canAppendEdgeBatchAsSegmentDelta(self: Store, old_meta: IndexMeta, edges: []const graph_mod.Edge) !bool {
        if (edges.len == 0) return false;
        const summary_current = try self.edgeSegmentMetaSummaryCurrent(old_meta);
        var manifest_found = summary_current;
        const manifest_edges = if (summary_current) old_meta.edge_segment_edges else blk: {
            var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
                error.FileNotFound => {
                    manifest_found = false;
                    break :blk @as(u64, 0);
                },
                else => |e| return e,
            };
            defer manifest.deinit(self.allocator);
            break :blk manifest.totalEdgeCount();
        };
        if (!manifest_found and old_meta.edge_indexed_edges < implicit_edge_delta_segment_min_base_edges) return false;
        if (try self.edgeSegmentManifestCoveredPhysicalEdges(old_meta, manifest_edges) == null) return false;
        if (try self.edgeIndexTailExceedsHighWater(old_meta)) return false;
        return try self.edgeBatchIdsAreNewForSegmentDelta(old_meta, edges, summary_current);
    }

    fn edgeBatchIdsAreNewForSegmentDelta(self: Store, meta: IndexMeta, edges: []const graph_mod.Edge, edge_segment_summary_current: bool) !bool {
        if (edges.len == 0) return true;
        var sorted_previous: u64 = 0;
        var sorted_candidate_min: u64 = std.math.maxInt(u64);
        var sorted_candidate_max: u64 = 0;
        var sorted_candidate_count: usize = 0;
        var sorted_needs_existing_check = false;
        for (edges, 0..) |edge, index| {
            const id = edge.id.toInt();
            if (id == 0 or id == std.math.maxInt(u64)) return false;
            if (index != 0 and id <= sorted_previous) break;
            if (id <= meta.max_edge_id_seen) {
                sorted_needs_existing_check = true;
                sorted_candidate_count += 1;
                sorted_candidate_min = @min(sorted_candidate_min, id);
                sorted_candidate_max = @max(sorted_candidate_max, id);
            }
            sorted_previous = id;
        } else {
            if (sorted_needs_existing_check) {
                if (self.edge_batch_segment_delta_stats) |delta_stats| {
                    delta_stats.slow_path_batches += 1;
                    delta_stats.slow_path_sorted_batches += 1;
                    delta_stats.slow_path_candidate_ids += sorted_candidate_count;
                }

                var existing_candidates = std.ArrayList(u64).empty;
                defer existing_candidates.deinit(self.allocator);
                try existing_candidates.ensureTotalCapacity(self.allocator, sorted_candidate_count);
                for (edges) |edge| {
                    const id = edge.id.toInt();
                    if (id <= meta.max_edge_id_seen) existing_candidates.appendAssumeCapacity(id);
                }
                return try self.edgeSortedCandidateIdsAreNewForSegmentDelta(
                    meta,
                    existing_candidates.items,
                    sorted_candidate_min,
                    sorted_candidate_max,
                    edge_segment_summary_current,
                );
            }
            if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.fast_path_batches += 1;
            return true;
        }

        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        try seen.ensureTotalCapacity(@intCast(edges.len));
        var candidate_min: u64 = std.math.maxInt(u64);
        var candidate_max: u64 = 0;
        var candidate_count: usize = 0;
        var needs_existing_check = false;
        for (edges) |edge| {
            const id = edge.id.toInt();
            if (id == 0 or id == std.math.maxInt(u64)) return false;
            if (id <= meta.max_edge_id_seen) {
                needs_existing_check = true;
                candidate_count += 1;
                candidate_min = @min(candidate_min, id);
                candidate_max = @max(candidate_max, id);
            }
            const entry = try seen.getOrPut(id);
            if (entry.found_existing) return false;
        }
        if (!needs_existing_check) return true;
        if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.slow_path_batches += 1;
            delta_stats.slow_path_candidate_ids += candidate_count;
        }

        var existing_candidates = std.ArrayList(u64).empty;
        defer existing_candidates.deinit(self.allocator);
        try existing_candidates.ensureTotalCapacity(self.allocator, candidate_count);
        for (edges) |edge| {
            const id = edge.id.toInt();
            if (id <= meta.max_edge_id_seen) existing_candidates.appendAssumeCapacity(id);
        }
        std.mem.sort(u64, existing_candidates.items, {}, u64LessThan);

        return try self.edgeSortedCandidateIdsAreNewForSegmentDelta(meta, existing_candidates.items, candidate_min, candidate_max, edge_segment_summary_current);
    }

    fn edgeSortedCandidateIdsAreNewForSegmentDelta(
        self: Store,
        meta: IndexMeta,
        existing_candidates: []const u64,
        candidate_min: u64,
        candidate_max: u64,
        edge_segment_summary_current: bool,
    ) !bool {
        var id_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer id_file.close(self.io);
        const id_header = try self.validateEdgeIndexHeaderForAppend(id_file, .id, meta);
        const base_check_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        var base_candidate_checks: usize = existing_candidates.len;
        const base_intersects = blk: {
            if (try self.edgeIdRunSummaryMatchesFile(id_file, id_header, meta.edge_by_id_runs)) {
                base_candidate_checks = meta.edge_by_id_runs.intersectingSortedIdCount(existing_candidates);
                break :blk base_candidate_checks != 0;
            }
            break :blk try self.edgeIdSortedSetIntersectsFile(id_file, id_header, existing_candidates);
        };
        if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.base_id_checks += base_candidate_checks;
            delta_stats.base_id_check_ns += storageElapsedNs(self.io, base_check_start);
        }
        if (base_intersects) return false;
        if (try self.edgeIdSetIntersectsTombstones(existing_candidates)) return false;
        const overlay_check_start = if (self.edge_batch_segment_delta_stats != null) storageMonotonicNs(self.io) else 0;
        defer if (self.edge_batch_segment_delta_stats) |delta_stats| {
            delta_stats.overlay_checks += 1;
            delta_stats.overlay_check_ns += storageElapsedNs(self.io, overlay_check_start);
        };
        if (try self.edgeIdSetIntersectsSegmentOverlayAfterEligibility(meta, existing_candidates, candidate_min, candidate_max, edge_segment_summary_current)) return false;
        return true;
    }

    fn edgeIdSetIntersectsTombstones(self: Store, ids_by_id: []const u64) !bool {
        if (ids_by_id.len == 0) return false;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        if (tombstone_header.count == 0) return false;
        var tombstones = try EdgeTombstoneIndexView.open(self);
        defer tombstones.deinit();
        for (ids_by_id) |edge_id| {
            if (try tombstones.contains(edge_id)) return true;
        }
        return false;
    }

    fn edgeSegmentManifestCoveredPhysicalEdges(self: Store, meta: IndexMeta, manifest_edges: u64) !?u64 {
        const physical_edges = try self.visiblePlusTombstoneEdgeCount(meta);
        if (manifest_edges == physical_edges) return physical_edges;
        if (meta.edge_indexed_edges > physical_edges) return null;
        if (manifest_edges == physical_edges - meta.edge_indexed_edges) {
            if (!try self.edgeIndexBaseHeadersMatchMeta(meta)) return null;
            return physical_edges;
        }
        return null;
    }

    fn edgeSegmentManifestCoversVisibleEdges(self: Store, meta: IndexMeta, manifest_edges: u64) !bool {
        if (manifest_edges != meta.edges) return false;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        return tombstone_header.count != 0;
    }

    fn edgeSegmentManifestMatchesMeta(self: Store, meta: IndexMeta) !bool {
        return try self.edgeSegmentManifestMatchesMetaWithTimings(meta, null);
    }

    fn edgeSegmentManifestMatchesMetaWithTimings(self: Store, meta: IndexMeta, timings: ?*PersistentValidateTimings) !bool {
        const manifest_read_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        if (timings) |t| t.edge_segment_manifest_read_ns = storageElapsedNs(self.io, manifest_read_start);
        const manifest_edges = manifest.totalEdgeCount();
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        const physical_edges = try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges);
        const visible_full = tombstone_header.count != 0 and manifest_edges == meta.edges;
        if (physical_edges == null and !visible_full) return false;
        const segment_open_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        var segments = PublishedEdgeSegments.init(self.allocator);
        try segments.openTrustedEntriesForQuery(self.io, manifest.entries.items);
        defer segments.deinit();
        if (timings) |t| t.edge_segment_open_ns = storageElapsedNs(self.io, segment_open_start);
        const segment_digest_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const segment_digest = edgeSegmentManifestOwnedEdgeDigest(manifest.entries.items);
        if (timings) |t| t.edge_segment_digest_ns = storageElapsedNs(self.io, segment_digest_start);
        if (visible_full and segment_digest == meta.edge_digest) return true;
        const covered_edges = physical_edges orelse return false;
        const physical_digest = meta.edge_digest ^ tombstone_header.digest;
        if (manifest_edges == covered_edges) return segment_digest == physical_digest;
        return (meta.edge_index_digest ^ segment_digest) == physical_digest;
    }

    pub fn forEachPublishedEdgeSegmentNeighbor(
        self: Store,
        direction: segment_mod.Direction,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_edges: usize,
        context: anytype,
        comptime callback: fn (@TypeOf(context), segment_mod.EdgeRecord) anyerror!bool,
    ) !?bool {
        var segments = (try self.openPublishedEdgeSegments(self.allocator)) orelse return null;
        defer segments.deinit();
        return try self.forEachOpenedPublishedEdgeSegmentNeighbor(&segments, direction, node_id, rel_filter, max_edges, context, callback);
    }

    pub fn forEachOpenedPublishedEdgeSegmentNeighbor(
        self: Store,
        segments: *PublishedEdgeSegments,
        direction: segment_mod.Direction,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_edges: usize,
        context: anytype,
        comptime callback: fn (@TypeOf(context), segment_mod.EdgeRecord) anyerror!bool,
    ) !bool {
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        if (tombstone_header.count == 0) {
            return try segments.forEachNeighbor(direction, node_id, rel_filter, max_edges, context, callback);
        }
        var tombstone_view = try EdgeTombstoneIndexView.open(self);
        defer tombstone_view.deinit();
        const Wrapper = struct {
            tombstones: *EdgeTombstoneIndexView,
            context: @TypeOf(context),

            fn visit(wrapper: *@This(), edge: segment_mod.EdgeRecord) !bool {
                if (try wrapper.tombstones.contains(edge.edge_id.toInt())) return false;
                return try callback(wrapper.context, edge);
            }
        };
        var wrapper = Wrapper{ .tombstones = &tombstone_view, .context = context };
        return try segments.forEachNeighbor(direction, node_id, rel_filter, max_edges, &wrapper, Wrapper.visit);
    }

    pub fn openPublishedEdgeSegment(self: Store, allocator: std.mem.Allocator) !?segment_mod.ImmutableAdjacencySegment {
        var segments = (try self.openPublishedEdgeSegments(allocator)) orelse return null;
        errdefer segments.deinit();
        if (segments.segments.items.len != 1 or segments.virtual_edges.items.len != 0) {
            segments.deinit();
            return null;
        }
        const segment = segments.segments.items[0];
        segments.segments.clearRetainingCapacity();
        segments.deinit();
        return segment;
    }

    pub fn openPublishedEdgeSegments(self: Store, allocator: std.mem.Allocator) !?PublishedEdgeSegments {
        var manifest = self.readEdgeSegmentManifest(allocator) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer manifest.deinit(allocator);
        const meta = try self.readCurrentIndexMeta();
        if (manifest.totalEdgeCount() != try self.visiblePlusTombstoneEdgeCount(meta)) return null;

        var segments = PublishedEdgeSegments.init(allocator);
        errdefer segments.deinit();
        try segments.openEntries(self.io, manifest.entries.items);
        return segments;
    }

    pub fn openPublishedEdgeSegmentsForQuery(self: Store, allocator: std.mem.Allocator) !?PublishedEdgeSegmentsForQuery {
        return self.openPublishedEdgeSegmentsForQueryFiltered(allocator, null, null);
    }

    pub fn openPublishedEdgeSegmentsForQueryRetained(
        self: Store,
        allocator: std.mem.Allocator,
        registry: *EdgeSegmentRetentionRegistry,
    ) !?PublishedEdgeSegmentsForQuery {
        return self.openPublishedEdgeSegmentsForQueryFilteredRetained(allocator, registry, null, null);
    }

    pub fn openPublishedEdgeSegmentsForQueryForNode(
        self: Store,
        allocator: std.mem.Allocator,
        direction: segment_mod.Direction,
        node_id: core.NodeId,
    ) !?PublishedEdgeSegmentsForQuery {
        return self.openPublishedEdgeSegmentsForQueryFiltered(allocator, direction, node_id);
    }

    pub fn openPublishedEdgeSegmentsForQueryForNodeRetained(
        self: Store,
        allocator: std.mem.Allocator,
        registry: *EdgeSegmentRetentionRegistry,
        direction: segment_mod.Direction,
        node_id: core.NodeId,
    ) !?PublishedEdgeSegmentsForQuery {
        return self.openPublishedEdgeSegmentsForQueryFilteredRetained(allocator, registry, direction, node_id);
    }

    fn openPublishedEdgeSegmentsForQueryFilteredRetained(
        self: Store,
        allocator: std.mem.Allocator,
        registry: *EdgeSegmentRetentionRegistry,
        filter_direction: ?segment_mod.Direction,
        filter_node_id: ?core.NodeId,
    ) !?PublishedEdgeSegmentsForQuery {
        var retention_window = try self.openRegisteredEdgeSegmentRetentionWindow(registry);
        errdefer retention_window.deinit();
        const manifest_path = retention_window.manifest_path orelse {
            retention_window.deinit();
            return null;
        };
        var opened = try self.openPublishedEdgeSegmentsForQueryFilteredAtManifestPath(allocator, manifest_path, filter_direction, filter_node_id);
        if (opened) |*segments_for_query| {
            segments_for_query.retention_window = retention_window;
            return opened;
        }
        retention_window.deinit();
        return null;
    }

    fn openPublishedEdgeSegmentsForQueryFiltered(
        self: Store,
        allocator: std.mem.Allocator,
        filter_direction: ?segment_mod.Direction,
        filter_node_id: ?core.NodeId,
    ) !?PublishedEdgeSegmentsForQuery {
        var manifest = self.readEdgeSegmentManifest(allocator) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer manifest.deinit(allocator);
        return self.openPublishedEdgeSegmentsForQueryFilteredFromManifest(allocator, &manifest, filter_direction, filter_node_id);
    }

    fn openPublishedEdgeSegmentsForQueryFilteredAtManifestPath(
        self: Store,
        allocator: std.mem.Allocator,
        manifest_path: []const u8,
        filter_direction: ?segment_mod.Direction,
        filter_node_id: ?core.NodeId,
    ) !?PublishedEdgeSegmentsForQuery {
        var manifest = try (self.readEdgeSegmentManifestAtPath(allocator, manifest_path) catch |err| switch (err) {
            error.FileNotFound => error.InvalidRecord,
            else => |e| e,
        });
        defer manifest.deinit(allocator);
        return self.openPublishedEdgeSegmentsForQueryFilteredFromManifest(allocator, &manifest, filter_direction, filter_node_id);
    }

    fn openPublishedEdgeSegmentsForQueryFilteredFromManifest(
        self: Store,
        allocator: std.mem.Allocator,
        manifest: *const EdgeSegmentManifest,
        filter_direction: ?segment_mod.Direction,
        filter_node_id: ?core.NodeId,
    ) !?PublishedEdgeSegmentsForQuery {
        const meta = try self.readCurrentIndexMeta();
        const manifest_edges = manifest.totalEdgeCount();
        const physical_edges = try self.visiblePlusTombstoneEdgeCount(meta);
        const coverage: PublishedEdgeSegmentsCoverage = if (manifest_edges == physical_edges)
            .full
        else blk: {
            if (try self.edgeSegmentManifestCoversVisibleEdges(meta, manifest_edges) and try self.edgeSegmentMetaSummaryCurrent(meta)) break :blk .visible_full;
            if (meta.edge_indexed_edges > physical_edges) return null;
            if (manifest_edges != physical_edges - meta.edge_indexed_edges) return null;
            if (!try self.edgeIndexBaseHeadersMatchMeta(meta)) return null;
            break :blk .delta;
        };

        var segments = PublishedEdgeSegments.init(allocator);
        errdefer segments.deinit();
        const filtered = coverage != .visible_full and filter_direction != null and filter_node_id != null and manifest.ranges_trusted;
        const node_id = if (filter_node_id) |id| id.toInt() else 0;
        const segment_capacity = if (filtered) blk: {
            var matching: usize = 0;
            for (manifest.entries.items) |entry| {
                if (edgeSegmentManifestEntryMayContainNode(entry, filter_direction.?, node_id)) matching += 1;
            }
            break :blk matching;
        } else manifest.entries.items.len;
        try segments.segments.ensureTotalCapacityPrecise(allocator, segment_capacity);
        if (self.options.validate_indexes_on_read) {
            for (manifest.entries.items) |entry| {
                if (filtered and !edgeSegmentManifestEntryMayContainNode(entry, filter_direction.?, node_id)) continue;
                try segments.openEntry(self.io, entry);
            }
        } else {
            for (manifest.entries.items) |entry| {
                if (filtered and !edgeSegmentManifestEntryMayContainNode(entry, filter_direction.?, node_id)) continue;
                if (coverage == .visible_full) {
                    try segments.openTrustedEntryForQuery(self.io, entry);
                } else if (filter_direction) |direction| {
                    try segments.openTrustedEntryDirectionForQuery(self.io, entry, direction);
                } else {
                    try segments.openTrustedEntryForQuery(self.io, entry);
                }
            }
        }
        return .{ .segments = segments, .coverage = coverage };
    }

    fn writeEdgeSegmentManifest(
        self: Store,
        segment_dir_path: []const u8,
        edge_digest: u64,
        edge_id_summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
        endpoint_summary: segment_mod.ImmutableAdjacencySegment.EndpointSummary,
        edge_id_order_digest: u64,
        edge_id_runs: EdgeSegmentIdRunSummary,
    ) !EdgeSegmentManifestSummary {
        const entry = EdgeSegmentManifestEntry{
            .edge_count = edge_id_summary.count,
            .edge_digest = edge_digest,
            .edge_id_range = edge_id_summary.range,
            .edge_id_digest = edge_id_summary.digest,
            .edge_id_order_digest = edge_id_order_digest,
            .edge_id_runs = edge_id_runs,
            .src_node_range = endpoint_summary.src_range,
            .dst_node_range = endpoint_summary.dst_range,
            .path = segment_dir_path,
        };
        try self.writeEdgeSegmentManifestEntries(&.{entry});
        return try self.edgeSegmentManifestSummary(&.{entry});
    }

    fn edgeSegmentManifestTotalEdges(entries: []const EdgeSegmentManifestEntry) !u64 {
        var total_edges: u64 = 0;
        for (entries) |entry| {
            if (entry.path.len > std.math.maxInt(u32)) return error.RecordTooLarge;
            if (edgeSegmentManifestEntryIsVirtual(entry)) {
                try edgeSegmentManifestValidateVirtualEntryShape(entry);
            } else if (entry.path.len == 0) return error.RecordTooLarge;
            if (entry.edge_count == 0 or
                entry.edge_id_range.min > entry.edge_id_range.max or
                entry.src_node_range.min > entry.src_node_range.max or
                entry.dst_node_range.min > entry.dst_node_range.max)
            {
                return error.InvalidRecord;
            }
            total_edges = std.math.add(u64, total_edges, entry.edge_count) catch return error.RecordTooLarge;
        }
        return total_edges;
    }

    fn edgeSegmentManifestSummary(self: Store, entries: []const EdgeSegmentManifestEntry) !EdgeSegmentManifestSummary {
        return .{
            .total_edges = try edgeSegmentManifestTotalEdges(entries),
            .manifest_digest = try self.edgeSegmentManifestDigest(entries),
            .edge_id_runs = try edgeSegmentManifestIdRunSummary(self.allocator, entries),
        };
    }

    fn edgeSegmentManifestIdRunSummary(allocator: std.mem.Allocator, entries: anytype) !EdgeSegmentIdRunSummary {
        var stream_builder = EdgeSegmentIdRunBuilder{};
        var previous_max: u64 = 0;
        var has_previous = false;
        var stream_sorted = true;
        for (entries) |entry| {
            const covered_count = try entry.edge_id_runs.coveredCount();
            if (covered_count != entry.edge_count) return .{};
            switch (entry.edge_id_runs.run_count) {
                0 => return .{},
                1 => if (!appendEdgeSegmentManifestRunRangeSorted(
                    &stream_builder,
                    &has_previous,
                    &previous_max,
                    entry.edge_id_runs.first_min,
                    entry.edge_id_runs.first_max,
                )) {
                    stream_sorted = false;
                    break;
                },
                2 => {
                    if (!appendEdgeSegmentManifestRunRangeSorted(
                        &stream_builder,
                        &has_previous,
                        &previous_max,
                        entry.edge_id_runs.first_min,
                        entry.edge_id_runs.first_max,
                    )) {
                        stream_sorted = false;
                        break;
                    }
                    if (!appendEdgeSegmentManifestRunRangeSorted(
                        &stream_builder,
                        &has_previous,
                        &previous_max,
                        entry.edge_id_runs.second_min,
                        entry.edge_id_runs.second_max,
                    )) {
                        stream_sorted = false;
                        break;
                    }
                },
                else => return error.InvalidRecord,
            }
        }
        if (stream_sorted) return stream_builder.finish();

        var ranges = std.ArrayList(EdgeSegmentIdRunRange).empty;
        defer ranges.deinit(allocator);
        const max_ranges = std.math.mul(usize, entries.len, 2) catch return error.RecordTooLarge;
        try ranges.ensureTotalCapacity(allocator, max_ranges);
        for (entries) |entry| {
            const covered_count = try entry.edge_id_runs.coveredCount();
            if (covered_count != entry.edge_count) return .{};
            switch (entry.edge_id_runs.run_count) {
                0 => return .{},
                1 => ranges.appendAssumeCapacity(.{
                    .min = entry.edge_id_runs.first_min,
                    .max = entry.edge_id_runs.first_max,
                }),
                2 => {
                    ranges.appendAssumeCapacity(.{
                        .min = entry.edge_id_runs.first_min,
                        .max = entry.edge_id_runs.first_max,
                    });
                    ranges.appendAssumeCapacity(.{
                        .min = entry.edge_id_runs.second_min,
                        .max = entry.edge_id_runs.second_max,
                    });
                },
                else => return error.InvalidRecord,
            }
        }
        std.mem.sort(EdgeSegmentIdRunRange, ranges.items, {}, edgeSegmentIdRunRangeLessThan);
        var builder = EdgeSegmentIdRunBuilder{};
        for (ranges.items) |range| builder.addRange(range.min, range.max);
        return builder.finish();
    }

    fn setEdgeSegmentSummary(meta: *IndexMeta, summary: EdgeSegmentManifestSummary) void {
        meta.edge_segment_edges = summary.total_edges;
        meta.edge_segment_manifest_digest = summary.manifest_digest;
        meta.edge_segment_id_runs = summary.edge_id_runs;
    }

    fn updateIndexMetaEdgeSegmentSummary(self: Store, summary: EdgeSegmentManifestSummary) !void {
        var meta = try self.readIndexMeta();
        setEdgeSegmentSummary(&meta, summary);
        try self.writeIndexMeta(meta);
    }

    fn writeEdgeSegmentManifestEntries(self: Store, entries: []const EdgeSegmentManifestEntry) !void {
        if (entries.len == 0 or entries.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        const total_edges = try edgeSegmentManifestTotalEdges(entries);
        const epoch_digest = try self.edgeSegmentManifestDigest(entries);
        const epoch_path = try self.edgeSegmentManifestEpochPath(total_edges, epoch_digest);
        defer self.allocator.free(epoch_path);

        // Keep an epoch whenever publication may have crossed the CURRENT
        // rename commit point. A leaked unreferenced manifest is recoverable;
        // CURRENT naming a deleted manifest is not.
        try self.writeEdgeSegmentManifestFile(epoch_path, entries);
        try self.writeEdgeSegmentCurrent(epoch_path);
    }

    fn updateEdgeSegmentManifestDigestFields(hasher: *std.hash.Wyhash, entry: anytype) void {
        var bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &bytes, entry.edge_count, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_digest, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_range.min, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_range.max, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, edgeSegmentManifestLogicalEdgeIdDigest(entry), .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_order_digest, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_runs.run_count, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_runs.first_min, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_runs.first_max, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_runs.second_min, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.edge_id_runs.second_max, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.src_node_range.min, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.src_node_range.max, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.dst_node_range.min, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.dst_node_range.max, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, if (entry.singleton_rel) |rel| @as(u64, @intFromEnum(rel)) else std.math.maxInt(u64), .little);
        hasher.update(&bytes);
    }

    fn updateEdgeSegmentManifestDigestEncodedPath(hasher: *std.hash.Wyhash, path_encoding: EdgeSegmentManifestPathEncoding) void {
        var bytes: [4]u8 = undefined;
        std.mem.writeInt(u32, &bytes, path_encoding.flags, .little);
        hasher.update(&bytes);
        hasher.update(path_encoding.bytes);
    }

    fn edgeSegmentManifestDigest(self: Store, entries: []const EdgeSegmentManifestEntry) !u64 {
        var hasher = std.hash.Wyhash.init(0x544B_4D46);
        for (entries) |entry| {
            updateEdgeSegmentManifestDigestFields(&hasher, entry);
            updateEdgeSegmentManifestDigestEncodedPath(&hasher, try self.edgeSegmentManifestPathEncoding(entry.path));
        }
        return hasher.final();
    }

    fn edgeSegmentManifestOwnedDigest(self: Store, entries: []const OwnedEdgeSegmentManifestEntry) !u64 {
        var hasher = std.hash.Wyhash.init(0x544B_4D46);
        for (entries) |entry| {
            updateEdgeSegmentManifestDigestFields(&hasher, entry);
            updateEdgeSegmentManifestDigestEncodedPath(&hasher, try self.edgeSegmentManifestPathEncoding(entry.path));
        }
        return hasher.final();
    }

    fn edgeSegmentManifestOwnedLegacyDigest(entries: []const OwnedEdgeSegmentManifestEntry) u64 {
        var hasher = std.hash.Wyhash.init(0x544B_4D46);
        for (entries) |entry| {
            updateEdgeSegmentManifestDigestFields(&hasher, entry);
            hasher.update(entry.path);
        }
        return hasher.final();
    }

    fn edgeSegmentManifestOwnedTotalEdges(entries: []const OwnedEdgeSegmentManifestEntry) ?u64 {
        var total: u64 = 0;
        for (entries) |entry| {
            if (edgeSegmentManifestEntryIsVirtual(entry)) {
                edgeSegmentManifestValidateVirtualEntryShape(entry) catch return null;
            } else if (entry.path.len == 0) return null;
            if (entry.edge_count == 0 or
                entry.edge_id_range.min > entry.edge_id_range.max or
                entry.src_node_range.min > entry.src_node_range.max or
                entry.dst_node_range.min > entry.dst_node_range.max)
            {
                return null;
            }
            total = std.math.add(u64, total, entry.edge_count) catch return null;
        }
        return total;
    }

    fn edgeSegmentManifestOwnedEdgeDigest(entries: []const OwnedEdgeSegmentManifestEntry) u64 {
        var digest: u64 = 0;
        for (entries) |entry| digest ^= entry.edge_digest;
        return digest;
    }

    fn edgeSegmentManifestEpochPath(self: Store, total_edges: u64, digest: u64) ![]u8 {
        return try self.edgeSegmentManifestEpochPathWithAllocator(self.allocator, total_edges, digest);
    }

    fn edgeSegmentManifestEpochPathWithAllocator(self: Store, allocator: std.mem.Allocator, total_edges: u64, digest: u64) ![]u8 {
        return std.fmt.allocPrint(allocator, "{s}.{d}.{x}", .{ self.edge_segment_manifest_path, total_edges, digest });
    }

    fn edgeSegmentManifestSegmentRoot(self: Store, allocator: std.mem.Allocator) ![]u8 {
        return try std.fs.path.join(allocator, &.{ self.dir_path, "edge_segments" });
    }

    fn edgeSegmentManifestRelativeSuffix(self: Store, segment_path: []const u8) !?[]const u8 {
        const root = try self.edgeSegmentManifestSegmentRoot(self.allocator);
        defer self.allocator.free(root);
        if (!std.mem.startsWith(u8, segment_path, root)) return null;
        if (segment_path.len <= root.len + 1) return null;
        if (!std.fs.path.isSep(segment_path[root.len])) return null;
        const suffix = segment_path[root.len + 1 ..];
        if (!edgeSegmentManifestSafeRelativePath(suffix)) return null;
        return suffix;
    }

    fn edgeSegmentManifestPathEncoding(self: Store, segment_path: []const u8) !EdgeSegmentManifestPathEncoding {
        if (segment_path.len == 0) return .{ .flags = 0, .bytes = "" };
        if (try self.edgeSegmentManifestRelativeSuffix(segment_path)) |suffix| {
            return .{ .flags = edge_segment_manifest_path_relative, .bytes = suffix };
        }
        return .{ .flags = 0, .bytes = segment_path };
    }

    fn restoreEdgeSegmentManifestPath(self: Store, allocator: std.mem.Allocator, flags: u32, stored_path: []const u8) ![]u8 {
        if ((flags & edge_segment_manifest_path_relative) == 0) {
            if (try self.edgeSegmentManifestRelativeSuffix(stored_path) != null) return error.InvalidRecord;
            return try allocator.dupe(u8, stored_path);
        }
        if (!edgeSegmentManifestSafeRelativePath(stored_path)) return error.InvalidRecord;
        const root = try self.edgeSegmentManifestSegmentRoot(allocator);
        defer allocator.free(root);
        return try std.fs.path.join(allocator, &.{ root, stored_path });
    }

    fn writeEdgeSegmentManifestFile(self: Store, manifest_path: []const u8, entries: []const EdgeSegmentManifestEntry) !void {
        const tmp_path = try self.tmpPathFor(manifest_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            var offset: u64 = 0;
            var header: [EdgeSegmentManifest.header_len]u8 = undefined;
            try encodeEdgeSegmentManifestHeader(entries, &header);
            try file.writePositionalAll(self.io, &header, offset);
            offset += header.len;

            var entry_header: [EdgeSegmentManifest.entry_header_len]u8 = undefined;
            for (entries) |entry| {
                const path_encoding = try self.edgeSegmentManifestPathEncoding(entry.path);
                try encodeEdgeSegmentManifestEntryHeaderForPath(entry, path_encoding.bytes.len, path_encoding.flags, &entry_header);
                try file.writePositionalAll(self.io, &entry_header, offset);
                offset += entry_header.len;
                var edge_digest_bytes: [8]u8 = undefined;
                std.mem.writeInt(u64, &edge_digest_bytes, entry.edge_digest, .little);
                try file.writePositionalAll(self.io, &edge_digest_bytes, offset);
                offset += edge_digest_bytes.len;
                const entry_flags = std.mem.readInt(u32, entry_header[4..8], .little);
                offset = try writeEdgeSegmentManifestOrderDigestExtra(self.io, file, offset, entry, entry_flags);
                offset = try writeEdgeSegmentManifestRunExtra(self.io, file, offset, try encodeEdgeSegmentManifestRunEncoding(entry));
                offset = try writeEdgeSegmentManifestEdgeCountExtra(self.io, file, offset, entry, entry_flags);
                offset = try writeEdgeSegmentManifestDigestExtra(self.io, file, offset, entry, entry_flags);
                offset = try writeEdgeSegmentManifestEndpointExtra(self.io, file, offset, try encodeEdgeSegmentManifestEndpointEncoding(entry));
                offset = try writeEdgeSegmentManifestSingletonRelExtra(self.io, file, offset, entry, entry_flags);
                try file.writePositionalAll(self.io, path_encoding.bytes, offset);
                offset = std.math.add(u64, offset, path_encoding.bytes.len) catch return error.RecordTooLarge;
            }
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, manifest_path);
    }

    fn edgeSegmentIdIndexPath(self: Store, segment_dir_path: []const u8) ![]u8 {
        return std.fs.path.join(self.allocator, &.{ segment_dir_path, "edge_ids.idx" });
    }

    fn writeEdgeSegmentIdIndexFromSegment(
        self: Store,
        segment_dir_path: []const u8,
        segment: *segment_mod.ImmutableAdjacencySegment,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    ) !EdgeSegmentIdSidecarSummary {
        if (try edgeSegmentIdSidecarSummaryFromCompleteRange(summary)) |sidecar_summary| return sidecar_summary;

        const pid = currentProcessIdForTempPath();
        const nonce = store_temp_nonce.fetchAdd(1, .monotonic);
        const spool_path = try std.fmt.allocPrint(self.allocator, "{s}/.edge-id-sidecar-spool-{d}-{d}.tmp", .{
            segment_dir_path,
            pid,
            nonce,
        });
        defer self.allocator.free(spool_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, spool_path) catch {};

        {
            var spool_file = try std.Io.Dir.cwd().createFile(self.io, spool_path, .{ .read = true, .truncate = true });
            defer spool_file.close(self.io);
            const spool_size = std.math.mul(u64, summary.count, 8) catch return error.RecordTooLarge;
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, spool_file, try storageWriteBufferCapacity(spool_size));
            defer writer.deinit();

            var written: u64 = 0;
            var min_seen: u64 = std.math.maxInt(u64);
            var max_seen: u64 = 0;
            var digest: u64 = 0;
            var id_bytes: [8]u8 = undefined;
            var iter = try segment.edgeIterator(.forward);
            while (try iter.next()) |edge| {
                const edge_id = edge.edge_id.toInt();
                if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
                std.mem.writeInt(u64, &id_bytes, edge_id, .little);
                try writer.append(&id_bytes);
                written += 1;
                min_seen = @min(min_seen, edge_id);
                max_seen = @max(max_seen, edge_id);
                digest ^= edgeSegmentIdDigest(edge_id);
            }
            if (written != summary.count) return error.InvalidRecord;
            if (min_seen != summary.range.min or max_seen != summary.range.max) return error.InvalidRecord;
            if (digest != summary.digest) return error.InvalidRecord;
            try writer.flush();
            if (try writer.position() != spool_size) return error.InvalidRecord;
            if (try self.regularFileSize(spool_file) != spool_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try spool_file.sync(self.io);
        }

        if (summary.count <= edge_segment_id_sort_chunk_records) {
            const sidecar_summary = try self.writeEdgeSegmentIdIndexFromSingleSpoolChunk(segment_dir_path, spool_path, summary);
            std.Io.Dir.cwd().deleteFile(self.io, spool_path) catch {};
            return sidecar_summary;
        }

        var runs = try self.buildEdgeSegmentIdSortedRunsFromSpool(segment_dir_path, spool_path, summary.count, nonce);
        defer runs.deinit();
        const sidecar_summary = try self.writeEdgeSegmentIdIndexFromRunFiles(segment_dir_path, runs.paths.items, summary);
        std.Io.Dir.cwd().deleteFile(self.io, spool_path) catch {};
        return sidecar_summary;
    }

    const EdgeSegmentIdRunSet = struct {
        allocator: std.mem.Allocator,
        store: Store,
        paths: std.ArrayList([]u8) = .empty,

        fn deinit(self: *EdgeSegmentIdRunSet) void {
            for (self.paths.items) |path| {
                std.Io.Dir.cwd().deleteFile(self.store.io, path) catch {};
                self.allocator.free(path);
            }
            self.paths.deinit(self.allocator);
        }
    };

    fn buildEdgeSegmentIdSortedRunsFromSpool(
        self: Store,
        segment_dir_path: []const u8,
        spool_path: []const u8,
        record_count: u64,
        nonce: u64,
    ) !EdgeSegmentIdRunSet {
        const record_count_usize = std.math.cast(usize, record_count) orelse return error.RecordTooLarge;
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, record_count, 8) catch return error.RecordTooLarge;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var runs = EdgeSegmentIdRunSet{ .allocator = self.allocator, .store = self };
        errdefer runs.deinit();

        var chunk = std.ArrayList(u64).empty;
        defer chunk.deinit(self.allocator);
        const max_chunk_records = @min(record_count_usize, edge_segment_id_sort_chunk_records);
        try chunk.ensureTotalCapacityPrecise(self.allocator, max_chunk_records);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, max_chunk_records, 8) catch return error.RecordTooLarge);
        defer self.allocator.free(chunk_bytes);

        const pid = currentProcessIdForTempPath();
        var read_pos: usize = 0;
        while (read_pos < record_count_usize) {
            chunk.clearRetainingCapacity();
            const take = @min(edge_segment_id_sort_chunk_records, record_count_usize - read_pos);
            try self.readEdgeSegmentIdSpoolChunk(spool_file, read_pos, take, chunk_bytes, &chunk);
            std.mem.sort(u64, chunk.items, {}, u64LessThan);
            const run_path = try std.fmt.allocPrint(self.allocator, "{s}/.edge-id-sidecar-run-{d}-{d}-{d}.tmp", .{
                segment_dir_path,
                pid,
                nonce,
                runs.paths.items.len,
            });
            var run_path_owned = true;
            errdefer {
                std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
                if (run_path_owned) self.allocator.free(run_path);
            }
            try self.writeEdgeSegmentIdRunFile(run_path, chunk.items);
            try runs.paths.append(self.allocator, run_path);
            run_path_owned = false;
            read_pos += take;
        }
        if (runs.paths.items.len == 0) return error.InvalidRecord;
        return runs;
    }

    fn readEdgeSegmentIdSpoolChunk(self: Store, file: std.Io.File, start_index: usize, record_count: usize, buffer: []u8, out: *std.ArrayList(u64)) !void {
        const byte_count = std.math.mul(usize, record_count, 8) catch return error.RecordTooLarge;
        if (byte_count > buffer.len) return error.InvalidRecord;
        const offset = std.math.mul(u64, @intCast(start_index), 8) catch return error.RecordTooLarge;
        const n = try file.readPositionalAll(self.io, buffer[0..byte_count], offset);
        if (n != byte_count) return error.InvalidRecord;
        var cursor: usize = 0;
        while (cursor < byte_count) : (cursor += 8) {
            var id_bytes: [8]u8 = undefined;
            @memcpy(&id_bytes, buffer[cursor .. cursor + 8]);
            const edge_id = std.mem.readInt(u64, &id_bytes, .little);
            if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            out.appendAssumeCapacity(edge_id);
        }
    }

    fn writeEdgeSegmentIdIndexFromSingleSpoolChunk(
        self: Store,
        segment_dir_path: []const u8,
        spool_path: []const u8,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    ) !EdgeSegmentIdSidecarSummary {
        if (summary.count == 0) return error.InvalidRecord;
        const record_count_usize = std.math.cast(usize, summary.count) orelse return error.RecordTooLarge;
        if (record_count_usize > edge_segment_id_sort_chunk_records) return error.InvalidRecord;
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, summary.count, 8) catch return error.RecordTooLarge;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var edge_ids = std.ArrayList(u64).empty;
        defer edge_ids.deinit(self.allocator);
        try edge_ids.ensureTotalCapacityPrecise(self.allocator, record_count_usize);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, record_count_usize, 8) catch return error.RecordTooLarge);
        defer self.allocator.free(chunk_bytes);

        try self.readEdgeSegmentIdSpoolChunk(spool_file, 0, record_count_usize, chunk_bytes, &edge_ids);
        std.mem.sort(u64, edge_ids.items, {}, u64LessThan);
        return try self.writeEdgeSegmentIdIndexFromSortedIds(segment_dir_path, edge_ids.items, summary);
    }

    fn writeEdgeSegmentIdIndexFromSortedIds(
        self: Store,
        segment_dir_path: []const u8,
        edge_ids: []const u64,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    ) !EdgeSegmentIdSidecarSummary {
        if (@as(u64, @intCast(edge_ids.len)) != summary.count) return error.InvalidRecord;
        if (edge_ids.len == 0) return error.InvalidRecord;

        var previous: u64 = 0;
        var min_seen: u64 = std.math.maxInt(u64);
        var max_seen: u64 = 0;
        var digest: u64 = 0;
        var order_digest: u64 = 0;
        var run_builder = EdgeSegmentIdRunBuilder{};
        for (edge_ids, 0..) |edge_id, index| {
            if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            if (index != 0 and edge_id <= previous) return error.InvalidRecord;
            previous = edge_id;
            min_seen = @min(min_seen, edge_id);
            max_seen = @max(max_seen, edge_id);
            digest ^= edgeSegmentIdDigest(edge_id);
            order_digest ^= edgeSegmentIdIndexOrderDigestAt(index, edge_id);
            run_builder.add(edge_id);
        }
        if (min_seen != summary.range.min or max_seen != summary.range.max) return error.InvalidRecord;
        if (digest != summary.digest) return error.InvalidRecord;

        const final_runs = run_builder.finish();
        if (try edgeSegmentIdSidecarSummaryFromCompleteRuns(summary, final_runs)) |sidecar_summary| return sidecar_summary;

        const path = try self.edgeSegmentIdIndexPath(segment_dir_path);
        defer self.allocator.free(path);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            var writer = try self.beginEdgeSegmentIdIndexFile(file, summary, order_digest);
            for (edge_ids, 0..) |edge_id, index| {
                try writer.write(self, index, edge_id);
            }
            try writer.finish(self);
        }
        try self.renameReplace(tmp_path, path);
        return .{
            .edge_id_order_digest = order_digest,
            .edge_id_runs = final_runs,
        };
    }

    fn writeEdgeSegmentIdRunFile(self: Store, path: []const u8, edge_ids: []const u64) !void {
        const expected_size = std.math.mul(u64, @intCast(edge_ids.len), 8) catch return error.RecordTooLarge;
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{ .read = true, .truncate = true });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();
        var previous: u64 = 0;
        var id_bytes: [8]u8 = undefined;
        for (edge_ids, 0..) |edge_id, index| {
            if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            if (index != 0 and edge_id <= previous) return error.InvalidRecord;
            previous = edge_id;
            std.mem.writeInt(u64, &id_bytes, edge_id, .little);
            try writer.append(&id_bytes);
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn writeEdgeSegmentIdIndexFromRunFiles(
        self: Store,
        segment_dir_path: []const u8,
        run_paths: []const []const u8,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    ) !EdgeSegmentIdSidecarSummary {
        if (run_paths.len == 0) return error.InvalidRecord;
        const path = try self.edgeSegmentIdIndexPath(segment_dir_path);
        defer self.allocator.free(path);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var readers = std.ArrayList(EdgeSegmentIdIndexRunReader).empty;
        defer {
            for (readers.items) |*reader| reader.deinit(self.allocator, self.io);
            readers.deinit(self.allocator);
        }
        try readers.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        var queue = std.PriorityQueue(EdgeSegmentIdIndexRunHeapEntry, void, compareEdgeSegmentIdIndexRunHeapEntry).initContext({});
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        for (run_paths) |run_path| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, run_path, .{});
            errdefer run_file.close(self.io);
            const run_size = try self.regularFileSize(run_file);
            if (run_size == 0 or run_size % 8 != 0) return error.InvalidRecord;
            var map = openReadOnlyMemoryMap(self.io, run_file, run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            var buffer: []u8 = &.{};
            errdefer self.allocator.free(buffer);
            if (map == null) {
                buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(run_size));
            }
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .base_offset = 0,
                .next_index = 0,
                .count = run_size / 8,
                .buffer = buffer,
                .file_offset = 0,
            });
            map = null;
            buffer = &.{};
            const first = (try readers.items[reader_index].next(self)) orelse return error.InvalidRecord;
            try queue.push(self.allocator, .{ .run_index = reader_index, .edge_id = first });
        }

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
        defer file.close(self.io);
        const expected_size = try edgeSegmentIdIndexFileSize(summary.count);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();
        var placeholder_header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, 0, &placeholder_header);
        try writer.append(&placeholder_header);

        var written: u64 = 0;
        var digest: u64 = 0;
        var order_digest: u64 = 0;
        var run_builder = EdgeSegmentIdRunBuilder{};
        var previous: u64 = 0;
        var min_seen: u64 = std.math.maxInt(u64);
        var max_seen: u64 = 0;
        while (queue.pop()) |entry| {
            if (entry.edge_id == 0 or entry.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            if (written != 0 and entry.edge_id <= previous) return error.InvalidRecord;
            previous = entry.edge_id;
            min_seen = @min(min_seen, entry.edge_id);
            max_seen = @max(max_seen, entry.edge_id);
            digest ^= edgeSegmentIdDigest(entry.edge_id);
            run_builder.add(entry.edge_id);
            const order_index = std.math.cast(usize, written) orelse return error.RecordTooLarge;
            order_digest ^= edgeSegmentIdIndexOrderDigestAt(order_index, entry.edge_id);

            var id_bytes: [8]u8 = undefined;
            std.mem.writeInt(u64, &id_bytes, entry.edge_id, .little);
            try writer.append(&id_bytes);
            written += 1;

            const reader = &readers.items[entry.run_index];
            if (try reader.next(self)) |next_id| {
                try queue.push(self.allocator, .{ .run_index = entry.run_index, .edge_id = next_id });
            }
        }

        if (written != summary.count) return error.InvalidRecord;
        if (min_seen != summary.range.min or max_seen != summary.range.max) return error.InvalidRecord;
        if (digest != summary.digest) return error.InvalidRecord;
        const final_runs = run_builder.finish();
        if (try edgeSegmentIdSidecarSummaryFromCompleteRuns(summary, final_runs)) |sidecar_summary| {
            std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
            return sidecar_summary;
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var final_header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, order_digest, &final_header);
        try file.writePositionalAll(self.io, &final_header, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
        return .{
            .edge_id_order_digest = order_digest,
            .edge_id_runs = final_runs,
        };
    }

    fn writeEdgeSegmentIdIndexFromRecords(
        self: Store,
        segment_dir_path: []const u8,
        records_by_id: []const EdgeIndexRecord,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
        edge_id_order_digest: u64,
    ) !EdgeSegmentIdSidecarSummary {
        if (records_by_id.len != summary.count) return error.InvalidRecord;
        const runs = edgeSegmentIdRunSummaryFromRecords(records_by_id);
        if (try edgeSegmentIdSidecarSummaryFromCompleteRuns(summary, runs)) |sidecar_summary| return sidecar_summary;

        const path = try self.edgeSegmentIdIndexPath(segment_dir_path);
        defer self.allocator.free(path);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            var writer = try self.beginEdgeSegmentIdIndexFile(file, summary, edge_id_order_digest);
            for (records_by_id, 0..) |record, index| {
                try writer.write(self, index, record.edge_id);
            }
            try writer.finish(self);
        }
        try self.renameReplace(tmp_path, path);
        return .{
            .edge_id_order_digest = edge_id_order_digest,
            .edge_id_runs = runs,
        };
    }

    fn writeEdgeSegmentIdIndexFromEdgeIndexReader(
        self: Store,
        segment_dir_path: []const u8,
        reader: *EdgeIndexRecordReader,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    ) !EdgeSegmentIdSidecarSummary {
        if (reader.edge_count != summary.count) return error.InvalidRecord;
        if (try edgeSegmentIdSidecarSummaryFromCompleteRange(summary)) |sidecar_summary| return sidecar_summary;

        const path = try self.edgeSegmentIdIndexPath(segment_dir_path);
        defer self.allocator.free(path);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
        defer file.close(self.io);
        const expected_size = try edgeSegmentIdIndexFileSize(summary.count);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var placeholder_header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, 0, &placeholder_header);
        try writer.append(&placeholder_header);

        var written: u64 = 0;
        var previous: u64 = 0;
        var min_seen: u64 = std.math.maxInt(u64);
        var max_seen: u64 = 0;
        var digest: u64 = 0;
        var order_digest: u64 = 0;
        var run_builder = EdgeSegmentIdRunBuilder{};
        while (written < reader.edge_count) : (written += 1) {
            const record = try reader.read(written);
            const edge_id = record.edge_id;
            if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            if (written != 0 and edge_id <= previous) return error.InvalidRecord;
            previous = edge_id;
            min_seen = @min(min_seen, edge_id);
            max_seen = @max(max_seen, edge_id);
            digest ^= edgeSegmentIdDigest(edge_id);
            run_builder.add(edge_id);
            const order_index = std.math.cast(usize, written) orelse return error.RecordTooLarge;
            order_digest ^= edgeSegmentIdIndexOrderDigestAt(order_index, edge_id);

            var id_bytes: [8]u8 = undefined;
            std.mem.writeInt(u64, &id_bytes, edge_id, .little);
            try writer.append(&id_bytes);
        }

        if (written != summary.count) return error.InvalidRecord;
        if (min_seen != summary.range.min or max_seen != summary.range.max) return error.InvalidRecord;
        if (digest != summary.digest) return error.InvalidRecord;
        const final_runs = run_builder.finish();
        if (try edgeSegmentIdSidecarSummaryFromCompleteRuns(summary, final_runs)) |sidecar_summary| {
            std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
            return sidecar_summary;
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var final_header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, order_digest, &final_header);
        try file.writePositionalAll(self.io, &final_header, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
        return .{
            .edge_id_order_digest = order_digest,
            .edge_id_runs = final_runs,
        };
    }

    const EdgeSegmentIdIndexRunReader = struct {
        file: ?std.Io.File = null,
        map: ?std.Io.File.MemoryMap = null,
        base_offset: u64 = EdgeSegmentIdIndex.header_len,
        next_index: u64,
        count: u64,
        buffer: []u8 = &.{},
        file_offset: u64 = EdgeSegmentIdIndex.header_len,
        cursor: usize = 0,
        len: usize = 0,
        synthetic_runs: EdgeSegmentIdRunSummary = .{},
        synthetic_next: u64 = 0,

        fn initSynthetic(runs: EdgeSegmentIdRunSummary, expected_count: u64) !EdgeSegmentIdIndexRunReader {
            try runs.validate();
            if (runs.run_count == 0) return error.InvalidRecord;
            if (try runs.coveredCount() != expected_count) return error.InvalidRecord;
            return .{
                .next_index = 0,
                .count = expected_count,
                .synthetic_runs = runs,
                .synthetic_next = runs.first_min,
            };
        }

        fn deinit(self: *EdgeSegmentIdIndexRunReader, allocator: std.mem.Allocator, io: std.Io) void {
            allocator.free(self.buffer);
            if (self.map) |*map| map.destroy(io);
            if (self.file) |file| file.close(io);
        }

        fn refill(self: *EdgeSegmentIdIndexRunReader, store: Store) !void {
            const file = self.file orelse return error.InvalidRecord;
            const n = try file.readPositionalAll(store.io, self.buffer, self.file_offset);
            if (n == 0) return error.InvalidRecord;
            self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
            self.cursor = 0;
            self.len = n;
        }

        fn readBytes(self: *EdgeSegmentIdIndexRunReader, store: Store, out: []u8) !void {
            var written: usize = 0;
            while (written < out.len) {
                if (self.cursor == self.len) try self.refill(store);
                const available = self.len - self.cursor;
                const n = @min(available, out.len - written);
                @memcpy(out[written .. written + n], self.buffer[self.cursor .. self.cursor + n]);
                self.cursor += n;
                written += n;
            }
        }

        fn next(self: *EdgeSegmentIdIndexRunReader, store: Store) !?u64 {
            if (self.next_index >= self.count) return null;
            if (self.synthetic_runs.run_count != 0) return try self.nextSynthetic();
            const edge_id = if (self.map) |*map| id: {
                const byte_index = std.math.mul(u64, self.next_index, 8) catch return error.RecordTooLarge;
                const offset = std.math.add(u64, self.base_offset, byte_index) catch return error.RecordTooLarge;
                const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
                const end = std.math.add(usize, start, 8) catch return error.InvalidRecord;
                if (end > map.memory.len) return error.InvalidRecord;
                break :id std.mem.readInt(u64, map.memory[start..end][0..8], .little);
            } else id: {
                if (self.cursor == self.len) try self.refill(store);
                if (self.len - self.cursor >= 8) {
                    var id_bytes: [8]u8 = undefined;
                    @memcpy(&id_bytes, self.buffer[self.cursor .. self.cursor + 8]);
                    self.cursor += 8;
                    break :id std.mem.readInt(u64, &id_bytes, .little);
                }
                var id_bytes: [8]u8 = undefined;
                try self.readBytes(store, &id_bytes);
                break :id std.mem.readInt(u64, &id_bytes, .little);
            };
            self.next_index += 1;
            return edge_id;
        }

        fn nextSynthetic(self: *EdgeSegmentIdIndexRunReader) !?u64 {
            if (self.next_index >= self.count) return null;
            const runs = self.synthetic_runs;
            if (runs.run_count == 0) return error.InvalidRecord;
            const edge_id = self.synthetic_next;
            if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            if (edge_id >= runs.first_min and edge_id <= runs.first_max) {
                if (edge_id == runs.first_max and runs.run_count == 2) {
                    self.synthetic_next = runs.second_min;
                } else if (edge_id != runs.first_max) {
                    self.synthetic_next = edge_id + 1;
                }
            } else if (runs.run_count == 2 and edge_id >= runs.second_min and edge_id <= runs.second_max) {
                if (edge_id != runs.second_max) self.synthetic_next = edge_id + 1;
            } else {
                return error.InvalidRecord;
            }
            self.next_index += 1;
            return edge_id;
        }
    };

    const EdgeSegmentIdIndexRunHeapEntry = struct {
        run_index: usize,
        edge_id: u64,
    };

    fn compareEdgeSegmentIdIndexRunHeapEntry(_: void, lhs: EdgeSegmentIdIndexRunHeapEntry, rhs: EdgeSegmentIdIndexRunHeapEntry) std.math.Order {
        const id_order = std.math.order(lhs.edge_id, rhs.edge_id);
        if (id_order != .eq) return id_order;
        return std.math.order(lhs.run_index, rhs.run_index);
    }

    fn writeEdgeSegmentIdIndexFromManifestEntries(
        self: Store,
        segment_dir_path: []const u8,
        entries: []const OwnedEdgeSegmentManifestEntry,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    ) !EdgeSegmentIdSidecarSummary {
        if (entries.len == 0) return error.InvalidRecord;
        const manifest_runs = try edgeSegmentManifestIdRunSummary(self.allocator, entries);
        if (try edgeSegmentIdSidecarSummaryFromCompleteRuns(summary, manifest_runs)) |sidecar_summary| return sidecar_summary;

        const path = try self.edgeSegmentIdIndexPath(segment_dir_path);
        defer self.allocator.free(path);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var readers = std.ArrayList(EdgeSegmentIdIndexRunReader).empty;
        defer {
            for (readers.items) |*reader| reader.deinit(self.allocator, self.io);
            readers.deinit(self.allocator);
        }
        try readers.ensureTotalCapacityPrecise(self.allocator, entries.len);

        var queue = std.PriorityQueue(EdgeSegmentIdIndexRunHeapEntry, void, compareEdgeSegmentIdIndexRunHeapEntry).initContext({});
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, entries.len);

        for (entries) |entry| {
            if (entry.edge_id_order_digest == 0) {
                try validateTrustedRunSummary(entry);
                const reader_index = readers.items.len;
                readers.appendAssumeCapacity(try EdgeSegmentIdIndexRunReader.initSynthetic(entry.edge_id_runs, entry.edge_count));
                const first = (try readers.items[reader_index].next(self)) orelse return error.InvalidRecord;
                try queue.push(self.allocator, .{
                    .run_index = reader_index,
                    .edge_id = first,
                });
                continue;
            }

            const entry_path = try self.edgeSegmentIdIndexPath(entry.path);
            defer self.allocator.free(entry_path);
            var entry_file = try std.Io.Dir.cwd().openFile(self.io, entry_path, .{});
            errdefer entry_file.close(self.io);
            const header = try self.validateEdgeSegmentIdIndexHeader(entry_file, entry);
            const file_size = try edgeSegmentIdIndexFileSize(header.edge_count);
            var map = openReadOnlyMemoryMap(self.io, entry_file, file_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            const payload_size = std.math.mul(u64, header.edge_count, 8) catch return error.RecordTooLarge;
            var buffer: []u8 = &.{};
            errdefer self.allocator.free(buffer);
            if (map == null) {
                buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(payload_size));
            }
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = entry_file,
                .map = map,
                .base_offset = EdgeSegmentIdIndex.header_len,
                .next_index = 0,
                .count = header.edge_count,
                .buffer = buffer,
                .file_offset = EdgeSegmentIdIndex.header_len,
            });
            map = null;
            buffer = &.{};
            const first = (try readers.items[reader_index].next(self)) orelse return error.InvalidRecord;
            try queue.push(self.allocator, .{
                .run_index = reader_index,
                .edge_id = first,
            });
        }

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
        defer file.close(self.io);
        const expected_size = try edgeSegmentIdIndexFileSize(summary.count);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();
        var placeholder_header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, 0, &placeholder_header);
        try writer.append(&placeholder_header);

        var written: u64 = 0;
        var digest: u64 = 0;
        var order_digest: u64 = 0;
        var run_builder = EdgeSegmentIdRunBuilder{};
        var previous: u64 = 0;
        var min_seen: u64 = std.math.maxInt(u64);
        var max_seen: u64 = 0;
        while (queue.pop()) |entry| {
            if (entry.edge_id == 0 or entry.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
            if (written != 0 and entry.edge_id <= previous) return error.InvalidRecord;
            previous = entry.edge_id;
            min_seen = @min(min_seen, entry.edge_id);
            max_seen = @max(max_seen, entry.edge_id);
            digest ^= edgeSegmentIdDigest(entry.edge_id);
            run_builder.add(entry.edge_id);
            const order_index = std.math.cast(usize, written) orelse return error.RecordTooLarge;
            order_digest ^= edgeSegmentIdIndexOrderDigestAt(order_index, entry.edge_id);

            var id_bytes: [8]u8 = undefined;
            std.mem.writeInt(u64, &id_bytes, entry.edge_id, .little);
            try writer.append(&id_bytes);
            written += 1;

            const reader = &readers.items[entry.run_index];
            if (try reader.next(self)) |next_id| {
                try queue.push(self.allocator, .{
                    .run_index = entry.run_index,
                    .edge_id = next_id,
                });
            }
        }

        if (written != summary.count) return error.InvalidRecord;
        if (min_seen != summary.range.min or max_seen != summary.range.max) return error.InvalidRecord;
        if (digest != summary.digest) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var final_header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, order_digest, &final_header);
        try file.writePositionalAll(self.io, &final_header, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
        return .{
            .edge_id_order_digest = order_digest,
            .edge_id_runs = run_builder.finish(),
        };
    }

    fn beginEdgeSegmentIdIndexFile(
        self: Store,
        file: std.Io.File,
        summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
        edge_id_order_digest: u64,
    ) !EdgeSegmentIdIndexWriter {
        var header: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        encodeEdgeSegmentIdIndexHeader(summary, edge_id_order_digest, &header);
        try file.writePositionalAll(self.io, &header, 0);
        return .{
            .file = file,
            .summary = summary,
            .edge_id_order_digest = edge_id_order_digest,
        };
    }

    fn edgeSegmentIdIndexContains(self: Store, entry: OwnedEdgeSegmentManifestEntry, edge_id: u64) !?bool {
        if (entry.edge_id_order_digest == 0) return null;
        const path = try self.edgeSegmentIdIndexPath(entry.path);
        defer self.allocator.free(path);
        var file = std.Io.Dir.cwd().openFile(self.io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);
        const header = try self.validateEdgeSegmentIdIndexHeader(file, entry);
        return try self.edgeSegmentIdIndexContainsInFile(file, header.edge_count, edge_id);
    }

    fn edgeSegmentIdIndexIntersects(self: Store, entry: OwnedEdgeSegmentManifestEntry, ids_by_id: []const u64) !?bool {
        if (entry.edge_id_order_digest == 0) return null;
        const path = try self.edgeSegmentIdIndexPath(entry.path);
        defer self.allocator.free(path);
        var file = std.Io.Dir.cwd().openFile(self.io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);
        const header = try self.validateEdgeSegmentIdIndexHeader(file, entry);
        return try self.edgeSegmentIdIndexIntersectsSortedInFile(file, header, ids_by_id, entry.edge_id_range);
    }

    fn trustedSingletonEdgeSegmentId(entry: OwnedEdgeSegmentManifestEntry) !?u64 {
        if (entry.edge_count != 1) return null;
        if (entry.edge_id_range.min == 0 or entry.edge_id_range.max == std.math.maxInt(u64)) return error.InvalidRecord;
        if (entry.edge_id_range.min != entry.edge_id_range.max) return error.InvalidRecord;
        const edge_id = entry.edge_id_range.min;
        if (entry.edge_id_digest == 0 and edgeSegmentManifestCanDeriveEdgeIdDigest(entry)) {
            try validateTrustedRunSummary(entry);
        } else if (entry.edge_id_digest != edgeSegmentIdDigest(edge_id)) return error.InvalidRecord;
        if (entry.edge_id_order_digest != 0 and entry.edge_id_order_digest != edgeSegmentIdIndexOrderDigestAt(0, edge_id)) {
            return error.InvalidRecord;
        }
        return edge_id;
    }

    fn trustedRunSummaryMayIntersect(entry: OwnedEdgeSegmentManifestEntry, ids_by_id: []const u64) !?bool {
        if (entry.edge_id_runs.run_count == 0) return null;
        if (entry.edge_id_runs.run_count > 2) return error.InvalidRecord;
        try validateTrustedRunSummary(entry);
        if (sortedSetIntersectsRange(ids_by_id, entry.edge_id_runs.first_min, entry.edge_id_runs.first_max)) return true;
        if (entry.edge_id_runs.run_count == 2 and sortedSetIntersectsRange(ids_by_id, entry.edge_id_runs.second_min, entry.edge_id_runs.second_max)) return true;
        return false;
    }

    fn validateTrustedRunSummary(entry: OwnedEdgeSegmentManifestEntry) !void {
        if (entry.edge_id_runs.run_count == 0) return;
        if (!edgeSegmentManifestRunsCoverEntry(entry.edge_count, entry.edge_id_range, entry.edge_id_runs)) return error.InvalidRecord;
    }

    fn validateEdgeSegmentIdIndexHeader(self: Store, file: std.Io.File, entry: OwnedEdgeSegmentManifestEntry) !EdgeSegmentIdIndexHeader {
        const file_size = try self.regularFileSize(file);
        if (file_size != try edgeSegmentIdIndexFileSize(entry.edge_count)) return error.InvalidRecord;
        var header_bytes: [EdgeSegmentIdIndex.header_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &header_bytes, 0);
        if (n != header_bytes.len) return error.InvalidRecord;
        const header = try decodeEdgeSegmentIdIndexHeader(&header_bytes);
        if (header.edge_count != entry.edge_count) return error.InvalidRecord;
        if (header.edge_id_min != entry.edge_id_range.min) return error.InvalidRecord;
        if (header.edge_id_max != entry.edge_id_range.max) return error.InvalidRecord;
        if (header.edge_id_digest != entry.edge_id_digest) return error.InvalidRecord;
        if (header.edge_id_order_digest != entry.edge_id_order_digest) return error.InvalidRecord;
        return header;
    }

    fn edgeSegmentIdIndexContainsInFile(self: Store, file: std.Io.File, edge_count: u64, edge_id: u64) !bool {
        const lo = try self.edgeSegmentIdIndexLowerBoundInFile(file, edge_count, edge_id);
        if (lo >= edge_count) return false;
        return try self.readEdgeSegmentIdIndexRecordAt(file, lo) == edge_id;
    }

    fn edgeSegmentIdIndexIntersectsSortedInFile(
        self: Store,
        file: std.Io.File,
        header: EdgeSegmentIdIndexHeader,
        ids_by_id: []const u64,
        range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    ) !bool {
        var id_index = lowerBoundU64(ids_by_id, range.min);
        if (id_index >= ids_by_id.len or ids_by_id[id_index] > range.max) return false;

        if (header.edge_count <= edge_segment_id_index_stack_scan_max) {
            return try self.edgeSegmentIdIndexIntersectsSmallSortedInFile(file, header, ids_by_id[id_index..], range);
        }

        var side_index = try self.edgeSegmentIdIndexLowerBoundInFile(file, header.edge_count, ids_by_id[id_index]);
        while (id_index < ids_by_id.len and ids_by_id[id_index] <= range.max and side_index < header.edge_count) {
            const current = try self.readEdgeSegmentIdIndexRecordAt(file, side_index);
            const candidate = ids_by_id[id_index];
            if (current == candidate) return true;
            if (current < candidate) {
                side_index = try self.edgeSegmentIdIndexLowerBoundInFileFrom(file, header.edge_count, candidate, side_index + 1);
                continue;
            }

            id_index += 1;
            while (id_index < ids_by_id.len and ids_by_id[id_index] <= range.max and ids_by_id[id_index] < current) {
                id_index += 1;
            }
            if (id_index >= ids_by_id.len or ids_by_id[id_index] > range.max) return false;
            if (ids_by_id[id_index] == current) return true;
            side_index = try self.edgeSegmentIdIndexLowerBoundInFileFrom(file, header.edge_count, ids_by_id[id_index], side_index);
        }
        return false;
    }

    fn edgeSegmentIdIndexIntersectsSmallSortedInFile(
        self: Store,
        file: std.Io.File,
        header: EdgeSegmentIdIndexHeader,
        ids_by_id: []const u64,
        range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    ) !bool {
        if (header.edge_count == 0 or header.edge_count > edge_segment_id_index_stack_scan_max) return error.InvalidRecord;
        const edge_count = std.math.cast(usize, header.edge_count) orelse return error.RecordTooLarge;
        const byte_len = edge_count * 8;
        var bytes: [edge_segment_id_index_stack_scan_max * 8]u8 = undefined;
        const n = try file.readPositionalAll(self.io, bytes[0..byte_len], EdgeSegmentIdIndex.header_len);
        if (n != byte_len) return error.InvalidRecord;

        var id_index = lowerBoundU64(ids_by_id, range.min);
        var previous: u64 = 0;
        var digest: u64 = 0;
        var order_digest: u64 = 0;
        var found = false;
        for (0..edge_count) |index| {
            const offset = index * 8;
            const current = std.mem.readInt(u64, bytes[offset..][0..8], .little);
            if (current == 0 or current == std.math.maxInt(u64)) return error.InvalidRecord;
            if (index == 0) {
                if (current != header.edge_id_min) return error.InvalidRecord;
            } else if (current <= previous) {
                return error.InvalidRecord;
            }
            previous = current;
            digest ^= edgeSegmentIdDigest(current);
            order_digest ^= edgeSegmentIdIndexOrderDigestAt(index, current);

            while (id_index < ids_by_id.len and ids_by_id[id_index] < current) {
                id_index += 1;
            }
            if (id_index < ids_by_id.len and ids_by_id[id_index] <= range.max and ids_by_id[id_index] == current) {
                found = true;
            }
        }
        if (previous != header.edge_id_max) return error.InvalidRecord;
        if (digest != header.edge_id_digest or order_digest != header.edge_id_order_digest) return error.InvalidRecord;
        return found;
    }

    fn edgeSegmentIdIndexLowerBoundInFile(self: Store, file: std.Io.File, edge_count: u64, edge_id: u64) !u64 {
        return try self.edgeSegmentIdIndexLowerBoundInFileFrom(file, edge_count, edge_id, 0);
    }

    fn edgeSegmentIdIndexLowerBoundInFileFrom(self: Store, file: std.Io.File, edge_count: u64, edge_id: u64, start: u64) !u64 {
        if (start > edge_count) return error.InvalidRecord;
        var lo: u64 = start;
        var hi: u64 = edge_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const current = try self.readEdgeSegmentIdIndexRecordAt(file, mid);
            if (current < edge_id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn readEdgeSegmentIdIndexRecordAt(self: Store, file: std.Io.File, index: u64) !u64 {
        const byte_index = std.math.mul(u64, index, 8) catch return error.RecordTooLarge;
        const offset = std.math.add(u64, EdgeSegmentIdIndex.header_len, byte_index) catch return error.RecordTooLarge;
        var bytes: [8]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &bytes, offset);
        if (n != bytes.len) return error.InvalidRecord;
        return std.mem.readInt(u64, &bytes, .little);
    }

    fn writeEdgeSegmentCurrent(self: Store, manifest_path: []const u8) !void {
        const manifest_leaf = std.fs.path.basename(manifest_path);
        if (manifest_leaf.len == 0 or manifest_leaf.len > edge_segment_current_max_path_bytes) return error.RecordTooLarge;
        const tmp_path = try self.tmpPathFor(self.edge_segment_current_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{ .read = true, .truncate = true });
            defer file.close(self.io);
            try file.writePositionalAll(self.io, manifest_leaf, 0);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.edge_segment_current_path);
    }

    fn readEdgeSegmentManifest(self: Store, allocator: std.mem.Allocator) !EdgeSegmentManifest {
        if (try self.readEdgeSegmentCurrentPath(allocator)) |manifest_path| {
            defer allocator.free(manifest_path);
            return self.readEdgeSegmentManifestAtPath(allocator, manifest_path) catch |err| switch (err) {
                error.FileNotFound => error.InvalidRecord,
                else => |e| e,
            };
        }
        return error.FileNotFound;
    }

    fn readEdgeSegmentManifestAtPath(self: Store, allocator: std.mem.Allocator, manifest_path: []const u8) !EdgeSegmentManifest {
        var manifest = try self.readEdgeSegmentManifestFile(allocator, manifest_path);
        errdefer manifest.deinit(allocator);
        try self.validateEdgeSegmentManifestPath(allocator, manifest_path, manifest.entries.items);
        manifest.ranges_trusted = true;
        return manifest;
    }

    fn validateEdgeSegmentManifestPath(
        self: Store,
        allocator: std.mem.Allocator,
        manifest_path: []const u8,
        entries: []const OwnedEdgeSegmentManifestEntry,
    ) !void {
        const total_edges = edgeSegmentManifestOwnedTotalEdges(entries) orelse return error.InvalidRecord;
        const digest = try self.edgeSegmentManifestOwnedDigest(entries);
        const expected_path = try self.edgeSegmentManifestEpochPathWithAllocator(allocator, total_edges, digest);
        defer allocator.free(expected_path);
        if (std.mem.eql(u8, manifest_path, expected_path)) return;
        const legacy_digest = edgeSegmentManifestOwnedLegacyDigest(entries);
        const legacy_expected_path = try self.edgeSegmentManifestEpochPathWithAllocator(allocator, total_edges, legacy_digest);
        defer allocator.free(legacy_expected_path);
        if (!std.mem.eql(u8, manifest_path, legacy_expected_path)) return error.InvalidRecord;
    }

    fn readEdgeSegmentCurrentPath(self: Store, allocator: std.mem.Allocator) !?[]u8 {
        var file = std.Io.Dir.cwd().openFile(self.io, self.edge_segment_current_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return null,
            else => |e| return e,
        };
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size == 0 or file_size > edge_segment_current_max_path_bytes) return error.InvalidRecord;
        const path_len = std.math.cast(usize, file_size) orelse return error.InvalidRecord;
        const path = try allocator.alloc(u8, path_len);
        errdefer allocator.free(path);
        const n = try file.readPositionalAll(self.io, path, 0);
        if (n != path.len) return error.InvalidRecord;
        if (std.mem.eql(u8, path, std.fs.path.basename(path))) {
            const resolved_path = try std.fs.path.join(allocator, &.{ self.dir_path, path });
            allocator.free(path);
            return resolved_path;
        }
        if (!std.fs.path.isAbsolute(path)) return error.InvalidRecord;
        return path;
    }

    fn readEdgeSegmentManifestFile(self: Store, allocator: std.mem.Allocator, manifest_path: []const u8) !EdgeSegmentManifest {
        var file = try std.Io.Dir.cwd().openFile(self.io, manifest_path, .{});
        defer file.close(self.io);
        const file_size = try self.regularFileSize(file);
        if (file_size < EdgeSegmentManifest.header_len) return error.InvalidRecord;
        var header_bytes: [EdgeSegmentManifest.header_len]u8 = undefined;
        const n = try file.readPositionalAll(self.io, &header_bytes, 0);
        if (n != header_bytes.len) return error.InvalidRecord;
        const header = try decodeEdgeSegmentManifestHeader(&header_bytes);
        var manifest = EdgeSegmentManifest{};
        errdefer manifest.deinit(allocator);
        try manifest.entries.ensureTotalCapacity(allocator, header.segment_count);

        var offset: u64 = EdgeSegmentManifest.header_len;
        var total_edges: u64 = 0;
        var entry_index: u32 = 0;
        while (entry_index < header.segment_count) : (entry_index += 1) {
            const entry_header_end = std.math.add(u64, offset, EdgeSegmentManifest.entry_header_len) catch return error.InvalidRecord;
            if (entry_header_end > file_size) return error.InvalidRecord;
            var entry_header_bytes: [EdgeSegmentManifest.entry_header_len]u8 = undefined;
            const entry_n = try file.readPositionalAll(self.io, &entry_header_bytes, offset);
            if (entry_n != entry_header_bytes.len) return error.InvalidRecord;
            offset = entry_header_end;
            const entry_header = try decodeEdgeSegmentManifestEntryHeader(&entry_header_bytes);
            const edge_digest_end = std.math.add(u64, offset, 8) catch return error.InvalidRecord;
            if (edge_digest_end > file_size) return error.InvalidRecord;
            var edge_digest_bytes: [8]u8 = undefined;
            const edge_digest_n = try file.readPositionalAll(self.io, &edge_digest_bytes, offset);
            if (edge_digest_n != edge_digest_bytes.len) return error.InvalidRecord;
            const edge_digest = std.mem.readInt(u64, &edge_digest_bytes, .little);
            offset = edge_digest_end;
            const order_digest_extra_len = try edgeSegmentManifestOrderDigestExtraLen(entry_header.entry_flags);
            var edge_id_order_digest: u64 = 0;
            if (order_digest_extra_len != 0) {
                const order_digest_extra_end = std.math.add(u64, offset, order_digest_extra_len) catch return error.InvalidRecord;
                if (order_digest_extra_end > file_size) return error.InvalidRecord;
                var order_digest_extra: [8]u8 = undefined;
                const order_digest_extra_n = try file.readPositionalAll(self.io, &order_digest_extra, offset);
                if (order_digest_extra_n != order_digest_extra.len) return error.InvalidRecord;
                edge_id_order_digest = std.mem.readInt(u64, &order_digest_extra, .little);
                if (edge_id_order_digest == 0) return error.InvalidRecord;
                offset = order_digest_extra_end;
            }
            const run_extra_len = try edgeSegmentManifestRunExtraLen(entry_header.entry_flags);
            var first_max: u64 = 0;
            var second_min: u64 = 0;
            if (run_extra_len != 0) {
                const run_extra_end = std.math.add(u64, offset, run_extra_len) catch return error.InvalidRecord;
                if (run_extra_end > file_size) return error.InvalidRecord;
                var run_extra: [16]u8 = undefined;
                const run_extra_n = try file.readPositionalAll(self.io, run_extra[0..run_extra_len], offset);
                if (run_extra_n != run_extra_len) return error.InvalidRecord;
                first_max = std.mem.readInt(u64, run_extra[0..8], .little);
                second_min = std.mem.readInt(u64, run_extra[8..16], .little);
                offset = run_extra_end;
            }
            const edge_count_extra_len = try edgeSegmentManifestEdgeCountExtraLen(entry_header.entry_flags);
            const edge_count = if (edge_count_extra_len != 0) count: {
                const edge_count_extra_end = std.math.add(u64, offset, edge_count_extra_len) catch return error.InvalidRecord;
                if (edge_count_extra_end > file_size) return error.InvalidRecord;
                var edge_count_extra: [8]u8 = undefined;
                const edge_count_extra_n = try file.readPositionalAll(self.io, &edge_count_extra, offset);
                if (edge_count_extra_n != edge_count_extra.len) return error.InvalidRecord;
                const explicit_edge_count = std.mem.readInt(u64, &edge_count_extra, .little);
                if (explicit_edge_count == 0) return error.InvalidRecord;
                offset = edge_count_extra_end;
                break :count explicit_edge_count;
            } else try deriveEdgeSegmentManifestEdgeCountFromRunEncoding(entry_header.edge_id_range, entry_header.entry_flags, first_max, second_min);
            const edge_id_runs = try decodeEdgeSegmentManifestRunEncoding(edge_count, entry_header.edge_id_range, entry_header.entry_flags, first_max, second_min);
            const digest_extra_len = try edgeSegmentManifestDigestExtraLen(entry_header.entry_flags);
            var edge_id_digest: u64 = 0;
            if (digest_extra_len != 0) {
                const digest_extra_end = std.math.add(u64, offset, digest_extra_len) catch return error.InvalidRecord;
                if (digest_extra_end > file_size) return error.InvalidRecord;
                var digest_extra: [8]u8 = undefined;
                const digest_extra_n = try file.readPositionalAll(self.io, &digest_extra, offset);
                if (digest_extra_n != digest_extra.len) return error.InvalidRecord;
                if (edge_id_order_digest == 0 and edgeSegmentManifestRunsCoverEntry(edge_count, entry_header.edge_id_range, edge_id_runs)) {
                    return error.InvalidRecord;
                }
                edge_id_digest = std.mem.readInt(u64, &digest_extra, .little);
                offset = digest_extra_end;
            } else if (!edgeSegmentManifestRunsCoverEntry(edge_count, entry_header.edge_id_range, edge_id_runs) or edge_id_order_digest != 0) {
                return error.InvalidRecord;
            }
            const endpoint_extra_len = try edgeSegmentManifestEndpointExtraLen(entry_header.entry_flags);
            var src_node_min: u64 = 0;
            var src_node_max: u64 = 0;
            var dst_node_min: u64 = 0;
            var dst_node_max: u64 = 0;
            if (endpoint_extra_len != 0) {
                const endpoint_extra_end = std.math.add(u64, offset, endpoint_extra_len) catch return error.InvalidRecord;
                if (endpoint_extra_end > file_size) return error.InvalidRecord;
                var endpoint_extra: [32]u8 = undefined;
                const endpoint_extra_n = try file.readPositionalAll(self.io, endpoint_extra[0..endpoint_extra_len], offset);
                if (endpoint_extra_n != endpoint_extra_len) return error.InvalidRecord;
                var endpoint_extra_pos: usize = 0;
                if ((entry_header.entry_flags & edge_segment_manifest_src_full) == 0) {
                    src_node_min = std.mem.readInt(u64, endpoint_extra[endpoint_extra_pos..][0..8], .little);
                    endpoint_extra_pos += 8;
                }
                if ((entry_header.entry_flags & (edge_segment_manifest_src_single | edge_segment_manifest_src_full)) == 0) {
                    src_node_max = std.mem.readInt(u64, endpoint_extra[endpoint_extra_pos..][0..8], .little);
                    endpoint_extra_pos += 8;
                }
                if ((entry_header.entry_flags & edge_segment_manifest_dst_full) == 0) {
                    dst_node_min = std.mem.readInt(u64, endpoint_extra[endpoint_extra_pos..][0..8], .little);
                    endpoint_extra_pos += 8;
                }
                if ((entry_header.entry_flags & (edge_segment_manifest_dst_single | edge_segment_manifest_dst_full)) == 0) {
                    dst_node_max = std.mem.readInt(u64, endpoint_extra[endpoint_extra_pos..][0..8], .little);
                    endpoint_extra_pos += 8;
                }
                if (endpoint_extra_pos != endpoint_extra_len) return error.InvalidRecord;
                offset = endpoint_extra_end;
            }
            const endpoint_ranges = try decodeEdgeSegmentManifestEndpointRanges(
                entry_header.entry_flags,
                src_node_min,
                dst_node_min,
                src_node_max,
                dst_node_max,
            );
            const singleton_rel_extra_len = try edgeSegmentManifestSingletonRelExtraLen(entry_header.entry_flags);
            var singleton_rel: ?core.RelKind = null;
            if (singleton_rel_extra_len != 0) {
                const singleton_rel_extra_end = std.math.add(u64, offset, singleton_rel_extra_len) catch return error.InvalidRecord;
                if (singleton_rel_extra_end > file_size) return error.InvalidRecord;
                var singleton_rel_extra: [2]u8 = undefined;
                const singleton_rel_extra_n = try file.readPositionalAll(self.io, &singleton_rel_extra, offset);
                if (singleton_rel_extra_n != singleton_rel_extra.len) return error.InvalidRecord;
                singleton_rel = relKindFromInt(std.mem.readInt(u16, &singleton_rel_extra, .little)) orelse return error.InvalidRecord;
                offset = singleton_rel_extra_end;
            }
            const path_end = std.math.add(u64, offset, entry_header.path_len) catch return error.InvalidRecord;
            if (path_end > file_size) return error.InvalidRecord;
            const restored_path = path: {
                if ((entry_header.entry_flags & edge_segment_manifest_virtual_singleton) != 0) {
                    if (entry_header.path_len != 0) return error.InvalidRecord;
                    break :path try allocator.dupe(u8, "");
                }
                const stored_path = try allocator.alloc(u8, entry_header.path_len);
                defer allocator.free(stored_path);
                const path_n = try file.readPositionalAll(self.io, stored_path, offset);
                if (path_n != stored_path.len) return error.InvalidRecord;
                break :path try self.restoreEdgeSegmentManifestPath(allocator, entry_header.entry_flags, stored_path);
            };
            errdefer allocator.free(restored_path);
            offset = path_end;
            total_edges = std.math.add(u64, total_edges, edge_count) catch return error.InvalidRecord;
            const entry = OwnedEdgeSegmentManifestEntry{
                .edge_count = edge_count,
                .edge_digest = edge_digest,
                .edge_id_range = entry_header.edge_id_range,
                .edge_id_digest = edge_id_digest,
                .edge_id_order_digest = edge_id_order_digest,
                .edge_id_runs = edge_id_runs,
                .src_node_range = endpoint_ranges.src_node_range,
                .dst_node_range = endpoint_ranges.dst_node_range,
                .singleton_rel = singleton_rel,
                .path = restored_path,
            };
            if (edgeSegmentManifestEntryIsVirtual(entry)) {
                try edgeSegmentManifestValidateVirtualEntry(entry);
            } else if ((entry_header.entry_flags & edge_segment_manifest_virtual_singleton) != 0) return error.InvalidRecord;
            manifest.entries.appendAssumeCapacity(entry);
        }
        if (offset != file_size or total_edges != header.total_edges) return error.InvalidRecord;
        return manifest;
    }

    pub fn ensurePersistentEdgeIndexes(self: Store, graph: *const graph_mod.Graph) !void {
        const graph_stats = try graphEdgeIndexStats(self.allocator, graph);
        const expected_edges = graph_stats.physical_edges;
        const id_digest = self.edgeIndexValidatedDigest(self.edge_by_id_path, .id, expected_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => null,
            else => |e| return e,
        };
        const src_digest = self.edgeIndexValidatedDigest(self.edge_by_src_path, .src, expected_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => null,
            else => |e| return e,
        };
        const dst_digest = self.edgeIndexValidatedDigest(self.edge_by_dst_path, .dst, expected_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => null,
            else => |e| return e,
        };
        const consistent_ok = consistent: {
            const id = id_digest orelse break :consistent false;
            const src = src_digest orelse break :consistent false;
            const dst = dst_digest orelse break :consistent false;
            break :consistent id.eql(src) and id.eql(dst);
        };
        const digest_ok = if (consistent_ok) self.edgeIndexHeadersMatchGraphStats(graph_stats) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => false,
            else => |e| return e,
        } else false;
        if (!consistent_ok or !digest_ok) try self.rebuildPersistentEdgeIndexes(graph);
    }

    pub fn ensurePersistentNodeIndexes(self: Store, graph: *const graph_mod.Graph) !void {
        const expected_nodes = activeNodeCount(graph);
        const ok = self.nodeIndexValid(expected_nodes) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => false,
            else => |e| return e,
        };
        if (!ok) try self.rebuildPersistentNodeIndexes(graph);
    }

    fn nodeIndexValid(self: Store, expected_nodes: u64) !bool {
        return try self.nodeIndexValidWithTimings(expected_nodes, null);
    }

    fn nodeIndexValidWithTimings(self: Store, expected_nodes: u64, timings: ?*PersistentValidateTimings) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{});
        defer file.close(self.io);
        const header = try self.readNodeByIdHeaderFromFile(file);
        if (header.node_count != expected_nodes) return false;
        const size = try self.fileSizeOrZero(self.node_by_id_path);
        if (size != try self.nodeByIdFileSizeForHeaderStore(header)) return false;
        var by_id_map = openReadOnlyMemoryMap(self.io, file, size) catch null;
        defer if (by_id_map) |*mapped| mapped.destroy(self.io);
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        const texts_size = texts.size;
        var validation_hashes: ?NodeTextValidationHashes = if (texts.shouldCacheValidationHashes())
            try NodeTextValidationHashes.init(self.allocator, header.max_node_id, expected_nodes)
        else
            null;
        defer if (validation_hashes) |*hashes| hashes.deinit(self.allocator);
        if (timings) |t| {
            if (validation_hashes) |*hashes| {
                t.node_text_hash_cache_enabled = true;
                t.node_text_hash_cache_bytes = hashes.estimatedBytes();
            }
        }

        var id: u64 = 1;
        var seen: u64 = 0;
        var by_id_digest: u64 = 0;
        var texts_cover_in_id_order = true;
        var texts_cover_cursor: u64 = 0;
        const by_id_scan_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        while (id <= header.max_node_id) : (id += 1) {
            const record = if (by_id_map) |*mapped|
                try readNodeByIdRecordFromMap(header, mapped, id)
            else
                try self.readNodeByIdRecordAt(file, header, id);
            if (record.id == 0) continue;
            if (record.id != id) return false;
            if (record.text_offset > texts_size or record.text_len > texts_size - record.text_offset) return false;
            if (texts_cover_in_id_order) {
                if (record.text_offset == texts_cover_cursor) {
                    texts_cover_cursor = std.math.add(u64, texts_cover_cursor, record.text_len) catch return false;
                } else {
                    texts_cover_in_id_order = false;
                }
            }
            const node_kind = try record.nodeKind();
            const hashes = try texts.validationHash(record.id, node_kind, record.text_offset, record.text_len);
            by_id_digest ^= hashes.node_digest;
            if (validation_hashes) |*cache| {
                try cache.put(record.id, .{
                    .text_hash = hashes.text_hash,
                    .node_digest = hashes.node_digest,
                });
            }
            seen += 1;
        }
        if (seen != expected_nodes) return false;
        if (by_id_digest != header.node_digest) return false;
        if (texts_cover_in_id_order) {
            if (texts_cover_cursor != texts_size) return false;
        } else if (!try self.nodeByIdTextSpansCoverTextsFile(file, if (by_id_map) |*mapped| mapped else null, header, texts_size)) {
            return false;
        }
        if (timings) |t| t.node_by_id_scan_ns = storageElapsedNs(self.io, by_id_scan_start);

        var text_index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer text_index_file.close(self.io);
        const text_header = try self.readNodeTextIndexHeaderFromFile(text_index_file);
        const delta_file = std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{}) catch |err| switch (err) {
            error.FileNotFound => null,
            else => |e| return e,
        };
        defer if (delta_file) |delta_open_file| delta_open_file.close(self.io);
        const delta_header = if (delta_file) |delta_open_file|
            try self.readNodeTextIndexHeaderFromFile(delta_open_file)
        else
            NodeTextIndexHeader{ .node_count = 0 };
        if (delta_header.node_count > node_text_delta_max_records) return false;
        var run_manifest = try self.readNodeTextRunManifest(self.allocator);
        defer run_manifest.deinit(self.allocator);
        const run_count = run_manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return false;
        if (text_header.node_count + delta_header.node_count + run_count != expected_nodes) return false;
        if ((text_header.node_digest ^ delta_header.node_digest ^ run_manifest.nodeDigest()) != header.node_digest) return false;
        const text_index_size = try self.fileSizeOrZero(self.node_by_text_path);
        if (text_index_size != try nodeTextIndexFileSizeForHeader(text_header)) return false;
        const delta_index_size = try self.fileSizeOrZero(self.node_by_text_delta_path);
        if (delta_index_size != try nodeTextIndexFileSizeForHeader(delta_header)) return false;

        var pos: u64 = 0;
        var previous: ?NodeTextIndexRecord = null;
        var by_text_digest = NodeTextIndexDigest{};
        var indexed_node_ids = try NodeIndexSeenIds.init(self.allocator, header.max_node_id, expected_nodes);
        defer indexed_node_ids.deinit(self.allocator);
        var validation_node_view: ?NodeByIdIndexView = null;
        defer if (validation_node_view) |*view| view.deinit();
        const validation_node_meta = IndexMeta{
            .nodes = expected_nodes,
            .node_digest = header.node_digest,
        };
        const by_text_scan_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const text_span_node_view = if (text_header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, validation_node_meta, &validation_node_view) else null;
        while (pos < text_header.node_count) : (pos += 1) {
            var record = try self.readNodeTextIndexRecordAtForValidation(text_index_file, text_header, pos, text_span_node_view);
            if (record.id == 0 or record.id > header.max_node_id) return false;
            if (record.text_offset > texts_size or record.text_len > texts_size - record.text_offset) return false;
            if (!text_header.hasDerivedTextSpan()) {
                const by_id = if (by_id_map) |*mapped|
                    try readNodeByIdRecordFromMap(header, mapped, record.id)
                else
                    try self.readNodeByIdRecordAt(file, header, record.id);
                if (by_id.id != record.id) return false;
                if (by_id.kind != record.kind) return false;
                if (by_id.text_offset != record.text_offset or by_id.text_len != record.text_len) return false;
            }
            const digests = if (validation_hashes) |*cache|
                try cache.get(record.id)
            else
                try texts.validationHash(record.id, try record.nodeKind(), record.text_offset, record.text_len);
            if (text_header.hasDerivedHash()) {
                record.hash = digests.text_hash;
            } else if (digests.text_hash != record.hash) return false;
            by_text_digest.add(record, digests.node_digest);
            if (try indexed_node_ids.put(record.id)) return false;
            if (previous) |prev| {
                if (nodeTextIndexLessThan({}, record, prev)) return false;
                if (record.id == prev.id) return false;
            }
            previous = record;
        }
        if (timings) |t| t.node_by_text_scan_ns = storageElapsedNs(self.io, by_text_scan_start);

        var delta_digest = NodeTextIndexDigest{};
        pos = 0;
        const delta_scan_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        const delta_span_node_view = if (delta_header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, validation_node_meta, &validation_node_view) else null;
        while (pos < delta_header.node_count) : (pos += 1) {
            var record = try self.readNodeTextIndexRecordAtForValidation(delta_file orelse return false, delta_header, pos, delta_span_node_view);
            if (record.id == 0 or record.id > header.max_node_id) return false;
            if (record.text_offset > texts_size or record.text_len > texts_size - record.text_offset) return false;
            if (!delta_header.hasDerivedTextSpan()) {
                const by_id = if (by_id_map) |*mapped|
                    try readNodeByIdRecordFromMap(header, mapped, record.id)
                else
                    try self.readNodeByIdRecordAt(file, header, record.id);
                if (by_id.id != record.id) return false;
                if (by_id.kind != record.kind) return false;
                if (by_id.text_offset != record.text_offset or by_id.text_len != record.text_len) return false;
            }
            const digests = if (validation_hashes) |*cache|
                try cache.get(record.id)
            else
                try texts.validationHash(record.id, try record.nodeKind(), record.text_offset, record.text_len);
            if (delta_header.hasDerivedHash()) {
                record.hash = digests.text_hash;
            } else if (digests.text_hash != record.hash) return false;
            delta_digest.add(record, digests.node_digest);
            if (try indexed_node_ids.put(record.id)) return false;
        }
        if (timings) |t| t.node_text_delta_scan_ns = storageElapsedNs(self.io, delta_scan_start);
        if (delta_digest.count != delta_header.node_count) return false;
        if (delta_digest.digest != delta_header.node_digest) return false;
        if (delta_digest.order_digest != delta_header.order_digest) return false;
        var run_digest_all: u64 = 0;
        const run_scan_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        for (run_manifest.entries.items) |entry| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, entry.path, .{});
            defer run_file.close(self.io);
            const run_header = try self.readNodeTextIndexHeaderFromFile(run_file);
            if (run_header.node_count != entry.node_count or
                run_header.node_digest != entry.node_digest or
                run_header.order_digest != entry.order_digest) return false;
            const run_size = try self.regularFileSize(run_file);
            if (run_size != try nodeTextIndexFileSizeForHeader(run_header)) return false;
            var run_digest = NodeTextIndexDigest{};
            previous = null;
            pos = 0;
            const run_span_node_view = if (run_header.hasDerivedTextSpan()) try ensureNodeByIdIndexView(self, validation_node_meta, &validation_node_view) else null;
            while (pos < run_header.node_count) : (pos += 1) {
                var record = try self.readNodeTextIndexRecordAtForValidation(run_file, run_header, pos, run_span_node_view);
                if (record.id == 0 or record.id > header.max_node_id) return false;
                if (record.text_offset > texts_size or record.text_len > texts_size - record.text_offset) return false;
                if (!run_header.hasDerivedTextSpan()) {
                    const by_id = if (by_id_map) |*mapped|
                        try readNodeByIdRecordFromMap(header, mapped, record.id)
                    else
                        try self.readNodeByIdRecordAt(file, header, record.id);
                    if (by_id.id != record.id) return false;
                    if (by_id.kind != record.kind) return false;
                    if (by_id.text_offset != record.text_offset or by_id.text_len != record.text_len) return false;
                }
                const digests = if (validation_hashes) |*cache|
                    try cache.get(record.id)
                else
                    try texts.validationHash(record.id, try record.nodeKind(), record.text_offset, record.text_len);
                if (run_header.hasDerivedHash()) {
                    record.hash = digests.text_hash;
                } else if (digests.text_hash != record.hash) return false;
                run_digest.add(record, digests.node_digest);
                if (try indexed_node_ids.put(record.id)) return false;
                if (previous) |prev| {
                    if (nodeTextIndexLessThan({}, record, prev)) return false;
                    if (record.id == prev.id) return false;
                }
                previous = record;
            }
            if (run_digest.count != run_header.node_count) return false;
            if (run_digest.digest != run_header.node_digest) return false;
            if (run_digest.order_digest != run_header.order_digest) return false;
            run_digest_all ^= run_digest.digest;
        }
        if (timings) |t| t.node_text_run_scan_ns = storageElapsedNs(self.io, run_scan_start);
        if (indexed_node_ids.count() != expected_nodes) return false;
        return by_text_digest.count == text_header.node_count and
            by_text_digest.digest == text_header.node_digest and
            by_text_digest.order_digest == text_header.order_digest and
            by_text_digest.count + delta_digest.count + run_count == seen and
            (by_text_digest.digest ^ delta_digest.digest ^ run_digest_all) == header.node_digest;
    }

    fn nodeByIdTextSpansCoverTextsFile(self: Store, file: std.Io.File, map: ?*const std.Io.File.MemoryMap, header: NodeByIdHeader, texts_size: u64) !bool {
        var text_spans = std.ArrayList(TextSpan).empty;
        defer text_spans.deinit(self.allocator);
        var id: u64 = 1;
        while (id <= header.max_node_id) : (id += 1) {
            const record = if (map) |mapped|
                try readNodeByIdRecordFromMap(header, mapped, id)
            else
                try self.readNodeByIdRecordAt(file, header, id);
            if (record.id == 0) continue;
            if (record.id != id) return false;
            if (record.text_offset > texts_size or record.text_len > texts_size - record.text_offset) return false;
            try text_spans.append(self.allocator, .{ .offset = record.text_offset, .len = record.text_len });
        }
        return textSpansCoverTextsFile(text_spans.items, texts_size);
    }

    fn nodeTextHashMatches(self: Store, record: NodeTextIndexRecord) !bool {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        return try texts.hashMatches(record);
    }

    fn nodeRecordDigestFromTextSpan(self: Store, record: NodeByIdRecord) !u64 {
        return self.nodeRecordDigestFromStoredText(record.id, try record.nodeKind(), record.text_offset, record.text_len);
    }

    fn nodeTextIndexRecordDigest(self: Store, record: NodeTextIndexRecord) !u64 {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        return self.nodeTextIndexRecordDigestWithTexts(&texts, record);
    }

    fn nodeTextIndexRecordDigestWithTexts(self: Store, texts: *const NodeTextsView, record: NodeTextIndexRecord) !u64 {
        _ = self;
        return texts.digestStoredNode(record.id, try record.nodeKind(), record.text_offset, record.text_len);
    }

    fn nodeRecordDigestFromStoredTextView(self: Store, texts: *const NodeTextsView, id: u64, kind: core.NodeKind, offset: u64, len: u32) !u64 {
        _ = self;
        return texts.digestStoredNode(id, kind, offset, len);
    }

    fn nodeRecordDigestFromStoredText(self: Store, id: u64, kind: core.NodeKind, offset: u64, len: u32) !u64 {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        return self.nodeRecordDigestFromStoredTextView(&texts, id, kind, offset, len);
    }

    fn edgeIndexValid(self: Store, path: []const u8, order: EdgeIndexOrder, expected_edges: u64) !bool {
        _ = self.edgeIndexValidatedDigest(path, order, expected_edges) catch |err| switch (err) {
            error.InvalidRecord => return false,
            else => |e| return e,
        };
        return true;
    }

    fn edgeIndexValidatedDigest(self: Store, path: []const u8, order: EdgeIndexOrder, expected_edges: u64) !EdgeIndexDigest {
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order or header.edge_count != expected_edges) return error.InvalidRecord;
        if (order == .id) {
            const meta = try self.readCurrentIndexMeta();
            if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        }
        const size = try self.regularFileSize(file);
        if (size != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;

        var node_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{});
        defer node_file.close(self.io);
        const node_header = try self.readNodeByIdHeaderFromFile(node_file);
        const node_index_size = try self.fileSizeOrZero(self.node_by_id_path);
        if (node_index_size != try self.nodeByIdFileSizeForHeaderStore(node_header)) return error.InvalidRecord;
        var node_map = openReadOnlyMemoryMap(self.io, node_file, node_index_size) catch null;
        defer if (node_map) |*mapped| mapped.destroy(self.io);

        var pos: u64 = 0;
        var previous: ?EdgeIndexRecord = null;
        var digest = EdgeIndexDigest{};
        var reader = try EdgeIndexSequentialRecordReader.init(self, file, header);
        while (pos < header.edge_count) : (pos += 1) {
            const record = try reader.read(pos);
            digest.add(record);
            if (!try self.nodeIdPresentInIndex(node_file, if (node_map) |*mapped| mapped else null, node_header, record.src)) return error.InvalidRecord;
            if (!try self.nodeIdPresentInIndex(node_file, if (node_map) |*mapped| mapped else null, node_header, record.dst)) return error.InvalidRecord;
            if (previous) |prev| {
                if (edgeIndexLessThan(order, record, prev)) return error.InvalidRecord;
                if (order == .id and record.edge_id == prev.edge_id) return error.InvalidRecord;
            }
            previous = record;
        }
        if (digest.digest != header.edge_digest) return error.InvalidRecord;
        if (digest.order_digest != header.order_digest) return error.InvalidRecord;
        return digest;
    }

    fn edgeIndexesConsistent(self: Store, expected_edges: u64) !bool {
        const by_id = try self.edgeIndexDigest(self.edge_by_id_path, .id, expected_edges);
        const by_src = try self.edgeIndexDigest(self.edge_by_src_path, .src, expected_edges);
        const by_dst = try self.edgeIndexDigest(self.edge_by_dst_path, .dst, expected_edges);
        return by_id.eql(by_src) and by_id.eql(by_dst);
    }

    fn edgeIndexesValidatedAndMatchMeta(self: Store, meta: IndexMeta) !bool {
        if (!try self.edgeBaseIndexesValidatedAndMatchMeta(meta)) return false;
        return try self.edgeIndexHeadersMatchMeta(meta);
    }

    fn edgeBaseIndexesValidatedAndMatchMeta(self: Store, meta: IndexMeta) !bool {
        const id_digest = self.edgeIndexValidatedDigest(self.edge_by_id_path, .id, meta.edge_indexed_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        const src_digest = self.edgeIndexValidatedDigest(self.edge_by_src_path, .src, meta.edge_indexed_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        const dst_digest = self.edgeIndexValidatedDigest(self.edge_by_dst_path, .dst, meta.edge_indexed_edges) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        if (!id_digest.eql(src_digest) or !id_digest.eql(dst_digest)) return false;
        if (id_digest.count != meta.edge_indexed_edges or id_digest.digest != meta.edge_index_digest) return false;
        if (id_digest.order_digest != meta.edge_by_id_order_digest) return false;
        if (src_digest.order_digest != meta.edge_by_src_order_digest) return false;
        return dst_digest.order_digest == meta.edge_by_dst_order_digest;
    }

    fn edgeIndexesMatchMeta(self: Store, meta: IndexMeta) !bool {
        // Runtime currentness check only. Explicit validation still scans
        // edge-index record bodies via persistentIndexFilesMatchMetaWithTimings.
        return try self.edgeIndexHeadersMatchMeta(meta);
    }

    fn validatedEdgeIndexDigestsMatchMeta(self: Store, meta: IndexMeta, id_digest: EdgeIndexDigest, src_digest: EdgeIndexDigest, dst_digest: EdgeIndexDigest) !bool {
        if (meta.edge_indexed_edges < meta.edges) return false;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        if (tombstone_header.count > meta.edge_indexed_edges) return false;
        if (meta.edge_indexed_edges - tombstone_header.count != meta.edges) return false;
        if ((meta.edge_index_digest ^ tombstone_header.digest) != meta.edge_digest) return false;
        if (id_digest.count != meta.edge_indexed_edges or id_digest.digest != meta.edge_index_digest) return false;
        if (src_digest.count != meta.edge_indexed_edges or src_digest.digest != meta.edge_index_digest) return false;
        if (dst_digest.count != meta.edge_indexed_edges or dst_digest.digest != meta.edge_index_digest) return false;
        if (id_digest.order_digest != meta.edge_by_id_order_digest) return false;
        if (src_digest.order_digest != meta.edge_by_src_order_digest) return false;
        if (dst_digest.order_digest != meta.edge_by_dst_order_digest) return false;
        return true;
    }

    fn edgeIndexHeadersMatchGraphStats(self: Store, graph_stats: GraphEdgeIndexStats) !bool {
        // The caller has already run per-index validation and cross-index
        // streamed digest checks; this only compares those trusted headers and
        // tombstones against the graph-derived count/digest identity.
        if (graph_stats.physical_edges < graph_stats.visible_edges) return false;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        if (tombstone_header.count > graph_stats.physical_edges) return false;
        if (graph_stats.physical_edges - tombstone_header.count != graph_stats.visible_edges) return false;
        if ((graph_stats.physical_edge_digest ^ tombstone_header.digest) != graph_stats.edge_digest) return false;

        const id_header = try self.readEdgeIndexHeader(self.edge_by_id_path);
        if (id_header.order != .id or id_header.edge_count != graph_stats.physical_edges) return false;
        if (id_header.edge_digest != graph_stats.physical_edge_digest) return false;
        const src_header = try self.readEdgeIndexHeader(self.edge_by_src_path);
        if (src_header.order != .src or src_header.edge_count != graph_stats.physical_edges) return false;
        if (src_header.edge_digest != graph_stats.physical_edge_digest) return false;
        const dst_header = try self.readEdgeIndexHeader(self.edge_by_dst_path);
        if (dst_header.order != .dst or dst_header.edge_count != graph_stats.physical_edges) return false;
        return dst_header.edge_digest == graph_stats.physical_edge_digest;
    }

    fn edgeIndexHeadersMatchMeta(self: Store, meta: IndexMeta) !bool {
        if (meta.edge_indexed_edges < meta.edges) return false;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        if (tombstone_header.count > meta.edge_indexed_edges) return false;
        if (meta.edge_indexed_edges - tombstone_header.count != meta.edges) return false;
        if ((meta.edge_index_digest ^ tombstone_header.digest) != meta.edge_digest) return false;
        return try self.edgeIndexBaseHeadersMatchMeta(meta);
    }

    fn edgeStorageMatchesMeta(self: Store, meta: IndexMeta, validate_base_records: bool) !bool {
        const base_matches = if (validate_base_records)
            try self.edgeBaseIndexesValidatedAndMatchMeta(meta)
        else
            try self.edgeIndexBaseHeadersMatchMeta(meta);
        if (!base_matches) return false;
        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
        const physical_edges = std.math.add(u64, meta.edges, tombstone_header.count) catch return false;
        if (meta.edge_indexed_edges > physical_edges) return false;
        if (meta.edge_indexed_edges == physical_edges) {
            return (meta.edge_index_digest ^ tombstone_header.digest) == meta.edge_digest;
        }
        // The base indexes intentionally lag while an immutable segment
        // overlay owns the physical suffix (or the complete visible set).
        // Treat that publication as current only after validating its count
        // and digest identity against the same IndexMeta snapshot.
        return try self.edgeSegmentManifestMatchesMeta(meta);
    }

    fn edgeIndexBaseHeadersMatchMeta(self: Store, meta: IndexMeta) !bool {
        if (!try self.edgeIndexHeaderFileMatchesMeta(self.edge_by_id_path, .id, meta.edge_indexed_edges, meta.edge_index_digest, meta.edge_by_id_order_digest)) return false;
        if (!try self.edgeIndexHeaderFileMatchesMeta(self.edge_by_src_path, .src, meta.edge_indexed_edges, meta.edge_index_digest, meta.edge_by_src_order_digest)) return false;
        if (!try self.edgeIndexHeaderFileMatchesMeta(self.edge_by_dst_path, .dst, meta.edge_indexed_edges, meta.edge_index_digest, meta.edge_by_dst_order_digest)) return false;
        return true;
    }

    fn edgeIndexHeaderFileMatchesMeta(self: Store, path: []const u8, order: EdgeIndexOrder, edge_count: u64, edge_digest: u64, order_digest: u64) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order or header.edge_count != edge_count) return false;
        if (header.edge_digest != edge_digest or header.order_digest != order_digest) return false;
        return try self.regularFileSize(file) == try edgeIndexFileSizeForHeader(header);
    }

    fn edgeIndexDigest(self: Store, path: []const u8, order: EdgeIndexOrder, expected_edges: u64) !EdgeIndexDigest {
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order or header.edge_count != expected_edges) return error.InvalidRecord;
        const size = try self.regularFileSize(file);
        if (size != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;

        var digest = EdgeIndexDigest{};
        var reader = try EdgeIndexSequentialRecordReader.init(self, file, header);
        var pos: u64 = 0;
        while (pos < header.edge_count) : (pos += 1) {
            const record = try reader.read(pos);
            digest.add(record);
        }
        if (digest.digest != header.edge_digest) return error.InvalidRecord;
        if (digest.order_digest != header.order_digest) return error.InvalidRecord;
        return digest;
    }

    fn nodeIdPresentInIndex(self: Store, file: std.Io.File, map: ?*const std.Io.File.MemoryMap, header: NodeByIdHeader, id: u64) !bool {
        if (id == 0 or id > header.max_node_id) return false;
        const record = if (map) |mapped|
            try readNodeByIdRecordFromMap(header, mapped, id)
        else
            try self.readNodeByIdRecordAt(file, header, id);
        return record.id == id;
    }

    fn rebuildPersistentEdgeIndexes(self: Store, graph: *const graph_mod.Graph) !void {
        const edge_repair_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_edges.tmp", .{self.edge_by_id_path});
        defer self.allocator.free(edge_repair_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, edge_repair_path) catch {};
        const tombstone_repair_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_tombstones.tmp", .{self.edge_tombstones_path});
        defer self.allocator.free(tombstone_repair_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tombstone_repair_path) catch {};

        var edge_record_count: usize = 0;
        var tombstone_count: usize = 0;
        var tombstone_digest: u64 = 0;

        {
            var edge_file = try std.Io.Dir.cwd().createFile(self.io, edge_repair_path, .{
                .read = true,
                .truncate = true,
            });
            defer edge_file.close(self.io);
            var edge_writer = try StorageBufferedWriter.init(self.allocator, self.io, edge_file, storage_write_buffer_bytes);
            defer edge_writer.deinit();

            var tombstone_file = try std.Io.Dir.cwd().createFile(self.io, tombstone_repair_path, .{
                .read = true,
                .truncate = true,
            });
            defer tombstone_file.close(self.io);
            var tombstone_writer = try StorageBufferedWriter.init(self.allocator, self.io, tombstone_file, storage_write_buffer_bytes);
            defer tombstone_writer.deinit();

            var active_nodes = try buildActiveNodeSet(self.allocator, graph);
            defer active_nodes.deinit();
            var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
            var tombstone_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
            for (graph.edges.items) |edge| {
                const record = (try physicalEdgeRecord(&active_nodes, edge)) orelse continue;
                record.encode(&record_bytes);
                try edge_writer.append(&record_bytes);
                edge_record_count = std.math.add(usize, edge_record_count, 1) catch return error.InvalidRecord;
                if (edge.status == .deleted) {
                    const edge_digest = edgeRecordDigest(record);
                    const tombstone = EdgeTombstoneRecord{
                        .edge_id = record.edge_id,
                        .edge_digest = edge_digest,
                    };
                    tombstone.encode(&tombstone_bytes);
                    try tombstone_writer.append(&tombstone_bytes);
                    tombstone_count = std.math.add(usize, tombstone_count, 1) catch return error.InvalidRecord;
                    tombstone_digest ^= edge_digest;
                }
            }

            try edge_writer.flush();
            const expected_edge_repair_size = std.math.mul(u64, @intCast(edge_record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
            if (try edge_writer.position() != expected_edge_repair_size) return error.InvalidRecord;
            if (try self.regularFileSize(edge_file) != expected_edge_repair_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try edge_file.sync(self.io);

            try tombstone_writer.flush();
            const expected_tombstone_repair_size = std.math.mul(u64, @intCast(tombstone_count), EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
            if (try tombstone_writer.position() != expected_tombstone_repair_size) return error.InvalidRecord;
            if (try self.regularFileSize(tombstone_file) != expected_tombstone_repair_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try tombstone_file.sync(self.io);
        }

        try self.writeEdgeIndexesFromRepairSpool(edge_repair_path, edge_record_count, null);
        std.Io.Dir.cwd().deleteFile(self.io, edge_repair_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };

        try self.writeEdgeTombstoneIndexFromRepairSpool(tombstone_repair_path, tombstone_count, tombstone_digest);
        std.Io.Dir.cwd().deleteFile(self.io, tombstone_repair_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
    }

    fn appendEdgeIndexRecord(self: Store, edge: graph_mod.Edge) !void {
        if (edge.status != .active) return;
        const record = edgeIndexRecordFromEdge(edge);

        try self.insertEdgeIndexRecord(self.edge_by_id_path, .id, record);
        try self.insertEdgeIndexRecord(self.edge_by_src_path, .src, record);
        try self.insertEdgeIndexRecord(self.edge_by_dst_path, .dst, record);
    }

    fn insertEdgeIndexRecord(self: Store, path: []const u8, order: EdgeIndexOrder, record: EdgeIndexRecord) !void {
        var old_file = try std.Io.Dir.cwd().openFile(self.io, path, .{ .mode = .read_write, .allow_directory = false });
        defer old_file.close(self.io);
        const old_header = try self.readEdgeIndexHeaderFromFile(old_file);
        if (old_header.order != order) return error.InvalidRecord;
        const expected_old_size = try edgeIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        if (old_header.edge_count == std.math.maxInt(u64)) return error.RecordTooLarge;
        const next_count = old_header.edge_count + 1;
        const record_digest = edgeRecordDigest(record);
        const next_order_digest = edgeIndexOrderDigestStep(old_header.order_digest, old_header.edge_count, record);
        const next_header = edgeIndexHeaderForTail(order, old_header, next_count, old_header.edge_digest ^ record_digest, next_order_digest, &.{record});

        if (old_header.edge_count == 0) {
            return try self.appendSortedEdgeIndexTail(old_file, old_header, next_header, record);
        }
        const last = try self.readEdgeIndexRecordAt(old_file, old_header, old_header.edge_count - 1);
        if (!old_header.hasKeyRuns() and !edgeIndexLessThan(order, record, last)) {
            if (old_header.record_len == next_header.record_len) {
                return try self.appendSortedEdgeIndexTail(old_file, old_header, next_header, record);
            }
        }

        const rewrite_header = edgeIndexHeaderForSingleFullRewrite(order, next_count, old_header.edge_digest ^ record_digest, 0, old_header, record);
        const expected_new_size = try edgeIndexFileSizeForHeader(rewrite_header);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(expected_new_size));
            defer writer.deinit();

            var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
            const placeholder_header = rewrite_header;
            placeholder_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var new_digest = EdgeIndexDigest{};
            var old_digest = EdgeIndexDigest{};
            var prev_old: ?EdgeIndexRecord = null;
            var inserted = false;
            var pos: u64 = 0;
            while (pos < old_header.edge_count) : (pos += 1) {
                const current = try self.readEdgeIndexRecordAt(old_file, old_header, pos);
                if (prev_old) |prev| {
                    if (!edgeIndexLessThan(order, prev, current)) return error.InvalidRecord;
                }
                prev_old = current;
                old_digest.add(current);
                if (!inserted and edgeIndexLessThan(order, record, current)) {
                    try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, record);
                    new_digest.addWithDigest(record, record_digest);
                    inserted = true;
                }
                try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, current);
                new_digest.add(current);
            }
            if (old_digest.count != old_header.edge_count or old_digest.digest != old_header.edge_digest or old_digest.order_digest != old_header.order_digest) return error.InvalidRecord;
            if (!inserted) {
                try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, record);
                new_digest.addWithDigest(record, record_digest);
            }
            if (new_digest.count != next_count) return error.InvalidRecord;
            if (new_digest.digest != placeholder_header.edge_digest) return error.InvalidRecord;
            try writer.flush();
            if (try writer.position() != expected_new_size) return error.InvalidRecord;
            if (try self.regularFileSize(new_file) != expected_new_size) return error.InvalidRecord;
            var new_header = rewrite_header;
            new_header.edge_digest = new_digest.digest;
            new_header.order_digest = new_digest.order_digest;
            new_header.encode(&header_bytes);
            try new_file.writePositionalAll(self.io, &header_bytes, 0);
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, path);
    }

    const EdgeIndexBatchWriteResult = struct {
        order_digest: u64,
        edge_id_runs: ?EdgeSegmentIdRunSummary = null,
    };

    fn writeMergedEdgeIndexBatch(self: Store, path: []const u8, order: EdgeIndexOrder, old_meta: IndexMeta, batch_records: []EdgeIndexRecord, next_digest: u64) !EdgeIndexBatchWriteResult {
        if (batch_records.len == 0) return .{
            .order_digest = edgeOrderDigestForMeta(old_meta, order),
            .edge_id_runs = if (order == .id) old_meta.edge_by_id_runs else null,
        };
        const next_count = std.math.add(u64, old_meta.edge_indexed_edges, @intCast(batch_records.len)) catch return error.RecordTooLarge;
        var old_file = try std.Io.Dir.cwd().openFile(self.io, path, .{ .mode = .read_write });
        defer old_file.close(self.io);
        const old_header = try self.readEdgeIndexHeaderFromFile(old_file);
        if (old_header.order != order) return error.InvalidRecord;
        if (old_header.edge_count != old_meta.edge_indexed_edges) return error.InvalidRecord;
        if (old_header.edge_digest != old_meta.edge_index_digest) return error.InvalidRecord;
        if (old_header.order_digest != edgeOrderDigestForMeta(old_meta, order)) return error.InvalidRecord;
        const expected_old_size = try edgeIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;

        var batch_sorted = edgeIndexBatchSorted(order, batch_records);
        if (batch_sorted) {
            if (try self.appendSortedEdgeIndexBatchTailIfPossible(old_file, old_header, order, batch_records, next_count, next_digest)) |order_digest| {
                var edge_id_runs = if (order == .id)
                    extendEdgeSegmentIdRunSummaryWithRecords(old_meta.edge_by_id_runs, old_header.edge_count, batch_records)
                else
                    null;
                if (edge_id_runs) |runs| {
                    const next_header = try self.readEdgeIndexHeaderFromFile(old_file);
                    if (!try self.edgeIdRunSummaryMatchesFile(old_file, next_header, runs)) edge_id_runs = null;
                }
                return .{
                    .order_digest = order_digest,
                    .edge_id_runs = edge_id_runs,
                };
            }
        }
        if (!batch_sorted) {
            sortEdgeIndexRecords(order, batch_records);
            batch_sorted = true;
            if (try self.appendSortedEdgeIndexBatchTailIfPossible(old_file, old_header, order, batch_records, next_count, next_digest)) |order_digest| {
                var edge_id_runs = if (order == .id)
                    extendEdgeSegmentIdRunSummaryWithRecords(old_meta.edge_by_id_runs, old_header.edge_count, batch_records)
                else
                    null;
                if (edge_id_runs) |runs| {
                    const next_header = try self.readEdgeIndexHeaderFromFile(old_file);
                    if (!try self.edgeIdRunSummaryMatchesFile(old_file, next_header, runs)) edge_id_runs = null;
                }
                return .{
                    .order_digest = order_digest,
                    .edge_id_runs = edge_id_runs,
                };
            }
        }
        std.debug.assert(batch_sorted);

        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var merged_order_digest: u64 = 0;
        const rewrite_header = EdgeIndexHeader.withShape(
            order,
            next_count,
            next_digest,
            0,
            false,
            old_header.hasU32NodeIds() and edgeRecordsHaveU32NodeIds(batch_records),
            old_header.hasU32EdgeIds() and edgeRecordsHaveU32EdgeIds(batch_records),
            edgeRecordsExtendDerivedRel(old_header, batch_records),
        );
        const expected_new_size = try edgeIndexFileSizeForHeader(rewrite_header);
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(expected_new_size));
            defer writer.deinit();

            var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
            const placeholder_header = rewrite_header;
            placeholder_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var batch_pos: usize = 0;
            var old_digest = EdgeIndexDigest{};
            var new_digest = EdgeIndexDigest{};
            var prev_old: ?EdgeIndexRecord = null;
            var old_pos: u64 = 0;
            while (old_pos < old_header.edge_count) : (old_pos += 1) {
                const current = try self.readEdgeIndexRecordAt(old_file, old_header, old_pos);
                if (prev_old) |prev| {
                    if (!edgeIndexLessThan(order, prev, current)) return error.InvalidRecord;
                }
                prev_old = current;
                old_digest.add(current);
                while (batch_pos < batch_records.len and edgeIndexLessThan(order, batch_records[batch_pos], current)) : (batch_pos += 1) {
                    try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, batch_records[batch_pos]);
                    new_digest.add(batch_records[batch_pos]);
                }
                try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, current);
                new_digest.add(current);
            }
            if (old_digest.count != old_meta.edge_indexed_edges or old_digest.digest != old_meta.edge_index_digest or old_digest.order_digest != old_header.order_digest) return error.InvalidRecord;
            while (batch_pos < batch_records.len) : (batch_pos += 1) {
                try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, batch_records[batch_pos]);
                new_digest.add(batch_records[batch_pos]);
            }
            if (new_digest.count != next_count or new_digest.digest != next_digest) return error.InvalidRecord;
            try writer.flush();
            if (try writer.position() != expected_new_size) return error.InvalidRecord;
            if (try self.regularFileSize(new_file) != expected_new_size) return error.InvalidRecord;
            var new_header = rewrite_header;
            new_header.edge_digest = new_digest.digest;
            new_header.order_digest = new_digest.order_digest;
            new_header.encode(&header_bytes);
            try new_file.writePositionalAll(self.io, &header_bytes, 0);
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
            merged_order_digest = new_digest.order_digest;
        }
        try self.renameReplace(tmp_path, path);
        return .{ .order_digest = merged_order_digest };
    }

    fn writeEdgeIndexWithoutRecord(self: Store, path: []const u8, order: EdgeIndexOrder, old_meta: IndexMeta, removed: EdgeIndexRecord, next_digest: u64) !void {
        if (old_meta.edges == 0) return error.InvalidRecord;
        const next_count = old_meta.edges - 1;

        var old_file = try std.Io.Dir.cwd().openFile(self.io, path, .{ .mode = .read_write });
        defer old_file.close(self.io);
        const old_header = try self.readEdgeIndexHeaderFromFile(old_file);
        if (old_header.order != order) return error.InvalidRecord;
        if (old_header.edge_count != old_meta.edges) return error.InvalidRecord;
        if (old_header.edge_digest != old_meta.edge_digest) return error.InvalidRecord;
        if (old_header.order_digest != edgeOrderDigestForMeta(old_meta, order)) return error.InvalidRecord;
        const expected_old_size = try edgeIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;

        const rewrite_header = edgeIndexHeaderWithoutRecord(order, next_count, next_digest, 0, old_header, removed);
        const expected_new_size = try edgeIndexFileSizeForHeader(rewrite_header);
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(expected_new_size));
            defer writer.deinit();

            var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
            const placeholder_header = rewrite_header;
            placeholder_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var old_digest = EdgeIndexDigest{};
            var new_digest = EdgeIndexDigest{};
            var prev_old: ?EdgeIndexRecord = null;
            var removed_count: u64 = 0;
            var old_pos: u64 = 0;
            while (old_pos < old_header.edge_count) : (old_pos += 1) {
                const current = try self.readEdgeIndexRecordAt(old_file, old_header, old_pos);
                if (prev_old) |prev| {
                    if (!edgeIndexLessThan(order, prev, current)) return error.InvalidRecord;
                }
                prev_old = current;
                old_digest.add(current);
                if (edgeIndexRecordEquals(current, removed)) {
                    removed_count += 1;
                    continue;
                }
                try writeEdgeIndexRecordToWriter(&writer, rewrite_header, new_digest.count, current);
                new_digest.add(current);
            }
            if (removed_count != 1) return error.InvalidRecord;
            if (old_digest.count != old_header.edge_count or old_digest.digest != old_header.edge_digest or old_digest.order_digest != old_header.order_digest) return error.InvalidRecord;
            if (new_digest.count != next_count or new_digest.digest != next_digest) return error.InvalidRecord;
            try writer.flush();
            if (try writer.position() != expected_new_size) return error.InvalidRecord;
            if (try self.regularFileSize(new_file) != expected_new_size) return error.InvalidRecord;
            var new_header = rewrite_header;
            new_header.edge_digest = new_digest.digest;
            new_header.order_digest = new_digest.order_digest;
            new_header.encode(&header_bytes);
            try new_file.writePositionalAll(self.io, &header_bytes, 0);
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, path);
    }

    fn appendSortedEdgeIndexBatchTailIfPossible(
        self: Store,
        file: std.Io.File,
        old_header: EdgeIndexHeader,
        order: EdgeIndexOrder,
        batch_records: []const EdgeIndexRecord,
        next_count: u64,
        next_digest: u64,
    ) !?u64 {
        if (batch_records.len == 0) return old_header.order_digest;

        if (old_header.edge_count != 0) {
            const last_old = try self.readEdgeIndexRecordAt(file, old_header, old_header.edge_count - 1);
            if (!edgeIndexLessThan(order, last_old, batch_records[0])) return null;
        }

        var edge_digest = old_header.edge_digest;
        var order_digest = old_header.order_digest;
        var edge_count = old_header.edge_count;
        for (batch_records) |record| {
            edge_digest ^= edgeRecordDigest(record);
            order_digest = edgeIndexOrderDigestStep(order_digest, edge_count, record);
            edge_count = std.math.add(u64, edge_count, 1) catch return error.RecordTooLarge;
        }
        if (edge_count != next_count or edge_digest != next_digest) return error.InvalidRecord;

        const new_header = edgeIndexHeaderForTail(order, old_header, next_count, edge_digest, order_digest, batch_records);
        if (old_header.edge_count == 0 and new_header.hasKeyRuns()) {
            try file.setLength(self.io, 0);
            const expected_new_size = try edgeIndexFileSizeForHeader(new_header);
            try writeCompleteEdgeIndexFile(self, file, new_header, batch_records, expected_new_size);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
            return order_digest;
        }
        if (old_header.hasKeyRuns()) return null;
        if (old_header.edge_count != 0 and old_header.record_len != new_header.record_len) return null;
        const expected_new_size = try edgeIndexFileSizeForHeader(new_header);
        const tail_bytes = std.math.mul(u64, @intCast(batch_records.len), new_header.record_len) catch return error.RecordTooLarge;
        var writer = try StorageBufferedWriter.initAtOffset(
            self.allocator,
            self.io,
            file,
            try storageWriteBufferCapacity(tail_bytes),
            try edgeIndexRecordOffsetForHeader(new_header, old_header.edge_count),
        );
        defer writer.deinit();
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        for (batch_records, 0..) |record, i| {
            const encoded = record_bytes[0..new_header.record_len];
            try record.encodeForHeader(new_header, old_header.edge_count + @as(u64, @intCast(i)), null, encoded);
            try writer.append(encoded);
        }
        try writer.flush();
        if (try writer.position() != expected_new_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_new_size) return error.InvalidRecord;

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        new_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        return order_digest;
    }

    fn appendSortedEdgeIndexTail(self: Store, file: std.Io.File, old_header: EdgeIndexHeader, new_header: EdgeIndexHeader, record: EdgeIndexRecord) !void {
        if (new_header.edge_count != old_header.edge_count + 1) return error.InvalidRecord;
        if (old_header.edge_count == 0 and new_header.hasKeyRuns()) {
            try file.setLength(self.io, 0);
            const expected_new_size = try edgeIndexFileSizeForHeader(new_header);
            try writeCompleteEdgeIndexFile(self, file, new_header, &.{record}, expected_new_size);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
            return;
        }
        if (old_header.hasKeyRuns() or new_header.hasKeyRuns()) return error.InvalidRecord;
        if (old_header.edge_count != 0 and old_header.record_len != new_header.record_len) return error.InvalidRecord;
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        const encoded = record_bytes[0..new_header.record_len];
        try record.encodeForHeader(new_header, old_header.edge_count, null, encoded);
        const record_offset = try edgeIndexRecordOffsetForHeader(new_header, old_header.edge_count);
        try file.writePositionalAll(self.io, encoded, record_offset);
        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        new_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (try self.regularFileSize(file) != try edgeIndexFileSizeForHeader(new_header)) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn rebuildPersistentNodeIndexes(self: Store, graph: *const graph_mod.Graph) !void {
        var active_node_set = try buildActiveNodeSet(self.allocator, graph);
        defer active_node_set.deinit();
        const active_nodes = active_node_set.count;
        var max_node_id: u64 = 0;
        var first_kind: ?core.NodeKind = null;
        var mixed_kind = false;
        for (graph.nodes.items) |node| {
            if (node.status != .active) continue;
            const node_id = node.id.toInt();
            if (node.text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
            max_node_id = @max(max_node_id, node_id);
            if (first_kind) |kind| {
                if (kind != node.kind) mixed_kind = true;
            } else {
                first_kind = node.kind;
            }
        }
        var short_text_lens = true;
        for (graph.nodes.items) |node| {
            if (node.status != .active) continue;
            if (!nodeTextLenFitsU16(node.text.len)) {
                short_text_lens = false;
                break;
            }
        }
        const has_zero_length_text = blk: {
            for (graph.nodes.items) |node| {
                if (node.status == .active and node.text.len == 0) break :blk true;
            }
            break :blk false;
        };
        const uniform_kind = if (!mixed_kind and !has_zero_length_text) first_kind else null;
        var by_id_header = if (uniform_kind) |kind|
            nodeByIdHeaderForUniformKind(kind, max_node_id, active_nodes, 0, short_text_lens)
        else
            NodeByIdHeader{ .max_node_id = max_node_id, .node_count = active_nodes };
        _ = try self.nodeByIdFileSizeForHeaderStore(by_id_header);

        const texts_tmp_path = try self.tmpPathFor(self.node_texts_path);
        defer self.allocator.free(texts_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, texts_tmp_path) catch {};
        const by_id_tmp_path = try self.tmpPathFor(self.node_by_id_path);
        defer self.allocator.free(by_id_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, by_id_tmp_path) catch {};
        const node_text_repair_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_texts.tmp", .{self.node_by_text_path});
        defer self.allocator.free(node_text_repair_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, node_text_repair_path) catch {};

        var node_digest: u64 = 0;
        var node_text_record_count: usize = 0;
        {
            var texts_file = try std.Io.Dir.cwd().createFile(self.io, texts_tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer texts_file.close(self.io);
            var texts_writer = try StorageBufferedWriter.init(self.allocator, self.io, texts_file, storage_write_buffer_bytes);
            defer texts_writer.deinit();
            var text_repair_file = try std.Io.Dir.cwd().createFile(self.io, node_text_repair_path, .{
                .read = true,
                .truncate = true,
            });
            defer text_repair_file.close(self.io);
            var text_repair_writer = try StorageBufferedWriter.init(self.allocator, self.io, text_repair_file, storage_write_buffer_bytes);
            defer text_repair_writer.deinit();

            var index_file = try std.Io.Dir.cwd().createFile(self.io, by_id_tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer index_file.close(self.io);

            try self.writeNodeByIdHeader(index_file, by_id_header);
            try self.extendNodeByIdIndex(index_file, 0, max_node_id);

            for (graph.nodes.items) |node| {
                if (node.status != .active) continue;
                const node_id = node.id.toInt();
                const text_offset = try texts_writer.position();
                try texts_writer.append(node.text);
                node_digest ^= try nodeRecordDigestFromParts(node_id, node.kind, node.text);

                const record = NodeByIdRecord{
                    .id = node_id,
                    .kind = @intFromEnum(node.kind),
                    .text_offset = text_offset,
                    .text_len = @intCast(node.text.len),
                };
                try self.writeNodeByIdRecordAt(index_file, by_id_header, record);

                const text_record = NodeTextIndexRecord{
                    .hash = nodeTextHash(node.text),
                    .id = node_id,
                    .kind = @intFromEnum(node.kind),
                    .text_offset = text_offset,
                    .text_len = @intCast(node.text.len),
                };
                var text_record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
                try text_record.encode(&text_record_bytes);
                try text_repair_writer.append(&text_record_bytes);
                node_text_record_count = std.math.add(usize, node_text_record_count, 1) catch return error.InvalidRecord;
            }

            try texts_writer.flush();
            if (try self.regularFileSize(texts_file) != try texts_writer.position()) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try texts_file.sync(self.io);
            try text_repair_writer.flush();
            const expected_text_repair_size = std.math.mul(u64, @intCast(node_text_record_count), NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
            if (try text_repair_writer.position() != expected_text_repair_size) return error.InvalidRecord;
            if (try self.regularFileSize(text_repair_file) != expected_text_repair_size) return error.InvalidRecord;
            if (selfOptionsNeedSync(self)) try text_repair_file.sync(self.io);
            if (@as(u64, @intCast(node_text_record_count)) != active_nodes) return error.InvalidRecord;
            by_id_header.node_count = active_nodes;
            by_id_header.node_digest = node_digest;
            try self.writeNodeByIdHeader(index_file, by_id_header);
            try self.compactNodeByIdIndexToDerivedTextOffsets(index_file, &by_id_header);
            if (selfOptionsNeedSync(self)) try index_file.sync(self.io);
        }

        try self.renameReplace(texts_tmp_path, self.node_texts_path);
        try self.renameReplace(by_id_tmp_path, self.node_by_id_path);
        try self.finalizePrimaryTextStorage();

        const node_text_publish_shape = NodeTextRepairPublishShape{
            .uniform_kind = if (uniform_kind) |kind| @intFromEnum(kind) else null,
            .u32_id = max_node_id <= std.math.maxInt(u32),
            .derived_hash = false,
            .derived_text_span = true,
        };
        try self.writeNodeTextIndexFromRepairSpool(node_text_repair_path, node_text_record_count, node_digest, node_text_publish_shape);
        try self.writeEmptyNodeTextDelta();
        try self.deleteNodeTextRunManifest();
        std.Io.Dir.cwd().deleteFile(self.io, node_text_repair_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
    }

    fn writeEmptyNodeIndexes(self: Store) !void {
        const texts_tmp_path = try self.tmpPathFor(self.node_texts_path);
        defer self.allocator.free(texts_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, texts_tmp_path) catch {};
        const by_id_tmp_path = try self.tmpPathFor(self.node_by_id_path);
        defer self.allocator.free(by_id_tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, by_id_tmp_path) catch {};

        {
            var texts_file = try std.Io.Dir.cwd().createFile(self.io, texts_tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer texts_file.close(self.io);
            if (selfOptionsNeedSync(self)) try texts_file.sync(self.io);

            var index_file = try std.Io.Dir.cwd().createFile(self.io, by_id_tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer index_file.close(self.io);
            try self.writeNodeByIdHeader(index_file, .{ .max_node_id = 0, .node_count = 0 });
            if (selfOptionsNeedSync(self)) try index_file.sync(self.io);
        }

        try self.renameReplace(texts_tmp_path, self.node_texts_path);
        try self.renameReplace(by_id_tmp_path, self.node_by_id_path);

        try self.writeNodeTextIndex(&.{});
    }

    fn appendNodeIndexRecord(self: Store, node: graph_mod.Node, text_span: TextSpan) !void {
        if (node.status != .active) return;
        const old_meta = try self.readIndexMeta();
        const by_id_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        const text_record = try self.appendNodeByIdIndexRecord(node, text_span);
        if (self.node_append_timings) |timings| timings.by_id_index_ns += storageElapsedNs(self.io, by_id_start);
        const text_index_start = if (self.node_append_timings != null) storageMonotonicNs(self.io) else 0;
        try self.appendNodeTextIndexRecordChecked(text_record, old_meta.nodes, old_meta.node_digest, old_meta.node_by_text_order_digest);
        if (self.node_append_timings) |timings| timings.node_text_index_ns += storageElapsedNs(self.io, text_index_start);
    }

    fn appendNodeByIdIndexRecord(self: Store, node: graph_mod.Node, text_span: TextSpan) !NodeTextIndexRecord {
        const node_id = node.id.toInt();
        if (node_id == 0 or node_id == std.math.maxInt(u64)) return core.Error.InvalidId;
        if (node.text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        if (text_span.len != node.text.len) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().createFile(self.io, self.node_by_id_path, .{
            .read = true,
            .truncate = false,
        });
        defer index_file.close(self.io);
        var header = try self.readNodeByIdHeaderFromFile(index_file);
        if (header.hasDerivedTextOffset()) {
            var text_records = std.ArrayList(NodeTextIndexRecord).empty;
            defer text_records.deinit(self.allocator);
            try text_records.ensureTotalCapacity(self.allocator, 1);

            var next_meta = IndexMeta{
                .nodes = header.node_count,
                .node_digest = header.node_digest,
            };
            const nodes = [_]graph_mod.Node{node};
            const text_spans = [_]TextSpan{text_span};
            if (try self.appendNodeByIdDerivedDenseTailBatch(index_file, &header, &nodes, &text_spans, &text_records, &next_meta)) {
                if (text_records.items.len != 1) return error.InvalidRecord;
                if (selfOptionsNeedSync(self)) try index_file.sync(self.io);
                return text_records.items[0];
            }
        }
        if (header.hasDerivedTextOffset()) {
            try self.convertNodeByIdIndexToWideUniformRecords(index_file, &header);
        }
        const next_node_count = std.math.add(u64, header.node_count, 1) catch return error.RecordTooLarge;
        const next_max_node_id = @max(header.max_node_id, node_id);
        if (header.node_count == 0) {
            header = if (node.text.len == 0)
                NodeByIdHeader{ .max_node_id = header.max_node_id, .node_count = header.node_count, .node_digest = header.node_digest }
            else
                nodeByIdHeaderForUniformKind(node.kind, header.max_node_id, header.node_count, header.node_digest, nodeTextLenFitsU16(node.text.len));
            try self.writeNodeByIdHeader(index_file, header);
        } else if (header.hasUniformKind() and header.uniform_kind != @intFromEnum(node.kind)) {
            try self.convertNodeByIdIndexToFullRecords(index_file, &header);
        } else if (header.hasUniformKind() and header.hasShortTextLen() and !nodeTextLenFitsU16(node.text.len)) {
            try self.convertNodeByIdIndexToWideUniformRecords(index_file, &header);
        }
        _ = try self.nodeByIdFileSizeForHeaderStore(.{
            .max_node_id = next_max_node_id,
            .node_count = header.node_count,
            .node_digest = header.node_digest,
            .flags = header.flags,
            .record_len = header.record_len,
            .uniform_kind = header.uniform_kind,
        });
        if (node_id <= header.max_node_id) {
            const existing = try self.readNodeByIdRecordAt(index_file, header, node_id);
            if (existing.id != 0) return core.Error.InvalidId;
        }

        const node_digest = try nodeRecordDigestFromParts(node_id, node.kind, node.text);

        if (node_id > header.max_node_id) {
            try self.extendNodeByIdIndex(index_file, header.max_node_id, node_id);
            header.max_node_id = node_id;
        }

        const record = NodeByIdRecord{
            .id = node_id,
            .kind = @intFromEnum(node.kind),
            .text_offset = text_span.offset,
            .text_len = @intCast(node.text.len),
        };
        try self.writeNodeByIdRecordAt(index_file, header, record);
        header.node_count = next_node_count;
        header.node_digest ^= node_digest;
        try self.writeNodeByIdHeader(index_file, header);
        try self.compactNodeByIdIndexToDerivedTextOffsets(index_file, &header);
        if (selfOptionsNeedSync(self)) try index_file.sync(self.io);

        return .{
            .hash = nodeTextHash(node.text),
            .id = node_id,
            .kind = @intFromEnum(node.kind),
            .text_offset = text_span.offset,
            .text_len = @intCast(node.text.len),
        };
    }

    fn nodeByIdHeaderForUniformKind(kind: core.NodeKind, max_node_id: u64, node_count: u64, node_digest: u64, short_text_len: bool) NodeByIdHeader {
        var header = NodeByIdHeader.uniform(kind, short_text_len);
        header.max_node_id = max_node_id;
        header.node_count = node_count;
        header.node_digest = node_digest;
        return header;
    }

    fn nodeByIdCanUseUniformAppend(header: NodeByIdHeader, nodes: []const graph_mod.Node) bool {
        if (nodes.len == 0) return false;
        const first_kind = nodes[0].kind;
        if (header.node_count == 0) {
            for (nodes) |node| {
                if (node.kind != first_kind) return false;
            }
            return true;
        }
        if (!header.hasUniformKind()) return false;
        if (header.uniform_kind != @intFromEnum(first_kind)) return false;
        for (nodes) |node| {
            if (node.kind != first_kind) return false;
        }
        return true;
    }

    fn nodeByIdBatchIsDenseTail(header: NodeByIdHeader, nodes: []const graph_mod.Node) bool {
        if (nodes.len == 0) return false;
        if (header.max_node_id == std.math.maxInt(u64)) return false;
        var expected_id = header.max_node_id + 1;
        for (nodes, 0..) |node, index| {
            if (node.id.toInt() != expected_id) return false;
            if (index + 1 < nodes.len) {
                if (expected_id == std.math.maxInt(u64)) return false;
                expected_id += 1;
            }
        }
        return true;
    }

    fn nodeByIdCanAppendDerivedDenseTail(header: NodeByIdHeader, nodes: []const graph_mod.Node) bool {
        return header.hasDerivedTextOffset() and
            nodeByIdBatchIsDenseTail(header, nodes) and
            nodeByIdCanUseUniformAppend(header, nodes) and
            nodeBatchTextsFitU16(nodes);
    }

    fn nodeBatchTextsFitU16(nodes: []const graph_mod.Node) bool {
        for (nodes) |node| {
            if (!nodeTextLenFitsU16(node.text.len)) return false;
        }
        return true;
    }

    fn nodeBatchHasZeroLengthText(nodes: []const graph_mod.Node) bool {
        for (nodes) |node| {
            if (node.text.len == 0) return true;
        }
        return false;
    }

    fn appendNodeByIdInitialDerivedDenseBatch(
        self: Store,
        file: std.Io.File,
        header: *NodeByIdHeader,
        nodes: []const graph_mod.Node,
        text_spans: []const TextSpan,
        text_records: *std.ArrayList(NodeTextIndexRecord),
        next_meta: *IndexMeta,
    ) !bool {
        if (nodes.len == 0) return false;
        if (nodes.len != text_spans.len) return error.InvalidRecord;
        if (header.node_count != 0 or header.max_node_id != 0 or header.node_digest != 0) return false;
        if (!nodeByIdBatchIsDenseTail(header.*, nodes)) return false;
        if (!nodeByIdCanUseUniformAppend(header.*, nodes)) return false;
        if (!nodeBatchTextsFitU16(nodes)) return false;
        if (text_spans[0].offset != 0) return false;
        if (try self.regularFileSize(file) != try self.nodeByIdFileSizeForHeaderStore(header.*)) return error.InvalidRecord;

        var validated_text_end: u64 = 0;
        for (nodes, text_spans) |node, text_span| {
            if (text_span.len != node.text.len) return error.InvalidRecord;
            if (text_span.offset != validated_text_end) return false;
            validated_text_end = std.math.add(u64, validated_text_end, text_span.len) catch return error.InvalidRecord;
        }

        var next_header = nodeByIdHeaderForUniformKind(
            nodes[0].kind,
            nodes[nodes.len - 1].id.toInt(),
            @intCast(nodes.len),
            0,
            true,
        );
        next_header.flags |= NodeByIdHeader.flag_derived_text_offset;
        next_header.record_len = next_header.expectedRecordLen();
        try next_header.validateShape();

        var record_writer = try StorageBufferedWriter.initAtOffset(
            self.allocator,
            self.io,
            file,
            storage_write_buffer_bytes,
            try nodeByIdRecordOffsetForHeader(next_header, nodes[0].id.toInt()),
        );
        defer record_writer.deinit();

        var len_bytes: [2]u8 = undefined;
        var expected_text_offset: u64 = 0;
        for (nodes, text_spans) |node, text_span| {
            if (text_span.offset != expected_text_offset) return error.InvalidRecord;
            const node_id = node.id.toInt();
            const node_digest = try nodeRecordDigestFromParts(node_id, node.kind, node.text);
            const text_len = std.math.cast(u16, node.text.len) orelse return error.InvalidRecord;
            std.mem.writeInt(u16, &len_bytes, text_len, .little);
            try record_writer.append(&len_bytes);
            try text_records.append(self.allocator, .{
                .hash = nodeTextHash(node.text),
                .id = node_id,
                .kind = @intFromEnum(node.kind),
                .text_offset = text_span.offset,
                .text_len = @intCast(node.text.len),
            });
            next_meta.nodes = std.math.add(u64, next_meta.nodes, 1) catch return error.InvalidRecord;
            next_meta.node_digest ^= node_digest;
            expected_text_offset = std.math.add(u64, expected_text_offset, text_span.len) catch return error.InvalidRecord;
        }
        try record_writer.flush();

        next_header.node_digest = next_meta.node_digest;
        if (next_header.node_count != next_meta.nodes) return error.InvalidRecord;
        if (try record_writer.position() != try nodeByIdTextOffsetCheckpointTableOffset(next_header)) return error.InvalidRecord;
        const expected_new_size = try self.nodeByIdFileSizeForHeaderStore(next_header);
        try file.setLength(self.io, expected_new_size);

        var checkpoint_value: u64 = 0;
        var checkpoint_index: usize = 0;
        const checkpoint_count = try nodeByIdTextOffsetCheckpointCount(next_header);
        var block: u64 = 0;
        while (block < checkpoint_count) : (block += 1) {
            const block_start_base = std.math.mul(u64, block, node_by_id_text_offset_checkpoint_stride) catch return error.InvalidRecord;
            const block_start_id = std.math.add(u64, block_start_base, 1) catch return error.InvalidRecord;
            const before_block = std.math.cast(usize, block_start_id - 1) orelse return error.RecordTooLarge;
            if (before_block > text_spans.len) return error.InvalidRecord;
            while (checkpoint_index < before_block) : (checkpoint_index += 1) {
                checkpoint_value = std.math.add(u64, checkpoint_value, text_spans[checkpoint_index].len) catch return error.InvalidRecord;
            }
            var checkpoint_bytes: [8]u8 = undefined;
            std.mem.writeInt(u64, &checkpoint_bytes, checkpoint_value, .little);
            try file.writePositionalAll(self.io, &checkpoint_bytes, try nodeByIdTextOffsetCheckpointOffset(next_header, block));
        }

        try self.writeNodeByIdHeader(file, next_header);
        if (try self.regularFileSize(file) != expected_new_size) return error.InvalidRecord;
        header.* = next_header;
        return true;
    }

    fn appendNodeByIdDerivedDenseTailBatch(
        self: Store,
        file: std.Io.File,
        header: *NodeByIdHeader,
        nodes: []const graph_mod.Node,
        text_spans: []const TextSpan,
        text_records: *std.ArrayList(NodeTextIndexRecord),
        next_meta: *IndexMeta,
    ) !bool {
        if (!nodeByIdCanAppendDerivedDenseTail(header.*, nodes)) return false;
        if (nodes.len != text_spans.len) return error.InvalidRecord;

        const old_header = header.*;
        const old_size = try self.nodeByIdFileSizeForHeaderStore(old_header);
        if (try self.regularFileSize(file) != old_size) return error.InvalidRecord;

        var expected_text_offset: u64 = if (old_header.max_node_id == 0) 0 else blk: {
            const last = try self.readNodeByIdRecordAt(file, old_header, old_header.max_node_id);
            break :blk std.math.add(u64, last.text_offset, last.text_len) catch return error.InvalidRecord;
        };
        if (text_spans[0].offset != expected_text_offset) return false;
        var validated_text_end = expected_text_offset;
        for (nodes, text_spans) |node, text_span| {
            if (text_span.len != node.text.len) return error.InvalidRecord;
            if (text_span.offset != validated_text_end) return false;
            validated_text_end = std.math.add(u64, validated_text_end, text_span.len) catch return error.InvalidRecord;
        }

        const old_checkpoint_count = try nodeByIdTextOffsetCheckpointCount(old_header);
        const old_checkpoint_bytes_len_u64 = std.math.mul(u64, old_checkpoint_count, 8) catch return error.InvalidRecord;
        const old_checkpoint_bytes_len = std.math.cast(usize, old_checkpoint_bytes_len_u64) orelse return error.RecordTooLarge;
        const old_checkpoint_bytes = try self.allocator.alloc(u8, old_checkpoint_bytes_len);
        defer self.allocator.free(old_checkpoint_bytes);
        if (old_checkpoint_bytes.len != 0) {
            const bytes_read = try file.readPositionalAll(self.io, old_checkpoint_bytes, try nodeByIdTextOffsetCheckpointTableOffset(old_header));
            if (bytes_read != old_checkpoint_bytes.len) return error.InvalidRecord;
        }

        var next_header = old_header;
        next_header.max_node_id = nodes[nodes.len - 1].id.toInt();
        next_header.node_count = std.math.add(u64, old_header.node_count, @intCast(nodes.len)) catch return error.RecordTooLarge;

        var record_writer = try StorageBufferedWriter.initAtOffset(
            self.allocator,
            self.io,
            file,
            storage_write_buffer_bytes,
            try nodeByIdRecordOffsetForHeader(next_header, nodes[0].id.toInt()),
        );
        defer record_writer.deinit();

        var record_bytes: [NodeByIdRecord.uniform_short_derived_offset_encoded_len]u8 = undefined;
        for (nodes, text_spans) |node, text_span| {
            if (text_span.len != node.text.len) return error.InvalidRecord;
            if (text_span.offset != expected_text_offset) return error.InvalidRecord;
            const node_digest = try nodeRecordDigestFromParts(node.id.toInt(), node.kind, node.text);
            const record = NodeByIdRecord{
                .id = node.id.toInt(),
                .kind = @intFromEnum(node.kind),
                .text_offset = text_span.offset,
                .text_len = @intCast(node.text.len),
            };
            try record.encodeForHeader(next_header, &record_bytes);
            try record_writer.append(&record_bytes);
            try text_records.append(self.allocator, .{
                .hash = nodeTextHash(node.text),
                .id = node.id.toInt(),
                .kind = @intFromEnum(node.kind),
                .text_offset = text_span.offset,
                .text_len = @intCast(node.text.len),
            });
            next_meta.nodes = std.math.add(u64, next_meta.nodes, 1) catch return error.InvalidRecord;
            next_meta.node_digest ^= node_digest;
            expected_text_offset = std.math.add(u64, expected_text_offset, text_span.len) catch return error.InvalidRecord;
        }
        try record_writer.flush();

        next_header.node_digest = next_meta.node_digest;
        if (next_header.node_count != next_meta.nodes) return error.InvalidRecord;
        if (try record_writer.position() != try nodeByIdTextOffsetCheckpointTableOffset(next_header)) return error.InvalidRecord;
        const expected_new_size = try self.nodeByIdFileSizeForHeaderStore(next_header);
        try file.setLength(self.io, expected_new_size);

        const new_checkpoint_table_offset = try nodeByIdTextOffsetCheckpointTableOffset(next_header);
        if (old_checkpoint_bytes.len != 0) {
            try file.writePositionalAll(self.io, old_checkpoint_bytes, new_checkpoint_table_offset);
        }

        const new_checkpoint_count = try nodeByIdTextOffsetCheckpointCount(next_header);
        var appended_len_prefix: u64 = 0;
        var appended_index: usize = 0;
        var block = old_checkpoint_count;
        while (block < new_checkpoint_count) : (block += 1) {
            const block_start_base = std.math.mul(u64, block, node_by_id_text_offset_checkpoint_stride) catch return error.InvalidRecord;
            const block_start_id = std.math.add(u64, block_start_base, 1) catch return error.InvalidRecord;
            if (block_start_id <= old_header.max_node_id) return error.InvalidRecord;
            const first_new_id = old_header.max_node_id + 1;
            const appended_before = std.math.cast(usize, block_start_id - first_new_id) orelse return error.RecordTooLarge;
            if (appended_before > text_spans.len) return error.InvalidRecord;
            while (appended_index < appended_before) : (appended_index += 1) {
                appended_len_prefix = std.math.add(u64, appended_len_prefix, text_spans[appended_index].len) catch return error.InvalidRecord;
            }
            const checkpoint_value = std.math.add(u64, text_spans[0].offset, appended_len_prefix) catch return error.InvalidRecord;
            var checkpoint_bytes: [8]u8 = undefined;
            std.mem.writeInt(u64, &checkpoint_bytes, checkpoint_value, .little);
            try file.writePositionalAll(self.io, &checkpoint_bytes, try nodeByIdTextOffsetCheckpointOffset(next_header, block));
        }

        try self.writeNodeByIdHeader(file, next_header);
        if (try self.regularFileSize(file) != expected_new_size) return error.InvalidRecord;
        header.* = next_header;
        return true;
    }

    fn convertNodeByIdIndexToFullRecords(self: Store, file: std.Io.File, header: *NodeByIdHeader) !void {
        if (!header.hasUniformKind()) return;
        const old_header = header.*;
        var full_header = NodeByIdHeader{
            .max_node_id = old_header.max_node_id,
            .node_count = old_header.node_count,
            .node_digest = old_header.node_digest,
        };
        try full_header.validateShape();
        try file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(full_header));
        var id = old_header.max_node_id;
        while (id > 0) : (id -= 1) {
            const record = try self.readNodeByIdRecordAt(file, old_header, id);
            var bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
            try record.encode(&bytes);
            try file.writePositionalAll(self.io, &bytes, try nodeByIdRecordOffsetForHeader(full_header, id));
        }
        try self.writeNodeByIdHeader(file, full_header);
        header.* = full_header;
    }

    fn convertNodeByIdIndexToWideUniformRecords(self: Store, file: std.Io.File, header: *NodeByIdHeader) !void {
        if (!header.hasUniformKind() or !header.hasShortTextLen()) return;
        const old_header = header.*;
        var wide_header = NodeByIdHeader{
            .max_node_id = old_header.max_node_id,
            .node_count = old_header.node_count,
            .node_digest = old_header.node_digest,
            .flags = if (old_header.hasDerivedTextOffset())
                NodeByIdHeader.flag_uniform_kind | NodeByIdHeader.flag_short_text_len
            else
                NodeByIdHeader.flag_uniform_kind,
            .record_len = if (old_header.hasDerivedTextOffset())
                NodeByIdRecord.uniform_short_text_len_encoded_len
            else
                NodeByIdRecord.uniform_encoded_len,
            .uniform_kind = old_header.uniform_kind,
        };
        try wide_header.validateShape();
        if (old_header.hasDerivedTextOffset()) {
            const node_count = std.math.cast(usize, old_header.node_count) orelse return error.RecordTooLarge;
            var lengths = try self.allocator.alloc(u16, node_count);
            defer self.allocator.free(lengths);

            var id: u64 = 1;
            while (id <= old_header.max_node_id) : (id += 1) {
                lengths[@intCast(id - 1)] = std.math.cast(u16, try self.readDerivedNodeByIdTextLenAt(file, old_header, id)) orelse return error.InvalidRecord;
            }

            try file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(wide_header));
            var text_offset: u64 = 0;
            for (lengths, 0..) |text_len, index| {
                const node_id: u64 = @intCast(index + 1);
                const record = NodeByIdRecord{
                    .id = node_id,
                    .kind = old_header.uniform_kind,
                    .text_offset = text_offset,
                    .text_len = text_len,
                };
                var bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
                const encoded = bytes[0..wide_header.record_len];
                try record.encodeForHeader(wide_header, encoded);
                try file.writePositionalAll(self.io, encoded, try nodeByIdRecordOffsetForHeader(wide_header, node_id));
                text_offset = std.math.add(u64, text_offset, text_len) catch return error.InvalidRecord;
            }
            try self.writeNodeByIdHeader(file, wide_header);
            header.* = wide_header;
            return;
        }
        try file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(wide_header));
        var id = old_header.max_node_id;
        while (id > 0) : (id -= 1) {
            const record = try self.readNodeByIdRecordAt(file, old_header, id);
            var bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
            const encoded = bytes[0..wide_header.record_len];
            try record.encodeForHeader(wide_header, encoded);
            try file.writePositionalAll(self.io, encoded, try nodeByIdRecordOffsetForHeader(wide_header, id));
        }
        try self.writeNodeByIdHeader(file, wide_header);
        header.* = wide_header;
    }

    fn compactNodeByIdIndexToUniformRecords(self: Store, file: std.Io.File, header: *NodeByIdHeader, kind: core.NodeKind) !void {
        if (header.hasUniformKind()) return;
        const old_header = header.*;
        const old_size = try self.nodeByIdFileSizeForHeaderStore(old_header);
        if (try self.regularFileSize(file) != old_size) return error.InvalidRecord;
        var old_map = openReadOnlyMemoryMap(self.io, file, old_size) catch null;
        defer if (old_map) |*mapped| mapped.destroy(self.io);

        var short_text_lens = true;
        var check_id: u64 = 1;
        while (check_id <= old_header.max_node_id) : (check_id += 1) {
            const record = if (old_map) |*mapped|
                try readNodeByIdRecordFromMap(old_header, mapped, check_id)
            else
                try self.readNodeByIdRecordAt(file, old_header, check_id);
            if (record.id != 0 and record.text_len == 0) return;
            if (record.id != 0 and !nodeRecordHasShortTextLen(record)) {
                short_text_lens = false;
                break;
            }
        }
        var uniform_header = nodeByIdHeaderForUniformKind(kind, old_header.max_node_id, old_header.node_count, old_header.node_digest, short_text_lens);
        try uniform_header.validateShape();
        var id: u64 = 1;
        while (id <= old_header.max_node_id) : (id += 1) {
            const record = if (old_map) |*mapped|
                try readNodeByIdRecordFromMap(old_header, mapped, id)
            else
                try self.readNodeByIdRecordAt(file, old_header, id);
            var bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
            const encoded = bytes[0..uniform_header.record_len];
            try record.encodeForHeader(uniform_header, encoded);
            try file.writePositionalAll(self.io, encoded, try nodeByIdRecordOffsetForHeader(uniform_header, id));
        }
        if (old_map) |*mapped| {
            mapped.destroy(self.io);
            old_map = null;
        }
        try file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(uniform_header));
        try self.writeNodeByIdHeader(file, uniform_header);
        header.* = uniform_header;
    }

    fn rewriteNodeByIdIndexToUniformRecordsFromTextRepair(
        self: Store,
        file: std.Io.File,
        header: *NodeByIdHeader,
        kind: core.NodeKind,
        text_repair_file: std.Io.File,
        node_count: u64,
        short_text_lens: bool,
    ) !void {
        if (header.hasUniformKind()) return;
        const old_header = header.*;
        if (old_header.node_count != node_count) return error.InvalidRecord;
        var uniform_header = nodeByIdHeaderForUniformKind(kind, old_header.max_node_id, old_header.node_count, old_header.node_digest, short_text_lens);
        try uniform_header.validateShape();
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(uniform_header);

        var record_bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
        var text_record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        var index: u64 = 0;
        while (index < node_count) : (index += 1) {
            const offset = std.math.mul(u64, index, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
            const n = try text_repair_file.readPositionalAll(self.io, &text_record_bytes, offset);
            if (n != text_record_bytes.len) return error.InvalidRecord;
            const text_record = try NodeTextIndexRecord.decode(&text_record_bytes);
            if (text_record.kind != @intFromEnum(kind)) return error.InvalidRecord;
            if (text_record.text_len == 0) return;
        }

        try file.setLength(self.io, 0);
        try file.setLength(self.io, expected_size);

        index = 0;
        while (index < node_count) : (index += 1) {
            const offset = std.math.mul(u64, index, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
            const n = try text_repair_file.readPositionalAll(self.io, &text_record_bytes, offset);
            if (n != text_record_bytes.len) return error.InvalidRecord;
            const text_record = try NodeTextIndexRecord.decode(&text_record_bytes);
            if (text_record.kind != @intFromEnum(kind)) return error.InvalidRecord;

            const node_record = NodeByIdRecord{
                .id = text_record.id,
                .kind = text_record.kind,
                .text_offset = text_record.text_offset,
                .text_len = text_record.text_len,
            };
            const encoded = record_bytes[0..uniform_header.record_len];
            try node_record.encodeForHeader(uniform_header, encoded);
            try file.writePositionalAll(self.io, encoded, try nodeByIdRecordOffsetForHeader(uniform_header, node_record.id));
        }

        try self.writeNodeByIdHeader(file, uniform_header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        header.* = uniform_header;
    }

    fn compactNodeByIdIndexToDerivedTextOffsets(self: Store, file: std.Io.File, header: *NodeByIdHeader) !void {
        try header.validateShape();
        if (header.hasDerivedTextOffset()) return;
        if (!header.hasUniformKind()) return;
        if (header.node_count == 0 or header.node_count != header.max_node_id) return;

        const old_header = header.*;
        const old_size = try self.nodeByIdFileSizeForHeaderStore(old_header);
        if (try self.regularFileSize(file) != old_size) return error.InvalidRecord;
        var old_map = openReadOnlyMemoryMap(self.io, file, old_size) catch null;
        defer if (old_map) |*mapped| mapped.destroy(self.io);

        const node_count = std.math.cast(usize, old_header.node_count) orelse return error.RecordTooLarge;
        var lengths = try self.allocator.alloc(u16, node_count);
        defer self.allocator.free(lengths);

        const texts_size = try self.nodeTextsLogicalSize();
        var expected_offset: u64 = 0;
        var id: u64 = 1;
        while (id <= old_header.max_node_id) : (id += 1) {
            const record = if (old_map) |*mapped|
                try readNodeByIdRecordFromMap(old_header, mapped, id)
            else
                try self.readNodeByIdRecordAt(file, old_header, id);
            if (record.id != id) return;
            if (record.text_offset != expected_offset) return;
            const short_len = std.math.cast(u16, record.text_len) orelse return;
            lengths[@intCast(id - 1)] = short_len;
            expected_offset = std.math.add(u64, expected_offset, record.text_len) catch return error.InvalidRecord;
        }
        if (expected_offset != texts_size) return;
        if (old_map) |*mapped| {
            mapped.destroy(self.io);
            old_map = null;
        }

        var derived_header = old_header;
        derived_header.flags |= NodeByIdHeader.flag_short_text_len | NodeByIdHeader.flag_derived_text_offset;
        derived_header.record_len = derived_header.expectedRecordLen();
        try derived_header.validateShape();

        var row_bytes: [2]u8 = undefined;
        for (lengths, 0..) |text_len, index| {
            std.mem.writeInt(u16, &row_bytes, text_len, .little);
            const node_id: u64 = @intCast(index + 1);
            try file.writePositionalAll(self.io, &row_bytes, try nodeByIdRecordOffsetForHeader(derived_header, node_id));
        }

        var checkpoint_offset_value: u64 = 0;
        var checkpoint_block: u64 = 0;
        for (lengths, 0..) |text_len, index| {
            if ((@as(u64, @intCast(index)) % node_by_id_text_offset_checkpoint_stride) == 0) {
                var checkpoint_bytes: [8]u8 = undefined;
                std.mem.writeInt(u64, &checkpoint_bytes, checkpoint_offset_value, .little);
                try file.writePositionalAll(self.io, &checkpoint_bytes, try nodeByIdTextOffsetCheckpointOffset(derived_header, checkpoint_block));
                checkpoint_block += 1;
            }
            checkpoint_offset_value = std.math.add(u64, checkpoint_offset_value, text_len) catch return error.InvalidRecord;
        }
        try file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(derived_header));
        try self.writeNodeByIdHeader(file, derived_header);
        header.* = derived_header;
    }

    fn rewriteNodeByIdIndexToDerivedDenseLengths(
        self: Store,
        file: std.Io.File,
        header: *NodeByIdHeader,
        kind: core.NodeKind,
        lengths: []const u16,
    ) !void {
        try header.validateShape();
        if (header.node_count == 0 or header.node_count != header.max_node_id) return error.InvalidRecord;
        if (lengths.len != header.node_count) return error.InvalidRecord;

        var derived_header = nodeByIdHeaderForUniformKind(kind, header.max_node_id, header.node_count, header.node_digest, true);
        derived_header.flags |= NodeByIdHeader.flag_derived_text_offset;
        derived_header.record_len = derived_header.expectedRecordLen();
        try derived_header.validateShape();

        const expected_size = try self.nodeByIdFileSizeForHeaderStore(derived_header);
        try file.setLength(self.io, expected_size);

        var record_writer = try StorageBufferedWriter.initAtOffset(
            self.allocator,
            self.io,
            file,
            storage_write_buffer_bytes,
            try nodeByIdRecordOffsetForHeader(derived_header, 1),
        );
        defer record_writer.deinit();

        var row_bytes: [NodeByIdRecord.uniform_short_derived_offset_encoded_len]u8 = undefined;
        for (lengths) |text_len| {
            std.mem.writeInt(u16, &row_bytes, text_len, .little);
            try record_writer.append(&row_bytes);
        }
        try record_writer.flush();
        if (try record_writer.position() != try nodeByIdTextOffsetCheckpointTableOffset(derived_header)) return error.InvalidRecord;

        var checkpoint_offset_value: u64 = 0;
        var checkpoint_block: u64 = 0;
        for (lengths, 0..) |text_len, index| {
            if ((@as(u64, @intCast(index)) % node_by_id_text_offset_checkpoint_stride) == 0) {
                var checkpoint_bytes: [8]u8 = undefined;
                std.mem.writeInt(u64, &checkpoint_bytes, checkpoint_offset_value, .little);
                try file.writePositionalAll(self.io, &checkpoint_bytes, try nodeByIdTextOffsetCheckpointOffset(derived_header, checkpoint_block));
                checkpoint_block += 1;
            }
            checkpoint_offset_value = std.math.add(u64, checkpoint_offset_value, text_len) catch return error.InvalidRecord;
        }
        if (checkpoint_block != try nodeByIdTextOffsetCheckpointCount(derived_header)) return error.InvalidRecord;

        try self.writeNodeByIdHeader(file, derived_header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        header.* = derived_header;
    }

    fn appendNodeByIdIndexRecordsBatch(
        self: Store,
        old_meta: IndexMeta,
        nodes: []const graph_mod.Node,
        text_spans: []const TextSpan,
        text_records: *std.ArrayList(NodeTextIndexRecord),
        next_meta: *IndexMeta,
    ) !void {
        if (nodes.len == 0) return;
        if (nodes.len != text_spans.len) return error.InvalidRecord;

        var index_file = try std.Io.Dir.cwd().createFile(self.io, self.node_by_id_path, .{
            .read = true,
            .truncate = false,
        });
        defer index_file.close(self.io);
        var header = try self.readNodeByIdHeaderFromFile(index_file);
        if (header.node_count != old_meta.nodes) return error.InvalidRecord;
        if (header.node_digest != old_meta.node_digest) return error.InvalidRecord;
        if (header.node_count > header.max_node_id) return error.InvalidRecord;

        if (try self.appendNodeByIdInitialDerivedDenseBatch(index_file, &header, nodes, text_spans, text_records, next_meta)) {
            if (selfOptionsNeedSync(self)) {
                try index_file.sync(self.io);
            }
            return;
        }

        if (try self.appendNodeByIdDerivedDenseTailBatch(index_file, &header, nodes, text_spans, text_records, next_meta)) {
            if (selfOptionsNeedSync(self)) {
                try index_file.sync(self.io);
            }
            return;
        }

        if (header.hasDerivedTextOffset()) {
            try self.convertNodeByIdIndexToWideUniformRecords(index_file, &header);
        }

        var next_max_node_id = header.max_node_id;
        var dense_tail = true;
        var expected_dense_id = std.math.add(u64, header.max_node_id, 1) catch return error.InvalidRecord;
        for (nodes) |node| {
            const node_id = node.id.toInt();
            next_max_node_id = @max(next_max_node_id, node_id);
            if (node_id != expected_dense_id) dense_tail = false;
            expected_dense_id = std.math.add(u64, expected_dense_id, 1) catch std.math.maxInt(u64);
        }
        const has_zero_length_text = nodeBatchHasZeroLengthText(nodes);
        if (!has_zero_length_text and nodeByIdCanUseUniformAppend(header, nodes)) {
            if (header.node_count == 0) {
                header = nodeByIdHeaderForUniformKind(nodes[0].kind, header.max_node_id, header.node_count, header.node_digest, nodeBatchTextsFitU16(nodes));
                try self.writeNodeByIdHeader(index_file, header);
            }
            if (header.hasShortTextLen() and !nodeBatchTextsFitU16(nodes)) {
                try self.convertNodeByIdIndexToWideUniformRecords(index_file, &header);
            }
        } else if (header.hasUniformKind()) {
            try self.convertNodeByIdIndexToFullRecords(index_file, &header);
        }
        _ = try self.nodeByIdFileSizeForHeaderStore(.{
            .max_node_id = next_max_node_id,
            .node_count = header.node_count,
            .node_digest = header.node_digest,
            .flags = header.flags,
            .record_len = header.record_len,
            .uniform_kind = header.uniform_kind,
        });

        if (next_max_node_id > header.max_node_id) {
            try self.extendNodeByIdIndex(index_file, header.max_node_id, next_max_node_id);
            header.max_node_id = next_max_node_id;
        }

        var dense_writer: ?StorageBufferedWriter = null;
        defer if (dense_writer) |*writer| writer.deinit();
        if (dense_tail) {
            dense_writer = try StorageBufferedWriter.initAtOffset(
                self.allocator,
                self.io,
                index_file,
                storage_write_buffer_bytes,
                try nodeByIdRecordOffsetForHeader(header, nodes[0].id.toInt()),
            );
        }

        for (nodes, text_spans) |node, text_span| {
            const node_id = node.id.toInt();
            if (text_span.len != node.text.len) return error.InvalidRecord;
            const node_digest = try nodeRecordDigestFromParts(node_id, node.kind, node.text);
            const record = NodeByIdRecord{
                .id = node_id,
                .kind = @intFromEnum(node.kind),
                .text_offset = text_span.offset,
                .text_len = @intCast(node.text.len),
            };
            var record_bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
            const encoded = record_bytes[0..header.record_len];
            try record.encodeForHeader(header, encoded);
            if (dense_writer) |*writer| {
                try writer.append(encoded);
            } else {
                try index_file.writePositionalAll(self.io, encoded, try nodeByIdRecordOffsetForHeader(header, node_id));
            }
            try text_records.append(self.allocator, .{
                .hash = nodeTextHash(node.text),
                .id = node_id,
                .kind = @intFromEnum(node.kind),
                .text_offset = text_span.offset,
                .text_len = @intCast(node.text.len),
            });
            next_meta.nodes = std.math.add(u64, next_meta.nodes, 1) catch return error.InvalidRecord;
            next_meta.node_digest ^= node_digest;
        }

        if (dense_writer) |*writer| try writer.flush();

        header.node_count = next_meta.nodes;
        header.node_digest = next_meta.node_digest;
        try self.writeNodeByIdHeader(index_file, header);
        try self.compactNodeByIdIndexToDerivedTextOffsets(index_file, &header);
        if (selfOptionsNeedSync(self)) {
            try index_file.sync(self.io);
        }
    }

    fn appendNodeTextIndexRecordChecked(self: Store, record: NodeTextIndexRecord, expected_count: u64, expected_digest: u64, expected_order_digest: u64) !void {
        var expected_order = expected_order_digest;
        var compacted = false;
        while (true) {
            var old_meta = IndexMeta{
                .nodes = expected_count,
                .node_digest = expected_digest,
                .node_by_text_order_digest = expected_order,
            };
            var compact_overlays = false;
            {
                var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .mode = .read_write, .allow_directory = false });
                defer old_file.close(self.io);
                const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
                const delta_header = try self.readNodeTextDeltaHeader();
                var manifest = try self.readNodeTextRunManifest(self.allocator);
                defer manifest.deinit(self.allocator);
                const run_count = manifest.totalNodeCount();
                if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
                if (old_header.node_count + delta_header.node_count + run_count != expected_count) return error.InvalidRecord;
                if ((old_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != expected_digest) return error.InvalidRecord;
                if (combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items) != expected_order) return error.InvalidRecord;

                if (delta_header.node_count == 0 and old_header.node_count == 0) {
                    return try self.appendNodeTextIndexRecordWithHeader(old_file, old_header, record);
                }
                if (delta_header.node_count == 0) {
                    const last = try self.readNodeTextIndexRecordAtForHeader(old_file, old_header, old_header.node_count - 1);
                    if (!nodeTextIndexLessThan({}, record, last)) {
                        return try self.appendNodeTextIndexRecordWithHeader(old_file, old_header, record);
                    }
                }

                if (delta_header.node_count >= node_text_single_append_delta_flush_records) {
                    if (try self.publishNodeTextDeltaAsRunForMeta(old_meta, old_header, delta_header, manifest.entries.items)) |next_order| {
                        expected_order = next_order;
                        compacted = false;
                        continue;
                    }
                }
                if (delta_header.node_count < node_text_delta_max_records) {
                    try self.ensureNodeTextBaseHashFilter(old_header);
                    return try self.appendNodeTextDeltaRecord(record, delta_header);
                }
                if (try self.publishNodeTextRunRecordIfPossible(old_meta, record)) {
                    return;
                }
                if (compacted) return error.InvalidRecord;
                compact_overlays = true;
            }
            if (compact_overlays) {
                var manifest = try self.readNodeTextRunManifest(self.allocator);
                defer manifest.deinit(self.allocator);
                const delta_header = try self.readNodeTextDeltaHeader();
                if (try self.compactNodeTextRunWindowForMeta(old_meta, manifest.entries.items, delta_header, 0, &.{})) |_| {
                    old_meta = try self.readIndexMeta();
                    if (old_meta.nodes != expected_count) return error.InvalidRecord;
                    if (old_meta.node_digest != expected_digest) return error.InvalidRecord;
                    expected_order = old_meta.node_by_text_order_digest;
                } else {
                    const compacted_overlays = try self.compactNodeTextOverlaysForMeta(expected_count, expected_digest, expected_order, &.{});
                    expected_order = compacted_overlays.order_digest;
                }
                compacted = true;
                continue;
            }
        }
    }

    fn publishNodeTextRunRecordIfPossible(self: Store, old_meta: IndexMeta, record: NodeTextIndexRecord) !bool {
        const record_digest = try self.nodeTextIndexRecordDigest(record);
        var next_meta = old_meta;
        next_meta.nodes = std.math.add(u64, next_meta.nodes, 1) catch return error.RecordTooLarge;
        next_meta.node_digest ^= record_digest;
        next_meta.event_bytes = try self.eventBytes();
        var batch = [_]NodeTextIndexRecord{record};
        return self.publishNodeTextRunBatchIfPossible(old_meta, next_meta, batch[0..], record_digest, .verify_by_id);
    }

    fn publishNodeTextDeltaAsRunForMeta(
        self: Store,
        meta: IndexMeta,
        base_header: NodeTextIndexHeader,
        delta_header: NodeTextIndexHeader,
        manifest_entries: []const OwnedNodeTextRunManifestEntry,
    ) !?u64 {
        if (delta_header.node_count == 0) return null;
        if (delta_header.node_count > node_text_run_max_records) return error.InvalidRecord;
        if (manifest_entries.len >= node_text_run_manifest_max_entries) return null;
        var next_meta = try self.readIndexMeta();
        if (next_meta.nodes != meta.nodes) return error.InvalidRecord;
        if (next_meta.node_digest != meta.node_digest) return error.InvalidRecord;
        if (next_meta.node_by_text_order_digest != meta.node_by_text_order_digest) return error.InvalidRecord;
        const run_count = nodeTextRunManifestTotalNodesOwned(manifest_entries) orelse return error.InvalidRecord;
        const indexed_count = std.math.add(u64, base_header.node_count, delta_header.node_count) catch return error.InvalidRecord;
        const logical_count = std.math.add(u64, indexed_count, run_count) catch return error.InvalidRecord;
        if (logical_count != meta.nodes) return error.InvalidRecord;
        if ((base_header.node_digest ^ delta_header.node_digest ^ nodeTextRunManifestDigestOwned(manifest_entries)) != meta.node_digest) return error.InvalidRecord;
        if (combinedNodeTextOrderDigestWithRuns(base_header, delta_header, manifest_entries) != meta.node_by_text_order_digest) return error.InvalidRecord;

        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        var delta_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{});
        defer delta_file.close(self.io);
        const expected_delta_size = try nodeTextIndexFileSizeForHeader(delta_header);
        if (try self.regularFileSize(delta_file) != expected_delta_size) return error.InvalidRecord;

        var delta_records = std.ArrayList(NodeTextIndexRecord).empty;
        defer delta_records.deinit(self.allocator);
        try delta_records.ensureTotalCapacityPrecise(self.allocator, @intCast(delta_header.node_count));
        var delta_digest = NodeTextIndexDigest{};
        var previous: ?NodeTextIndexRecord = null;
        var pos: u64 = 0;
        while (pos < delta_header.node_count) : (pos += 1) {
            const record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(delta_file, delta_header, pos, &texts);
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
                if (prev.id == record.id) return error.InvalidRecord;
            }
            delta_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
            delta_records.appendAssumeCapacity(record);
            previous = record;
        }
        if (delta_digest.count != delta_header.node_count) return error.InvalidRecord;
        if (delta_digest.digest != delta_header.node_digest) return error.InvalidRecord;
        if (delta_digest.order_digest != delta_header.order_digest) return error.InvalidRecord;

        const run_path = try self.nodeTextRunBatchPath(next_meta, next_meta, delta_header.node_count);
        defer self.allocator.free(run_path);
        if (try self.pathExists(run_path)) return error.AlreadyExists;
        var run_unpublished = true;
        errdefer if (run_unpublished) std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
        try self.writeNodeTextRunFile(run_path, delta_records.items, delta_digest.digest, delta_digest.order_digest, .verify_by_id);

        var next_entries = std.ArrayList(NodeTextRunManifestEntry).empty;
        defer next_entries.deinit(self.allocator);
        try next_entries.ensureTotalCapacityPrecise(self.allocator, manifest_entries.len + 1);
        for (manifest_entries) |entry| {
            next_entries.appendAssumeCapacity(.{
                .node_count = entry.node_count,
                .node_digest = entry.node_digest,
                .order_digest = entry.order_digest,
                .min_node_id = entry.min_node_id,
                .max_node_id = entry.max_node_id,
                .min_hash = entry.min_hash,
                .max_hash = entry.max_hash,
                .path = entry.path,
                .hash_filter = entry.hash_filter,
            });
        }
        const hash_filter = try self.buildNodeTextRunHashFilterForRecords(delta_records.items);
        defer self.allocator.free(hash_filter);
        next_entries.appendAssumeCapacity(.{
            .node_count = delta_header.node_count,
            .node_digest = delta_digest.digest,
            .order_digest = delta_digest.order_digest,
            .min_node_id = delta_digest.min_node_id,
            .max_node_id = delta_digest.max_node_id,
            .min_hash = delta_digest.min_hash,
            .max_hash = delta_digest.max_hash,
            .path = run_path,
            .hash_filter = hash_filter,
        });

        run_unpublished = false;
        try self.writeNodeTextRunManifestEntries(next_entries.items);
        try self.writeEmptyNodeTextDelta();
        next_meta.node_by_text_order_digest = combinedNodeTextOrderDigestWithRunEntries(base_header, .{ .node_count = 0 }, next_entries.items);
        try self.writeIndexMeta(next_meta);
        return next_meta.node_by_text_order_digest;
    }

    fn appendNodeTextIndexRecord(self: Store, record: NodeTextIndexRecord) !void {
        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .mode = .read_write, .allow_directory = false });
        defer old_file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
        try self.appendNodeTextIndexRecordWithHeader(old_file, old_header, record);
    }

    fn appendNodeTextIndexRecordWithHeader(self: Store, old_file: std.Io.File, old_header: NodeTextIndexHeader, record: NodeTextIndexRecord) !void {
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        if (old_header.node_count == std.math.maxInt(u64)) return error.RecordTooLarge;
        _ = try nodeTextIndexFileSizeForHeader(.{
            .node_count = old_header.node_count + 1,
            .flags = old_header.flags,
            .record_len = old_header.record_len,
            .uniform_kind = old_header.uniform_kind,
        });
        const record_digest = try self.nodeTextIndexRecordDigest(record);

        if (old_header.node_count == 0) {
            return try self.appendSortedNodeTextIndexTail(old_file, old_header, record, record_digest);
        }
        const last = try self.readNodeTextIndexRecordAtForHeader(old_file, old_header, old_header.node_count - 1);
        if (!nodeTextIndexLessThan({}, record, last)) {
            if (try self.nodeTextRecordFitsStoredHeader(old_header, record)) {
                return try self.appendSortedNodeTextIndexTail(old_file, old_header, record, record_digest);
            }
            var manifest = try self.readNodeTextRunManifest(self.allocator);
            defer manifest.deinit(self.allocator);
            if (manifest.totalNodeCount() != 0) {
                try self.ensureNodeTextBaseHashFilter(old_header);
                return try self.appendNodeTextDeltaRecord(record, .{ .node_count = 0 });
            }
            return try self.rewriteNodeTextIndexWithSortedTail(old_file, old_header, record);
        }
        try self.ensureNodeTextBaseHashFilter(old_header);
        return try self.appendNodeTextDeltaRecord(record, .{ .node_count = 0 });
    }

    fn nodeTextRecordFitsStoredHeader(self: Store, header: NodeTextIndexHeader, record: NodeTextIndexRecord) !bool {
        if (!nodeTextRecordFitsHeader(header, record)) return false;
        if (!header.hasDerivedTextSpan()) return true;
        const by_id = self.readNodeRecordById(record.id) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        return by_id.id == record.id and
            by_id.kind == record.kind and
            by_id.text_offset == record.text_offset and
            by_id.text_len == record.text_len;
    }

    fn rewriteNodeTextIndexWithSortedTail(self: Store, old_file: std.Io.File, old_header: NodeTextIndexHeader, record: NodeTextIndexRecord) !void {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        const record_digest = try self.nodeTextIndexRecordDigestWithTexts(&texts, record);
        const next_count = old_header.node_count + 1;
        const output_header = nodeTextHeaderForTail(
            old_header,
            next_count,
            old_header.node_digest ^ record_digest,
            nodeTextIndexOrderDigestStep(old_header.order_digest, old_header.node_count, record),
            &.{record},
        );
        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer new_file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(output_header)));
        defer writer.deinit();

        var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        output_header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var digest = NodeTextIndexDigest{};
        var previous: ?NodeTextIndexRecord = null;
        var pos: u64 = 0;
        while (pos < old_header.node_count) : (pos += 1) {
            const old_record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(old_file, old_header, pos, &texts);
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, old_record)) return error.InvalidRecord;
                if (prev.id == old_record.id) return error.InvalidRecord;
            }
            digest.add(old_record, try self.nodeTextIndexRecordDigestWithTexts(&texts, old_record));
            try writeNodeTextIndexRecordToWriter(&writer, output_header, old_record);
            previous = old_record;
        }
        if (digest.count != old_header.node_count) return error.InvalidRecord;
        if (digest.digest != old_header.node_digest) return error.InvalidRecord;
        if (digest.order_digest != old_header.order_digest) return error.InvalidRecord;
        if (previous) |prev| {
            if (nodeTextIndexLessThan({}, record, prev)) return error.InvalidRecord;
            if (record.id == prev.id) return error.InvalidRecord;
        }
        digest.add(record, record_digest);
        if (digest.count != output_header.node_count) return error.InvalidRecord;
        if (digest.digest != output_header.node_digest) return error.InvalidRecord;
        if (digest.order_digest != output_header.order_digest) return error.InvalidRecord;
        try writeNodeTextIndexRecordToWriter(&writer, output_header, record);
        try writer.flush();
        if (try writer.position() != try nodeTextIndexFileSizeForHeader(output_header)) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        try self.renameReplace(tmp_path, self.node_by_text_path);
    }

    fn readNodeTextDeltaHeader(self: Store) !NodeTextIndexHeader {
        if (!self.options.validate_indexes_on_read and self.node_text_delta_header_cache.valid) {
            return self.node_text_delta_header_cache.header;
        }
        var file = std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{}) catch |err| switch (err) {
            error.FileNotFound => {
                const header = NodeTextIndexHeader{ .node_count = 0 };
                if (!self.options.validate_indexes_on_read) {
                    self.node_text_delta_header_cache.header = header;
                    self.node_text_delta_header_cache.valid = true;
                }
                return header;
            },
            else => |e| return e,
        };
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        if (header.node_count > node_text_delta_max_records) return error.InvalidRecord;
        const expected_size = try nodeTextIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (!self.options.validate_indexes_on_read) {
            self.node_text_delta_header_cache.header = header;
            self.node_text_delta_header_cache.valid = true;
        }
        return header;
    }

    fn appendNodeTextDeltaRecord(self: Store, record: NodeTextIndexRecord, old_header_hint: NodeTextIndexHeader) !void {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{ .mode = .read_write, .allow_directory = false });
        var file_open = true;
        defer if (file_open) file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(file);
        if (old_header.node_count != old_header_hint.node_count) return error.InvalidRecord;
        if (old_header.node_count >= node_text_delta_max_records) return core.Error.BudgetExceeded;
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(file) != expected_old_size) return error.InvalidRecord;
        const next_count = old_header.node_count + 1;

        if (old_header.node_count == 0) {
            const record_digest = try self.nodeTextIndexRecordDigest(record);
            const new_header = nodeTextIndexHeaderForSortedUniqueHashRecords(&.{record}, record_digest, nodeTextIndexOrderDigestStep(0, 0, record));
            try self.writeNodeTextIndexRecordAt(file, new_header, 0, record);
            try self.writeNodeTextIndexHeader(file, new_header);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
            self.node_text_delta_header_cache.header = new_header;
            self.node_text_delta_header_cache.valid = true;
            self.refreshNodeTextDeltaRunCache(new_header);
            return;
        }

        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        var records = std.ArrayList(NodeTextIndexRecord).empty;
        defer records.deinit(self.allocator);
        try records.ensureTotalCapacity(self.allocator, @intCast(next_count));

        var old_digest = NodeTextIndexDigest{};
        var pos: u64 = 0;
        while (pos < old_header.node_count) : (pos += 1) {
            const old_record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(file, old_header, pos, &texts);
            old_digest.add(old_record, try self.nodeTextIndexRecordDigestWithTexts(&texts, old_record));
            records.appendAssumeCapacity(old_record);
        }
        if (old_digest.count != old_header.node_count) return error.InvalidRecord;
        if (old_digest.digest != old_header.node_digest) return error.InvalidRecord;
        if (old_digest.order_digest != old_header.order_digest) return error.InvalidRecord;

        records.appendAssumeCapacity(record);
        std.mem.sort(NodeTextIndexRecord, records.items, {}, nodeTextIndexLessThan);

        var next_digest = NodeTextIndexDigest{};
        var previous: ?NodeTextIndexRecord = null;
        for (records.items) |sorted_record| {
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, sorted_record)) return error.InvalidRecord;
            }
            next_digest.add(sorted_record, try self.nodeTextIndexRecordDigestWithTexts(&texts, sorted_record));
            previous = sorted_record;
        }
        if (next_digest.count != next_count) return error.InvalidRecord;

        file.close(self.io);
        file_open = false;

        const tmp_path = try self.tmpPathFor(self.node_by_text_delta_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var next_header = NodeTextIndexHeader{ .node_count = 0 };
        {
            var tmp_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer tmp_file.close(self.io);
            next_header = nodeTextIndexHeaderForSortedUniqueHashRecords(records.items, next_digest.digest, next_digest.order_digest);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, tmp_file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(next_header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            next_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            for (records.items) |sorted_record| {
                try writeNodeTextIndexRecordToWriter(&writer, next_header, sorted_record);
            }
            try writer.flush();
            if (selfOptionsNeedSync(self)) try tmp_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_by_text_delta_path);
        self.node_text_delta_header_cache.header = next_header;
        self.node_text_delta_header_cache.valid = true;
        self.refreshNodeTextDeltaRunCache(next_header);
    }

    pub fn compactNodeTextDeltaBudgeted(self: Store, max_delta_records: u64) !NodeTextDeltaMaintenanceResult {
        const meta = try self.readCurrentIndexMeta();
        const delta_header = try self.readNodeTextDeltaHeader();
        if (delta_header.node_count == 0) return .{
            .compacted = false,
            .delta_records_before = 0,
            .delta_records_after = 0,
        };
        if (max_delta_records != 0 and delta_header.node_count > max_delta_records) return .{
            .compacted = false,
            .delta_records_before = delta_header.node_count,
            .delta_records_after = delta_header.node_count,
        };
        _ = try self.compactNodeTextDeltaForMeta(meta.nodes, meta.node_digest, meta.node_by_text_order_digest);
        return .{
            .compacted = true,
            .delta_records_before = delta_header.node_count,
            .delta_records_after = 0,
        };
    }

    pub fn compactNodeTextRunsBudgeted(self: Store, max_run_records: u64) !NodeTextRunMaintenanceResult {
        return self.compactNodeTextRunsBudgetedExcept(max_run_records, &.{});
    }

    pub fn compactNodeTextRunsBudgetedRetainingRegistry(self: Store, max_run_records: u64, registry: *const NodeTextRunRetentionRegistry) !NodeTextRunMaintenanceResult {
        const pinned_paths = try registry.activeManifestPaths(self.allocator);
        defer self.allocator.free(pinned_paths);
        return self.compactNodeTextRunsBudgetedExcept(max_run_records, pinned_paths);
    }

    pub fn compactNodeTextRunsBudgetedWithProcessLeases(self: Store, max_run_records: u64) !NodeTextRunMaintenanceResult {
        return self.compactNodeTextRunsBudgetedExceptAndProcessLeases(max_run_records, &.{});
    }

    pub fn compactNodeTextRunsBudgetedExceptAndProcessLeases(
        self: Store,
        max_run_records: u64,
        pinned_manifest_paths: []const []const u8,
    ) !NodeTextRunMaintenanceResult {
        const protected_paths = try self.pinnedManifestPathsWithProcessLeases(.node_text_run, self.allocator, pinned_manifest_paths);
        defer freeOwnedManifestPathList(self.allocator, protected_paths);
        return self.compactNodeTextRunsBudgetedExcept(max_run_records, protected_paths);
    }

    pub fn compactNodeTextRunsBudgetedExcept(self: Store, max_run_records: u64, pinned_manifest_paths: []const []const u8) !NodeTextRunMaintenanceResult {
        const meta = try self.readCurrentIndexMeta();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        const delta_header = try self.readNodeTextDeltaHeader();
        if (manifest.entries.items.len == 0) return .{
            .compacted = false,
            .run_entries_before = 0,
            .run_entries_after = 0,
            .run_records_before = 0,
            .run_records_after = 0,
            .delta_records_before = delta_header.node_count,
            .delta_records_after = delta_header.node_count,
        };
        if (try self.compactNodeTextRunWindowForMeta(meta, manifest.entries.items, delta_header, max_run_records, pinned_manifest_paths)) |compacted| {
            return compacted;
        }
        if (max_run_records != 0 and run_count > max_run_records) return .{
            .compacted = false,
            .run_entries_before = manifest.entries.items.len,
            .run_entries_after = manifest.entries.items.len,
            .run_records_before = run_count,
            .run_records_after = run_count,
            .delta_records_before = delta_header.node_count,
            .delta_records_after = delta_header.node_count,
        };
        const compacted = try self.compactNodeTextOverlaysForMeta(meta.nodes, meta.node_digest, meta.node_by_text_order_digest, pinned_manifest_paths);
        return .{
            .compacted = true,
            .run_entries_before = compacted.run_entries_before,
            .run_entries_after = 0,
            .run_records_before = compacted.run_records_before,
            .run_records_after = 0,
            .compacted_run_records = compacted.run_records_before,
            .delta_records_before = compacted.delta_records_before,
            .delta_records_after = 0,
            .gc_deleted_runs = compacted.gc_deleted_runs,
        };
    }

    pub fn gcUnreferencedNodeTextRuns(self: Store) !NodeTextRunGcResult {
        return self.gcUnreferencedNodeTextRunsExcept(&.{});
    }

    pub fn gcUnreferencedNodeTextRunsExcept(self: Store, pinned_manifest_paths: []const []const u8) !NodeTextRunGcResult {
        const current_manifest_path = try self.readNodeTextRunCurrentPath(self.allocator);
        defer if (current_manifest_path) |path| self.allocator.free(path);

        var live_run_paths = std.StringHashMap([]u8).init(self.allocator);
        defer {
            var live_iter = live_run_paths.valueIterator();
            while (live_iter.next()) |path| self.allocator.free(path.*);
            live_run_paths.deinit();
        }
        var protected_manifest_paths = std.StringHashMap(void).init(self.allocator);
        defer protected_manifest_paths.deinit();
        try protected_manifest_paths.ensureTotalCapacity(@intCast(pinned_manifest_paths.len + 1));

        if (current_manifest_path) |path| {
            try protected_manifest_paths.put(path, {});
            try self.addNodeTextRunManifestLivePaths(path, &live_run_paths);
        }
        for (pinned_manifest_paths) |path| {
            try protected_manifest_paths.put(path, {});
            try self.addNodeTextRunManifestLivePaths(path, &live_run_paths);
        }

        var result = NodeTextRunGcResult{};
        const runs_dir_path = try std.fs.path.join(self.allocator, &.{ self.dir_path, "node_text_runs" });
        defer self.allocator.free(runs_dir_path);
        var runs_dir = std.Io.Dir.cwd().openDir(self.io, runs_dir_path, .{ .iterate = true }) catch |err| switch (err) {
            error.FileNotFound => null,
            else => |e| return e,
        };
        if (runs_dir) |*dir| {
            defer dir.close(self.io);
            var iter = dir.iterate();
            while (try iter.next(self.io)) |entry| {
                if (entry.kind != .file) continue;
                const full_path = try std.fs.path.join(self.allocator, &.{ runs_dir_path, entry.name });
                defer self.allocator.free(full_path);
                if (live_run_paths.contains(full_path)) continue;
                try std.Io.Dir.cwd().deleteFile(self.io, full_path);
                result.deleted_runs = std.math.add(u64, result.deleted_runs, 1) catch return error.RecordTooLarge;
            }
        }

        const manifest_leaf = std.fs.path.basename(self.node_text_run_manifest_path);
        const epoch_prefix = try std.fmt.allocPrint(self.allocator, "{s}.", .{manifest_leaf});
        defer self.allocator.free(epoch_prefix);
        var store_dir = try std.Io.Dir.cwd().openDir(self.io, self.dir_path, .{ .iterate = true });
        defer store_dir.close(self.io);
        var iter = store_dir.iterate();
        while (try iter.next(self.io)) |entry| {
            if (entry.kind != .file) continue;
            if (!std.mem.startsWith(u8, entry.name, epoch_prefix)) continue;
            const full_path = try std.fs.path.join(self.allocator, &.{ self.dir_path, entry.name });
            defer self.allocator.free(full_path);
            if (protected_manifest_paths.contains(full_path)) continue;
            try std.Io.Dir.cwd().deleteFile(self.io, full_path);
            result.deleted_manifests = std.math.add(u64, result.deleted_manifests, 1) catch return error.RecordTooLarge;
        }
        return result;
    }

    fn addNodeTextRunManifestLivePaths(self: Store, manifest_path: []const u8, live_run_paths: *std.StringHashMap([]u8)) !void {
        var manifest = try self.readNodeTextRunManifestFile(self.allocator, manifest_path);
        defer manifest.deinit(self.allocator);
        try live_run_paths.ensureUnusedCapacity(@intCast(manifest.entries.items.len));
        for (manifest.entries.items) |entry| {
            if (live_run_paths.contains(entry.path)) continue;
            const owned_path = try self.allocator.dupe(u8, entry.path);
            live_run_paths.putAssumeCapacityNoClobber(owned_path, owned_path);
        }
    }

    fn nodeTextRunPathsForPinnedManifests(self: Store, pinned_manifest_paths: []const []const u8) !std.StringHashMap([]u8) {
        var run_paths = std.StringHashMap([]u8).init(self.allocator);
        errdefer self.freeOwnedPathSet(&run_paths);
        for (pinned_manifest_paths) |manifest_path| {
            try self.addNodeTextRunManifestLivePaths(manifest_path, &run_paths);
        }
        return run_paths;
    }

    fn freeOwnedPathSet(self: Store, path_set: *std.StringHashMap([]u8)) void {
        var iter = path_set.valueIterator();
        while (iter.next()) |path| self.allocator.free(path.*);
        path_set.deinit();
    }

    fn compactNodeTextDeltaForMeta(self: Store, expected_count: u64, expected_digest: u64, expected_order_digest: u64) !u64 {
        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer old_file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        var old_map = if (old_header.hasDerivedTextSpan()) null else openReadOnlyMemoryMap(self.io, old_file, expected_old_size) catch null;
        defer if (old_map) |*mapped| mapped.destroy(self.io);

        const delta_header = try self.readNodeTextDeltaHeader();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (delta_header.node_count == 0) return combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items);
        if (old_header.node_count + delta_header.node_count + run_count != expected_count) return error.InvalidRecord;
        if ((old_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != expected_digest) return error.InvalidRecord;
        if (combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items) != expected_order_digest) return error.InvalidRecord;
        const next_base_count = old_header.node_count + delta_header.node_count;
        const next_base_digest = old_header.node_digest ^ delta_header.node_digest;

        var delta_records = std.ArrayList(NodeTextIndexRecord).empty;
        defer delta_records.deinit(self.allocator);
        try delta_records.ensureTotalCapacity(self.allocator, @intCast(delta_header.node_count));
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        {
            var delta_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{});
            defer delta_file.close(self.io);
            var delta_digest = NodeTextIndexDigest{};
            var delta_pos: u64 = 0;
            while (delta_pos < delta_header.node_count) : (delta_pos += 1) {
                const record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(delta_file, delta_header, delta_pos, &texts);
                delta_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
                try delta_records.append(self.allocator, record);
            }
            if (delta_digest.count != delta_header.node_count) return error.InvalidRecord;
            if (delta_digest.digest != delta_header.node_digest) return error.InvalidRecord;
            if (delta_digest.order_digest != delta_header.order_digest) return error.InvalidRecord;
        }
        std.mem.sort(NodeTextIndexRecord, delta_records.items, {}, nodeTextIndexLessThan);

        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var next_order = NodeTextIndexDigest{};
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            const output_header = nodeTextHeaderForTail(old_header, next_base_count, next_base_digest, 0, delta_records.items);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(output_header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            output_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var delta_pos: usize = 0;
            var old_pos: u64 = 0;
            var previous: ?NodeTextIndexRecord = null;
            while (old_pos < old_header.node_count) : (old_pos += 1) {
                const current = if (old_map) |*mapped|
                    try readNodeTextIndexRecordFromMapForHeaderWithTexts(old_header, mapped, old_pos, &texts)
                else
                    try self.readNodeTextIndexRecordAtForHeaderWithTexts(old_file, old_header, old_pos, &texts);
                if (previous) |prev| {
                    if (!nodeTextIndexLessThan({}, prev, current)) return error.InvalidRecord;
                    if (prev.id == current.id) return error.InvalidRecord;
                }
                while (delta_pos < delta_records.items.len and nodeTextIndexLessThan({}, delta_records.items[delta_pos], current)) : (delta_pos += 1) {
                    if (previous) |prev| {
                        if (prev.id == delta_records.items[delta_pos].id) return error.InvalidRecord;
                    }
                    next_order.add(delta_records.items[delta_pos], try self.nodeTextIndexRecordDigestWithTexts(&texts, delta_records.items[delta_pos]));
                    try writeNodeTextIndexRecordToWriter(&writer, output_header, delta_records.items[delta_pos]);
                    previous = delta_records.items[delta_pos];
                }
                if (previous) |prev| {
                    if (prev.id == current.id) return error.InvalidRecord;
                }
                next_order.add(current, try self.nodeTextIndexRecordDigestWithTexts(&texts, current));
                try writeNodeTextIndexRecordToWriter(&writer, output_header, current);
                previous = current;
            }
            while (delta_pos < delta_records.items.len) : (delta_pos += 1) {
                if (previous) |prev| {
                    if (prev.id == delta_records.items[delta_pos].id) return error.InvalidRecord;
                }
                next_order.add(delta_records.items[delta_pos], try self.nodeTextIndexRecordDigestWithTexts(&texts, delta_records.items[delta_pos]));
                try writeNodeTextIndexRecordToWriter(&writer, output_header, delta_records.items[delta_pos]);
                previous = delta_records.items[delta_pos];
            }
            if (next_order.count != next_base_count) return error.InvalidRecord;
            if (next_order.digest != next_base_digest) return error.InvalidRecord;
            try writer.flush();
            try self.writeNodeTextIndexHeader(new_file, .{
                .node_count = next_base_count,
                .node_digest = next_base_digest,
                .order_digest = next_order.order_digest,
                .flags = output_header.flags,
                .record_len = output_header.record_len,
                .uniform_kind = output_header.uniform_kind,
            });
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        }

        try self.renameReplace(tmp_path, self.node_by_text_path);
        try self.writeEmptyNodeTextDelta();

        var meta = try self.readIndexMeta();
        if (meta.nodes != expected_count) return error.InvalidRecord;
        if (meta.node_digest != expected_digest) return error.InvalidRecord;
        if (meta.node_by_text_order_digest != expected_order_digest) return error.InvalidRecord;
        meta.node_by_text_order_digest = combinedNodeTextOrderDigestWithRuns(.{
            .node_count = next_base_count,
            .node_digest = next_base_digest,
            .order_digest = next_order.order_digest,
        }, .{ .node_count = 0 }, manifest.entries.items);
        try self.writeIndexMeta(meta);
        return meta.node_by_text_order_digest;
    }

    fn writeEmptyNodeTextDelta(self: Store) !void {
        const tmp_path = try self.tmpPathFor(self.node_by_text_delta_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            try self.writeNodeTextIndexHeader(file, .{ .node_count = 0 });
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_by_text_delta_path);
        self.node_text_delta_header_cache.header = .{ .node_count = 0 };
        self.node_text_delta_header_cache.valid = true;
        self.node_text_delta_run_cache.clear();
    }

    fn deleteNodeTextRunManifest(self: Store) !void {
        _ = try self.deleteNodeTextRunManifestExcept(&.{});
    }

    fn deleteNodeTextRunManifestExcept(self: Store, pinned_manifest_paths: []const []const u8) !NodeTextRunGcResult {
        self.invalidateNodeTextRunManifestCache();
        std.Io.Dir.cwd().deleteFile(self.io, self.node_text_run_manifest_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        // The CURRENT unlink must be durable before GC removes the manifest
        // and run files it named. Otherwise a crash can resurrect CURRENT and
        // leave it pointing at files that were already reclaimed.
        try self.invalidateNodeTextRunCurrent();
        return self.gcUnreferencedNodeTextRunsExceptAndProcessLeases(pinned_manifest_paths);
    }

    const NodeTextOverlayRunReader = struct {
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        next_index: u64,
        count: u64,
        header: NodeTextIndexHeader,
        digest: NodeTextIndexDigest = .{},
        previous: ?NodeTextIndexRecord = null,

        fn deinit(self: *NodeTextOverlayRunReader, io: std.Io) void {
            if (self.map) |*map| map.destroy(io);
            self.file.close(io);
        }
    };

    const NodeTextOverlayRunHeapEntry = struct {
        run_index: usize,
        record: NodeTextIndexRecord,
    };

    const NodeTextOverlayCompactionResult = struct {
        order_digest: u64,
        run_entries_before: usize,
        run_records_before: u64,
        delta_records_before: u64,
        gc_deleted_runs: u64,
    };

    const NodeTextRunCompactionWindow = struct {
        start: usize,
        count: usize,
        records: u64,
        min_run_records: u64,
        max_run_records: u64,
    };

    const NodeTextSpanDeriveMode = enum {
        verify_by_id,
        trusted_recent_by_id_append,
    };

    fn compareNodeTextOverlayRunHeapEntry(_: void, lhs: NodeTextOverlayRunHeapEntry, rhs: NodeTextOverlayRunHeapEntry) std.math.Order {
        if (nodeTextIndexLessThan({}, lhs.record, rhs.record)) return .lt;
        if (nodeTextIndexLessThan({}, rhs.record, lhs.record)) return .gt;
        return std.math.order(lhs.run_index, rhs.run_index);
    }

    fn compactNodeTextRunWindowForMeta(
        self: Store,
        meta: IndexMeta,
        manifest_entries: []const OwnedNodeTextRunManifestEntry,
        delta_header: NodeTextIndexHeader,
        max_run_records: u64,
        pinned_manifest_paths: []const []const u8,
    ) !?NodeTextRunMaintenanceResult {
        if (manifest_entries.len < 2) return null;
        var base_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer base_file.close(self.io);
        const base_header = try self.readNodeTextIndexHeaderFromFile(base_file);
        const expected_base_size = try nodeTextIndexFileSizeForHeader(base_header);
        if (try self.regularFileSize(base_file) != expected_base_size) return error.InvalidRecord;

        const run_count = nodeTextRunManifestTotalNodesOwned(manifest_entries) orelse return error.InvalidRecord;
        const base_and_delta = std.math.add(u64, base_header.node_count, delta_header.node_count) catch return error.InvalidRecord;
        const logical_count = std.math.add(u64, base_and_delta, run_count) catch return error.InvalidRecord;
        if (logical_count != meta.nodes) return error.InvalidRecord;
        if ((base_header.node_digest ^ delta_header.node_digest ^ nodeTextRunManifestDigestOwned(manifest_entries)) != meta.node_digest) return error.InvalidRecord;
        const combined_order = combinedNodeTextOrderDigestWithRuns(base_header, delta_header, manifest_entries);
        if (combined_order != meta.node_by_text_order_digest) return error.InvalidRecord;

        const selected_limit = if (max_run_records == 0)
            node_text_run_max_records
        else
            @min(max_run_records, node_text_run_max_records);
        const selected = (try selectNodeTextRunCompactionWindow(self.allocator, manifest_entries, selected_limit)) orelse return null;
        const selected_end = std.math.add(usize, selected.start, selected.count) catch return error.RecordTooLarge;

        var texts = try NodeTextsView.open(self);
        defer texts.deinit();

        var readers = std.ArrayList(NodeTextOverlayRunReader).empty;
        var readers_closed = false;
        defer {
            if (!readers_closed) {
                for (readers.items) |*reader| reader.deinit(self.io);
            }
            readers.deinit(self.allocator);
        }
        try readers.ensureTotalCapacityPrecise(self.allocator, selected.count);

        var queue = std.PriorityQueue(NodeTextOverlayRunHeapEntry, void, compareNodeTextOverlayRunHeapEntry).initContext({});
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, selected.count);

        var entry_index: usize = selected.start;
        while (entry_index < selected_end) : (entry_index += 1) {
            const entry = manifest_entries[entry_index];
            var run_file = try std.Io.Dir.cwd().openFile(self.io, entry.path, .{});
            var run_file_owned_by_readers = false;
            errdefer if (!run_file_owned_by_readers) run_file.close(self.io);
            const run_header = try self.readNodeTextIndexHeaderFromFile(run_file);
            if (run_header.node_count != entry.node_count or
                run_header.node_digest != entry.node_digest or
                run_header.order_digest != entry.order_digest) return error.InvalidRecord;
            const expected_run_size = try nodeTextIndexFileSizeForHeader(run_header);
            if (try self.regularFileSize(run_file) != expected_run_size) return error.InvalidRecord;
            var map = if (run_header.hasDerivedTextSpan()) null else openReadOnlyMemoryMap(self.io, run_file, expected_run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .next_index = 0,
                .count = run_header.node_count,
                .header = run_header,
            });
            run_file_owned_by_readers = true;
            map = null;
            try self.pushNextNodeTextOverlayRecord(&readers, &queue, &texts, reader_index);
        }

        const scratch_path = try self.nodeTextRunWindowCompactionScratchPath(meta, selected.start, selected.count, selected.records);
        defer self.allocator.free(scratch_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, scratch_path) catch {};
        const compacted_digest = try self.writeNodeTextRunFileFromHeap(scratch_path, &readers, &queue, &texts, selected.records);

        for (readers.items) |*reader| reader.deinit(self.io);
        readers_closed = true;

        const compacted_path = try self.nodeTextRunWindowCompactionPath(meta, selected.start, selected.count, selected.records, compacted_digest.order_digest);
        defer self.allocator.free(compacted_path);
        if (try self.pathExists(compacted_path)) return error.AlreadyExists;
        var compacted_run_unpublished = true;
        errdefer if (compacted_run_unpublished) std.Io.Dir.cwd().deleteFile(self.io, compacted_path) catch {};
        try self.renameReplace(scratch_path, compacted_path);

        var next_entries = std.ArrayList(NodeTextRunManifestEntry).empty;
        defer next_entries.deinit(self.allocator);
        try next_entries.ensureTotalCapacityPrecise(self.allocator, manifest_entries.len - selected.count + 1);
        var prefix_index: usize = 0;
        while (prefix_index < selected.start) : (prefix_index += 1) {
            const entry = manifest_entries[prefix_index];
            next_entries.appendAssumeCapacity(.{
                .node_count = entry.node_count,
                .node_digest = entry.node_digest,
                .order_digest = entry.order_digest,
                .min_node_id = entry.min_node_id,
                .max_node_id = entry.max_node_id,
                .min_hash = entry.min_hash,
                .max_hash = entry.max_hash,
                .path = entry.path,
                .hash_filter = entry.hash_filter,
            });
        }
        const compacted_hash_filter = try self.buildNodeTextRunHashFilterFromFile(compacted_path, selected.records);
        defer self.allocator.free(compacted_hash_filter);
        next_entries.appendAssumeCapacity(.{
            .node_count = selected.records,
            .node_digest = compacted_digest.digest,
            .order_digest = compacted_digest.order_digest,
            .min_node_id = compacted_digest.min_node_id,
            .max_node_id = compacted_digest.max_node_id,
            .min_hash = compacted_digest.min_hash,
            .max_hash = compacted_digest.max_hash,
            .path = compacted_path,
            .hash_filter = compacted_hash_filter,
        });
        var remaining_index = selected_end;
        while (remaining_index < manifest_entries.len) : (remaining_index += 1) {
            const entry = manifest_entries[remaining_index];
            next_entries.appendAssumeCapacity(.{
                .node_count = entry.node_count,
                .node_digest = entry.node_digest,
                .order_digest = entry.order_digest,
                .min_node_id = entry.min_node_id,
                .max_node_id = entry.max_node_id,
                .min_hash = entry.min_hash,
                .max_hash = entry.max_hash,
                .path = entry.path,
                .hash_filter = entry.hash_filter,
            });
        }
        compacted_run_unpublished = false;
        try self.writeNodeTextRunManifestEntriesExcept(next_entries.items, pinned_manifest_paths);

        var next_meta = try self.readIndexMeta();
        if (next_meta.nodes != meta.nodes) return error.InvalidRecord;
        if (next_meta.node_digest != meta.node_digest) return error.InvalidRecord;
        if (next_meta.node_by_text_order_digest != meta.node_by_text_order_digest) return error.InvalidRecord;
        next_meta.node_by_text_order_digest = combinedNodeTextOrderDigestWithRunEntries(base_header, delta_header, next_entries.items);
        try self.writeIndexMeta(next_meta);

        var gc_deleted_runs: u64 = 0;
        var delete_index: usize = selected.start;
        var pinned_run_paths = try self.nodeTextRunPathsForPinnedManifests(pinned_manifest_paths);
        defer self.freeOwnedPathSet(&pinned_run_paths);
        while (delete_index < selected_end) : (delete_index += 1) {
            if (pinned_run_paths.contains(manifest_entries[delete_index].path)) continue;
            std.Io.Dir.cwd().deleteFile(self.io, manifest_entries[delete_index].path) catch |err| switch (err) {
                error.FileNotFound => {},
                else => |e| return e,
            };
            gc_deleted_runs += 1;
        }

        return .{
            .compacted = true,
            .run_entries_before = manifest_entries.len,
            .run_entries_after = manifest_entries.len - selected.count + 1,
            .run_records_before = run_count,
            .run_records_after = run_count,
            .compacted_run_records = selected.records,
            .delta_records_before = delta_header.node_count,
            .delta_records_after = delta_header.node_count,
            .gc_deleted_runs = gc_deleted_runs,
        };
    }

    fn selectNodeTextRunCompactionWindow(
        allocator: std.mem.Allocator,
        entries: []const OwnedNodeTextRunManifestEntry,
        selected_limit: u64,
    ) !?NodeTextRunCompactionWindow {
        if (entries.len < 2 or selected_limit == 0) return null;

        var min_queue = std.ArrayList(usize).empty;
        var max_queue = std.ArrayList(usize).empty;
        const max_window_entries = if (selected_limit >= entries.len) entries.len else @as(usize, @intCast(selected_limit)) + 1;
        var stack_queue_storage: [node_text_run_compaction_stack_queue_entries * 2]usize = undefined;
        var fixed_queue_allocator = std.heap.FixedBufferAllocator.init(std.mem.sliceAsBytes(stack_queue_storage[0..]));
        const queue_allocator = if (max_window_entries <= node_text_run_compaction_stack_queue_entries)
            fixed_queue_allocator.allocator()
        else
            allocator;
        defer min_queue.deinit(queue_allocator);
        defer max_queue.deinit(queue_allocator);
        try min_queue.ensureTotalCapacity(queue_allocator, max_window_entries);
        try max_queue.ensureTotalCapacity(queue_allocator, max_window_entries);
        var min_head: usize = 0;
        var max_head: usize = 0;

        var best: ?NodeTextRunCompactionWindow = null;
        var start: usize = 0;
        var records: u64 = 0;
        for (entries, 0..) |entry, end| {
            const entry_records = entry.node_count;
            if (entry_records == 0 or entry_records > selected_limit) {
                min_queue.clearRetainingCapacity();
                max_queue.clearRetainingCapacity();
                min_head = 0;
                max_head = 0;
                start = end + 1;
                records = 0;
                continue;
            }

            records = std.math.add(u64, records, entry_records) catch return error.RecordTooLarge;
            while (min_queue.items.len > min_head and entries[min_queue.items[min_queue.items.len - 1]].node_count >= entry_records) {
                _ = min_queue.pop();
            }
            compactSlidingIndexQueueIfFull(&min_queue, &min_head);
            min_queue.appendAssumeCapacity(end);
            while (max_queue.items.len > max_head and entries[max_queue.items[max_queue.items.len - 1]].node_count <= entry_records) {
                _ = max_queue.pop();
            }
            compactSlidingIndexQueueIfFull(&max_queue, &max_head);
            max_queue.appendAssumeCapacity(end);

            while (start <= end and records > selected_limit) {
                if (min_queue.items[min_head] == start) min_head += 1;
                if (max_queue.items[max_head] == start) max_head += 1;
                records -= entries[start].node_count;
                start += 1;
            }

            const candidate_count = if (start <= end) end - start + 1 else 0;
            if (candidate_count < 2) continue;
            const candidate = NodeTextRunCompactionWindow{
                .start = start,
                .count = candidate_count,
                .records = records,
                .min_run_records = entries[min_queue.items[min_head]].node_count,
                .max_run_records = entries[max_queue.items[max_head]].node_count,
            };
            if (best == null or nodeTextRunWindowBetter(candidate, best.?)) {
                best = candidate;
            }
        }
        return best;
    }

    fn nodeTextRunWindowIsSameTier(window: NodeTextRunCompactionWindow) bool {
        if (window.min_run_records == 0) return false;
        const max_same_tier = std.math.mul(u64, window.min_run_records, node_text_run_compaction_tier_ratio) catch std.math.maxInt(u64);
        return window.max_run_records <= max_same_tier;
    }

    fn nodeTextRunWindowBetter(candidate: NodeTextRunCompactionWindow, current: NodeTextRunCompactionWindow) bool {
        const candidate_same_tier = nodeTextRunWindowIsSameTier(candidate);
        const current_same_tier = nodeTextRunWindowIsSameTier(current);
        if (candidate_same_tier != current_same_tier) return candidate_same_tier;
        if (candidate.records != current.records) return candidate.records > current.records;
        if (candidate.count != current.count) return candidate.count > current.count;
        return candidate.start < current.start;
    }

    fn pushNextNodeTextOverlayRecord(
        self: Store,
        readers: *std.ArrayList(NodeTextOverlayRunReader),
        queue: *std.PriorityQueue(NodeTextOverlayRunHeapEntry, void, compareNodeTextOverlayRunHeapEntry),
        texts: *const NodeTextsView,
        reader_index: usize,
    ) !void {
        const reader = &readers.items[reader_index];
        if (reader.next_index >= reader.count) return;
        const record = if (reader.map) |*map|
            try readNodeTextIndexRecordFromMapForHeaderWithTexts(reader.header, map, reader.next_index, texts)
        else
            try self.readNodeTextIndexRecordAtForHeaderWithTexts(reader.file, reader.header, reader.next_index, texts);
        if (reader.previous) |prev| {
            if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
            if (prev.id == record.id) return error.InvalidRecord;
        }
        reader.previous = record;
        reader.digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(texts, record));
        reader.next_index += 1;
        try queue.push(self.allocator, .{ .run_index = reader_index, .record = record });
    }

    fn compactNodeTextOverlaysForMeta(self: Store, expected_count: u64, expected_digest: u64, expected_order_digest: u64, pinned_manifest_paths: []const []const u8) !NodeTextOverlayCompactionResult {
        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer old_file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        var old_map = if (old_header.hasDerivedTextSpan()) null else openReadOnlyMemoryMap(self.io, old_file, expected_old_size) catch null;
        defer if (old_map) |*mapped| mapped.destroy(self.io);

        const delta_header = try self.readNodeTextDeltaHeader();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (delta_header.node_count == 0 and manifest.entries.items.len == 0) return .{
            .order_digest = combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items),
            .run_entries_before = 0,
            .run_records_before = 0,
            .delta_records_before = 0,
            .gc_deleted_runs = 0,
        };
        if (old_header.node_count + delta_header.node_count + run_count != expected_count) return error.InvalidRecord;
        if ((old_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != expected_digest) return error.InvalidRecord;
        if (combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items) != expected_order_digest) return error.InvalidRecord;

        var texts = try NodeTextsView.open(self);
        defer texts.deinit();

        var readers = std.ArrayList(NodeTextOverlayRunReader).empty;
        var readers_closed = false;
        defer {
            if (!readers_closed) {
                for (readers.items) |*reader| reader.deinit(self.io);
            }
            readers.deinit(self.allocator);
        }
        const overlay_run_fanin = manifest.entries.items.len + @as(usize, if (delta_header.node_count == 0) 0 else 1);
        try readers.ensureTotalCapacityPrecise(self.allocator, overlay_run_fanin);

        var queue = std.PriorityQueue(NodeTextOverlayRunHeapEntry, void, compareNodeTextOverlayRunHeapEntry).initContext({});
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, overlay_run_fanin);

        var sorted_delta_run_path: ?[]u8 = null;
        defer if (sorted_delta_run_path) |path| {
            std.Io.Dir.cwd().deleteFile(self.io, path) catch {};
            self.allocator.free(path);
        };

        if (delta_header.node_count != 0) {
            var delta_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{});
            defer delta_file.close(self.io);
            const expected_delta_size = try nodeTextIndexFileSizeForHeader(delta_header);
            if (try self.regularFileSize(delta_file) != expected_delta_size) return error.InvalidRecord;
            var delta_records = std.ArrayList(NodeTextIndexRecord).empty;
            defer delta_records.deinit(self.allocator);
            try delta_records.ensureTotalCapacityPrecise(self.allocator, @intCast(delta_header.node_count));
            var original_delta_digest = NodeTextIndexDigest{};
            var delta_pos: u64 = 0;
            while (delta_pos < delta_header.node_count) : (delta_pos += 1) {
                const record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(delta_file, delta_header, delta_pos, &texts);
                original_delta_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
                delta_records.appendAssumeCapacity(record);
            }
            if (original_delta_digest.count != delta_header.node_count) return error.InvalidRecord;
            if (original_delta_digest.digest != delta_header.node_digest) return error.InvalidRecord;
            if (original_delta_digest.order_digest != delta_header.order_digest) return error.InvalidRecord;

            std.mem.sort(NodeTextIndexRecord, delta_records.items, {}, nodeTextIndexLessThan);
            var sorted_delta_digest = NodeTextIndexDigest{};
            var previous_delta: ?NodeTextIndexRecord = null;
            for (delta_records.items) |record| {
                if (previous_delta) |prev| {
                    if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
                    if (prev.id == record.id) return error.InvalidRecord;
                }
                sorted_delta_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
                previous_delta = record;
            }
            if (sorted_delta_digest.count != delta_header.node_count) return error.InvalidRecord;
            if (sorted_delta_digest.digest != delta_header.node_digest) return error.InvalidRecord;

            const delta_run_path = try self.tmpPathFor(self.node_by_text_delta_path);
            sorted_delta_run_path = delta_run_path;
            try self.writeNodeTextRunFile(delta_run_path, delta_records.items, sorted_delta_digest.digest, sorted_delta_digest.order_digest, .verify_by_id);
            var sorted_delta_file = try std.Io.Dir.cwd().openFile(self.io, delta_run_path, .{});
            var sorted_delta_file_owned_by_readers = false;
            errdefer if (!sorted_delta_file_owned_by_readers) sorted_delta_file.close(self.io);
            const sorted_delta_header = try self.readNodeTextIndexHeaderFromFile(sorted_delta_file);
            if (sorted_delta_header.node_count != sorted_delta_digest.count or
                sorted_delta_header.node_digest != sorted_delta_digest.digest or
                sorted_delta_header.order_digest != sorted_delta_digest.order_digest) return error.InvalidRecord;
            const sorted_delta_size = try nodeTextIndexFileSizeForHeader(sorted_delta_header);
            var sorted_delta_map = if (sorted_delta_header.hasDerivedTextSpan()) null else openReadOnlyMemoryMap(self.io, sorted_delta_file, sorted_delta_size) catch null;
            errdefer if (sorted_delta_map) |*mapped| mapped.destroy(self.io);
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = sorted_delta_file,
                .map = sorted_delta_map,
                .next_index = 0,
                .count = sorted_delta_header.node_count,
                .header = sorted_delta_header,
            });
            sorted_delta_file_owned_by_readers = true;
            sorted_delta_map = null;
            try self.pushNextNodeTextOverlayRecord(&readers, &queue, &texts, reader_index);
        }

        for (manifest.entries.items) |entry| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, entry.path, .{});
            var run_file_owned_by_readers = false;
            errdefer if (!run_file_owned_by_readers) run_file.close(self.io);
            const run_header = try self.readNodeTextIndexHeaderFromFile(run_file);
            if (run_header.node_count != entry.node_count or
                run_header.node_digest != entry.node_digest or
                run_header.order_digest != entry.order_digest) return error.InvalidRecord;
            const expected_run_size = try nodeTextIndexFileSizeForHeader(run_header);
            if (try self.regularFileSize(run_file) != expected_run_size) return error.InvalidRecord;
            var map = if (run_header.hasDerivedTextSpan()) null else openReadOnlyMemoryMap(self.io, run_file, expected_run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .next_index = 0,
                .count = run_header.node_count,
                .header = run_header,
            });
            run_file_owned_by_readers = true;
            map = null;
            try self.pushNextNodeTextOverlayRecord(&readers, &queue, &texts, reader_index);
        }

        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var next_order = NodeTextIndexDigest{};
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            const output_header = NodeTextIndexHeader{
                .node_count = expected_count,
                .node_digest = expected_digest,
            };
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(output_header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            output_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var old_digest = NodeTextIndexDigest{};
            var old_pos: u64 = 0;
            var old_pending: ?NodeTextIndexRecord = null;
            var overlay_pending: ?NodeTextOverlayRunHeapEntry = null;
            var previous: ?NodeTextIndexRecord = null;
            while (old_pos < old_header.node_count or old_pending != null or overlay_pending != null or queue.count() != 0) {
                if (old_pending == null and old_pos < old_header.node_count) {
                    const record = if (old_map) |*mapped|
                        try readNodeTextIndexRecordFromMapForHeaderWithTexts(old_header, mapped, old_pos, &texts)
                    else
                        try self.readNodeTextIndexRecordAtForHeaderWithTexts(old_file, old_header, old_pos, &texts);
                    old_pos += 1;
                    old_pending = record;
                }
                if (overlay_pending == null) overlay_pending = queue.pop();

                const take_old = if (old_pending) |old_record|
                    if (overlay_pending) |overlay_record|
                        nodeTextIndexLessThan({}, old_record, overlay_record.record)
                    else
                        true
                else
                    false;

                const record = if (take_old) blk: {
                    const current = old_pending.?;
                    old_pending = null;
                    const record_digest = try self.nodeTextIndexRecordDigestWithTexts(&texts, current);
                    old_digest.add(current, record_digest);
                    break :blk current;
                } else blk: {
                    const current = overlay_pending orelse return error.InvalidRecord;
                    overlay_pending = null;
                    try self.pushNextNodeTextOverlayRecord(&readers, &queue, &texts, current.run_index);
                    break :blk current.record;
                };

                if (previous) |prev| {
                    if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
                    if (prev.id == record.id) return error.InvalidRecord;
                }
                previous = record;
                next_order.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
                try writeNodeTextIndexRecordToWriter(&writer, output_header, record);
            }
            if (old_digest.count != old_header.node_count) return error.InvalidRecord;
            if (old_digest.digest != old_header.node_digest) return error.InvalidRecord;
            if (old_digest.order_digest != old_header.order_digest) return error.InvalidRecord;
            for (readers.items) |reader| {
                if (reader.next_index != reader.count) return error.InvalidRecord;
                if (reader.digest.count != reader.header.node_count) return error.InvalidRecord;
                if (reader.digest.digest != reader.header.node_digest) return error.InvalidRecord;
                if (reader.digest.order_digest != reader.header.order_digest) return error.InvalidRecord;
            }
            if (next_order.count != expected_count) return error.InvalidRecord;
            if (next_order.digest != expected_digest) return error.InvalidRecord;
            try writer.flush();
            try self.writeNodeTextIndexHeader(new_file, .{
                .node_count = expected_count,
                .node_digest = expected_digest,
                .order_digest = next_order.order_digest,
                .flags = output_header.flags,
                .record_len = output_header.record_len,
                .uniform_kind = output_header.uniform_kind,
            });
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        }

        for (readers.items) |*reader| reader.deinit(self.io);
        readers_closed = true;

        try self.renameReplace(tmp_path, self.node_by_text_path);
        try self.writeEmptyNodeTextDelta();
        const gc = try self.deleteNodeTextRunManifestExcept(pinned_manifest_paths);

        var meta = try self.readIndexMeta();
        if (meta.nodes != expected_count) return error.InvalidRecord;
        if (meta.node_digest != expected_digest) return error.InvalidRecord;
        if (meta.node_by_text_order_digest != expected_order_digest) return error.InvalidRecord;
        meta.node_by_text_order_digest = next_order.order_digest;
        try self.writeIndexMeta(meta);
        return .{
            .order_digest = next_order.order_digest,
            .run_entries_before = manifest.entries.items.len,
            .run_records_before = run_count,
            .delta_records_before = delta_header.node_count,
            .gc_deleted_runs = gc.deleted_runs,
        };
    }

    fn writeMergedNodeTextIndexBatch(
        self: Store,
        old_meta: IndexMeta,
        batch_records: []NodeTextIndexRecord,
        batch_digest: u64,
        next_digest: u64,
        span_derive_mode: NodeTextSpanDeriveMode,
    ) !void {
        if (batch_records.len == 0) return;
        std.mem.sort(NodeTextIndexRecord, batch_records, {}, nodeTextIndexLessThan);
        const next_count = std.math.add(u64, old_meta.nodes, @intCast(batch_records.len)) catch return error.RecordTooLarge;

        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .mode = .read_write, .allow_directory = false });
        defer old_file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
        if (old_header.node_count != old_meta.nodes) return error.InvalidRecord;
        if (old_header.node_digest != old_meta.node_digest) return error.InvalidRecord;
        if (old_header.order_digest != old_meta.node_by_text_order_digest) return error.InvalidRecord;
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        if (old_header.node_count == 0) {
            if (old_meta.node_digest != 0) return error.InvalidRecord;
            if (batch_digest != next_digest) return error.InvalidRecord;
            const batch_order_digest = try sortedNodeTextBatchOrderDigest(batch_records);
            const tmp_path = try self.tmpPathFor(self.node_by_text_path);
            defer self.allocator.free(tmp_path);
            errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
            {
                var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                    .read = true,
                    .truncate = true,
                });
                defer new_file.close(self.io);
                const derive_text_span = try self.nodeTextRecordsCanDeriveSpans(batch_records, span_derive_mode);
                const header = nodeTextIndexHeaderForRecordsWithDerivedSpan(batch_records, next_digest, batch_order_digest, derive_text_span);
                var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(header)));
                defer writer.deinit();

                var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
                header.encode(&header_bytes);
                try writer.append(&header_bytes);
                for (batch_records) |record| {
                    try writeNodeTextIndexRecordToWriter(&writer, header, record);
                }
                try writer.flush();
                if (try writer.position() != try nodeTextIndexFileSizeForHeader(header)) return error.InvalidRecord;
                if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
            }
            try self.renameReplace(tmp_path, self.node_by_text_path);
            try self.writeEmptyNodeTextDelta();
            try self.deleteNodeTextRunManifest();
            try self.ensureCurrentNodeTextBaseHashFilter();
            return;
        }
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        if (try self.appendSortedNodeTextIndexBatchTail(old_file, old_header, batch_records, next_count, next_digest, &texts)) {
            try self.writeEmptyNodeTextDelta();
            try self.deleteNodeTextRunManifest();
            return;
        }
        var old_map = if (old_header.hasDerivedTextSpan()) null else openReadOnlyMemoryMap(self.io, old_file, expected_old_size) catch null;
        defer if (old_map) |*mapped| mapped.destroy(self.io);

        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var new_file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer new_file.close(self.io);
            const output_header = nodeTextHeaderForTail(old_header, next_count, next_digest, 0, batch_records);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, new_file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(output_header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            output_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var batch_pos: usize = 0;
            var old_digest = NodeTextIndexDigest{};
            var next_order = NodeTextIndexDigest{};
            var prev_old: ?NodeTextIndexRecord = null;
            var old_pos: u64 = 0;
            while (old_pos < old_header.node_count) : (old_pos += 1) {
                const current = if (old_map) |*mapped|
                    try readNodeTextIndexRecordFromMapForHeaderWithTexts(old_header, mapped, old_pos, &texts)
                else
                    try self.readNodeTextIndexRecordAtForHeaderWithTexts(old_file, old_header, old_pos, &texts);
                if (prev_old) |prev| {
                    if (!nodeTextIndexLessThan({}, prev, current)) return error.InvalidRecord;
                }
                prev_old = current;
                const current_digest = try self.nodeTextIndexRecordDigestWithTexts(&texts, current);
                old_digest.add(current, current_digest);
                while (batch_pos < batch_records.len and nodeTextIndexLessThan({}, batch_records[batch_pos], current)) : (batch_pos += 1) {
                    next_order.add(batch_records[batch_pos], try self.nodeTextIndexRecordDigestWithTexts(&texts, batch_records[batch_pos]));
                    try writeNodeTextIndexRecordToWriter(&writer, output_header, batch_records[batch_pos]);
                }
                next_order.add(current, current_digest);
                try writeNodeTextIndexRecordToWriter(&writer, output_header, current);
            }
            if (old_digest.digest != old_meta.node_digest) return error.InvalidRecord;
            if (old_digest.order_digest != old_meta.node_by_text_order_digest) return error.InvalidRecord;
            while (batch_pos < batch_records.len) : (batch_pos += 1) {
                next_order.add(batch_records[batch_pos], try self.nodeTextIndexRecordDigestWithTexts(&texts, batch_records[batch_pos]));
                try writeNodeTextIndexRecordToWriter(&writer, output_header, batch_records[batch_pos]);
            }
            if (next_order.count != next_count) return error.InvalidRecord;
            if (next_order.digest != next_digest) return error.InvalidRecord;
            try writer.flush();
            try self.writeNodeTextIndexHeader(new_file, .{
                .node_count = next_count,
                .node_digest = next_digest,
                .order_digest = next_order.order_digest,
                .flags = output_header.flags,
                .record_len = output_header.record_len,
                .uniform_kind = output_header.uniform_kind,
            });
            if (selfOptionsNeedSync(self)) try new_file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_by_text_path);
        try self.writeEmptyNodeTextDelta();
        try self.deleteNodeTextRunManifest();
        try self.ensureCurrentNodeTextBaseHashFilter();
    }

    fn publishNodeTextRunBatchIfPossible(
        self: Store,
        old_meta: IndexMeta,
        next_meta: IndexMeta,
        batch_records: []NodeTextIndexRecord,
        batch_digest: u64,
        span_derive_mode: NodeTextSpanDeriveMode,
    ) !bool {
        if (batch_records.len == 0) return true;
        if (old_meta.nodes == 0) {
            return false;
        }
        const batch_count: u64 = @intCast(batch_records.len);
        if (batch_count > node_text_run_max_records) {
            return false;
        }

        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .allow_directory = false });
        defer old_file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
        const delta_header = try self.readNodeTextDeltaHeader();

        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        if (manifest.entries.items.len >= node_text_run_manifest_max_entries) {
            return false;
        }
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (old_header.node_count + delta_header.node_count + run_count != old_meta.nodes) return error.InvalidRecord;
        if ((old_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != old_meta.node_digest) return error.InvalidRecord;
        if (combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items) != old_meta.node_by_text_order_digest) return error.InvalidRecord;
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        try self.ensureNodeTextBaseHashFilter(old_header);

        std.mem.sort(NodeTextIndexRecord, batch_records, {}, nodeTextIndexLessThan);
        const batch_order_digest = try sortedNodeTextBatchOrderDigest(batch_records);
        if ((old_meta.node_digest ^ batch_digest) != next_meta.node_digest) return error.InvalidRecord;

        const run_path = try self.nodeTextRunBatchPath(old_meta, next_meta, batch_count);
        defer self.allocator.free(run_path);
        if (try self.pathExists(run_path)) {
            return error.AlreadyExists;
        }
        var run_unpublished = true;
        errdefer if (run_unpublished) std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
        try self.writeNodeTextRunFile(run_path, batch_records, batch_digest, batch_order_digest, span_derive_mode);

        var entries = std.ArrayList(NodeTextRunManifestEntry).empty;
        defer entries.deinit(self.allocator);
        try entries.ensureTotalCapacity(self.allocator, manifest.entries.items.len + 1);
        for (manifest.entries.items) |entry| {
            entries.appendAssumeCapacity(.{
                .node_count = entry.node_count,
                .node_digest = entry.node_digest,
                .order_digest = entry.order_digest,
                .min_node_id = entry.min_node_id,
                .max_node_id = entry.max_node_id,
                .min_hash = entry.min_hash,
                .max_hash = entry.max_hash,
                .path = entry.path,
                .hash_filter = entry.hash_filter,
            });
        }
        const batch_id_range = try nodeTextRecordIdRange(batch_records);
        const batch_hash_range = try nodeTextRecordHashRange(batch_records);
        const batch_hash_filter = try self.buildNodeTextRunHashFilterForRecords(batch_records);
        defer self.allocator.free(batch_hash_filter);
        entries.appendAssumeCapacity(.{
            .node_count = batch_count,
            .node_digest = batch_digest,
            .order_digest = batch_order_digest,
            .min_node_id = batch_id_range.min,
            .max_node_id = batch_id_range.max,
            .min_hash = batch_hash_range.min,
            .max_hash = batch_hash_range.max,
            .path = run_path,
            .hash_filter = batch_hash_filter,
        });
        run_unpublished = false;
        try self.writeNodeTextRunManifestEntries(entries.items);
        return true;
    }

    fn nodeTextRunBatchPath(self: Store, old_meta: IndexMeta, next_meta: IndexMeta, batch_count: u64) ![]u8 {
        const parent = try std.fs.path.join(self.allocator, &.{ self.dir_path, "node_text_runs" });
        defer self.allocator.free(parent);
        try std.Io.Dir.cwd().createDirPath(self.io, parent);
        const leaf = try std.fmt.allocPrint(self.allocator, "l0-{}-{}-{}-{}", .{ old_meta.nodes, next_meta.nodes, batch_count, next_meta.event_bytes });
        defer self.allocator.free(leaf);
        return try std.fs.path.join(self.allocator, &.{ parent, leaf });
    }

    fn nodeTextRunWindowCompactionPath(self: Store, meta: IndexMeta, selected_start: usize, selected_entries: usize, selected_records: u64, order_digest: u64) ![]u8 {
        const parent = try std.fs.path.join(self.allocator, &.{ self.dir_path, "node_text_runs" });
        defer self.allocator.free(parent);
        try std.Io.Dir.cwd().createDirPath(self.io, parent);
        const leaf = try std.fmt.allocPrint(self.allocator, "lc-{}-{}-{}-{}-{x}", .{ meta.nodes, selected_start, selected_entries, selected_records, order_digest });
        defer self.allocator.free(leaf);
        return try std.fs.path.join(self.allocator, &.{ parent, leaf });
    }

    fn nodeTextRunWindowCompactionScratchPath(self: Store, meta: IndexMeta, selected_start: usize, selected_entries: usize, selected_records: u64) ![]u8 {
        const parent = try std.fs.path.join(self.allocator, &.{ self.dir_path, "node_text_runs" });
        defer self.allocator.free(parent);
        try std.Io.Dir.cwd().createDirPath(self.io, parent);
        const pid = currentProcessIdForTempPath();
        const leaf = try std.fmt.allocPrint(self.allocator, "lc-{}-{}-{}-{}-{}-{x}.tmp", .{ meta.nodes, selected_start, selected_entries, selected_records, pid, meta.event_bytes });
        defer self.allocator.free(leaf);
        return try std.fs.path.join(self.allocator, &.{ parent, leaf });
    }

    fn writeNodeTextRunFileFromHeap(
        self: Store,
        path: []const u8,
        readers: *std.ArrayList(NodeTextOverlayRunReader),
        queue: *std.PriorityQueue(NodeTextOverlayRunHeapEntry, void, compareNodeTextOverlayRunHeapEntry),
        texts: *const NodeTextsView,
        expected_records: u64,
    ) !NodeTextIndexDigest {
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var compacted_digest = NodeTextIndexDigest{};
        var final_header = NodeTextIndexHeader{ .node_count = expected_records };
        {
            const output_header = NodeTextIndexHeader{ .node_count = expected_records };
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(output_header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            output_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            var previous: ?NodeTextIndexRecord = null;
            while (queue.pop()) |entry| {
                try self.pushNextNodeTextOverlayRecord(readers, queue, texts, entry.run_index);
                const record = entry.record;
                if (previous) |prev| {
                    if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
                    if (prev.id == record.id) return error.InvalidRecord;
                }
                compacted_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(texts, record));
                previous = record;
                try writeNodeTextIndexRecordToWriter(&writer, output_header, record);
            }
            try writer.flush();
            final_header = .{
                .node_count = compacted_digest.count,
                .node_digest = compacted_digest.digest,
                .order_digest = compacted_digest.order_digest,
                .flags = output_header.flags,
                .record_len = output_header.record_len,
                .uniform_kind = output_header.uniform_kind,
            };
        }
        if (compacted_digest.count != expected_records) return error.InvalidRecord;
        for (readers.items) |reader| {
            if (reader.next_index != reader.count) return error.InvalidRecord;
            if (reader.digest.count != reader.header.node_count) return error.InvalidRecord;
            if (reader.digest.digest != reader.header.node_digest) return error.InvalidRecord;
            if (reader.digest.order_digest != reader.header.order_digest) return error.InvalidRecord;
        }

        try self.writeNodeTextIndexHeader(file, final_header);
        try self.compactNodeTextIndexToDerivedRecords(file, &final_header);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        if (try self.regularFileSize(file) != try nodeTextIndexFileSizeForHeader(final_header)) return error.InvalidRecord;
        return compacted_digest;
    }

    fn nodeTextRecordsCanDeriveSpans(self: Store, records: []const NodeTextIndexRecord, mode: NodeTextSpanDeriveMode) !bool {
        return switch (mode) {
            .trusted_recent_by_id_append => records.len != 0,
            .verify_by_id => try self.nodeTextRecordsCanDeriveSpansFromById(records),
        };
    }

    fn nodeTextRecordsCanDeriveSpansFromById(self: Store, records: []const NodeTextIndexRecord) !bool {
        if (records.len == 0) return false;
        var node_file = std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer node_file.close(self.io);
        const node_header = try self.readNodeByIdHeaderFromFile(node_file);
        if (node_header.node_count == 0) return false;
        const node_file_size = try self.regularFileSize(node_file);
        if (node_file_size != try self.nodeByIdFileSizeForHeaderStore(node_header)) return false;
        var node_map = openReadOnlyMemoryMap(self.io, node_file, node_file_size) catch null;
        defer if (node_map) |*mapped| mapped.destroy(self.io);

        for (records) |record| {
            if (record.id == 0 or record.id > node_header.max_node_id) return false;
            const by_id = if (node_map) |*mapped|
                try readNodeByIdRecordFromMap(node_header, mapped, record.id)
            else
                try self.readNodeByIdRecordAt(node_file, node_header, record.id);
            if (by_id.id != record.id or
                by_id.kind != record.kind or
                by_id.text_offset != record.text_offset or
                by_id.text_len != record.text_len)
            {
                return false;
            }
        }
        return true;
    }

    fn writeNodeTextRunFile(
        self: Store,
        path: []const u8,
        records: []const NodeTextIndexRecord,
        node_digest: u64,
        order_digest: u64,
        span_derive_mode: NodeTextSpanDeriveMode,
    ) !void {
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            const derive_text_span = try self.nodeTextRecordsCanDeriveSpans(records, span_derive_mode);
            var texts = try NodeTextsView.open(self);
            defer texts.deinit();
            var header = nodeTextIndexHeaderForRecordsWithDerivedSpan(records, node_digest, order_digest, derive_text_span);
            header.setTextHashUnique(try self.sortedNodeTextRecordsHaveUniqueTextHashes(&texts, records));
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(header)));
            defer writer.deinit();
            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            for (records) |record| {
                try writeNodeTextIndexRecordToWriter(&writer, header, record);
            }
            try writer.flush();
            if (try writer.position() != try nodeTextIndexFileSizeForHeader(header)) return error.InvalidRecord;
            if (!derive_text_span) {
                var compact_header = header;
                try self.compactNodeTextIndexToDerivedRecords(file, &compact_header);
            }
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, path);
    }

    fn buildNodeTextRunHashFilterForRecords(self: Store, records: []const NodeTextIndexRecord) ![]u8 {
        const filter_len = nodeTextRunHashFilterLenForRecords(@intCast(records.len));
        if (filter_len == 0) return try self.allocator.alloc(u8, 0);
        const filter = try self.allocator.alloc(u8, filter_len);
        @memset(filter, 0);
        for (records) |record| nodeTextRunHashFilterSet(filter, record.hash);
        return filter;
    }

    fn buildNodeTextRunHashFilterFromFile(self: Store, path: []const u8, expected_records: u64) ![]u8 {
        const filter_len = nodeTextRunHashFilterLenForRecords(expected_records);
        if (filter_len == 0) return try self.allocator.alloc(u8, 0);
        var file = try std.Io.Dir.cwd().openFile(self.io, path, .{});
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        if (header.node_count != expected_records) return error.InvalidRecord;
        const expected_size = try nodeTextIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var texts: ?NodeTextsView = null;
        defer if (texts) |*view| view.deinit();
        var nodes: ?NodeByIdIndexView = null;
        defer if (nodes) |*view| view.deinit();
        if (header.hasDerivedHash()) {
            texts = try NodeTextsView.open(self);
            if (header.hasDerivedTextSpan()) {
                const meta = try self.readCurrentIndexMeta();
                nodes = try NodeByIdIndexView.open(self, meta);
            }
        }

        const filter = try self.allocator.alloc(u8, filter_len);
        errdefer self.allocator.free(filter);
        @memset(filter, 0);
        var pos: u64 = 0;
        while (pos < header.node_count) : (pos += 1) {
            const hash = try self.readNodeTextIndexRecordHashAtForHeader(file, header, pos, if (texts) |*view| view else null, if (nodes) |*view| view else null);
            nodeTextRunHashFilterSet(filter, hash);
        }
        return filter;
    }

    fn writeNodeTextDeltaBatchIfPossible(self: Store, old_meta: IndexMeta, batch_records: []NodeTextIndexRecord, batch_digest: u64, next_digest: u64) !bool {
        if (batch_records.len == 0) return true;
        if (old_meta.nodes == 0) return false;
        const batch_count: u64 = @intCast(batch_records.len);
        if (batch_count > node_text_delta_max_records) return false;

        var old_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{ .allow_directory = false });
        defer old_file.close(self.io);
        const old_header = try self.readNodeTextIndexHeaderFromFile(old_file);
        const delta_header = try self.readNodeTextDeltaHeader();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (delta_header.node_count + batch_count > node_text_delta_max_records) return false;
        if (old_header.node_count + delta_header.node_count + run_count != old_meta.nodes) return error.InvalidRecord;
        if ((old_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != old_meta.node_digest) return error.InvalidRecord;
        if (combinedNodeTextOrderDigestWithRuns(old_header, delta_header, manifest.entries.items) != old_meta.node_by_text_order_digest) return error.InvalidRecord;
        const expected_old_size = try nodeTextIndexFileSizeForHeader(old_header);
        if (try self.regularFileSize(old_file) != expected_old_size) return error.InvalidRecord;
        try self.ensureNodeTextBaseHashFilter(old_header);

        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        std.mem.sort(NodeTextIndexRecord, batch_records, {}, nodeTextIndexLessThan);
        if (delta_header.node_count == 0) {
            const last = try self.readNodeTextIndexRecordAtForHeaderWithTexts(old_file, old_header, old_header.node_count - 1, &texts);
            if (!nodeTextIndexLessThan({}, batch_records[0], last)) return false;
        }
        if (delta_header.node_count == 0) {
            const batch_order_digest = try sortedNodeTextBatchOrderDigest(batch_records);
            if ((old_meta.node_digest ^ batch_digest) != next_digest) return error.InvalidRecord;
            const tmp_path = try self.tmpPathFor(self.node_by_text_delta_path);
            defer self.allocator.free(tmp_path);
            errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
            var next_header = NodeTextIndexHeader{ .node_count = 0 };
            {
                var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                    .read = true,
                    .truncate = true,
                });
                defer file.close(self.io);
                next_header = nodeTextIndexHeaderForSortedUniqueHashRecords(batch_records, batch_digest, batch_order_digest);
                var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(next_header)));
                defer writer.deinit();

                var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
                next_header.encode(&header_bytes);
                try writer.append(&header_bytes);

                for (batch_records) |record| {
                    try writeNodeTextIndexRecordToWriter(&writer, next_header, record);
                }
                try writer.flush();
                if (selfOptionsNeedSync(self)) try file.sync(self.io);
            }
            try self.renameReplace(tmp_path, self.node_by_text_delta_path);
            self.node_text_delta_header_cache.header = next_header;
            self.node_text_delta_header_cache.valid = true;
            self.refreshNodeTextDeltaRunCache(next_header);
            return true;
        }

        var delta_records = std.ArrayList(NodeTextIndexRecord).empty;
        defer delta_records.deinit(self.allocator);
        try delta_records.ensureTotalCapacity(self.allocator, @intCast(delta_header.node_count + batch_count));
        var old_delta_digest = NodeTextIndexDigest{};
        if (delta_header.node_count != 0) {
            var delta_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{});
            defer delta_file.close(self.io);
            const expected_delta_size = try nodeTextIndexFileSizeForHeader(delta_header);
            if (try self.regularFileSize(delta_file) != expected_delta_size) return error.InvalidRecord;
            var pos: u64 = 0;
            while (pos < delta_header.node_count) : (pos += 1) {
                const record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(delta_file, delta_header, pos, &texts);
                old_delta_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
                try delta_records.append(self.allocator, record);
            }
            if (old_delta_digest.count != delta_header.node_count) return error.InvalidRecord;
            if (old_delta_digest.digest != delta_header.node_digest) return error.InvalidRecord;
            if (old_delta_digest.order_digest != delta_header.order_digest) return error.InvalidRecord;
        }
        for (batch_records) |record| {
            try delta_records.append(self.allocator, record);
        }
        if ((old_meta.node_digest ^ batch_digest) != next_digest) return error.InvalidRecord;
        std.mem.sort(NodeTextIndexRecord, delta_records.items, {}, nodeTextIndexLessThan);
        var delta_digest = NodeTextIndexDigest{};
        var seen_ids = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen_ids.deinit();
        try seen_ids.ensureTotalCapacity(@intCast(delta_records.items.len));
        var previous: ?NodeTextIndexRecord = null;
        for (delta_records.items) |record| {
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
            }
            if ((try seen_ids.getOrPut(record.id)).found_existing) return error.InvalidRecord;
            delta_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(&texts, record));
            previous = record;
        }
        if (delta_digest.count != delta_header.node_count + batch_count) return error.InvalidRecord;
        if ((old_header.node_digest ^ delta_digest.digest ^ manifest.nodeDigest()) != next_digest) return error.InvalidRecord;

        const tmp_path = try self.tmpPathFor(self.node_by_text_delta_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        var next_header = NodeTextIndexHeader{ .node_count = 0 };
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            next_header = nodeTextIndexHeaderForSortedUniqueHashRecords(delta_records.items, delta_digest.digest, delta_digest.order_digest);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(next_header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            next_header.encode(&header_bytes);
            try writer.append(&header_bytes);

            for (delta_records.items) |record| {
                try writeNodeTextIndexRecordToWriter(&writer, next_header, record);
            }
            try writer.flush();
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_by_text_delta_path);
        self.node_text_delta_header_cache.header = next_header;
        self.node_text_delta_header_cache.valid = true;
        self.refreshNodeTextDeltaRunCache(next_header);
        return true;
    }

    fn appendSortedNodeTextIndexBatchTail(
        self: Store,
        file: std.Io.File,
        old_header: NodeTextIndexHeader,
        batch_records: []const NodeTextIndexRecord,
        next_count: u64,
        next_digest: u64,
        texts: *const NodeTextsView,
    ) !bool {
        if (batch_records.len == 0) return true;
        var text_hash_unique = old_header.hasTextHashUnique();
        var previous_for_hash: ?NodeTextIndexRecord = null;
        if (old_header.node_count != 0) {
            const last = try self.readNodeTextIndexRecordAtForHeaderWithTexts(file, old_header, old_header.node_count - 1, texts);
            if (nodeTextIndexLessThan({}, batch_records[0], last)) return false;
            if (text_hash_unique) previous_for_hash = last;
        }

        var next_order = old_header.order_digest;
        var batch_digest: u64 = 0;
        var position = old_header.node_count;
        for (batch_records) |record| {
            if (text_hash_unique) {
                if (previous_for_hash) |prev| {
                    if (prev.hash == record.hash) {
                        text_hash_unique = false;
                    }
                }
                previous_for_hash = record;
            }
            if (!try self.nodeTextRecordFitsStoredHeader(old_header, record)) return false;
            const record_digest = try self.nodeTextIndexRecordDigestWithTexts(texts, record);
            batch_digest ^= record_digest;
            next_order = nodeTextIndexOrderDigestStep(next_order, position, record);
            position = std.math.add(u64, position, 1) catch return error.RecordTooLarge;
        }
        if (position != next_count) return error.InvalidRecord;
        if ((old_header.node_digest ^ batch_digest) != next_digest) return error.InvalidRecord;
        var new_header = nodeTextHeaderForTail(old_header, next_count, next_digest, next_order, batch_records);
        new_header.setTextHashUnique(text_hash_unique);
        if (new_header.record_len != old_header.record_len or
            new_header.flags != old_header.flags or
            new_header.uniform_kind != old_header.uniform_kind) return false;

        var writer = try StorageBufferedWriter.initAtOffset(
            self.allocator,
            self.io,
            file,
            storage_write_buffer_bytes,
            try nodeTextIndexRecordOffsetForHeader(old_header, old_header.node_count),
        );
        defer writer.deinit();
        for (batch_records) |record| {
            try writeNodeTextIndexRecordToWriter(&writer, old_header, record);
        }
        try writer.flush();

        var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        new_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        return true;
    }

    fn appendSortedNodeTextIndexTail(self: Store, file: std.Io.File, old_header: NodeTextIndexHeader, record: NodeTextIndexRecord, record_digest: u64) !void {
        if (old_header.node_count == 0) {
            var new_header = nodeTextIndexHeaderForRecords(&.{record}, record_digest, nodeTextIndexOrderDigestStep(old_header.order_digest, 0, record));
            new_header.setTextHashUnique(true);
            try self.writeNodeTextIndexRecordAt(file, new_header, 0, record);
            try self.writeNodeTextIndexHeader(file, new_header);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
            return;
        }
        if (!nodeTextRecordFitsHeader(old_header, record)) return error.InvalidRecord;
        if (!try self.nodeTextRecordFitsStoredHeader(old_header, record)) return error.InvalidRecord;
        var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        var new_header = NodeTextIndexHeader{
            .node_count = old_header.node_count + 1,
            .node_digest = old_header.node_digest ^ record_digest,
            .order_digest = nodeTextIndexOrderDigestStep(old_header.order_digest, old_header.node_count, record),
            .flags = old_header.flags,
            .record_len = old_header.record_len,
            .uniform_kind = old_header.uniform_kind,
        };
        new_header.setTextHashUnique(false);
        try self.writeNodeTextIndexRecordAt(file, old_header, old_header.node_count, record);
        new_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn readAllNodeTextIndexRecords(self: Store, allocator: std.mem.Allocator) !std.ArrayList(NodeTextIndexRecord) {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer file.close(self.io);
        const header = try self.readNodeTextIndexHeaderFromFile(file);
        const expected_size = try nodeTextIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        var out = std.ArrayList(NodeTextIndexRecord).empty;
        errdefer out.deinit(allocator);
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        var pos: u64 = 0;
        while (pos < header.node_count) : (pos += 1) {
            try out.append(allocator, try self.readNodeTextIndexRecordAtForHeaderWithTexts(file, header, pos, &texts));
        }
        const delta_header = try self.readNodeTextDeltaHeader();
        if (delta_header.node_count != 0) {
            var delta_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_delta_path, .{});
            defer delta_file.close(self.io);
            pos = 0;
            while (pos < delta_header.node_count) : (pos += 1) {
                try out.append(allocator, try self.readNodeTextIndexRecordAtForHeaderWithTexts(delta_file, delta_header, pos, &texts));
            }
        }
        var manifest = try self.readNodeTextRunManifest(allocator);
        defer manifest.deinit(allocator);
        for (manifest.entries.items) |entry| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, entry.path, .{});
            defer run_file.close(self.io);
            const run_header = try self.readNodeTextIndexHeaderFromFile(run_file);
            if (run_header.node_count != entry.node_count or
                run_header.node_digest != entry.node_digest or
                run_header.order_digest != entry.order_digest) return error.InvalidRecord;
            pos = 0;
            while (pos < run_header.node_count) : (pos += 1) {
                try out.append(allocator, try self.readNodeTextIndexRecordAtForHeaderWithTexts(run_file, run_header, pos, &texts));
            }
        }
        if (delta_header.node_count != 0 or manifest.entries.items.len != 0) {
            std.mem.sort(NodeTextIndexRecord, out.items, {}, nodeTextIndexLessThan);
        }
        return out;
    }

    fn writeNodeTextIndex(self: Store, records: []const NodeTextIndexRecord) !void {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        var node_digest: u64 = 0;
        for (records) |record| node_digest ^= try self.nodeTextIndexRecordDigestWithTexts(&texts, record);
        try self.writeNodeTextIndexWithDigestWithTexts(records, node_digest, &texts);
    }

    fn writeNodeTextIndexWithDigest(self: Store, records: []const NodeTextIndexRecord, node_digest: u64) !void {
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        try self.writeNodeTextIndexWithDigestWithTexts(records, node_digest, &texts);
    }

    fn writeNodeTextIndexWithDigestWithTexts(self: Store, records: []const NodeTextIndexRecord, node_digest: u64, texts: *const NodeTextsView) !void {
        var index_digest = NodeTextIndexDigest{};
        for (records) |record| index_digest.add(record, try self.nodeTextIndexRecordDigestWithTexts(texts, record));
        if (index_digest.digest != node_digest) return error.InvalidRecord;
        const text_hash_unique = try self.sortedNodeTextRecordsHaveUniqueTextHashes(texts, records);

        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var header = nodeTextIndexHeaderForRecords(records, node_digest, index_digest.order_digest);
            header.setTextHashUnique(text_hash_unique);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try nodeTextIndexFileSizeForHeader(header)));
            defer writer.deinit();

            var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            for (records) |record| {
                try writeNodeTextIndexRecordToWriter(&writer, header, record);
            }
            try writer.flush();
            try self.compactNodeTextIndexToDerivedRecords(file, &header);
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.node_by_text_path);
        try self.writeEmptyNodeTextDelta();
        try self.deleteNodeTextRunManifest();
        try self.ensureCurrentNodeTextBaseHashFilter();
    }

    fn storedNodeTextsEqual(self: Store, texts: *const NodeTextsView, lhs: NodeTextIndexRecord, rhs: NodeTextIndexRecord) !bool {
        if (lhs.text_len != rhs.text_len) return false;
        const rhs_name = try texts.readTextAlloc(self.allocator, rhs.text_offset, rhs.text_len);
        defer self.allocator.free(rhs_name);
        return try texts.matches(lhs.text_offset, lhs.text_len, rhs_name);
    }

    fn sortedNodeTextRecordsHaveUniqueTextHashes(self: Store, texts: *const NodeTextsView, records: []const NodeTextIndexRecord) !bool {
        _ = self;
        _ = texts;
        var previous: ?NodeTextIndexRecord = null;
        for (records) |record| {
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, record)) return false;
                if (prev.hash == record.hash) return false;
            }
            previous = record;
        }
        return true;
    }

    const NodeTextRepairRunReader = struct {
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        next_index: u64,
        count: u64,
        buffer: []u8 = &.{},
        file_offset: u64 = 0,
        cursor: usize = 0,
        len: usize = 0,

        fn deinit(self: *NodeTextRepairRunReader, allocator: std.mem.Allocator, io: std.Io) void {
            allocator.free(self.buffer);
            if (self.map) |*map| map.destroy(io);
            self.file.close(io);
        }

        fn refill(self: *NodeTextRepairRunReader, store: Store) !void {
            const n = try self.file.readPositionalAll(store.io, self.buffer, self.file_offset);
            if (n == 0) return error.InvalidRecord;
            self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
            self.cursor = 0;
            self.len = n;
        }

        fn readBytes(self: *NodeTextRepairRunReader, store: Store, out: []u8) !void {
            var written: usize = 0;
            while (written < out.len) {
                if (self.cursor == self.len) try self.refill(store);
                const available = self.len - self.cursor;
                const n = @min(available, out.len - written);
                @memcpy(out[written .. written + n], self.buffer[self.cursor .. self.cursor + n]);
                self.cursor += n;
                written += n;
            }
        }

        fn next(self: *NodeTextRepairRunReader, store: Store) !?NodeTextIndexRecord {
            if (self.next_index >= self.count) return null;
            const record = if (self.map) |*map| record: {
                const offset = std.math.mul(u64, self.next_index, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
                const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
                const end = std.math.add(usize, start, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
                if (end > map.memory.len) return error.InvalidRecord;
                break :record try NodeTextIndexRecord.decodeSlice(map.memory[start..end]);
            } else record: {
                if (self.cursor == self.len) try self.refill(store);
                if (self.len - self.cursor >= NodeTextIndexRecord.encoded_len) {
                    const bytes = self.buffer[self.cursor .. self.cursor + NodeTextIndexRecord.encoded_len];
                    self.cursor += NodeTextIndexRecord.encoded_len;
                    break :record try NodeTextIndexRecord.decodeSlice(bytes);
                }
                var bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
                try self.readBytes(store, &bytes);
                break :record try NodeTextIndexRecord.decode(&bytes);
            };
            self.next_index += 1;
            return record;
        }
    };

    const NodeTextRepairRunHeapEntry = struct {
        run_index: usize,
        record: NodeTextIndexRecord,
    };

    const NodeTextRepairPublishShape = struct {
        uniform_kind: ?u16 = null,
        u32_id: bool = false,
        derived_hash: bool = true,
        derived_text_span: bool = false,

        fn header(self: NodeTextRepairPublishShape, record_count: usize, node_digest: u64, order_digest: u64) NodeTextIndexHeader {
            return NodeTextIndexHeader.withShape(
                @intCast(record_count),
                node_digest,
                order_digest,
                self.uniform_kind,
                false,
                self.u32_id,
                self.derived_hash,
                self.derived_text_span,
            );
        }
    };

    fn compareNodeTextRepairRunHeapEntry(_: void, lhs: NodeTextRepairRunHeapEntry, rhs: NodeTextRepairRunHeapEntry) std.math.Order {
        if (nodeTextIndexLessThan({}, lhs.record, rhs.record)) return .lt;
        if (nodeTextIndexLessThan({}, rhs.record, lhs.record)) return .gt;
        return std.math.order(lhs.run_index, rhs.run_index);
    }

    fn writeNodeTextIndexFromRepairSpool(
        self: Store,
        spool_path: []const u8,
        record_count: usize,
        node_digest: u64,
        publish_shape: ?NodeTextRepairPublishShape,
    ) !void {
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        if (record_count <= node_text_repair_sort_chunk_records) {
            var records = std.ArrayList(NodeTextIndexRecord).empty;
            defer records.deinit(self.allocator);
            try records.ensureTotalCapacityPrecise(self.allocator, record_count);
            const chunk_bytes = try self.allocator.alloc(u8, expected_spool_size);
            defer self.allocator.free(chunk_bytes);
            if (record_count != 0) {
                try self.readNodeTextRepairSpoolChunk(spool_file, 0, record_count, chunk_bytes, &records);
                std.mem.sort(NodeTextIndexRecord, records.items, {}, nodeTextIndexLessThan);
            }
            try self.writeSortedNodeTextRepairRecords(records.items, node_digest, publish_shape);
            return;
        }

        var run_paths = std.ArrayList([]u8).empty;
        defer {
            for (run_paths.items) |run_path| {
                std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
                self.allocator.free(run_path);
            }
            run_paths.deinit(self.allocator);
        }

        var chunk = std.ArrayList(NodeTextIndexRecord).empty;
        defer chunk.deinit(self.allocator);
        const max_chunk_records = @min(record_count, node_text_repair_sort_chunk_records);
        try chunk.ensureTotalCapacityPrecise(self.allocator, max_chunk_records);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, max_chunk_records, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord);
        defer self.allocator.free(chunk_bytes);

        var read_pos: usize = 0;
        while (read_pos < record_count) {
            chunk.clearRetainingCapacity();
            const take = @min(node_text_repair_sort_chunk_records, record_count - read_pos);
            try self.readNodeTextRepairSpoolChunk(spool_file, read_pos, take, chunk_bytes, &chunk);
            std.mem.sort(NodeTextIndexRecord, chunk.items, {}, nodeTextIndexLessThan);
            const run_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_run.{d}.tmp", .{ self.node_by_text_path, run_paths.items.len });
            errdefer self.allocator.free(run_path);
            try self.writeNodeTextRepairRun(run_path, chunk.items);
            try run_paths.append(self.allocator, run_path);
            read_pos += take;
        }

        try self.writeMergedNodeTextRepairRuns(run_paths.items, record_count, node_digest, publish_shape);
    }

    fn readNodeTextRepairSpoolChunk(self: Store, file: std.Io.File, start_index: usize, record_count: usize, buffer: []u8, out: *std.ArrayList(NodeTextIndexRecord)) !void {
        const byte_count = std.math.mul(usize, record_count, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (byte_count > buffer.len) return error.InvalidRecord;
        const offset = std.math.mul(u64, @intCast(start_index), NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
        const n = try file.readPositionalAll(self.io, buffer[0..byte_count], offset);
        if (n != byte_count) return error.InvalidRecord;
        var cursor: usize = 0;
        while (cursor < byte_count) : (cursor += NodeTextIndexRecord.encoded_len) {
            out.appendAssumeCapacity(try NodeTextIndexRecord.decodeSlice(buffer[cursor .. cursor + NodeTextIndexRecord.encoded_len]));
        }
    }

    fn writeSortedNodeTextRepairRecords(
        self: Store,
        records: []const NodeTextIndexRecord,
        node_digest: u64,
        publish_shape: ?NodeTextRepairPublishShape,
    ) !void {
        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);

        var order_digest: u64 = 0;
        var previous: ?NodeTextIndexRecord = null;
        for (records, 0..) |record, index| {
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
            }
            previous = record;
            order_digest = nodeTextIndexOrderDigestStep(order_digest, @intCast(index), record);
        }

        var header = if (publish_shape) |shape|
            shape.header(records.len, node_digest, order_digest)
        else
            nodeTextIndexHeaderForRecords(records, node_digest, order_digest);
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        header.setTextHashUnique(try self.sortedNodeTextRecordsHaveUniqueTextHashes(&texts, records));
        const expected_size = try nodeTextIndexFileSizeForHeader(header);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try writer.append(&header_bytes);
        for (records) |record| {
            try writeNodeTextIndexRecordToWriter(&writer, header, record);
        }
        try writer.flush();
        if (try writer.position() != try nodeTextIndexFileSizeForHeader(header)) return error.InvalidRecord;
        if (try self.regularFileSize(file) != try nodeTextIndexFileSizeForHeader(header)) return error.InvalidRecord;

        if (publish_shape == null) try self.compactNodeTextIndexToDerivedRecords(file, &header);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, self.node_by_text_path);
    }

    fn writeNodeTextRepairRun(self: Store, path: []const u8, records: []const NodeTextIndexRecord) !void {
        const expected_size = std.math.mul(u64, @intCast(records.len), NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();
        var record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        for (records) |record| {
            try record.encode(&record_bytes);
            try writer.append(&record_bytes);
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn writeMergedNodeTextRepairRuns(
        self: Store,
        run_paths: []const []const u8,
        record_count: usize,
        node_digest: u64,
        publish_shape: ?NodeTextRepairPublishShape,
    ) !void {
        const tmp_path = try self.tmpPathFor(self.node_by_text_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var readers = std.ArrayList(NodeTextRepairRunReader).empty;
        defer {
            for (readers.items) |*reader| reader.deinit(self.allocator, self.io);
            readers.deinit(self.allocator);
        }
        try readers.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        var queue = std.PriorityQueue(NodeTextRepairRunHeapEntry, void, compareNodeTextRepairRunHeapEntry).initContext({});
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        for (run_paths) |run_path| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, run_path, .{});
            var close_run_file = true;
            errdefer if (close_run_file) run_file.close(self.io);
            const run_size = try self.regularFileSize(run_file);
            if (run_size % NodeTextIndexRecord.encoded_len != 0) return error.InvalidRecord;
            const run_count = run_size / NodeTextIndexRecord.encoded_len;
            var map = if (run_count == 0) null else openReadOnlyMemoryMap(self.io, run_file, run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            var buffer: []u8 = &.{};
            errdefer self.allocator.free(buffer);
            if (map == null) {
                buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(run_size));
            }
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .next_index = 0,
                .count = run_count,
                .buffer = buffer,
            });
            close_run_file = false;
            map = null;
            buffer = &.{};
            if (run_count != 0) {
                const record = (try readers.items[reader_index].next(self)) orelse return error.InvalidRecord;
                try queue.push(self.allocator, .{ .run_index = reader_index, .record = record });
            }
        }

        const placeholder_header = if (publish_shape) |shape|
            shape.header(record_count, node_digest, 0)
        else
            NodeTextIndexHeader{
                .node_count = @intCast(record_count),
                .node_digest = node_digest,
            };
        const expected_size = try nodeTextIndexFileSizeForHeader(placeholder_header);
        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        placeholder_header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var order_digest: u64 = 0;
        var emitted: u64 = 0;
        var previous: ?NodeTextIndexRecord = null;
        var text_hash_unique = true;
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        var record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        while (queue.pop()) |entry| {
            if (previous) |prev| {
                if (!nodeTextIndexLessThan({}, prev, entry.record)) return error.InvalidRecord;
                if (prev.hash == entry.record.hash) {
                    text_hash_unique = false;
                }
            }
            previous = entry.record;
            order_digest = nodeTextIndexOrderDigestStep(order_digest, emitted, entry.record);
            emitted += 1;
            if (publish_shape != null) {
                try writeNodeTextIndexRecordToWriter(&writer, placeholder_header, entry.record);
            } else {
                try entry.record.encode(&record_bytes);
                try writer.append(&record_bytes);
            }

            const reader = &readers.items[entry.run_index];
            if (try reader.next(self)) |record| {
                try queue.push(self.allocator, .{ .run_index = entry.run_index, .record = record });
            }
        }
        if (emitted != record_count) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var header = if (publish_shape) |shape|
            shape.header(record_count, node_digest, order_digest)
        else
            NodeTextIndexHeader{
                .node_count = @intCast(record_count),
                .node_digest = node_digest,
                .order_digest = order_digest,
            };
        header.setTextHashUnique(text_hash_unique);
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (publish_shape == null) try self.compactNodeTextIndexToDerivedRecords(file, &header);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, self.node_by_text_path);
    }

    fn validateNodeIndexAppend(self: Store, node: graph_mod.Node) !void {
        if (node.status != .active) return;
        const node_id = node.id.toInt();
        if (node_id == 0 or node_id == std.math.maxInt(u64)) return core.Error.InvalidId;
        const meta = try self.readCurrentIndexMetaForAppend();
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;
        var index_file = std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return,
            else => |e| return e,
        };
        defer index_file.close(self.io);
        const header = try self.readNodeByIdHeaderFromFile(index_file);
        if (header.node_count != meta.nodes) return error.InvalidRecord;
        if (header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (header.node_count > header.max_node_id) return error.InvalidRecord;
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(header);
        if (try self.regularFileSize(index_file) != expected_size) return error.InvalidRecord;
        const empty_uniform = header.node_count == 0;
        const short_text_len = nodeTextLenFitsU16(node.text.len);
        const would_convert = !empty_uniform and header.hasUniformKind() and header.uniform_kind != @intFromEnum(node.kind);
        const derived_dense_tail = header.hasDerivedTextOffset() and !would_convert and short_text_len and
            header.max_node_id != std.math.maxInt(u64) and node_id == header.max_node_id + 1;
        const would_expand_derived = !would_convert and header.hasDerivedTextOffset() and !derived_dense_tail;
        const would_widen_uniform = !would_convert and header.hasUniformKind() and header.hasShortTextLen() and !short_text_len;
        const next_flags: u16 = if (empty_uniform)
            NodeByIdHeader.flag_uniform_kind | if (short_text_len) NodeByIdHeader.flag_short_text_len else 0
        else if (would_convert)
            0
        else if (derived_dense_tail)
            NodeByIdHeader.flag_uniform_kind | NodeByIdHeader.flag_short_text_len | NodeByIdHeader.flag_derived_text_offset
        else if (would_expand_derived)
            NodeByIdHeader.flag_uniform_kind | if (short_text_len) NodeByIdHeader.flag_short_text_len else 0
        else if (would_widen_uniform)
            header.flags & ~NodeByIdHeader.flag_short_text_len
        else
            header.flags;
        const next_record_len: u16 = if (empty_uniform)
            if (short_text_len) NodeByIdRecord.uniform_short_text_len_encoded_len else NodeByIdRecord.uniform_encoded_len
        else if (would_convert)
            NodeByIdRecord.encoded_len
        else if (derived_dense_tail)
            NodeByIdRecord.uniform_short_derived_offset_encoded_len
        else if (would_expand_derived)
            if (short_text_len) NodeByIdRecord.uniform_short_text_len_encoded_len else NodeByIdRecord.uniform_encoded_len
        else if (would_widen_uniform)
            NodeByIdRecord.uniform_encoded_len
        else
            header.record_len;
        const next_node_count_for_size = if (derived_dense_tail) header.node_count + 1 else header.node_count;
        _ = try self.nodeByIdFileSizeForHeaderStore(.{
            .max_node_id = @max(header.max_node_id, node_id),
            .node_count = next_node_count_for_size,
            .node_digest = header.node_digest,
            .flags = next_flags,
            .record_len = next_record_len,
            .uniform_kind = if (empty_uniform) @intFromEnum(node.kind) else if (would_convert) 0 else header.uniform_kind,
        });
        if (node_id > header.max_node_id) return;
        const existing = try self.readNodeByIdRecordAt(index_file, header, node_id);
        if (existing.id == 0 and header.node_count == header.max_node_id) return error.InvalidRecord;
        if (existing.id != 0) return core.Error.InvalidId;
    }

    fn validateNodeBatchAppend(self: Store, nodes: []const graph_mod.Node, meta: IndexMeta) !void {
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        try seen.ensureTotalCapacity(@intCast(nodes.len));

        var index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{});
        defer index_file.close(self.io);
        const header = try self.readNodeByIdHeaderFromFile(index_file);
        if (header.node_count != meta.nodes) return error.InvalidRecord;
        if (header.node_digest != meta.node_digest) return error.InvalidRecord;
        if (header.node_count > header.max_node_id) return error.InvalidRecord;
        const expected_size = try self.nodeByIdFileSizeForHeaderStore(header);
        if (try self.regularFileSize(index_file) != expected_size) return error.InvalidRecord;
        if (self.options.validate_indexes_on_read and !try self.nodeIndexValid(meta.nodes)) return error.InvalidRecord;

        var texts_file = try std.Io.Dir.cwd().openFile(self.io, self.node_texts_path, .{});
        defer texts_file.close(self.io);
        _ = try self.regularFileSize(texts_file);

        var text_index_file = try std.Io.Dir.cwd().openFile(self.io, self.node_by_text_path, .{});
        defer text_index_file.close(self.io);
        const text_header = try self.readNodeTextIndexHeaderFromFile(text_index_file);
        const delta_header = try self.readNodeTextDeltaHeader();
        var manifest = try self.readNodeTextRunManifest(self.allocator);
        defer manifest.deinit(self.allocator);
        const run_count = manifest.totalNodeCount();
        if (run_count == std.math.maxInt(u64)) return error.InvalidRecord;
        if (text_header.node_count + delta_header.node_count + run_count != meta.nodes) return error.InvalidRecord;
        if ((text_header.node_digest ^ delta_header.node_digest ^ manifest.nodeDigest()) != meta.node_digest) return error.InvalidRecord;
        if (combinedNodeTextOrderDigestWithRuns(text_header, delta_header, manifest.entries.items) != meta.node_by_text_order_digest) return error.InvalidRecord;
        if (try self.regularFileSize(text_index_file) != try nodeTextIndexFileSizeForHeader(text_header)) return error.InvalidRecord;
        if (try self.fileSizeOrZero(self.node_by_text_delta_path) != try nodeTextIndexFileSizeForHeader(delta_header)) return error.InvalidRecord;

        var next_count = meta.nodes;
        var next_max = header.max_node_id;
        var next_record_len = header.record_len;
        var next_flags = header.flags;
        var next_uniform_kind = header.uniform_kind;
        const derived_dense_tail_batch = nodeByIdCanAppendDerivedDenseTail(header, nodes);
        const has_zero_length_text = nodeBatchHasZeroLengthText(nodes);
        if (header.hasUniformKind() and (has_zero_length_text or !nodeByIdCanUseUniformAppend(header, nodes))) {
            next_record_len = NodeByIdRecord.encoded_len;
            next_flags = 0;
            next_uniform_kind = 0;
        } else if (derived_dense_tail_batch) {
            next_record_len = NodeByIdRecord.uniform_short_derived_offset_encoded_len;
            next_flags = NodeByIdHeader.flag_uniform_kind | NodeByIdHeader.flag_short_text_len | NodeByIdHeader.flag_derived_text_offset;
        } else if (header.hasDerivedTextOffset()) {
            next_record_len = NodeByIdRecord.uniform_encoded_len;
            next_flags = NodeByIdHeader.flag_uniform_kind;
        } else if (header.node_count == 0 and !has_zero_length_text and nodeByIdCanUseUniformAppend(header, nodes)) {
            const short_text_lens = nodeBatchTextsFitU16(nodes);
            next_record_len = if (short_text_lens) NodeByIdRecord.uniform_short_text_len_encoded_len else NodeByIdRecord.uniform_encoded_len;
            next_flags = NodeByIdHeader.flag_uniform_kind | if (short_text_lens) NodeByIdHeader.flag_short_text_len else 0;
            next_uniform_kind = @intFromEnum(nodes[0].kind);
        } else if (header.hasUniformKind() and header.hasShortTextLen() and !nodeBatchTextsFitU16(nodes)) {
            next_record_len = NodeByIdRecord.uniform_encoded_len;
            next_flags = header.flags & ~NodeByIdHeader.flag_short_text_len;
        }
        for (nodes) |node| {
            if (node.status != .active) return core.Error.Unsupported;
            if (node.text.len > maxBinaryNodeTextLen()) return error.RecordTooLarge;
            try graph_mod.validateNodeText(node.text);
            const node_id = node.id.toInt();
            if (node_id == 0 or node_id == std.math.maxInt(u64)) return core.Error.InvalidId;
            const entry = try seen.getOrPut(node_id);
            if (entry.found_existing) return core.Error.InvalidId;
            next_count = std.math.add(u64, next_count, 1) catch return error.RecordTooLarge;
            next_max = @max(next_max, node_id);
            _ = try self.nodeByIdFileSizeForHeaderStore(.{
                .max_node_id = next_max,
                .node_count = if (derived_dense_tail_batch) next_count else header.node_count,
                .node_digest = header.node_digest,
                .flags = next_flags,
                .record_len = next_record_len,
                .uniform_kind = next_uniform_kind,
            });
            if (node_id <= header.max_node_id) {
                const existing = try self.readNodeByIdRecordAt(index_file, header, node_id);
                if (existing.id == 0 and header.node_count == header.max_node_id) return error.InvalidRecord;
                if (existing.id != 0) return core.Error.InvalidId;
            }
        }
    }

    fn validateNodeIndexAppendWithRepair(self: Store, node: graph_mod.Node) !void {
        self.validateNodeIndexAppend(node) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                try self.repairPersistentIndexesFromLog();
                return try self.validateNodeIndexAppend(node);
            },
            else => |e| return e,
        };
    }

    fn validateEdgeAppend(self: Store, edge: graph_mod.Edge) !void {
        if (edge.id == .none or edge.id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
        if (edge.src == .none or edge.dst == .none) return core.Error.InvalidId;
        if (edge.src.toInt() == std.math.maxInt(u64) or edge.dst.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
        const meta = try self.readCurrentIndexMetaForAppend();
        var id_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer id_file.close(self.io);
        const id_header = try self.validateEdgeIndexHeaderForAppend(id_file, .id, meta);
        if (id_header.edge_count != 0) {
            const last = try self.readEdgeIndexRecordAt(id_file, id_header, id_header.edge_count - 1);
            if (last.edge_id > meta.max_edge_id_seen) return error.InvalidRecord;
        }
        var src_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_src_path, .{});
        defer src_file.close(self.io);
        _ = try self.validateEdgeIndexHeaderForAppend(src_file, .src, meta);
        var dst_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_dst_path, .{});
        defer dst_file.close(self.io);
        _ = try self.validateEdgeIndexHeaderForAppend(dst_file, .dst, meta);
        if (self.options.validate_indexes_on_read) {
            if (!try self.edgeIndexesValidatedAndMatchMeta(meta)) return error.InvalidRecord;
        }
        if (try self.edgeIdExistsInFile(id_file, id_header, edge.id.toInt())) return core.Error.InvalidId;
        if (edge.id.toInt() <= meta.max_edge_id_seen) {
            if (try self.edgeTombstoneContains(edge.id.toInt())) return core.Error.InvalidId;
            if (try self.edgeIdExistsInSegmentOverlay(meta, edge.id.toInt())) return core.Error.InvalidId;
        }
        var src = (try self.readNodeById(self.allocator, edge.src)) orelse return core.Error.NotFound;
        defer src.deinit(self.allocator);
        var dst = (try self.readNodeById(self.allocator, edge.dst)) orelse return core.Error.NotFound;
        defer dst.deinit(self.allocator);
    }

    fn validateEdgeAppendWithRepair(self: Store, edge: graph_mod.Edge) !void {
        self.validateEdgeAppend(edge) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => {
                try self.repairPersistentIndexesFromLog();
                return try self.validateEdgeAppend(edge);
            },
            else => |e| return e,
        };
    }

    fn validateEdgeBatchAppend(
        self: Store,
        edges: []const graph_mod.Edge,
        meta: IndexMeta,
        edge_records: *std.ArrayList(EdgeIndexRecord),
        next_meta: *IndexMeta,
        segment_delta_append: bool,
    ) !void {
        var node_view = try NodeByIdIndexView.open(self, meta);
        defer node_view.deinit();

        var id_file: ?std.Io.File = null;
        defer if (id_file) |file| file.close(self.io);
        var id_header: ?EdgeIndexHeader = null;
        const ids_known_new = if (segment_delta_append) true else blk: {
            id_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
            id_header = try self.validateEdgeIndexHeaderForAppend(id_file.?, .id, meta);
            if (id_header.?.edge_count != 0) {
                const last = try self.readEdgeIndexRecordAt(id_file.?, id_header.?, id_header.?.edge_count - 1);
                if (last.edge_id > meta.max_edge_id_seen) return error.InvalidRecord;
            }
            var src_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_src_path, .{});
            defer src_file.close(self.io);
            _ = try self.validateEdgeIndexHeaderForAppend(src_file, .src, meta);
            var dst_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_dst_path, .{});
            defer dst_file.close(self.io);
            _ = try self.validateEdgeIndexHeaderForAppend(dst_file, .dst, meta);

            if (self.options.validate_indexes_on_read) {
                if (!try self.edgeIndexesValidatedAndMatchMeta(meta)) return error.InvalidRecord;
            }
            break :blk try self.edgeBatchIdsAppendAfterTail(id_file.?, id_header.?, meta, edges);
        };
        if (segment_delta_append and !ids_known_new) return error.InvalidRecord;
        var seen = std.AutoHashMap(u64, void).init(self.allocator);
        defer seen.deinit();
        if (!ids_known_new) try seen.ensureTotalCapacity(@intCast(edges.len));
        var node_cache = EdgeBatchNodeExistenceCache{};
        var tombstone_view: ?EdgeTombstoneIndexView = null;
        defer if (tombstone_view) |*view| view.deinit();
        var tombstone_view_loaded = false;

        next_meta.* = meta;
        for (edges) |edge| {
            if (edge.status != .active) return core.Error.Unsupported;
            const record = edgeIndexRecordFromEdge(edge);
            if (record.edge_id == 0 or record.edge_id == std.math.maxInt(u64)) return core.Error.InvalidId;
            if (record.src == 0 or record.dst == 0 or record.src == std.math.maxInt(u64) or record.dst == std.math.maxInt(u64)) return core.Error.InvalidId;
            if (!ids_known_new) {
                const entry = try seen.getOrPut(record.edge_id);
                if (entry.found_existing) return core.Error.InvalidId;
                if (try self.edgeIdExistsInFile(id_file.?, id_header.?, record.edge_id)) return core.Error.InvalidId;
                if (record.edge_id <= meta.max_edge_id_seen) {
                    if (!tombstone_view_loaded) {
                        const tombstone_header = try self.readEdgeTombstoneIndexHeader();
                        if (tombstone_header.count != 0) tombstone_view = try EdgeTombstoneIndexView.open(self);
                        tombstone_view_loaded = true;
                    }
                    if (tombstone_view) |*view| {
                        if (try view.contains(record.edge_id)) return core.Error.InvalidId;
                    }
                    if (try self.edgeIdExistsInSegmentOverlay(meta, record.edge_id)) return core.Error.InvalidId;
                }
            }
            if (!try node_cache.nodeExists(&node_view, record.src)) return core.Error.NotFound;
            if (!try node_cache.nodeExists(&node_view, record.dst)) return core.Error.NotFound;
            edge_records.appendAssumeCapacity(record);
            next_meta.edges = std.math.add(u64, next_meta.edges, 1) catch return error.RecordTooLarge;
            next_meta.edge_digest ^= edgeRecordDigest(record);
            next_meta.edge_indexed_edges = std.math.add(u64, next_meta.edge_indexed_edges, 1) catch return error.RecordTooLarge;
            next_meta.edge_index_digest ^= edgeRecordDigest(record);
            next_meta.max_edge_id_seen = @max(next_meta.max_edge_id_seen, record.edge_id);
        }
        _ = try edgeIndexFileSize(next_meta.edge_indexed_edges);
    }

    fn edgeBatchIdsAppendAfterTail(self: Store, id_file: std.Io.File, id_header: EdgeIndexHeader, meta: IndexMeta, edges: []const graph_mod.Edge) !bool {
        if (edges.len == 0) return true;
        const first_id = edges[0].id.toInt();
        if (first_id == 0 or first_id == std.math.maxInt(u64)) return false;
        if (first_id <= meta.max_edge_id_seen) return false;

        if (id_header.edge_count != 0) {
            const last = try self.readEdgeIndexRecordAt(id_file, id_header, id_header.edge_count - 1);
            if (last.edge_id >= first_id) return false;
        }

        var previous = first_id;
        var pos: usize = 1;
        while (pos < edges.len) : (pos += 1) {
            const current = edges[pos].id.toInt();
            if (current == 0 or current == std.math.maxInt(u64)) return false;
            if (current <= previous) return false;
            previous = current;
        }
        return true;
    }

    fn validateEdgeIndexHeaderForAppend(self: Store, file: std.Io.File, order: EdgeIndexOrder, meta: IndexMeta) !EdgeIndexHeader {
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != order) return error.InvalidRecord;
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, order)) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        return header;
    }

    fn edgeIdExists(self: Store, edge_id: core.EdgeId) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer file.close(self.io);
        const meta = try self.readCurrentIndexMeta();
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != .id) return error.InvalidRecord;
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, .id)) return error.InvalidRecord;
        const expected_size = try edgeIndexFileSizeForHeader(header);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        return try self.edgeIdExistsInFile(file, header, edge_id.toInt());
    }

    fn visibleEdgeIdExists(self: Store, edge_id: core.EdgeId) !bool {
        const raw_id = edge_id.toInt();
        if (raw_id == 0 or raw_id == std.math.maxInt(u64)) return false;
        if (try self.edgeTombstoneContains(raw_id)) return false;
        if (try self.edgeIdExists(edge_id)) return true;
        const meta = try self.readCurrentIndexMeta();
        return try self.edgeIdExistsInSegmentOverlay(meta, raw_id);
    }

    fn edgeSegmentMetaSummaryCurrent(self: Store, meta: IndexMeta) !bool {
        if (meta.edge_segment_edges == 0) return false;
        try meta.edge_segment_id_runs.validate();
        if (meta.edge_segment_id_runs.run_count == 0) return false;
        if (try meta.edge_segment_id_runs.coveredCount() != meta.edge_segment_edges) return false;
        if (try self.edgeSegmentManifestCoveredPhysicalEdges(meta, meta.edge_segment_edges) == null) {
            if (!try self.edgeSegmentManifestCoversVisibleEdges(meta, meta.edge_segment_edges)) return false;
        }
        const current_path = (try self.readEdgeSegmentCurrentPath(self.allocator)) orelse return false;
        defer self.allocator.free(current_path);
        const expected_path = try self.edgeSegmentManifestEpochPathWithAllocator(self.allocator, meta.edge_segment_edges, meta.edge_segment_manifest_digest);
        defer self.allocator.free(expected_path);
        return std.mem.eql(u8, current_path, expected_path);
    }

    fn edgeSegmentMetaSummaryReadable(self: Store, meta: IndexMeta) !bool {
        if (meta.edge_segment_edges == 0) return false;
        try meta.edge_segment_id_runs.validate();
        if (meta.edge_segment_id_runs.run_count == 0) return false;
        if (try meta.edge_segment_id_runs.coveredCount() != meta.edge_segment_edges) return false;
        const current_path = (try self.readEdgeSegmentCurrentPath(self.allocator)) orelse return false;
        defer self.allocator.free(current_path);
        const expected_path = try self.edgeSegmentManifestEpochPathWithAllocator(self.allocator, meta.edge_segment_edges, meta.edge_segment_manifest_digest);
        defer self.allocator.free(expected_path);
        if (!std.mem.eql(u8, current_path, expected_path)) return false;
        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound, error.InvalidRecord => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);
        return manifest.totalEdgeCount() == meta.edge_segment_edges;
    }

    fn edgeSegmentMetaSummaryContains(self: Store, meta: IndexMeta, edge_id: u64) !?bool {
        if (!try self.edgeSegmentMetaSummaryCurrent(meta)) return null;
        return meta.edge_segment_id_runs.contains(edge_id);
    }

    fn edgeSegmentMetaSummaryIntersects(self: Store, meta: IndexMeta, ids_by_id: []const u64) !?bool {
        if (!try self.edgeSegmentMetaSummaryCurrent(meta)) return null;
        return meta.edge_segment_id_runs.intersectsSortedIds(ids_by_id);
    }

    fn edgeIdSetIntersectsSegmentOverlayAfterEligibility(
        self: Store,
        meta: IndexMeta,
        ids_by_id: []const u64,
        min_edge_id: u64,
        max_edge_id: u64,
        edge_segment_summary_current: bool,
    ) !bool {
        if (edge_segment_summary_current) {
            return meta.edge_segment_id_runs.intersectsSortedIds(ids_by_id);
        }
        return try self.edgeIdSetIntersectsSegmentOverlay(meta, ids_by_id, min_edge_id, max_edge_id);
    }

    fn edgeIdExistsInSegmentOverlay(self: Store, meta: IndexMeta, edge_id: u64) !bool {
        if (try self.edgeSegmentMetaSummaryContains(meta, edge_id)) |contains| return contains;

        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);

        const manifest_edges = manifest.totalEdgeCount();
        const physical_edges = (try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges)) orelse return error.InvalidRecord;
        if (manifest_edges != physical_edges and meta.edge_indexed_edges >= physical_edges) return false;

        for (manifest.entries.items) |entry| {
            if (manifest.ranges_trusted and (edge_id < entry.edge_id_range.min or edge_id > entry.edge_id_range.max)) continue;
            if (manifest.ranges_trusted) {
                const single = [_]u64{edge_id};
                if (try trustedRunSummaryMayIntersect(entry, &single)) |may_intersect| {
                    if (may_intersect) return true;
                    continue;
                }
                if (try trustedSingletonEdgeSegmentId(entry)) |singleton_id| {
                    if (edge_id == singleton_id) return true;
                    continue;
                }
            }
            if (try self.edgeSegmentIdIndexContains(entry, edge_id)) |found| {
                if (found) return true;
                continue;
            }
            var segment = try segment_mod.ImmutableAdjacencySegment.open(self.allocator, self.io, entry.path);
            defer segment.deinit();
            if (try segment.edgeCount() != entry.edge_count) return error.InvalidRecord;
            if (!try segment.mayContainEdgeId(edge_id)) continue;
            var iter = try segment.edgeIterator(.forward);
            while (try iter.next()) |edge| {
                if (edge.edge_id.toInt() == edge_id) return true;
            }
        }
        return false;
    }

    fn edgeIdSetIntersectsSegmentOverlay(
        self: Store,
        meta: IndexMeta,
        ids_by_id: []const u64,
        min_edge_id: u64,
        max_edge_id: u64,
    ) !bool {
        if (try self.edgeSegmentMetaSummaryIntersects(meta, ids_by_id)) |intersects| return intersects;

        var manifest = self.readEdgeSegmentManifest(self.allocator) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => |e| return e,
        };
        defer manifest.deinit(self.allocator);

        const manifest_edges = manifest.totalEdgeCount();
        const physical_edges = (try self.edgeSegmentManifestCoveredPhysicalEdges(meta, manifest_edges)) orelse return error.InvalidRecord;
        if (manifest_edges != physical_edges and meta.edge_indexed_edges >= physical_edges) return false;

        for (manifest.entries.items) |entry| {
            if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.overlay_entries_considered += 1;
            if (manifest.ranges_trusted and (max_edge_id < entry.edge_id_range.min or min_edge_id > entry.edge_id_range.max)) {
                if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.overlay_entries_range_skipped += 1;
                continue;
            }
            const entry_ids = if (manifest.ranges_trusted) blk: {
                const start = lowerBoundU64(ids_by_id, entry.edge_id_range.min);
                if (start >= ids_by_id.len or ids_by_id[start] > entry.edge_id_range.max) {
                    if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.overlay_entries_range_skipped += 1;
                    continue;
                }
                const end = upperBoundU64(ids_by_id, entry.edge_id_range.max);
                break :blk ids_by_id[start..end];
            } else ids_by_id;
            if (manifest.ranges_trusted) {
                if (try trustedRunSummaryMayIntersect(entry, entry_ids)) |may_intersect| {
                    if (may_intersect) return true;
                    if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.overlay_entries_range_skipped += 1;
                    continue;
                }
                if (try trustedSingletonEdgeSegmentId(entry)) |_| return true;
            }
            if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.overlay_sidecar_checks += 1;
            if (try self.edgeSegmentIdIndexIntersects(entry, entry_ids)) |found| {
                if (found) return true;
                continue;
            }
            if (self.edge_batch_segment_delta_stats) |delta_stats| delta_stats.overlay_csr_fallbacks += 1;
            var segment = try segment_mod.ImmutableAdjacencySegment.open(self.allocator, self.io, entry.path);
            defer segment.deinit();
            if (try segment.edgeCount() != entry.edge_count) return error.InvalidRecord;
            if (!try segment.edgeIdRangeMayIntersect(min_edge_id, max_edge_id)) continue;
            var iter = try segment.edgeIterator(.forward);
            while (try iter.next()) |edge| {
                if (u64SortedContains(ids_by_id, edge.edge_id.toInt())) return true;
            }
        }
        return false;
    }

    fn edgeIndexTailExceedsHighWater(self: Store, meta: IndexMeta) !bool {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer file.close(self.io);
        const header = try self.readEdgeIndexHeaderFromFile(file);
        if (header.order != .id) return error.InvalidRecord;
        if (header.edge_count != meta.edge_indexed_edges) return error.InvalidRecord;
        if (header.edge_digest != meta.edge_index_digest) return error.InvalidRecord;
        if (header.order_digest != edgeOrderDigestForMeta(meta, .id)) return error.InvalidRecord;
        if (header.edge_count == 0) return false;
        if (header.hasDenseId()) {
            if (try self.regularFileSize(file) != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;
            return header.edge_count > meta.max_edge_id_seen;
        }
        const last = try self.readEdgeIndexRecordAt(file, header, header.edge_count - 1);
        return last.edge_id > meta.max_edge_id_seen;
    }

    fn edgeIdExistsInFile(self: Store, file: std.Io.File, header: EdgeIndexHeader, id: u64) !bool {
        if (header.order == .id and header.hasDenseId()) {
            if (try self.regularFileSize(file) != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;
            return id != 0 and id <= header.edge_count;
        }
        const lo = try self.edgeIdLowerBoundInFileFrom(file, header, id, 0);
        if (lo >= header.edge_count) return false;
        const record = try self.readEdgeIndexRecordAt(file, header, lo);
        return record.edge_id == id;
    }

    fn edgeIdSortedSetIntersectsFile(self: Store, file: std.Io.File, header: EdgeIndexHeader, ids_by_id: []const u64) !bool {
        if (ids_by_id.len == 0 or header.edge_count == 0) return false;
        if (header.order == .id and header.hasDenseId()) {
            if (try self.regularFileSize(file) != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;
            const pos = lowerBoundU64(ids_by_id, 1);
            return pos < ids_by_id.len and ids_by_id[pos] <= header.edge_count;
        }
        var id_index: usize = 0;
        var base_index = try self.edgeIdLowerBoundInFileFrom(file, header, ids_by_id[id_index], 0);
        while (id_index < ids_by_id.len and base_index < header.edge_count) {
            const record = try self.readEdgeIndexRecordAt(file, header, base_index);
            const candidate = ids_by_id[id_index];
            if (record.edge_id == candidate) return true;
            if (record.edge_id < candidate) {
                base_index = try self.edgeIdLowerBoundInFileFrom(file, header, candidate, base_index + 1);
                continue;
            }
            id_index += 1;
            while (id_index < ids_by_id.len and ids_by_id[id_index] < record.edge_id) {
                id_index += 1;
            }
            if (id_index >= ids_by_id.len) return false;
            if (ids_by_id[id_index] == record.edge_id) return true;
            base_index = try self.edgeIdLowerBoundInFileFrom(file, header, ids_by_id[id_index], base_index);
        }
        return false;
    }

    fn edgeIdRunSummaryMatchesFile(self: Store, file: std.Io.File, header: EdgeIndexHeader, summary: EdgeSegmentIdRunSummary) !bool {
        try summary.validate();
        if (try denseEdgeIdRunSummaryForHeader(header)) |expected| {
            if (try self.regularFileSize(file) != try edgeIndexFileSizeForHeader(header)) return error.InvalidRecord;
            return edgeSegmentIdRunSummariesEqual(summary, expected);
        }
        if (header.edge_count == 0) return summary.run_count == 0;
        if (summary.run_count == 0) return false;
        const covered_count = try summary.coveredCount();
        if (covered_count != header.edge_count) return false;
        const first = try self.readEdgeIndexRecordAt(file, header, 0);
        if (first.edge_id != summary.first_min) return false;
        if (summary.run_count == 1) {
            const last = try self.readEdgeIndexRecordAt(file, header, header.edge_count - 1);
            return last.edge_id == summary.first_max;
        }
        const first_len = std.math.add(u64, summary.first_max - summary.first_min, 1) catch return error.InvalidRecord;
        const first_last = try self.readEdgeIndexRecordAt(file, header, first_len - 1);
        if (first_last.edge_id != summary.first_max) return false;
        const second_first = try self.readEdgeIndexRecordAt(file, header, first_len);
        if (second_first.edge_id != summary.second_min) return false;
        const last = try self.readEdgeIndexRecordAt(file, header, header.edge_count - 1);
        return last.edge_id == summary.second_max;
    }

    fn edgeIdLowerBoundInFileFrom(self: Store, file: std.Io.File, header: EdgeIndexHeader, id: u64, start: u64) !u64 {
        if (start > header.edge_count) return error.InvalidRecord;
        var lo: u64 = start;
        var hi: u64 = header.edge_count;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            const record = try self.readEdgeIndexRecordAt(file, header, mid);
            if (record.edge_id < id) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    fn extendNodeByIdIndex(self: Store, file: std.Io.File, old_max_id: u64, new_max_id: u64) !void {
        if (new_max_id <= old_max_id) return;
        const header = try self.readNodeByIdHeaderFromFile(file);
        try file.setLength(self.io, try self.nodeByIdFileSizeForHeaderStore(.{
            .max_node_id = new_max_id,
            .node_count = header.node_count,
            .node_digest = header.node_digest,
            .flags = header.flags,
            .record_len = header.record_len,
            .uniform_kind = header.uniform_kind,
        }));
    }

    fn writeNodeByIdHeader(self: Store, file: std.Io.File, header: NodeByIdHeader) !void {
        try header.validateShape();
        var header_bytes: [NodeByIdHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
    }

    fn writeNodeByIdRecordAt(self: Store, file: std.Io.File, header: NodeByIdHeader, record: NodeByIdRecord) !void {
        var record_bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
        const encoded = record_bytes[0..header.record_len];
        try record.encodeForHeader(header, encoded);
        try file.writePositionalAll(self.io, encoded, try nodeByIdRecordOffsetForHeader(header, record.id));
    }

    fn writeEdgeIndexRecordAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, index: u64, record: EdgeIndexRecord) !void {
        if (header.hasKeyRuns()) return error.InvalidRecord;
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        const encoded = record_bytes[0..header.record_len];
        try record.encodeForHeader(header, index, null, encoded);
        try file.writePositionalAll(self.io, encoded, try edgeIndexRecordOffsetForHeader(header, index));
    }

    fn compactEdgeIndexToDerivedRecords(self: Store, file: std.Io.File, header: *EdgeIndexHeader) !void {
        if (header.hasKeyRuns()) return;
        var dense_id = header.order == .id;
        var u32_node_ids = header.edge_count != 0;
        var u32_edge_ids = header.order != .id and header.edge_count != 0;
        var rel_counts: [edge_index_rel_kind_count]u64 = [_]u64{0} ** edge_index_rel_kind_count;
        {
            var reader = try ExplicitEdgeIndexSequentialReader.init(self.allocator, self.io, file, header.*);
            defer reader.deinit();
            var check_pos: u64 = 0;
            while (try reader.next()) |record| : (check_pos += 1) {
                if (dense_id) {
                    const expected_edge_id = std.math.add(u64, check_pos, 1) catch return error.InvalidRecord;
                    if (record.edge_id != expected_edge_id) dense_id = false;
                }
                if (u32_node_ids and !edgeRecordHasU32NodeIds(record)) u32_node_ids = false;
                if (u32_edge_ids and !edgeRecordHasU32EdgeId(record)) u32_edge_ids = false;
                const rel_kind = relKindFromInt(record.rel) orelse return error.InvalidRecord;
                rel_counts[@intFromEnum(rel_kind)] += 1;
            }
            if (check_pos != header.edge_count) return error.InvalidRecord;
        }
        var rel_derivation: ?EdgeIndexRelDerivation = null;
        if (edgeIndexDefaultRelFromCounts(rel_counts, header.edge_count)) |default_rel| {
            var derivation = EdgeIndexRelDerivation{ .default_rel = default_rel };
            var reader = try ExplicitEdgeIndexSequentialReader.init(self.allocator, self.io, file, header.*);
            defer reader.deinit();
            while (try reader.next()) |record| {
                if (record.rel != default_rel and !edgeIndexRelDerivationAddException(&derivation, record.edge_id, record.rel)) {
                    derivation.exception_count = std.math.maxInt(u8);
                    break;
                }
            }
            if (derivation.exception_count <= derivation.exception_edge_ids.len) rel_derivation = derivation;
        }
        const derived_header = EdgeIndexHeader.withShape(header.order, header.edge_count, header.edge_digest, header.order_digest, dense_id, u32_node_ids, u32_edge_ids, rel_derivation);
        if (!(derived_header.record_len == header.record_len and derived_header.flags == header.flags and derived_header.default_rel == header.default_rel and derived_header.rel_exception_count == header.rel_exception_count and std.mem.eql(u64, &derived_header.rel_exception_edge_ids, &header.rel_exception_edge_ids) and std.mem.eql(u16, &derived_header.rel_exception_rels, &header.rel_exception_rels))) {
            var reader = try ExplicitEdgeIndexSequentialReader.init(self.allocator, self.io, file, header.*);
            defer reader.deinit();
            var writer = try StorageBufferedWriter.initAtOffset(
                self.allocator,
                self.io,
                file,
                storage_write_buffer_bytes,
                EdgeIndexHeader.encoded_len,
            );
            defer writer.deinit();
            var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
            var pos: u64 = 0;
            while (try reader.next()) |record| : (pos += 1) {
                const encoded = record_bytes[0..derived_header.record_len];
                try record.encodeForHeader(derived_header, pos, null, encoded);
                try writer.append(encoded);
            }
            if (pos != header.edge_count) return error.InvalidRecord;
            try writer.flush();
            if (try writer.position() != try edgeIndexFileSizeForHeader(derived_header)) return error.InvalidRecord;
            try file.setLength(self.io, try edgeIndexFileSizeForHeader(derived_header));
            var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
            derived_header.encode(&header_bytes);
            try file.writePositionalAll(self.io, &header_bytes, 0);
            header.* = derived_header;
        }

        if (try self.compactIdEdgeIndexToEndpointRuns(file, header)) return;
        if (try self.compactSecondaryEdgeIndexToDenseKeyRuns(file, header)) return;
    }

    fn compactIdEdgeIndexToEndpointRuns(self: Store, file: std.Io.File, header: *EdgeIndexHeader) !bool {
        if (header.order != .id or !header.hasDenseId() or !header.hasU32NodeIds() or !header.hasDerivedRel() or header.hasKeyRuns() or header.edge_count == 0) return false;

        const expected_size = try edgeIndexFileSizeForHeader(header.*);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        var map = openReadOnlyMemoryMap(self.io, file, expected_size) catch null;
        defer if (map) |*mapped| mapped.destroy(self.io);

        var runs = std.ArrayList(EdgeIndexKeyRunRecord).empty;
        defer runs.deinit(self.allocator);

        var pos: u64 = 0;
        while (pos < header.edge_count) {
            const first = if (map) |*mapped|
                try readEdgeIndexRecordFromMap(header.*, mapped, pos)
            else
                try self.readEdgeIndexRecordAt(file, header.*, pos);
            if (!edgeIndexIdEndpointCanStartRun(first)) return false;
            if (runs.items.len >= edge_index_repair_key_run_memory_cap / 12) return false;
            try runs.append(self.allocator, .{
                .key = first.src,
                .start = pos,
                .opposite = first.dst,
            });

            pos += 1;
            var previous = first;
            while (pos < header.edge_count) : (pos += 1) {
                const record = if (map) |*mapped|
                    try readEdgeIndexRecordFromMap(header.*, mapped, pos)
                else
                    try self.readEdgeIndexRecordAt(file, header.*, pos);
                if (!edgeIndexIdEndpointCanStartRun(record)) return false;
                const expected_src = std.math.add(u64, previous.src, 1) catch break;
                const expected_dst = std.math.add(u64, previous.dst, 1) catch break;
                if (record.src != expected_src or record.dst != expected_dst) break;
                previous = record;
            }
        }
        if (runs.items.len == 0 or runs.items.len > std.math.maxInt(u32)) return false;

        const key_run_header = header.withKeyRuns(@intCast(runs.items.len), true, false);
        if (key_run_header.record_len != 0) return false;
        const next_size = try edgeIndexFileSizeForHeader(key_run_header);
        if (next_size >= try edgeIndexFileSizeForHeader(header.*)) return false;

        if (map) |*mapped| {
            mapped.destroy(self.io);
            map = null;
        }

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        key_run_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        var run_bytes: [40]u8 = undefined;
        var offset: u64 = EdgeIndexHeader.encoded_len;
        for (runs.items) |run| {
            const encoded = run_bytes[0..edgeIndexKeyRunRecordLen(key_run_header)];
            try run.encodeForHeader(key_run_header, encoded);
            try file.writePositionalAll(self.io, encoded, offset);
            offset += encoded.len;
        }
        try file.setLength(self.io, next_size);
        header.* = key_run_header;
        return true;
    }

    fn compactSecondaryEdgeIndexToDenseKeyRuns(self: Store, file: std.Io.File, header: *EdgeIndexHeader) !bool {
        if (header.order == .id or !header.hasU32NodeIds() or !header.hasU32EdgeIds() or !header.hasDerivedRel() or header.hasKeyRuns() or header.edge_count == 0) return false;
        if (header.edge_count > std.math.maxInt(u32)) return false;
        if (try self.compactSecondaryEdgeIndexToPartialDenseKeyRuns(file, header)) return true;

        const expected_size = try edgeIndexFileSizeForHeader(header.*);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        var map = openReadOnlyMemoryMap(self.io, file, expected_size) catch null;
        defer if (map) |*mapped| mapped.destroy(self.io);

        var first_run: EdgeIndexKeyRunRecord = undefined;
        var previous_run: EdgeIndexKeyRunRecord = undefined;
        var current_key: u64 = 0;
        var current_opposite: u64 = 0;
        var current_start: u64 = 0;
        var current_edge_id_base: u64 = 0;
        var current_edge_id_step: u64 = 0;
        var current_len: u64 = 0;
        var run_count: u64 = 0;
        var start_step: u64 = 0;
        var edge_id_base_step: u64 = 0;
        var uniform_edge_id_step: u64 = 0;
        var first_opposite: u64 = 0;

        const FinishRun = struct {
            fn finish(
                order: EdgeIndexOrder,
                run_count_ptr: *u64,
                first_run_ptr: *EdgeIndexKeyRunRecord,
                previous_run_ptr: *EdgeIndexKeyRunRecord,
                start_step_ptr: *u64,
                edge_id_base_step_ptr: *u64,
                uniform_edge_id_step_ptr: *u64,
                first_opposite_ptr: *u64,
                key: u64,
                opposite: u64,
                start: u64,
                edge_id_base: u64,
                edge_id_step: u64,
                len: u64,
            ) !bool {
                if (key == 0 or key > std.math.maxInt(u32)) return false;
                if (opposite == 0 or opposite > std.math.maxInt(u32)) return false;
                if (edge_id_base == 0 or edge_id_base > std.math.maxInt(u32)) return false;
                if (start > std.math.maxInt(u32)) return false;
                if (len == 0) return false;
                if (len > 1) {
                    if (edge_id_step == 0 or edge_id_step > std.math.maxInt(u32)) return false;
                    if (uniform_edge_id_step_ptr.* == 0) {
                        uniform_edge_id_step_ptr.* = edge_id_step;
                    } else if (uniform_edge_id_step_ptr.* != edge_id_step) {
                        return false;
                    }
                }

                const run = EdgeIndexKeyRunRecord{
                    .key = key,
                    .start = start,
                    .opposite = opposite,
                    .edge_id_base = edge_id_base,
                    .edge_id_step = edge_id_step,
                };
                if (run_count_ptr.* == 0) {
                    if (key != 1) return false;
                    first_run_ptr.* = run;
                    first_opposite_ptr.* = opposite;
                } else {
                    if (key != previous_run_ptr.key + 1) return false;
                    if (start <= previous_run_ptr.start or edge_id_base <= previous_run_ptr.edge_id_base) return false;
                    const next_start_step = start - previous_run_ptr.start;
                    const next_edge_base_step = edge_id_base - previous_run_ptr.edge_id_base;
                    if (run_count_ptr.* == 1) {
                        start_step_ptr.* = next_start_step;
                        edge_id_base_step_ptr.* = next_edge_base_step;
                    } else if (start_step_ptr.* != next_start_step or edge_id_base_step_ptr.* != next_edge_base_step) {
                        return false;
                    }
                    switch (order) {
                        .id => return false,
                        .src => if (previous_run_ptr.opposite != previous_run_ptr.key + 1) return false,
                        .dst => if (run.opposite != run.key - 1) return false,
                    }
                }
                previous_run_ptr.* = run;
                run_count_ptr.* += 1;
                return true;
            }
        };

        var pos: u64 = 0;
        while (pos < header.edge_count) : (pos += 1) {
            const record = if (map) |*mapped|
                try readEdgeIndexRecordFromMap(header.*, mapped, pos)
            else
                try self.readEdgeIndexRecordAt(file, header.*, pos);
            if (!edgeRecordHasU32NodeIds(record) or !edgeRecordHasU32EdgeId(record)) return false;
            const key = edgeIndexRecordKey(record, header.order);
            const opposite = edgeIndexRecordOpposite(record, header.order) orelse return false;
            if (current_len == 0) {
                current_key = key;
                current_opposite = opposite;
                current_start = pos;
                current_edge_id_base = record.edge_id;
                current_edge_id_step = 0;
                current_len = 1;
                continue;
            }
            if (key != current_key) {
                if (!try FinishRun.finish(header.order, &run_count, &first_run, &previous_run, &start_step, &edge_id_base_step, &uniform_edge_id_step, &first_opposite, current_key, current_opposite, current_start, current_edge_id_base, current_edge_id_step, current_len)) return false;
                current_key = key;
                current_opposite = opposite;
                current_start = pos;
                current_edge_id_base = record.edge_id;
                current_edge_id_step = 0;
                current_len = 1;
                continue;
            }
            if (opposite != current_opposite) return false;
            if (current_len == 1) {
                if (record.edge_id <= current_edge_id_base) return false;
                current_edge_id_step = record.edge_id - current_edge_id_base;
            } else {
                const expected_delta = std.math.mul(u64, current_len, current_edge_id_step) catch return false;
                const expected = std.math.add(u64, current_edge_id_base, expected_delta) catch return false;
                if (record.edge_id != expected) return false;
            }
            current_len += 1;
        }
        if (current_len == 0) return false;
        if (!try FinishRun.finish(header.order, &run_count, &first_run, &previous_run, &start_step, &edge_id_base_step, &uniform_edge_id_step, &first_opposite, current_key, current_opposite, current_start, current_edge_id_base, current_edge_id_step, current_len)) return false;
        if (run_count < 2 or run_count > std.math.maxInt(u32)) return false;
        if (uniform_edge_id_step == 0 or start_step == 0 or edge_id_base_step == 0) return false;
        switch (header.order) {
            .id => return false,
            .src => if (previous_run.opposite != 1) return false,
            .dst => if (first_opposite != previous_run.key) return false,
        }

        const dense = EdgeIndexDenseKeyRunSpan{
            .run_start = 0,
            .count = run_count,
            .key_base = first_run.key,
            .start_base = first_run.start,
            .start_step = start_step,
            .edge_id_base = first_run.edge_id_base,
            .edge_id_base_step = edge_id_base_step,
        };
        const key_run_header = header
            .withKeyRuns(@intCast(run_count), true, true)
            .withKeyRunRingOpposite(previous_run.key)
            .withKeyRunUniformEdgeIdStep(uniform_edge_id_step)
            .withKeyRunDenseSpan(dense);
        if (key_run_header.record_len != 0) return false;
        const next_size = try edgeIndexFileSizeForHeader(key_run_header);
        if (next_size >= try edgeIndexFileSizeForHeader(header.*)) return false;

        if (map) |*mapped| {
            mapped.destroy(self.io);
            map = null;
        }

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        key_run_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        try file.setLength(self.io, next_size);
        header.* = key_run_header;
        return true;
    }

    const SecondaryRepairKeyRun = struct {
        run: EdgeIndexKeyRunRecord,
        next_pos: u64,
    };

    fn readSecondaryRepairKeyRunAt(self: Store, file: std.Io.File, header: EdgeIndexHeader, start: u64) !?SecondaryRepairKeyRun {
        if (header.order == .id or start >= header.edge_count) return null;
        const first = try self.readEdgeIndexRecordAt(file, header, start);
        if (!edgeRecordHasU32NodeIds(first) or !edgeRecordHasU32EdgeId(first)) return null;
        const key = edgeIndexRecordKey(first, header.order);
        const opposite = edgeIndexRecordOpposite(first, header.order) orelse return null;
        if (key == 0 or key > std.math.maxInt(u32)) return null;
        if (opposite == 0 or opposite > std.math.maxInt(u32)) return null;
        var step: u64 = 0;
        var len: u64 = 1;
        var pos = start + 1;
        while (pos < header.edge_count) : (pos += 1) {
            const record = try self.readEdgeIndexRecordAt(file, header, pos);
            if (!edgeRecordHasU32NodeIds(record) or !edgeRecordHasU32EdgeId(record)) return null;
            if (edgeIndexRecordKey(record, header.order) != key) break;
            const record_opposite = edgeIndexRecordOpposite(record, header.order) orelse return null;
            if (record_opposite != opposite) break;
            if (len == 1) {
                if (record.edge_id <= first.edge_id) break;
                step = record.edge_id - first.edge_id;
                if (step > std.math.maxInt(u32)) return null;
            } else {
                const expected_delta = std.math.mul(u64, len, step) catch return null;
                const expected = std.math.add(u64, first.edge_id, expected_delta) catch return null;
                if (record.edge_id != expected) break;
            }
            len += 1;
        }
        return .{
            .run = .{
                .key = key,
                .start = start,
                .opposite = opposite,
                .edge_id_base = first.edge_id,
                .edge_id_step = step,
            },
            .next_pos = pos,
        };
    }

    fn readSecondaryRepairKeyRunFromMap(header: EdgeIndexHeader, map: *const std.Io.File.MemoryMap, start: u64) !?SecondaryRepairKeyRun {
        if (header.order == .id or start >= header.edge_count) return null;
        const first = try readEdgeIndexRecordFromMap(header, map, start);
        if (!edgeRecordHasU32NodeIds(first) or !edgeRecordHasU32EdgeId(first)) return null;
        const key = edgeIndexRecordKey(first, header.order);
        const opposite = edgeIndexRecordOpposite(first, header.order) orelse return null;
        if (key == 0 or key > std.math.maxInt(u32)) return null;
        if (opposite == 0 or opposite > std.math.maxInt(u32)) return null;
        var step: u64 = 0;
        var len: u64 = 1;
        var pos = start + 1;
        while (pos < header.edge_count) : (pos += 1) {
            const record = try readEdgeIndexRecordFromMap(header, map, pos);
            if (!edgeRecordHasU32NodeIds(record) or !edgeRecordHasU32EdgeId(record)) return null;
            if (edgeIndexRecordKey(record, header.order) != key) break;
            const record_opposite = edgeIndexRecordOpposite(record, header.order) orelse return null;
            if (record_opposite != opposite) break;
            if (len == 1) {
                if (record.edge_id <= first.edge_id) break;
                step = record.edge_id - first.edge_id;
                if (step > std.math.maxInt(u32)) return null;
            } else {
                const expected_delta = std.math.mul(u64, len, step) catch return null;
                const expected = std.math.add(u64, first.edge_id, expected_delta) catch return null;
                if (record.edge_id != expected) break;
            }
            len += 1;
        }
        return .{
            .run = .{
                .key = key,
                .start = start,
                .opposite = opposite,
                .edge_id_base = first.edge_id,
                .edge_id_step = step,
            },
            .next_pos = pos,
        };
    }

    fn compactSecondaryEdgeIndexToPartialDenseKeyRuns(self: Store, file: std.Io.File, header: *EdgeIndexHeader) !bool {
        const expected_size = try edgeIndexFileSizeForHeader(header.*);
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        var map = openReadOnlyMemoryMap(self.io, file, expected_size) catch null;
        defer if (map) |*mapped| mapped.destroy(self.io);

        var uniform_step: u64 = 0;
        var max_key: u64 = 0;
        var run_count: u64 = 0;
        var best: ?EdgeIndexDenseKeyRunSpan = null;
        var best_score: u64 = 0;
        var span_start_index: u64 = 0;
        var span_start: EdgeIndexKeyRunRecord = undefined;
        var previous: EdgeIndexKeyRunRecord = undefined;
        var span_count: u64 = 0;
        var start_step: u64 = 0;
        var edge_id_base_step: u64 = 0;

        var pos: u64 = 0;
        while (pos < header.edge_count) {
            const scanned = (if (map) |*mapped|
                try readSecondaryRepairKeyRunFromMap(header.*, mapped, pos)
            else
                try self.readSecondaryRepairKeyRunAt(file, header.*, pos)) orelse return false;
            const run = scanned.run;
            if (run.key > max_key) max_key = run.key;
            if (run.edge_id_base == 0 or run.edge_id_base > std.math.maxInt(u32)) return false;
            if (run.edge_id_step != 0) {
                if (uniform_step == 0) {
                    uniform_step = run.edge_id_step;
                } else if (uniform_step != run.edge_id_step) {
                    return false;
                }
            }

            const eligible = uniform_step != 0 and run.edge_id_step == uniform_step;
            if (eligible and span_count != 0) {
                const continues = run.key == previous.key + 1 and
                    run.start > previous.start and
                    run.edge_id_base > previous.edge_id_base;
                if (continues) {
                    const next_start_step = run.start - previous.start;
                    const next_edge_base_step = run.edge_id_base - previous.edge_id_base;
                    if (span_count == 1) {
                        start_step = next_start_step;
                        edge_id_base_step = next_edge_base_step;
                        span_count = 2;
                    } else if (next_start_step == start_step and next_edge_base_step == edge_id_base_step) {
                        span_count += 1;
                    } else {
                        best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                        span_start_index = run_count;
                        span_start = run;
                        start_step = 0;
                        edge_id_base_step = 0;
                        span_count = 1;
                    }
                } else {
                    best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                    span_start_index = run_count;
                    span_start = run;
                    start_step = 0;
                    edge_id_base_step = 0;
                    span_count = 1;
                }
            } else if (eligible) {
                best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                span_start_index = run_count;
                span_start = run;
                start_step = 0;
                edge_id_base_step = 0;
                span_count = 1;
            } else {
                best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                span_count = 0;
                start_step = 0;
                edge_id_base_step = 0;
            }

            previous = run;
            run_count += 1;
            pos = scanned.next_pos;
        }
        best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
        const dense = best orelse return false;
        if (run_count == 0 or run_count > std.math.maxInt(u32) or max_key < 2 or max_key > std.math.maxInt(u32)) return false;
        if (uniform_step == 0) return false;

        const key_run_header = header
            .withKeyRuns(@intCast(run_count), true, true)
            .withKeyRunRingOpposite(max_key)
            .withKeyRunUniformEdgeIdStep(uniform_step)
            .withKeyRunDenseSpan(dense);
        if (key_run_header.record_len != 0) return false;
        const next_size = try edgeIndexFileSizeForHeader(key_run_header);
        if (next_size >= try edgeIndexFileSizeForHeader(header.*)) return false;
        const explicit_bytes = try edgeIndexKeyRunDirectorySizeForHeader(key_run_header);
        if (explicit_bytes > edge_index_repair_key_run_memory_cap) return false;

        var explicit_runs = std.ArrayList(EdgeIndexKeyRunRecord).empty;
        defer explicit_runs.deinit(self.allocator);
        try explicit_runs.ensureTotalCapacityPrecise(self.allocator, @intCast(explicit_bytes / edgeIndexKeyRunRecordLen(key_run_header)));

        const dense_end = dense.run_start + dense.count;
        pos = 0;
        var run_index: u64 = 0;
        while (pos < header.edge_count) : (run_index += 1) {
            const scanned = (if (map) |*mapped|
                try readSecondaryRepairKeyRunFromMap(header.*, mapped, pos)
            else
                try self.readSecondaryRepairKeyRunAt(file, header.*, pos)) orelse return false;
            const run = scanned.run;
            if (run_index >= dense.run_start and run_index < dense_end) {
                const expected = try edgeIndexDenseKeyRunSpanRecordForIndex(key_run_header, run_index);
                if (!edgeIndexKeyRunRecordsEquivalent(key_run_header, expected, run)) return false;
            } else {
                try explicit_runs.append(self.allocator, run);
            }
            pos = scanned.next_pos;
        }
        if (run_index != run_count) return false;

        if (map) |*mapped| {
            mapped.destroy(self.io);
            map = null;
        }

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        key_run_header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        var run_bytes: [40]u8 = undefined;
        var write_offset: u64 = EdgeIndexHeader.encoded_len;
        for (explicit_runs.items) |run| {
            const encoded = run_bytes[0..edgeIndexKeyRunRecordLen(key_run_header)];
            try run.encodeForHeader(key_run_header, encoded);
            try file.writePositionalAll(self.io, encoded, write_offset);
            write_offset += encoded.len;
        }
        try file.setLength(self.io, next_size);
        header.* = key_run_header;
        return true;
    }

    fn edgeIndexHeaderForTail(order: EdgeIndexOrder, old_header: EdgeIndexHeader, next_count: u64, edge_digest: u64, order_digest: u64, tail_records: []const EdgeIndexRecord) EdgeIndexHeader {
        const dense_id = order == .id and (old_header.edge_count == 0 or old_header.hasDenseId()) and edgeRecordsAreDenseIdTail(old_header.edge_count, tail_records);
        const u32_node_ids = tail_records.len != 0 and (old_header.edge_count == 0 or old_header.hasU32NodeIds()) and edgeRecordsHaveU32NodeIds(tail_records);
        const u32_edge_ids = !dense_id and tail_records.len != 0 and (old_header.edge_count == 0 or old_header.hasU32EdgeIds()) and edgeRecordsHaveU32EdgeIds(tail_records);
        const rel_derivation = if (old_header.edge_count == 0)
            edgeRecordsDerivedRel(tail_records)
        else
            edgeRecordsExtendDerivedRel(old_header, tail_records);
        const header = EdgeIndexHeader.withShape(order, next_count, edge_digest, order_digest, dense_id, u32_node_ids, u32_edge_ids, rel_derivation);
        if (old_header.edge_count == 0) return edgeIndexHeaderWithBeneficialKeyRuns(order, header, tail_records);
        return header;
    }

    fn edgeIndexHeaderForCompleteRecords(order: EdgeIndexOrder, records: []const EdgeIndexRecord, edge_digest: u64, order_digest: u64) EdgeIndexHeader {
        const count: u64 = @intCast(records.len);
        const dense_id = order == .id and edgeRecordsAreDenseIdTail(0, records);
        const header = EdgeIndexHeader.withShape(order, count, edge_digest, order_digest, dense_id, edgeRecordsHaveU32NodeIds(records), !dense_id and edgeRecordsHaveU32EdgeIds(records), edgeRecordsDerivedRel(records));
        return edgeIndexHeaderWithBeneficialKeyRuns(order, header, records);
    }

    fn edgeIndexHeaderForSingleFullRewrite(order: EdgeIndexOrder, next_count: u64, edge_digest: u64, order_digest: u64, old_header: EdgeIndexHeader, inserted: EdgeIndexRecord) EdgeIndexHeader {
        const rel_derivation = edgeRecordsExtendDerivedRel(old_header, &.{inserted});
        return EdgeIndexHeader.withShape(order, next_count, edge_digest, order_digest, false, old_header.hasU32NodeIds() and edgeRecordHasU32NodeIds(inserted), old_header.hasU32EdgeIds() and edgeRecordHasU32EdgeId(inserted), rel_derivation);
    }

    fn edgeIndexHeaderWithoutRecord(order: EdgeIndexOrder, next_count: u64, edge_digest: u64, order_digest: u64, old_header: EdgeIndexHeader, removed: EdgeIndexRecord) EdgeIndexHeader {
        const dense_id = order == .id and old_header.hasDenseId() and removed.edge_id == old_header.edge_count;
        const rel_derivation = edgeIndexRelDerivationWithoutRecord(old_header, removed, next_count);
        return EdgeIndexHeader.withShape(order, next_count, edge_digest, order_digest, dense_id, next_count != 0 and old_header.hasU32NodeIds(), !dense_id and next_count != 0 and old_header.hasU32EdgeIds(), rel_derivation);
    }

    fn writeEdgeIndexRecordToWriter(writer: *StorageBufferedWriter, header: EdgeIndexHeader, index: u64, record: EdgeIndexRecord) !void {
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        const encoded = record_bytes[0..header.record_len];
        try record.encodeForHeader(header, index, null, encoded);
        try writer.append(encoded);
    }

    fn writeEdgeIndexRunsToWriter(writer: *StorageBufferedWriter, header: EdgeIndexHeader, records: []const EdgeIndexRecord) !void {
        if (!header.hasKeyRuns()) return;
        var run_bytes: [40]u8 = undefined;
        var run_count: u32 = 0;
        var run_start: usize = 0;
        while (run_start < records.len) {
            const run = try edgeIndexRunRecordForStart(header, records, run_start);
            const dense_end = if (header.hasKeyRunDenseSpan())
                try std.math.add(u64, header.key_run_dense_run_start, header.key_run_dense_count)
            else
                0;
            if (header.hasKeyRunDenseSpan() and run_count >= header.key_run_dense_run_start and run_count < dense_end) {
                const expected = try edgeIndexDenseKeyRunSpanRecordForIndex(header, run_count);
                if (!edgeIndexKeyRunRecordsEquivalent(header, expected, run)) return error.InvalidRecord;
            } else {
                const encoded = run_bytes[0..edgeIndexKeyRunRecordLen(header)];
                try run.encodeForHeader(header, encoded);
                try writer.append(encoded);
            }
            run_count += 1;
            run_start = edgeIndexNextRunStartForHeaderShape(header, records, run_start) orelse return error.InvalidRecord;
        }
        if (run_count != header.key_run_count) return error.InvalidRecord;
    }

    fn writeCompleteEdgeIndexFile(self: Store, file: std.Io.File, header: EdgeIndexHeader, records: []const EdgeIndexRecord, expected_size: u64) !void {
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try writer.append(&header_bytes);
        try writeEdgeIndexRunsToWriter(&writer, header, records);
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        var current_run: ?EdgeIndexKeyRunRecord = null;
        var next_run_start: usize = 0;
        if (header.hasKeyRuns() and records.len != 0) {
            current_run = try edgeIndexRunRecordForStart(header, records, 0);
            next_run_start = edgeIndexNextRunStartForHeaderShape(header, records, 0) orelse return error.InvalidRecord;
        }
        for (records, 0..) |record, i| {
            if (header.hasKeyRuns()) {
                if (current_run) |run| {
                    if (i == next_run_start) {
                        const next_run = try edgeIndexRunRecordForStart(header, records, i);
                        if (i != 0) try validateAdjacentEdgeIndexKeyRuns(header, run, next_run);
                        current_run = next_run;
                        next_run_start = edgeIndexNextRunStartForHeaderShape(header, records, i) orelse return error.InvalidRecord;
                    }
                } else return error.InvalidRecord;
            }
            const encoded = record_bytes[0..header.record_len];
            try record.encodeForHeader(header, @intCast(i), current_run, encoded);
            try writer.append(encoded);
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
    }

    fn writeNodeTextIndexHeader(self: Store, file: std.Io.File, header: NodeTextIndexHeader) !void {
        try header.validateShape();
        var header_bytes: [NodeTextIndexHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
    }

    fn writeNodeTextIndexRecordToWriter(writer: *StorageBufferedWriter, header: NodeTextIndexHeader, record: NodeTextIndexRecord) !void {
        var record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        const encoded = record_bytes[0..header.record_len];
        try record.encodeForHeader(header, encoded);
        try writer.append(encoded);
    }

    fn writeNodeTextIndexRecordAt(self: Store, file: std.Io.File, header: NodeTextIndexHeader, index: u64, record: NodeTextIndexRecord) !void {
        var record_bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        const encoded = record_bytes[0..header.record_len];
        try record.encodeForHeader(header, encoded);
        try file.writePositionalAll(self.io, encoded, try nodeTextIndexRecordOffsetForHeader(header, index));
    }

    fn compactNodeTextIndexToDerivedRecords(self: Store, file: std.Io.File, header: *NodeTextIndexHeader) !void {
        if (header.node_count == 0) return;
        try header.validateShape();
        var texts = try NodeTextsView.open(self);
        defer texts.deinit();
        const node_file_opt = std.Io.Dir.cwd().openFile(self.io, self.node_by_id_path, .{}) catch |err| switch (err) {
            error.FileNotFound => null,
            else => |e| return e,
        };
        defer if (node_file_opt) |node_file| node_file.close(self.io);
        var node_header: NodeByIdHeader = undefined;
        var node_map: ?std.Io.File.MemoryMap = null;
        defer if (node_map) |*mapped| mapped.destroy(self.io);
        var derive_text_span = false;
        if (node_file_opt) |node_file| {
            node_header = self.readNodeByIdHeaderFromFile(node_file) catch NodeByIdHeader{ .node_count = 0, .max_node_id = 0 };
            const node_file_size = self.regularFileSize(node_file) catch 0;
            if (node_header.node_count != 0 and
                node_header.node_count == header.node_count and
                node_file_size == (self.nodeByIdFileSizeForHeaderStore(node_header) catch std.math.maxInt(u64)))
            {
                derive_text_span = true;
                node_map = openReadOnlyMemoryMap(self.io, node_file, node_file_size) catch null;
            }
        }
        var uniform_kind: ?u16 = null;
        var short_text_len = true;
        var u32_id = true;
        var text_hash_unique = true;
        var previous_hash_record: ?NodeTextIndexRecord = null;
        var pos: u64 = 0;
        while (pos < header.node_count) : (pos += 1) {
            const record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(file, header.*, pos, &texts);
            if (previous_hash_record) |prev| {
                if (prev.hash == record.hash) {
                    text_hash_unique = false;
                }
            }
            previous_hash_record = record;
            if (derive_text_span) {
                const node_file = node_file_opt orelse return error.InvalidRecord;
                const by_id = (if (node_map) |*mapped|
                    readNodeByIdRecordFromMap(node_header, mapped, record.id)
                else
                    self.readNodeByIdRecordAt(node_file, node_header, record.id)) catch {
                    derive_text_span = false;
                    continue;
                };
                if (by_id.id != record.id or
                    by_id.kind != record.kind or
                    by_id.text_offset != record.text_offset or
                    by_id.text_len != record.text_len)
                {
                    derive_text_span = false;
                }
            }
            if (pos == 0) {
                uniform_kind = record.kind;
            } else if (uniform_kind != null and uniform_kind.? != record.kind) {
                uniform_kind = null;
            }
            if (record.text_len > std.math.maxInt(u16)) short_text_len = false;
            if (record.id > std.math.maxInt(u32)) u32_id = false;
        }
        var derived_header = NodeTextIndexHeader.withShape(header.node_count, header.node_digest, header.order_digest, uniform_kind, short_text_len, u32_id, false, derive_text_span);
        derived_header.setTextHashUnique(text_hash_unique);
        if (derived_header.record_len == header.record_len and
            derived_header.flags == header.flags and
            derived_header.uniform_kind == header.uniform_kind) return;
        pos = 0;
        while (pos < header.node_count) : (pos += 1) {
            const record = try self.readNodeTextIndexRecordAtForHeaderWithTexts(file, header.*, pos, &texts);
            try self.writeNodeTextIndexRecordAt(file, derived_header, pos, record);
        }
        try file.setLength(self.io, try nodeTextIndexFileSizeForHeader(derived_header));
        try self.writeNodeTextIndexHeader(file, derived_header);
        header.* = derived_header;
    }

    const EdgeRepairRunReader = struct {
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        next_index: u64,
        count: u64,
        buffer: []u8 = &.{},
        file_offset: u64 = 0,
        cursor: usize = 0,
        len: usize = 0,

        fn deinit(self: *EdgeRepairRunReader, allocator: std.mem.Allocator, io: std.Io) void {
            allocator.free(self.buffer);
            if (self.map) |*map| map.destroy(io);
            self.file.close(io);
        }

        fn refill(self: *EdgeRepairRunReader, store: Store) !void {
            const n = try self.file.readPositionalAll(store.io, self.buffer, self.file_offset);
            if (n == 0) return error.InvalidRecord;
            self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
            self.cursor = 0;
            self.len = n;
        }

        fn readBytes(self: *EdgeRepairRunReader, store: Store, out: []u8) !void {
            var written: usize = 0;
            while (written < out.len) {
                if (self.cursor == self.len) try self.refill(store);
                const available = self.len - self.cursor;
                const n = @min(available, out.len - written);
                @memcpy(out[written .. written + n], self.buffer[self.cursor .. self.cursor + n]);
                self.cursor += n;
                written += n;
            }
        }

        fn next(self: *EdgeRepairRunReader, store: Store) !?EdgeIndexRecord {
            if (self.next_index >= self.count) return null;
            const record = if (self.map) |*map| record: {
                const offset = std.math.mul(u64, self.next_index, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
                const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
                const end = std.math.add(usize, start, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
                if (end > map.memory.len) return error.InvalidRecord;
                break :record try EdgeIndexRecord.decodeSlice(map.memory[start..end]);
            } else record: {
                if (self.cursor == self.len) try self.refill(store);
                if (self.len - self.cursor >= EdgeIndexRecord.encoded_len) {
                    const bytes = self.buffer[self.cursor .. self.cursor + EdgeIndexRecord.encoded_len];
                    self.cursor += EdgeIndexRecord.encoded_len;
                    break :record try EdgeIndexRecord.decodeSlice(bytes);
                }
                var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
                try self.readBytes(store, &bytes);
                break :record try EdgeIndexRecord.decode(&bytes);
            };
            self.next_index += 1;
            return record;
        }
    };

    const EdgeRepairRunHeapEntry = struct {
        run_index: usize,
        record: EdgeIndexRecord,
    };

    const EdgeRepairRunHeapContext = struct {
        order: EdgeIndexOrder,
    };

    fn compareEdgeRepairRunHeapEntry(context: EdgeRepairRunHeapContext, lhs: EdgeRepairRunHeapEntry, rhs: EdgeRepairRunHeapEntry) std.math.Order {
        if (edgeIndexLessThan(context.order, lhs.record, rhs.record)) return .lt;
        if (edgeIndexLessThan(context.order, rhs.record, lhs.record)) return .gt;
        return std.math.order(lhs.run_index, rhs.run_index);
    }

    fn deinitEdgeRepairRunPaths(self: Store, run_paths: *std.ArrayList([]u8)) void {
        for (run_paths.items) |run_path| {
            std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
            self.allocator.free(run_path);
        }
        run_paths.deinit(self.allocator);
    }

    fn appendEdgeRepairRunPath(
        self: Store,
        run_paths: *std.ArrayList([]u8),
        path: []const u8,
        order: EdgeIndexOrder,
        records: []const EdgeIndexRecord,
    ) !void {
        const run_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_run.{c}.{d}.tmp", .{ path, @intFromEnum(order), run_paths.items.len });
        var keep_run_path = false;
        errdefer if (!keep_run_path) {
            std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
            self.allocator.free(run_path);
        };
        try self.writeRepairEdgeRun(run_path, records);
        try run_paths.append(self.allocator, run_path);
        keep_run_path = true;
    }

    fn validateSortedRepairEdgeRecords(order: EdgeIndexOrder, records: []const EdgeIndexRecord) !void {
        var previous: ?EdgeIndexRecord = null;
        for (records) |record| {
            if (previous) |prev| {
                if (!edgeIndexLessThan(order, prev, record)) return error.InvalidRecord;
                if (order == .id and record.edge_id == prev.edge_id) return error.InvalidRecord;
            }
            previous = record;
        }
    }

    fn validateSortedRepairEdgeRecordOrder(order: EdgeIndexOrder, records: []const EdgeIndexRecord, record_order: []const u32) !void {
        if (records.len != record_order.len) return error.InvalidRecord;
        var previous: ?EdgeIndexRecord = null;
        for (record_order) |index| {
            if (index >= records.len) return error.InvalidRecord;
            const record = records[@intCast(index)];
            if (previous) |prev| {
                if (!edgeIndexLessThan(order, prev, record)) return error.InvalidRecord;
                if (order == .id and record.edge_id == prev.edge_id) return error.InvalidRecord;
            }
            previous = record;
        }
    }

    fn writeEdgeIndexesFromRepairSpool(self: Store, spool_path: []const u8, record_count: usize, timings: ?*PersistentRepairTimings) !void {
        if (record_count > edge_repair_sort_chunk_records) {
            // Large repairs are disk-bound. Build each order to completion before
            // starting the next one so only one order's run files coexist with the
            // repair spool and output temp file.
            const ring_shape = try self.detectDenseRingRepairSpoolShape(spool_path, record_count);
            const id_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            if (ring_shape) |shape| {
                if (!try self.writeDenseRingIdEdgeIndex(self.edge_by_id_path, shape)) {
                    try self.writeEdgeIndexFromRepairSpool(self.edge_by_id_path, .id, spool_path, record_count);
                }
            } else {
                try self.writeEdgeIndexFromRepairSpool(self.edge_by_id_path, .id, spool_path, record_count);
            }
            if (timings) |t| t.edge_id_index_ns += storageElapsedNs(self.io, id_start);
            const src_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            if (ring_shape) |shape| {
                if (!try self.writeDenseRingSecondaryEdgeIndex(self.edge_by_src_path, .src, shape)) {
                    try self.writeEdgeIndexFromRepairSpool(self.edge_by_src_path, .src, spool_path, record_count);
                }
            } else {
                try self.writeEdgeIndexFromRepairSpool(self.edge_by_src_path, .src, spool_path, record_count);
            }
            if (timings) |t| t.edge_src_index_ns += storageElapsedNs(self.io, src_start);
            const dst_start = if (timings != null) storageMonotonicNs(self.io) else 0;
            if (ring_shape) |shape| {
                if (!try self.writeDenseRingSecondaryEdgeIndex(self.edge_by_dst_path, .dst, shape)) {
                    try self.writeEdgeIndexFromRepairSpool(self.edge_by_dst_path, .dst, spool_path, record_count);
                }
            } else {
                try self.writeEdgeIndexFromRepairSpool(self.edge_by_dst_path, .dst, spool_path, record_count);
            }
            if (timings) |t| t.edge_dst_index_ns += storageElapsedNs(self.io, dst_start);
            return;
        }

        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var records = std.ArrayList(EdgeIndexRecord).empty;
        defer records.deinit(self.allocator);
        var sorted_records = std.ArrayList(EdgeIndexRecord).empty;
        defer sorted_records.deinit(self.allocator);
        try records.ensureTotalCapacityPrecise(self.allocator, record_count);
        try sorted_records.ensureTotalCapacityPrecise(self.allocator, record_count);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, record_count, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord);
        defer self.allocator.free(chunk_bytes);
        if (record_count != 0) {
            try self.readEdgeRepairSpoolChunk(spool_file, 0, record_count, chunk_bytes, &records);
        }

        const id_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        try self.writeSingleChunkRepairEdgeIndexFromScratch(self.edge_by_id_path, .id, records.items, &sorted_records);
        if (timings) |t| t.edge_id_index_ns += storageElapsedNs(self.io, id_start);
        const src_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        try self.writeSingleChunkRepairEdgeIndexFromScratch(self.edge_by_src_path, .src, records.items, &sorted_records);
        if (timings) |t| t.edge_src_index_ns += storageElapsedNs(self.io, src_start);
        const dst_start = if (timings != null) storageMonotonicNs(self.io) else 0;
        try self.writeSingleChunkRepairEdgeIndexFromScratch(self.edge_by_dst_path, .dst, records.items, &sorted_records);
        if (timings) |t| t.edge_dst_index_ns += storageElapsedNs(self.io, dst_start);
    }

    const DenseRingRepairSpoolShape = struct {
        edge_count: u64,
        ring_count: u64,
        node_mod: u64,
        edge_digest: u64,
        id_order_digest: u64,
        has_tail_fixture: bool,
    };

    const DenseRingSecondaryRun = struct {
        src: u64,
        dst: u64,
        edge_id_base: u64,
        len: u64,
        rel: u16,

        fn firstRecord(self: DenseRingSecondaryRun) EdgeIndexRecord {
            return .{
                .src = self.src,
                .dst = self.dst,
                .edge_id = self.edge_id_base,
                .rel = self.rel,
            };
        }

        fn key(self: DenseRingSecondaryRun, order: EdgeIndexOrder) u64 {
            return edgeIndexRecordKey(self.firstRecord(), order);
        }

        fn opposite(self: DenseRingSecondaryRun, order: EdgeIndexOrder) u64 {
            return edgeIndexRecordOpposite(self.firstRecord(), order) orelse 0;
        }
    };

    const DenseRingSecondaryDensePlan = struct {
        run_count: u64,
        dense: EdgeIndexDenseKeyRunSpan,
    };

    fn openEdgeRepairSpoolReader(self: Store, spool_path: []const u8, record_count: usize) !EdgeRepairRunReader {
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        var keep_file = false;
        errdefer if (!keep_file) spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var map = if (shouldMmapRepairSpool(expected_spool_size))
            openReadOnlyMemoryMap(self.io, spool_file, expected_spool_size) catch null
        else
            null;
        errdefer if (map) |*mapped| mapped.destroy(self.io);
        var buffer: []u8 = &.{};
        errdefer self.allocator.free(buffer);
        if (map == null) {
            buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(expected_spool_size));
        }

        const reader = EdgeRepairRunReader{
            .file = spool_file,
            .map = map,
            .next_index = 0,
            .count = @intCast(record_count),
            .buffer = buffer,
        };
        keep_file = true;
        map = null;
        buffer = &.{};
        return reader;
    }

    fn shouldMmapRepairSpool(file_size: u64) bool {
        return file_size <= repair_spool_mmap_max_bytes;
    }

    fn detectDenseRingRepairSpoolShape(self: Store, spool_path: []const u8, record_count: usize) !?DenseRingRepairSpoolShape {
        if (record_count == 0 or record_count > std.math.maxInt(u32)) return null;

        var reader = try self.openEdgeRepairSpoolReader(spool_path, record_count);
        defer reader.deinit(self.allocator, self.io);

        var digest = EdgeIndexDigest{};
        var max_endpoint: u64 = 0;
        var previous: ?EdgeIndexRecord = null;
        var last: ?EdgeIndexRecord = null;
        var pos: u64 = 0;
        while (try reader.next(self)) |record| : (pos += 1) {
            const expected_edge_id = pos + 1;
            if (record.edge_id != expected_edge_id) return null;
            if (!edgeRecordHasU32NodeIds(record)) return null;
            max_endpoint = @max(max_endpoint, @max(record.src, record.dst));
            digest.add(record);
            previous = last;
            last = record;
        }
        if (pos != record_count) return error.InvalidRecord;
        if (max_endpoint < 2 or max_endpoint > std.math.maxInt(u32)) return null;

        const edge_count: u64 = @intCast(record_count);
        const depends_rel: u16 = @intFromEnum(core.RelKind.depends_on);
        const has_tail_fixture = if (previous) |prev|
            if (last) |tail|
                prev.edge_id == edge_count - 1 and
                    prev.src == 1 and prev.dst == 2 and prev.rel == depends_rel and
                    tail.edge_id == edge_count and tail.src == 2 and tail.dst == 3 and tail.rel == depends_rel
            else
                false
        else
            false;
        const ring_count = if (has_tail_fixture) edge_count - 2 else edge_count;
        if (ring_count < max_endpoint) return null;

        var verify_reader = try self.openEdgeRepairSpoolReader(spool_path, record_count);
        defer verify_reader.deinit(self.allocator, self.io);
        const mentions_rel: u16 = @intFromEnum(core.RelKind.mentions);
        pos = 0;
        while (try verify_reader.next(self)) |record| : (pos += 1) {
            const edge_id = pos + 1;
            if (edge_id <= ring_count) {
                const expected_src = ((edge_id - 1) % max_endpoint) + 1;
                const expected_dst = (edge_id % max_endpoint) + 1;
                if (record.src != expected_src or record.dst != expected_dst or record.rel != mentions_rel) return null;
            } else if (edge_id == edge_count - 1) {
                if (record.src != 1 or record.dst != 2 or record.rel != depends_rel) return null;
            } else if (edge_id == edge_count) {
                if (record.src != 2 or record.dst != 3 or record.rel != depends_rel) return null;
            } else {
                return null;
            }
        }

        return .{
            .edge_count = edge_count,
            .ring_count = ring_count,
            .node_mod = max_endpoint,
            .edge_digest = digest.digest,
            .id_order_digest = digest.order_digest,
            .has_tail_fixture = has_tail_fixture,
        };
    }

    fn denseRingIdRunCount(shape: DenseRingRepairSpoolShape) ?u32 {
        if (shape.edge_count == 0 or shape.node_mod < 2 or shape.edge_count > std.math.maxInt(u32) or shape.node_mod > std.math.maxInt(u32)) return null;
        var run_count: u64 = 0;
        var pos: u64 = 0;
        while (pos < shape.ring_count) {
            const edge_id = pos + 1;
            const src = ((edge_id - 1) % shape.node_mod) + 1;
            const len = if (src == shape.node_mod)
                1
            else
                @min(shape.node_mod - src, shape.ring_count - pos);
            if (len == 0) return null;
            run_count = std.math.add(u64, run_count, 1) catch return null;
            pos = std.math.add(u64, pos, len) catch return null;
        }
        if (shape.has_tail_fixture) {
            run_count = std.math.add(u64, run_count, 2) catch return null;
        }
        if (run_count == 0 or run_count > std.math.maxInt(u32)) return null;
        const probe_header = denseRingIdHeader(shape, @intCast(run_count));
        if (probe_header.record_len != 0) return null;
        const run_bytes = std.math.mul(u64, run_count, edgeIndexKeyRunRecordLen(probe_header)) catch return null;
        if (run_bytes > edge_index_repair_key_run_memory_cap) return null;
        return @intCast(run_count);
    }

    fn denseRingIdHeader(shape: DenseRingRepairSpoolShape, run_count: u32) EdgeIndexHeader {
        return EdgeIndexHeader.withShape(
            .id,
            shape.edge_count,
            shape.edge_digest,
            shape.id_order_digest,
            true,
            true,
            false,
            denseRingRelDerivation(shape),
        ).withKeyRuns(run_count, true, false);
    }

    fn writeDenseRingIdRun(writer: *StorageBufferedWriter, header: EdgeIndexHeader, previous: *?EdgeIndexKeyRunRecord, run: EdgeIndexKeyRunRecord) !void {
        if (previous.*) |prev| try validateAdjacentEdgeIndexKeyRuns(header, prev, run);
        var run_bytes: [40]u8 = undefined;
        const encoded = run_bytes[0..edgeIndexKeyRunRecordLen(header)];
        try run.encodeForHeader(header, encoded);
        try writer.append(encoded);
        previous.* = run;
    }

    fn writeDenseRingIdEdgeIndex(self: Store, path: []const u8, shape: DenseRingRepairSpoolShape) !bool {
        const run_count = denseRingIdRunCount(shape) orelse return false;
        const header = denseRingIdHeader(shape, run_count);
        if (header.record_len != 0) return false;

        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        const expected_size = try edgeIndexFileSizeForHeader(header);
        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var previous: ?EdgeIndexKeyRunRecord = null;
        var written_runs: u32 = 0;
        var pos: u64 = 0;
        while (pos < shape.ring_count) {
            const edge_id = pos + 1;
            const src = ((edge_id - 1) % shape.node_mod) + 1;
            const dst = (edge_id % shape.node_mod) + 1;
            const len = if (src == shape.node_mod)
                1
            else
                @min(shape.node_mod - src, shape.ring_count - pos);
            if (len == 0) return error.InvalidRecord;
            try writeDenseRingIdRun(&writer, header, &previous, .{
                .key = src,
                .start = pos,
                .opposite = dst,
            });
            written_runs = std.math.add(u32, written_runs, 1) catch return error.InvalidRecord;
            pos = std.math.add(u64, pos, len) catch return error.InvalidRecord;
        }
        if (shape.has_tail_fixture) {
            try writeDenseRingIdRun(&writer, header, &previous, .{
                .key = 1,
                .start = shape.ring_count,
                .opposite = 2,
            });
            written_runs = std.math.add(u32, written_runs, 1) catch return error.InvalidRecord;
            const tail_second_start = std.math.add(u64, shape.ring_count, 1) catch return error.InvalidRecord;
            try writeDenseRingIdRun(&writer, header, &previous, .{
                .key = 2,
                .start = tail_second_start,
                .opposite = 3,
            });
            written_runs = std.math.add(u32, written_runs, 1) catch return error.InvalidRecord;
        }
        if (pos != shape.ring_count or written_runs != run_count) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
        return true;
    }

    fn appendDenseRingSecondaryRunCandidates(
        shape: DenseRingRepairSpoolShape,
        order: EdgeIndexOrder,
        key: u64,
        out: *[3]DenseRingSecondaryRun,
    ) usize {
        var count: usize = 0;
        const mentions_rel: u16 = @intFromEnum(core.RelKind.mentions);
        const first_ring_edge_id = switch (order) {
            .id => 0,
            .src => key,
            .dst => if (key == 1) shape.node_mod else key - 1,
        };
        if (first_ring_edge_id != 0 and first_ring_edge_id <= shape.ring_count) {
            const len = ((shape.ring_count - first_ring_edge_id) / shape.node_mod) + 1;
            out[count] = switch (order) {
                .id => unreachable,
                .src => .{
                    .src = key,
                    .dst = if (key == shape.node_mod) 1 else key + 1,
                    .edge_id_base = first_ring_edge_id,
                    .len = len,
                    .rel = mentions_rel,
                },
                .dst => .{
                    .src = if (key == 1) shape.node_mod else key - 1,
                    .dst = key,
                    .edge_id_base = first_ring_edge_id,
                    .len = len,
                    .rel = mentions_rel,
                },
            };
            count += 1;
        }

        if (shape.has_tail_fixture) {
            const depends_rel: u16 = @intFromEnum(core.RelKind.depends_on);
            if (order == .src and key == 1) {
                out[count] = .{ .src = 1, .dst = 2, .edge_id_base = shape.edge_count - 1, .len = 1, .rel = depends_rel };
                count += 1;
            } else if (order == .src and key == 2) {
                out[count] = .{ .src = 2, .dst = 3, .edge_id_base = shape.edge_count, .len = 1, .rel = depends_rel };
                count += 1;
            } else if (order == .dst and key == 2) {
                out[count] = .{ .src = 1, .dst = 2, .edge_id_base = shape.edge_count - 1, .len = 1, .rel = depends_rel };
                count += 1;
            } else if (order == .dst and key == 3) {
                out[count] = .{ .src = 2, .dst = 3, .edge_id_base = shape.edge_count, .len = 1, .rel = depends_rel };
                count += 1;
            }
        }

        std.mem.sort(DenseRingSecondaryRun, out[0..count], order, denseRingSecondaryRunLessThan);
        return count;
    }

    fn denseRingSecondaryRunLessThan(order: EdgeIndexOrder, lhs: DenseRingSecondaryRun, rhs: DenseRingSecondaryRun) bool {
        return edgeIndexLessThan(order, lhs.firstRecord(), rhs.firstRecord());
    }

    fn planDenseRingSecondaryIndex(shape: DenseRingRepairSpoolShape, order: EdgeIndexOrder) ?DenseRingSecondaryDensePlan {
        if (order == .id or shape.node_mod == 0 or shape.node_mod > std.math.maxInt(u32)) return null;

        var best: ?EdgeIndexDenseKeyRunSpan = null;
        var best_score: u64 = 0;
        var span_start_index: u64 = 0;
        var span_start: EdgeIndexKeyRunRecord = undefined;
        var previous: EdgeIndexKeyRunRecord = undefined;
        var span_count: u64 = 0;
        var start_step: u64 = 0;
        var edge_id_base_step: u64 = 0;

        var row_start: u64 = 0;
        var run_index: u64 = 0;
        var key: u64 = 1;
        while (key <= shape.node_mod) : (key += 1) {
            var candidates: [3]DenseRingSecondaryRun = undefined;
            const candidate_count = appendDenseRingSecondaryRunCandidates(shape, order, key, &candidates);
            for (candidates[0..candidate_count]) |candidate| {
                const run = EdgeIndexKeyRunRecord{
                    .key = candidate.key(order),
                    .start = row_start,
                    .opposite = candidate.opposite(order),
                    .edge_id_base = candidate.edge_id_base,
                    .edge_id_step = shape.node_mod,
                };
                const eligible = candidate.rel == @intFromEnum(core.RelKind.mentions) and
                    run.key != 0 and run.key <= std.math.maxInt(u32) and
                    run.start <= std.math.maxInt(u32) and
                    run.edge_id_base != 0 and run.edge_id_base <= std.math.maxInt(u32);
                if (eligible and span_count != 0) {
                    const continues = run.key == previous.key + 1 and
                        run.start > previous.start and
                        run.edge_id_base > previous.edge_id_base;
                    if (continues) {
                        const next_start_step = run.start - previous.start;
                        const next_edge_base_step = run.edge_id_base - previous.edge_id_base;
                        if (span_count == 1) {
                            start_step = next_start_step;
                            edge_id_base_step = next_edge_base_step;
                            span_count = 2;
                        } else if (next_start_step == start_step and next_edge_base_step == edge_id_base_step) {
                            span_count += 1;
                        } else {
                            best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                            span_start_index = run_index;
                            span_start = run;
                            start_step = 0;
                            edge_id_base_step = 0;
                            span_count = 1;
                        }
                    } else {
                        best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                        span_start_index = run_index;
                        span_start = run;
                        start_step = 0;
                        edge_id_base_step = 0;
                        span_count = 1;
                    }
                } else if (eligible) {
                    best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                    span_start_index = run_index;
                    span_start = run;
                    start_step = 0;
                    edge_id_base_step = 0;
                    span_count = 1;
                } else {
                    best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                    span_count = 0;
                    start_step = 0;
                    edge_id_base_step = 0;
                }
                previous = run;
                row_start += candidate.len;
                run_index += 1;
            }
        }
        best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
        const dense = best orelse return null;
        if (row_start != shape.edge_count or run_index == 0 or run_index > std.math.maxInt(u32)) return null;

        const explicit_runs = run_index - dense.count;
        const probe_header = EdgeIndexHeader.withShape(
            order,
            shape.edge_count,
            shape.edge_digest,
            0,
            false,
            true,
            true,
            denseRingRelDerivation(shape),
        ).withKeyRuns(@intCast(run_index), true, true).withKeyRunRingOpposite(shape.node_mod).withKeyRunUniformEdgeIdStep(shape.node_mod).withKeyRunDenseSpan(dense);
        const explicit_bytes = std.math.mul(u64, explicit_runs, edgeIndexKeyRunRecordLen(probe_header)) catch return null;
        if (explicit_bytes > edge_index_repair_key_run_memory_cap) return null;

        return .{ .run_count = run_index, .dense = dense };
    }

    fn denseRingRelDerivation(shape: DenseRingRepairSpoolShape) EdgeIndexRelDerivation {
        var derivation = EdgeIndexRelDerivation{ .default_rel = @intFromEnum(core.RelKind.mentions) };
        if (shape.has_tail_fixture) {
            derivation.exception_count = 2;
            derivation.exception_edge_ids = .{ shape.edge_count - 1, shape.edge_count };
            derivation.exception_rels = .{ @intFromEnum(core.RelKind.depends_on), @intFromEnum(core.RelKind.depends_on) };
        }
        return derivation;
    }

    fn denseRingSecondaryDigest(shape: DenseRingRepairSpoolShape, order: EdgeIndexOrder) !EdgeIndexDigest {
        var digest = EdgeIndexDigest{};
        var key: u64 = 1;
        while (key <= shape.node_mod) : (key += 1) {
            var candidates: [3]DenseRingSecondaryRun = undefined;
            const candidate_count = appendDenseRingSecondaryRunCandidates(shape, order, key, &candidates);
            for (candidates[0..candidate_count]) |candidate| {
                var offset: u64 = 0;
                while (offset < candidate.len) : (offset += 1) {
                    const edge_delta = std.math.mul(u64, offset, shape.node_mod) catch return error.InvalidRecord;
                    const edge_id = std.math.add(u64, candidate.edge_id_base, edge_delta) catch return error.InvalidRecord;
                    digest.add(.{
                        .src = candidate.src,
                        .dst = candidate.dst,
                        .edge_id = edge_id,
                        .rel = candidate.rel,
                    });
                }
            }
        }
        if (digest.count != shape.edge_count) return error.InvalidRecord;
        if (digest.digest != shape.edge_digest) return error.InvalidRecord;
        return digest;
    }

    fn writeDenseRingSecondaryEdgeIndex(self: Store, path: []const u8, order: EdgeIndexOrder, shape: DenseRingRepairSpoolShape) !bool {
        const plan = planDenseRingSecondaryIndex(shape, order) orelse return false;
        const digest = try denseRingSecondaryDigest(shape, order);
        var header = EdgeIndexHeader.withShape(
            order,
            shape.edge_count,
            shape.edge_digest,
            digest.order_digest,
            false,
            true,
            true,
            denseRingRelDerivation(shape),
        ).withKeyRuns(@intCast(plan.run_count), true, true).withKeyRunRingOpposite(shape.node_mod).withKeyRunUniformEdgeIdStep(shape.node_mod).withKeyRunDenseSpan(plan.dense);
        if (header.record_len != 0) return false;

        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        const expected_size = try edgeIndexFileSizeForHeader(header);
        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        header.encode(&header_bytes);
        try writer.append(&header_bytes);

        const dense_end = plan.dense.run_start + plan.dense.count;
        var row_start: u64 = 0;
        var run_index: u64 = 0;
        var key: u64 = 1;
        var run_bytes: [40]u8 = undefined;
        while (key <= shape.node_mod) : (key += 1) {
            var candidates: [3]DenseRingSecondaryRun = undefined;
            const candidate_count = appendDenseRingSecondaryRunCandidates(shape, order, key, &candidates);
            for (candidates[0..candidate_count]) |candidate| {
                const run = EdgeIndexKeyRunRecord{
                    .key = candidate.key(order),
                    .start = row_start,
                    .opposite = candidate.opposite(order),
                    .edge_id_base = candidate.edge_id_base,
                    .edge_id_step = shape.node_mod,
                };
                if (run_index >= plan.dense.run_start and run_index < dense_end) {
                    const expected = try edgeIndexDenseKeyRunSpanRecordForIndex(header, run_index);
                    if (!edgeIndexKeyRunRecordsEquivalent(header, expected, run)) return false;
                } else {
                    const encoded = run_bytes[0..edgeIndexKeyRunRecordLen(header)];
                    try run.encodeForHeader(header, encoded);
                    try writer.append(encoded);
                }
                row_start += candidate.len;
                run_index += 1;
            }
        }
        if (row_start != shape.edge_count or run_index != plan.run_count) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
        return true;
    }

    fn writeSingleChunkRepairEdgeIndexFromScratch(
        self: Store,
        path: []const u8,
        order: EdgeIndexOrder,
        records: []const EdgeIndexRecord,
        sorted_records: *std.ArrayList(EdgeIndexRecord),
    ) !void {
        try sorted_records.ensureTotalCapacityPrecise(self.allocator, records.len);
        sorted_records.clearRetainingCapacity();
        for (records) |record| sorted_records.appendAssumeCapacity(record);
        sortEdgeIndexRecords(order, sorted_records.items);
        try validateSortedRepairEdgeRecords(order, sorted_records.items);
        try self.writeEdgeIndex(path, sorted_records.items);
    }

    fn writeEdgeIndexFromRepairSpool(self: Store, path: []const u8, order: EdgeIndexOrder, spool_path: []const u8, record_count: usize) !void {
        if (order == .id and try self.writeSortedEdgeIdIndexFromRepairSpoolIfPossible(path, spool_path, record_count)) return;

        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var run_paths = std.ArrayList([]u8).empty;
        defer self.deinitEdgeRepairRunPaths(&run_paths);

        var chunk = std.ArrayList(EdgeIndexRecord).empty;
        defer chunk.deinit(self.allocator);
        const max_chunk_records = @min(record_count, edge_repair_sort_chunk_records);
        try chunk.ensureTotalCapacityPrecise(self.allocator, max_chunk_records);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, max_chunk_records, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord);
        defer self.allocator.free(chunk_bytes);

        var read_pos: usize = 0;
        while (read_pos < record_count) {
            chunk.clearRetainingCapacity();
            const take = @min(edge_repair_sort_chunk_records, record_count - read_pos);
            try self.readEdgeRepairSpoolChunk(spool_file, read_pos, take, chunk_bytes, &chunk);
            sortEdgeIndexRecords(order, chunk.items);
            try self.appendEdgeRepairRunPath(&run_paths, path, order, chunk.items);
            read_pos += take;
        }

        try self.writeMergedRepairEdgeRuns(path, order, run_paths.items, record_count);
    }

    fn writeSortedEdgeIdIndexFromRepairSpoolIfPossible(self: Store, path: []const u8, spool_path: []const u8, record_count: usize) !bool {
        if (record_count == 0) return false;

        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        var close_spool_file = true;
        errdefer if (close_spool_file) spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        var map = if (shouldMmapRepairSpool(expected_spool_size))
            openReadOnlyMemoryMap(self.io, spool_file, expected_spool_size) catch null
        else
            null;
        errdefer if (map) |*mapped| mapped.destroy(self.io);
        var buffer: []u8 = &.{};
        errdefer self.allocator.free(buffer);
        if (map == null) {
            buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(expected_spool_size));
        }
        var reader = EdgeRepairRunReader{
            .file = spool_file,
            .map = map,
            .next_index = 0,
            .count = @intCast(record_count),
            .buffer = buffer,
        };
        defer reader.deinit(self.allocator, self.io);
        close_spool_file = false;
        map = null;
        buffer = &.{};

        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        var published = false;
        defer if (!published) std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        const expected_size = try edgeIndexFileSize(@intCast(record_count));
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        const placeholder_header = EdgeIndexHeader{ .order = .id, .edge_count = @intCast(record_count) };
        placeholder_header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var digest = EdgeIndexDigest{};
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        var previous: ?EdgeIndexRecord = null;
        while (try reader.next(self)) |record| {
            if (previous) |prev| {
                if (!edgeIndexLessThan(.id, prev, record)) return false;
                if (record.edge_id == prev.edge_id) return false;
            }
            previous = record;
            record.encode(&record_bytes);
            try writer.append(&record_bytes);
            digest.add(record);
        }
        if (digest.count != record_count) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var header = EdgeIndexHeader{
            .order = .id,
            .edge_count = @intCast(record_count),
            .edge_digest = digest.digest,
            .order_digest = digest.order_digest,
        };
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        try self.compactEdgeIndexToDerivedRecords(file, &header);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
        published = true;
        return true;
    }

    fn readEdgeRepairSpoolChunk(self: Store, file: std.Io.File, start_index: usize, record_count: usize, buffer: []u8, out: *std.ArrayList(EdgeIndexRecord)) !void {
        const byte_count = std.math.mul(usize, record_count, EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        if (byte_count > buffer.len) return error.InvalidRecord;
        const offset = std.math.mul(u64, @intCast(start_index), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        const n = try file.readPositionalAll(self.io, buffer[0..byte_count], offset);
        if (n != byte_count) return error.InvalidRecord;
        var cursor: usize = 0;
        while (cursor < byte_count) : (cursor += EdgeIndexRecord.encoded_len) {
            out.appendAssumeCapacity(try EdgeIndexRecord.decodeSlice(buffer[cursor .. cursor + EdgeIndexRecord.encoded_len]));
        }
    }

    fn writeRepairEdgeRun(self: Store, path: []const u8, records: []const EdgeIndexRecord) !void {
        const expected_size = std.math.mul(u64, @intCast(records.len), EdgeIndexRecord.encoded_len) catch return error.InvalidRecord;
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        for (records) |record| {
            record.encode(&record_bytes);
            try writer.append(&record_bytes);
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn writeMergedRepairEdgeRuns(self: Store, path: []const u8, order: EdgeIndexOrder, run_paths: []const []const u8, record_count: usize) !void {
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var readers = std.ArrayList(EdgeRepairRunReader).empty;
        defer {
            for (readers.items) |*reader| reader.deinit(self.allocator, self.io);
            readers.deinit(self.allocator);
        }
        try readers.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        var queue = std.PriorityQueue(EdgeRepairRunHeapEntry, EdgeRepairRunHeapContext, compareEdgeRepairRunHeapEntry).initContext(.{ .order = order });
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        for (run_paths) |run_path| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, run_path, .{});
            var close_run_file = true;
            errdefer if (close_run_file) run_file.close(self.io);
            const run_size = try self.regularFileSize(run_file);
            if (run_size % EdgeIndexRecord.encoded_len != 0) return error.InvalidRecord;
            const run_count = run_size / EdgeIndexRecord.encoded_len;
            var map = if (run_count == 0) null else openReadOnlyMemoryMap(self.io, run_file, run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            var buffer: []u8 = &.{};
            errdefer self.allocator.free(buffer);
            if (map == null) {
                buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(run_size));
            }
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .next_index = 0,
                .count = run_count,
                .buffer = buffer,
            });
            close_run_file = false;
            map = null;
            buffer = &.{};
            if (run_count != 0) {
                const record = (try readers.items[reader_index].next(self)) orelse return error.InvalidRecord;
                try queue.push(self.allocator, .{ .run_index = reader_index, .record = record });
            }
        }

        const expected_size = try edgeIndexFileSize(@intCast(record_count));
        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
        const placeholder_header = EdgeIndexHeader{ .order = order, .edge_count = @intCast(record_count) };
        placeholder_header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var digest = EdgeIndexDigest{};
        var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        var previous: ?EdgeIndexRecord = null;
        while (queue.pop()) |entry| {
            if (previous) |prev| {
                if (!edgeIndexLessThan(order, prev, entry.record)) return error.InvalidRecord;
                if (order == .id and entry.record.edge_id == prev.edge_id) return error.InvalidRecord;
            }
            previous = entry.record;
            entry.record.encode(&record_bytes);
            try writer.append(&record_bytes);
            digest.add(entry.record);

            const reader = &readers.items[entry.run_index];
            if (try reader.next(self)) |record| {
                try queue.push(self.allocator, .{ .run_index = entry.run_index, .record = record });
            }
        }
        if (digest.count != record_count) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        var header = EdgeIndexHeader{
            .order = order,
            .edge_count = @intCast(record_count),
            .edge_digest = digest.digest,
            .order_digest = digest.order_digest,
        };
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        try self.compactEdgeIndexToDerivedRecords(file, &header);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, path);
    }

    fn writeEdgeIndex(self: Store, path: []const u8, records: []const EdgeIndexRecord) !void {
        const order: EdgeIndexOrder = if (std.mem.eql(u8, path, self.edge_by_id_path))
            .id
        else if (std.mem.eql(u8, path, self.edge_by_dst_path))
            .dst
        else
            .src;
        const tmp_path = try self.tmpPathFor(path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var digest = EdgeIndexDigest{};
            for (records) |record| digest.add(record);
            const header = edgeIndexHeaderForCompleteRecords(order, records, digest.digest, digest.order_digest);
            const expected_size = try edgeIndexFileSizeForHeader(header);
            try writeCompleteEdgeIndexFile(self, file, header, records, expected_size);
            if (selfOptionsNeedSync(self)) {
                try file.sync(self.io);
            }
        }
        try self.renameReplace(tmp_path, path);
    }

    fn writeEdgeTombstoneIndex(self: Store, records: []const EdgeTombstoneRecord) !void {
        const tmp_path = try self.tmpPathFor(self.edge_tombstones_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(try edgeTombstoneFileSize(@intCast(records.len))));
            defer writer.deinit();

            var digest: u64 = 0;
            for (records, 0..) |record, i| {
                if (record.edge_id == 0 or record.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
                if (i != 0 and records[i - 1].edge_id >= record.edge_id) return error.InvalidRecord;
                digest ^= record.edge_digest;
            }
            var header_bytes: [EdgeTombstoneHeader.encoded_len]u8 = undefined;
            const header = EdgeTombstoneHeader{
                .count = @intCast(records.len),
                .digest = digest,
            };
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            var record_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
            for (records) |record| {
                record.encode(&record_bytes);
                try writer.append(&record_bytes);
            }
            try writer.flush();
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.edge_tombstones_path);
    }

    fn writeEdgeOrderIndex(self: Store, records: []const EdgeOrderRecord) !void {
        const tmp_path = try self.tmpPathFor(self.edge_order_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};
        {
            var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
                .read = true,
                .truncate = true,
            });
            defer file.close(self.io);
            const payload_bytes = std.math.mul(u64, @intCast(records.len), EdgeOrderRecord.encoded_len) catch return error.InvalidRecord;
            const file_size = EdgeOrderHeader.encoded_len + payload_bytes;
            var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(file_size));
            defer writer.deinit();

            var digest: u64 = 0;
            for (records, 0..) |record, i| {
                try validateEdgeOrderRecord(record);
                if (i != 0 and !edgeOrderRecordLessThan({}, records[i - 1], record)) return error.InvalidRecord;
                if (i != 0 and records[i - 1].edge_id == record.edge_id) return error.InvalidRecord;
                digest ^= edgeOrderRecordDigest(record);
            }
            var header_bytes: [EdgeOrderHeader.encoded_len]u8 = undefined;
            const header = EdgeOrderHeader{
                .count = @intCast(records.len),
                .digest = digest,
            };
            header.encode(&header_bytes);
            try writer.append(&header_bytes);
            var record_bytes: [EdgeOrderRecord.encoded_len]u8 = undefined;
            for (records) |record| {
                record.encode(&record_bytes);
                try writer.append(&record_bytes);
            }
            try writer.flush();
            if (selfOptionsNeedSync(self)) try file.sync(self.io);
        }
        try self.renameReplace(tmp_path, self.edge_order_path);
    }

    const TombstoneRepairRunReader = struct {
        file: std.Io.File,
        map: ?std.Io.File.MemoryMap = null,
        next_index: u64,
        count: u64,
        buffer: []u8 = &.{},
        file_offset: u64 = 0,
        cursor: usize = 0,
        len: usize = 0,

        fn deinit(self: *TombstoneRepairRunReader, allocator: std.mem.Allocator, io: std.Io) void {
            allocator.free(self.buffer);
            if (self.map) |*map| map.destroy(io);
            self.file.close(io);
        }

        fn refill(self: *TombstoneRepairRunReader, store: Store) !void {
            const n = try self.file.readPositionalAll(store.io, self.buffer, self.file_offset);
            if (n == 0) return error.InvalidRecord;
            self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
            self.cursor = 0;
            self.len = n;
        }

        fn readBytes(self: *TombstoneRepairRunReader, store: Store, out: []u8) !void {
            var written: usize = 0;
            while (written < out.len) {
                if (self.cursor == self.len) try self.refill(store);
                const available = self.len - self.cursor;
                const n = @min(available, out.len - written);
                @memcpy(out[written .. written + n], self.buffer[self.cursor .. self.cursor + n]);
                self.cursor += n;
                written += n;
            }
        }

        fn next(self: *TombstoneRepairRunReader, store: Store) !?EdgeTombstoneRecord {
            if (self.next_index >= self.count) return null;
            const record = if (self.map) |*map| record: {
                const offset = std.math.mul(u64, self.next_index, EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
                const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
                const end = std.math.add(usize, start, EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
                if (end > map.memory.len) return error.InvalidRecord;
                break :record try EdgeTombstoneRecord.decodeSlice(map.memory[start..end]);
            } else record: {
                if (self.cursor == self.len) try self.refill(store);
                if (self.len - self.cursor >= EdgeTombstoneRecord.encoded_len) {
                    const bytes = self.buffer[self.cursor .. self.cursor + EdgeTombstoneRecord.encoded_len];
                    self.cursor += EdgeTombstoneRecord.encoded_len;
                    break :record try EdgeTombstoneRecord.decodeSlice(bytes);
                }
                var bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
                try self.readBytes(store, &bytes);
                break :record try EdgeTombstoneRecord.decode(&bytes);
            };
            self.next_index += 1;
            return record;
        }
    };

    const TombstoneRepairRunHeapEntry = struct {
        run_index: usize,
        record: EdgeTombstoneRecord,
    };

    fn compareTombstoneRepairRunHeapEntry(_: void, lhs: TombstoneRepairRunHeapEntry, rhs: TombstoneRepairRunHeapEntry) std.math.Order {
        if (edgeTombstoneLessThan({}, lhs.record, rhs.record)) return .lt;
        if (edgeTombstoneLessThan({}, rhs.record, lhs.record)) return .gt;
        return std.math.order(lhs.run_index, rhs.run_index);
    }

    fn writeEdgeTombstoneIndexFromRepairSpool(self: Store, spool_path: []const u8, record_count: usize, expected_digest: u64) !void {
        var spool_file = try std.Io.Dir.cwd().openFile(self.io, spool_path, .{});
        defer spool_file.close(self.io);
        const expected_spool_size = std.math.mul(u64, @intCast(record_count), EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
        if (try self.regularFileSize(spool_file) != expected_spool_size) return error.InvalidRecord;

        if (record_count <= tombstone_repair_sort_chunk_records) {
            var records = std.ArrayList(EdgeTombstoneRecord).empty;
            defer records.deinit(self.allocator);
            try records.ensureTotalCapacityPrecise(self.allocator, record_count);
            const chunk_bytes = try self.allocator.alloc(u8, expected_spool_size);
            defer self.allocator.free(chunk_bytes);
            if (record_count != 0) {
                try self.readTombstoneRepairSpoolChunk(spool_file, 0, record_count, chunk_bytes, &records);
                std.mem.sort(EdgeTombstoneRecord, records.items, {}, edgeTombstoneLessThan);
            }
            try self.writeSortedTombstoneRepairRecords(records.items, expected_digest);
            return;
        }

        var run_paths = std.ArrayList([]u8).empty;
        defer {
            for (run_paths.items) |run_path| {
                std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
                self.allocator.free(run_path);
            }
            run_paths.deinit(self.allocator);
        }

        var chunk = std.ArrayList(EdgeTombstoneRecord).empty;
        defer chunk.deinit(self.allocator);
        const max_chunk_records = @min(record_count, tombstone_repair_sort_chunk_records);
        try chunk.ensureTotalCapacityPrecise(self.allocator, max_chunk_records);
        const chunk_bytes = try self.allocator.alloc(u8, std.math.mul(usize, max_chunk_records, EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord);
        defer self.allocator.free(chunk_bytes);

        var read_pos: usize = 0;
        while (read_pos < record_count) {
            chunk.clearRetainingCapacity();
            const take = @min(tombstone_repair_sort_chunk_records, record_count - read_pos);
            try self.readTombstoneRepairSpoolChunk(spool_file, read_pos, take, chunk_bytes, &chunk);
            std.mem.sort(EdgeTombstoneRecord, chunk.items, {}, edgeTombstoneLessThan);
            const run_path = try std.fmt.allocPrint(self.allocator, "{s}.repair_run.{d}.tmp", .{ self.edge_tombstones_path, run_paths.items.len });
            errdefer self.allocator.free(run_path);
            try self.writeTombstoneRepairRun(run_path, chunk.items);
            try run_paths.append(self.allocator, run_path);
            read_pos += take;
        }

        try self.writeMergedTombstoneRepairRuns(run_paths.items, record_count, expected_digest);
    }

    fn readTombstoneRepairSpoolChunk(self: Store, file: std.Io.File, start_index: usize, record_count: usize, buffer: []u8, out: *std.ArrayList(EdgeTombstoneRecord)) !void {
        const byte_count = std.math.mul(usize, record_count, EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
        if (byte_count > buffer.len) return error.InvalidRecord;
        const offset = std.math.mul(u64, @intCast(start_index), EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
        const n = try file.readPositionalAll(self.io, buffer[0..byte_count], offset);
        if (n != byte_count) return error.InvalidRecord;
        var cursor: usize = 0;
        while (cursor < byte_count) : (cursor += EdgeTombstoneRecord.encoded_len) {
            out.appendAssumeCapacity(try EdgeTombstoneRecord.decodeSlice(buffer[cursor .. cursor + EdgeTombstoneRecord.encoded_len]));
        }
    }

    fn writeSortedTombstoneRepairRecords(self: Store, records: []const EdgeTombstoneRecord, expected_digest: u64) !void {
        const tmp_path = try self.tmpPathFor(self.edge_tombstones_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        const expected_size = try edgeTombstoneFileSize(@intCast(records.len));
        var edge_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer edge_file.close(self.io);
        const edge_header = try self.readEdgeIndexHeaderFromFile(edge_file);
        if (edge_header.order != .id) return error.InvalidRecord;
        if (try self.regularFileSize(edge_file) != try edgeIndexFileSizeForHeader(edge_header)) return error.InvalidRecord;

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeTombstoneHeader.encoded_len]u8 = undefined;
        const placeholder_header = EdgeTombstoneHeader{ .count = @intCast(records.len), .digest = expected_digest };
        placeholder_header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var emitted: u64 = 0;
        var derived_digest: u64 = 0;
        var edge_scan_pos: u64 = 0;
        var previous: ?EdgeTombstoneRecord = null;
        var record_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
        for (records) |record| {
            if (previous) |prev| {
                if (prev.edge_id >= record.edge_id) return error.InvalidRecord;
            }
            previous = record;
            var found_edge = false;
            while (edge_scan_pos < edge_header.edge_count) {
                const edge = try self.readEdgeIndexRecordAt(edge_file, edge_header, edge_scan_pos);
                edge_scan_pos += 1;
                if (edge.edge_id < record.edge_id) continue;
                if (edge.edge_id != record.edge_id) return error.InvalidRecord;
                derived_digest ^= edgeRecordDigest(edge);
                found_edge = true;
                break;
            }
            if (!found_edge) return error.InvalidRecord;
            emitted += 1;
            record.encode(&record_bytes);
            try writer.append(&record_bytes);
        }
        if (emitted != records.len) return error.InvalidRecord;
        if (derived_digest != expected_digest) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        const header = EdgeTombstoneHeader{ .count = @intCast(records.len), .digest = expected_digest };
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, self.edge_tombstones_path);
    }

    fn writeTombstoneRepairRun(self: Store, path: []const u8, records: []const EdgeTombstoneRecord) !void {
        const expected_size = std.math.mul(u64, @intCast(records.len), EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
        var file = try std.Io.Dir.cwd().createFile(self.io, path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();
        var record_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
        for (records) |record| {
            record.encode(&record_bytes);
            try writer.append(&record_bytes);
        }
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
    }

    fn writeMergedTombstoneRepairRuns(self: Store, run_paths: []const []const u8, record_count: usize, expected_digest: u64) !void {
        const tmp_path = try self.tmpPathFor(self.edge_tombstones_path);
        defer self.allocator.free(tmp_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, tmp_path) catch {};

        var readers = std.ArrayList(TombstoneRepairRunReader).empty;
        defer {
            for (readers.items) |*reader| reader.deinit(self.allocator, self.io);
            readers.deinit(self.allocator);
        }
        try readers.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        var queue = std.PriorityQueue(TombstoneRepairRunHeapEntry, void, compareTombstoneRepairRunHeapEntry).initContext({});
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacityPrecise(self.allocator, run_paths.len);

        for (run_paths) |run_path| {
            var run_file = try std.Io.Dir.cwd().openFile(self.io, run_path, .{});
            var close_run_file = true;
            errdefer if (close_run_file) run_file.close(self.io);
            const run_size = try self.regularFileSize(run_file);
            if (run_size % EdgeTombstoneRecord.encoded_len != 0) return error.InvalidRecord;
            const run_count = run_size / EdgeTombstoneRecord.encoded_len;
            var map = if (run_count == 0) null else openReadOnlyMemoryMap(self.io, run_file, run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.io);
            var buffer: []u8 = &.{};
            errdefer self.allocator.free(buffer);
            if (map == null) {
                buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(run_size));
            }
            const reader_index = readers.items.len;
            readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .next_index = 0,
                .count = run_count,
                .buffer = buffer,
            });
            close_run_file = false;
            map = null;
            buffer = &.{};
            if (run_count != 0) {
                const record = (try readers.items[reader_index].next(self)) orelse return error.InvalidRecord;
                try queue.push(self.allocator, .{ .run_index = reader_index, .record = record });
            }
        }

        const expected_size = try edgeTombstoneFileSize(@intCast(record_count));
        var edge_file = try std.Io.Dir.cwd().openFile(self.io, self.edge_by_id_path, .{});
        defer edge_file.close(self.io);
        const edge_header = try self.readEdgeIndexHeaderFromFile(edge_file);
        if (edge_header.order != .id) return error.InvalidRecord;
        if (try self.regularFileSize(edge_file) != try edgeIndexFileSizeForHeader(edge_header)) return error.InvalidRecord;

        var file = try std.Io.Dir.cwd().createFile(self.io, tmp_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(self.io);
        var writer = try StorageBufferedWriter.init(self.allocator, self.io, file, try storageWriteBufferCapacity(expected_size));
        defer writer.deinit();

        var header_bytes: [EdgeTombstoneHeader.encoded_len]u8 = undefined;
        const placeholder_header = EdgeTombstoneHeader{ .count = @intCast(record_count), .digest = expected_digest };
        placeholder_header.encode(&header_bytes);
        try writer.append(&header_bytes);

        var emitted: u64 = 0;
        var derived_digest: u64 = 0;
        var edge_scan_pos: u64 = 0;
        var previous: ?EdgeTombstoneRecord = null;
        var record_bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
        while (queue.pop()) |entry| {
            if (previous) |prev| {
                if (prev.edge_id >= entry.record.edge_id) return error.InvalidRecord;
            }
            previous = entry.record;
            var found_edge = false;
            while (edge_scan_pos < edge_header.edge_count) {
                const edge = try self.readEdgeIndexRecordAt(edge_file, edge_header, edge_scan_pos);
                edge_scan_pos += 1;
                if (edge.edge_id < entry.record.edge_id) continue;
                if (edge.edge_id != entry.record.edge_id) return error.InvalidRecord;
                derived_digest ^= edgeRecordDigest(edge);
                found_edge = true;
                break;
            }
            if (!found_edge) return error.InvalidRecord;
            emitted += 1;
            entry.record.encode(&record_bytes);
            try writer.append(&record_bytes);

            const reader = &readers.items[entry.run_index];
            if (try reader.next(self)) |record| {
                try queue.push(self.allocator, .{ .run_index = entry.run_index, .record = record });
            }
        }
        if (emitted != record_count) return error.InvalidRecord;
        if (derived_digest != expected_digest) return error.InvalidRecord;
        try writer.flush();
        if (try writer.position() != expected_size) return error.InvalidRecord;
        if (try self.regularFileSize(file) != expected_size) return error.InvalidRecord;

        const header = EdgeTombstoneHeader{ .count = @intCast(record_count), .digest = expected_digest };
        header.encode(&header_bytes);
        try file.writePositionalAll(self.io, &header_bytes, 0);
        if (selfOptionsNeedSync(self)) try file.sync(self.io);
        try self.renameReplace(tmp_path, self.edge_tombstones_path);
    }

    fn eventBytes(self: Store) !u64 {
        var file = try std.Io.Dir.cwd().openFile(self.io, self.events_bin_path, .{});
        defer file.close(self.io);
        return self.regularFileSize(file);
    }

    fn fileSizeOrZero(self: Store, path: []const u8) !u64 {
        var file = std.Io.Dir.cwd().openFile(self.io, path, .{}) catch |err| switch (err) {
            error.FileNotFound => return 0,
            error.NotDir => return 0,
            error.IsDir => return error.IsDir,
            else => |e| return e,
        };
        defer file.close(self.io);
        const stat = try file.stat(self.io);
        if (stat.kind != .file) return error.IsDir;
        return stat.size;
    }

    fn nodeByIdFileSizeForStore(self: Store, max_node_id: u64) !u64 {
        const size = try nodeByIdFileSize(max_node_id);
        if (size > self.options.max_node_by_id_index_bytes) return error.RecordTooLarge;
        return size;
    }

    fn nodeByIdFileSizeForHeaderStore(self: Store, header: NodeByIdHeader) !u64 {
        const size = try nodeByIdFileSizeForHeader(header);
        if (size > self.options.max_node_by_id_index_bytes) return error.RecordTooLarge;
        return size;
    }

    fn tmpPathFor(self: Store, path: []const u8) ![]u8 {
        return try std.fmt.allocPrint(self.allocator, "{s}.tmp", .{path});
    }

    fn renameReplace(self: Store, tmp_path: []const u8, final_path: []const u8) !void {
        if (std.fs.path.isAbsolute(tmp_path) or std.fs.path.isAbsolute(final_path)) {
            try std.Io.Dir.renameAbsolute(tmp_path, final_path, self.io);
        } else {
            try std.Io.Dir.rename(.cwd(), tmp_path, .cwd(), final_path, self.io);
        }
        try self.syncParentDirForPath(final_path);
    }

    fn syncParentDirForPath(self: Store, path: []const u8) !void {
        if (!selfOptionsNeedSync(self)) return;
        if (builtin.os.tag == .windows) return;
        const dir_path = std.fs.path.dirname(path) orelse ".";
        var dir_file = if (std.fs.path.isAbsolute(dir_path))
            try std.Io.Dir.openFileAbsolute(self.io, dir_path, .{ .allow_directory = true })
        else
            try std.Io.Dir.cwd().openFile(self.io, dir_path, .{ .allow_directory = true });
        defer dir_file.close(self.io);
        try dir_file.sync(self.io);
    }
};

fn selfOptionsNeedSync(store: Store) bool {
    return switch (store.options.durability) {
        .fast => false,
        .safe => true,
    };
}

fn storageMonotonicNs(io: std.Io) u128 {
    const timestamp = std.Io.Clock.awake.now(io).nanoseconds;
    return if (timestamp < 0) 0 else @intCast(timestamp);
}

fn storageElapsedNs(io: std.Io, start: u128) u128 {
    const now = storageMonotonicNs(io);
    return if (now >= start) now - start else 0;
}

fn indexMetaEquals(lhs: IndexMeta, rhs: IndexMeta) bool {
    return lhs.event_bytes == rhs.event_bytes and
        lhs.nodes == rhs.nodes and
        lhs.edges == rhs.edges and
        lhs.node_digest == rhs.node_digest and
        lhs.edge_digest == rhs.edge_digest and
        lhs.node_by_text_order_digest == rhs.node_by_text_order_digest and
        lhs.edge_indexed_edges == rhs.edge_indexed_edges and
        lhs.edge_index_digest == rhs.edge_index_digest and
        lhs.edge_by_id_order_digest == rhs.edge_by_id_order_digest and
        lhs.edge_by_src_order_digest == rhs.edge_by_src_order_digest and
        lhs.edge_by_dst_order_digest == rhs.edge_by_dst_order_digest and
        lhs.max_edge_id_seen == rhs.max_edge_id_seen and
        edgeSegmentIdRunSummariesEqual(lhs.edge_by_id_runs, rhs.edge_by_id_runs) and
        lhs.edge_segment_edges == rhs.edge_segment_edges and
        lhs.edge_segment_manifest_digest == rhs.edge_segment_manifest_digest and
        edgeSegmentIdRunSummariesEqual(lhs.edge_segment_id_runs, rhs.edge_segment_id_runs);
}

fn segmentManifestUniqueEntry(snapshot: segment_manifest.Snapshot, kind: segment_manifest.SegmentKind) !segment_manifest.Entry {
    var found: ?segment_manifest.Entry = null;
    for (snapshot.entries.items) |entry| {
        if (entry.kind != kind) continue;
        if (found != null) return error.InvalidRecord;
        found = entry.asEntry();
    }
    return found orelse error.InvalidRecord;
}

fn segmentManifestHasEdgeEntry(snapshot: segment_manifest.Snapshot) bool {
    for (snapshot.entries.items) |entry| {
        if (entry.kind == .edge) return true;
    }
    return false;
}

fn segmentManifestEdgeEntries(allocator: std.mem.Allocator, snapshot: segment_manifest.Snapshot) ![]segment_manifest.Entry {
    var count: usize = 0;
    for (snapshot.entries.items) |entry| {
        if (entry.kind == .edge) count += 1;
    }
    if (count == 0) return error.InvalidRecord;

    const entries = try allocator.alloc(segment_manifest.Entry, count);
    errdefer allocator.free(entries);
    var index: usize = 0;
    for (snapshot.entries.items) |entry| {
        if (entry.kind != .edge) continue;
        entries[index] = entry.asEntry();
        index += 1;
    }
    return entries;
}

fn segmentManifestEdgeCount(entries: []const segment_manifest.Entry) !u64 {
    var total: u64 = 0;
    for (entries) |entry| {
        if (entry.kind != .edge) return error.InvalidRecord;
        total = std.math.add(u64, total, entry.edge_count) catch return error.InvalidRecord;
    }
    return total;
}

fn segmentManifestEdgeDigest(entries: []const segment_manifest.Entry) u64 {
    var digest: u64 = 0;
    for (entries) |entry| digest ^= entry.segment_digest;
    return digest;
}

fn markEdgeIndexesCurrent(meta: *IndexMeta) void {
    meta.edge_indexed_edges = meta.edges;
    meta.edge_index_digest = meta.edge_digest;
    clearEdgeSegmentSummary(meta);
}

fn clearEdgeSegmentSummary(meta: *IndexMeta) void {
    meta.edge_segment_edges = 0;
    meta.edge_segment_manifest_digest = 0;
    meta.edge_segment_id_runs = .{};
}

fn edgeOrderDigestForMeta(meta: IndexMeta, order: EdgeIndexOrder) u64 {
    return switch (order) {
        .id => meta.edge_by_id_order_digest,
        .src => meta.edge_by_src_order_digest,
        .dst => meta.edge_by_dst_order_digest,
    };
}

fn edgeIndexBySrcLessThan(_: void, lhs: EdgeIndexRecord, rhs: EdgeIndexRecord) bool {
    if (lhs.src != rhs.src) return lhs.src < rhs.src;
    if (lhs.rel != rhs.rel) return lhs.rel < rhs.rel;
    if (lhs.dst != rhs.dst) return lhs.dst < rhs.dst;
    return lhs.edge_id < rhs.edge_id;
}

fn edgeIndexByIdLessThan(_: void, lhs: EdgeIndexRecord, rhs: EdgeIndexRecord) bool {
    if (lhs.edge_id != rhs.edge_id) return lhs.edge_id < rhs.edge_id;
    if (lhs.src != rhs.src) return lhs.src < rhs.src;
    if (lhs.dst != rhs.dst) return lhs.dst < rhs.dst;
    return lhs.rel < rhs.rel;
}

fn edgeIndexByDstLessThan(_: void, lhs: EdgeIndexRecord, rhs: EdgeIndexRecord) bool {
    if (lhs.dst != rhs.dst) return lhs.dst < rhs.dst;
    if (lhs.rel != rhs.rel) return lhs.rel < rhs.rel;
    if (lhs.src != rhs.src) return lhs.src < rhs.src;
    return lhs.edge_id < rhs.edge_id;
}

fn edgeIndexLessThan(order: EdgeIndexOrder, lhs: EdgeIndexRecord, rhs: EdgeIndexRecord) bool {
    return switch (order) {
        .id => edgeIndexByIdLessThan({}, lhs, rhs),
        .src => edgeIndexBySrcLessThan({}, lhs, rhs),
        .dst => edgeIndexByDstLessThan({}, lhs, rhs),
    };
}

fn edgeIndexBatchSorted(order: EdgeIndexOrder, records: []const EdgeIndexRecord) bool {
    var pos: usize = 1;
    while (pos < records.len) : (pos += 1) {
        if (!edgeIndexLessThan(order, records[pos - 1], records[pos])) return false;
    }
    return true;
}

fn edgeRecordsAreDenseIdTail(base_count: u64, records: []const EdgeIndexRecord) bool {
    for (records, 0..) |record, i| {
        const expected = std.math.add(u64, base_count, @intCast(i + 1)) catch return false;
        if (record.edge_id != expected) return false;
    }
    return true;
}

fn edgeRecordHasU32NodeIds(record: EdgeIndexRecord) bool {
    return record.src <= std.math.maxInt(u32) and record.dst <= std.math.maxInt(u32);
}

fn edgeRecordsHaveU32NodeIds(records: []const EdgeIndexRecord) bool {
    if (records.len == 0) return false;
    for (records) |record| {
        if (!edgeRecordHasU32NodeIds(record)) return false;
    }
    return true;
}

fn edgeRecordHasU32EdgeId(record: EdgeIndexRecord) bool {
    return record.edge_id <= std.math.maxInt(u32);
}

fn edgeRecordsHaveU32EdgeIds(records: []const EdgeIndexRecord) bool {
    if (records.len == 0) return false;
    for (records) |record| {
        if (!edgeRecordHasU32EdgeId(record)) return false;
    }
    return true;
}

fn edgeIndexHeaderWithBeneficialKeyRuns(order: EdgeIndexOrder, header: EdgeIndexHeader, records: []const EdgeIndexRecord) EdgeIndexHeader {
    if (records.len == 0) return header;
    if (order == .id) return edgeIndexHeaderWithBeneficialIdEndpointRuns(header, records);
    if (header.hasDenseId() or header.hasKeyRuns()) return header;
    const run_count = edgeIndexRunCountForSortedRecords(order, records) orelse return header;
    if (run_count == 0 or run_count > std.math.maxInt(u32)) return header;
    const opposite_lane_len: u64 = if (header.hasU32NodeIds()) 4 else 8;
    const constant_opposite = edgeIndexRunsHaveConstantOpposite(order, records) and constant_opposite: {
        const dir_bytes = std.math.mul(u64, run_count, opposite_lane_len) catch break :constant_opposite false;
        const row_bytes = std.math.mul(u64, @intCast(records.len), opposite_lane_len) catch break :constant_opposite false;
        break :constant_opposite dir_bytes < row_bytes;
    };
    const base_body_bytes = edgeIndexBodyBytes(header) orelse return header;
    var best_header = header;
    var best_body_bytes = base_body_bytes;

    const key_run_header = header.withKeyRuns(@intCast(run_count), constant_opposite, false);
    if (edgeIndexBodyBytes(key_run_header)) |bytes| {
        if (bytes < best_body_bytes) {
            best_header = key_run_header;
            best_body_bytes = bytes;
        }
    }
    if (constant_opposite) {
        if (edgeIndexRunsHaveRingOpposite(order, key_run_header, records)) |opposite_mod| {
            const ring_header = key_run_header.withKeyRunRingOpposite(opposite_mod);
            if (edgeIndexBodyBytes(ring_header)) |bytes| {
                if (bytes < best_body_bytes) {
                    best_header = ring_header;
                    best_body_bytes = bytes;
                }
            }
        }
    }

    const linear_probe = header.withKeyRuns(1, constant_opposite, true);
    if (edgeIndexRunCountForHeaderShape(linear_probe, records)) |linear_run_count| {
        if (linear_run_count != 0 and linear_run_count <= std.math.maxInt(u32)) {
            const linear_header = header.withKeyRuns(@intCast(linear_run_count), constant_opposite, true);
            if (edgeIndexBodyBytes(linear_header)) |bytes| {
                if (bytes < best_body_bytes) {
                    best_header = linear_header;
                    best_body_bytes = bytes;
                }
            }
            if (constant_opposite) {
                if (edgeIndexRunsHaveRingOpposite(order, linear_header, records)) |opposite_mod| {
                    const ring_linear_header = linear_header.withKeyRunRingOpposite(opposite_mod);
                    if (edgeIndexBodyBytes(ring_linear_header)) |bytes| {
                        if (bytes < best_body_bytes) {
                            best_header = ring_linear_header;
                            best_body_bytes = bytes;
                        }
                    }
                    if (edgeIndexRunsHaveUniformEdgeIdStep(ring_linear_header, records)) |edge_id_step| {
                        const uniform_step_header = ring_linear_header.withKeyRunUniformEdgeIdStep(edge_id_step);
                        if (edgeIndexBodyBytes(uniform_step_header)) |uniform_bytes| {
                            if (uniform_bytes < best_body_bytes) {
                                best_header = uniform_step_header;
                                best_body_bytes = uniform_bytes;
                            }
                        }
                        if (edgeIndexRunsHaveDenseSpan(uniform_step_header, records)) |dense_span| {
                            const dense_span_header = uniform_step_header.withKeyRunDenseSpan(dense_span);
                            if (edgeIndexBodyBytes(dense_span_header)) |dense_span_bytes| {
                                if (dense_span_bytes < best_body_bytes) {
                                    best_header = dense_span_header;
                                    best_body_bytes = dense_span_bytes;
                                }
                            }
                        }
                    }
                }
            }
            if (edgeIndexRunsHaveUniformEdgeIdStep(linear_header, records)) |edge_id_step| {
                const uniform_step_header = linear_header.withKeyRunUniformEdgeIdStep(edge_id_step);
                if (edgeIndexBodyBytes(uniform_step_header)) |bytes| {
                    if (bytes < best_body_bytes) {
                        best_header = uniform_step_header;
                        best_body_bytes = bytes;
                    }
                }
            }
        }
    }

    return best_header;
}

fn edgeIndexHeaderWithBeneficialIdEndpointRuns(header: EdgeIndexHeader, records: []const EdgeIndexRecord) EdgeIndexHeader {
    if (header.order != .id or !header.hasDenseId() or !header.hasU32NodeIds() or header.hasKeyRuns()) return header;
    const run_count = edgeIndexIdEndpointRunCount(records) orelse return header;
    if (run_count == 0 or run_count > std.math.maxInt(u32)) return header;
    const run_bytes = std.math.mul(u64, run_count, @as(u64, 12)) catch return header;
    const row_endpoint_bytes = std.math.mul(u64, @intCast(records.len), @as(u64, 8)) catch return header;
    if (run_bytes >= row_endpoint_bytes) return header;
    return header.withKeyRuns(@intCast(run_count), true, false);
}

fn denseEdgeIdRunSummaryForHeader(header: EdgeIndexHeader) !?EdgeSegmentIdRunSummary {
    try header.validateShape();
    if (header.order != .id or !header.hasDenseId()) return null;
    if (header.edge_count == 0) return .{};
    if (header.edge_count == std.math.maxInt(u64)) return error.InvalidRecord;
    return .{
        .run_count = 1,
        .first_min = 1,
        .first_max = header.edge_count,
    };
}

fn edgeIndexIdEndpointRunCount(records: []const EdgeIndexRecord) ?u64 {
    if (records.len == 0) return 0;
    var run_count: u64 = 1;
    if (!edgeIndexIdEndpointCanStartRun(records[0])) return null;
    for (records[1..], 1..) |record, i| {
        if (!edgeIndexIdEndpointCanStartRun(record)) return null;
        const previous = records[i - 1];
        const expected_src = std.math.add(u64, previous.src, 1) catch std.math.maxInt(u64);
        const expected_dst = std.math.add(u64, previous.dst, 1) catch std.math.maxInt(u64);
        if (record.src == expected_src and record.dst == expected_dst) continue;
        run_count = std.math.add(u64, run_count, 1) catch return null;
    }
    return run_count;
}

fn edgeIndexIdEndpointCanStartRun(record: EdgeIndexRecord) bool {
    return edgeRecordHasU32NodeIds(record) and record.src != 0 and record.dst != 0;
}

fn edgeIndexRecordStartsNewRun(header: EdgeIndexHeader, records: []const EdgeIndexRecord, index: usize) !bool {
    if (!header.hasKeyRuns() or index >= records.len) return error.InvalidRecord;
    if (index == 0) return true;
    if (header.order == .id) {
        const previous = records[index - 1];
        const record = records[index];
        const expected_src = std.math.add(u64, previous.src, 1) catch return true;
        const expected_dst = std.math.add(u64, previous.dst, 1) catch return true;
        return record.src != expected_src or record.dst != expected_dst;
    }
    return edgeIndexRecordKey(records[index], header.order) != edgeIndexRecordKey(records[index - 1], header.order);
}

fn edgeIndexBodyBytes(header: EdgeIndexHeader) ?u64 {
    const directory_size = edgeIndexKeyRunDirectorySizeForHeader(header) catch return null;
    const row_bytes = std.math.mul(u64, header.edge_count, header.record_len) catch return null;
    return std.math.add(u64, directory_size, row_bytes) catch return null;
}

fn edgeIndexRunCountForHeaderShape(header: EdgeIndexHeader, records: []const EdgeIndexRecord) ?u64 {
    if (!header.hasKeyRuns() or records.len == 0) return null;
    var run_count: u64 = 0;
    var run_start: usize = 0;
    while (run_start < records.len) {
        run_count = std.math.add(u64, run_count, 1) catch return null;
        run_start = edgeIndexNextRunStartForHeaderShape(header, records, run_start) orelse return null;
    }
    return run_count;
}

fn edgeIndexRingOppositeForKey(header: EdgeIndexHeader, key: u64) !u64 {
    try header.validateShape();
    if (!header.hasKeyRunRingOpposite()) return error.InvalidRecord;
    if (key == 0 or key > header.key_run_opposite_mod) return error.InvalidRecord;
    return switch (header.order) {
        .id => error.InvalidRecord,
        .src => if (key == header.key_run_opposite_mod) 1 else key + 1,
        .dst => if (key == 1) header.key_run_opposite_mod else key - 1,
    };
}

fn edgeIndexRunsHaveRingOpposite(order: EdgeIndexOrder, header: EdgeIndexHeader, records: []const EdgeIndexRecord) ?u64 {
    if (order == .id or !header.hasKeyRuns() or !header.hasKeyRunConstantOpposite() or records.len == 0) return null;
    var max_key: u64 = 0;
    var run_start: usize = 0;
    while (run_start < records.len) {
        const key = edgeIndexRecordKey(records[run_start], order);
        if (key == 0 or key == std.math.maxInt(u64)) return null;
        if (key > max_key) max_key = key;
        run_start = edgeIndexNextRunStartForHeaderShape(header, records, run_start) orelse return null;
    }
    if (max_key < 2) return null;
    if (header.hasU32NodeIds() and max_key > std.math.maxInt(u32)) return null;

    const probe_header = header.withKeyRunRingOpposite(max_key);
    run_start = 0;
    while (run_start < records.len) {
        const run = edgeIndexRunRecordForStart(header, records, run_start) catch return null;
        const expected = edgeIndexRingOppositeForKey(probe_header, run.key) catch return null;
        if (run.opposite != expected) return null;
        run_start = edgeIndexNextRunStartForHeaderShape(header, records, run_start) orelse return null;
    }
    return max_key;
}

fn edgeIndexRunsHaveUniformEdgeIdStep(header: EdgeIndexHeader, records: []const EdgeIndexRecord) ?u64 {
    if (!header.hasKeyRuns() or !header.hasKeyRunLinearEdgeIds() or records.len == 0) return null;
    var uniform_step: u64 = 0;
    var run_start: usize = 0;
    while (run_start < records.len) {
        const step = edgeIndexRunEdgeIdStep(header, records, run_start) orelse return null;
        if (step != 0) {
            if (step > std.math.maxInt(u32)) return null;
            if (uniform_step == 0) {
                uniform_step = step;
            } else if (step != uniform_step) {
                return null;
            }
        }
        run_start = edgeIndexNextRunStartForHeaderShape(header, records, run_start) orelse return null;
    }
    if (uniform_step == 0) return null;
    return uniform_step;
}

fn edgeIndexDenseKeyRunSpanRecordForIndex(header: EdgeIndexHeader, run_index: u64) !EdgeIndexKeyRunRecord {
    try header.validateShape();
    if (!header.hasKeyRunDenseSpan() or run_index < header.key_run_dense_run_start) return error.InvalidRecord;
    const dense_index = run_index - header.key_run_dense_run_start;
    if (dense_index >= header.key_run_dense_count) return error.InvalidRecord;
    const key = std.math.add(u64, header.key_run_dense_key_base, dense_index) catch return error.InvalidRecord;
    const start_delta = std.math.mul(u64, dense_index, header.key_run_dense_start_step) catch return error.InvalidRecord;
    const start = std.math.add(u64, header.key_run_dense_start_base, start_delta) catch return error.InvalidRecord;
    const edge_id_delta = std.math.mul(u64, dense_index, header.key_run_dense_edge_id_base_step) catch return error.InvalidRecord;
    const edge_id_base = std.math.add(u64, header.key_run_dense_edge_id_base, edge_id_delta) catch return error.InvalidRecord;
    return .{
        .key = key,
        .start = start,
        .opposite = try edgeIndexRingOppositeForKey(header, key),
        .edge_id_base = edge_id_base,
        .edge_id_step = header.key_run_edge_id_step,
    };
}

fn edgeIndexKeyRunRecordsEquivalent(header: EdgeIndexHeader, expected: EdgeIndexKeyRunRecord, actual: EdgeIndexKeyRunRecord) bool {
    if (expected.key != actual.key or expected.start != actual.start or expected.opposite != actual.opposite) return false;
    if (header.hasKeyRunLinearEdgeIds()) {
        if (expected.edge_id_base != actual.edge_id_base) return false;
        if (actual.edge_id_step != 0 and expected.edge_id_step != actual.edge_id_step) return false;
    }
    return true;
}

fn edgeIndexRunsHaveDenseSpan(header: EdgeIndexHeader, records: []const EdgeIndexRecord) ?EdgeIndexDenseKeyRunSpan {
    if (!header.hasKeyRunRingOpposite() or !header.hasKeyRunUniformEdgeIdStep()) return null;
    if (!header.hasU32NodeIds() or !header.hasU32EdgeIds()) return null;
    if (records.len == 0) return null;

    var best: ?EdgeIndexDenseKeyRunSpan = null;
    var best_score: u64 = 0;
    var span_start_index: u64 = 0;
    var span_start = edgeIndexRunRecordForStart(header, records, 0) catch return null;
    var previous = span_start;
    var span_count: u64 = 1;
    var start_step: u64 = 0;
    var edge_id_base_step: u64 = 0;

    var run_start: usize = 0;
    var run_index: u64 = 0;
    while (true) {
        const next_start = edgeIndexNextRunStartForHeaderShape(header, records, run_start) orelse return null;
        if (next_start >= records.len) break;
        const next = edgeIndexRunRecordForStart(header, records, next_start) catch return null;
        const continues = next.key == previous.key + 1 and
            next.start > previous.start and
            next.edge_id_base > previous.edge_id_base and
            (next.edge_id_step == 0 or next.edge_id_step == header.key_run_edge_id_step);
        if (continues) {
            const next_start_step = next.start - previous.start;
            const next_edge_base_step = next.edge_id_base - previous.edge_id_base;
            if (span_count == 1) {
                start_step = next_start_step;
                edge_id_base_step = next_edge_base_step;
                span_count = 2;
            } else if (next_start_step == start_step and next_edge_base_step == edge_id_base_step) {
                span_count += 1;
            } else {
                best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
                span_start_index = run_index;
                span_start = previous;
                start_step = next_start_step;
                edge_id_base_step = next_edge_base_step;
                span_count = 2;
            }
        } else {
            best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
            span_start_index = run_index + 1;
            span_start = next;
            start_step = 0;
            edge_id_base_step = 0;
            span_count = 1;
        }
        previous = next;
        run_start = next_start;
        run_index += 1;
    }
    best = edgeIndexMaybeBetterDenseKeyRunSpan(best, &best_score, span_start_index, span_start, span_count, start_step, edge_id_base_step);
    return best;
}

fn edgeIndexMaybeBetterDenseKeyRunSpan(current: ?EdgeIndexDenseKeyRunSpan, best_score: *u64, run_start: u64, first: EdgeIndexKeyRunRecord, count: u64, start_step: u64, edge_id_base_step: u64) ?EdgeIndexDenseKeyRunSpan {
    if (count < 2 or count > std.math.maxInt(u32)) return current;
    if (run_start > std.math.maxInt(u32)) return current;
    if (first.key == 0 or first.key > std.math.maxInt(u32)) return current;
    if (first.start > std.math.maxInt(u32)) return current;
    if (first.edge_id_base == 0 or first.edge_id_base > std.math.maxInt(u32)) return current;
    if (start_step == 0 or start_step > std.math.maxInt(u32)) return current;
    if (edge_id_base_step == 0 or edge_id_base_step > std.math.maxInt(u32)) return current;
    const score = count;
    if (score <= best_score.*) return current;
    best_score.* = score;
    return .{
        .run_start = run_start,
        .count = count,
        .key_base = first.key,
        .start_base = first.start,
        .start_step = start_step,
        .edge_id_base = first.edge_id_base,
        .edge_id_base_step = edge_id_base_step,
    };
}

fn edgeIndexNextRunStartForHeaderShape(header: EdgeIndexHeader, records: []const EdgeIndexRecord, run_start: usize) ?usize {
    if (!header.hasKeyRuns() or run_start >= records.len) return null;
    var index = run_start + 1;
    while (index < records.len and edgeIndexRecordContinuesRunForHeaderShape(header, records, run_start, index)) : (index += 1) {}
    return index;
}

fn edgeIndexRecordContinuesRunForHeaderShape(header: EdgeIndexHeader, records: []const EdgeIndexRecord, run_start: usize, index: usize) bool {
    if (!header.hasKeyRuns() or run_start >= records.len or index <= run_start or index >= records.len) return false;
    if (header.order == .id) {
        const previous = records[index - 1];
        const record = records[index];
        const expected_src = std.math.add(u64, previous.src, 1) catch return false;
        const expected_dst = std.math.add(u64, previous.dst, 1) catch return false;
        return record.src == expected_src and record.dst == expected_dst;
    }

    const key = edgeIndexRecordKey(records[run_start], header.order);
    if (key == 0 or key == std.math.maxInt(u64)) return false;
    if (edgeIndexRecordKey(records[index], header.order) != key) return false;
    if (header.hasKeyRunConstantOpposite()) {
        const run_opposite = edgeIndexRecordOpposite(records[run_start], header.order) orelse return false;
        const current_opposite = edgeIndexRecordOpposite(records[index], header.order) orelse return false;
        if (run_opposite == 0 or run_opposite == std.math.maxInt(u64)) return false;
        if (current_opposite != run_opposite) return false;
    }
    if (!header.hasKeyRunLinearEdgeIds()) return true;

    const base = records[run_start].edge_id;
    const current = records[index].edge_id;
    if (base == 0 or base == std.math.maxInt(u64)) return false;
    if (current == 0 or current == std.math.maxInt(u64)) return false;
    if (index == run_start + 1) return current > base;
    const second = records[run_start + 1].edge_id;
    if (second <= base or second == std.math.maxInt(u64)) return false;
    const step = second - base;
    const delta: u64 = @intCast(index - run_start);
    const scaled_delta = std.math.mul(u64, delta, step) catch return false;
    const expected = std.math.add(u64, base, scaled_delta) catch return false;
    return current == expected;
}

fn edgeIndexRunRecordForStart(header: EdgeIndexHeader, records: []const EdgeIndexRecord, run_start: usize) !EdgeIndexKeyRunRecord {
    if (!header.hasKeyRuns() or run_start >= records.len) return error.InvalidRecord;
    const record = records[run_start];
    if (header.order == .id) {
        return .{
            .key = record.src,
            .start = @intCast(run_start),
            .opposite = record.dst,
        };
    }
    return .{
        .key = edgeIndexRecordKey(record, header.order),
        .start = @intCast(run_start),
        .opposite = if (header.hasKeyRunConstantOpposite()) edgeIndexRunOpposite(header.order, records, run_start) orelse return error.InvalidRecord else 0,
        .edge_id_base = if (header.hasKeyRunLinearEdgeIds()) record.edge_id else 0,
        .edge_id_step = if (header.hasKeyRunLinearEdgeIds()) edgeIndexRunEdgeIdStep(header, records, run_start) orelse return error.InvalidRecord else 0,
    };
}

fn edgeIndexRunCountForSortedRecords(order: EdgeIndexOrder, records: []const EdgeIndexRecord) ?u64 {
    if (order == .id or records.len == 0) return 0;
    var run_count: u64 = 1;
    var previous_key = edgeIndexRecordKey(records[0], order);
    if (previous_key == 0 or previous_key == std.math.maxInt(u64)) return null;
    for (records[1..]) |record| {
        const key = edgeIndexRecordKey(record, order);
        if (key == 0 or key == std.math.maxInt(u64)) return null;
        if (key < previous_key) return null;
        if (key != previous_key) {
            run_count = std.math.add(u64, run_count, 1) catch return null;
            previous_key = key;
        }
    }
    return run_count;
}

fn edgeIndexRunsHaveConstantOpposite(order: EdgeIndexOrder, records: []const EdgeIndexRecord) bool {
    if (order == .id or records.len == 0) return false;
    var previous_key = edgeIndexRecordKey(records[0], order);
    if (previous_key == 0 or previous_key == std.math.maxInt(u64)) return false;
    var run_opposite = edgeIndexRecordOpposite(records[0], order) orelse return false;
    if (run_opposite == 0 or run_opposite == std.math.maxInt(u64)) return false;
    for (records[1..]) |record| {
        const key = edgeIndexRecordKey(record, order);
        if (key == 0 or key == std.math.maxInt(u64) or key < previous_key) return false;
        const opposite = edgeIndexRecordOpposite(record, order) orelse return false;
        if (opposite == 0 or opposite == std.math.maxInt(u64)) return false;
        if (key != previous_key) {
            previous_key = key;
            run_opposite = opposite;
        } else if (opposite != run_opposite) {
            return false;
        }
    }
    return true;
}

fn edgeIndexRunOpposite(order: EdgeIndexOrder, records: []const EdgeIndexRecord, run_start: usize) ?u64 {
    if (order == .id or run_start >= records.len) return null;
    return edgeIndexRecordOpposite(records[run_start], order);
}

fn edgeIndexRunEdgeIdStep(header: EdgeIndexHeader, records: []const EdgeIndexRecord, run_start: usize) ?u64 {
    if (header.order == .id or run_start >= records.len) return null;
    const key = edgeIndexRecordKey(records[run_start], header.order);
    if (key == 0 or key == std.math.maxInt(u64)) return null;
    if (run_start + 1 >= records.len) return 0;
    if (!edgeIndexRecordContinuesRunForHeaderShape(header, records, run_start, run_start + 1)) return 0;
    if (records[run_start + 1].edge_id <= records[run_start].edge_id) return null;
    return records[run_start + 1].edge_id - records[run_start].edge_id;
}

fn edgeIndexRecordOpposite(record: EdgeIndexRecord, order: EdgeIndexOrder) ?u64 {
    return switch (order) {
        .id => null,
        .src => record.dst,
        .dst => record.src,
    };
}

fn validateAdjacentEdgeIndexKeyRuns(header: EdgeIndexHeader, current: EdgeIndexKeyRunRecord, next: EdgeIndexKeyRunRecord) !void {
    if (next.start <= current.start) return error.InvalidRecord;
    if (header.order == .id) return;
    if (next.key < current.key) return error.InvalidRecord;
    if (next.key == current.key and !header.hasKeyRunLinearEdgeIds()) return error.InvalidRecord;
    if (next.key == current.key and header.hasKeyRunConstantOpposite() and next.opposite != current.opposite) return error.InvalidRecord;
    if (next.key == current.key and header.hasKeyRunLinearEdgeIds()) {
        if (current.edge_id_step != 0) {
            const last_delta = next.start - current.start - 1;
            const last_scaled_delta = std.math.mul(u64, last_delta, current.edge_id_step) catch return error.InvalidRecord;
            const last_edge_id = std.math.add(u64, current.edge_id_base, last_scaled_delta) catch return error.InvalidRecord;
            if (next.edge_id_base >= current.edge_id_base and next.edge_id_base <= last_edge_id) {
                const offset = next.edge_id_base - current.edge_id_base;
                if (offset % current.edge_id_step == 0) return error.InvalidRecord;
            }
        } else if (next.edge_id_base == current.edge_id_base) {
            return error.InvalidRecord;
        }
    }
}

fn nodeTextLenFitsU16(text_len: usize) bool {
    return text_len != 0 and text_len <= std.math.maxInt(u16);
}

fn nodeRecordHasShortTextLen(record: NodeByIdRecord) bool {
    return record.id == 0 or record.text_len <= std.math.maxInt(u16);
}

const edge_index_rel_kind_count = schema.max_relation_types;

fn edgeIndexDefaultRelFromCounts(counts: [edge_index_rel_kind_count]u64, total: u64) ?u16 {
    if (total == 0) return null;
    var best_index: usize = 0;
    var best_count: u64 = 0;
    for (counts, 0..) |count, index| {
        if (count > best_count) {
            best_count = count;
            best_index = index;
        }
    }
    if (best_count == 0 or total - best_count > 2) return null;
    const best_rel: u16 = @intCast(best_index);
    if (relKindFromInt(best_rel) == null) return null;
    return best_rel;
}

fn edgeIndexRelDerivationAddException(derivation: *EdgeIndexRelDerivation, edge_id: u64, rel: u16) bool {
    if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return false;
    if (relKindFromInt(rel) == null or rel == derivation.default_rel) return false;
    if (derivation.exception_count >= derivation.exception_edge_ids.len) return false;
    var insert_at: usize = derivation.exception_count;
    var pos: usize = 0;
    while (pos < derivation.exception_count) : (pos += 1) {
        const existing_id = derivation.exception_edge_ids[pos];
        if (edge_id == existing_id) return false;
        if (edge_id < existing_id) {
            insert_at = pos;
            break;
        }
    }
    var move_pos: usize = derivation.exception_count;
    while (move_pos > insert_at) : (move_pos -= 1) {
        derivation.exception_edge_ids[move_pos] = derivation.exception_edge_ids[move_pos - 1];
        derivation.exception_rels[move_pos] = derivation.exception_rels[move_pos - 1];
    }
    derivation.exception_edge_ids[insert_at] = edge_id;
    derivation.exception_rels[insert_at] = rel;
    derivation.exception_count += 1;
    return true;
}

fn edgeRecordsDerivedRel(records: []const EdgeIndexRecord) ?EdgeIndexRelDerivation {
    var counts: [edge_index_rel_kind_count]u64 = [_]u64{0} ** edge_index_rel_kind_count;
    for (records) |record| {
        const rel_kind = relKindFromInt(record.rel) orelse return null;
        counts[@intFromEnum(rel_kind)] += 1;
    }
    const default_rel = edgeIndexDefaultRelFromCounts(counts, @intCast(records.len)) orelse return null;
    var derivation = EdgeIndexRelDerivation{ .default_rel = default_rel };
    for (records) |record| {
        if (record.rel != default_rel and !edgeIndexRelDerivationAddException(&derivation, record.edge_id, record.rel)) return null;
    }
    return derivation;
}

fn edgeRecordsExtendDerivedRel(header: EdgeIndexHeader, records: []const EdgeIndexRecord) ?EdgeIndexRelDerivation {
    if (!header.hasDerivedRel()) return null;
    var derivation = EdgeIndexRelDerivation{
        .default_rel = header.default_rel,
        .exception_count = header.rel_exception_count,
        .exception_edge_ids = header.rel_exception_edge_ids,
        .exception_rels = header.rel_exception_rels,
    };
    for (records) |record| {
        if (record.rel == derivation.default_rel) continue;
        var existing = false;
        var pos: usize = 0;
        while (pos < derivation.exception_count) : (pos += 1) {
            if (record.edge_id == derivation.exception_edge_ids[pos]) {
                if (record.rel != derivation.exception_rels[pos]) return null;
                existing = true;
                break;
            }
        }
        if (!existing and !edgeIndexRelDerivationAddException(&derivation, record.edge_id, record.rel)) return null;
    }
    return derivation;
}

fn edgeIndexRelDerivationWithoutRecord(header: EdgeIndexHeader, removed: EdgeIndexRecord, next_count: u64) ?EdgeIndexRelDerivation {
    if (!header.hasDerivedRel() or next_count == 0) return null;
    var derivation = EdgeIndexRelDerivation{
        .default_rel = header.default_rel,
        .exception_count = 0,
    };
    var pos: usize = 0;
    while (pos < header.rel_exception_count) : (pos += 1) {
        if (header.rel_exception_edge_ids[pos] == removed.edge_id) continue;
        if (!edgeIndexRelDerivationAddException(&derivation, header.rel_exception_edge_ids[pos], header.rel_exception_rels[pos])) return null;
    }
    return derivation;
}

fn edgeIndexRecordToSegmentEdge(record: EdgeIndexRecord) !segment_mod.EdgeRecord {
    return .{
        .src = core.NodeId.fromInt(record.src),
        .dst = core.NodeId.fromInt(record.dst),
        .edge_id = core.EdgeId.fromInt(record.edge_id),
        .rel = try record.relKind(),
    };
}

const EdgeIndexRecordReader = struct {
    store: Store,
    file: std.Io.File,
    map: ?std.Io.File.MemoryMap = null,
    header: EdgeIndexHeader,
    edge_count: u64,

    fn deinit(self: *EdgeIndexRecordReader) void {
        if (self.map) |*map| map.destroy(self.store.io);
        self.file.close(self.store.io);
    }

    fn read(self: *EdgeIndexRecordReader, index: u64) !EdgeIndexRecord {
        if (index >= self.edge_count) return error.InvalidRecord;
        if (self.map) |*map| return Store.readEdgeIndexRecordFromMap(self.header, map, index);
        return self.store.readEdgeIndexRecordAt(self.file, self.header, index);
    }
};

fn edgeIndexReaderRecordToSegmentEdge(reader: *EdgeIndexRecordReader, index: u64) !segment_mod.EdgeRecord {
    return edgeIndexRecordToSegmentEdge(try reader.read(index));
}

const StoreTextsFileStream = struct {
    allocator: std.mem.Allocator,
    texts: Store.NodeTextsView,
    buffer: []u8,
    size: u64,
    offset: u64 = 0,

    fn init(allocator: std.mem.Allocator, store: Store) !StoreTextsFileStream {
        var texts = try Store.NodeTextsView.open(store);
        errdefer texts.deinit();
        if (texts.size == 0) return error.InvalidRecord;
        return .{
            .allocator = allocator,
            .texts = texts,
            .buffer = try allocator.alloc(u8, try storageWriteBufferCapacity(texts.size)),
            .size = texts.size,
        };
    }

    fn deinit(self: *StoreTextsFileStream) void {
        self.allocator.free(self.buffer);
        self.texts.deinit();
    }

    fn reset(self: *StoreTextsFileStream) !void {
        self.offset = 0;
    }

    fn next(self: *StoreTextsFileStream) !?[]const u8 {
        if (self.offset >= self.size) return null;
        const remaining = self.size - self.offset;
        const want = @min(self.buffer.len, std.math.cast(usize, remaining) orelse self.buffer.len);
        try self.texts.readInto(self.offset, self.buffer[0..want]);
        self.offset = std.math.add(u64, self.offset, want) catch return error.RecordTooLarge;
        return self.buffer[0..want];
    }
};

const StoreCatalogByIdStream = struct {
    view: Store.NodeByIdIndexView,
    next_id: u64 = 1,
    seen_nodes: u64 = 0,

    fn init(store: Store, meta: IndexMeta) !StoreCatalogByIdStream {
        return .{ .view = try Store.NodeByIdIndexView.open(store, meta) };
    }

    fn deinit(self: *StoreCatalogByIdStream) void {
        self.view.deinit();
    }

    fn reset(self: *StoreCatalogByIdStream) !void {
        self.next_id = 1;
        self.seen_nodes = 0;
    }

    fn next(self: *StoreCatalogByIdStream) !?segment_node_index.CatalogRecord {
        while (self.next_id <= self.view.max_node_id) : (self.next_id += 1) {
            const id = self.next_id;
            const record = try self.view.readRecord(id);
            if (record.id == 0) continue;
            if (record.id != id) return error.InvalidRecord;
            if (self.seen_nodes >= self.view.node_count) return error.InvalidRecord;
            self.seen_nodes += 1;
            self.next_id += 1;
            return try nodeByIdRecordToCatalogRecord(record);
        }
        if (self.seen_nodes != self.view.node_count) return error.InvalidRecord;
        return null;
    }
};

const StoreEdgeRecordStream = struct {
    reader: *EdgeIndexRecordReader,
    tombstones: ?*Store.EdgeTombstoneIndexView = null,
    pos: u64 = 0,

    fn reset(self: *StoreEdgeRecordStream) !void {
        self.pos = 0;
    }

    fn next(self: *StoreEdgeRecordStream) !?segment_mod.EdgeRecord {
        while (self.pos < self.reader.edge_count) {
            const edge = try edgeIndexReaderRecordToSegmentEdge(self.reader, self.pos);
            self.pos += 1;
            if (self.tombstones) |tombstones| {
                if (try tombstones.contains(edge.edge_id.toInt())) continue;
            }
            return edge;
        }
        return null;
    }
};

const EdgeSortedRunStream = struct {
    allocator: std.mem.Allocator,
    store: Store,
    order: EdgeIndexOrder,
    run_paths: []const []u8,
    readers: std.ArrayList(Store.EdgeRepairRunReader) = .empty,
    queue: std.PriorityQueue(Store.EdgeRepairRunHeapEntry, Store.EdgeRepairRunHeapContext, Store.compareEdgeRepairRunHeapEntry),

    fn init(
        allocator: std.mem.Allocator,
        store: Store,
        order: EdgeIndexOrder,
        run_paths: []const []u8,
    ) EdgeSortedRunStream {
        return .{
            .allocator = allocator,
            .store = store,
            .order = order,
            .run_paths = run_paths,
            .queue = std.PriorityQueue(Store.EdgeRepairRunHeapEntry, Store.EdgeRepairRunHeapContext, Store.compareEdgeRepairRunHeapEntry).initContext(.{ .order = order }),
        };
    }

    fn deinit(self: *EdgeSortedRunStream) void {
        self.clearReaders();
        self.readers.deinit(self.allocator);
        self.queue.deinit(self.allocator);
    }

    fn clearReaders(self: *EdgeSortedRunStream) void {
        for (self.readers.items) |*reader| reader.deinit(self.allocator, self.store.io);
        self.readers.clearRetainingCapacity();
    }

    fn reset(self: *EdgeSortedRunStream) !void {
        self.clearReaders();
        self.queue.deinit(self.allocator);
        self.queue = std.PriorityQueue(Store.EdgeRepairRunHeapEntry, Store.EdgeRepairRunHeapContext, Store.compareEdgeRepairRunHeapEntry).initContext(.{ .order = self.order });
        try self.readers.ensureTotalCapacityPrecise(self.allocator, self.run_paths.len);
        try self.queue.ensureTotalCapacityPrecise(self.allocator, self.run_paths.len);

        for (self.run_paths) |run_path| {
            var run_file = try std.Io.Dir.cwd().openFile(self.store.io, run_path, .{});
            var close_run_file = true;
            errdefer if (close_run_file) run_file.close(self.store.io);
            const run_size = try self.store.regularFileSize(run_file);
            if (run_size == 0 or run_size % EdgeIndexRecord.encoded_len != 0) return error.InvalidRecord;
            const run_count = run_size / EdgeIndexRecord.encoded_len;
            var map = Store.openReadOnlyMemoryMap(self.store.io, run_file, run_size) catch null;
            errdefer if (map) |*mapped| mapped.destroy(self.store.io);
            var buffer: []u8 = &.{};
            errdefer self.allocator.free(buffer);
            if (map == null) {
                buffer = try self.allocator.alloc(u8, try storageWriteBufferCapacity(run_size));
            }
            const reader_index = self.readers.items.len;
            self.readers.appendAssumeCapacity(.{
                .file = run_file,
                .map = map,
                .next_index = 0,
                .count = run_count,
                .buffer = buffer,
            });
            close_run_file = false;
            map = null;
            buffer = &.{};
            const record = (try self.readers.items[reader_index].next(self.store)) orelse return error.InvalidRecord;
            try self.queue.push(self.allocator, .{ .run_index = reader_index, .record = record });
        }
    }

    fn next(self: *EdgeSortedRunStream) !?segment_mod.EdgeRecord {
        const entry = self.queue.pop() orelse return null;
        const reader = &self.readers.items[entry.run_index];
        if (try reader.next(self.store)) |record| {
            try self.queue.push(self.allocator, .{ .run_index = entry.run_index, .record = record });
        }
        return try edgeIndexRecordToSegmentEdge(entry.record);
    }
};

const EdgeSortedRecordSliceStream = struct {
    records: []const EdgeIndexRecord,
    pos: usize = 0,

    fn init(records: []const EdgeIndexRecord) EdgeSortedRecordSliceStream {
        return .{ .records = records };
    }

    fn reset(self: *EdgeSortedRecordSliceStream) !void {
        self.pos = 0;
    }

    fn next(self: *EdgeSortedRecordSliceStream) !?segment_mod.EdgeRecord {
        if (self.pos >= self.records.len) return null;
        const record = self.records[self.pos];
        self.pos += 1;
        return try edgeIndexRecordToSegmentEdge(record);
    }
};

const EdgeSortedRecordOrderStream = struct {
    records: []const EdgeIndexRecord,
    order: []const u32,
    pos: usize = 0,

    fn init(records: []const EdgeIndexRecord, order: []const u32) EdgeSortedRecordOrderStream {
        return .{ .records = records, .order = order };
    }

    fn reset(self: *EdgeSortedRecordOrderStream) !void {
        self.pos = 0;
    }

    fn next(self: *EdgeSortedRecordOrderStream) !?segment_mod.EdgeRecord {
        if (self.pos >= self.order.len) return null;
        const index = self.order[self.pos];
        self.pos += 1;
        if (index >= self.records.len) return error.InvalidRecord;
        return try edgeIndexRecordToSegmentEdge(self.records[@intCast(index)]);
    }
};

const StoreSegmentBundleExactRuns = struct {
    allocator: std.mem.Allocator,
    store: Store,
    paths: std.ArrayList([]u8) = .empty,

    fn build(store: Store, root_dir: []const u8, meta: IndexMeta) !StoreSegmentBundleExactRuns {
        var runs = StoreSegmentBundleExactRuns{
            .allocator = store.allocator,
            .store = store,
        };
        errdefer runs.deinit();

        var texts = try Store.NodeTextsView.open(store);
        defer texts.deinit();
        var by_id = try StoreCatalogByIdStream.init(store, meta);
        defer by_id.deinit();
        var chunk = SegmentBundleExactSortChunk{};
        defer chunk.deinit(store.allocator);
        try chunk.ensureTotalCapacityPrecise(store.allocator, segment_bundle_exact_sort_chunk_records);

        while (try by_id.next()) |record| {
            try chunk.append(store.allocator, &texts, record);
            if (chunk.entries.items.len == segment_bundle_exact_sort_chunk_records) try runs.flush(root_dir, &chunk);
        }
        try runs.flush(root_dir, &chunk);
        if (runs.paths.items.len == 0) return error.InvalidRecord;
        return runs;
    }

    fn deinit(self: *StoreSegmentBundleExactRuns) void {
        for (self.paths.items) |path| {
            std.Io.Dir.cwd().deleteFile(self.store.io, path) catch {};
            self.allocator.free(path);
        }
        self.paths.deinit(self.allocator);
    }

    fn flush(self: *StoreSegmentBundleExactRuns, root_dir: []const u8, chunk: *SegmentBundleExactSortChunk) !void {
        if (chunk.entries.items.len == 0) return;
        std.mem.sort(SegmentBundleExactSortEntry, chunk.entries.items, chunk.texts.items, segmentBundleExactSortEntryLessThan);
        for (chunk.entries.items[1..], chunk.entries.items[0 .. chunk.entries.items.len - 1]) |entry, previous| {
            if (!segmentBundleExactSortEntryLessThan(chunk.texts.items, previous, entry)) return error.InvalidRecord;
        }

        const run_path = try std.fmt.allocPrint(self.allocator, "{s}/.segment-bundle-exact-{d}.tmp", .{ root_dir, self.paths.items.len });
        var run_path_owned = true;
        errdefer {
            std.Io.Dir.cwd().deleteFile(self.store.io, run_path) catch {};
            if (run_path_owned) self.allocator.free(run_path);
        }

        try writeSegmentBundleExactRunFile(self.allocator, self.store.io, run_path, chunk.entries.items);
        try self.paths.append(self.allocator, run_path);
        run_path_owned = false;

        chunk.clearRetainingCapacity();
        try chunk.ensureTotalCapacityPrecise(self.allocator, segment_bundle_exact_sort_chunk_records);
    }
};

const SegmentBundleExactSortChunk = struct {
    entries: std.ArrayList(SegmentBundleExactSortEntry) = .empty,
    texts: std.ArrayList(u8) = .empty,

    fn deinit(self: *SegmentBundleExactSortChunk, allocator: std.mem.Allocator) void {
        self.texts.deinit(allocator);
        self.entries.deinit(allocator);
    }

    fn ensureTotalCapacityPrecise(self: *SegmentBundleExactSortChunk, allocator: std.mem.Allocator, entry_count: usize) !void {
        try self.entries.ensureTotalCapacityPrecise(allocator, entry_count);
    }

    fn append(
        self: *SegmentBundleExactSortChunk,
        allocator: std.mem.Allocator,
        texts_view: *const Store.NodeTextsView,
        record: segment_node_index.CatalogRecord,
    ) !void {
        const span = try appendSegmentBundleExactSortText(allocator, texts_view, record, &self.texts);
        errdefer self.texts.shrinkRetainingCapacity(span.offset);
        try self.entries.append(allocator, .{
            .record = record,
            .text_offset = span.offset,
            .text_len = span.len,
        });
    }

    fn clearRetainingCapacity(self: *SegmentBundleExactSortChunk) void {
        self.entries.clearRetainingCapacity();
        self.texts.clearRetainingCapacity();
    }
};

const SegmentBundleExactSortEntry = struct {
    record: segment_node_index.CatalogRecord,
    text_offset: usize,
    text_len: usize,
};

fn segmentBundleExactSortEntryLessThan(texts: []const u8, left: SegmentBundleExactSortEntry, right: SegmentBundleExactSortEntry) bool {
    const kind_order = std.math.order(@intFromEnum(left.record.kind), @intFromEnum(right.record.kind));
    if (kind_order != .eq) return kind_order == .lt;
    const text_order = std.mem.order(u8, segmentBundleExactSortText(texts, left), segmentBundleExactSortText(texts, right));
    if (text_order != .eq) return text_order == .lt;
    return left.record.id.toInt() < right.record.id.toInt();
}

fn segmentBundleExactSortText(texts: []const u8, entry: SegmentBundleExactSortEntry) []const u8 {
    return texts[entry.text_offset .. entry.text_offset + entry.text_len];
}

const SegmentBundleExactTextSpan = struct {
    offset: usize,
    len: usize,
};

fn appendSegmentBundleExactSortText(
    allocator: std.mem.Allocator,
    texts: *const Store.NodeTextsView,
    record: segment_node_index.CatalogRecord,
    out: *std.ArrayList(u8),
) !SegmentBundleExactTextSpan {
    const len = std.math.cast(usize, record.text_len) orelse return error.RecordTooLarge;
    const offset = out.items.len;
    const end = std.math.add(usize, offset, len) catch return error.RecordTooLarge;
    if (try texts.mappedBytes(record.text_offset, record.text_len)) |bytes| {
        try out.appendSlice(allocator, bytes);
    } else {
        try out.resize(allocator, end);
        errdefer out.shrinkRetainingCapacity(offset);
        const dst = out.items[offset..end];
        try texts.readInto(record.text_offset, dst);
    }
    const text = out.items[offset..end];
    if (std.mem.indexOfScalar(u8, text, 0) != null) return error.InvalidRecord;
    return .{ .offset = offset, .len = len };
}

fn nodeByIdRecordToCatalogRecord(record: NodeByIdRecord) !segment_node_index.CatalogRecord {
    return .{
        .id = core.NodeId.fromInt(record.id),
        .kind = try record.nodeKind(),
        .text_offset = record.text_offset,
        .text_len = record.text_len,
    };
}

fn readSegmentBundleExactTextIntoBuffer(
    allocator: std.mem.Allocator,
    texts: *const Store.NodeTextsView,
    record: segment_node_index.CatalogRecord,
    out: *std.ArrayList(u8),
) !void {
    const len = std.math.cast(usize, record.text_len) orelse return error.RecordTooLarge;
    out.clearRetainingCapacity();
    try out.resize(allocator, len);
    errdefer out.clearRetainingCapacity();
    try readSegmentBundleExactTextIntoSlice(texts, record, out.items);
}

fn readSegmentBundleExactTextIntoSlice(
    texts: *const Store.NodeTextsView,
    record: segment_node_index.CatalogRecord,
    text: []u8,
) !void {
    if (text.len != record.text_len) return error.InvalidRecord;
    if (try texts.mappedBytes(record.text_offset, record.text_len)) |bytes| {
        @memcpy(text, bytes);
    } else {
        try texts.readInto(record.text_offset, text);
    }
    if (std.mem.indexOfScalar(u8, text, 0) != null) return error.InvalidRecord;
}

fn writeSegmentBundleExactRunFile(
    allocator: std.mem.Allocator,
    io: std.Io,
    path: []const u8,
    entries: []const SegmentBundleExactSortEntry,
) !void {
    const file_size = std.math.mul(u64, entries.len, SegmentBundleExactRunRecord.encoded_len) catch return error.RecordTooLarge;
    var file = try std.Io.Dir.cwd().createFile(io, path, .{ .read = true, .truncate = true });
    defer file.close(io);
    var writer = try StorageBufferedWriter.init(allocator, io, file, try storageWriteBufferCapacity(file_size));
    defer writer.deinit();
    var bytes: [SegmentBundleExactRunRecord.encoded_len]u8 = undefined;
    for (entries) |entry| {
        SegmentBundleExactRunRecord.encode(entry.record, &bytes);
        try writer.append(&bytes);
    }
    try writer.flush();
    try file.sync(io);
    const stat = try file.stat(io);
    if (stat.kind != .file or stat.size != file_size) return error.InvalidRecord;
}

const SegmentBundleExactRunRecord = struct {
    const encoded_len: usize = 32;

    fn encode(record: segment_node_index.CatalogRecord, out: *[encoded_len]u8) void {
        std.mem.writeInt(u64, out[0..8], record.id.toInt(), .little);
        std.mem.writeInt(u16, out[8..10], @intFromEnum(record.kind), .little);
        @memset(out[10..16], 0);
        std.mem.writeInt(u64, out[16..24], record.text_offset, .little);
        std.mem.writeInt(u32, out[24..28], record.text_len, .little);
        @memset(out[28..32], 0);
    }

    fn decode(bytes: []const u8) !segment_node_index.CatalogRecord {
        if (bytes.len != encoded_len) return error.InvalidRecord;
        if (!allZero(bytes[10..16]) or !allZero(bytes[28..32])) return error.InvalidRecord;
        const id = std.mem.readInt(u64, bytes[0..8], .little);
        const kind_int = std.mem.readInt(u16, bytes[8..10], .little);
        const text_offset = std.mem.readInt(u64, bytes[16..24], .little);
        const text_len = std.mem.readInt(u32, bytes[24..28], .little);
        if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
        return .{
            .id = core.NodeId.fromInt(id),
            .kind = nodeKindFromInt(kind_int) orelse return error.InvalidRecord,
            .text_offset = text_offset,
            .text_len = text_len,
        };
    }
};

const SegmentBundleExactRunReader = struct {
    store: Store,
    file: std.Io.File,
    map: ?std.Io.File.MemoryMap = null,
    count: u64,
    pos: u64 = 0,

    fn open(store: Store, path: []const u8) !SegmentBundleExactRunReader {
        var file = try std.Io.Dir.cwd().openFile(store.io, path, .{});
        errdefer file.close(store.io);
        const stat = try file.stat(store.io);
        if (stat.kind != .file or stat.size == 0 or stat.size % SegmentBundleExactRunRecord.encoded_len != 0) return error.InvalidRecord;
        var map = Store.openReadOnlyMemoryMap(store.io, file, stat.size) catch null;
        errdefer if (map) |*mapped| mapped.destroy(store.io);
        return .{
            .store = store,
            .file = file,
            .map = map,
            .count = stat.size / SegmentBundleExactRunRecord.encoded_len,
        };
    }

    fn deinit(self: *SegmentBundleExactRunReader) void {
        if (self.map) |*map| map.destroy(self.store.io);
        self.file.close(self.store.io);
    }

    fn next(self: *SegmentBundleExactRunReader) !?segment_node_index.CatalogRecord {
        if (self.pos >= self.count) return null;
        const offset = std.math.mul(u64, self.pos, SegmentBundleExactRunRecord.encoded_len) catch return error.RecordTooLarge;
        self.pos += 1;
        if (self.map) |*map| {
            const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
            const end = std.math.add(usize, start, SegmentBundleExactRunRecord.encoded_len) catch return error.InvalidRecord;
            if (end > map.memory.len) return error.InvalidRecord;
            return try SegmentBundleExactRunRecord.decode(map.memory[start..end]);
        }
        var bytes: [SegmentBundleExactRunRecord.encoded_len]u8 = undefined;
        if (try self.file.readPositionalAll(self.store.io, &bytes, offset) != bytes.len) return error.InvalidRecord;
        return try SegmentBundleExactRunRecord.decode(&bytes);
    }
};

const StoreSegmentBundleExactStream = struct {
    allocator: std.mem.Allocator,
    store: Store,
    run_paths: []const []u8,
    merger: ?SegmentBundleExactRunMerger = null,

    fn init(allocator: std.mem.Allocator, store: Store, run_paths: []const []u8) StoreSegmentBundleExactStream {
        return .{ .allocator = allocator, .store = store, .run_paths = run_paths };
    }

    fn deinit(self: *StoreSegmentBundleExactStream) void {
        if (self.merger) |*merger| merger.deinit();
    }

    fn reset(self: *StoreSegmentBundleExactStream) !void {
        if (self.merger) |*merger| merger.deinit();
        self.merger = null;
        self.merger = try SegmentBundleExactRunMerger.init(self.allocator, self.store, self.run_paths);
    }

    fn next(self: *StoreSegmentBundleExactStream) !?segment_node_index.CatalogRecord {
        if (self.merger == null) try self.reset();
        return try self.merger.?.next();
    }
};

const SegmentBundleExactCurrent = struct {
    record: segment_node_index.CatalogRecord,
    text: std.ArrayList(u8) = .empty,
};

const SegmentBundleExactRunMerger = struct {
    allocator: std.mem.Allocator,
    store: Store,
    texts: Store.NodeTextsView,
    readers: std.ArrayList(SegmentBundleExactRunReader),
    current: std.ArrayList(SegmentBundleExactCurrent),
    queue: std.PriorityQueue(usize, []const SegmentBundleExactCurrent, compareSegmentBundleExactRunIndex),

    fn init(allocator: std.mem.Allocator, store: Store, run_paths: []const []u8) !SegmentBundleExactRunMerger {
        var texts = try Store.NodeTextsView.open(store);
        errdefer texts.deinit();
        var readers = std.ArrayList(SegmentBundleExactRunReader).empty;
        errdefer {
            for (readers.items) |*reader| reader.deinit();
            readers.deinit(allocator);
        }
        var current = std.ArrayList(SegmentBundleExactCurrent).empty;
        errdefer {
            for (current.items) |*entry| entry.text.deinit(allocator);
            current.deinit(allocator);
        }
        try readers.ensureTotalCapacityPrecise(allocator, run_paths.len);
        try current.ensureTotalCapacityPrecise(allocator, run_paths.len);

        for (run_paths) |path| {
            var reader = try SegmentBundleExactRunReader.open(store, path);
            errdefer reader.deinit();
            const record = (try reader.next()) orelse return error.InvalidRecord;
            var text = std.ArrayList(u8).empty;
            errdefer text.deinit(allocator);
            try readSegmentBundleExactTextIntoBuffer(allocator, &texts, record, &text);
            readers.appendAssumeCapacity(reader);
            current.appendAssumeCapacity(.{ .record = record, .text = text });
            text = .empty;
        }

        var queue = std.PriorityQueue(usize, []const SegmentBundleExactCurrent, compareSegmentBundleExactRunIndex).initContext(current.items);
        errdefer queue.deinit(allocator);
        try queue.ensureTotalCapacityPrecise(allocator, current.items.len);
        for (current.items, 0..) |_, index| {
            try queue.push(allocator, index);
        }

        return .{
            .allocator = allocator,
            .store = store,
            .texts = texts,
            .readers = readers,
            .current = current,
            .queue = queue,
        };
    }

    fn deinit(self: *SegmentBundleExactRunMerger) void {
        self.queue.deinit(self.allocator);
        for (self.current.items) |*entry| entry.text.deinit(self.allocator);
        self.current.deinit(self.allocator);
        for (self.readers.items) |*reader| reader.deinit();
        self.readers.deinit(self.allocator);
        self.texts.deinit();
    }

    fn next(self: *SegmentBundleExactRunMerger) !?segment_node_index.CatalogRecord {
        const reader_index = self.queue.pop() orelse return null;
        const out = self.current.items[reader_index].record;
        if (try self.readers.items[reader_index].next()) |record| {
            self.current.items[reader_index].record = record;
            try readSegmentBundleExactTextIntoBuffer(self.allocator, &self.texts, record, &self.current.items[reader_index].text);
            try self.queue.push(self.allocator, reader_index);
        } else {
            self.current.items[reader_index].text.clearRetainingCapacity();
        }
        return out;
    }
};

fn compareSegmentBundleExactRunIndex(records: []const SegmentBundleExactCurrent, lhs: usize, rhs: usize) std.math.Order {
    const left = records[lhs];
    const right = records[rhs];
    const kind_order = std.math.order(@intFromEnum(left.record.kind), @intFromEnum(right.record.kind));
    if (kind_order != .eq) return kind_order;
    const text_order = std.mem.order(u8, left.text.items, right.text.items);
    if (text_order != .eq) return text_order;
    return std.math.order(left.record.id.toInt(), right.record.id.toInt());
}

const EdgeSegmentManifestEntry = struct {
    const full_node_range = segment_mod.ImmutableAdjacencySegment.NodeIdRange{
        .min = 1,
        .max = std.math.maxInt(u64) - 1,
    };

    edge_count: u64,
    edge_digest: u64,
    edge_id_range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    edge_id_digest: u64,
    edge_id_order_digest: u64 = 0,
    edge_id_runs: EdgeSegmentIdRunSummary = .{},
    src_node_range: segment_mod.ImmutableAdjacencySegment.NodeIdRange = full_node_range,
    dst_node_range: segment_mod.ImmutableAdjacencySegment.NodeIdRange = full_node_range,
    singleton_rel: ?core.RelKind = null,
    path: []const u8,
};

const EdgeSegmentIdSidecarSummary = struct {
    edge_id_order_digest: u64,
    edge_id_runs: EdgeSegmentIdRunSummary,
};

const EdgeSegmentManifestSummary = struct {
    total_edges: u64,
    manifest_digest: u64,
    edge_id_runs: EdgeSegmentIdRunSummary,
};

const EdgeSegmentIdRunRange = struct {
    min: u64,
    max: u64,
};

fn edgeSegmentIdRunRangeLessThan(_: void, lhs: EdgeSegmentIdRunRange, rhs: EdgeSegmentIdRunRange) bool {
    if (lhs.min != rhs.min) return lhs.min < rhs.min;
    return lhs.max < rhs.max;
}

fn appendEdgeSegmentManifestRunRangeSorted(
    builder: *EdgeSegmentIdRunBuilder,
    has_previous: *bool,
    previous_max: *u64,
    min: u64,
    max: u64,
) bool {
    if (has_previous.* and min <= previous_max.*) return false;
    builder.addRange(min, max);
    previous_max.* = max;
    has_previous.* = true;
    return true;
}

const EdgeSegmentIdRunBuilder = struct {
    summary: EdgeSegmentIdRunSummary = .{},
    previous: u64 = 0,
    overflow: bool = false,

    fn add(self: *EdgeSegmentIdRunBuilder, edge_id: u64) void {
        if (self.overflow) return;
        if (self.summary.run_count == 0) {
            self.summary.run_count = 1;
            self.summary.first_min = edge_id;
            self.summary.first_max = edge_id;
            self.previous = edge_id;
            return;
        }
        if (self.previous != std.math.maxInt(u64) and edge_id == self.previous + 1) {
            if (self.summary.run_count == 1) {
                self.summary.first_max = edge_id;
            } else {
                self.summary.second_max = edge_id;
            }
            self.previous = edge_id;
            return;
        }
        if (self.summary.run_count == 1) {
            self.summary.run_count = 2;
            self.summary.second_min = edge_id;
            self.summary.second_max = edge_id;
            self.previous = edge_id;
            return;
        }
        self.overflow = true;
    }

    fn addRange(self: *EdgeSegmentIdRunBuilder, min: u64, max: u64) void {
        if (self.overflow) return;
        if (min > max) {
            self.overflow = true;
            return;
        }
        if (self.summary.run_count == 0) {
            self.summary.run_count = 1;
            self.summary.first_min = min;
            self.summary.first_max = max;
            self.previous = max;
            return;
        }
        if (min <= self.previous) {
            self.overflow = true;
            return;
        }
        if (self.previous != std.math.maxInt(u64) and min == self.previous + 1) {
            if (self.summary.run_count == 1) {
                self.summary.first_max = max;
            } else {
                self.summary.second_max = max;
            }
            self.previous = max;
            return;
        }
        if (self.summary.run_count == 1) {
            self.summary.run_count = 2;
            self.summary.second_min = min;
            self.summary.second_max = max;
            self.previous = max;
            return;
        }
        self.overflow = true;
    }

    fn finish(self: EdgeSegmentIdRunBuilder) EdgeSegmentIdRunSummary {
        if (self.overflow) return .{};
        return self.summary;
    }
};

const OwnedEdgeSegmentManifestEntry = struct {
    edge_count: u64,
    edge_digest: u64 = 0,
    edge_id_range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    edge_id_digest: u64,
    edge_id_order_digest: u64 = 0,
    edge_id_runs: EdgeSegmentIdRunSummary = .{},
    src_node_range: segment_mod.ImmutableAdjacencySegment.NodeIdRange,
    dst_node_range: segment_mod.ImmutableAdjacencySegment.NodeIdRange,
    singleton_rel: ?core.RelKind = null,
    path: []u8,

    fn deinit(self: *OwnedEdgeSegmentManifestEntry, allocator: std.mem.Allocator) void {
        allocator.free(self.path);
    }
};

const EdgeSegmentManifest = struct {
    const multi_magic = [_]u8{ 'T', 'K', 'M', 'S' };
    const version: u16 = 14;
    const header_len: usize = 24;
    const entry_header_len: usize = 24;

    entries: std.ArrayList(OwnedEdgeSegmentManifestEntry) = .empty,
    ranges_trusted: bool = false,

    fn deinit(self: *EdgeSegmentManifest, allocator: std.mem.Allocator) void {
        for (self.entries.items) |*entry| entry.deinit(allocator);
        self.entries.deinit(allocator);
    }

    fn totalEdgeCount(self: EdgeSegmentManifest) u64 {
        var total: u64 = 0;
        for (self.entries.items) |entry| {
            total = std.math.add(u64, total, entry.edge_count) catch return std.math.maxInt(u64);
        }
        return total;
    }
};

const edge_segment_manifest_run_from_range: u32 = 1 << 0;
const edge_segment_manifest_run_two_split: u32 = 1 << 1;
const edge_segment_manifest_src_single: u32 = 1 << 2;
const edge_segment_manifest_src_full: u32 = 1 << 3;
const edge_segment_manifest_dst_single: u32 = 1 << 4;
const edge_segment_manifest_dst_full: u32 = 1 << 5;
const edge_segment_manifest_edge_digest_explicit: u32 = 1 << 6;
const edge_segment_manifest_edge_count_explicit: u32 = 1 << 7;
const edge_segment_manifest_order_digest_explicit: u32 = 1 << 8;
const edge_segment_manifest_path_relative: u32 = 1 << 9;
const edge_segment_manifest_virtual_singleton: u32 = 1 << 10;
const edge_segment_manifest_known_run_flags: u32 =
    edge_segment_manifest_run_from_range |
    edge_segment_manifest_run_two_split;
const edge_segment_manifest_endpoint_flags: u32 =
    edge_segment_manifest_src_single |
    edge_segment_manifest_src_full |
    edge_segment_manifest_dst_single |
    edge_segment_manifest_dst_full;
const edge_segment_manifest_known_flags: u32 =
    edge_segment_manifest_known_run_flags |
    edge_segment_manifest_endpoint_flags |
    edge_segment_manifest_edge_digest_explicit |
    edge_segment_manifest_edge_count_explicit |
    edge_segment_manifest_order_digest_explicit |
    edge_segment_manifest_path_relative |
    edge_segment_manifest_virtual_singleton;

const EdgeSegmentManifestRunEncoding = struct {
    flags: u32,
    first_max: u64,
    second_min: u64,
};

const EdgeSegmentManifestEndpointEncoding = struct {
    flags: u32,
    src_min: u64,
    src_max: u64,
    dst_min: u64,
    dst_max: u64,
};

const EdgeSegmentManifestPathEncoding = struct {
    flags: u32,
    bytes: []const u8,
};

const ParsedManifestProcessLease = struct {
    kind: ManifestProcessLeaseKind,
    pid: ProcessId,
    manifest_path: []const u8,
};

fn parseManifestProcessLease(content: []const u8) ?ParsedManifestProcessLease {
    var lines = std.mem.splitScalar(u8, content, '\n');
    const magic = lines.next() orelse return null;
    if (!std.mem.eql(u8, magic, "tinykg-manifest-lease-v1")) return null;
    const kind_line = lines.next() orelse return null;
    const pid_line = lines.next() orelse return null;
    const manifest_line = lines.next() orelse return null;
    if (!std.mem.startsWith(u8, kind_line, "kind=")) return null;
    if (!std.mem.startsWith(u8, pid_line, "pid=")) return null;
    if (!std.mem.startsWith(u8, manifest_line, "manifest=")) return null;
    const kind_value = kind_line["kind=".len..];
    const kind: ManifestProcessLeaseKind = if (std.mem.eql(u8, kind_value, ManifestProcessLeaseKind.edge_segment.tag()))
        .edge_segment
    else if (std.mem.eql(u8, kind_value, ManifestProcessLeaseKind.node_text_run.tag()))
        .node_text_run
    else
        return null;
    const pid = std.fmt.parseInt(ProcessId, pid_line["pid=".len..], 10) catch return null;
    const manifest_path = manifest_line["manifest=".len..];
    if (manifest_path.len == 0) return null;
    return .{ .kind = kind, .pid = pid, .manifest_path = manifest_path };
}

fn edgeSegmentManifestSafeRelativePath(path: []const u8) bool {
    if (path.len == 0) return false;
    if (std.fs.path.isAbsolute(path)) return false;
    if (std.mem.indexOfScalar(u8, path, 0) != null) return false;
    // Validate both separator spellings independent of the current host.  A
    // Windows-authored manifest may be inspected or restored on POSIX, where
    // `std.fs.path.isAbsolute("C:\\...")` and split('/') alone are insufficient.
    if (path[0] == '/' or path[0] == '\\') return false;
    if (path.len >= 2 and std.ascii.isAlphabetic(path[0]) and path[1] == ':') return false;
    var part_start: usize = 0;
    for (path, 0..) |byte, index| {
        if (byte != '/' and byte != '\\') continue;
        const part = path[part_start..index];
        if (part.len == 0) return false;
        if (std.mem.eql(u8, part, ".") or std.mem.eql(u8, part, "..")) return false;
        part_start = index + 1;
    }
    const final_part = path[part_start..];
    if (final_part.len == 0) return false;
    if (std.mem.eql(u8, final_part, ".") or std.mem.eql(u8, final_part, "..")) return false;
    return true;
}

fn processIdIsAlive(pid: ProcessId) bool {
    return process_liveness.isAlive(pid);
}

fn freeOwnedManifestPathList(allocator: std.mem.Allocator, paths: []const []const u8) void {
    for (paths) |path| allocator.free(path);
    allocator.free(paths);
}

fn freeOwnedManifestPathArrayList(allocator: std.mem.Allocator, paths: *std.ArrayList([]const u8)) void {
    for (paths.items) |path| allocator.free(path);
    paths.deinit(allocator);
}

fn edgeSegmentManifestEntryMayContainNode(
    entry: OwnedEdgeSegmentManifestEntry,
    direction: segment_mod.Direction,
    node_id: u64,
) bool {
    const range = switch (direction) {
        .forward => entry.src_node_range,
        .reverse => entry.dst_node_range,
    };
    return node_id >= range.min and node_id <= range.max;
}

fn edgeSegmentManifestEntryIsVirtual(entry: anytype) bool {
    return entry.singleton_rel != null;
}

fn edgeSegmentManifestVirtualRunEdgeAt(entry: anytype, index: u64) !segment_mod.EdgeRecord {
    const rel = entry.singleton_rel orelse return error.InvalidRecord;
    if (entry.path.len != 0) return error.InvalidRecord;
    if (index >= entry.edge_count) return error.InvalidRecord;
    if (entry.edge_id_range.min == 0 or entry.edge_id_range.max == std.math.maxInt(u64)) return error.InvalidRecord;
    if (entry.src_node_range.min == 0 or entry.src_node_range.max == std.math.maxInt(u64)) return error.InvalidRecord;
    if (entry.dst_node_range.min == 0 or entry.dst_node_range.max == std.math.maxInt(u64)) return error.InvalidRecord;
    if (entry.src_node_range.min != entry.src_node_range.max) return error.InvalidRecord;
    if (try edgeSegmentManifestRangeCount(entry.edge_id_range) != entry.edge_count) return error.InvalidRecord;
    if (try nodeIdRangeCount(entry.dst_node_range) != entry.edge_count) return error.InvalidRecord;
    const edge_id = std.math.add(u64, entry.edge_id_range.min, index) catch return error.InvalidRecord;
    const dst = std.math.add(u64, entry.dst_node_range.min, index) catch return error.InvalidRecord;
    return .{
        .src = .fromInt(entry.src_node_range.min),
        .rel = rel,
        .dst = .fromInt(dst),
        .edge_id = .fromInt(edge_id),
    };
}

fn edgeSegmentManifestVirtualRunDigest(entry: anytype) !u64 {
    var digest: u64 = 0;
    var index: u64 = 0;
    while (index < entry.edge_count) : (index += 1) {
        const edge = try edgeSegmentManifestVirtualRunEdgeAt(entry, index);
        digest ^= edgeRecordDigest(.{
            .src = edge.src.toInt(),
            .dst = edge.dst.toInt(),
            .edge_id = edge.edge_id.toInt(),
            .rel = @intFromEnum(edge.rel),
        });
    }
    return digest;
}

fn edgeSegmentManifestValidateVirtualEntryShape(entry: anytype) !void {
    const rel = entry.singleton_rel orelse return error.InvalidRecord;
    _ = rel;
    if (entry.edge_count == 0) return error.InvalidRecord;
    if (entry.path.len != 0) return error.InvalidRecord;
    if (entry.edge_id_order_digest != 0) return error.InvalidRecord;
    if (!edgeSegmentManifestRunsCoverEntry(entry.edge_count, entry.edge_id_range, entry.edge_id_runs)) {
        return error.InvalidRecord;
    }
    if (try edgeSegmentManifestRangeCount(entry.edge_id_range) != entry.edge_count) return error.InvalidRecord;
    if (try nodeIdRangeCount(entry.dst_node_range) != entry.edge_count) return error.InvalidRecord;
}

fn edgeSegmentManifestValidateVirtualEntry(entry: anytype) !void {
    try edgeSegmentManifestValidateVirtualEntryShape(entry);
    const expected_id_digest = try edgeSegmentIdDigestForRun(entry.edge_id_range.min, entry.edge_count);
    if (entry.edge_id_digest != 0 and entry.edge_id_digest != expected_id_digest) return error.InvalidRecord;
    if (entry.edge_digest != try edgeSegmentManifestVirtualRunDigest(entry)) return error.InvalidRecord;
}

fn appendEdgeSegmentManifestVirtualEdges(
    allocator: std.mem.Allocator,
    out: *std.ArrayList(segment_mod.EdgeRecord),
    entry: anytype,
) !void {
    try edgeSegmentManifestValidateVirtualEntry(entry);
    const additional = std.math.cast(usize, entry.edge_count) orelse return error.RecordTooLarge;
    try out.ensureUnusedCapacity(allocator, additional);
    var index: u64 = 0;
    while (index < entry.edge_count) : (index += 1) {
        out.appendAssumeCapacity(try edgeSegmentManifestVirtualRunEdgeAt(entry, index));
    }
}

fn edgeSegmentIdDigestForRun(first: u64, count: u64) !u64 {
    var digest: u64 = 0;
    var offset: u64 = 0;
    while (offset < count) : (offset += 1) {
        digest ^= edgeSegmentIdDigest(std.math.add(u64, first, offset) catch return error.InvalidRecord);
    }
    return digest;
}

fn nodeIdRangeCount(range: segment_mod.ImmutableAdjacencySegment.NodeIdRange) !u64 {
    if (range.min == 0 or range.max == std.math.maxInt(u64) or range.min > range.max) return error.InvalidRecord;
    return std.math.add(u64, range.max - range.min, 1) catch return error.InvalidRecord;
}

fn extendVirtualEdgeRun(existing: *EdgeSegmentManifestEntry, next: EdgeSegmentManifestEntry) !bool {
    if (!edgeSegmentManifestEntryIsVirtual(existing.*)) return false;
    if (!edgeSegmentManifestEntryIsVirtual(next)) return false;
    try edgeSegmentManifestValidateVirtualEntryShape(existing.*);
    try edgeSegmentManifestValidateVirtualEntryShape(next);
    if (existing.singleton_rel.? != next.singleton_rel.?) return false;
    if (existing.src_node_range.min != next.src_node_range.min or existing.src_node_range.max != next.src_node_range.max) return false;
    if (existing.edge_id_range.max == std.math.maxInt(u64) or existing.dst_node_range.max == std.math.maxInt(u64)) return false;
    if (next.edge_id_range.min != existing.edge_id_range.max + 1 or next.edge_id_range.max != next.edge_id_range.min) return false;
    if (next.dst_node_range.min != existing.dst_node_range.max + 1 or next.dst_node_range.max != next.dst_node_range.min) return false;
    const existing_id_digest = if (existing.edge_id_digest != 0)
        existing.edge_id_digest
    else
        try edgeSegmentIdDigestForRun(existing.edge_id_range.min, existing.edge_count);
    existing.edge_count = std.math.add(u64, existing.edge_count, 1) catch return error.RecordTooLarge;
    existing.edge_digest ^= next.edge_digest;
    existing.edge_id_range.max = next.edge_id_range.max;
    existing.edge_id_digest = existing_id_digest ^ next.edge_id_digest;
    existing.edge_id_order_digest = 0;
    existing.edge_id_runs = .{
        .run_count = 1,
        .first_min = existing.edge_id_range.min,
        .first_max = existing.edge_id_range.max,
    };
    existing.dst_node_range.max = next.dst_node_range.max;
    try edgeSegmentManifestValidateVirtualEntryShape(existing.*);
    return true;
}

fn addEdgeSegmentManifestLivePaths(
    live_paths: *std.StringHashMap(void),
    entries: []const OwnedEdgeSegmentManifestEntry,
) !void {
    try live_paths.ensureUnusedCapacity(@intCast(entries.len));
    for (entries) |entry| {
        if (edgeSegmentManifestEntryIsVirtual(entry)) continue;
        live_paths.putAssumeCapacity(entry.path, {});
    }
}

const EdgeSegmentIdIndex = struct {
    const magic = [_]u8{ 'T', 'K', 'E', 'I' };
    const version: u16 = 1;
    const header_len: usize = 48;
};

const edge_segment_id_index_stack_scan_max = 256;

const EdgeSegmentIdIndexHeader = struct {
    edge_count: u64,
    edge_id_min: u64,
    edge_id_max: u64,
    edge_id_digest: u64,
    edge_id_order_digest: u64,
};

const EdgeSegmentIdIndexWriter = struct {
    file: std.Io.File,
    summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    edge_id_order_digest: u64,
    offset: u64 = EdgeSegmentIdIndex.header_len,
    previous: u64 = 0,
    digest: u64 = 0,
    order_digest: u64 = 0,

    fn write(self: *EdgeSegmentIdIndexWriter, store: Store, index: usize, edge_id: u64) !void {
        if (index != 0 and edge_id <= self.previous) return error.InvalidRecord;
        self.previous = edge_id;
        self.digest ^= edgeSegmentIdDigest(edge_id);
        self.order_digest ^= edgeSegmentIdIndexOrderDigestAt(index, edge_id);
        var id_bytes: [8]u8 = undefined;
        std.mem.writeInt(u64, &id_bytes, edge_id, .little);
        try self.file.writePositionalAll(store.io, &id_bytes, self.offset);
        self.offset += id_bytes.len;
    }

    fn finish(self: *EdgeSegmentIdIndexWriter, store: Store) !void {
        if (self.digest != self.summary.digest) return error.InvalidRecord;
        if (self.order_digest != self.edge_id_order_digest) return error.InvalidRecord;
        if (self.offset != try edgeSegmentIdIndexFileSize(self.summary.count)) return error.InvalidRecord;
        if (selfOptionsNeedSync(store)) try self.file.sync(store.io);
    }
};

pub const PublishedEdgeSegments = struct {
    allocator: std.mem.Allocator,
    segments: std.ArrayList(segment_mod.ImmutableAdjacencySegment) = .empty,
    virtual_edges: std.ArrayList(segment_mod.EdgeRecord) = .empty,
    query_direction: ?segment_mod.Direction = null,

    fn init(allocator: std.mem.Allocator) PublishedEdgeSegments {
        return .{ .allocator = allocator };
    }

    fn openFromManifest(allocator: std.mem.Allocator, io: std.Io, entries: []const OwnedEdgeSegmentManifestEntry) !PublishedEdgeSegments {
        var out = PublishedEdgeSegments.init(allocator);
        errdefer out.deinit();
        try out.openEntries(io, entries);
        return out;
    }

    fn openEntries(self: *PublishedEdgeSegments, io: std.Io, entries: []const OwnedEdgeSegmentManifestEntry) !void {
        try self.segments.ensureTotalCapacity(self.allocator, self.segments.items.len + entries.len);
        for (entries) |entry| {
            try self.openEntry(io, entry);
        }
    }

    fn openTrustedEntriesForQuery(self: *PublishedEdgeSegments, io: std.Io, entries: []const OwnedEdgeSegmentManifestEntry) !void {
        try self.segments.ensureTotalCapacity(self.allocator, self.segments.items.len + entries.len);
        for (entries) |entry| {
            try self.openTrustedEntryForQuery(io, entry);
        }
    }

    fn openEntry(self: *PublishedEdgeSegments, io: std.Io, entry: OwnedEdgeSegmentManifestEntry) !void {
        if (edgeSegmentManifestEntryIsVirtual(entry)) {
            try appendEdgeSegmentManifestVirtualEdges(self.allocator, &self.virtual_edges, entry);
            return;
        }
        const segment = try segment_mod.ImmutableAdjacencySegment.open(self.allocator, io, entry.path);
        errdefer {
            var cleanup = segment;
            cleanup.deinit();
        }
        if (try segment.edgeCount() != entry.edge_count) return error.InvalidRecord;
        self.segments.appendAssumeCapacity(segment);
    }

    fn openTrustedEntryForQuery(self: *PublishedEdgeSegments, io: std.Io, entry: OwnedEdgeSegmentManifestEntry) !void {
        if (edgeSegmentManifestEntryIsVirtual(entry)) {
            try appendEdgeSegmentManifestVirtualEdges(self.allocator, &self.virtual_edges, entry);
            return;
        }
        const segment = try segment_mod.ImmutableAdjacencySegment.openTrustedForQuery(self.allocator, io, entry.path, entry.edge_count);
        errdefer {
            var cleanup = segment;
            cleanup.deinit();
        }
        self.segments.appendAssumeCapacity(segment);
    }

    fn openTrustedEntryDirectionForQuery(
        self: *PublishedEdgeSegments,
        io: std.Io,
        entry: OwnedEdgeSegmentManifestEntry,
        direction: segment_mod.Direction,
    ) !void {
        if (self.query_direction) |query_direction| {
            if (query_direction != direction) return error.InvalidRecord;
        } else {
            self.query_direction = direction;
        }
        if (edgeSegmentManifestEntryIsVirtual(entry)) {
            try appendEdgeSegmentManifestVirtualEdges(self.allocator, &self.virtual_edges, entry);
            return;
        }
        const segment = try segment_mod.ImmutableAdjacencySegment.openTrustedDirectionForQuery(self.allocator, io, entry.path, direction, entry.edge_count);
        errdefer {
            var cleanup = segment;
            cleanup.deinit();
        }
        self.segments.appendAssumeCapacity(segment);
    }

    pub fn deinit(self: *PublishedEdgeSegments) void {
        for (self.segments.items) |*segment| segment.deinit();
        self.segments.deinit(self.allocator);
        self.virtual_edges.deinit(self.allocator);
    }

    pub fn edgeDigest(self: *PublishedEdgeSegments) !u64 {
        if (self.query_direction != null) return error.InvalidRecord;
        var digest: u64 = 0;
        for (self.segments.items) |segment| {
            digest ^= try segment.edgeDigest();
        }
        for (self.virtual_edges.items) |edge| {
            digest ^= edgeRecordDigest(.{
                .src = edge.src.toInt(),
                .dst = edge.dst.toInt(),
                .edge_id = edge.edge_id.toInt(),
                .rel = @intFromEnum(edge.rel),
            });
        }
        return digest;
    }

    pub fn forEachNeighbor(
        self: *PublishedEdgeSegments,
        direction: segment_mod.Direction,
        node_id: core.NodeId,
        rel_filter: ?core.RelKind,
        max_edges: usize,
        context: anytype,
        comptime callback: fn (@TypeOf(context), segment_mod.EdgeRecord) anyerror!bool,
    ) !bool {
        if (self.query_direction) |query_direction| {
            if (query_direction != direction) return error.InvalidRecord;
        }
        var iterators = std.ArrayList(segment_mod.ImmutableAdjacencySegment.NeighborIterator).empty;
        defer iterators.deinit(self.allocator);
        try iterators.ensureTotalCapacity(self.allocator, self.segments.items.len);

        var queue = std.PriorityQueue(SegmentNeighborHeapEntry, SegmentNeighborHeapContext, compareSegmentNeighborHeapEntry).initContext(.{ .direction = direction });
        defer queue.deinit(self.allocator);
        try queue.ensureTotalCapacity(self.allocator, self.segments.items.len + self.virtual_edges.items.len);

        for (self.segments.items) |*segment| {
            var iterator = (try segment.neighborIterator(direction, node_id, rel_filter)) orelse continue;
            if (try iterator.next()) |edge| {
                const iterator_index = iterators.items.len;
                iterators.appendAssumeCapacity(iterator);
                try queue.push(self.allocator, .{
                    .iterator_index = iterator_index,
                    .edge = edge,
                });
            }
        }
        for (self.virtual_edges.items) |edge| {
            const owner = switch (direction) {
                .forward => edge.src,
                .reverse => edge.dst,
            };
            if (owner != node_id) continue;
            if (rel_filter) |rel| {
                if (edge.rel != rel) continue;
            }
            try queue.push(self.allocator, .{
                .iterator_index = null,
                .edge = edge,
            });
        }

        var emitted: usize = 0;
        while (queue.pop()) |entry| {
            if (emitted >= max_edges) return core.Error.BudgetExceeded;
            emitted += 1;
            if (try callback(context, entry.edge)) return true;
            if (entry.iterator_index) |iterator_index| {
                if (try iterators.items[iterator_index].next()) |next_edge| {
                    try queue.push(self.allocator, .{
                        .iterator_index = iterator_index,
                        .edge = next_edge,
                    });
                }
            }
        }
        return false;
    }
};

pub const PublishedEdgeSegmentsCoverage = enum {
    full,
    visible_full,
    delta,
};

pub const PublishedEdgeSegmentsForQuery = struct {
    segments: PublishedEdgeSegments,
    coverage: PublishedEdgeSegmentsCoverage,
    retention_window: ?EdgeSegmentRegisteredRetentionWindow = null,

    pub fn deinit(self: *PublishedEdgeSegmentsForQuery) void {
        self.segments.deinit();
        if (self.retention_window) |*retention_window| retention_window.deinit();
        self.retention_window = null;
    }
};

const EdgeSegmentMergeStream = struct {
    allocator: std.mem.Allocator,
    segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
    virtual_edges: ?*std.ArrayList(segment_mod.EdgeRecord) = null,
    direction: segment_mod.Direction,
    tombstones: ?*Store.EdgeTombstoneIndexView = null,
    iterators: std.ArrayList(segment_mod.ImmutableAdjacencySegment.EdgeIterator) = .empty,
    queue: std.PriorityQueue(SegmentEdgeHeapEntry, SegmentEdgeHeapContext, compareSegmentEdgeHeapEntry),

    fn init(
        allocator: std.mem.Allocator,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        direction: segment_mod.Direction,
    ) EdgeSegmentMergeStream {
        return .{
            .allocator = allocator,
            .segments = segments,
            .direction = direction,
            .queue = std.PriorityQueue(SegmentEdgeHeapEntry, SegmentEdgeHeapContext, compareSegmentEdgeHeapEntry).initContext(.{ .direction = direction }),
        };
    }

    fn initFiltered(
        allocator: std.mem.Allocator,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        direction: segment_mod.Direction,
        tombstones: ?*Store.EdgeTombstoneIndexView,
    ) EdgeSegmentMergeStream {
        var stream = EdgeSegmentMergeStream.init(allocator, segments, direction);
        stream.tombstones = tombstones;
        return stream;
    }

    fn initWithVirtual(
        allocator: std.mem.Allocator,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        virtual_edges: *std.ArrayList(segment_mod.EdgeRecord),
        direction: segment_mod.Direction,
    ) EdgeSegmentMergeStream {
        var stream = EdgeSegmentMergeStream.init(allocator, segments, direction);
        stream.virtual_edges = virtual_edges;
        return stream;
    }

    fn initWithVirtualFiltered(
        allocator: std.mem.Allocator,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        virtual_edges: *std.ArrayList(segment_mod.EdgeRecord),
        direction: segment_mod.Direction,
        tombstones: ?*Store.EdgeTombstoneIndexView,
    ) EdgeSegmentMergeStream {
        var stream = EdgeSegmentMergeStream.initWithVirtual(allocator, segments, virtual_edges, direction);
        stream.tombstones = tombstones;
        return stream;
    }

    fn deinit(self: *EdgeSegmentMergeStream) void {
        self.queue.deinit(self.allocator);
        self.iterators.deinit(self.allocator);
    }

    fn reset(self: *EdgeSegmentMergeStream) !void {
        self.queue.clearRetainingCapacity();
        self.iterators.clearRetainingCapacity();
        try self.iterators.ensureTotalCapacity(self.allocator, self.segments.items.len);
        const virtual_count = if (self.virtual_edges) |virtual_edges| virtual_edges.items.len else 0;
        try self.queue.ensureTotalCapacity(self.allocator, self.segments.items.len + virtual_count);
        for (self.segments.items) |*segment| {
            var iterator = try segment.edgeIterator(self.direction);
            if (try iterator.next()) |edge| {
                const iterator_index = self.iterators.items.len;
                self.iterators.appendAssumeCapacity(iterator);
                try self.queue.push(self.allocator, .{
                    .iterator_index = iterator_index,
                    .edge = edge,
                });
            }
        }
        if (self.virtual_edges) |virtual_edges| {
            for (virtual_edges.items) |edge| {
                try self.queue.push(self.allocator, .{
                    .iterator_index = null,
                    .edge = edge,
                });
            }
        }
    }

    fn next(self: *EdgeSegmentMergeStream) !?segment_mod.EdgeRecord {
        while (true) {
            const entry = self.queue.pop() orelse return null;
            if (entry.iterator_index) |iterator_index| {
                if (try self.iterators.items[iterator_index].next()) |edge| {
                    try self.queue.push(self.allocator, .{
                        .iterator_index = iterator_index,
                        .edge = edge,
                    });
                }
            }
            if (self.tombstones) |tombstones| {
                if (try tombstones.contains(entry.edge.edge_id.toInt())) continue;
            }
            return entry.edge;
        }
    }
};

const BaseAndSegmentMergeStream = struct {
    allocator: std.mem.Allocator,
    base: *EdgeIndexRecordReader,
    segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
    virtual_edges: ?*std.ArrayList(segment_mod.EdgeRecord) = null,
    direction: segment_mod.Direction,
    tombstones: ?*Store.EdgeTombstoneIndexView = null,
    segment_stream: EdgeSegmentMergeStream,
    base_pos: u64 = 0,
    next_base: ?segment_mod.EdgeRecord = null,
    next_segment: ?segment_mod.EdgeRecord = null,

    fn init(
        allocator: std.mem.Allocator,
        base: *EdgeIndexRecordReader,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        direction: segment_mod.Direction,
    ) BaseAndSegmentMergeStream {
        return .{
            .allocator = allocator,
            .base = base,
            .segments = segments,
            .direction = direction,
            .segment_stream = EdgeSegmentMergeStream.init(allocator, segments, direction),
        };
    }

    fn initFiltered(
        allocator: std.mem.Allocator,
        base: *EdgeIndexRecordReader,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        direction: segment_mod.Direction,
        tombstones: ?*Store.EdgeTombstoneIndexView,
    ) BaseAndSegmentMergeStream {
        return .{
            .allocator = allocator,
            .base = base,
            .segments = segments,
            .direction = direction,
            .tombstones = tombstones,
            .segment_stream = EdgeSegmentMergeStream.initFiltered(allocator, segments, direction, tombstones),
        };
    }

    fn initWithVirtualFiltered(
        allocator: std.mem.Allocator,
        base: *EdgeIndexRecordReader,
        segments: *std.ArrayList(segment_mod.ImmutableAdjacencySegment),
        virtual_edges: *std.ArrayList(segment_mod.EdgeRecord),
        direction: segment_mod.Direction,
        tombstones: ?*Store.EdgeTombstoneIndexView,
    ) BaseAndSegmentMergeStream {
        return .{
            .allocator = allocator,
            .base = base,
            .segments = segments,
            .virtual_edges = virtual_edges,
            .direction = direction,
            .tombstones = tombstones,
            .segment_stream = EdgeSegmentMergeStream.initWithVirtualFiltered(allocator, segments, virtual_edges, direction, tombstones),
        };
    }

    fn deinit(self: *BaseAndSegmentMergeStream) void {
        self.segment_stream.deinit();
    }

    fn reset(self: *BaseAndSegmentMergeStream) !void {
        _ = self.allocator;
        _ = self.segments;
        self.base_pos = 0;
        self.next_base = try self.readNextBase();
        try self.segment_stream.reset();
        self.next_segment = try self.segment_stream.next();
    }

    fn next(self: *BaseAndSegmentMergeStream) !?segment_mod.EdgeRecord {
        if (self.next_base) |base_edge| {
            if (self.next_segment) |segment_edge| {
                if (segmentEdgeLessThan(self.direction, segment_edge, base_edge)) {
                    self.next_segment = try self.segment_stream.next();
                    return segment_edge;
                }
            }
            self.next_base = try self.readNextBase();
            return base_edge;
        }
        if (self.next_segment) |segment_edge| {
            self.next_segment = try self.segment_stream.next();
            return segment_edge;
        }
        return null;
    }

    fn readNextBase(self: *BaseAndSegmentMergeStream) !?segment_mod.EdgeRecord {
        while (self.base_pos < self.base.edge_count) {
            const edge = try edgeIndexReaderRecordToSegmentEdge(self.base, self.base_pos);
            self.base_pos += 1;
            if (self.tombstones) |tombstones| {
                if (try tombstones.contains(edge.edge_id.toInt())) continue;
            }
            return edge;
        }
        return null;
    }
};

const SegmentEdgeHeapEntry = struct {
    iterator_index: ?usize,
    edge: segment_mod.EdgeRecord,
};

const SegmentEdgeHeapContext = struct {
    direction: segment_mod.Direction,
};

fn compareSegmentEdgeHeapEntry(context: SegmentEdgeHeapContext, lhs: SegmentEdgeHeapEntry, rhs: SegmentEdgeHeapEntry) std.math.Order {
    if (segmentEdgeLessThan(context.direction, lhs.edge, rhs.edge)) return .lt;
    if (segmentEdgeLessThan(context.direction, rhs.edge, lhs.edge)) return .gt;
    return std.math.order(optionalHeapIndex(lhs.iterator_index), optionalHeapIndex(rhs.iterator_index));
}

const SegmentNeighborHeapEntry = struct {
    iterator_index: ?usize,
    edge: segment_mod.EdgeRecord,
};

const SegmentNeighborHeapContext = struct {
    direction: segment_mod.Direction,
};

fn compareSegmentNeighborHeapEntry(context: SegmentNeighborHeapContext, lhs: SegmentNeighborHeapEntry, rhs: SegmentNeighborHeapEntry) std.math.Order {
    if (segmentEdgeLessThan(context.direction, lhs.edge, rhs.edge)) return .lt;
    if (segmentEdgeLessThan(context.direction, rhs.edge, lhs.edge)) return .gt;
    return std.math.order(optionalHeapIndex(lhs.iterator_index), optionalHeapIndex(rhs.iterator_index));
}

fn optionalHeapIndex(index: ?usize) usize {
    return index orelse std.math.maxInt(usize);
}

fn segmentEdgeLessThan(direction: segment_mod.Direction, lhs: segment_mod.EdgeRecord, rhs: segment_mod.EdgeRecord) bool {
    return switch (direction) {
        .forward => segmentForwardEdgeLessThan(lhs, rhs),
        .reverse => segmentReverseEdgeLessThan(lhs, rhs),
    };
}

fn segmentForwardEdgeLessThan(lhs: segment_mod.EdgeRecord, rhs: segment_mod.EdgeRecord) bool {
    if (lhs.src.toInt() != rhs.src.toInt()) return lhs.src.toInt() < rhs.src.toInt();
    if (@intFromEnum(lhs.rel) != @intFromEnum(rhs.rel)) return @intFromEnum(lhs.rel) < @intFromEnum(rhs.rel);
    if (lhs.dst.toInt() != rhs.dst.toInt()) return lhs.dst.toInt() < rhs.dst.toInt();
    return lhs.edge_id.toInt() < rhs.edge_id.toInt();
}

fn segmentReverseEdgeLessThan(lhs: segment_mod.EdgeRecord, rhs: segment_mod.EdgeRecord) bool {
    if (lhs.dst.toInt() != rhs.dst.toInt()) return lhs.dst.toInt() < rhs.dst.toInt();
    if (@intFromEnum(lhs.rel) != @intFromEnum(rhs.rel)) return @intFromEnum(lhs.rel) < @intFromEnum(rhs.rel);
    if (lhs.src.toInt() != rhs.src.toInt()) return lhs.src.toInt() < rhs.src.toInt();
    return lhs.edge_id.toInt() < rhs.edge_id.toInt();
}

fn isEdgeSegmentManifestEpochLeaf(name: []const u8, prefix: []const u8) bool {
    if (!std.mem.startsWith(u8, name, prefix)) return false;
    const rest = name[prefix.len..];
    const dot_index = std.mem.indexOfScalar(u8, rest, '.') orelse return false;
    if (dot_index == 0 or dot_index + 1 >= rest.len) return false;
    if (std.mem.indexOfScalar(u8, rest[dot_index + 1 ..], '.') != null) return false;
    _ = std.fmt.parseUnsigned(u64, rest[0..dot_index], 10) catch return false;
    _ = std.fmt.parseUnsigned(u64, rest[dot_index + 1 ..], 16) catch return false;
    return true;
}

fn encodeEdgeSegmentManifestHeader(entries: []const EdgeSegmentManifestEntry, out: *[EdgeSegmentManifest.header_len]u8) !void {
    if (entries.len == 0 or entries.len > std.math.maxInt(u32)) return error.RecordTooLarge;
    @memcpy(out[0..4], &EdgeSegmentManifest.multi_magic);
    std.mem.writeInt(u16, out[4..6], EdgeSegmentManifest.version, .little);
    std.mem.writeInt(u16, out[6..8], EdgeSegmentManifest.header_len, .little);
    std.mem.writeInt(u32, out[8..12], @intCast(entries.len), .little);
    std.mem.writeInt(u16, out[12..14], EdgeSegmentManifest.entry_header_len, .little);
    @memset(out[14..16], 0);
    const total_edges = try Store.edgeSegmentManifestTotalEdges(entries);
    std.mem.writeInt(u64, out[16..24], total_edges, .little);
}

fn edgeSegmentManifestRangeCount(range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange) !u64 {
    if (range.min > range.max) return error.InvalidRecord;
    return std.math.add(u64, range.max - range.min, 1) catch return error.InvalidRecord;
}

fn edgeSegmentManifestRunsCoverEntry(
    edge_count: u64,
    edge_id_range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    runs: EdgeSegmentIdRunSummary,
) bool {
    if (runs.run_count == 0 or runs.run_count > 2) return false;
    if (runs.first_min == 0 or runs.first_max == std.math.maxInt(u64) or runs.first_min > runs.first_max) return false;
    var represented = std.math.add(u64, runs.first_max - runs.first_min, 1) catch return false;
    if (runs.run_count == 1) {
        if (runs.second_min != 0 or runs.second_max != 0) return false;
    } else {
        if (runs.second_min == 0 or runs.second_max == std.math.maxInt(u64) or runs.second_min > runs.second_max) return false;
        if (runs.second_min <= runs.first_max) return false;
        const second_count = std.math.add(u64, runs.second_max - runs.second_min, 1) catch return false;
        represented = std.math.add(u64, represented, second_count) catch return false;
    }
    if (represented != edge_count) return false;
    if (runs.first_min != edge_id_range.min) return false;
    const max = if (runs.run_count == 2) runs.second_max else runs.first_max;
    return max == edge_id_range.max;
}

fn edgeSegmentManifestCanDeriveEdgeIdDigest(entry: anytype) bool {
    if (entry.edge_id_order_digest != 0) return false;
    return edgeSegmentManifestRunsCoverEntry(entry.edge_count, entry.edge_id_range, entry.edge_id_runs);
}

fn edgeSegmentManifestCanDeriveEdgeCount(entry: anytype) bool {
    return edgeSegmentManifestRunsCoverEntry(entry.edge_count, entry.edge_id_range, entry.edge_id_runs);
}

fn edgeSegmentManifestLogicalEdgeIdDigest(entry: anytype) u64 {
    return if (edgeSegmentManifestCanDeriveEdgeIdDigest(entry)) 0 else entry.edge_id_digest;
}

fn edgeSegmentManifestOrderDigestExtraLen(flags: u32) !usize {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    return if ((flags & edge_segment_manifest_order_digest_explicit) != 0) 8 else 0;
}

fn writeEdgeSegmentManifestOrderDigestExtra(
    io: std.Io,
    file: std.Io.File,
    offset: u64,
    entry: EdgeSegmentManifestEntry,
    flags: u32,
) !u64 {
    if (try edgeSegmentManifestOrderDigestExtraLen(flags) == 0) return offset;
    var extra: [8]u8 = undefined;
    std.mem.writeInt(u64, &extra, entry.edge_id_order_digest, .little);
    try file.writePositionalAll(io, &extra, offset);
    return std.math.add(u64, offset, extra.len) catch return error.RecordTooLarge;
}

fn encodeEdgeSegmentManifestRunEncoding(entry: EdgeSegmentManifestEntry) !EdgeSegmentManifestRunEncoding {
    try entry.edge_id_runs.validate();
    const covered_count = try entry.edge_id_runs.coveredCount();
    if (covered_count != 0 and covered_count != entry.edge_count) return error.InvalidRecord;
    switch (entry.edge_id_runs.run_count) {
        0 => return .{ .flags = 0, .first_max = 0, .second_min = 0 },
        1 => {
            if (entry.edge_id_runs.first_min != entry.edge_id_range.min) return error.InvalidRecord;
            if (entry.edge_id_runs.first_max != entry.edge_id_range.max) return error.InvalidRecord;
            if (try edgeSegmentManifestRangeCount(entry.edge_id_range) != entry.edge_count) return error.InvalidRecord;
            return .{
                .flags = edge_segment_manifest_run_from_range,
                .first_max = 0,
                .second_min = 0,
            };
        },
        2 => {
            if (entry.edge_id_runs.first_min != entry.edge_id_range.min) return error.InvalidRecord;
            if (entry.edge_id_runs.second_max != entry.edge_id_range.max) return error.InvalidRecord;
            return .{
                .flags = edge_segment_manifest_run_two_split,
                .first_max = entry.edge_id_runs.first_max,
                .second_min = entry.edge_id_runs.second_min,
            };
        },
        else => return error.InvalidRecord,
    }
}

fn decodeEdgeSegmentManifestRunEncoding(
    edge_count: u64,
    edge_id_range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    flags: u32,
    first_max: u64,
    second_min: u64,
) !EdgeSegmentIdRunSummary {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    const run_flags = flags & edge_segment_manifest_known_run_flags;
    if ((run_flags & edge_segment_manifest_run_from_range) != 0 and (run_flags & edge_segment_manifest_run_two_split) != 0) {
        return error.InvalidRecord;
    }
    if (run_flags == 0) {
        if (first_max != 0 or second_min != 0) return error.InvalidRecord;
        return .{};
    }
    if ((run_flags & edge_segment_manifest_run_from_range) != 0) {
        if (first_max != 0 or second_min != 0) return error.InvalidRecord;
        if (try edgeSegmentManifestRangeCount(edge_id_range) != edge_count) return error.InvalidRecord;
        return .{
            .run_count = 1,
            .first_min = edge_id_range.min,
            .first_max = edge_id_range.max,
        };
    }
    if (first_max == 0 or second_min == 0) return error.InvalidRecord;
    if (edge_id_range.min > first_max or second_min > edge_id_range.max) return error.InvalidRecord;
    if (first_max == std.math.maxInt(u64) or second_min <= first_max + 1) return error.InvalidRecord;
    const first_count = std.math.add(u64, first_max - edge_id_range.min, 1) catch return error.InvalidRecord;
    const second_count = std.math.add(u64, edge_id_range.max - second_min, 1) catch return error.InvalidRecord;
    const total_count = std.math.add(u64, first_count, second_count) catch return error.InvalidRecord;
    if (total_count != edge_count) return error.InvalidRecord;
    return .{
        .run_count = 2,
        .first_min = edge_id_range.min,
        .first_max = first_max,
        .second_min = second_min,
        .second_max = edge_id_range.max,
    };
}

fn deriveEdgeSegmentManifestEdgeCountFromRunEncoding(
    edge_id_range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    flags: u32,
    first_max: u64,
    second_min: u64,
) !u64 {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    const run_flags = flags & edge_segment_manifest_known_run_flags;
    if ((run_flags & edge_segment_manifest_run_from_range) != 0 and (run_flags & edge_segment_manifest_run_two_split) != 0) {
        return error.InvalidRecord;
    }
    if ((flags & edge_segment_manifest_edge_count_explicit) != 0) return error.InvalidRecord;
    if ((run_flags & edge_segment_manifest_run_from_range) != 0) {
        if (first_max != 0 or second_min != 0) return error.InvalidRecord;
        return try edgeSegmentManifestRangeCount(edge_id_range);
    }
    if ((run_flags & edge_segment_manifest_run_two_split) != 0) {
        if (first_max == 0 or second_min == 0) return error.InvalidRecord;
        if (edge_id_range.min > first_max or second_min > edge_id_range.max) return error.InvalidRecord;
        if (first_max == std.math.maxInt(u64) or second_min <= first_max + 1) return error.InvalidRecord;
        const first_count = std.math.add(u64, first_max - edge_id_range.min, 1) catch return error.InvalidRecord;
        const second_count = std.math.add(u64, edge_id_range.max - second_min, 1) catch return error.InvalidRecord;
        return std.math.add(u64, first_count, second_count) catch return error.InvalidRecord;
    }
    return error.InvalidRecord;
}

fn edgeSegmentManifestRunExtraLen(flags: u32) !usize {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    const run_flags = flags & edge_segment_manifest_known_run_flags;
    if ((run_flags & edge_segment_manifest_run_from_range) != 0 and (run_flags & edge_segment_manifest_run_two_split) != 0) {
        return error.InvalidRecord;
    }
    return if ((run_flags & edge_segment_manifest_run_two_split) != 0) 16 else 0;
}

fn writeEdgeSegmentManifestRunExtra(
    io: std.Io,
    file: std.Io.File,
    offset: u64,
    run_encoding: EdgeSegmentManifestRunEncoding,
) !u64 {
    if ((run_encoding.flags & edge_segment_manifest_run_two_split) == 0) return offset;
    var extra: [16]u8 = undefined;
    std.mem.writeInt(u64, extra[0..8], run_encoding.first_max, .little);
    std.mem.writeInt(u64, extra[8..16], run_encoding.second_min, .little);
    try file.writePositionalAll(io, &extra, offset);
    return std.math.add(u64, offset, extra.len) catch return error.RecordTooLarge;
}

fn edgeSegmentManifestEdgeCountExtraLen(flags: u32) !usize {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    const run_flags = flags & edge_segment_manifest_known_run_flags;
    if ((run_flags & edge_segment_manifest_run_from_range) != 0 and (run_flags & edge_segment_manifest_run_two_split) != 0) {
        return error.InvalidRecord;
    }
    const explicit = (flags & edge_segment_manifest_edge_count_explicit) != 0;
    if (explicit and run_flags != 0) return error.InvalidRecord;
    if (!explicit and run_flags == 0) return error.InvalidRecord;
    return if (explicit) 8 else 0;
}

fn writeEdgeSegmentManifestEdgeCountExtra(
    io: std.Io,
    file: std.Io.File,
    offset: u64,
    entry: EdgeSegmentManifestEntry,
    flags: u32,
) !u64 {
    if (try edgeSegmentManifestEdgeCountExtraLen(flags) == 0) return offset;
    var extra: [8]u8 = undefined;
    std.mem.writeInt(u64, &extra, entry.edge_count, .little);
    try file.writePositionalAll(io, &extra, offset);
    return std.math.add(u64, offset, extra.len) catch return error.RecordTooLarge;
}

fn edgeSegmentManifestDigestExtraLen(flags: u32) !usize {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    return if ((flags & edge_segment_manifest_edge_digest_explicit) != 0) 8 else 0;
}

fn writeEdgeSegmentManifestDigestExtra(
    io: std.Io,
    file: std.Io.File,
    offset: u64,
    entry: EdgeSegmentManifestEntry,
    flags: u32,
) !u64 {
    if (try edgeSegmentManifestDigestExtraLen(flags) == 0) return offset;
    var extra: [8]u8 = undefined;
    std.mem.writeInt(u64, &extra, entry.edge_id_digest, .little);
    try file.writePositionalAll(io, &extra, offset);
    return std.math.add(u64, offset, extra.len) catch return error.RecordTooLarge;
}

fn edgeSegmentManifestNodeRangeIsFull(range: segment_mod.ImmutableAdjacencySegment.NodeIdRange) bool {
    return range.min == EdgeSegmentManifestEntry.full_node_range.min and
        range.max == EdgeSegmentManifestEntry.full_node_range.max;
}

fn encodeEdgeSegmentManifestEndpointEncoding(entry: EdgeSegmentManifestEntry) !EdgeSegmentManifestEndpointEncoding {
    if (entry.src_node_range.min > entry.src_node_range.max or
        entry.dst_node_range.min > entry.dst_node_range.max)
    {
        return error.InvalidRecord;
    }

    var encoding = EdgeSegmentManifestEndpointEncoding{
        .flags = 0,
        .src_min = entry.src_node_range.min,
        .src_max = entry.src_node_range.max,
        .dst_min = entry.dst_node_range.min,
        .dst_max = entry.dst_node_range.max,
    };
    if (edgeSegmentManifestNodeRangeIsFull(entry.src_node_range)) {
        encoding.flags |= edge_segment_manifest_src_full;
        encoding.src_min = 0;
        encoding.src_max = 0;
    } else if (entry.src_node_range.min == entry.src_node_range.max) {
        encoding.flags |= edge_segment_manifest_src_single;
        encoding.src_max = 0;
    }
    if (edgeSegmentManifestNodeRangeIsFull(entry.dst_node_range)) {
        encoding.flags |= edge_segment_manifest_dst_full;
        encoding.dst_min = 0;
        encoding.dst_max = 0;
    } else if (entry.dst_node_range.min == entry.dst_node_range.max) {
        encoding.flags |= edge_segment_manifest_dst_single;
        encoding.dst_max = 0;
    }
    return encoding;
}

fn edgeSegmentManifestEndpointExtraLen(flags: u32) !usize {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    if ((flags & edge_segment_manifest_src_single) != 0 and (flags & edge_segment_manifest_src_full) != 0) {
        return error.InvalidRecord;
    }
    if ((flags & edge_segment_manifest_dst_single) != 0 and (flags & edge_segment_manifest_dst_full) != 0) {
        return error.InvalidRecord;
    }
    var len: usize = 0;
    if ((flags & edge_segment_manifest_src_full) == 0) len += 8;
    if ((flags & (edge_segment_manifest_src_single | edge_segment_manifest_src_full)) == 0) len += 8;
    if ((flags & edge_segment_manifest_dst_full) == 0) len += 8;
    if ((flags & (edge_segment_manifest_dst_single | edge_segment_manifest_dst_full)) == 0) len += 8;
    return len;
}

fn writeEdgeSegmentManifestEndpointExtra(
    io: std.Io,
    file: std.Io.File,
    offset: u64,
    encoding: EdgeSegmentManifestEndpointEncoding,
) !u64 {
    var extra: [32]u8 = undefined;
    var len: usize = 0;
    if ((encoding.flags & edge_segment_manifest_src_full) == 0) {
        std.mem.writeInt(u64, extra[len..][0..8], encoding.src_min, .little);
        len += 8;
    }
    if ((encoding.flags & (edge_segment_manifest_src_single | edge_segment_manifest_src_full)) == 0) {
        std.mem.writeInt(u64, extra[len..][0..8], encoding.src_max, .little);
        len += 8;
    }
    if ((encoding.flags & edge_segment_manifest_dst_full) == 0) {
        std.mem.writeInt(u64, extra[len..][0..8], encoding.dst_min, .little);
        len += 8;
    }
    if ((encoding.flags & (edge_segment_manifest_dst_single | edge_segment_manifest_dst_full)) == 0) {
        std.mem.writeInt(u64, extra[len..][0..8], encoding.dst_max, .little);
        len += 8;
    }
    if (len == 0) return offset;
    try file.writePositionalAll(io, extra[0..len], offset);
    return std.math.add(u64, offset, len) catch return error.RecordTooLarge;
}

fn edgeSegmentManifestSingletonRelExtraLen(flags: u32) !usize {
    if ((flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    if ((flags & edge_segment_manifest_virtual_singleton) == 0) return 0;
    if ((flags & edge_segment_manifest_path_relative) != 0) return error.InvalidRecord;
    return 2;
}

fn writeEdgeSegmentManifestSingletonRelExtra(
    io: std.Io,
    file: std.Io.File,
    offset: u64,
    entry: EdgeSegmentManifestEntry,
    flags: u32,
) !u64 {
    if (try edgeSegmentManifestSingletonRelExtraLen(flags) == 0) return offset;
    const rel = entry.singleton_rel orelse return error.InvalidRecord;
    var extra: [2]u8 = undefined;
    std.mem.writeInt(u16, &extra, @intFromEnum(rel), .little);
    try file.writePositionalAll(io, &extra, offset);
    return std.math.add(u64, offset, extra.len) catch return error.RecordTooLarge;
}

fn decodeEdgeSegmentManifestEndpointRanges(
    flags: u32,
    src_min: u64,
    dst_min: u64,
    src_max_extra: u64,
    dst_max_extra: u64,
) !struct {
    src_node_range: segment_mod.ImmutableAdjacencySegment.NodeIdRange,
    dst_node_range: segment_mod.ImmutableAdjacencySegment.NodeIdRange,
} {
    _ = try edgeSegmentManifestEndpointExtraLen(flags);
    const src_node_range = if ((flags & edge_segment_manifest_src_full) != 0) blk: {
        if (src_min != 0 or src_max_extra != 0) return error.InvalidRecord;
        break :blk EdgeSegmentManifestEntry.full_node_range;
    } else if ((flags & edge_segment_manifest_src_single) != 0) blk: {
        if (src_min == 0 or src_max_extra != 0) return error.InvalidRecord;
        break :blk segment_mod.ImmutableAdjacencySegment.NodeIdRange{ .min = src_min, .max = src_min };
    } else blk: {
        if (src_min == 0 or src_max_extra < src_min) return error.InvalidRecord;
        break :blk segment_mod.ImmutableAdjacencySegment.NodeIdRange{ .min = src_min, .max = src_max_extra };
    };
    const dst_node_range = if ((flags & edge_segment_manifest_dst_full) != 0) blk: {
        if (dst_min != 0 or dst_max_extra != 0) return error.InvalidRecord;
        break :blk EdgeSegmentManifestEntry.full_node_range;
    } else if ((flags & edge_segment_manifest_dst_single) != 0) blk: {
        if (dst_min == 0 or dst_max_extra != 0) return error.InvalidRecord;
        break :blk segment_mod.ImmutableAdjacencySegment.NodeIdRange{ .min = dst_min, .max = dst_min };
    } else blk: {
        if (dst_min == 0 or dst_max_extra < dst_min) return error.InvalidRecord;
        break :blk segment_mod.ImmutableAdjacencySegment.NodeIdRange{ .min = dst_min, .max = dst_max_extra };
    };
    return .{ .src_node_range = src_node_range, .dst_node_range = dst_node_range };
}

fn encodeEdgeSegmentManifestEntryHeader(entry: EdgeSegmentManifestEntry, out: *[EdgeSegmentManifest.entry_header_len]u8) !void {
    return encodeEdgeSegmentManifestEntryHeaderForPath(entry, entry.path.len, 0, out);
}

fn encodeEdgeSegmentManifestEntryHeaderForPath(
    entry: EdgeSegmentManifestEntry,
    encoded_path_len: usize,
    extra_flags: u32,
    out: *[EdgeSegmentManifest.entry_header_len]u8,
) !void {
    if ((extra_flags & ~edge_segment_manifest_path_relative) != 0) return error.InvalidRecord;
    if (encoded_path_len > std.math.maxInt(u32)) return error.RecordTooLarge;
    const virtual_entry = edgeSegmentManifestEntryIsVirtual(entry);
    if (virtual_entry) {
        try edgeSegmentManifestValidateVirtualEntryShape(entry);
        if (encoded_path_len != 0 or (extra_flags & edge_segment_manifest_path_relative) != 0) return error.InvalidRecord;
    } else if (encoded_path_len == 0) return error.RecordTooLarge;
    if (entry.edge_count == 0 or
        entry.edge_id_range.min > entry.edge_id_range.max or
        entry.src_node_range.min > entry.src_node_range.max or
        entry.dst_node_range.min > entry.dst_node_range.max)
    {
        return error.InvalidRecord;
    }
    const run_encoding = try encodeEdgeSegmentManifestRunEncoding(entry);
    const endpoint_encoding = try encodeEdgeSegmentManifestEndpointEncoding(entry);
    var entry_flags = run_encoding.flags | endpoint_encoding.flags | extra_flags;
    if (virtual_entry) entry_flags |= edge_segment_manifest_virtual_singleton;
    if (!edgeSegmentManifestCanDeriveEdgeCount(entry)) entry_flags |= edge_segment_manifest_edge_count_explicit;
    if (!edgeSegmentManifestCanDeriveEdgeIdDigest(entry)) entry_flags |= edge_segment_manifest_edge_digest_explicit;
    if (entry.edge_id_order_digest != 0) entry_flags |= edge_segment_manifest_order_digest_explicit;
    std.mem.writeInt(u32, out[0..4], @intCast(encoded_path_len), .little);
    std.mem.writeInt(u32, out[4..8], entry_flags, .little);
    std.mem.writeInt(u64, out[8..16], entry.edge_id_range.min, .little);
    std.mem.writeInt(u64, out[16..24], entry.edge_id_range.max, .little);
}

fn decodeEdgeSegmentManifestHeader(bytes: *const [EdgeSegmentManifest.header_len]u8) !struct { segment_count: u32, total_edges: u64 } {
    if (!std.mem.eql(u8, bytes[0..4], &EdgeSegmentManifest.multi_magic)) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[4..6], .little) != EdgeSegmentManifest.version) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[6..8], .little) != EdgeSegmentManifest.header_len) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[12..14], .little) != EdgeSegmentManifest.entry_header_len) return error.InvalidRecord;
    if (!allZero(bytes[14..16])) return error.InvalidRecord;
    const segment_count = std.mem.readInt(u32, bytes[8..12], .little);
    if (segment_count == 0) return error.InvalidRecord;
    return .{
        .segment_count = segment_count,
        .total_edges = std.mem.readInt(u64, bytes[16..24], .little),
    };
}

fn decodeEdgeSegmentManifestEntryHeader(bytes: *const [EdgeSegmentManifest.entry_header_len]u8) !struct {
    path_len: u32,
    edge_id_range: segment_mod.ImmutableAdjacencySegment.EdgeIdRange,
    entry_flags: u32,
} {
    const entry_flags = std.mem.readInt(u32, bytes[4..8], .little);
    if ((entry_flags & ~edge_segment_manifest_known_flags) != 0) return error.InvalidRecord;
    _ = try edgeSegmentManifestOrderDigestExtraLen(entry_flags);
    _ = try edgeSegmentManifestRunExtraLen(entry_flags);
    _ = try edgeSegmentManifestEdgeCountExtraLen(entry_flags);
    _ = try edgeSegmentManifestDigestExtraLen(entry_flags);
    _ = try edgeSegmentManifestEndpointExtraLen(entry_flags);
    _ = try edgeSegmentManifestSingletonRelExtraLen(entry_flags);
    const path_len = std.mem.readInt(u32, bytes[0..4], .little);
    if ((entry_flags & edge_segment_manifest_virtual_singleton) != 0) {
        if (path_len != 0) return error.InvalidRecord;
    } else if (path_len == 0) return error.InvalidRecord;
    const edge_id_min = std.mem.readInt(u64, bytes[8..16], .little);
    const edge_id_max = std.mem.readInt(u64, bytes[16..24], .little);
    if (edge_id_min > edge_id_max) {
        return error.InvalidRecord;
    }
    return .{
        .path_len = path_len,
        .edge_id_range = .{ .min = edge_id_min, .max = edge_id_max },
        .entry_flags = entry_flags,
    };
}

fn encodeEdgeSegmentIdIndexHeader(
    summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    edge_id_order_digest: u64,
    out: *[EdgeSegmentIdIndex.header_len]u8,
) void {
    @memcpy(out[0..4], &EdgeSegmentIdIndex.magic);
    std.mem.writeInt(u16, out[4..6], EdgeSegmentIdIndex.version, .little);
    std.mem.writeInt(u16, out[6..8], EdgeSegmentIdIndex.header_len, .little);
    std.mem.writeInt(u64, out[8..16], summary.count, .little);
    std.mem.writeInt(u64, out[16..24], summary.range.min, .little);
    std.mem.writeInt(u64, out[24..32], summary.range.max, .little);
    std.mem.writeInt(u64, out[32..40], summary.digest, .little);
    std.mem.writeInt(u64, out[40..48], edge_id_order_digest, .little);
}

fn decodeEdgeSegmentIdIndexHeader(bytes: *const [EdgeSegmentIdIndex.header_len]u8) !EdgeSegmentIdIndexHeader {
    if (!std.mem.eql(u8, bytes[0..4], &EdgeSegmentIdIndex.magic)) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[4..6], .little) != EdgeSegmentIdIndex.version) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[6..8], .little) != EdgeSegmentIdIndex.header_len) return error.InvalidRecord;
    const edge_count = std.mem.readInt(u64, bytes[8..16], .little);
    const edge_id_min = std.mem.readInt(u64, bytes[16..24], .little);
    const edge_id_max = std.mem.readInt(u64, bytes[24..32], .little);
    if (edge_count == 0 or edge_id_min > edge_id_max) return error.InvalidRecord;
    return .{
        .edge_count = edge_count,
        .edge_id_min = edge_id_min,
        .edge_id_max = edge_id_max,
        .edge_id_digest = std.mem.readInt(u64, bytes[32..40], .little),
        .edge_id_order_digest = std.mem.readInt(u64, bytes[40..48], .little),
    };
}

fn edgeSegmentIdIndexFileSize(edge_count: u64) !u64 {
    const records = std.math.mul(u64, edge_count, 8) catch return error.RecordTooLarge;
    return std.math.add(u64, EdgeSegmentIdIndex.header_len, records) catch return error.RecordTooLarge;
}

fn edgeSegmentIdDigest(edge_id: u64) u64 {
    var bytes: [8]u8 = undefined;
    std.mem.writeInt(u64, &bytes, edge_id, .little);
    return std.hash.Wyhash.hash(0x544B_4549, &bytes);
}

fn edgeSegmentIdIndexOrderDigest(records_by_id: []const EdgeIndexRecord) u64 {
    var digest: u64 = 0;
    for (records_by_id, 0..) |record, index| {
        digest ^= edgeSegmentIdIndexOrderDigestAt(index, record.edge_id);
    }
    return digest;
}

fn edgeSegmentIdRunSummaryFromRecords(records_by_id: []const EdgeIndexRecord) EdgeSegmentIdRunSummary {
    var builder = EdgeSegmentIdRunBuilder{};
    for (records_by_id) |record| builder.add(record.edge_id);
    return builder.finish();
}

fn edgeSegmentIdSidecarSummaryFromCompleteRuns(
    summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
    runs: EdgeSegmentIdRunSummary,
) !?EdgeSegmentIdSidecarSummary {
    if (runs.run_count == 0) return null;
    if (try runs.coveredCount() != summary.count) return null;
    if (runs.first_min != summary.range.min) return null;
    const max = if (runs.run_count == 2) runs.second_max else runs.first_max;
    if (max != summary.range.max) return null;
    if (try edgeSegmentIdRunSummaryDigest(runs) != summary.digest) return null;
    return .{
        .edge_id_order_digest = 0,
        .edge_id_runs = runs,
    };
}

fn edgeSegmentIdSidecarSummaryFromCompleteRange(
    summary: segment_mod.ImmutableAdjacencySegment.EdgeIdSummary,
) !?EdgeSegmentIdSidecarSummary {
    if (summary.count == 0 or summary.range.min == 0 or summary.range.max == std.math.maxInt(u64)) return null;
    if (summary.range.min > summary.range.max) return null;
    const span = std.math.add(u64, summary.range.max - summary.range.min, 1) catch return error.RecordTooLarge;
    if (span != summary.count) return null;
    return try edgeSegmentIdSidecarSummaryFromCompleteRuns(summary, .{
        .run_count = 1,
        .first_min = summary.range.min,
        .first_max = summary.range.max,
    });
}

fn edgeSegmentIdRunSummaryDigest(runs: EdgeSegmentIdRunSummary) !u64 {
    try runs.validate();
    var digest: u64 = 0;
    digest ^= try edgeSegmentIdRangeDigest(runs.first_min, runs.first_max);
    if (runs.run_count == 2) digest ^= try edgeSegmentIdRangeDigest(runs.second_min, runs.second_max);
    return digest;
}

fn edgeSegmentIdRangeDigest(min: u64, max: u64) !u64 {
    if (min == 0 or max == std.math.maxInt(u64) or min > max) return error.InvalidRecord;
    var digest: u64 = 0;
    var edge_id = min;
    while (true) {
        digest ^= edgeSegmentIdDigest(edge_id);
        if (edge_id == max) break;
        edge_id += 1;
    }
    return digest;
}

fn edgeSegmentIdRunBuilderFromSummary(summary: EdgeSegmentIdRunSummary) !EdgeSegmentIdRunBuilder {
    try summary.validate();
    var builder = EdgeSegmentIdRunBuilder{};
    switch (summary.run_count) {
        0 => {},
        1 => builder.addRange(summary.first_min, summary.first_max),
        2 => {
            builder.addRange(summary.first_min, summary.first_max);
            builder.addRange(summary.second_min, summary.second_max);
        },
        else => return error.InvalidRecord,
    }
    return builder;
}

fn extendEdgeSegmentIdRunSummaryWithRecords(
    summary: EdgeSegmentIdRunSummary,
    old_count: u64,
    records_by_id: []const EdgeIndexRecord,
) ?EdgeSegmentIdRunSummary {
    const covered = summary.coveredCount() catch return null;
    if (covered != old_count) return null;
    var builder = edgeSegmentIdRunBuilderFromSummary(summary) catch return null;
    for (records_by_id) |record| builder.add(record.edge_id);
    const next = builder.finish();
    const expected_count = std.math.add(u64, old_count, @intCast(records_by_id.len)) catch return null;
    const next_covered = next.coveredCount() catch return null;
    if (next_covered != expected_count) return null;
    return next;
}

fn extendEdgeSegmentIdRunSummaryWithEdge(
    summary: EdgeSegmentIdRunSummary,
    old_count: u64,
    edge_id: u64,
) ?EdgeSegmentIdRunSummary {
    const covered = summary.coveredCount() catch return null;
    if (covered != old_count) return null;
    var builder = edgeSegmentIdRunBuilderFromSummary(summary) catch return null;
    builder.add(edge_id);
    const next = builder.finish();
    const expected_count = std.math.add(u64, old_count, 1) catch return null;
    const next_covered = next.coveredCount() catch return null;
    if (next_covered != expected_count) return null;
    return next;
}

fn edgeSegmentIdIndexOrderDigestAt(index: usize, edge_id: u64) u64 {
    var bytes: [16]u8 = undefined;
    std.mem.writeInt(u64, bytes[0..8], @intCast(index), .little);
    std.mem.writeInt(u64, bytes[8..16], edge_id, .little);
    return std.hash.Wyhash.hash(0x544B_454F, &bytes);
}

fn u64LessThan(_: void, lhs: u64, rhs: u64) bool {
    return lhs < rhs;
}

fn lowerBoundU64(items: []const u64, needle: u64) usize {
    var lo: usize = 0;
    var hi: usize = items.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (items[mid] < needle) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

fn upperBoundU64(items: []const u64, needle: u64) usize {
    var lo: usize = 0;
    var hi: usize = items.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (items[mid] <= needle) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

fn sortedSetIntersectsRange(items: []const u64, min: u64, max: u64) bool {
    const index = lowerBoundU64(items, min);
    return index < items.len and items[index] <= max;
}

fn u64SortedContains(items: []const u64, needle: u64) bool {
    const index = lowerBoundU64(items, needle);
    return index < items.len and items[index] == needle;
}

fn sortEdgeIndexRecords(order: EdgeIndexOrder, records: []EdgeIndexRecord) void {
    switch (order) {
        .id => std.mem.sort(EdgeIndexRecord, records, {}, edgeIndexByIdLessThan),
        .src => std.mem.sort(EdgeIndexRecord, records, {}, edgeIndexBySrcLessThan),
        .dst => std.mem.sort(EdgeIndexRecord, records, {}, edgeIndexByDstLessThan),
    }
}

const EdgeIndexRecordOrderContext = struct {
    order: EdgeIndexOrder,
    records: []const EdgeIndexRecord,
};

fn edgeIndexRecordOrderLessThan(context: EdgeIndexRecordOrderContext, lhs: u32, rhs: u32) bool {
    return edgeIndexLessThan(context.order, context.records[@intCast(lhs)], context.records[@intCast(rhs)]);
}

fn edgeIndexRecordOptionalOrderLessThan(order_map: *std.AutoHashMap(u64, u64), lhs: EdgeIndexRecord, rhs: EdgeIndexRecord) bool {
    const lhs_order = order_map.get(lhs.edge_id);
    const rhs_order = order_map.get(rhs.edge_id);
    if (lhs_order != null and rhs_order != null and lhs_order.? != rhs_order.?) return lhs_order.? < rhs_order.?;
    if (lhs_order != null and rhs_order == null) return true;
    if (lhs_order == null and rhs_order != null) return false;
    return lhs.edge_id < rhs.edge_id;
}

fn edgeOrderRecordLessThan(_: void, lhs: EdgeOrderRecord, rhs: EdgeOrderRecord) bool {
    if (lhs.src != rhs.src) return lhs.src < rhs.src;
    if (lhs.order_key != rhs.order_key) return lhs.order_key < rhs.order_key;
    if (lhs.edge_id != rhs.edge_id) return lhs.edge_id < rhs.edge_id;
    return lhs.rel < rhs.rel;
}

fn validateEdgeOrderRecord(record: EdgeOrderRecord) !void {
    if (record.src == 0 or record.src == std.math.maxInt(u64)) return error.InvalidRecord;
    if (record.edge_id == 0 or record.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
    if (record.order_key == std.math.maxInt(u64)) return error.InvalidRecord;
    if (relKindFromInt(record.rel) == null) return error.InvalidRecord;
}

fn sortEdgeIndexRecordOrder(order: EdgeIndexOrder, records: []const EdgeIndexRecord, record_order: []u32) void {
    const context = EdgeIndexRecordOrderContext{ .order = order, .records = records };
    std.mem.sort(u32, record_order, context, edgeIndexRecordOrderLessThan);
}

fn edgeRecordDigest(record: EdgeIndexRecord) u64 {
    var bytes: [26]u8 = undefined;
    std.mem.writeInt(u64, bytes[0..8], record.edge_id, .little);
    std.mem.writeInt(u64, bytes[8..16], record.src, .little);
    std.mem.writeInt(u16, bytes[16..18], record.rel, .little);
    std.mem.writeInt(u64, bytes[18..26], record.dst, .little);
    return std.hash.Wyhash.hash(0x544B_4745, &bytes);
}

fn edgeOrderRecordDigest(record: EdgeOrderRecord) u64 {
    var bytes: [EdgeOrderRecord.encoded_len]u8 = undefined;
    record.encode(&bytes);
    return std.hash.Wyhash.hash(0x544B_4F52, &bytes);
}

fn edgeIndexRecordFromEdge(edge: graph_mod.Edge) EdgeIndexRecord {
    return .{
        .src = edge.src.toInt(),
        .dst = edge.dst.toInt(),
        .edge_id = edge.id.toInt(),
        .rel = @intFromEnum(edge.rel),
    };
}

fn edgeIndexRecordEquals(lhs: EdgeIndexRecord, rhs: EdgeIndexRecord) bool {
    return lhs.src == rhs.src and
        lhs.dst == rhs.dst and
        lhs.edge_id == rhs.edge_id and
        lhs.rel == rhs.rel;
}

fn tombstoneDigest(records: []const EdgeTombstoneRecord) u64 {
    var digest: u64 = 0;
    for (records) |record| digest ^= record.edge_digest;
    return digest;
}

fn edgeTombstoneSliceContains(records: []const EdgeTombstoneRecord, edge_id: u64) bool {
    var lo: usize = 0;
    var hi: usize = records.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (records[mid].edge_id < edge_id) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo < records.len and records[lo].edge_id == edge_id;
}

fn mergeEdgeTombstones(
    existing: []const EdgeTombstoneRecord,
    batch: []const EdgeTombstoneRecord,
    out: *std.ArrayList(EdgeTombstoneRecord),
) !void {
    var existing_index: usize = 0;
    var batch_index: usize = 0;
    while (existing_index < existing.len or batch_index < batch.len) {
        const take_existing = if (batch_index >= batch.len)
            true
        else if (existing_index >= existing.len)
            false
        else
            existing[existing_index].edge_id < batch[batch_index].edge_id;
        const record = if (take_existing) record: {
            const value = existing[existing_index];
            existing_index += 1;
            break :record value;
        } else record: {
            const value = batch[batch_index];
            batch_index += 1;
            break :record value;
        };
        if (out.items.len != 0 and out.items[out.items.len - 1].edge_id >= record.edge_id) return core.Error.InvalidId;
        out.appendAssumeCapacity(record);
    }
}

fn nodeRecordDigestFromParts(id: u64, kind: core.NodeKind, text: []const u8) !u64 {
    if (text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
    var fixed: [node_record_digest_fixed_len]u8 = undefined;
    std.mem.writeInt(u64, fixed[0..8], id, .little);
    std.mem.writeInt(u16, fixed[8..10], @intFromEnum(kind), .little);
    std.mem.writeInt(u32, fixed[10..14], @intCast(text.len), .little);
    var hasher = std.hash.Wyhash.init(0);
    hasher.update(&fixed);
    hasher.update(text);
    return hasher.final();
}

fn nodeRecordDigestFromPayload(payload: []const u8) !u64 {
    _ = payload;
    return error.InvalidRecord;
}

const EdgeIndexDigest = struct {
    count: u64 = 0,
    digest: u64 = 0,
    order_digest: u64 = 0,

    fn add(self: *EdgeIndexDigest, record: EdgeIndexRecord) void {
        self.addWithDigest(record, edgeRecordDigest(record));
    }

    fn addWithDigest(self: *EdgeIndexDigest, record: EdgeIndexRecord, record_digest: u64) void {
        self.order_digest = edgeIndexOrderDigestStep(self.order_digest, self.count, record);
        self.digest ^= record_digest;
        self.count += 1;
    }

    fn eql(self: EdgeIndexDigest, other: EdgeIndexDigest) bool {
        return self.count == other.count and self.digest == other.digest;
    }
};

fn edgeIndexOrderDigestStep(previous: u64, position: u64, record: EdgeIndexRecord) u64 {
    var bytes: [34]u8 = undefined;
    std.mem.writeInt(u64, bytes[0..8], previous, .little);
    std.mem.writeInt(u64, bytes[8..16], position, .little);
    std.mem.writeInt(u64, bytes[16..24], edgeRecordDigest(record), .little);
    std.mem.writeInt(u64, bytes[24..32], record.edge_id, .little);
    std.mem.writeInt(u16, bytes[32..34], record.rel, .little);
    return std.hash.Wyhash.hash(0x544B_4758, &bytes);
}

fn activeNodeCount(graph: *const graph_mod.Graph) u64 {
    var count: u64 = 0;
    for (graph.nodes.items) |node| {
        if (node.status == .active) count += 1;
    }
    return count;
}

const ActiveNodeSet = struct {
    allocator: std.mem.Allocator,
    ids: Ids,
    count: u64 = 0,

    const Dense = struct {
        bits: std.DynamicBitSetUnmanaged,
    };

    const Ids = union(enum) {
        dense: Dense,
        sparse: std.AutoHashMap(u64, void),
    };

    fn deinit(self: *ActiveNodeSet) void {
        switch (self.ids) {
            .dense => |*dense| dense.bits.deinit(self.allocator),
            .sparse => |*sparse| sparse.deinit(),
        }
    }

    fn contains(self: ActiveNodeSet, id: u64) bool {
        if (id == 0 or id == std.math.maxInt(u64)) return false;
        return switch (self.ids) {
            .dense => |dense| blk: {
                const index = std.math.cast(usize, id - 1) orelse break :blk false;
                break :blk index < dense.bits.capacity() and dense.bits.isSet(index);
            },
            .sparse => |sparse| sparse.contains(id),
        };
    }
};

const GraphIndexStats = struct {
    active_nodes: u64 = 0,
    visible_edges: u64 = 0,
    physical_edges: u64 = 0,
    node_digest: u64 = 0,
    edge_digest: u64 = 0,
    physical_edge_digest: u64 = 0,
    node_by_text_order_digest: u64 = 0,
    edge_by_id_order_digest: u64 = 0,
    edge_by_src_order_digest: u64 = 0,
    edge_by_dst_order_digest: u64 = 0,
    max_edge_id_seen: u64 = 0,
};

const GraphCurrentMetaStats = struct {
    active_nodes: u64 = 0,
    visible_edges: u64 = 0,
    node_digest: u64 = 0,
    edge_digest: u64 = 0,
    max_edge_id_seen: u64 = 0,
};

const GraphEdgeIndexStats = struct {
    visible_edges: u64 = 0,
    physical_edges: u64 = 0,
    edge_digest: u64 = 0,
    physical_edge_digest: u64 = 0,
};

fn graphCurrentMetaStats(allocator: std.mem.Allocator, graph: *const graph_mod.Graph) !GraphCurrentMetaStats {
    var active_nodes = try buildActiveNodeSet(allocator, graph);
    defer active_nodes.deinit();
    var edge_ids = try GraphPhysicalEdgeIdSet.init(allocator, @intCast(graph.edges.items.len));
    defer edge_ids.deinit();

    var out = GraphCurrentMetaStats{ .active_nodes = active_nodes.count };
    for (graph.nodes.items) |node| {
        if (node.status != .active) continue;
        out.node_digest ^= try nodeRecordDigestFromParts(node.id.toInt(), node.kind, node.text);
    }

    for (graph.edges.items) |edge| {
        const record = (try physicalEdgeRecord(&active_nodes, edge)) orelse continue;
        if (try edge_ids.put(record.edge_id)) return core.Error.InvalidId;
        out.max_edge_id_seen = @max(out.max_edge_id_seen, record.edge_id);
        if (edge.status == .active) {
            out.visible_edges += 1;
            out.edge_digest ^= edgeRecordDigest(record);
        }
    }
    return out;
}

const GraphPhysicalEdgeIdSet = struct {
    allocator: std.mem.Allocator,
    dense_limit: u64,
    dense_bits: std.ArrayList(u8) = .empty,
    overflow: std.AutoHashMap(u64, void),
    count: u64 = 0,

    fn init(allocator: std.mem.Allocator, expected_edges: u64) !GraphPhysicalEdgeIdSet {
        return .{
            .allocator = allocator,
            .dense_limit = try denseLimit(expected_edges),
            .overflow = std.AutoHashMap(u64, void).init(allocator),
        };
    }

    fn deinit(self: *GraphPhysicalEdgeIdSet) void {
        self.overflow.deinit();
        self.dense_bits.deinit(self.allocator);
    }

    fn put(self: *GraphPhysicalEdgeIdSet, edge_id: u64) !bool {
        if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const found = if (edge_id <= self.dense_limit)
            try self.putDense(edge_id)
        else
            try self.putOverflow(edge_id);
        if (!found) self.count = std.math.add(u64, self.count, 1) catch return error.InvalidRecord;
        return found;
    }

    fn putDense(self: *GraphPhysicalEdgeIdSet, edge_id: u64) !bool {
        const bit = edge_id - 1;
        const byte_index = std.math.cast(usize, bit / 8) orelse return error.RecordTooLarge;
        if (byte_index >= self.dense_bits.items.len) {
            const old_len = self.dense_bits.items.len;
            const min_len = byte_index + 1;
            const doubled = std.math.mul(usize, @max(old_len, 4096), 2) catch return error.RecordTooLarge;
            const next_len = @max(min_len, doubled);
            try self.dense_bits.resize(self.allocator, next_len);
            @memset(self.dense_bits.items[old_len..], 0);
        }
        const mask = @as(u8, 1) << @intCast(bit % 8);
        const found = (self.dense_bits.items[byte_index] & mask) != 0;
        self.dense_bits.items[byte_index] |= mask;
        return found;
    }

    fn putOverflow(self: *GraphPhysicalEdgeIdSet, edge_id: u64) !bool {
        return (try self.overflow.getOrPut(edge_id)).found_existing;
    }

    fn denseLimit(expected_edges: u64) !u64 {
        const scaled = std.math.mul(u64, expected_edges, graph_edge_id_set_dense_ratio) catch graph_edge_id_set_dense_max_id;
        return @min(@max(graph_edge_id_set_dense_min_id, scaled), graph_edge_id_set_dense_max_id);
    }
};

fn graphEdgeIndexStats(allocator: std.mem.Allocator, graph: *const graph_mod.Graph) !GraphEdgeIndexStats {
    var active_nodes = try buildActiveNodeSet(allocator, graph);
    defer active_nodes.deinit();

    var out = GraphEdgeIndexStats{};
    for (graph.edges.items) |edge| {
        const record = (try physicalEdgeRecord(&active_nodes, edge)) orelse continue;
        out.physical_edges += 1;
        const digest = edgeRecordDigest(record);
        out.physical_edge_digest ^= digest;
        if (edge.status == .active) {
            out.visible_edges += 1;
            out.edge_digest ^= digest;
        }
    }
    return out;
}

fn graphIndexStats(allocator: std.mem.Allocator, graph: *const graph_mod.Graph) !GraphIndexStats {
    var active_nodes = try buildActiveNodeSet(allocator, graph);
    defer active_nodes.deinit();
    var edge_order = std.ArrayList(u32).empty;
    defer edge_order.deinit(allocator);
    var text_order = std.ArrayList(u32).empty;
    defer text_order.deinit(allocator);
    try text_order.ensureTotalCapacity(allocator, @intCast(active_nodes.count));

    var out = GraphIndexStats{ .active_nodes = active_nodes.count };
    var text_bytes: u64 = 0;
    for (graph.nodes.items, 0..) |node, node_index| {
        if (node.status != .active) continue;
        if (node.text.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        out.node_digest ^= try nodeRecordDigestFromParts(node.id.toInt(), node.kind, node.text);
        text_order.appendAssumeCapacity(std.math.cast(u32, node_index) orelse return error.RecordTooLarge);
        text_bytes = std.math.add(u64, text_bytes, node.text.len) catch return error.RecordTooLarge;
    }
    std.mem.sort(u32, text_order.items, GraphNodeTextOrderContext{ .graph = graph }, graphNodeTextOrderLessThan);
    out.node_by_text_order_digest = graphNodeTextOrderDigest(graph, text_order.items);

    for (graph.edges.items, 0..) |edge, edge_index| {
        const record = (try physicalEdgeRecord(&active_nodes, edge)) orelse continue;
        out.physical_edges += 1;
        const digest = edgeRecordDigest(record);
        out.physical_edge_digest ^= digest;
        out.max_edge_id_seen = @max(out.max_edge_id_seen, record.edge_id);
        if (edge.status == .active) {
            out.visible_edges += 1;
            out.edge_digest ^= digest;
        }
        try edge_order.append(allocator, std.math.cast(u32, edge_index) orelse return error.RecordTooLarge);
    }
    std.mem.sort(u32, edge_order.items, GraphEdgeOrderContext{ .graph = graph, .order = .id }, graphEdgeOrderLessThan);
    var previous_edge_id: u64 = 0;
    for (edge_order.items) |edge_index| {
        const record = edgeIndexRecordFromEdge(graph.edges.items[@intCast(edge_index)]);
        if (record.edge_id == previous_edge_id) return error.InvalidRecord;
        previous_edge_id = record.edge_id;
    }
    out.edge_by_id_order_digest = graphEdgeOrderDigest(graph, edge_order.items);
    std.mem.sort(u32, edge_order.items, GraphEdgeOrderContext{ .graph = graph, .order = .src }, graphEdgeOrderLessThan);
    out.edge_by_src_order_digest = graphEdgeOrderDigest(graph, edge_order.items);
    std.mem.sort(u32, edge_order.items, GraphEdgeOrderContext{ .graph = graph, .order = .dst }, graphEdgeOrderLessThan);
    out.edge_by_dst_order_digest = graphEdgeOrderDigest(graph, edge_order.items);
    return out;
}

fn nodeTextOrderDigestForRecords(records: []const NodeTextIndexRecord) u64 {
    var digest = NodeTextIndexDigest{};
    for (records) |record| digest.add(record, 0);
    return digest.order_digest;
}

fn sortedNodeTextBatchOrderDigest(records: []const NodeTextIndexRecord) !u64 {
    var order_digest: u64 = 0;
    var previous: ?NodeTextIndexRecord = null;
    for (records, 0..) |record, position| {
        if (previous) |prev| {
            if (!nodeTextIndexLessThan({}, prev, record)) return error.InvalidRecord;
            if (prev.id == record.id) return error.InvalidRecord;
        }
        order_digest = nodeTextIndexOrderDigestStep(order_digest, @intCast(position), record);
        previous = record;
    }
    return order_digest;
}

fn nodeTextRecordIdRange(records: []const NodeTextIndexRecord) !struct { min: u64, max: u64 } {
    if (records.len == 0) return error.InvalidRecord;
    var min_id = records[0].id;
    var max_id = records[0].id;
    for (records[1..]) |record| {
        if (record.id < min_id) min_id = record.id;
        if (record.id > max_id) max_id = record.id;
    }
    if (min_id == 0 or max_id < min_id) return error.InvalidRecord;
    return .{ .min = min_id, .max = max_id };
}

fn nodeTextRecordHashRange(records: []const NodeTextIndexRecord) !struct { min: u64, max: u64 } {
    if (records.len == 0) return error.InvalidRecord;
    var min_hash = records[0].hash;
    var max_hash = records[0].hash;
    for (records[1..]) |record| {
        if (record.hash < min_hash) min_hash = record.hash;
        if (record.hash > max_hash) max_hash = record.hash;
    }
    return .{ .min = min_hash, .max = max_hash };
}

const GraphNodeTextOrderContext = struct {
    graph: *const graph_mod.Graph,
};

fn graphNodeTextOrderLessThan(context: GraphNodeTextOrderContext, lhs: u32, rhs: u32) bool {
    const lhs_node = context.graph.nodes.items[@intCast(lhs)];
    const rhs_node = context.graph.nodes.items[@intCast(rhs)];
    const lhs_hash = nodeTextHash(lhs_node.text);
    const rhs_hash = nodeTextHash(rhs_node.text);
    if (lhs_hash != rhs_hash) return lhs_hash < rhs_hash;
    if (lhs_node.id != rhs_node.id) return nodeIdLessThan({}, lhs_node.id, rhs_node.id);
    return @intFromEnum(lhs_node.kind) < @intFromEnum(rhs_node.kind);
}

fn graphNodeTextOrderDigest(graph: *const graph_mod.Graph, order: []const u32) u64 {
    var order_digest: u64 = 0;
    for (order, 0..) |node_index, position| {
        const node = graph.nodes.items[@intCast(node_index)];
        order_digest = nodeTextIndexOrderDigestStepParts(
            order_digest,
            @intCast(position),
            nodeTextHash(node.text),
            node.id.toInt(),
            @intFromEnum(node.kind),
        );
    }
    return order_digest;
}

fn edgeOrderDigestForRecords(records: []const EdgeIndexRecord) u64 {
    var digest = EdgeIndexDigest{};
    for (records) |record| digest.add(record);
    return digest.order_digest;
}

const GraphEdgeOrderContext = struct {
    graph: *const graph_mod.Graph,
    order: EdgeIndexOrder,
};

fn graphEdgeOrderLessThan(context: GraphEdgeOrderContext, lhs: u32, rhs: u32) bool {
    const lhs_record = edgeIndexRecordFromEdge(context.graph.edges.items[@intCast(lhs)]);
    const rhs_record = edgeIndexRecordFromEdge(context.graph.edges.items[@intCast(rhs)]);
    return edgeIndexLessThan(context.order, lhs_record, rhs_record);
}

fn graphEdgeOrderDigest(graph: *const graph_mod.Graph, order: []const u32) u64 {
    var digest = EdgeIndexDigest{};
    for (order) |edge_index| digest.add(edgeIndexRecordFromEdge(graph.edges.items[@intCast(edge_index)]));
    return digest.order_digest;
}

fn edgeTombstoneLessThan(_: void, lhs: EdgeTombstoneRecord, rhs: EdgeTombstoneRecord) bool {
    return lhs.edge_id < rhs.edge_id;
}

fn buildActiveNodeSet(allocator: std.mem.Allocator, graph: *const graph_mod.Graph) !ActiveNodeSet {
    var count: u64 = 0;
    var max_node_id: u64 = 0;
    for (graph.nodes.items) |node| {
        if (node.status != .active) continue;
        try graph_mod.validateNodeText(node.text);
        const id = node.id.toInt();
        if (id == 0 or id == std.math.maxInt(u64)) return core.Error.InvalidId;
        count = std.math.add(u64, count, 1) catch return error.InvalidRecord;
        max_node_id = @max(max_node_id, id);
    }

    if (try activeNodeSetShouldUseDense(max_node_id, count)) {
        const bit_count = std.math.cast(usize, max_node_id) orelse return error.RecordTooLarge;
        var out = ActiveNodeSet{
            .allocator = allocator,
            .ids = .{ .dense = .{ .bits = try std.DynamicBitSetUnmanaged.initEmpty(allocator, bit_count) } },
            .count = count,
        };
        errdefer out.deinit();
        for (graph.nodes.items) |node| {
            if (node.status != .active) continue;
            const index = std.math.cast(usize, node.id.toInt() - 1) orelse return error.RecordTooLarge;
            if (out.ids.dense.bits.isSet(index)) return core.Error.InvalidId;
            out.ids.dense.bits.set(index);
        }
        return out;
    }

    var out = ActiveNodeSet{
        .allocator = allocator,
        .ids = .{ .sparse = std.AutoHashMap(u64, void).init(allocator) },
        .count = count,
    };
    errdefer out.deinit();
    try out.ids.sparse.ensureTotalCapacity(@intCast(count));
    for (graph.nodes.items) |node| {
        if (node.status != .active) continue;
        const entry = try out.ids.sparse.getOrPut(node.id.toInt());
        if (entry.found_existing) return core.Error.InvalidId;
    }
    return out;
}

fn activeNodeSetShouldUseDense(max_node_id: u64, count: u64) !bool {
    if (count == 0 or max_node_id == 0 or max_node_id > active_node_set_dense_max_id) return false;
    const scaled = std.math.mul(u64, count, active_node_set_dense_ratio) catch active_node_set_dense_max_id;
    return max_node_id <= @max(active_node_set_dense_min_id, scaled);
}

fn visibleEdgeRecord(active_nodes: *const ActiveNodeSet, edge: graph_mod.Edge) !?EdgeIndexRecord {
    if (edge.status != .active) return null;
    return physicalEdgeRecord(active_nodes, edge);
}

fn physicalEdgeRecord(active_nodes: *const ActiveNodeSet, edge: graph_mod.Edge) !?EdgeIndexRecord {
    if (edge.status != .active and edge.status != .deleted) return null;
    const edge_id = edge.id.toInt();
    const src = edge.src.toInt();
    const dst = edge.dst.toInt();
    if (edge_id == 0 or edge_id == std.math.maxInt(u64)) return core.Error.InvalidId;
    if (src == 0 or dst == 0 or src == std.math.maxInt(u64) or dst == std.math.maxInt(u64)) return core.Error.InvalidId;
    if (!active_nodes.contains(src) or !active_nodes.contains(dst)) return null;
    return .{
        .src = src,
        .dst = dst,
        .edge_id = edge_id,
        .rel = @intFromEnum(edge.rel),
    };
}

fn edgeIndexRecordKey(record: EdgeIndexRecord, order: EdgeIndexOrder) u64 {
    return switch (order) {
        .id => record.edge_id,
        .src => record.src,
        .dst => record.dst,
    };
}

fn edgeIndexRecordNodeRelLessThan(record: EdgeIndexRecord, order: EdgeIndexOrder, key: u64, rel: u16) bool {
    const record_key = edgeIndexRecordKey(record, order);
    if (record_key != key) return record_key < key;
    return switch (order) {
        .src, .dst => record.rel < rel,
        .id => false,
    };
}

fn nodeTextHash(text: []const u8) u64 {
    return std.hash.Wyhash.hash(0, text);
}

fn nodeTextIndexLessThan(_: void, lhs: NodeTextIndexRecord, rhs: NodeTextIndexRecord) bool {
    if (lhs.hash != rhs.hash) return lhs.hash < rhs.hash;
    if (lhs.id != rhs.id) return lhs.id < rhs.id;
    return lhs.kind < rhs.kind;
}

fn nodeTextIndexOrderDigestStepParts(previous: u64, position: u64, hash: u64, id: u64, kind: u16) u64 {
    var bytes: [34]u8 = undefined;
    std.mem.writeInt(u64, bytes[0..8], previous, .little);
    std.mem.writeInt(u64, bytes[8..16], position, .little);
    std.mem.writeInt(u64, bytes[16..24], hash, .little);
    std.mem.writeInt(u64, bytes[24..32], id, .little);
    std.mem.writeInt(u16, bytes[32..34], kind, .little);
    return std.hash.Wyhash.hash(0x544B_474D, &bytes);
}

fn nodeTextIndexOrderDigestStep(previous: u64, position: u64, record: NodeTextIndexRecord) u64 {
    return nodeTextIndexOrderDigestStepParts(previous, position, record.hash, record.id, record.kind);
}

fn combinedNodeTextOrderDigest(base: NodeTextIndexHeader, delta: NodeTextIndexHeader) u64 {
    if (delta.node_count == 0) return base.order_digest;
    var bytes: [48]u8 = undefined;
    std.mem.writeInt(u64, bytes[0..8], base.node_count, .little);
    std.mem.writeInt(u64, bytes[8..16], base.node_digest, .little);
    std.mem.writeInt(u64, bytes[16..24], base.order_digest, .little);
    std.mem.writeInt(u64, bytes[24..32], delta.node_count, .little);
    std.mem.writeInt(u64, bytes[32..40], delta.node_digest, .little);
    std.mem.writeInt(u64, bytes[40..48], delta.order_digest, .little);
    return std.hash.Wyhash.hash(0x544B_474C, &bytes);
}

fn combinedNodeTextOrderDigestWithRuns(base: NodeTextIndexHeader, delta: NodeTextIndexHeader, runs: []const OwnedNodeTextRunManifestEntry) u64 {
    var digest = combinedNodeTextOrderDigest(base, delta);
    if (runs.len == 0) return digest;
    for (runs) |run| {
        var bytes: [56]u8 = undefined;
        std.mem.writeInt(u64, bytes[0..8], digest, .little);
        std.mem.writeInt(u64, bytes[8..16], base.node_count, .little);
        std.mem.writeInt(u64, bytes[16..24], delta.node_count, .little);
        std.mem.writeInt(u64, bytes[24..32], run.node_count, .little);
        std.mem.writeInt(u64, bytes[32..40], run.node_digest, .little);
        std.mem.writeInt(u64, bytes[40..48], run.order_digest, .little);
        std.mem.writeInt(u64, bytes[48..56], std.hash.Wyhash.hash(0x544B_4E52, run.path), .little);
        digest = std.hash.Wyhash.hash(0x544B_4E4D, &bytes);
    }
    return digest;
}

fn combinedNodeTextOrderDigestWithRunEntries(base: NodeTextIndexHeader, delta: NodeTextIndexHeader, runs: []const NodeTextRunManifestEntry) u64 {
    var digest = combinedNodeTextOrderDigest(base, delta);
    if (runs.len == 0) return digest;
    for (runs) |run| {
        var bytes: [56]u8 = undefined;
        std.mem.writeInt(u64, bytes[0..8], digest, .little);
        std.mem.writeInt(u64, bytes[8..16], base.node_count, .little);
        std.mem.writeInt(u64, bytes[16..24], delta.node_count, .little);
        std.mem.writeInt(u64, bytes[24..32], run.node_count, .little);
        std.mem.writeInt(u64, bytes[32..40], run.node_digest, .little);
        std.mem.writeInt(u64, bytes[40..48], run.order_digest, .little);
        std.mem.writeInt(u64, bytes[48..56], std.hash.Wyhash.hash(0x544B_4E52, run.path), .little);
        digest = std.hash.Wyhash.hash(0x544B_4E4D, &bytes);
    }
    return digest;
}

fn nodeTextBaseHeaderCoversMeta(base: NodeTextIndexHeader, meta: IndexMeta) bool {
    return base.node_count == meta.nodes and
        base.node_digest == meta.node_digest and
        base.order_digest == meta.node_by_text_order_digest;
}

fn nodeTextRunManifestTotalNodesOwned(entries: []const OwnedNodeTextRunManifestEntry) ?u64 {
    var total: u64 = 0;
    for (entries) |entry| {
        total = std.math.add(u64, total, entry.node_count) catch return null;
    }
    return total;
}

fn nodeTextRunManifestDigestOwned(entries: []const OwnedNodeTextRunManifestEntry) u64 {
    var digest: u64 = 0;
    for (entries) |entry| digest ^= entry.node_digest;
    return digest;
}

fn nodeTextRunManifestEntryMayContainHash(entry: OwnedNodeTextRunManifestEntry, hash: u64) bool {
    return hash >= entry.min_hash and hash <= entry.max_hash and nodeTextRunHashFilterMayContain(entry.hash_filter, hash);
}

fn nodeTextLookupRunMayContainHash(run: Store.NodeTextLookupRun, hash: u64) bool {
    return nodeTextRunHashFilterMayContain(run.hash_filter, hash);
}

fn nodeTextRunHashFilterShouldBuild(record_count: u64) bool {
    return nodeTextRunHashFilterLenForRecords(record_count) != 0;
}

fn nodeTextRunHashFilterLenForRecords(record_count: u64) usize {
    if (record_count < node_text_run_hash_filter_min_records) return 0;
    const target_bytes = std.math.mul(u64, record_count, node_text_run_hash_filter_target_bytes_per_record) catch std.math.maxInt(u64);
    const clamped = @min(@max(target_bytes, node_text_run_hash_filter_min_bytes), node_text_run_hash_filter_max_bytes);
    const filter_len = std.math.ceilPowerOfTwoAssert(usize, @intCast(clamped));
    return @min(filter_len, node_text_run_hash_filter_max_bytes);
}

fn nodeTextRunHashFilterLenValid(filter_len: u64) bool {
    if (filter_len == 0) return true;
    if (filter_len < node_text_run_hash_filter_min_bytes) return false;
    if (filter_len > node_text_run_hash_filter_max_bytes) return false;
    return std.math.isPowerOfTwo(filter_len);
}

fn nodeTextBaseHashFilterLenForRecords(record_count: u64) usize {
    if (record_count < node_text_base_hash_filter_min_records) return 0;
    const target_bytes = std.math.mul(u64, record_count, node_text_base_hash_filter_target_bytes_per_record) catch std.math.maxInt(u64);
    const clamped = @min(@max(target_bytes, node_text_base_hash_filter_min_bytes), node_text_base_hash_filter_max_bytes);
    const filter_len = std.math.ceilPowerOfTwoAssert(usize, @intCast(clamped));
    return @min(filter_len, node_text_base_hash_filter_max_bytes);
}

fn nodeTextBaseHashFilterLenValid(filter_len: u64) bool {
    if (filter_len == 0) return false;
    if (filter_len < node_text_base_hash_filter_min_bytes) return false;
    if (filter_len > node_text_base_hash_filter_max_bytes) return false;
    return std.math.isPowerOfTwo(filter_len);
}

fn nodeTextHashFilterDigest(filter: []const u8) u64 {
    return std.hash.Wyhash.hash(0x544B_4E42, filter);
}

fn nodeTextRunHashFilterProbe(hash: u64, probe_index: usize, mask: u64) u64 {
    var delta = hash;
    delta ^= delta >> 33;
    delta *%= 0xff51afd7ed558ccd;
    delta ^= delta >> 33;
    delta *%= 0xc4ceb9fe1a85ec53;
    delta ^= delta >> 33;
    delta |= 1;
    return (hash +% (@as(u64, @intCast(probe_index)) *% delta)) & mask;
}

fn nodeTextRunHashFilterSet(filter: []u8, hash: u64) void {
    std.debug.assert(nodeTextRunHashFilterLenValid(filter.len));
    std.debug.assert(filter.len != 0);
    const mask: u64 = @intCast(filter.len * 8 - 1);
    var probe_index: usize = 0;
    while (probe_index < node_text_run_hash_filter_probes) : (probe_index += 1) {
        const bit = nodeTextRunHashFilterProbe(hash, probe_index, mask);
        filter[@intCast(bit >> 3)] |= @as(u8, 1) << @intCast(bit & 7);
    }
}

fn nodeTextRunHashFilterMayContain(filter: []const u8, hash: u64) bool {
    if (filter.len == 0) return true;
    if (!nodeTextRunHashFilterLenValid(filter.len)) return true;
    const mask: u64 = @intCast(filter.len * 8 - 1);
    var probe_index: usize = 0;
    while (probe_index < node_text_run_hash_filter_probes) : (probe_index += 1) {
        const bit = nodeTextRunHashFilterProbe(hash, probe_index, mask);
        if ((filter[@intCast(bit >> 3)] & (@as(u8, 1) << @intCast(bit & 7))) == 0) return false;
    }
    return true;
}

fn nodeTextRunManifestDigestFields(entries: anytype, include_hash_filter: bool) u64 {
    var hasher = std.hash.Wyhash.init(0x544B_4E52);
    var bytes: [8]u8 = undefined;
    for (entries) |entry| {
        std.mem.writeInt(u64, &bytes, entry.node_count, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.node_digest, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.order_digest, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.min_node_id, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.max_node_id, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.min_hash, .little);
        hasher.update(&bytes);
        std.mem.writeInt(u64, &bytes, entry.max_hash, .little);
        hasher.update(&bytes);
        hasher.update(entry.path);
        if (include_hash_filter) hasher.update(entry.hash_filter);
    }
    return hasher.final();
}

fn nodeTextRunManifestEpochDigestOwned(entries: []const OwnedNodeTextRunManifestEntry) u64 {
    return nodeTextRunManifestDigestFields(entries, false);
}

fn nodeTextRunManifestContentDigestOwned(entries: []const OwnedNodeTextRunManifestEntry) u64 {
    return nodeTextRunManifestDigestFields(entries, true);
}

fn nodeTextRunManifestContentDigest(entries: []const NodeTextRunManifestEntry) u64 {
    return nodeTextRunManifestDigestFields(entries, true);
}

fn encodeNodeTextRunManifestHeader(entries: []const NodeTextRunManifestEntry, out: *[NodeTextRunManifest.header_len]u8) !void {
    if (entries.len > node_text_run_manifest_max_entries) return core.Error.BudgetExceeded;
    var total_nodes: u64 = 0;
    var node_digest: u64 = 0;
    for (entries) |entry| {
        if (entry.node_count == 0 or entry.node_count > node_text_run_max_records) return error.InvalidRecord;
        if (entry.min_node_id == 0 or entry.max_node_id < entry.min_node_id) return error.InvalidRecord;
        if (entry.min_hash > entry.max_hash) return error.InvalidRecord;
        if (entry.path.len == 0 or entry.path.len > node_text_run_current_max_path_bytes) return error.InvalidRecord;
        if (!nodeTextRunHashFilterLenValid(entry.hash_filter.len)) return error.InvalidRecord;
        total_nodes = std.math.add(u64, total_nodes, entry.node_count) catch return error.InvalidRecord;
        node_digest ^= entry.node_digest;
    }
    @memcpy(out[0..4], &NodeTextRunManifest.magic);
    std.mem.writeInt(u16, out[4..6], NodeTextRunManifest.version, .little);
    std.mem.writeInt(u16, out[6..8], NodeTextRunManifest.header_len, .little);
    std.mem.writeInt(u32, out[8..12], @intCast(entries.len), .little);
    @memset(out[12..16], 0);
    std.mem.writeInt(u64, out[16..24], total_nodes, .little);
    std.mem.writeInt(u64, out[24..32], node_digest, .little);
    std.mem.writeInt(u64, out[32..40], nodeTextRunManifestContentDigest(entries), .little);
}

fn decodeNodeTextRunManifestHeader(bytes: *const [NodeTextRunManifest.header_len]u8) !struct { run_count: usize, total_nodes: u64, node_digest: u64, content_digest: u64 } {
    if (!std.mem.eql(u8, bytes[0..4], &NodeTextRunManifest.magic)) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[4..6], .little) != NodeTextRunManifest.version) return error.InvalidRecord;
    if (std.mem.readInt(u16, bytes[6..8], .little) != NodeTextRunManifest.header_len) return error.InvalidRecord;
    if (!allZero(bytes[12..16])) return error.InvalidRecord;
    const run_count = std.mem.readInt(u32, bytes[8..12], .little);
    if (run_count > node_text_run_manifest_max_entries) return error.InvalidRecord;
    return .{
        .run_count = @intCast(run_count),
        .total_nodes = std.mem.readInt(u64, bytes[16..24], .little),
        .node_digest = std.mem.readInt(u64, bytes[24..32], .little),
        .content_digest = std.mem.readInt(u64, bytes[32..40], .little),
    };
}

fn encodeNodeTextRunManifestEntryHeader(entry: NodeTextRunManifestEntry, out: *[NodeTextRunManifest.entry_header_len]u8) !void {
    if (entry.node_count == 0 or entry.node_count > node_text_run_max_records) return error.InvalidRecord;
    if (entry.min_node_id == 0 or entry.max_node_id < entry.min_node_id) return error.InvalidRecord;
    if (entry.min_hash > entry.max_hash) return error.InvalidRecord;
    if (entry.path.len == 0 or entry.path.len > node_text_run_current_max_path_bytes) return error.InvalidRecord;
    if (!nodeTextRunHashFilterLenValid(entry.hash_filter.len)) return error.InvalidRecord;
    std.mem.writeInt(u64, out[0..8], entry.node_count, .little);
    std.mem.writeInt(u64, out[8..16], entry.node_digest, .little);
    std.mem.writeInt(u64, out[16..24], entry.order_digest, .little);
    std.mem.writeInt(u64, out[24..32], entry.min_node_id, .little);
    std.mem.writeInt(u64, out[32..40], entry.max_node_id, .little);
    std.mem.writeInt(u64, out[40..48], entry.min_hash, .little);
    std.mem.writeInt(u64, out[48..56], entry.max_hash, .little);
    std.mem.writeInt(u32, out[56..60], @intCast(entry.path.len), .little);
    std.mem.writeInt(u32, out[60..64], @intCast(entry.hash_filter.len), .little);
}

fn decodeNodeTextRunManifestEntryHeader(bytes: *const [NodeTextRunManifest.entry_header_len]u8) !struct { node_count: u64, node_digest: u64, order_digest: u64, min_node_id: u64, max_node_id: u64, min_hash: u64, max_hash: u64, path_len: u64, hash_filter_len: u64 } {
    const min_node_id = std.mem.readInt(u64, bytes[24..32], .little);
    const max_node_id = std.mem.readInt(u64, bytes[32..40], .little);
    if (min_node_id == 0 or max_node_id < min_node_id) return error.InvalidRecord;
    const min_hash = std.mem.readInt(u64, bytes[40..48], .little);
    const max_hash = std.mem.readInt(u64, bytes[48..56], .little);
    if (min_hash > max_hash) return error.InvalidRecord;
    return .{
        .node_count = std.mem.readInt(u64, bytes[0..8], .little),
        .node_digest = std.mem.readInt(u64, bytes[8..16], .little),
        .order_digest = std.mem.readInt(u64, bytes[16..24], .little),
        .min_node_id = min_node_id,
        .max_node_id = max_node_id,
        .min_hash = min_hash,
        .max_hash = max_hash,
        .path_len = std.mem.readInt(u32, bytes[56..60], .little),
        .hash_filter_len = std.mem.readInt(u32, bytes[60..64], .little),
    };
}

fn storedNodeIdLessThan(_: void, lhs: StoredNode, rhs: StoredNode) bool {
    return lhs.id.toInt() < rhs.id.toInt();
}

fn nodeIdLessThan(_: void, lhs: core.NodeId, rhs: core.NodeId) bool {
    return lhs.toInt() < rhs.toInt();
}

fn validateNodeTextLookupRecord(record: NodeTextIndexRecord, by_id: NodeByIdRecord, kind: core.NodeKind, text_len: usize) !void {
    const expected_len = std.math.cast(u32, text_len) orelse return error.InvalidRecord;
    if (by_id.id != record.id) return error.InvalidRecord;
    if ((try by_id.nodeKind()) != kind) return error.InvalidRecord;
    if (by_id.text_offset != record.text_offset) return error.InvalidRecord;
    if (by_id.text_len != record.text_len) return error.InvalidRecord;
    if (record.text_len != expected_len) return error.InvalidRecord;
}

const NodeTextIndexDigest = struct {
    count: u64 = 0,
    digest: u64 = 0,
    order_digest: u64 = 0,
    min_node_id: u64 = 0,
    max_node_id: u64 = 0,
    min_hash: u64 = 0,
    max_hash: u64 = 0,

    fn add(self: *NodeTextIndexDigest, record: NodeTextIndexRecord, record_digest: u64) void {
        self.order_digest = nodeTextIndexOrderDigestStep(self.order_digest, self.count, record);
        self.digest ^= record_digest;
        if (self.count == 0 or record.id < self.min_node_id) self.min_node_id = record.id;
        if (record.id > self.max_node_id) self.max_node_id = record.id;
        if (self.count == 0 or record.hash < self.min_hash) self.min_hash = record.hash;
        if (self.count == 0 or record.hash > self.max_hash) self.max_hash = record.hash;
        self.count += 1;
    }
};

fn nameSpanLessThan(_: void, lhs: TextSpan, rhs: TextSpan) bool {
    if (lhs.offset != rhs.offset) return lhs.offset < rhs.offset;
    return lhs.len < rhs.len;
}

fn textSpansCoverTextsFile(spans: []TextSpan, texts_size: u64) bool {
    std.mem.sort(TextSpan, spans, {}, nameSpanLessThan);
    var cursor: u64 = 0;
    var previous: ?TextSpan = null;
    for (spans) |span| {
        if (previous) |prev| {
            if (prev.offset == span.offset and prev.len == span.len) continue;
        }
        previous = span;
        if (span.offset != cursor) return false;
        cursor = std.math.add(u64, cursor, span.len) catch return false;
    }
    return cursor == texts_size;
}

fn isReservedNodeId(id: core.NodeId) bool {
    return id == .none or id.toInt() == std.math.maxInt(u64);
}

fn edgeIndexFileSize(edge_count: u64) !u64 {
    return edgeIndexFileSizeWithRecordLen(edge_count, EdgeIndexRecord.encoded_len);
}

fn edgeIndexFileSizeForHeader(header: EdgeIndexHeader) !u64 {
    try header.validateShape();
    const directory_size = try edgeIndexKeyRunDirectorySizeForHeader(header);
    const rows_size = std.math.mul(u64, header.edge_count, header.record_len) catch return error.InvalidRecord;
    const with_directory = std.math.add(u64, EdgeIndexHeader.encoded_len, directory_size) catch return error.InvalidRecord;
    return std.math.add(u64, with_directory, rows_size) catch return error.InvalidRecord;
}

fn edgeIndexFileSizeWithRecordLen(edge_count: u64, record_len: u16) !u64 {
    if (record_len == 0) return error.InvalidRecord;
    const max_records_size = std.math.maxInt(u64) - EdgeIndexHeader.encoded_len;
    if (edge_count > max_records_size / record_len) return error.InvalidRecord;
    return EdgeIndexHeader.encoded_len + edge_count * record_len;
}

fn edgeTombstoneFileSize(count: u64) !u64 {
    const max_records_size = std.math.maxInt(u64) - EdgeTombstoneHeader.encoded_len;
    if (count > max_records_size / EdgeTombstoneRecord.encoded_len) return error.InvalidRecord;
    return EdgeTombstoneHeader.encoded_len + count * EdgeTombstoneRecord.encoded_len;
}

fn edgeTombstoneRecordOffset(index: u64) !u64 {
    const bytes = std.math.mul(u64, index, EdgeTombstoneRecord.encoded_len) catch return error.InvalidRecord;
    return std.math.add(u64, EdgeTombstoneHeader.encoded_len, bytes) catch return error.InvalidRecord;
}

fn edgeIndexRecordOffset(index: u64) !u64 {
    return edgeIndexRecordOffsetWithLen(index, EdgeIndexRecord.encoded_len);
}

fn edgeIndexRecordOffsetForHeader(header: EdgeIndexHeader, index: u64) !u64 {
    try header.validateShape();
    const directory_size = try edgeIndexKeyRunDirectorySizeForHeader(header);
    const rows_base = std.math.add(u64, EdgeIndexHeader.encoded_len, directory_size) catch return error.InvalidRecord;
    const bytes = std.math.mul(u64, index, header.record_len) catch return error.InvalidRecord;
    return std.math.add(u64, rows_base, bytes) catch return error.InvalidRecord;
}

fn edgeIndexRecordOffsetWithLen(index: u64, record_len: u16) !u64 {
    const bytes = std.math.mul(u64, index, record_len) catch return error.InvalidRecord;
    return std.math.add(u64, EdgeIndexHeader.encoded_len, bytes) catch return error.InvalidRecord;
}

fn edgeIndexStoredEndpointLen(header: EdgeIndexHeader) usize {
    if (header.hasKeyRunConstantOpposite()) return 0;
    if (header.hasKeyRuns()) return if (header.hasU32NodeIds()) 4 else 8;
    return if (header.hasU32NodeIds()) 8 else 16;
}

fn edgeIndexStoredEdgeIdLen(header: EdgeIndexHeader) usize {
    if (header.hasDenseId() or header.hasKeyRunLinearEdgeIds()) return 0;
    return if (header.hasU32EdgeIds()) 4 else 8;
}

fn edgeIndexKeyRunRecordLen(header: EdgeIndexHeader) usize {
    var len: usize = if (header.hasU32NodeIds()) 8 else 16;
    if (header.hasKeyRunConstantOpposite() and !header.hasKeyRunRingOpposite()) len += if (header.hasU32NodeIds()) 4 else 8;
    if (header.hasKeyRunLinearEdgeIds()) {
        len += if (header.hasU32EdgeIds()) 4 else 8;
        if (!header.hasKeyRunUniformEdgeIdStep()) len += if (header.hasU32EdgeIds()) 4 else 8;
    }
    return len;
}

fn edgeIndexKeyRunDirectorySizeForHeader(header: EdgeIndexHeader) !u64 {
    if (!header.hasKeyRuns()) return 0;
    const explicit_runs = if (header.hasKeyRunDenseSpan())
        header.key_run_count - @as(u32, @intCast(header.key_run_dense_count))
    else
        header.key_run_count;
    return std.math.mul(u64, explicit_runs, edgeIndexKeyRunRecordLen(header)) catch return error.InvalidRecord;
}

fn edgeIndexKeyRunOffsetForHeader(header: EdgeIndexHeader, run_index: u64) !u64 {
    try header.validateShape();
    if (!header.hasKeyRuns() or run_index >= header.key_run_count) return error.InvalidRecord;
    const explicit_index = if (header.hasKeyRunDenseSpan()) explicit_index: {
        const dense_end = std.math.add(u64, header.key_run_dense_run_start, header.key_run_dense_count) catch return error.InvalidRecord;
        if (run_index >= header.key_run_dense_run_start and run_index < dense_end) return error.InvalidRecord;
        break :explicit_index if (run_index < header.key_run_dense_run_start)
            run_index
        else
            run_index - header.key_run_dense_count;
    } else run_index;
    const bytes = std.math.mul(u64, explicit_index, edgeIndexKeyRunRecordLen(header)) catch return error.InvalidRecord;
    return std.math.add(u64, EdgeIndexHeader.encoded_len, bytes) catch return error.InvalidRecord;
}

fn nodeByIdFileSize(max_node_id: u64) !u64 {
    return nodeByIdFileSizeWithRecordLen(max_node_id, NodeByIdRecord.encoded_len);
}

fn nodeByIdFileSizeForHeader(header: NodeByIdHeader) !u64 {
    try header.validateShape();
    const records_size = try nodeByIdRecordsByteLen(header.max_node_id, header.record_len);
    var size = try std.math.add(u64, NodeByIdHeader.encoded_len, records_size);
    if (header.hasDerivedTextOffset()) {
        const checkpoints = try nodeByIdTextOffsetCheckpointCount(header);
        const checkpoint_bytes = std.math.mul(u64, checkpoints, 8) catch return error.InvalidRecord;
        size = std.math.add(u64, size, checkpoint_bytes) catch return error.InvalidRecord;
    }
    return size;
}

fn nodeByIdFileSizeWithRecordLen(max_node_id: u64, record_len: u16) !u64 {
    if (record_len == 0) return error.InvalidRecord;
    const records_size = try nodeByIdRecordsByteLen(max_node_id, record_len);
    return std.math.add(u64, NodeByIdHeader.encoded_len, records_size) catch return error.InvalidRecord;
}

fn nodeByIdRecordsByteLen(max_node_id: u64, record_len: u16) !u64 {
    if (record_len == 0) return error.InvalidRecord;
    return std.math.mul(u64, max_node_id, record_len) catch return error.InvalidRecord;
}

fn nodeByIdRecordOffset(node_id: u64) !u64 {
    return nodeByIdRecordOffsetWithLen(node_id, NodeByIdRecord.encoded_len);
}

fn nodeByIdRecordOffsetForHeader(header: NodeByIdHeader, node_id: u64) !u64 {
    try header.validateShape();
    return nodeByIdRecordOffsetWithLen(node_id, header.record_len);
}

fn nodeByIdRecordOffsetWithLen(node_id: u64, record_len: u16) !u64 {
    if (node_id == 0) return error.InvalidRecord;
    const index = node_id - 1;
    const bytes = std.math.mul(u64, index, record_len) catch return error.InvalidRecord;
    return std.math.add(u64, NodeByIdHeader.encoded_len, bytes) catch return error.InvalidRecord;
}

const node_by_id_text_offset_checkpoint_stride: u64 = 128;

fn nodeByIdTextOffsetCheckpointCount(header: NodeByIdHeader) !u64 {
    try header.validateShape();
    if (!header.hasDerivedTextOffset()) return 0;
    return header.max_node_id / node_by_id_text_offset_checkpoint_stride +
        @intFromBool((header.max_node_id % node_by_id_text_offset_checkpoint_stride) != 0);
}

fn nodeByIdTextOffsetCheckpointBlock(node_id: u64) !u64 {
    if (node_id == 0) return error.InvalidRecord;
    return (node_id - 1) / node_by_id_text_offset_checkpoint_stride;
}

fn nodeByIdTextOffsetCheckpointTableOffset(header: NodeByIdHeader) !u64 {
    try header.validateShape();
    const records_size = try nodeByIdRecordsByteLen(header.max_node_id, header.record_len);
    return std.math.add(u64, NodeByIdHeader.encoded_len, records_size) catch return error.InvalidRecord;
}

fn nodeByIdTextOffsetCheckpointOffset(header: NodeByIdHeader, block: u64) !u64 {
    const checkpoint_count = try nodeByIdTextOffsetCheckpointCount(header);
    if (block >= checkpoint_count) return error.InvalidRecord;
    const table_offset = try nodeByIdTextOffsetCheckpointTableOffset(header);
    const byte_offset = std.math.mul(u64, block, 8) catch return error.InvalidRecord;
    return std.math.add(u64, table_offset, byte_offset) catch return error.InvalidRecord;
}

fn readDerivedNodeByIdTextLenFromMap(header: NodeByIdHeader, map: *const std.Io.File.MemoryMap, node_id: u64) !u32 {
    const offset = try nodeByIdRecordOffsetForHeader(header, node_id);
    const start = std.math.cast(usize, offset) orelse return error.RecordTooLarge;
    const end = std.math.add(usize, start, 2) catch return error.InvalidRecord;
    if (end > map.memory.len) return error.InvalidRecord;
    return readU16(map.memory[start..end]);
}

fn deriveNodeByIdTextOffsetFromMap(header: NodeByIdHeader, map: *const std.Io.File.MemoryMap, node_id: u64) !u64 {
    const block = try nodeByIdTextOffsetCheckpointBlock(node_id);
    const checkpoint_offset = try nodeByIdTextOffsetCheckpointOffset(header, block);
    const checkpoint_start = std.math.cast(usize, checkpoint_offset) orelse return error.RecordTooLarge;
    const checkpoint_end = std.math.add(usize, checkpoint_start, 8) catch return error.InvalidRecord;
    if (checkpoint_end > map.memory.len) return error.InvalidRecord;
    var text_offset = readU64(map.memory[checkpoint_start..checkpoint_end]);
    var id = block * node_by_id_text_offset_checkpoint_stride + 1;
    while (id < node_id) : (id += 1) {
        text_offset = std.math.add(u64, text_offset, try readDerivedNodeByIdTextLenFromMap(header, map, id)) catch return error.InvalidRecord;
    }
    return text_offset;
}

fn nodeTextIndexHeaderForRecords(records: []const NodeTextIndexRecord, node_digest: u64, order_digest: u64) NodeTextIndexHeader {
    return nodeTextIndexHeaderForRecordsWithDerivedSpan(records, node_digest, order_digest, false);
}

fn nodeTextIndexHeaderForSortedUniqueHashRecords(records: []const NodeTextIndexRecord, node_digest: u64, order_digest: u64) NodeTextIndexHeader {
    var header = nodeTextIndexHeaderForRecords(records, node_digest, order_digest);
    header.setTextHashUnique(sortedNodeTextRecordsHaveUniqueHashes(records));
    return header;
}

fn sortedNodeTextRecordsHaveUniqueHashes(records: []const NodeTextIndexRecord) bool {
    var previous_hash: ?u64 = null;
    for (records) |record| {
        if (previous_hash) |hash| {
            if (hash >= record.hash) return false;
        }
        previous_hash = record.hash;
    }
    return records.len != 0;
}

fn nodeTextIndexHeaderForRecordsWithDerivedSpan(
    records: []const NodeTextIndexRecord,
    node_digest: u64,
    order_digest: u64,
    derived_text_span: bool,
) NodeTextIndexHeader {
    if (records.len == 0) {
        return .{ .node_count = 0, .node_digest = node_digest, .order_digest = order_digest };
    }
    const uniform_kind = records[0].kind;
    var has_uniform_kind = true;
    var short_text_len = true;
    var u32_id = true;
    for (records) |record| {
        if (record.kind != uniform_kind) has_uniform_kind = false;
        if (record.text_len > std.math.maxInt(u16)) short_text_len = false;
        if (record.id > std.math.maxInt(u32)) u32_id = false;
    }
    return NodeTextIndexHeader.withShape(
        @intCast(records.len),
        node_digest,
        order_digest,
        if (has_uniform_kind) uniform_kind else null,
        short_text_len,
        u32_id,
        false,
        derived_text_span,
    );
}

fn nodeTextRecordFitsHeader(header: NodeTextIndexHeader, record: NodeTextIndexRecord) bool {
    if (header.hasUniformKind() and record.kind != header.uniform_kind) return false;
    if (header.hasShortTextLen() and record.text_len > std.math.maxInt(u16)) return false;
    if (header.hasU32Id() and record.id > std.math.maxInt(u32)) return false;
    return true;
}

fn nodeTextHeaderForTail(old_header: NodeTextIndexHeader, next_count: u64, node_digest: u64, order_digest: u64, records: []const NodeTextIndexRecord) NodeTextIndexHeader {
    var uniform_kind: ?u16 = null;
    if (old_header.hasUniformKind()) {
        uniform_kind = old_header.uniform_kind;
        for (records) |record| {
            if (record.kind != old_header.uniform_kind) {
                uniform_kind = null;
                break;
            }
        }
    }
    var short_text_len = old_header.hasShortTextLen();
    if (short_text_len) {
        for (records) |record| {
            if (record.text_len > std.math.maxInt(u16)) {
                short_text_len = false;
                break;
            }
        }
    }
    var u32_id = old_header.hasU32Id();
    if (u32_id) {
        for (records) |record| {
            if (record.id > std.math.maxInt(u32)) {
                u32_id = false;
                break;
            }
        }
    }
    return NodeTextIndexHeader.withShape(next_count, node_digest, order_digest, uniform_kind, short_text_len, u32_id, false, old_header.hasDerivedTextSpan());
}

fn nodeTextIndexFileSize(node_count: u64) !u64 {
    const max_records_size = std.math.maxInt(u64) - NodeTextIndexHeader.encoded_len;
    if (node_count > max_records_size / NodeTextIndexRecord.encoded_len) return error.InvalidRecord;
    return NodeTextIndexHeader.encoded_len + node_count * NodeTextIndexRecord.encoded_len;
}

fn nodeTextIndexFileSizeForHeader(header: NodeTextIndexHeader) !u64 {
    try header.validateShape();
    const max_records_size = std.math.maxInt(u64) - NodeTextIndexHeader.encoded_len;
    if (header.node_count > max_records_size / header.record_len) return error.InvalidRecord;
    return NodeTextIndexHeader.encoded_len + header.node_count * header.record_len;
}

fn nodeTextIndexRecordOffset(index: u64) !u64 {
    const bytes = std.math.mul(u64, index, NodeTextIndexRecord.encoded_len) catch return error.InvalidRecord;
    return std.math.add(u64, NodeTextIndexHeader.encoded_len, bytes) catch return error.InvalidRecord;
}

fn nodeTextIndexRecordOffsetForHeader(header: NodeTextIndexHeader, index: u64) !u64 {
    try header.validateShape();
    const bytes = std.math.mul(u64, index, header.record_len) catch return error.InvalidRecord;
    return std.math.add(u64, NodeTextIndexHeader.encoded_len, bytes) catch return error.InvalidRecord;
}

fn allZero(bytes: []const u8) bool {
    for (bytes) |byte| {
        if (byte != 0) return false;
    }
    return true;
}

const BinaryRecordKind = enum(u8) {
    node = 'N',
    node_batch = 'M',
    edge = 'E',
    edge_batch = 'A',
    edge_delete = 'D',
    batch_begin = 'B',
    batch_commit = 'C',
};

const BinaryRecordHeader = struct {
    version: u8,
    kind: BinaryRecordKind,
    payload_len: u32,
    payload_checksum: ?u64 = null,

    const magic = [_]u8{ 'T', 'K', 'G', 'E' };
    const current_version: u8 = 2;
    const encoded_len: usize = 18;
    const max_payload_len: u32 = 64 * 1024 * 1024;

    fn decode(bytes: *const [encoded_len]u8) !BinaryRecordHeader {
        if (!std.mem.eql(u8, bytes[0..4], &magic)) return error.InvalidRecord;
        if (bytes[4] != current_version) return error.InvalidRecord;
        const kind: BinaryRecordKind = switch (bytes[5]) {
            'N' => .node,
            'M' => .node_batch,
            'E' => .edge,
            'A' => .edge_batch,
            'D' => .edge_delete,
            'B' => .batch_begin,
            'C' => .batch_commit,
            else => return error.InvalidRecord,
        };
        const payload_len = readU32(bytes[6..10]);
        if (payload_len > max_payload_len) return error.InvalidRecord;
        return .{
            .version = bytes[4],
            .kind = kind,
            .payload_len = payload_len,
            .payload_checksum = readU64(bytes[10..18]),
        };
    }
};

fn binaryPayloadChecksum(payload: []const u8) u64 {
    return std.hash.Wyhash.hash(0, payload);
}

fn validateBinaryChecksum(header: BinaryRecordHeader, payload: []const u8) !void {
    if (header.payload_checksum != null) {
        try validateBinaryChecksumValue(header, binaryPayloadChecksum(payload));
    }
}

fn validateBinaryChecksumValue(header: BinaryRecordHeader, checksum: u64) !void {
    if (header.payload_checksum) |expected| {
        if (expected != checksum) return error.InvalidRecord;
    }
}

fn ensureBinaryPayloadFits(file_size: u64, payload_offset: u64, payload_len: u32) !void {
    if (payload_offset > file_size) return error.InvalidRecord;
    if (@as(u64, payload_len) > file_size - payload_offset) return error.InvalidRecord;
}

fn appendBinaryHeader(out: *std.ArrayList(u8), allocator: std.mem.Allocator, kind: BinaryRecordKind, payload_len: usize, payload_checksum: u64) !void {
    if (payload_len > BinaryRecordHeader.max_payload_len) return error.RecordTooLarge;
    try out.appendSlice(allocator, &BinaryRecordHeader.magic);
    try out.append(allocator, BinaryRecordHeader.current_version);
    try out.append(allocator, @intFromEnum(kind));
    try appendU32(out, allocator, @intCast(payload_len));
    try appendU64(out, allocator, payload_checksum);
}

fn appendBinaryRecord(out: *std.ArrayList(u8), allocator: std.mem.Allocator, kind: BinaryRecordKind, payload: []const u8) !void {
    try appendBinaryHeader(out, allocator, kind, payload.len, binaryPayloadChecksum(payload));
    try out.appendSlice(allocator, payload);
}

const binary_edge_record_len: usize = BinaryRecordHeader.encoded_len + binary_edge_payload_len;
const binary_edge_delete_record_len: usize = BinaryRecordHeader.encoded_len + binary_edge_delete_payload_len;

fn encodeBinaryRecordHeader(out: *[BinaryRecordHeader.encoded_len]u8, kind: BinaryRecordKind, payload_len: u32, payload_checksum: u64) void {
    @memcpy(out[0..4], &BinaryRecordHeader.magic);
    out[4] = BinaryRecordHeader.current_version;
    out[5] = @intFromEnum(kind);
    std.mem.writeInt(u32, out[6..10], payload_len, .little);
    std.mem.writeInt(u64, out[10..18], payload_checksum, .little);
}

fn encodeBinaryNodeFixedPayload(out: *[binary_node_payload_len]u8, node: graph_mod.Node, span: TextSpan) !u32 {
    if (node.text.len > maxBinaryNodeTextLen()) return error.RecordTooLarge;
    if (span.len != node.text.len) return error.InvalidRecord;
    std.mem.writeInt(u64, out[0..8], node.id.toInt(), .little);
    std.mem.writeInt(u16, out[8..10], @intFromEnum(node.kind), .little);
    std.mem.writeInt(u64, out[10..18], span.offset, .little);
    std.mem.writeInt(u32, out[18..22], span.len, .little);
    return binary_node_payload_len;
}

fn appendBinaryNodeRecordToWriter(writer: *StorageBufferedWriter, node: graph_mod.Node, span: TextSpan) !void {
    var payload: [binary_node_payload_len]u8 = undefined;
    const payload_len = try encodeBinaryNodeFixedPayload(&payload, node, span);

    var header: [BinaryRecordHeader.encoded_len]u8 = undefined;
    encodeBinaryRecordHeader(&header, .node, payload_len, binaryPayloadChecksum(&payload));
    try writer.append(&header);
    try writer.append(&payload);
}

fn appendBinaryNodeBatchRecordToWriter(writer: *StorageBufferedWriter, allocator: std.mem.Allocator, nodes: []const graph_mod.Node, spans: []const TextSpan) !void {
    if (nodes.len != spans.len) return error.InvalidRecord;
    const compact_dense_uniform = binaryNodeBatchCanUseDenseUniform(nodes);
    const short_text_len = compact_dense_uniform and binaryNodeBatchTextsFitU16(nodes);
    const derived_text_offset = compact_dense_uniform and binaryNodeBatchCanDeriveTextOffsets(nodes, spans);
    const payload_len = try binaryNodeBatchPayloadLen(nodes.len, compact_dense_uniform, short_text_len, derived_text_offset);
    const payload = try allocator.alloc(u8, payload_len);
    defer allocator.free(payload);

    std.mem.writeInt(u32, payload[0..4], @intCast(nodes.len), .little);
    if (compact_dense_uniform) {
        const flags = binary_node_batch_compact_flags |
            (if (short_text_len) binary_node_batch_flag_short_text_len else 0) |
            (if (derived_text_offset) binary_node_batch_flag_derived_text_offset else 0);
        std.mem.writeInt(u16, payload[4..6], flags, .little);
        std.mem.writeInt(u16, payload[6..8], @intFromEnum(nodes[0].kind), .little);
        std.mem.writeInt(u64, payload[8..16], nodes[0].id.toInt(), .little);
        var payload_offset: usize = binary_node_batch_compact_header_len;
        if (derived_text_offset) {
            try writeU48(payload[payload_offset..][0..6], spans[0].offset);
            payload_offset += binary_node_batch_derived_text_offset_header_extra_len;
        }
        const row_len = binaryNodeBatchCompactRowLen(short_text_len, derived_text_offset);
        for (nodes, spans) |node, span| {
            if (node.text.len > maxBinaryNodeTextLen()) return error.RecordTooLarge;
            if (span.len != node.text.len) return error.InvalidRecord;
            if (derived_text_offset) {
                if (short_text_len) {
                    std.mem.writeInt(u16, payload[payload_offset..][0..2], @intCast(span.len), .little);
                } else {
                    std.mem.writeInt(u32, payload[payload_offset..][0..4], span.len, .little);
                }
            } else {
                try writeU48(payload[payload_offset..][0..6], span.offset);
                if (short_text_len) {
                    std.mem.writeInt(u16, payload[payload_offset + 6 ..][0..2], @intCast(span.len), .little);
                } else {
                    std.mem.writeInt(u32, payload[payload_offset + 6 ..][0..4], span.len, .little);
                }
            }
            payload_offset += row_len;
        }
    } else {
        std.mem.writeInt(u16, payload[4..6], 0, .little);
        var payload_offset: usize = binary_node_batch_base_header_len;
        for (nodes, spans) |node, span| {
            _ = try encodeBinaryNodeFixedPayload(payload[payload_offset..][0..binary_node_payload_len], node, span);
            payload_offset += binary_node_payload_len;
        }
    }

    var header: [BinaryRecordHeader.encoded_len]u8 = undefined;
    encodeBinaryRecordHeader(&header, .node_batch, payload_len, binaryPayloadChecksum(payload));
    try writer.append(&header);
    try writer.append(payload);
}

fn appendBinaryEdgeBatchRecordToWriter(writer: *StorageBufferedWriter, allocator: std.mem.Allocator, edges: []const graph_mod.Edge) !void {
    const compact_dense_derived_rel = binaryEdgeBatchDenseDerivedRelShape(edges);
    const payload_len = try binaryEdgeBatchPayloadLen(edges.len, compact_dense_derived_rel);
    const payload = try allocator.alloc(u8, payload_len);
    defer allocator.free(payload);

    std.mem.writeInt(u32, payload[0..4], @intCast(edges.len), .little);
    if (compact_dense_derived_rel) |shape| {
        const flags = binary_edge_batch_compact_flags |
            (if (shape.compact_node_ids) binary_edge_batch_flag_u32_node_ids else 0) |
            (if (shape.linear_endpoint_runs) binary_edge_batch_flag_linear_endpoints else 0);
        std.mem.writeInt(u16, payload[4..6], flags, .little);
        std.mem.writeInt(u16, payload[6..8], shape.default_rel, .little);
        std.mem.writeInt(u64, payload[8..16], shape.base_id, .little);
        payload[16] = shape.exception_count;
        const row_len: usize = if (shape.compact_node_ids) binary_edge_batch_compact_u32_row_len else binary_edge_batch_compact_row_len;
        var exception_offset: usize = binary_edge_batch_compact_fixed_header_len;
        var exception_index: usize = 0;
        while (exception_index < shape.exception_count) : (exception_index += 1) {
            std.mem.writeInt(u32, payload[exception_offset..][0..4], shape.exception_ordinals[exception_index], .little);
            std.mem.writeInt(u16, payload[exception_offset + 4 ..][0..2], shape.exception_rels[exception_index], .little);
            exception_offset += binary_edge_batch_compact_exception_len;
        }
        var payload_offset = exception_offset;
        if (shape.linear_endpoint_runs) {
            std.mem.writeInt(u32, payload[payload_offset..][0..4], shape.endpoint_run_count, .little);
            payload_offset += 4;
            for (edges, 0..) |edge, i| {
                if (!binaryEdgeBatchEndpointStartsNewRun(edges, i)) continue;
                std.mem.writeInt(u32, payload[payload_offset..][0..4], @intCast(edge.src.toInt()), .little);
                std.mem.writeInt(u32, payload[payload_offset + 4 ..][0..4], @intCast(i), .little);
                std.mem.writeInt(u32, payload[payload_offset + 8 ..][0..4], @intCast(edge.dst.toInt()), .little);
                payload_offset += binary_edge_batch_endpoint_run_len;
            }
        }
        for (edges) |edge| {
            if (shape.linear_endpoint_runs) break;
            if (shape.compact_node_ids) {
                std.mem.writeInt(u32, payload[payload_offset..][0..4], @intCast(edge.src.toInt()), .little);
                std.mem.writeInt(u32, payload[payload_offset + 4 ..][0..4], @intCast(edge.dst.toInt()), .little);
            } else {
                std.mem.writeInt(u64, payload[payload_offset..][0..8], edge.src.toInt(), .little);
                std.mem.writeInt(u64, payload[payload_offset + 8 ..][0..8], edge.dst.toInt(), .little);
            }
            payload_offset += row_len;
        }
    } else {
        std.mem.writeInt(u16, payload[4..6], 0, .little);
        var payload_offset: usize = binary_edge_batch_base_header_len;
        for (edges) |edge| {
            encodeBinaryEdgePayload(payload[payload_offset..][0..binary_edge_payload_len], edge);
            payload_offset += binary_edge_payload_len;
        }
    }

    var header: [BinaryRecordHeader.encoded_len]u8 = undefined;
    encodeBinaryRecordHeader(&header, .edge_batch, payload_len, binaryPayloadChecksum(payload));
    try writer.append(&header);
    try writer.append(payload);
}

fn encodeBinaryEdgeRecord(out: *[binary_edge_record_len]u8, edge: graph_mod.Edge) void {
    const payload = out[BinaryRecordHeader.encoded_len..];
    encodeBinaryEdgePayload(payload[0..binary_edge_payload_len], edge);
    var header: [BinaryRecordHeader.encoded_len]u8 = undefined;
    encodeBinaryRecordHeader(&header, .edge, binary_edge_payload_len, binaryPayloadChecksum(payload));
    @memcpy(out[0..BinaryRecordHeader.encoded_len], &header);
}

fn encodeBinaryEdgePayload(out: *[binary_edge_payload_len]u8, edge: graph_mod.Edge) void {
    std.mem.writeInt(u64, out[0..8], edge.id.toInt(), .little);
    std.mem.writeInt(u64, out[8..16], edge.src.toInt(), .little);
    std.mem.writeInt(u16, out[16..18], @intFromEnum(edge.rel), .little);
    std.mem.writeInt(u64, out[18..26], edge.dst.toInt(), .little);
}

fn encodeBinaryEdgeDeleteRecord(out: *[binary_edge_delete_record_len]u8, edge_id: core.EdgeId) void {
    const payload = out[BinaryRecordHeader.encoded_len..];
    std.mem.writeInt(u64, payload[0..8], edge_id.toInt(), .little);
    var header: [BinaryRecordHeader.encoded_len]u8 = undefined;
    encodeBinaryRecordHeader(&header, .edge_delete, binary_edge_delete_payload_len, binaryPayloadChecksum(payload));
    @memcpy(out[0..BinaryRecordHeader.encoded_len], &header);
}

fn replayBinaryRecord(graph: *graph_mod.Graph, kind: BinaryRecordKind, payload: []const u8, deadline: core.QueryDeadline) !void {
    if (deadline.expired()) return core.Error.BudgetExceeded;
    switch (kind) {
        .node, .node_batch => return error.InvalidRecord,
        .edge => {
            const parsed = try validateBinaryEdgePayload(payload);
            graph.addEdgeWithIdUnchecked(core.EdgeId.fromInt(parsed.id), core.NodeId.fromInt(parsed.src), parsed.rel, core.NodeId.fromInt(parsed.dst)) catch |err| switch (err) {
                core.Error.InvalidId, core.Error.NotFound => return error.InvalidRecord,
                else => |e| return e,
            };
        },
        .edge_batch => {
            const batch = try validateBinaryEdgeBatchHeader(payload);
            var index: u32 = 0;
            while (index < batch.count) : (index += 1) {
                if (deadline.expired()) return core.Error.BudgetExceeded;
                const parsed = try validateBinaryEdgeBatchEdge(payload, batch, index);
                graph.addEdgeWithIdUnchecked(core.EdgeId.fromInt(parsed.id), core.NodeId.fromInt(parsed.src), parsed.rel, core.NodeId.fromInt(parsed.dst)) catch |err| switch (err) {
                    core.Error.InvalidId, core.Error.NotFound => return error.InvalidRecord,
                    else => |e| return e,
                };
            }
        },
        .edge_delete => {
            const edge_id = try validateBinaryEdgeDeletePayload(payload);
            graph.deleteEdgeById(edge_id) catch |err| switch (err) {
                core.Error.InvalidId => return error.InvalidRecord,
                else => |e| return e,
            };
        },
        .batch_begin, .batch_commit => {},
    }
}

fn validateBinaryRecordPayload(kind: BinaryRecordKind, payload: []const u8) !void {
    switch (kind) {
        .node => _ = try validateBinaryNodePayload(payload),
        .node_batch => try validateBinaryNodeBatchPayload(payload),
        .edge => _ = try validateBinaryEdgePayload(payload),
        .edge_batch => try validateBinaryEdgeBatchPayload(payload),
        .edge_delete => _ = try validateBinaryEdgeDeletePayload(payload),
        .batch_begin, .batch_commit => if (payload.len != 0) return error.InvalidRecord,
    }
}

const ParsedBinaryNode = struct {
    id: u64,
    kind: core.NodeKind,
    text_offset: u64,
    text_len: u32,
};

const node_record_digest_fixed_len: usize = 14;
const binary_node_payload_len: usize = 22;
const binary_node_batch_base_header_len: usize = 6;
const binary_node_batch_compact_header_len: usize = 16;
const binary_node_batch_derived_text_offset_header_extra_len: usize = 6;
const binary_node_batch_compact_row_len: usize = 10;
const binary_node_batch_compact_short_text_len_row_len: usize = 8;
const binary_node_batch_compact_derived_text_offset_row_len: usize = 4;
const binary_node_batch_compact_short_derived_text_offset_row_len: usize = 2;
const binary_node_batch_flag_dense_id: u16 = 1 << 0;
const binary_node_batch_flag_uniform_kind: u16 = 1 << 1;
const binary_node_batch_flag_short_text_len: u16 = 1 << 2;
const binary_node_batch_flag_derived_text_offset: u16 = 1 << 3;
const binary_node_batch_compact_flags: u16 = binary_node_batch_flag_dense_id | binary_node_batch_flag_uniform_kind;
const binary_node_batch_known_flags: u16 = binary_node_batch_compact_flags | binary_node_batch_flag_short_text_len | binary_node_batch_flag_derived_text_offset;
const binary_node_batch_max_count: usize = (BinaryRecordHeader.max_payload_len - binary_node_batch_base_header_len) / binary_node_payload_len;
const binary_edge_payload_len: usize = 26;
const binary_edge_batch_base_header_len: usize = 6;
const binary_edge_batch_compact_fixed_header_len: usize = 17;
const binary_edge_batch_compact_exception_len: usize = 6;
const binary_edge_batch_endpoint_run_len: usize = 12;
const binary_edge_batch_compact_row_len: usize = 16;
const binary_edge_batch_compact_u32_row_len: usize = 8;
const binary_edge_batch_flag_dense_id: u16 = 1 << 0;
const binary_edge_batch_flag_derived_rel: u16 = 1 << 1;
const binary_edge_batch_flag_u32_node_ids: u16 = 1 << 2;
const binary_edge_batch_flag_linear_endpoints: u16 = 1 << 3;
const binary_edge_batch_compact_flags: u16 = binary_edge_batch_flag_dense_id | binary_edge_batch_flag_derived_rel;
const binary_edge_batch_known_flags: u16 = binary_edge_batch_compact_flags | binary_edge_batch_flag_u32_node_ids | binary_edge_batch_flag_linear_endpoints;
const binary_edge_batch_max_rel_exceptions: usize = 2;
const binary_edge_batch_max_count: usize = (BinaryRecordHeader.max_payload_len - binary_edge_batch_base_header_len) / binary_edge_payload_len;
const binary_edge_delete_payload_len: usize = 8;
const max_binary_count_payload_prefix_len: usize = @max(binary_node_payload_len, @max(binary_edge_payload_len, binary_edge_delete_payload_len));
const binary_count_read_chunk_len: usize = 64 * 1024;

fn maxBinaryNodeTextLen() usize {
    return std.math.maxInt(u32);
}

fn validateBinaryNodePayload(payload: []const u8) !ParsedBinaryNode {
    if (payload.len != binary_node_payload_len) return error.InvalidRecord;
    const id = readU64(payload[0..8]);
    const kind_int = readU16(payload[8..10]);
    const text_offset = readU64(payload[10..18]);
    const text_len = readU32(payload[18..22]);
    if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
    const node_kind = nodeKindFromInt(kind_int) orelse return error.InvalidRecord;
    return .{ .id = id, .kind = node_kind, .text_offset = text_offset, .text_len = text_len };
}

fn validateBinaryNodePayloadForCount(prefix: []const u8, payload_len: u32) !ParsedBinaryNode {
    if (prefix.len < binary_node_payload_len) return error.InvalidRecord;
    if (payload_len != binary_node_payload_len) return error.InvalidRecord;
    const id = readU64(prefix[0..8]);
    const kind_int = readU16(prefix[8..10]);
    const text_offset = readU64(prefix[10..18]);
    const text_len = readU32(prefix[18..22]);
    if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
    const node_kind = nodeKindFromInt(kind_int) orelse return error.InvalidRecord;
    return .{ .id = id, .kind = node_kind, .text_offset = text_offset, .text_len = text_len };
}

const ParsedBinaryNodeBatch = struct {
    count: u32,
    flags: u16,
    header_len: usize,
    row_len: usize,
    dense_base_id: u64 = 0,
    uniform_kind: ?core.NodeKind = null,
    short_text_len: bool = false,
    derived_text_offset: bool = false,
    base_text_offset: u64 = 0,
};

fn binaryNodeBatchCanUseDenseUniform(nodes: []const graph_mod.Node) bool {
    if (nodes.len == 0) return false;
    const first_kind = nodes[0].kind;
    const base_id = nodes[0].id.toInt();
    if (base_id == 0 or base_id == std.math.maxInt(u64)) return false;
    for (nodes, 0..) |node, ordinal| {
        const expected_id = std.math.add(u64, base_id, @intCast(ordinal)) catch return false;
        if (expected_id == std.math.maxInt(u64)) return false;
        if (node.kind != first_kind) return false;
        if (node.id.toInt() != expected_id) return false;
    }
    return true;
}

fn binaryNodeBatchTextsFitU16(nodes: []const graph_mod.Node) bool {
    for (nodes) |node| {
        if (!nodeTextLenFitsU16(node.text.len)) return false;
    }
    return true;
}

fn binaryNodeBatchCanDeriveTextOffsets(nodes: []const graph_mod.Node, spans: []const TextSpan) bool {
    if (nodes.len == 0 or nodes.len != spans.len) return false;
    var expected_offset = spans[0].offset;
    for (nodes, spans) |node, span| {
        if (node.text.len > maxBinaryNodeTextLen()) return false;
        if (span.len != node.text.len) return false;
        if (span.offset != expected_offset) return false;
        expected_offset = std.math.add(u64, expected_offset, span.len) catch return false;
    }
    return true;
}

fn binaryNodeBatchCompactRowLen(short_text_len: bool, derived_text_offset: bool) usize {
    if (derived_text_offset) {
        return if (short_text_len) binary_node_batch_compact_short_derived_text_offset_row_len else binary_node_batch_compact_derived_text_offset_row_len;
    }
    return if (short_text_len) binary_node_batch_compact_short_text_len_row_len else binary_node_batch_compact_row_len;
}

fn binaryNodeBatchPayloadLen(node_count: usize, compact_dense_uniform: bool, short_text_len: bool, derived_text_offset: bool) !u32 {
    if (node_count == 0 or node_count > binary_node_batch_max_count) return error.RecordTooLarge;
    if (short_text_len and !compact_dense_uniform) return error.InvalidRecord;
    if (derived_text_offset and !compact_dense_uniform) return error.InvalidRecord;
    const header_len: usize = if (compact_dense_uniform)
        binary_node_batch_compact_header_len + if (derived_text_offset) binary_node_batch_derived_text_offset_header_extra_len else 0
    else
        binary_node_batch_base_header_len;
    const row_len: usize = if (compact_dense_uniform)
        binaryNodeBatchCompactRowLen(short_text_len, derived_text_offset)
    else
        binary_node_payload_len;
    const body_len = std.math.mul(usize, node_count, row_len) catch return error.RecordTooLarge;
    const payload_len = std.math.add(usize, header_len, body_len) catch return error.RecordTooLarge;
    if (payload_len > BinaryRecordHeader.max_payload_len) return error.RecordTooLarge;
    return @intCast(payload_len);
}

fn binaryNodeBatchCountFromPrefix(prefix: []const u8, payload_len: u32) !u32 {
    if (prefix.len < binary_node_batch_base_header_len) return error.InvalidRecord;
    const count = readU32(prefix[0..4]);
    if (count == 0 or count > binary_node_batch_max_count) return error.InvalidRecord;
    const flags = readU16(prefix[4..6]);
    var header_len: usize = binary_node_batch_base_header_len;
    var row_len: usize = binary_node_payload_len;
    if (flags == 0) {
        // Full rows carry id and kind per node.
    } else if ((flags & ~binary_node_batch_known_flags) == 0 and (flags & binary_node_batch_compact_flags) == binary_node_batch_compact_flags) {
        if (prefix.len < binary_node_batch_compact_header_len) return error.InvalidRecord;
        _ = nodeKindFromInt(readU16(prefix[6..8])) orelse return error.InvalidRecord;
        const base_id = readU64(prefix[8..16]);
        if (base_id == 0 or base_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const last_id = std.math.add(u64, base_id, @as(u64, count) - 1) catch return error.InvalidRecord;
        if (last_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const short_text_len = (flags & binary_node_batch_flag_short_text_len) != 0;
        const derived_text_offset = (flags & binary_node_batch_flag_derived_text_offset) != 0;
        header_len = binary_node_batch_compact_header_len + if (derived_text_offset) binary_node_batch_derived_text_offset_header_extra_len else 0;
        if (prefix.len < header_len) return error.InvalidRecord;
        row_len = binaryNodeBatchCompactRowLen(short_text_len, derived_text_offset);
    } else {
        return error.InvalidRecord;
    }
    const body_len = std.math.mul(usize, @intCast(count), row_len) catch return error.InvalidRecord;
    const expected_len = std.math.add(usize, header_len, body_len) catch return error.InvalidRecord;
    if (expected_len != payload_len) return error.InvalidRecord;
    return count;
}

fn validateBinaryNodeBatchHeader(payload: []const u8) !ParsedBinaryNodeBatch {
    if (payload.len < binary_node_batch_base_header_len) return error.InvalidRecord;
    const count = readU32(payload[0..4]);
    if (count == 0 or count > binary_node_batch_max_count) return error.InvalidRecord;
    const flags = readU16(payload[4..6]);
    var header = ParsedBinaryNodeBatch{
        .count = count,
        .flags = flags,
        .header_len = binary_node_batch_base_header_len,
        .row_len = binary_node_payload_len,
    };
    if (flags == 0) {
        // Full rows carry id and kind per node.
    } else if ((flags & ~binary_node_batch_known_flags) == 0 and (flags & binary_node_batch_compact_flags) == binary_node_batch_compact_flags) {
        if (payload.len < binary_node_batch_compact_header_len) return error.InvalidRecord;
        const kind_int = readU16(payload[6..8]);
        const node_kind = nodeKindFromInt(kind_int) orelse return error.InvalidRecord;
        const base_id = readU64(payload[8..16]);
        if (base_id == 0 or base_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const last_offset: u64 = @as(u64, count) - 1;
        const last_id = std.math.add(u64, base_id, last_offset) catch return error.InvalidRecord;
        if (last_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const short_text_len = (flags & binary_node_batch_flag_short_text_len) != 0;
        const derived_text_offset = (flags & binary_node_batch_flag_derived_text_offset) != 0;
        header.header_len = binary_node_batch_compact_header_len;
        if (derived_text_offset) {
            header.header_len += binary_node_batch_derived_text_offset_header_extra_len;
            if (payload.len < header.header_len) return error.InvalidRecord;
            header.base_text_offset = readU48(payload[16..22]);
        }
        header.row_len = binaryNodeBatchCompactRowLen(short_text_len, derived_text_offset);
        header.dense_base_id = base_id;
        header.uniform_kind = node_kind;
        header.short_text_len = short_text_len;
        header.derived_text_offset = derived_text_offset;
    } else {
        return error.InvalidRecord;
    }
    const body_len = std.math.mul(usize, @intCast(count), header.row_len) catch return error.InvalidRecord;
    const expected_len = std.math.add(usize, header.header_len, body_len) catch return error.InvalidRecord;
    if (payload.len != expected_len) return error.InvalidRecord;
    return header;
}

fn validateBinaryNodeBatchNode(payload: []const u8, batch: ParsedBinaryNodeBatch, index: u32) !ParsedBinaryNode {
    if (index >= batch.count) return error.InvalidRecord;
    const row_offset = std.math.add(usize, batch.header_len, std.math.mul(usize, @intCast(index), batch.row_len) catch return error.InvalidRecord) catch return error.InvalidRecord;
    if (batch.flags == 0) {
        return validateBinaryNodePayload(payload[row_offset..][0..binary_node_payload_len]);
    }
    if ((batch.flags & binary_node_batch_compact_flags) != binary_node_batch_compact_flags) return error.InvalidRecord;
    const row = payload[row_offset..][0..batch.row_len];
    const id = std.math.add(u64, batch.dense_base_id, index) catch return error.InvalidRecord;
    if (batch.derived_text_offset) return error.InvalidRecord;
    const text_offset = readU48(row[0..6]);
    const text_len: u32 = if (batch.short_text_len) readU16(row[6..8]) else readU32(row[6..10]);
    return .{
        .id = id,
        .kind = batch.uniform_kind orelse return error.InvalidRecord,
        .text_offset = text_offset,
        .text_len = text_len,
    };
}

fn validateBinaryNodeBatchPayload(payload: []const u8) !void {
    var reader = try BinaryNodeBatchReader.init(payload);
    while (try reader.next()) |_| {}
}

const BinaryNodeBatchReader = struct {
    payload: []const u8,
    batch: ParsedBinaryNodeBatch,
    index: u32 = 0,
    next_text_offset: u64 = 0,

    fn init(payload: []const u8) !BinaryNodeBatchReader {
        const batch = try validateBinaryNodeBatchHeader(payload);
        return .{
            .payload = payload,
            .batch = batch,
            .next_text_offset = batch.base_text_offset,
        };
    }

    fn next(self: *BinaryNodeBatchReader) !?ParsedBinaryNode {
        if (self.index >= self.batch.count) return null;
        const index = self.index;
        self.index += 1;
        if (self.batch.flags == 0) {
            return try validateBinaryNodeBatchNode(self.payload, self.batch, index);
        }
        if ((self.batch.flags & binary_node_batch_compact_flags) != binary_node_batch_compact_flags) return error.InvalidRecord;
        const row_offset = std.math.add(usize, self.batch.header_len, std.math.mul(usize, @intCast(index), self.batch.row_len) catch return error.InvalidRecord) catch return error.InvalidRecord;
        const row = self.payload[row_offset..][0..self.batch.row_len];
        const id = std.math.add(u64, self.batch.dense_base_id, index) catch return error.InvalidRecord;
        const text_len: u32 = if (self.batch.derived_text_offset)
            if (self.batch.short_text_len) readU16(row[0..2]) else readU32(row[0..4])
        else if (self.batch.short_text_len) readU16(row[6..8]) else readU32(row[6..10]);
        const text_offset = if (self.batch.derived_text_offset) offset: {
            const current = self.next_text_offset;
            self.next_text_offset = std.math.add(u64, self.next_text_offset, text_len) catch return error.InvalidRecord;
            break :offset current;
        } else readU48(row[0..6]);
        return .{
            .id = id,
            .kind = self.batch.uniform_kind orelse return error.InvalidRecord,
            .text_offset = text_offset,
            .text_len = text_len,
        };
    }
};

const ParsedBinaryEdge = struct {
    id: u64,
    src: u64,
    rel: core.RelKind,
    dst: u64,
};

const BinaryEdgeBatchCompactShape = struct {
    default_rel: u16,
    base_id: u64,
    compact_node_ids: bool = false,
    linear_endpoint_runs: bool = false,
    endpoint_run_count: u32 = 0,
    exception_count: u8 = 0,
    exception_ordinals: [binary_edge_batch_max_rel_exceptions]u32 = [_]u32{0} ** binary_edge_batch_max_rel_exceptions,
    exception_rels: [binary_edge_batch_max_rel_exceptions]u16 = [_]u16{0} ** binary_edge_batch_max_rel_exceptions,
};

const ParsedBinaryEdgeBatch = struct {
    count: u32,
    flags: u16,
    header_len: usize,
    row_len: usize,
    dense_base_id: u64 = 0,
    compact_node_ids: bool = false,
    linear_endpoint_runs: bool = false,
    endpoint_run_count: u32 = 0,
    endpoint_runs_offset: usize = 0,
    default_rel: u16 = 0,
    exception_count: u8 = 0,
    exception_ordinals: [binary_edge_batch_max_rel_exceptions]u32 = [_]u32{0} ** binary_edge_batch_max_rel_exceptions,
    exception_rels: [binary_edge_batch_max_rel_exceptions]u16 = [_]u16{0} ** binary_edge_batch_max_rel_exceptions,
};

const BinaryEdgeBatchEndpointRun = struct {
    src_base: u32,
    start: u32,
    dst_base: u32,
};

fn validateBinaryEdgePayload(payload: []const u8) !ParsedBinaryEdge {
    if (payload.len != binary_edge_payload_len) return error.InvalidRecord;
    const id = readU64(payload[0..8]);
    const src = readU64(payload[8..16]);
    const rel_int = readU16(payload[16..18]);
    const dst = readU64(payload[18..26]);
    if (id == 0 or src == 0 or dst == 0) return error.InvalidRecord;
    if (id == std.math.maxInt(u64) or src == std.math.maxInt(u64) or dst == std.math.maxInt(u64)) return error.InvalidRecord;
    const rel = relKindFromInt(rel_int) orelse return error.InvalidRecord;
    return .{ .id = id, .src = src, .rel = rel, .dst = dst };
}

fn binaryEdgeBatchDenseDerivedRelShape(edges: []const graph_mod.Edge) ?BinaryEdgeBatchCompactShape {
    if (edges.len == 0) return null;
    const base_id = edges[0].id.toInt();
    if (base_id == 0 or base_id == std.math.maxInt(u64)) return null;
    var compact_node_ids = true;
    var counts: [edge_index_rel_kind_count]u64 = [_]u64{0} ** edge_index_rel_kind_count;
    for (edges, 0..) |edge, ordinal| {
        const expected_id = std.math.add(u64, base_id, @intCast(ordinal)) catch return null;
        if (expected_id == std.math.maxInt(u64) or edge.id.toInt() != expected_id) return null;
        if (edge.src.toInt() == 0 or edge.dst.toInt() == 0) return null;
        if (edge.src.toInt() == std.math.maxInt(u64) or edge.dst.toInt() == std.math.maxInt(u64)) return null;
        if (edge.src.toInt() > std.math.maxInt(u32) or edge.dst.toInt() > std.math.maxInt(u32)) compact_node_ids = false;
        counts[@intFromEnum(edge.rel)] += 1;
    }
    const default_rel = edgeIndexDefaultRelFromCounts(counts, @intCast(edges.len)) orelse return null;
    var shape = BinaryEdgeBatchCompactShape{
        .default_rel = default_rel,
        .base_id = base_id,
        .compact_node_ids = compact_node_ids,
    };
    if (compact_node_ids) {
        if (binaryEdgeBatchEndpointRunCount(edges)) |run_count| {
            const run_bytes = std.math.add(usize, 4, std.math.mul(usize, @intCast(run_count), binary_edge_batch_endpoint_run_len) catch return null) catch return null;
            const row_bytes = std.math.mul(usize, edges.len, binary_edge_batch_compact_u32_row_len) catch return null;
            if (run_count != 0 and run_bytes < row_bytes) {
                shape.linear_endpoint_runs = true;
                shape.endpoint_run_count = run_count;
            }
        }
    }
    for (edges, 0..) |edge, ordinal| {
        const rel: u16 = @intFromEnum(edge.rel);
        if (rel == default_rel) continue;
        if (shape.exception_count >= binary_edge_batch_max_rel_exceptions) return null;
        const exception_index = shape.exception_count;
        shape.exception_ordinals[exception_index] = @intCast(ordinal);
        shape.exception_rels[exception_index] = rel;
        shape.exception_count += 1;
    }
    return shape;
}

fn binaryEdgeBatchEndpointRunCount(edges: []const graph_mod.Edge) ?u32 {
    if (edges.len == 0) return 0;
    if (!binaryEdgeBatchEndpointCanStartRun(edges[0])) return null;
    var run_count: u64 = 1;
    for (edges[1..], 1..) |edge, i| {
        if (!binaryEdgeBatchEndpointCanStartRun(edge)) return null;
        if (binaryEdgeBatchEndpointContinuesRun(edges[i - 1], edge)) continue;
        run_count = std.math.add(u64, run_count, 1) catch return null;
    }
    if (run_count > std.math.maxInt(u32)) return null;
    return @intCast(run_count);
}

fn binaryEdgeBatchEndpointCanStartRun(edge: graph_mod.Edge) bool {
    const src = edge.src.toInt();
    const dst = edge.dst.toInt();
    return src != 0 and dst != 0 and src <= std.math.maxInt(u32) and dst <= std.math.maxInt(u32);
}

fn binaryEdgeBatchEndpointContinuesRun(previous: graph_mod.Edge, edge: graph_mod.Edge) bool {
    const expected_src = std.math.add(u64, previous.src.toInt(), 1) catch return false;
    const expected_dst = std.math.add(u64, previous.dst.toInt(), 1) catch return false;
    return edge.src.toInt() == expected_src and edge.dst.toInt() == expected_dst;
}

fn binaryEdgeBatchEndpointStartsNewRun(edges: []const graph_mod.Edge, index: usize) bool {
    if (index == 0) return true;
    return !binaryEdgeBatchEndpointContinuesRun(edges[index - 1], edges[index]);
}

fn binaryEdgeBatchPayloadLen(edge_count: usize, compact_dense_derived_rel: ?BinaryEdgeBatchCompactShape) !u32 {
    if (edge_count == 0 or edge_count > binary_edge_batch_max_count) return error.RecordTooLarge;
    const header_len: usize = if (compact_dense_derived_rel) |shape| header_len: {
        var len = binary_edge_batch_compact_fixed_header_len + @as(usize, shape.exception_count) * binary_edge_batch_compact_exception_len;
        if (shape.linear_endpoint_runs) {
            len = std.math.add(usize, len, 4) catch return error.RecordTooLarge;
            len = std.math.add(usize, len, std.math.mul(usize, @intCast(shape.endpoint_run_count), binary_edge_batch_endpoint_run_len) catch return error.RecordTooLarge) catch return error.RecordTooLarge;
        }
        break :header_len len;
    } else binary_edge_batch_base_header_len;
    const row_len: usize = if (compact_dense_derived_rel) |shape|
        if (shape.linear_endpoint_runs) 0 else if (shape.compact_node_ids) binary_edge_batch_compact_u32_row_len else binary_edge_batch_compact_row_len
    else
        binary_edge_payload_len;
    const body_len = std.math.mul(usize, edge_count, row_len) catch return error.RecordTooLarge;
    const payload_len = std.math.add(usize, header_len, body_len) catch return error.RecordTooLarge;
    if (payload_len > BinaryRecordHeader.max_payload_len) return error.RecordTooLarge;
    return @intCast(payload_len);
}

fn validateBinaryEdgeBatchHeader(payload: []const u8) !ParsedBinaryEdgeBatch {
    if (payload.len < binary_edge_batch_base_header_len) return error.InvalidRecord;
    const count = readU32(payload[0..4]);
    if (count == 0 or count > binary_edge_batch_max_count) return error.InvalidRecord;
    const flags = readU16(payload[4..6]);
    var header = ParsedBinaryEdgeBatch{
        .count = count,
        .flags = flags,
        .header_len = binary_edge_batch_base_header_len,
        .row_len = binary_edge_payload_len,
    };
    if (flags == 0) {
        // Full rows carry id and relation per edge.
    } else if ((flags & binary_edge_batch_compact_flags) == binary_edge_batch_compact_flags) {
        if ((flags & ~binary_edge_batch_known_flags) != 0) return error.InvalidRecord;
        if (payload.len < binary_edge_batch_compact_fixed_header_len) return error.InvalidRecord;
        const default_rel = readU16(payload[6..8]);
        if (relKindFromInt(default_rel) == null) return error.InvalidRecord;
        const base_id = readU64(payload[8..16]);
        if (base_id == 0 or base_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const last_offset: u64 = @as(u64, count) - 1;
        const last_id = std.math.add(u64, base_id, last_offset) catch return error.InvalidRecord;
        if (last_id == std.math.maxInt(u64)) return error.InvalidRecord;
        const exception_count = payload[16];
        if (exception_count > binary_edge_batch_max_rel_exceptions) return error.InvalidRecord;
        header.header_len = binary_edge_batch_compact_fixed_header_len + @as(usize, exception_count) * binary_edge_batch_compact_exception_len;
        if (payload.len < header.header_len) return error.InvalidRecord;
        header.dense_base_id = base_id;
        header.compact_node_ids = (flags & binary_edge_batch_flag_u32_node_ids) != 0;
        header.linear_endpoint_runs = (flags & binary_edge_batch_flag_linear_endpoints) != 0;
        if (header.linear_endpoint_runs and !header.compact_node_ids) return error.InvalidRecord;
        header.row_len = if (header.linear_endpoint_runs) 0 else if (header.compact_node_ids) binary_edge_batch_compact_u32_row_len else binary_edge_batch_compact_row_len;
        header.default_rel = default_rel;
        header.exception_count = exception_count;
        var previous_ordinal: ?u32 = null;
        var exception_index: usize = 0;
        var exception_offset: usize = binary_edge_batch_compact_fixed_header_len;
        while (exception_index < exception_count) : (exception_index += 1) {
            const ordinal = readU32(payload[exception_offset..][0..4]);
            const rel = readU16(payload[exception_offset + 4 ..][0..2]);
            if (ordinal >= count) return error.InvalidRecord;
            if (previous_ordinal) |previous| {
                if (ordinal <= previous) return error.InvalidRecord;
            }
            if (rel == default_rel or relKindFromInt(rel) == null) return error.InvalidRecord;
            header.exception_ordinals[exception_index] = ordinal;
            header.exception_rels[exception_index] = rel;
            previous_ordinal = ordinal;
            exception_offset += binary_edge_batch_compact_exception_len;
        }
        if (header.linear_endpoint_runs) {
            if (payload.len < header.header_len + 4) return error.InvalidRecord;
            header.endpoint_run_count = readU32(payload[header.header_len..][0..4]);
            if (header.endpoint_run_count == 0 or header.endpoint_run_count > count) return error.InvalidRecord;
            header.endpoint_runs_offset = header.header_len + 4;
            const run_bytes = std.math.mul(usize, @intCast(header.endpoint_run_count), binary_edge_batch_endpoint_run_len) catch return error.InvalidRecord;
            header.header_len = std.math.add(usize, header.endpoint_runs_offset, run_bytes) catch return error.InvalidRecord;
            if (payload.len < header.header_len) return error.InvalidRecord;
            var run_index: u32 = 0;
            var previous_start: ?u32 = null;
            while (run_index < header.endpoint_run_count) : (run_index += 1) {
                const run = try readBinaryEdgeBatchEndpointRun(payload, header, run_index);
                if (run_index == 0 and run.start != 0) return error.InvalidRecord;
                if (run.start >= count) return error.InvalidRecord;
                if (previous_start) |start| {
                    if (run.start <= start) return error.InvalidRecord;
                }
                const end = if (run_index + 1 < header.endpoint_run_count)
                    (try readBinaryEdgeBatchEndpointRun(payload, header, run_index + 1)).start
                else
                    count;
                if (end <= run.start) return error.InvalidRecord;
                const last_delta = end - run.start - 1;
                const last_src = std.math.add(u64, run.src_base, last_delta) catch return error.InvalidRecord;
                const last_dst = std.math.add(u64, run.dst_base, last_delta) catch return error.InvalidRecord;
                if (last_src > std.math.maxInt(u32) or last_dst > std.math.maxInt(u32)) return error.InvalidRecord;
                previous_start = run.start;
            }
        }
    } else {
        return error.InvalidRecord;
    }
    const body_len = std.math.mul(usize, @intCast(count), header.row_len) catch return error.InvalidRecord;
    const expected_len = std.math.add(usize, header.header_len, body_len) catch return error.InvalidRecord;
    if (payload.len != expected_len) return error.InvalidRecord;
    return header;
}

fn binaryEdgeBatchRelAt(batch: ParsedBinaryEdgeBatch, index: u32) !core.RelKind {
    if (index >= batch.count) return error.InvalidRecord;
    if (batch.flags == 0) return error.InvalidRecord;
    var rel = batch.default_rel;
    var exception_index: usize = 0;
    while (exception_index < batch.exception_count) : (exception_index += 1) {
        if (batch.exception_ordinals[exception_index] == index) {
            rel = batch.exception_rels[exception_index];
            break;
        }
    }
    return relKindFromInt(rel) orelse error.InvalidRecord;
}

fn readBinaryEdgeBatchEndpointRun(payload: []const u8, batch: ParsedBinaryEdgeBatch, run_index: u32) !BinaryEdgeBatchEndpointRun {
    if (!batch.linear_endpoint_runs or run_index >= batch.endpoint_run_count) return error.InvalidRecord;
    const offset = std.math.add(usize, batch.endpoint_runs_offset, std.math.mul(usize, @intCast(run_index), binary_edge_batch_endpoint_run_len) catch return error.InvalidRecord) catch return error.InvalidRecord;
    const end = std.math.add(usize, offset, binary_edge_batch_endpoint_run_len) catch return error.InvalidRecord;
    if (end > payload.len) return error.InvalidRecord;
    const bytes = payload[offset..][0..binary_edge_batch_endpoint_run_len];
    const src_base = readU32(bytes[0..4]);
    const start = readU32(bytes[4..8]);
    const dst_base = readU32(bytes[8..12]);
    if (src_base == 0 or dst_base == 0) return error.InvalidRecord;
    return .{
        .src_base = src_base,
        .start = start,
        .dst_base = dst_base,
    };
}

fn binaryEdgeBatchEndpointRunForIndex(payload: []const u8, batch: ParsedBinaryEdgeBatch, index: u32) !BinaryEdgeBatchEndpointRun {
    if (!batch.linear_endpoint_runs or index >= batch.count) return error.InvalidRecord;
    var lo: u32 = 0;
    var hi = batch.endpoint_run_count;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const run = try readBinaryEdgeBatchEndpointRun(payload, batch, mid);
        if (run.start <= index) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    if (lo == 0) return error.InvalidRecord;
    return readBinaryEdgeBatchEndpointRun(payload, batch, lo - 1);
}

fn validateBinaryEdgeBatchEdge(payload: []const u8, batch: ParsedBinaryEdgeBatch, index: u32) !ParsedBinaryEdge {
    if (index >= batch.count) return error.InvalidRecord;
    const row_offset = std.math.add(usize, batch.header_len, std.math.mul(usize, @intCast(index), batch.row_len) catch return error.InvalidRecord) catch return error.InvalidRecord;
    if (batch.flags == 0) {
        return validateBinaryEdgePayload(payload[row_offset..][0..binary_edge_payload_len]);
    }
    if ((batch.flags & binary_edge_batch_compact_flags) != binary_edge_batch_compact_flags) return error.InvalidRecord;
    const id = std.math.add(u64, batch.dense_base_id, index) catch return error.InvalidRecord;
    const src: u64, const dst: u64 = if (batch.linear_endpoint_runs) endpoints: {
        const run = try binaryEdgeBatchEndpointRunForIndex(payload, batch, index);
        if (index < run.start) return error.InvalidRecord;
        const delta = index - run.start;
        break :endpoints .{
            std.math.add(u64, run.src_base, delta) catch return error.InvalidRecord,
            std.math.add(u64, run.dst_base, delta) catch return error.InvalidRecord,
        };
    } else endpoints: {
        const src = if (batch.compact_node_ids) src: {
            const row = payload[row_offset..][0..binary_edge_batch_compact_u32_row_len];
            break :src @as(u64, readU32(row[0..4]));
        } else src: {
            const row = payload[row_offset..][0..binary_edge_batch_compact_row_len];
            break :src readU64(row[0..8]);
        };
        const dst = if (batch.compact_node_ids) dst: {
            const row = payload[row_offset..][0..binary_edge_batch_compact_u32_row_len];
            break :dst @as(u64, readU32(row[4..8]));
        } else dst: {
            const row = payload[row_offset..][0..binary_edge_batch_compact_row_len];
            break :dst readU64(row[8..16]);
        };
        break :endpoints .{ src, dst };
    };
    if (src == 0 or dst == 0) return error.InvalidRecord;
    if (src == std.math.maxInt(u64) or dst == std.math.maxInt(u64)) return error.InvalidRecord;
    if (batch.compact_node_ids and (src > std.math.maxInt(u32) or dst > std.math.maxInt(u32))) return error.InvalidRecord;
    return .{
        .id = id,
        .src = src,
        .rel = try binaryEdgeBatchRelAt(batch, index),
        .dst = dst,
    };
}

fn validateBinaryEdgeBatchPayload(payload: []const u8) !void {
    const batch = try validateBinaryEdgeBatchHeader(payload);
    var index: u32 = 0;
    while (index < batch.count) : (index += 1) {
        _ = try validateBinaryEdgeBatchEdge(payload, batch, index);
    }
}

fn validateBinaryEdgeDeletePayload(payload: []const u8) !core.EdgeId {
    if (payload.len != binary_edge_delete_payload_len) return error.InvalidRecord;
    const id = readU64(payload[0..8]);
    if (id == 0 or id == std.math.maxInt(u64)) return error.InvalidRecord;
    return core.EdgeId.fromInt(id);
}

fn nodeKindFromInt(value: u16) ?core.NodeKind {
    if (value >= schema.max_node_types) return null;
    return @enumFromInt(value);
}

fn relKindFromInt(value: u16) ?core.RelKind {
    if (value >= schema.max_relation_types) return null;
    return @enumFromInt(value);
}

fn appendU16(out: *std.ArrayList(u8), allocator: std.mem.Allocator, value: u16) !void {
    var bytes: [2]u8 = undefined;
    std.mem.writeInt(u16, &bytes, value, .little);
    try out.appendSlice(allocator, &bytes);
}

fn appendU32(out: *std.ArrayList(u8), allocator: std.mem.Allocator, value: u32) !void {
    var bytes: [4]u8 = undefined;
    std.mem.writeInt(u32, &bytes, value, .little);
    try out.appendSlice(allocator, &bytes);
}

fn appendU64(out: *std.ArrayList(u8), allocator: std.mem.Allocator, value: u64) !void {
    var bytes: [8]u8 = undefined;
    std.mem.writeInt(u64, &bytes, value, .little);
    try out.appendSlice(allocator, &bytes);
}

fn writeU48(bytes: []u8, value: u64) !void {
    std.debug.assert(bytes.len == 6);
    const packed_value = std.math.cast(u48, value) orelse return error.RecordTooLarge;
    std.mem.writeInt(u48, bytes[0..6], packed_value, .little);
}

fn writeU16(bytes: []u8, value: u16) void {
    std.mem.writeInt(u16, bytes[0..2], value, .little);
}

fn writeU32(bytes: []u8, value: u32) void {
    std.mem.writeInt(u32, bytes[0..4], value, .little);
}

fn writeU64(bytes: []u8, value: u64) void {
    std.mem.writeInt(u64, bytes[0..8], value, .little);
}

fn readU16(bytes: []const u8) u16 {
    return std.mem.readInt(u16, bytes[0..2], .little);
}

fn readU32(bytes: []const u8) u32 {
    return std.mem.readInt(u32, bytes[0..4], .little);
}

fn readU48(bytes: []const u8) u64 {
    std.debug.assert(bytes.len == 6);
    return @intCast(std.mem.readInt(u48, bytes[0..6], .little));
}

fn readU64(bytes: []const u8) u64 {
    return std.mem.readInt(u64, bytes[0..8], .little);
}

