    try std.testing.expectEqual(@as(u128, 0), timings.text_match_ns);
    try std.testing.expectEqual(@as(u128, 0), timings.text_compare_ns);
    try std.testing.expectEqual(@as(u128, 0), timings.by_id_validate_ns);
}

