test "node batch short text length flag requires compact dense uniform shape" {
    var payload = [_]u8{0} ** (binary_node_batch_compact_header_len + binary_node_batch_compact_short_text_len_row_len);
    std.mem.writeInt(u32, payload[0..4], 1, .little);
    std.mem.writeInt(u16, payload[4..6], binary_node_batch_flag_short_text_len, .little);
    std.mem.writeInt(u16, payload[6..8], @intFromEnum(core.NodeKind.file), .little);
    std.mem.writeInt(u64, payload[8..16], 1, .little);
    try writeU48(payload[16..22], 0);
    std.mem.writeInt(u16, payload[22..24], 3, .little);
    try std.testing.expectError(error.InvalidRecord, validateBinaryNodeBatchPayload(&payload));

    std.mem.writeInt(u16, payload[4..6], binary_node_batch_flag_derived_text_offset, .little);
    try std.testing.expectError(error.InvalidRecord, validateBinaryNodeBatchPayload(&payload));

    std.mem.writeInt(u16, payload[4..6], binary_node_batch_compact_flags | binary_node_batch_flag_short_text_len | (1 << 15), .little);
    try std.testing.expectError(error.InvalidRecord, validateBinaryNodeBatchPayload(&payload));
}

test "node batch derived text offsets synthesize contiguous spans" {
    var payload = [_]u8{0} ** (binary_node_batch_compact_header_len + binary_node_batch_derived_text_offset_header_extra_len + 2 * binary_node_batch_compact_short_derived_text_offset_row_len);
    std.mem.writeInt(u32, payload[0..4], 2, .little);
    std.mem.writeInt(u16, payload[4..6], binary_node_batch_compact_flags | binary_node_batch_flag_short_text_len | binary_node_batch_flag_derived_text_offset, .little);
    std.mem.writeInt(u16, payload[6..8], @intFromEnum(core.NodeKind.file), .little);
    std.mem.writeInt(u64, payload[8..16], 7, .little);
    try writeU48(payload[16..22], 100);
    std.mem.writeInt(u16, payload[22..24], 3, .little);
    std.mem.writeInt(u16, payload[24..26], 5, .little);

    const batch = try validateBinaryNodeBatchHeader(&payload);
    try std.testing.expect(batch.derived_text_offset);
    try std.testing.expect(batch.short_text_len);
    try std.testing.expectEqual(@as(usize, binary_node_batch_compact_short_derived_text_offset_row_len), batch.row_len);

    var reader = try BinaryNodeBatchReader.init(&payload);
    const first = (try reader.next()).?;
    const second = (try reader.next()).?;
    try std.testing.expect((try reader.next()) == null);
    try std.testing.expectEqual(@as(u64, 7), first.id);
    try std.testing.expectEqual(@as(u64, 100), first.text_offset);
    try std.testing.expectEqual(@as(u32, 3), first.text_len);
    try std.testing.expectEqual(@as(u64, 8), second.id);
    try std.testing.expectEqual(@as(u64, 103), second.text_offset);
    try std.testing.expectEqual(@as(u32, 5), second.text_len);
}

