test "store batch appends small out-of-order node texts as L0 run" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    try generated.ensureTotalCapacity(std.testing.allocator, 32);
    for (0..32) |i| {
        try generated.append(std.testing.allocator, try std.fmt.allocPrint(std.testing.allocator, "delta-probe-{d}", .{i}));
    }

    var base_index: usize = 0;
    for (generated.items, 0..) |text, i| {
        if (nodeTextHash(text) > nodeTextHash(generated.items[base_index])) base_index = i;
    }
    var batch_indexes = [_]usize{ std.math.maxInt(usize), std.math.maxInt(usize) };
    for (generated.items, 0..) |text, i| {
        if (i == base_index or nodeTextHash(text) >= nodeTextHash(generated.items[base_index])) continue;
        if (batch_indexes[0] == std.math.maxInt(usize) or nodeTextHash(text) < nodeTextHash(generated.items[batch_indexes[0]])) {
            batch_indexes[1] = batch_indexes[0];
            batch_indexes[0] = i;
        } else if (batch_indexes[1] == std.math.maxInt(usize) or nodeTextHash(text) < nodeTextHash(generated.items[batch_indexes[1]])) {
            batch_indexes[1] = i;
        }
    }
    try std.testing.expect(batch_indexes[0] != std.math.maxInt(usize));
    try std.testing.expect(batch_indexes[1] != std.math.maxInt(usize));

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = generated.items[base_index] });
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(2), .kind = .function, .text = generated.items[batch_indexes[0]] },
        .{ .id = .fromInt(3), .kind = .task, .text = generated.items[batch_indexes[1]] },
    });

    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    var delta_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_delta_path, .{});
    defer delta_file.close(std.testing.io);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexHeaderFromFile(base_file)).node_count);
    try std.testing.expectEqual(@as(u64, 0), (try store.readNodeTextIndexHeaderFromFile(delta_file)).node_count);
    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 2), manifest.entries.items[0].node_count);
    {
        var run_file = try std.Io.Dir.cwd().openFile(std.testing.io, manifest.entries.items[0].path, .{});
        defer run_file.close(std.testing.io);
        const run_header = try store.readNodeTextIndexHeaderFromFile(run_file);
        try std.testing.expect(run_header.hasDerivedTextSpan());
        try std.testing.expect(!run_header.hasDerivedHash());
        try std.testing.expect(run_header.hasU32Id());
        try std.testing.expect(!run_header.hasUniformKind());
        try std.testing.expectEqual(@as(u16, 14), run_header.record_len);
    }
    try std.testing.expect(try store.nodeIndexValid(3));

    var matches = try store.lookupNodesByTextLimited(std.testing.allocator, .function, generated.items[batch_indexes[0]], 4);
    defer {
        for (matches.items) |*node| node.deinit(std.testing.allocator);
        matches.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), matches.items.len);
    try std.testing.expectEqual(@as(u64, 2), matches.items[0].id.toInt());
}

