    try order.ensureTotalCapacity(std.testing.allocator, generated.items.len);
    for (generated.items, 0..) |_, i| try order.append(std.testing.allocator, i);
    std.mem.sort(usize, order.items, generated.items, struct {
        fn less(texts: []const []u8, lhs: usize, rhs: usize) bool {
            return nodeTextHash(texts[lhs]) < nodeTextHash(texts[rhs]);
        }
    }.less);

    const base_index = order.items[order.items.len - 1];
    const delta_index = order.items[0];
    const batch_a_index = order.items[1];
    const batch_b_index = order.items[2];

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = generated.items[base_index] });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = generated.items[delta_index] });
    var existing_records = try store.readAllNodeTextIndexRecords(std.testing.allocator);
    defer existing_records.deinit(std.testing.allocator);
    var base_record: ?NodeTextIndexRecord = null;
    var delta_record: ?NodeTextIndexRecord = null;
    for (existing_records.items) |record| {
        if (record.id == 1) base_record = record;
        if (record.id == 2) delta_record = record;
    }
    const forced_base = base_record orelse return error.InvalidRecord;
    const forced_delta = delta_record orelse return error.InvalidRecord;
    try store.writeNodeTextIndex(&.{forced_base});
    try store.appendNodeTextDeltaRecord(forced_delta, .{ .node_count = 0 });
    var meta = try store.readIndexMeta();
    try store.copyNodeTextOrderDigestFromHeader(&meta);
    try store.writeIndexMeta(meta);

    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(3), .kind = .task, .text = generated.items[batch_a_index] },
        .{ .id = .fromInt(4), .kind = .document, .text = generated.items[batch_b_index] },
    });

    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    var delta_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_delta_path, .{});
    defer delta_file.close(std.testing.io);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexHeaderFromFile(base_file)).node_count);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexHeaderFromFile(delta_file)).node_count);
    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 2), manifest.entries.items[0].node_count);
    try std.testing.expect(try store.nodeIndexValid(4));

    var matches = try store.lookupNodesByTextLimited(std.testing.allocator, .document, generated.items[batch_b_index], 4);
    defer {
        for (matches.items) |*node| node.deinit(std.testing.allocator);
        matches.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), matches.items.len);
    try std.testing.expectEqual(@as(u64, 4), matches.items[0].id.toInt());
}

