    defer compacted_run_file.close(std.testing.io);
    const compacted_run_header = try store.readNodeTextIndexHeaderFromFile(compacted_run_file);
    try std.testing.expect(!compacted_run_header.hasUniformKind());
    try std.testing.expect(compacted_run_header.hasShortTextLen());
    try std.testing.expect(compacted_run_header.hasU32Id());
    try std.testing.expect(!compacted_run_header.hasDerivedHash());
    try std.testing.expectEqual(@as(u16, 22), compacted_run_header.record_len);
    try std.testing.expectEqual(
        @as(u64, NodeTextIndexHeader.encoded_len + 5 * 22),
        try store.regularFileSize(compacted_run_file),
    );
    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    var delta_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_delta_path, .{});
    defer delta_file.close(std.testing.io);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexHeaderFromFile(base_file)).node_count);
    try std.testing.expectEqual(@as(u64, 0), (try store.readNodeTextIndexHeaderFromFile(delta_file)).node_count);
    try std.testing.expect(try store.nodeIndexValid(6));

    var limited = try store.lookupNodesByTextLimited(std.testing.allocator, null, "shared", 3);
    defer {
        for (limited.items) |*node| node.deinit(std.testing.allocator);
