    try std.testing.expectEqual(@as(u64, 5), limited.items[0].id.toInt());
    try std.testing.expectEqual(@as(u64, 10), limited.items[1].id.toInt());
    try std.testing.expectEqual(@as(u64, 20), limited.items[2].id.toInt());
}

