test "node text run manifest budget covers GB10 bulk node batches" {
    const gb10_nodes: u64 = 18_000_000;
    const required_batches = (gb10_nodes + node_text_run_max_records - 1) / node_text_run_max_records;
    try std.testing.expect(production_node_text_run_manifest_max_entries >= required_batches);
    try std.testing.expect(node_text_run_manifest_max_entries <= production_node_text_run_manifest_max_entries);
    try std.testing.expect(node_text_delta_max_records <= production_node_text_delta_max_records);
}

test "store node text overlay run reader maps records when available" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = true,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(10), .kind = .file, .text = "src/main.zig" });
    try store.appendNode(.{ .id = .fromInt(20), .kind = .function, .text = "main" });

    var texts = try Store.NodeTextsView.open(store);
    defer texts.deinit();

    var readers = std.ArrayList(Store.NodeTextOverlayRunReader).empty;
    defer {
        for (readers.items) |*reader| reader.deinit(std.testing.io);
        readers.deinit(std.testing.allocator);
    }
    try readers.ensureTotalCapacityPrecise(std.testing.allocator, 1);

    var file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    var file_owned_by_reader = false;
    errdefer if (!file_owned_by_reader) file.close(std.testing.io);
    const header = try store.readNodeTextIndexHeaderFromFile(file);
    try std.testing.expectEqual(@as(u64, 2), header.node_count);
    const file_size = try nodeTextIndexFileSizeForHeader(header);
    var map: ?std.Io.File.MemoryMap = Store.openReadOnlyMemoryMap(std.testing.io, file, file_size) catch return error.SkipZigTest;
    errdefer if (map) |*mapped| mapped.destroy(std.testing.io);

    readers.appendAssumeCapacity(.{
        .file = file,
        .map = map,
        .next_index = 0,
        .count = header.node_count,
        .header = header,
    });
    file_owned_by_reader = true;
    map = null;

    var queue = std.PriorityQueue(Store.NodeTextOverlayRunHeapEntry, void, Store.compareNodeTextOverlayRunHeapEntry).initContext({});
    defer queue.deinit(std.testing.allocator);
    try queue.ensureTotalCapacityPrecise(std.testing.allocator, 1);

    try std.testing.expect(readers.items[0].map != null);
    try store.pushNextNodeTextOverlayRecord(&readers, &queue, &texts, 0);
    const expected_first = try store.readNodeTextIndexRecordAt(readers.items[0].file, 0);
    const first = queue.pop() orelse return error.InvalidRecord;
    try std.testing.expectEqual(expected_first.hash, first.record.hash);
    try std.testing.expectEqual(expected_first.id, first.record.id);
    try std.testing.expectEqual(expected_first.kind, first.record.kind);
    try std.testing.expectEqual(@as(u64, 1), readers.items[0].next_index);

    try store.pushNextNodeTextOverlayRecord(&readers, &queue, &texts, first.run_index);
    const expected_second = try store.readNodeTextIndexRecordAt(readers.items[0].file, 1);
    const second = queue.pop() orelse return error.InvalidRecord;
    try std.testing.expectEqual(expected_second.hash, second.record.hash);
    try std.testing.expectEqual(expected_second.id, second.record.id);
    try std.testing.expectEqual(expected_second.kind, second.record.kind);
    try std.testing.expectEqual(@as(u64, 2), readers.items[0].next_index);
}

test "store compacts non-prefix node text L0 run window within record budget" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = true,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(100), .kind = .repo, .text = "base" });
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(10), .kind = .task, .text = "large-a" },
        .{ .id = .fromInt(20), .kind = .file, .text = "large-b" },
        .{ .id = .fromInt(30), .kind = .function, .text = "large-c" },
        .{ .id = .fromInt(40), .kind = .document, .text = "large-d" },
        .{ .id = .fromInt(50), .kind = .task, .text = "large-e" },
    });
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(60), .kind = .file, .text = "small-a" },
    });
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(70), .kind = .function, .text = "small-b" },
    });

    var before_manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer before_manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 3), before_manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 5), before_manifest.entries.items[0].node_count);
    try std.testing.expectEqual(@as(u64, 1), before_manifest.entries.items[1].node_count);
    try std.testing.expectEqual(@as(u64, 1), before_manifest.entries.items[2].node_count);
    const first_run_path = try std.testing.allocator.dupe(u8, before_manifest.entries.items[0].path);
    defer std.testing.allocator.free(first_run_path);
    const second_run_path = try std.testing.allocator.dupe(u8, before_manifest.entries.items[1].path);
    defer std.testing.allocator.free(second_run_path);
    const third_run_path = try std.testing.allocator.dupe(u8, before_manifest.entries.items[2].path);
    defer std.testing.allocator.free(third_run_path);

    const compacted = try store.compactNodeTextRunsBudgeted(2);
    try std.testing.expect(compacted.compacted);
    try std.testing.expectEqual(@as(usize, 3), compacted.run_entries_before);
    try std.testing.expectEqual(@as(usize, 2), compacted.run_entries_after);
    try std.testing.expectEqual(@as(u64, 7), compacted.run_records_before);
    try std.testing.expectEqual(@as(u64, 7), compacted.run_records_after);
    try std.testing.expectEqual(@as(u64, 2), compacted.compacted_run_records);
    try std.testing.expectEqual(@as(u64, 2), compacted.gc_deleted_runs);
    try std.testing.expect(try store.pathExists(first_run_path));
    try std.testing.expect(!try store.pathExists(second_run_path));
    try std.testing.expect(!try store.pathExists(third_run_path));

    var after_manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer after_manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), after_manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 5), after_manifest.entries.items[0].node_count);
    try std.testing.expectEqual(@as(u64, 2), after_manifest.entries.items[1].node_count);
    try std.testing.expectEqualStrings(first_run_path, after_manifest.entries.items[0].path);
    try std.testing.expect(try store.nodeIndexValid(8));
}

