}

test "store retained node text lookup view preserves old run epoch through compaction gc" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = true,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(100), .kind = .repo, .text = "base" });
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(20), .kind = .task, .text = "shared" },
        .{ .id = .fromInt(30), .kind = .file, .text = "run-a" },
    });
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(10), .kind = .function, .text = "shared" },
        .{ .id = .fromInt(40), .kind = .document, .text = "run-b" },
    });

    const old_epoch_path = (try store.readNodeTextRunCurrentPath(std.testing.allocator)).?;
    defer std.testing.allocator.free(old_epoch_path);
    var old_manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer old_manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), old_manifest.entries.items.len);
    const first_old_run = try std.testing.allocator.dupe(u8, old_manifest.entries.items[0].path);
    defer std.testing.allocator.free(first_old_run);
    const second_old_run = try std.testing.allocator.dupe(u8, old_manifest.entries.items[1].path);
    defer std.testing.allocator.free(second_old_run);

    var retention_registry = NodeTextRunRetentionRegistry.init(std.testing.allocator);
    defer retention_registry.deinit();
    var view = try store.openNodeTextLookupViewRetained(std.testing.allocator, &retention_registry);
    var view_live = true;
    defer if (view_live) view.deinit();
    {
        const active_paths = try retention_registry.activeManifestPaths(std.testing.allocator);
        defer std.testing.allocator.free(active_paths);
        try std.testing.expectEqual(@as(usize, 1), active_paths.len);
        try std.testing.expectEqualStrings(old_epoch_path, active_paths[0]);
    }

    const compacted = try store.compactNodeTextRunsBudgetedWithProcessLeases(0);
    try std.testing.expect(compacted.compacted);
    try std.testing.expectEqual(@as(usize, 2), compacted.run_entries_before);
    try std.testing.expectEqual(@as(usize, 1), compacted.run_entries_after);
    try std.testing.expectEqual(@as(u64, 0), compacted.gc_deleted_runs);

    const new_epoch_path = (try store.readNodeTextRunCurrentPath(std.testing.allocator)).?;
    defer std.testing.allocator.free(new_epoch_path);
    try std.testing.expect(!std.mem.eql(u8, old_epoch_path, new_epoch_path));
    try std.testing.expect(try store.pathExists(old_epoch_path));
    try std.testing.expect(try store.pathExists(first_old_run));
    try std.testing.expect(try store.pathExists(second_old_run));

    var shared = try view.lookupIds(std.testing.allocator, null, "shared", 2);
    defer shared.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), shared.items.len);
    try std.testing.expectEqual(@as(u64, 10), shared.items[0].toInt());
    try std.testing.expectEqual(@as(u64, 20), shared.items[1].toInt());

    const pinned_gc = try store.gcUnreferencedNodeTextRunsRetainingRegistry(&retention_registry);
    try std.testing.expectEqual(@as(u64, 0), pinned_gc.deleted_runs);
    try std.testing.expectEqual(@as(u64, 0), pinned_gc.deleted_manifests);
    try std.testing.expect(try store.pathExists(old_epoch_path));
    try std.testing.expect(try store.pathExists(first_old_run));
    try std.testing.expect(try store.pathExists(second_old_run));

    const process_lease_gc = try store.gcUnreferencedNodeTextRunsWithProcessLeases();
    try std.testing.expectEqual(@as(u64, 0), process_lease_gc.deleted_runs);
    try std.testing.expectEqual(@as(u64, 0), process_lease_gc.deleted_manifests);
    try std.testing.expect(try store.pathExists(old_epoch_path));
    try std.testing.expect(try store.pathExists(first_old_run));
    try std.testing.expect(try store.pathExists(second_old_run));

    view.deinit();
    view_live = false;
    {
        const active_paths = try retention_registry.activeManifestPaths(std.testing.allocator);
        defer std.testing.allocator.free(active_paths);
        try std.testing.expectEqual(@as(usize, 0), active_paths.len);
    }

    const lease_dir_path = try store.manifestProcessLeaseDirPath(std.testing.allocator);
    defer std.testing.allocator.free(lease_dir_path);
    try std.Io.Dir.cwd().createDirPath(std.testing.io, lease_dir_path);
    const stale_lease_path = try std.fs.path.join(std.testing.allocator, &.{ lease_dir_path, "node-text-stale.lease" });
    defer std.testing.allocator.free(stale_lease_path);
    const stale_lease_content = try std.fmt.allocPrint(
        std.testing.allocator,
        "tinykg-manifest-lease-v1\nkind=node-text-run\npid=2147483647\nmanifest={s}\n",
        .{old_epoch_path},
    );
    defer std.testing.allocator.free(stale_lease_content);
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = stale_lease_path,
        .data = stale_lease_content,
        .flags = .{ .truncate = true },
    });

    const final_gc = try store.gcUnreferencedNodeTextRunsWithProcessLeases();
    try std.testing.expectEqual(@as(u64, 2), final_gc.deleted_runs);
    try std.testing.expectEqual(@as(u64, 1), final_gc.deleted_manifests);
    try std.testing.expect(!try store.pathExists(old_epoch_path));
    try std.testing.expect(!try store.pathExists(first_old_run));
    try std.testing.expect(!try store.pathExists(second_old_run));
    try std.testing.expect(try store.pathExists(new_epoch_path));
    try std.testing.expect(!try store.pathExists(stale_lease_path));
    try std.testing.expect(try store.nodeIndexValid(5));
}

test "store compacts full node text run manifest before large batch fallback" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = true,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .repo, .text = "base-node" });
    var run_index: usize = 0;
    while (run_index < node_text_run_manifest_max_entries) : (run_index += 1) {
        var text_buf: [32]u8 = undefined;
        const text = try std.fmt.bufPrint(&text_buf, "l0-run-{d}", .{run_index});
        try store.appendNodesBatch(&.{.{ .id = .fromInt(2 + @as(u64, @intCast(run_index))), .kind = .task, .text = text }});
    }
    var full_manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer full_manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(node_text_run_manifest_max_entries, full_manifest.entries.items.len);

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    try generated.ensureTotalCapacity(std.testing.allocator, node_text_delta_max_records + 1);
    var i: u64 = 0;
    while (i < node_text_delta_max_records + 1) : (i += 1) {
        try generated.append(std.testing.allocator, try std.fmt.allocPrint(std.testing.allocator, "large-batch-{d}", .{i}));
    }
    var batch = std.ArrayList(graph_mod.Node).empty;
    defer batch.deinit(std.testing.allocator);
    try batch.ensureTotalCapacity(std.testing.allocator, generated.items.len);
    for (generated.items, 0..) |text, idx| {
        try batch.append(std.testing.allocator, .{
            .id = .fromInt(1000 + @as(u64, @intCast(idx))),
            .kind = .document,
            .text = text,
        });
    }

    try store.appendNodesBatch(batch.items);

    var after_manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer after_manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), after_manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, node_text_run_manifest_max_entries), after_manifest.entries.items[0].node_count);
    try std.testing.expectEqual(node_text_delta_max_records + 1, after_manifest.entries.items[1].node_count);
    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexHeaderFromFile(base_file)).node_count);
    try std.testing.expect(try store.nodeIndexValid(1 + node_text_run_manifest_max_entries + node_text_delta_max_records + 1));
}

