fn makeCompressibleNodeTextForTest(allocator: std.mem.Allocator, id: u64) ![]u8 {
    var text = std.ArrayList(u8).empty;
    errdefer text.deinit(allocator);
    var prefix_buf: [64]u8 = undefined;
    const prefix = try std.fmt.bufPrint(&prefix_buf, "agent-memory-node-{d}:", .{id});
    try text.appendSlice(allocator, prefix);
    const phrase =
        " observed build output references src/storage.zig, repair context, benchmark density, " ++
        "and a repeated decision trail for realistic agent memory retrieval. ";
    var repeat: usize = 0;
    while (repeat < 64) : (repeat += 1) try text.appendSlice(allocator, phrase);
    return try text.toOwnedSlice(allocator);
}

test "store appends to compressed node texts without expanding primary text" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = true,
    });
    defer store.deinit();
    try store.createEmpty();

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    var nodes = std.ArrayList(graph_mod.Node).empty;
    defer nodes.deinit(std.testing.allocator);

    var index: u64 = 0;
    while (index < 96) : (index += 1) {
        const text = try makeCompressibleNodeTextForTest(std.testing.allocator, index + 1);
        try generated.append(std.testing.allocator, text);
        try nodes.append(std.testing.allocator, .{
            .id = .fromInt(index + 1),
            .kind = .document,
            .text = text,
        });
    }
    try store.appendNodesBatch(nodes.items);
    const raw_size = try store.nodeTextsLogicalSize();
    try std.testing.expect(raw_size > Store.node_texts_block_deflate_block_bytes);

    {
        var texts = try Store.NodeTextsView.open(store);
        defer texts.deinit();
        try std.testing.expectEqual(Store.NodeTextsStorageFormat.block_deflate, texts.format);
        try std.testing.expectEqual(raw_size, texts.size);
    }
    var compressed_initial_validate_timings = PersistentValidateTimings{};
    try store.validatePersistentIndexesWithTimings(&compressed_initial_validate_timings);
    try std.testing.expect(compressed_initial_validate_timings.node_text_hash_cache_enabled);
    try std.testing.expect(compressed_initial_validate_timings.node_text_hash_cache_bytes > 0);

    try store.repairPersistentIndexesFromLog();

    {
        var texts = try Store.NodeTextsView.open(store);
        defer texts.deinit();
        try std.testing.expectEqual(Store.NodeTextsStorageFormat.block_deflate, texts.format);
        try std.testing.expectEqual(raw_size, texts.size);
        try std.testing.expect(texts.map == null);
    }
    try std.testing.expect((try store.fileSizeOrZero(store.node_texts_path)) < raw_size);
    const compressed_size = try store.fileSizeOrZero(store.node_texts_path);

    try store.rebuildPersistentIndexesFromLogStreamingReuseTexts(true, null);
    var compressed_validate_timings = PersistentValidateTimings{};
    try store.validatePersistentIndexesWithTimings(&compressed_validate_timings);
    try std.testing.expect(compressed_validate_timings.node_text_hash_cache_enabled);
    try std.testing.expect(compressed_validate_timings.node_text_hash_cache_bytes > 0);
    try std.testing.expectEqual(compressed_size, try store.fileSizeOrZero(store.node_texts_path));

    const target_id: u64 = 17;
    const target_text = generated.items[@intCast(target_id - 1)];
    var restored = (try store.readNodeById(std.testing.allocator, .fromInt(target_id))).?;
    defer restored.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings(target_text, restored.text);

    var matches = try store.lookupNodesByTextLimited(std.testing.allocator, .document, target_text, 2);
    defer {
        for (matches.items) |*node| node.deinit(std.testing.allocator);
        matches.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), matches.items.len);
    try std.testing.expectEqual(target_id, matches.items[0].id.toInt());

    const appended_text = try makeCompressibleNodeTextForTest(std.testing.allocator, 1000);
