        try std.testing.expectEqual(raw_size + appended_text.len, texts.size);
        try std.testing.expect((try store.fileSizeOrZero(store.node_texts_path)) < texts.size);
    }

    var appended_matches = try store.lookupNodesByTextLimited(std.testing.allocator, .document, appended_text, 2);
    defer {
        for (appended_matches.items) |*node| node.deinit(std.testing.allocator);
        appended_matches.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), appended_matches.items.len);
    try std.testing.expectEqual(@as(u64, 1000), appended_matches.items[0].id.toInt());

    const batch_first = try makeCompressibleNodeTextForTest(std.testing.allocator, 1001);
    defer std.testing.allocator.free(batch_first);
    const batch_second = try makeCompressibleNodeTextForTest(std.testing.allocator, 1002);
    defer std.testing.allocator.free(batch_second);
    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(1001), .kind = .document, .text = batch_first },
        .{ .id = .fromInt(1002), .kind = .document, .text = batch_second },
