test "store node record iterator borrows compressed single-block texts" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = true,
    });
    defer store.deinit();
    try store.createEmpty();

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    var nodes = std.ArrayList(graph_mod.Node).empty;
    defer nodes.deinit(std.testing.allocator);

    var index: u64 = 0;
    while (index < 96) : (index += 1) {
        const text = try makeCompressibleNodeTextForTest(std.testing.allocator, index + 1);
        try generated.append(std.testing.allocator, text);
        try nodes.append(std.testing.allocator, .{
            .id = .fromInt(index + 1),
            .kind = .document,
            .text = text,
        });
    }
    try store.appendNodesBatch(nodes.items);
    try std.testing.expect((try store.nodeTextsLogicalSize()) > Store.node_texts_block_deflate_block_bytes);
    try store.compressNodeTextsFileIfSmaller();

    var iterator = try store.nodeRecordsIterator(null);
    defer iterator.deinit();

    var borrowed_single_block = false;
    var saw_cross_block_fallback = false;
    while (try iterator.nextRef()) |node| {
        try std.testing.expect(node.text_bytes == null);
        const expected = generated.items[@intCast(node.id.toInt() - 1)];
        const crosses_block = (node.text_offset % Store.node_texts_block_deflate_block_bytes) + node.text_len > Store.node_texts_block_deflate_block_bytes;
        if (crosses_block) {
            try std.testing.expect((try iterator.readRefTextBorrowed(node)) == null);
            const allocated = try iterator.readRefTextAlloc(std.testing.allocator, node);
            defer std.testing.allocator.free(allocated);
            try std.testing.expectEqualStrings(expected, allocated);
            saw_cross_block_fallback = true;
        } else {
            const borrowed = (try iterator.readRefTextBorrowed(node)) orelse return error.InvalidRecord;
            try std.testing.expectEqualStrings(expected, borrowed);
            borrowed_single_block = true;
        }
    }

    try std.testing.expect(borrowed_single_block);
    try std.testing.expect(saw_cross_block_fallback);
}

