    var docs = try store.lookupNodesByText(std.testing.allocator, .document, "shared");
    defer {
        for (docs.items) |*node| node.deinit(std.testing.allocator);
        docs.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), docs.items.len);
    try std.testing.expectEqual(doc.toInt(), docs.items[0].id.toInt());
}

test "store default exact-text lookup rejects unbounded duplicate materialization" {
