test "store single-result exact-text lookup skips higher-id L0 run" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();

    const target_text = "target";
    const run_text = blk: {
        const candidates = [_][]const u8{ "a", "b", "c", "aa", "zz", "src/main.zig", "README.md" };
        for (candidates) |candidate| {
            if (nodeTextHash(candidate) < nodeTextHash(target_text)) break :blk candidate;
        }
        return error.InvalidRecord;
    };

    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = target_text });
    try store.appendNodesBatch(&.{.{ .id = .fromInt(10), .kind = .file, .text = run_text }});

    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 10), manifest.entries.items[0].min_node_id);
    try std.testing.expectEqual(@as(u64, 10), manifest.entries.items[0].max_node_id);
    const skipped_run_path = try std.testing.allocator.dupe(u8, manifest.entries.items[0].path);
    defer std.testing.allocator.free(skipped_run_path);

    var timings = Store.NodeTextLookupTimings{};
    var limited = try store.lookupNodesByTextLimitedWithTimings(std.testing.allocator, .file, target_text, 1, &timings);
    defer {
        for (limited.items) |*node| node.deinit(std.testing.allocator);
        limited.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), limited.items.len);
    try std.testing.expectEqual(@as(u64, 2), limited.items[0].id.toInt());
    try std.testing.expectEqual(@as(u64, 1), timings.run_count);
    try std.testing.expectEqual(@as(u64, 1), timings.range_skip_count);

    var open_timings = Store.NodeTextLookupOpenTimings{};
    var view = try store.openNodeTextLookupViewWithTimings(std.testing.allocator, &open_timings);
    defer view.deinit();
    try std.testing.expectEqual(@as(u64, 1), open_timings.run_entries);
    try std.testing.expectEqual(@as(u64, 0), open_timings.runs_open_count);
    var retained_timings = Store.NodeTextLookupTimings{};
    const retained_first = try view.lookupFirstIdWithTimings(.file, target_text, &retained_timings);
    try std.testing.expect(retained_first != null);
    try std.testing.expectEqual(@as(u64, 2), retained_first.?.toInt());
    try std.testing.expectEqual(@as(u64, 1), retained_timings.run_count);
    try std.testing.expectEqual(@as(u64, 1), retained_timings.range_skip_count);

    var retained_limited_timings = Store.NodeTextLookupTimings{};
    var retained_limited = try view.lookupIdsWithTimings(std.testing.allocator, .file, target_text, 1, &retained_limited_timings);
    defer retained_limited.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), retained_limited.items.len);
    try std.testing.expectEqual(@as(u64, 2), retained_limited.items[0].toInt());
    try std.testing.expectEqual(@as(u64, 1), retained_limited_timings.run_count);
    try std.testing.expectEqual(@as(u64, 1), retained_limited_timings.range_skip_count);

    try std.Io.Dir.cwd().deleteFile(std.testing.io, skipped_run_path);
    var retained_after_delete_timings = Store.NodeTextLookupTimings{};
    var retained_after_delete = try view.lookupIdsWithTimings(std.testing.allocator, .file, target_text, 1, &retained_after_delete_timings);
    defer retained_after_delete.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), retained_after_delete.items.len);
    try std.testing.expectEqual(@as(u64, 2), retained_after_delete.items[0].toInt());
    try std.testing.expectEqual(@as(u64, 1), retained_after_delete_timings.run_count);
    try std.testing.expectEqual(@as(u64, 1), retained_after_delete_timings.range_skip_count);

    var skipped_timings = Store.NodeTextLookupTimings{};
    var skipped = try store.lookupNodesByTextLimitedWithTimings(std.testing.allocator, .file, target_text, 1, &skipped_timings);
    defer {
        for (skipped.items) |*node| node.deinit(std.testing.allocator);
        skipped.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), skipped.items.len);
    try std.testing.expectEqual(@as(u64, 2), skipped.items[0].id.toInt());
    try std.testing.expectEqual(@as(u64, 1), skipped_timings.run_count);
    try std.testing.expectEqual(@as(u64, 1), skipped_timings.range_skip_count);

    store.options.validate_indexes_on_read = true;
    try std.testing.expectError(error.FileNotFound, store.lookupNodeIdsByTextLimited(std.testing.allocator, .file, target_text, 1));
}

test "store base-covered node text lookup derives empty overlays" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
