    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "alpha.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "beta.zig" });
    try store.repairPersistentIndexesFromLog();

    const meta = try store.readCurrentIndexMeta();
    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    const base_header = try store.readNodeTextIndexHeaderFromFile(base_file);
    try std.testing.expect(nodeTextBaseHeaderCoversMeta(base_header, meta));

    var timings = Store.NodeTextLookupTimings{};
    var limited = try store.lookupNodesByTextLimitedWithTimings(std.testing.allocator, .file, "alpha.zig", 1, &timings);
    defer {
        for (limited.items) |*node| node.deinit(std.testing.allocator);
        limited.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), limited.items.len);
    try std.testing.expectEqual(@as(u64, 1), limited.items[0].id.toInt());
    try std.testing.expectEqual(@as(u128, 0), timings.lazy_open_delta_header_ns);
    try std.testing.expectEqual(@as(u128, 0), timings.lazy_open_manifest_ns);
