test "store exact-text lookup skips L0 runs by manifest hash range before open" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();
    try std.testing.expect((try store.cachedNodeTextBaseHashFilter(null)) == null);
    try std.testing.expect(store.node_text_base_filter_cache.known_absent);

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    try generated.ensureTotalCapacity(std.testing.allocator, 64);
    for (0..64) |i| {
        try generated.append(std.testing.allocator, try std.fmt.allocPrint(std.testing.allocator, "hash-range-{d}", .{i}));
    }

    var order = std.ArrayList(usize).empty;
    defer order.deinit(std.testing.allocator);
    try order.ensureTotalCapacity(std.testing.allocator, generated.items.len);
    for (generated.items, 0..) |_, i| try order.append(std.testing.allocator, i);
    std.mem.sort(usize, order.items, generated.items, struct {
        fn less(texts: []const []u8, lhs: usize, rhs: usize) bool {
            return nodeTextHash(texts[lhs]) < nodeTextHash(texts[rhs]);
        }
    }.less);

    const target_text = generated.items[order.items[0]];
    const skipped_b = generated.items[order.items[1]];
    const skipped_a = generated.items[order.items[2]];
    const base_text = generated.items[order.items[order.items.len - 1]];
    const target_hash = nodeTextHash(target_text);

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = base_text });
    try store.appendNodesBatch(&.{.{ .id = .fromInt(2), .kind = .file, .text = skipped_a }});
    try store.appendNodesBatch(&.{.{ .id = .fromInt(3), .kind = .file, .text = skipped_b }});
    try store.appendNodesBatch(&.{.{ .id = .fromInt(4), .kind = .file, .text = target_text }});

    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 3), manifest.entries.items.len);
    for (manifest.entries.items) |entry| {
        try std.testing.expectEqual(entry.min_hash, entry.max_hash);
    }
    try std.testing.expectEqual(nodeTextHash(skipped_a), manifest.entries.items[0].min_hash);
    try std.testing.expectEqual(nodeTextHash(skipped_b), manifest.entries.items[1].min_hash);
    try std.testing.expectEqual(target_hash, manifest.entries.items[2].min_hash);

    const skipped_a_path = try std.testing.allocator.dupe(u8, manifest.entries.items[0].path);
    defer std.testing.allocator.free(skipped_a_path);
    const skipped_b_path = try std.testing.allocator.dupe(u8, manifest.entries.items[1].path);
    defer std.testing.allocator.free(skipped_b_path);
    try std.Io.Dir.cwd().deleteFile(std.testing.io, skipped_a_path);
    try std.Io.Dir.cwd().deleteFile(std.testing.io, skipped_b_path);

    var timings = Store.NodeTextLookupTimings{};
    const id = try store.lookupFirstNodeIdByTextWithTimings(std.testing.allocator, .file, target_text, &timings);
    try std.testing.expect(id != null);
    try std.testing.expectEqual(@as(u64, 4), id.?.toInt());
    try std.testing.expectEqual(@as(u64, 2), timings.run_count);
    try std.testing.expectEqual(@as(u64, 2), timings.range_skip_count);

    store.options.validate_indexes_on_read = true;
    var strict_timings = Store.NodeTextLookupTimings{};
    try std.testing.expectError(error.FileNotFound, store.lookupFirstNodeIdByTextWithTimings(std.testing.allocator, .file, target_text, &strict_timings));
}

test "store exact-text lookup skips broad L0 runs by manifest hash filter before open" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();
    try std.testing.expect((try store.cachedNodeTextBaseHashFilter(null)) == null);
    try std.testing.expect(store.node_text_base_filter_cache.known_absent);

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    try generated.ensureTotalCapacity(std.testing.allocator, @intCast(node_text_run_hash_filter_min_records));
    var min_hash: u64 = std.math.maxInt(u64);
    var max_hash: u64 = 0;
    for (0..node_text_run_hash_filter_min_records) |i| {
        const text = try std.fmt.allocPrint(std.testing.allocator, "hash-filter-run-{d}", .{i});
        const hash = nodeTextHash(text);
        min_hash = @min(min_hash, hash);
        max_hash = @max(max_hash, hash);
        try generated.append(std.testing.allocator, text);
    }

    var target_storage: [64]u8 = undefined;
    var target_text: []const u8 = &.{};
    var probe: u64 = 0;
    while (probe < 100_000) : (probe += 1) {
        const candidate = try std.fmt.bufPrint(&target_storage, "hash-filter-target-{d}", .{probe});
        const hash = nodeTextHash(candidate);
        if (hash > min_hash and hash < max_hash) {
            var collides = false;
            for (generated.items) |text| {
                if (std.mem.eql(u8, text, candidate)) {
                    collides = true;
                    break;
                }
            }
            if (!collides) {
                target_text = candidate;
                break;
            }
        }
    }
    if (target_text.len == 0) return error.InvalidRecord;

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = target_text });

    var nodes = std.ArrayList(graph_mod.Node).empty;
    defer nodes.deinit(std.testing.allocator);
    try nodes.ensureTotalCapacity(std.testing.allocator, generated.items.len);
    for (generated.items, 0..) |text, index| {
        try nodes.append(std.testing.allocator, .{
            .id = .fromInt(@as(u64, @intCast(index)) + 2),
            .kind = .file,
            .text = text,
        });
    }
    try store.appendNodesBatch(nodes.items);

    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    const entry = manifest.entries.items[0];
    try std.testing.expect(entry.min_hash < nodeTextHash(target_text));
    try std.testing.expect(entry.max_hash > nodeTextHash(target_text));
    try std.testing.expectEqual(nodeTextRunHashFilterLenForRecords(node_text_run_hash_filter_min_records), entry.hash_filter.len);
    try std.testing.expect(!nodeTextRunManifestEntryMayContainHash(entry, nodeTextHash(target_text)));

    const skipped_run_path = try std.testing.allocator.dupe(u8, entry.path);
    defer std.testing.allocator.free(skipped_run_path);
    try std.Io.Dir.cwd().deleteFile(std.testing.io, skipped_run_path);

    var timings = Store.NodeTextLookupTimings{};
    const id = try store.lookupFirstNodeIdByTextWithTimings(std.testing.allocator, .file, target_text, &timings);
    try std.testing.expect(id != null);
    try std.testing.expectEqual(@as(u64, 1), id.?.toInt());
    try std.testing.expectEqual(@as(u64, 1), timings.run_count);
    try std.testing.expectEqual(@as(u64, 1), timings.range_skip_count);

    store.options.validate_indexes_on_read = true;
    var strict_timings = Store.NodeTextLookupTimings{};
    try std.testing.expectError(error.FileNotFound, store.lookupFirstNodeIdByTextWithTimings(std.testing.allocator, .file, target_text, &strict_timings));
}

