test "store routes single out-of-order node texts through bounded delta" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();

    var generated = std.ArrayList([]u8).empty;
    defer {
        for (generated.items) |text| std.testing.allocator.free(text);
        generated.deinit(std.testing.allocator);
    }
    try generated.ensureTotalCapacity(std.testing.allocator, 48);
    for (0..48) |i| {
        try generated.append(std.testing.allocator, try std.fmt.allocPrint(std.testing.allocator, "single-delta-{d}", .{i}));
    }

    var order = std.ArrayList(usize).empty;
    defer order.deinit(std.testing.allocator);
    try order.ensureTotalCapacity(std.testing.allocator, generated.items.len);
    for (generated.items, 0..) |_, i| try order.append(std.testing.allocator, i);
    std.mem.sort(usize, order.items, generated.items, struct {
        fn less(texts: []const []u8, lhs: usize, rhs: usize) bool {
            return nodeTextHash(texts[lhs]) < nodeTextHash(texts[rhs]);
        }
    }.less);

    const base_index = order.items[order.items.len - 1];
    const delta_high_index = order.items[2];
    const delta_low_index = order.items[1];

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = generated.items[base_index] });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = generated.items[delta_high_index] });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .file, .text = generated.items[delta_low_index] });

    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    var delta_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_delta_path, .{});
    defer delta_file.close(std.testing.io);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexHeaderFromFile(base_file)).node_count);
    const delta_header = try store.readNodeTextIndexHeaderFromFile(delta_file);
    try std.testing.expectEqual(@as(u64, 2), delta_header.node_count);
    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 0), manifest.entries.items.len);

    var low = try store.lookupNodeIdsByTextLimited(std.testing.allocator, .file, generated.items[delta_low_index], 1);
    defer low.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), low.items.len);
    try std.testing.expectEqual(@as(u64, 3), low.items[0].toInt());

    var high = try store.lookupNodeIdsByTextLimited(std.testing.allocator, .file, generated.items[delta_high_index], 1);
    defer high.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), high.items.len);
    try std.testing.expectEqual(@as(u64, 2), high.items[0].toInt());
}

