    const base_end = base_start + @as(usize, @intCast(node_text_base_hash_filter_min_records));
    for (generated.items[base_start..base_end], 0..) |text, index| {
        try store.appendNode(.{ .id = .fromInt(@as(u64, @intCast(index)) + 1), .kind = .file, .text = text });
