    try std.testing.expectEqual(@as(u64, 0), timings.first_base_probe_count);
    try std.testing.expectEqual(@as(u64, 1), timings.first_delta_hit_count);
    try std.testing.expectEqual(@as(u128, 0), timings.lazy_open_base_ns);
}

test "store ignores stale base hash filter after sorted base tail append" {
    var tmp = std.testing.tmpDir(.{});
