    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(10), .kind = .repo, .text = "shared" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .task, .text = "shared" });

    var existing_records = try store.readAllNodeTextIndexRecords(std.testing.allocator);
    defer existing_records.deinit(std.testing.allocator);
    var base_record: ?NodeTextIndexRecord = null;
    var delta_record: ?NodeTextIndexRecord = null;
    for (existing_records.items) |record| {
        if (record.id == 10) base_record = record;
        if (record.id == 2) delta_record = record;
    }
    const forced_base = base_record orelse return error.InvalidRecord;
    const forced_delta = delta_record orelse return error.InvalidRecord;
    try store.writeNodeTextIndex(&.{forced_base});
    try store.appendNodeTextDeltaRecord(forced_delta, .{ .node_count = 0 });
    var meta = try store.readIndexMeta();
    try store.copyNodeTextOrderDigestFromHeader(&meta);
    try store.writeIndexMeta(meta);

    const compacted = try store.compactNodeTextDeltaBudgeted(0);
    try std.testing.expect(compacted.compacted);
    try std.testing.expectEqual(@as(u64, 1), compacted.delta_records_before);
    try std.testing.expectEqual(@as(u64, 0), compacted.delta_records_after);

    var base_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer base_file.close(std.testing.io);
    var delta_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_delta_path, .{});
    defer delta_file.close(std.testing.io);
    try std.testing.expectEqual(@as(u64, 2), (try store.readNodeTextIndexHeaderFromFile(base_file)).node_count);
    try std.testing.expectEqual(@as(u64, 0), (try store.readNodeTextIndexHeaderFromFile(delta_file)).node_count);
    try std.testing.expect(try store.persistentIndexesCurrent(try store.stats()));

    var limited = try store.lookupNodesByTextLimited(std.testing.allocator, null, "shared", 1);
    defer {
        for (limited.items) |*node| node.deinit(std.testing.allocator);
        limited.deinit(std.testing.allocator);
    }
    try std.testing.expectEqual(@as(usize, 1), limited.items.len);
    try std.testing.expectEqual(@as(u64, 2), limited.items[0].id.toInt());
}

