test "store flushes single append delta after bulk node-text runs" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();

    var initial_texts = std.ArrayList([]u8).empty;
    defer {
        for (initial_texts.items) |text| std.testing.allocator.free(text);
        initial_texts.deinit(std.testing.allocator);
    }
    try initial_texts.ensureTotalCapacity(std.testing.allocator, 128);
    for (0..128) |index| {
        const text = try std.fmt.allocPrint(std.testing.allocator, "bulk-node-{d}", .{index});
        try initial_texts.append(std.testing.allocator, text);
    }
    var order = std.ArrayList(usize).empty;
    defer order.deinit(std.testing.allocator);
    try order.ensureTotalCapacity(std.testing.allocator, initial_texts.items.len);
    for (initial_texts.items, 0..) |_, index| try order.append(std.testing.allocator, index);
    std.mem.sort(usize, order.items, initial_texts.items, struct {
        fn less(texts: []const []u8, lhs: usize, rhs: usize) bool {
            return nodeTextHash(texts[lhs]) < nodeTextHash(texts[rhs]);
        }
    }.less);
    const base_index = order.items[order.items.len - 1];
    try store.appendNode(.{
        .id = .fromInt(1000 + @as(u64, @intCast(base_index))),
        .kind = .file,
        .text = initial_texts.items[base_index],
    });

    var initial_nodes = std.ArrayList(graph_mod.Node).empty;
    defer initial_nodes.deinit(std.testing.allocator);
    try initial_nodes.ensureTotalCapacity(std.testing.allocator, order.items.len - 1);
    for (order.items[0 .. order.items.len - 1]) |text_index| {
        try initial_nodes.append(std.testing.allocator, .{
            .id = .fromInt(1000 + @as(u64, @intCast(text_index))),
            .kind = .file,
            .text = initial_texts.items[text_index],
        });
    }
    try store.appendNodesBatch(initial_nodes.items);

    var manifest = try store.readNodeTextRunManifest(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    manifest.deinit(std.testing.allocator);

    var text_storage: [128]u8 = undefined;
    var node_id: u64 = 1;
    while (node_id <= node_text_single_append_delta_flush_records + 8) : (node_id += 1) {
        const text = try std.fmt.bufPrint(&text_storage, "post-bulk-node-{d}", .{node_id});
        try store.appendNode(.{ .id = .fromInt(node_id), .kind = .task, .text = text });
        const found = try store.lookupFirstNodeIdByText(std.testing.allocator, .task, text);
        try std.testing.expect(found != null);
        try std.testing.expectEqual(node_id, found.?.toInt());
    }

    try std.testing.expect(try store.persistentIndexesCurrent(try store.stats()));
}

