    defer file.close(std.testing.io);
    const header = try store.readNodeByIdHeaderFromFile(file);
    var record_bytes: [NodeByIdRecord.encoded_len]u8 = undefined;
    const encoded = record_bytes[0..header.record_len];
    if (header.hasUniformKind()) {
        if (header.hasShortTextLen()) {
            std.mem.writeInt(u16, encoded[0..2], 0, .little);
            try writeU48(encoded[2..8], 1);
        } else {
            std.mem.writeInt(u32, encoded[0..4], 0, .little);
            try writeU48(encoded[4..10], 1);
        }
    } else {
        std.mem.writeInt(u16, encoded[0..2], 0, .little);
        std.mem.writeInt(u32, encoded[2..6], 1, .little);
        try writeU48(encoded[6..12], 1);
    }
    try file.writePositionalAll(std.testing.io, encoded, try nodeByIdRecordOffsetForHeader(header, 1));

    try std.testing.expectError(error.InvalidRecord, store.scanNodeIds(std.testing.allocator, null, 10));
}

