test "store enforces node by id index size limit before appending node event" {
    {
        var tmp = std.testing.tmpDir(.{});
        defer tmp.cleanup();

        var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
        const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
        const root_path = path_buf[0..root_len];
        const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg-tight" });
        defer std.testing.allocator.free(store_path);

        const one_node_derived_size = NodeByIdHeader.encoded_len + NodeByIdRecord.uniform_short_derived_offset_encoded_len + 8;
        var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
            .max_node_by_id_index_bytes = one_node_derived_size,
        });
        defer store.deinit();
        try store.createEmpty();

        try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "one" });
        try std.testing.expectEqual(
            one_node_derived_size,
            try store.fileSizeOrZero(store.node_by_id_path),
        );
        try std.testing.expectError(error.RecordTooLarge, store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "two" }));
    }

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    const two_node_derived_size = NodeByIdHeader.encoded_len + 2 * NodeByIdRecord.uniform_short_derived_offset_encoded_len + 8;
    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "one" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "two" });
    try std.testing.expectEqual(two_node_derived_size, try store.fileSizeOrZero(store.node_by_id_path));
    store.options.max_node_by_id_index_bytes = two_node_derived_size;
    try std.testing.expectError(error.RecordTooLarge, store.nextNodeId());

    const before = try store.fileSizeOrZero(store.events_bin_path);
    try std.testing.expectError(error.RecordTooLarge, store.appendNode(.{ .id = .fromInt(3), .kind = .file, .text = "three" }));
    try std.testing.expectEqual(before, try store.fileSizeOrZero(store.events_bin_path));
}

