    try store.writeEdgeSegmentManifestEntries(&.{
        .{ .edge_count = segment_a_summary.count, .edge_digest = segment_a_digest, .edge_id_range = segment_a_summary.range, .edge_id_digest = segment_a_summary.digest, .edge_id_order_digest = segment_a_index.edge_id_order_digest, .edge_id_runs = segment_a_index.edge_id_runs, .path = segment_a_path },
        .{ .edge_count = segment_b_summary.count, .edge_digest = segment_b_digest, .edge_id_range = segment_b_summary.range, .edge_id_digest = segment_b_summary.digest, .edge_id_order_digest = segment_b_index.edge_id_order_digest, .edge_id_runs = segment_b_index.edge_id_runs, .path = segment_b_path },
    });

    const current_path = (try store.readEdgeSegmentCurrentPath(std.testing.allocator)).?;
    defer std.testing.allocator.free(current_path);
    try std.testing.expect(std.mem.indexOf(u8, current_path, "edge_segment.manifest.2.") != null);
    var current_manifest = try store.readEdgeSegmentManifest(std.testing.allocator);
    try std.testing.expect(current_manifest.ranges_trusted);
    try std.testing.expectEqual(@as(u64, 2), current_manifest.totalEdgeCount());
    try std.testing.expectEqual(@as(u64, 2), current_manifest.entries.items[0].edge_id_range.min);
    try std.testing.expectEqual(@as(u64, 2), current_manifest.entries.items[0].edge_id_range.max);
    try std.testing.expectEqual(@as(u64, 1), current_manifest.entries.items[1].edge_id_range.min);
    try std.testing.expectEqual(@as(u64, 1), current_manifest.entries.items[1].edge_id_range.max);
    current_manifest.deinit(std.testing.allocator);

    try std.testing.expect(!try store.pathExists(store.edge_segment_manifest_path));

    try std.Io.Dir.cwd().deleteFile(std.testing.io, store.edge_segment_current_path);
    try std.testing.expectError(error.FileNotFound, store.readEdgeSegmentManifest(std.testing.allocator));
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = store.edge_segment_current_path,
        .data = current_path,
        .flags = .{ .truncate = true },
    });

    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = store.edge_segment_current_path,
        .data = store.edge_segment_manifest_path,
        .flags = .{ .truncate = true },
    });
    try std.testing.expectError(error.InvalidRecord, store.readEdgeSegmentManifest(std.testing.allocator));

    const missing_manifest_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "missing-edge-segment.manifest" });
    defer std.testing.allocator.free(missing_manifest_path);
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = store.edge_segment_current_path,
        .data = missing_manifest_path,
        .flags = .{ .truncate = true },
    });
    try std.testing.expectError(error.InvalidRecord, store.readEdgeSegmentManifest(std.testing.allocator));
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = store.edge_segment_current_path,
        .data = current_path,
        .flags = .{ .truncate = true },
    });

    const CollectContext = struct {
        dsts: *std.ArrayList(u64),
        allocator: std.mem.Allocator,
    };
    var dsts = std.ArrayList(u64).empty;
    defer dsts.deinit(std.testing.allocator);
    var context = CollectContext{ .dsts = &dsts, .allocator = std.testing.allocator };
    const routed = try store.forEachPublishedEdgeSegmentNeighbor(.forward, .fromInt(1), .mentions, 10, &context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);

    try std.testing.expectEqual(false, routed);
    try std.testing.expectEqual(@as(usize, 2), dsts.items.len);
    try std.testing.expectEqual(@as(u64, 2), dsts.items[0]);
    try std.testing.expectEqual(@as(u64, 3), dsts.items[1]);
    try std.testing.expectEqual(null, try store.openPublishedEdgeSegment(std.testing.allocator));
}

