test "edge segment id sidecar summary derives complete range without material sidecar" {
    const complete = segment_mod.ImmutableAdjacencySegment.EdgeIdSummary{
        .count = 4,
        .range = .{ .min = 10, .max = 13 },
        .digest = try edgeSegmentIdRangeDigest(10, 13),
    };
    const derived = (try edgeSegmentIdSidecarSummaryFromCompleteRange(complete)).?;
    try std.testing.expectEqual(@as(u64, 0), derived.edge_id_order_digest);
    try std.testing.expectEqual(@as(u64, 1), derived.edge_id_runs.run_count);
    try std.testing.expectEqual(@as(u64, 10), derived.edge_id_runs.first_min);
    try std.testing.expectEqual(@as(u64, 13), derived.edge_id_runs.first_max);

    const gap = segment_mod.ImmutableAdjacencySegment.EdgeIdSummary{
        .count = 3,
        .range = .{ .min = 10, .max = 13 },
        .digest = edgeSegmentIdDigest(10) ^ edgeSegmentIdDigest(12) ^ edgeSegmentIdDigest(13),
    };
    try std.testing.expectEqual(@as(?EdgeSegmentIdSidecarSummary, null), try edgeSegmentIdSidecarSummaryFromCompleteRange(gap));

    var wrong_digest = complete;
    wrong_digest.digest ^= 1;
    try std.testing.expectEqual(@as(?EdgeSegmentIdSidecarSummary, null), try edgeSegmentIdSidecarSummaryFromCompleteRange(wrong_digest));
}

