    try std.Io.Dir.cwd().deleteFile(std.testing.io, rev_path);

    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(2500), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
        .{ .id = .fromInt(2600), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });

