        .{ .id = .fromInt(2000), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
        .{ .id = .fromInt(2700), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    }));
    try std.testing.expectEqual(before, try store.fileSizeOrZero(store.events_bin_path));
}

test "store skips whole overlay through current meta run summary" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "b.zig" });

    var base_edges = std.ArrayList(graph_mod.Edge).empty;
    defer base_edges.deinit(std.testing.allocator);
    try base_edges.ensureTotalCapacity(std.testing.allocator, 1024);
    var edge_id: u64 = 1;
    while (edge_id <= 1024) : (edge_id += 1) {
        base_edges.appendAssumeCapacity(.{
            .id = .fromInt(edge_id),
            .src = .fromInt(1),
            .rel = .mentions,
            .dst = .fromInt(2),
        });
    }
    try store.appendEdgesBatch(base_edges.items);
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(2000), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(3000), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });

    var manifest = try store.readEdgeSegmentManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expect(manifest.ranges_trusted);
    try std.testing.expectEqual(@as(usize, 2), manifest.entries.items.len);

    var stats = EdgeBatchSegmentDeltaStats{};
    store.edge_batch_segment_delta_stats = &stats;
    const meta = try store.readCurrentIndexMeta();
    try std.testing.expectEqual(@as(u64, 2), meta.edge_segment_id_runs.run_count);
    try std.testing.expectEqual(@as(u64, 2), meta.edge_segment_edges);
    try std.testing.expect(!try store.edgeIdSetIntersectsSegmentOverlay(meta, &.{2500}, 2500, 2500));
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_entries_considered);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_entries_range_skipped);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_sidecar_checks);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_csr_fallbacks);

    stats = .{};
    try std.testing.expect(try store.edgeIdSetIntersectsSegmentOverlay(meta, &.{3000}, 3000, 3000));
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_entries_considered);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_entries_range_skipped);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_sidecar_checks);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_csr_fallbacks);

    var stale_meta = meta;
    stale_meta.edge_segment_manifest_digest ^= 1;
    stats = .{};
    try std.testing.expect(!try store.edgeIdSetIntersectsSegmentOverlay(stale_meta, &.{2500}, 2500, 2500));
    try std.testing.expectEqual(@as(u64, 2), stats.overlay_entries_considered);
    try std.testing.expectEqual(@as(u64, 2), stats.overlay_entries_range_skipped);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_sidecar_checks);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_csr_fallbacks);

    stats = .{};
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(2500), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });
    try std.testing.expectEqual(@as(u64, 1), stats.slow_path_batches);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_entries_considered);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_sidecar_checks);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_csr_fallbacks);
}

