test "edge segment manifest stores two-run summaries as split points" {
    const entry = EdgeSegmentManifestEntry{
        .edge_count = 5,
        .edge_digest = 0,
        .edge_id_range = .{ .min = 1, .max = 11 },
        .edge_id_digest = 0,
        .edge_id_runs = .{
            .run_count = 2,
            .first_min = 1,
            .first_max = 3,
            .second_min = 10,
            .second_max = 11,
        },
        .path = "segments/edge-s000001",
    };
    var encoded: [EdgeSegmentManifest.entry_header_len]u8 = undefined;
    try encodeEdgeSegmentManifestEntryHeader(entry, &encoded);
    try std.testing.expectEqual(edge_segment_manifest_run_two_split | edge_segment_manifest_src_full | edge_segment_manifest_dst_full, std.mem.readInt(u32, encoded[4..8], .little));
    const run_encoding = try encodeEdgeSegmentManifestRunEncoding(entry);
    var extra: [16]u8 = undefined;
    std.mem.writeInt(u64, extra[0..8], run_encoding.first_max, .little);
    std.mem.writeInt(u64, extra[8..16], run_encoding.second_min, .little);

    const decoded = try decodeEdgeSegmentManifestEntryHeader(&encoded);
    const decoded_edge_count = try deriveEdgeSegmentManifestEdgeCountFromRunEncoding(
        decoded.edge_id_range,
        decoded.entry_flags,
        std.mem.readInt(u64, extra[0..8], .little),
        std.mem.readInt(u64, extra[8..16], .little),
    );
    const decoded_runs = try decodeEdgeSegmentManifestRunEncoding(
        decoded_edge_count,
        decoded.edge_id_range,
        decoded.entry_flags,
        std.mem.readInt(u64, extra[0..8], .little),
        std.mem.readInt(u64, extra[8..16], .little),
    );
    try std.testing.expectEqual(@as(u64, 2), decoded_runs.run_count);
    try std.testing.expectEqual(@as(u64, 1), decoded_runs.first_min);
    try std.testing.expectEqual(@as(u64, 3), decoded_runs.first_max);
    try std.testing.expectEqual(@as(u64, 10), decoded_runs.second_min);
    try std.testing.expectEqual(@as(u64, 11), decoded_runs.second_max);

    try std.testing.expectError(error.InvalidRecord, deriveEdgeSegmentManifestEdgeCountFromRunEncoding(decoded.edge_id_range, decoded.entry_flags, 3, 4));
}

test "edge segment manifest stores order digest only when explicit" {
