    try std.testing.expect(std.mem.startsWith(u8, std.fs.path.basename(current_path), "edge_segment.manifest."));

    var manifest = try moved_store.readEdgeSegmentManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    const moved_segment_path = try std.fs.path.join(std.testing.allocator, &.{ moved_store_path, "edge_segments", "safeleafx" });
    defer std.testing.allocator.free(moved_segment_path);
