    try std.testing.expectEqual(edge_segment_manifest_edge_count_explicit | edge_segment_manifest_edge_digest_explicit | edge_segment_manifest_src_single, std.mem.readInt(u32, encoded[4..8], .little));
    try std.testing.expectEqual(@as(usize, 8), try edgeSegmentManifestEdgeCountExtraLen(std.mem.readInt(u32, encoded[4..8], .little)));

    const endpoint_encoding = try encodeEdgeSegmentManifestEndpointEncoding(entry);
    try std.testing.expectEqual(@as(usize, 24), try edgeSegmentManifestEndpointExtraLen(endpoint_encoding.flags));
    const decoded = try decodeEdgeSegmentManifestEndpointRanges(
        endpoint_encoding.flags,
        endpoint_encoding.src_min,
        endpoint_encoding.dst_min,
        0,
        endpoint_encoding.dst_max,
    );
    try std.testing.expectEqual(@as(u64, 7), decoded.src_node_range.min);
    try std.testing.expectEqual(@as(u64, 7), decoded.src_node_range.max);
    try std.testing.expectEqual(@as(u64, 20), decoded.dst_node_range.min);
    try std.testing.expectEqual(@as(u64, 22), decoded.dst_node_range.max);

    const full_entry = EdgeSegmentManifestEntry{
        .edge_count = 1,
        .edge_digest = 0,
        .edge_id_range = .{ .min = 1, .max = 1 },
        .edge_id_digest = 0,
        .path = "segments/edge-s000002",
    };
    const full_endpoint_encoding = try encodeEdgeSegmentManifestEndpointEncoding(full_entry);
    try std.testing.expectEqual(edge_segment_manifest_src_full | edge_segment_manifest_dst_full, full_endpoint_encoding.flags);
    try std.testing.expectEqual(@as(usize, 0), try edgeSegmentManifestEndpointExtraLen(full_endpoint_encoding.flags));
    const full_decoded = try decodeEdgeSegmentManifestEndpointRanges(
        full_endpoint_encoding.flags,
        full_endpoint_encoding.src_min,
        full_endpoint_encoding.dst_min,
        0,
        0,
    );
    try std.testing.expectEqual(EdgeSegmentManifestEntry.full_node_range.min, full_decoded.src_node_range.min);
    try std.testing.expectEqual(EdgeSegmentManifestEntry.full_node_range.max, full_decoded.src_node_range.max);
    try std.testing.expectError(error.InvalidRecord, edgeSegmentManifestEndpointExtraLen(edge_segment_manifest_src_single | edge_segment_manifest_src_full));
}

