test "store skips two-run edge id manifest entries without opening sidecar" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const missing_segment_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "missing-two-run-segment" });
    defer std.testing.allocator.free(missing_segment_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "b.zig" });

    var edges = std.ArrayList(graph_mod.Edge).empty;
    defer edges.deinit(std.testing.allocator);
    try edges.ensureTotalCapacity(std.testing.allocator, 128);
    var id: u64 = 1;
    while (id <= 64) : (id += 1) {
        edges.appendAssumeCapacity(.{ .id = .fromInt(id), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) });
    }
    id = 1001;
    while (id <= 1064) : (id += 1) {
        edges.appendAssumeCapacity(.{ .id = .fromInt(id), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) });
    }
    try store.appendEdgesBatch(edges.items);

    var digest: u64 = 0;
    var edge_digest: u64 = 0;
    var order_digest: u64 = 0;
    for (edges.items, 0..) |edge, index| {
        const edge_id = edge.id.toInt();
        digest ^= edgeSegmentIdDigest(edge_id);
        edge_digest ^= edgeRecordDigest(.{ .src = edge.src.toInt(), .dst = edge.dst.toInt(), .edge_id = edge_id, .rel = @intFromEnum(edge.rel) });
        order_digest ^= edgeSegmentIdIndexOrderDigestAt(index, edge_id);
    }
    try store.writeEdgeSegmentManifestEntries(&.{
        .{
            .edge_count = 128,
            .edge_digest = edge_digest,
            .edge_id_range = .{ .min = 1, .max = 1064 },
            .edge_id_digest = digest,
            .edge_id_order_digest = order_digest,
            .edge_id_runs = .{
                .run_count = 2,
                .first_min = 1,
                .first_max = 64,
                .second_min = 1001,
                .second_max = 1064,
            },
            .path = missing_segment_path,
        },
    });

    const meta = try store.readCurrentIndexMeta();
    var stats = EdgeBatchSegmentDeltaStats{};
    store.edge_batch_segment_delta_stats = &stats;
    try std.testing.expect(!try store.edgeIdSetIntersectsSegmentOverlay(meta, &.{500}, 500, 500));
    try std.testing.expectEqual(@as(u64, 1), stats.overlay_entries_considered);
    try std.testing.expectEqual(@as(u64, 1), stats.overlay_entries_range_skipped);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_sidecar_checks);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_csr_fallbacks);

    stats = .{};
    try std.testing.expect(try store.edgeIdSetIntersectsSegmentOverlay(meta, &.{1005}, 1005, 1005));
    try std.testing.expectEqual(@as(u64, 1), stats.overlay_entries_considered);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_sidecar_checks);
    try std.testing.expectEqual(@as(u64, 0), stats.overlay_csr_fallbacks);
}

