test "store skips base id checks for candidates outside base id run summary" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "b.zig" });

    var base_edges = std.ArrayList(graph_mod.Edge).empty;
    defer base_edges.deinit(std.testing.allocator);
    try base_edges.ensureTotalCapacity(std.testing.allocator, 1024);
    var ordinal: u64 = 1;
    while (ordinal <= 1024) : (ordinal += 1) {
        const edge_id = if ((ordinal & 1) == 1) 100_000 + (ordinal + 1) / 2 else ordinal / 2;
        base_edges.appendAssumeCapacity(.{
            .id = .fromInt(edge_id),
            .src = .fromInt(1),
            .rel = .mentions,
            .dst = .fromInt(2),
        });
    }
    try store.appendEdgesBatch(base_edges.items);

    const base_meta = try store.readIndexMeta();
    try std.testing.expectEqual(@as(u64, 2), base_meta.edge_by_id_runs.run_count);
    try std.testing.expectEqual(@as(u64, 1), base_meta.edge_by_id_runs.first_min);
    try std.testing.expectEqual(@as(u64, 512), base_meta.edge_by_id_runs.first_max);
    try std.testing.expectEqual(@as(u64, 100_001), base_meta.edge_by_id_runs.second_min);
    try std.testing.expectEqual(@as(u64, 100_512), base_meta.edge_by_id_runs.second_max);
    try std.testing.expectEqual(@as(usize, 0), base_meta.edge_by_id_runs.intersectingSortedIdCount(&.{ 513, 576 }));
    try std.testing.expectEqual(@as(usize, 2), base_meta.edge_by_id_runs.intersectingSortedIdCount(&.{ 1, 513, 100_010 }));

    var duplicate_stats = EdgeBatchSegmentDeltaStats{};
    store.edge_batch_segment_delta_stats = &duplicate_stats;
    try std.testing.expectError(core.Error.InvalidId, store.appendEdgesBatch(&.{
        .{ .id = .fromInt(100_010), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    }));
    try std.testing.expectEqual(@as(u64, 1), duplicate_stats.slow_path_batches);
    try std.testing.expectEqual(@as(u64, 1), duplicate_stats.base_id_checks);
    try std.testing.expectEqual(@as(u64, 0), duplicate_stats.overlay_checks);

    const id_index_size_before_sorted_gap = try store.fileSizeOrZero(store.edge_by_id_path);
    var sorted_gap_edges = std.ArrayList(graph_mod.Edge).empty;
    defer sorted_gap_edges.deinit(std.testing.allocator);
    try sorted_gap_edges.ensureTotalCapacity(std.testing.allocator, 64);
    var sorted_gap_id: u64 = 513;
    while (sorted_gap_id <= 576) : (sorted_gap_id += 1) {
        sorted_gap_edges.appendAssumeCapacity(.{
            .id = .fromInt(sorted_gap_id),
            .src = .fromInt(1),
            .rel = .mentions,
            .dst = .fromInt(2),
        });
    }
    var sorted_gap_stats = EdgeBatchSegmentDeltaStats{};
    store.edge_batch_segment_delta_stats = &sorted_gap_stats;
    try store.appendEdgesBatch(sorted_gap_edges.items);
    try std.testing.expectEqual(id_index_size_before_sorted_gap, try store.fileSizeOrZero(store.edge_by_id_path));
    try std.testing.expectEqual(@as(u64, 1), sorted_gap_stats.slow_path_batches);
    try std.testing.expectEqual(@as(u64, 1), sorted_gap_stats.slow_path_sorted_batches);
    try std.testing.expectEqual(@as(u64, 64), sorted_gap_stats.slow_path_candidate_ids);
    try std.testing.expectEqual(@as(u64, 0), sorted_gap_stats.base_id_checks);
    try std.testing.expectEqual(@as(u64, 1), sorted_gap_stats.overlay_checks);

    var next_edges = std.ArrayList(graph_mod.Edge).empty;
    defer next_edges.deinit(std.testing.allocator);
    try next_edges.ensureTotalCapacity(std.testing.allocator, 128);
    ordinal = 1153;
    while (ordinal <= 1280) : (ordinal += 1) {
        const edge_id = if ((ordinal & 1) == 1) 100_000 + (ordinal + 1) / 2 else ordinal / 2;
        next_edges.appendAssumeCapacity(.{
            .id = .fromInt(edge_id),
            .src = .fromInt(1),
            .rel = .mentions,
            .dst = .fromInt(2),
        });
    }

    const id_index_size_before = try store.fileSizeOrZero(store.edge_by_id_path);
    var stats = EdgeBatchSegmentDeltaStats{};
    store.edge_batch_segment_delta_stats = &stats;
    try store.appendEdgesBatch(next_edges.items);
    try std.testing.expectEqual(id_index_size_before, try store.fileSizeOrZero(store.edge_by_id_path));
    try std.testing.expectEqual(@as(u64, 1), stats.slow_path_batches);
    try std.testing.expectEqual(@as(u64, 0), stats.slow_path_sorted_batches);
    try std.testing.expectEqual(@as(u64, 64), stats.slow_path_candidate_ids);
    try std.testing.expectEqual(@as(u64, 0), stats.base_id_checks);
    try std.testing.expectEqual(@as(u64, 1), stats.overlay_checks);

    var corrupt_meta = base_meta;
    corrupt_meta.edge_by_id_runs = .{ .run_count = 1, .first_min = 1, .first_max = 1024 };
    try store.writeIndexMeta(corrupt_meta);
    try std.testing.expectError(core.Error.InvalidId, store.appendEdgesBatch(&.{
        .{ .id = .fromInt(100_010), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    }));
}

test "store compacts published edge segments into single merged segment" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const segment_a_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-s000001" });
    defer std.testing.allocator.free(segment_a_path);
    const segment_b_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-s000002" });
    defer std.testing.allocator.free(segment_b_path);
    const compacted_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-compacted" });
    defer std.testing.allocator.free(compacted_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = "main" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .file, .text = "b.zig" });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3) },
    });

    var segment_a = try segment_mod.ImmutableAdjacencySegment.buildFromOrderedDirections(
        std.testing.allocator,
        std.testing.io,
        segment_a_path,
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3), .edge_id = .fromInt(2) }},
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3), .edge_id = .fromInt(2) }},
    );
    defer segment_a.deinit();
    var segment_b = try segment_mod.ImmutableAdjacencySegment.buildFromOrderedDirections(
        std.testing.allocator,
        std.testing.io,
        segment_b_path,
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2), .edge_id = .fromInt(1) }},
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2), .edge_id = .fromInt(1) }},
    );
    defer segment_b.deinit();
    const segment_a_summary = (try segment_a.edgeIdSummary()).?;
    const segment_b_summary = (try segment_b.edgeIdSummary()).?;
    const segment_a_digest = try segment_a.edgeDigest();
    const segment_b_digest = try segment_b.edgeDigest();
    const segment_a_index = try store.writeEdgeSegmentIdIndexFromSegment(segment_a_path, &segment_a, segment_a_summary);
    const segment_b_index = try store.writeEdgeSegmentIdIndexFromSegment(segment_b_path, &segment_b, segment_b_summary);
    try store.writeEdgeSegmentManifestEntries(&.{
        .{ .edge_count = segment_a_summary.count, .edge_digest = segment_a_digest, .edge_id_range = segment_a_summary.range, .edge_id_digest = segment_a_summary.digest, .edge_id_order_digest = segment_a_index.edge_id_order_digest, .edge_id_runs = segment_a_index.edge_id_runs, .path = segment_a_path },
        .{ .edge_count = segment_b_summary.count, .edge_digest = segment_b_digest, .edge_id_range = segment_b_summary.range, .edge_id_digest = segment_b_summary.digest, .edge_id_order_digest = segment_b_index.edge_id_order_digest, .edge_id_runs = segment_b_index.edge_id_runs, .path = segment_b_path },
    });

    try std.testing.expectEqual(@as(u64, 2), try store.compactPublishedEdgeSegments(compacted_path));
    var manifest = try store.readEdgeSegmentManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 2), manifest.totalEdgeCount());
    try std.testing.expectEqualStrings(compacted_path, manifest.entries.items[0].path);
    try std.testing.expectEqual(@as(u64, 1), manifest.entries.items[0].edge_id_runs.run_count);
    try std.testing.expectEqual(@as(u64, 1), manifest.entries.items[0].edge_id_runs.first_min);
    try std.testing.expectEqual(@as(u64, 2), manifest.entries.items[0].edge_id_runs.first_max);

    try std.Io.Dir.cwd().deleteFile(std.testing.io, store.edge_by_src_path);
    try std.Io.Dir.cwd().deleteFile(std.testing.io, store.edge_by_dst_path);

    const CollectContext = struct {
        dsts: *std.ArrayList(u64),
        allocator: std.mem.Allocator,
    };
    var dsts = std.ArrayList(u64).empty;
    defer dsts.deinit(std.testing.allocator);
    var context = CollectContext{ .dsts = &dsts, .allocator = std.testing.allocator };
    const routed = try store.forEachPublishedEdgeSegmentNeighbor(.forward, .fromInt(1), .mentions, 10, &context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);
    try std.testing.expectEqual(false, routed);
    try std.testing.expectEqual(@as(usize, 2), dsts.items.len);
    try std.testing.expectEqual(@as(u64, 2), dsts.items[0]);
    try std.testing.expectEqual(@as(u64, 3), dsts.items[1]);
}

