    try std.testing.expectEqual(@as(?bool, true), try store.edgeSegmentIdIndexContains(manifest.entries.items[0], 10));
    try std.testing.expectEqual(@as(?bool, false), try store.edgeSegmentIdIndexContains(manifest.entries.items[0], 11));

