    try std.testing.expectEqual(@as(u64, 10), try store.readEdgeSegmentIdIndexRecordAt(sidecar_file, 1));
    try std.testing.expectEqual(@as(u64, 20), try store.readEdgeSegmentIdIndexRecordAt(sidecar_file, 2));
}

test "edge segment merge stream reuses queue capacity across resets" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const segment_a_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-s000001" });
    defer std.testing.allocator.free(segment_a_path);
    const segment_b_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-s000002" });
    defer std.testing.allocator.free(segment_b_path);

    var segments = std.ArrayList(segment_mod.ImmutableAdjacencySegment).empty;
    defer {
        for (segments.items) |*edge_segment| edge_segment.deinit();
        segments.deinit(std.testing.allocator);
    }
    try segments.ensureTotalCapacity(std.testing.allocator, 2);

    segments.appendAssumeCapacity(try segment_mod.ImmutableAdjacencySegment.buildFromOrderedDirections(
        std.testing.allocator,
        std.testing.io,
        segment_a_path,
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2), .edge_id = .fromInt(1) }},
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2), .edge_id = .fromInt(1) }},
    ));
    segments.appendAssumeCapacity(try segment_mod.ImmutableAdjacencySegment.buildFromOrderedDirections(
        std.testing.allocator,
        std.testing.io,
        segment_b_path,
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3), .edge_id = .fromInt(2) }},
        &.{.{ .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3), .edge_id = .fromInt(2) }},
    ));

    var stream = EdgeSegmentMergeStream.init(std.testing.allocator, &segments, .forward);
    defer stream.deinit();

    try stream.reset();
    const first_capacity = stream.queue.cap;
    try std.testing.expect(first_capacity >= 2);
    var first_count: u64 = 0;
    while (try stream.next()) |_| first_count += 1;
    try std.testing.expectEqual(@as(u64, 2), first_count);

    try stream.reset();
    try std.testing.expectEqual(first_capacity, stream.queue.cap);
    var second_count: u64 = 0;
    while (try stream.next()) |_| second_count += 1;
    try std.testing.expectEqual(first_count, second_count);
}

