    try std.testing.expect(try store.pathExists(manifest_tmp_path));
    try std.testing.expect(try store.pathExists(manifest_non_epoch_path));
    const final_gc = try store.gcUnreferencedEdgeSegments();
    try std.testing.expectEqual(@as(u64, 0), final_gc.deleted_segments);
    try std.testing.expectEqual(@as(u64, 0), final_gc.deleted_manifests);
}

