    try std.testing.expectEqual(@as(u64, 1), pinned_gc.deleted_segments);
    try std.testing.expectEqual(@as(u64, 0), pinned_gc.deleted_manifests);
    try std.testing.expect(try store.pathExists(segment_a_path));
    try std.testing.expect(try store.pathExists(segment_b_path));
    try std.testing.expect(!try store.pathExists(segment_orphan_path));
    try std.testing.expect(try store.pathExists(compacted_path));
    try std.testing.expect(try store.pathExists(pinned_epoch_manifest));
    try std.testing.expect(try store.pathExists(current_epoch_manifest));

    pinned_window.deinit();
    const final_gc = try store.gcUnreferencedEdgeSegmentsRetainingRegistry(&retention_registry);
    try std.testing.expectEqual(@as(u64, 2), final_gc.deleted_segments);
    try std.testing.expectEqual(@as(u64, 1), final_gc.deleted_manifests);
    try std.testing.expect(!try store.pathExists(segment_a_path));
    try std.testing.expect(!try store.pathExists(segment_b_path));
    try std.testing.expect(try store.pathExists(compacted_path));
    try std.testing.expect(!try store.pathExists(pinned_epoch_manifest));
    try std.testing.expect(try store.pathExists(current_epoch_manifest));
}

