test "store retained edge segment query keeps old epoch through registry gc" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const base_segment_path = try std.fs.path.join(std.testing.allocator, &.{ store_path, "edge_segments", "base" });
    defer std.testing.allocator.free(base_segment_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
        .auto_compact_edge_segment_entries = 0,
        .auto_gc_edge_segments = true,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = "base" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .function, .text = "later" });
    try store.appendNode(.{ .id = .fromInt(4), .kind = .function, .text = "earlier" });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });
    try std.testing.expectEqual(@as(u64, 1), try store.publishEdgeAdjacencySegment(base_segment_path));
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(3), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3) },
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(4) },
    });

    var manifest_before = try store.readEdgeSegmentManifest(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), manifest_before.entries.items.len);
    const l0_segment_path = try std.testing.allocator.dupe(u8, manifest_before.entries.items[1].path);
    defer std.testing.allocator.free(l0_segment_path);
    manifest_before.deinit(std.testing.allocator);

    var retention_registry = EdgeSegmentRetentionRegistry.init(std.testing.allocator);
    defer retention_registry.deinit();
    var retained = (try store.openPublishedEdgeSegmentsForQueryRetained(std.testing.allocator, &retention_registry)).?;
    try std.testing.expectEqual(PublishedEdgeSegmentsCoverage.full, retained.coverage);
    try std.testing.expectEqual(@as(usize, 2), retained.segments.segments.items.len);
    {
        const active_paths = try retention_registry.activeManifestPaths(std.testing.allocator);
        defer std.testing.allocator.free(active_paths);
        try std.testing.expectEqual(@as(usize, 1), active_paths.len);
    }

    const compacted = try store.compactEdgeSegmentsBudgetedWithProcessLeases(.{ .max_segments = 2, .max_edges = 3 });
    try std.testing.expect(compacted.compacted);
    try std.testing.expectEqual(@as(u64, 0), compacted.gc_deleted_segments);

    const process_lease_gc = try store.gcUnreferencedEdgeSegmentsWithProcessLeases();
    try std.testing.expectEqual(@as(u64, 0), process_lease_gc.deleted_segments);
    try std.testing.expect(try store.pathExists(base_segment_path));
    try std.testing.expect(try store.pathExists(l0_segment_path));

    const retained_gc = try store.gcUnreferencedEdgeSegmentsRetainingRegistry(&retention_registry);
    try std.testing.expectEqual(@as(u64, 0), retained_gc.deleted_segments);
    try std.testing.expect(try store.pathExists(base_segment_path));
    try std.testing.expect(try store.pathExists(l0_segment_path));

    retained.deinit();
    {
        const active_paths = try retention_registry.activeManifestPaths(std.testing.allocator);
        defer std.testing.allocator.free(active_paths);
        try std.testing.expectEqual(@as(usize, 0), active_paths.len);
    }

    const final_gc = try store.gcUnreferencedEdgeSegmentsWithProcessLeases();
    try std.testing.expectEqual(@as(u64, 2), final_gc.deleted_segments);
    try std.testing.expect(!try store.pathExists(base_segment_path));
    try std.testing.expect(!try store.pathExists(l0_segment_path));
}

