    try store.appendNode(.{ .id = .fromInt(3), .kind = .function, .text = "small" });
    try store.appendNode(.{ .id = .fromInt(4), .kind = .function, .text = "large" });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });
    try std.testing.expectEqual(@as(u64, 1), try store.publishEdgeAdjacencySegment(base_segment_path));

    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3) },
    });
    var large_edges: [20]graph_mod.Edge = undefined;
    for (&large_edges, 0..) |*edge, index| {
        edge.* = .{
            .id = .fromInt(@as(u64, 3) + @as(u64, @intCast(index))),
            .src = .fromInt(1),
            .rel = .mentions,
            .dst = .fromInt(4),
        };
    }
