    var before = try store.readEdgeSegmentManifest(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 3), before.entries.items.len);
    try std.testing.expectEqual(@as(u64, 1), before.entries.items[0].edge_count);
    try std.testing.expectEqual(@as(u64, 1), before.entries.items[1].edge_count);
    try std.testing.expectEqual(@as(u64, 20), before.entries.items[2].edge_count);
    try std.testing.expectEqual(@as(usize, 0), before.entries.items[1].path.len);
    const small_segment_path = try std.testing.allocator.dupe(u8, before.entries.items[1].path);
    defer std.testing.allocator.free(small_segment_path);
    const large_segment_path = try std.testing.allocator.dupe(u8, before.entries.items[2].path);
    defer std.testing.allocator.free(large_segment_path);
    before.deinit(std.testing.allocator);

    const result = try store.compactEdgeSegmentsBudgeted(.{ .max_segments = 2, .max_edges = 2 });
    try std.testing.expect(result.compacted);
    try std.testing.expectEqual(@as(u64, 2), result.compacted_edges);
    try std.testing.expectEqual(@as(usize, 2), result.compacted_segments);
    try std.testing.expectEqual(@as(u64, 1), result.gc_deleted_segments);
    try std.testing.expectEqual(@as(usize, 3), result.manifest_entries_before);
    try std.testing.expectEqual(@as(usize, 2), result.manifest_entries_after);
    try std.testing.expect(!try store.pathExists(base_segment_path));
    try std.testing.expectEqual(@as(usize, 0), small_segment_path.len);
    try std.testing.expect(try store.pathExists(large_segment_path));

    var manifest = try store.readEdgeSegmentManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 2), manifest.entries.items[0].edge_count);
    try std.testing.expectEqual(@as(u64, 20), manifest.entries.items[1].edge_count);
    try std.testing.expectEqual(@as(u64, 22), manifest.totalEdgeCount());

    var query_segments = (try store.openPublishedEdgeSegmentsForQuery(std.testing.allocator)).?;
    defer query_segments.deinit();
    try std.testing.expectEqual(PublishedEdgeSegmentsCoverage.full, query_segments.coverage);
    try std.testing.expectEqual(@as(usize, 2), query_segments.segments.segments.items.len);
}

