test "store compacts delta overlay with repeated ring keys" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const compacted_path = try std.fs.path.join(std.testing.allocator, &.{ store_path, "edge_segments", "compacted" });
    defer std.testing.allocator.free(compacted_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    var nodes = std.ArrayList(graph_mod.Node).empty;
    defer nodes.deinit(std.testing.allocator);
    var texts = std.ArrayList([]u8).empty;
    defer {
        for (texts.items) |text| std.testing.allocator.free(text);
        texts.deinit(std.testing.allocator);
    }
    try nodes.ensureTotalCapacity(std.testing.allocator, 2000);
    try texts.ensureTotalCapacity(std.testing.allocator, 2000);
    var node_id: u64 = 1;
    while (node_id <= 2000) : (node_id += 1) {
        const text = try std.fmt.allocPrint(std.testing.allocator, "node-{d}", .{node_id});
        texts.appendAssumeCapacity(text);
        try nodes.append(std.testing.allocator, .{
            .id = .fromInt(node_id),
            .kind = .file,
            .text = text,
        });
    }
    try store.appendNodesBatch(nodes.items);

    var edge_id: u64 = 1;
    while (edge_id <= 5000) {
        var edges = std.ArrayList(graph_mod.Edge).empty;
        defer edges.deinit(std.testing.allocator);
        try edges.ensureTotalCapacity(std.testing.allocator, 1024);
        var chunk_pos: usize = 0;
        while (edge_id <= 5000 and chunk_pos < 1024) : ({
            edge_id += 1;
            chunk_pos += 1;
        }) {
            const src = ((edge_id - 1) % 2000) + 1;
            const dst = (edge_id % 2000) + 1;
            edges.appendAssumeCapacity(.{
                .id = .fromInt(edge_id),
                .src = .fromInt(src),
                .rel = .mentions,
                .dst = .fromInt(dst),
            });
        }
        try store.appendEdgesBatch(edges.items);
    }
    try store.validatePersistentIndexes();
    try std.testing.expectEqual(@as(u64, 5000), try store.compactPublishedEdgeSegments(compacted_path));
    try store.repairPersistentIndexesFromLog();
    try store.validatePersistentIndexes();
}

