    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = "main" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .file, .text = "b.zig" });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
    });
    try std.testing.expectEqual(@as(u64, 1), try store.publishEdgeAdjacencySegment(base_segment_path));
    const src_index_size_before_l0 = try store.fileSizeOrZero(store.edge_by_src_path);
    const dst_index_size_before_l0 = try store.fileSizeOrZero(store.edge_by_dst_path);
    const id_index_size_before_l0 = try store.fileSizeOrZero(store.edge_by_id_path);

    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3) },
    });
    try std.testing.expectEqual(src_index_size_before_l0, try store.fileSizeOrZero(store.edge_by_src_path));
    try std.testing.expectEqual(dst_index_size_before_l0, try store.fileSizeOrZero(store.edge_by_dst_path));
    try std.testing.expectEqual(id_index_size_before_l0, try store.fileSizeOrZero(store.edge_by_id_path));
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(3), .src = .fromInt(2), .rel = .mentions, .dst = .fromInt(3) },
    });
    try std.testing.expectEqual(src_index_size_before_l0, try store.fileSizeOrZero(store.edge_by_src_path));
    try std.testing.expectEqual(dst_index_size_before_l0, try store.fileSizeOrZero(store.edge_by_dst_path));
    try std.testing.expectEqual(id_index_size_before_l0, try store.fileSizeOrZero(store.edge_by_id_path));
    const stale_meta = try store.readIndexMeta();
    try std.testing.expectEqual(@as(u64, 3), stale_meta.edges);
    try std.testing.expectEqual(@as(u64, 1), stale_meta.edge_indexed_edges);
    try std.testing.expect(stale_meta.edge_index_digest != stale_meta.edge_digest);
    try std.testing.expect(!try store.edgeIndexesMatchMeta(stale_meta));

    var segments = (try store.openPublishedEdgeSegments(std.testing.allocator)).?;
    defer segments.deinit();
    try std.testing.expectEqual(@as(usize, 1), segments.segments.items.len);
    try std.testing.expectEqual(@as(usize, 2), segments.virtual_edges.items.len);

    try std.Io.Dir.cwd().deleteFile(std.testing.io, store.edge_by_src_path);
    const CollectContext = struct {
        dsts: *std.ArrayList(u64),
        allocator: std.mem.Allocator,
    };
    var dsts = std.ArrayList(u64).empty;
    defer dsts.deinit(std.testing.allocator);
    var context = CollectContext{ .dsts = &dsts, .allocator = std.testing.allocator };
    const routed = try store.forEachPublishedEdgeSegmentNeighbor(.forward, .fromInt(1), .mentions, 10, &context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);

    try std.testing.expectEqual(false, routed.?);
    try std.testing.expectEqual(@as(usize, 2), dsts.items.len);
    try std.testing.expectEqual(@as(u64, 2), dsts.items[0]);
    try std.testing.expectEqual(@as(u64, 3), dsts.items[1]);

    var second_context = CollectContext{ .dsts = &dsts, .allocator = std.testing.allocator };
    dsts.clearRetainingCapacity();
    const second_routed = try store.forEachPublishedEdgeSegmentNeighbor(.forward, .fromInt(2), .mentions, 10, &second_context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);
    try std.testing.expectEqual(false, second_routed.?);
    try std.testing.expectEqual(@as(usize, 1), dsts.items.len);
    try std.testing.expectEqual(@as(u64, 3), dsts.items[0]);

    try store.deleteEdge(.fromInt(2));
    const repaired_meta = try store.readIndexMeta();
    try std.testing.expectEqual(@as(u64, 2), repaired_meta.edges);
    try std.testing.expectEqual(@as(u64, 3), repaired_meta.edge_indexed_edges);
    try std.testing.expect(try store.edgeIndexesMatchMeta(repaired_meta));
    var after_delete_context = CollectContext{ .dsts = &dsts, .allocator = std.testing.allocator };
    dsts.clearRetainingCapacity();
    const after_delete_routed = try store.forEachPublishedEdgeSegmentNeighbor(.forward, .fromInt(1), .mentions, 10, &after_delete_context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);
    try std.testing.expectEqual(false, after_delete_routed.?);
    try std.testing.expectEqual(@as(usize, 1), dsts.items.len);
    try std.testing.expectEqual(@as(u64, 2), dsts.items[0]);
}

test "store exports segment bundle including edge segment delta overlay" {
    const optimizer = @import("ql/optimizer.zig");

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const bundle_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "bundle" });
    defer std.testing.allocator.free(bundle_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    var nodes = std.ArrayList(graph_mod.Node).empty;
    defer nodes.deinit(std.testing.allocator);
    var texts = std.ArrayList([]u8).empty;
    defer {
        for (texts.items) |text| std.testing.allocator.free(text);
        texts.deinit(std.testing.allocator);
    }
    try nodes.ensureTotalCapacity(std.testing.allocator, 1027);
    try texts.ensureTotalCapacity(std.testing.allocator, 1027);
    var node_id: u64 = 1;
    while (node_id <= 1027) : (node_id += 1) {
        const text = if (node_id == 1026)
            try std.testing.allocator.dupe(u8, "src/delta.zig")
        else if (node_id == 1027)
            try std.testing.allocator.dupe(u8, "delta")
        else
            try std.fmt.allocPrint(std.testing.allocator, "node-{d}", .{node_id});
        texts.appendAssumeCapacity(text);
        nodes.appendAssumeCapacity(.{
            .id = .fromInt(node_id),
            .kind = if (node_id == 1027) .function else .file,
            .text = text,
        });
    }
    try store.appendNodesBatch(nodes.items);

    var base_edges = std.ArrayList(graph_mod.Edge).empty;
    defer base_edges.deinit(std.testing.allocator);
    try base_edges.ensureTotalCapacity(std.testing.allocator, 1024);
    var edge_id: u64 = 1;
    while (edge_id <= 1024) : (edge_id += 1) {
        base_edges.appendAssumeCapacity(.{
            .id = .fromInt(edge_id),
            .src = .fromInt(1),
            .rel = .mentions,
            .dst = .fromInt(edge_id + 1),
        });
    }
    try store.appendEdgesBatch(base_edges.items);
    try std.testing.expectEqual(@as(u64, 1024), (try store.readIndexMeta()).edge_indexed_edges);

    try store.appendEdge(.{
        .id = .fromInt(1025),
        .src = .fromInt(1026),
        .rel = .defines,
        .dst = .fromInt(1027),
    });
    const delta_meta = try store.readIndexMeta();
    try std.testing.expectEqual(@as(u64, 1025), delta_meta.edges);
    try std.testing.expectEqual(@as(u64, 1024), delta_meta.edge_indexed_edges);

    try store.publishSegmentBundle(bundle_path);
    var opened = try segment_bundle.openTrusted(std.testing.allocator, std.testing.io, bundle_path);
    defer opened.deinit();
    try std.testing.expectEqual(delta_meta.event_bytes, opened.snapshot.wal_checkpoint_bytes);
    const first_generation = opened.snapshot.generation;

    try store.publishSegmentBundle(bundle_path);
    var reopened = try segment_bundle.openTrusted(std.testing.allocator, std.testing.io, bundle_path);
    defer reopened.deinit();
    try std.testing.expectEqual(first_generation, reopened.snapshot.generation);

    const manifest_dir = try std.fs.path.join(std.testing.allocator, &.{ bundle_path, segment_bundle.manifest_leaf });
    defer std.testing.allocator.free(manifest_dir);
    var manifest_store = try segment_manifest.Store.init(std.testing.allocator, std.testing.io, manifest_dir);
    defer manifest_store.deinit();
    var current_bundle = try manifest_store.pinCurrent();
    defer current_bundle.deinit(std.testing.allocator);
    var stale_entries = std.ArrayList(segment_manifest.Entry).empty;
    defer stale_entries.deinit(std.testing.allocator);
    try stale_entries.ensureTotalCapacity(std.testing.allocator, current_bundle.entries.items.len);
    for (current_bundle.entries.items) |owned_entry| {
        var entry = owned_entry.asEntry();
        if (entry.kind == .node) entry.node_digest ^= 1;
        stale_entries.appendAssumeCapacity(entry);
    }
    const mismatched_generation = try manifest_store.publish(current_bundle.wal_checkpoint_bytes, stale_entries.items);
    try store.publishSegmentBundle(bundle_path);
    var after_digest_mismatch = try segment_bundle.openTrusted(std.testing.allocator, std.testing.io, bundle_path);
    defer after_digest_mismatch.deinit();
    try std.testing.expectEqual(mismatched_generation + 1, after_digest_mismatch.snapshot.generation);

    var ops = std.ArrayList(optimizer.PhysicalOp).empty;
    defer ops.deinit(std.testing.allocator);
    try ops.append(std.testing.allocator, .{ .node_lookup_by_text = .{ .var_name = "f", .kind = .file, .text = "src/delta.zig" } });
    try ops.append(std.testing.allocator, .{ .expand = .{
        .left_var = "f",
        .rel = .defines,
        .right_var = "s",
        .right_kind = .function,
    } });
    try ops.append(std.testing.allocator, .{ .project = &.{} });

    var table = try opened.executeExactTextPath(std.testing.allocator, .{ .ops = ops }, .{});
    defer table.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), table.rows.items.len);
    try std.testing.expectEqual(@as(u64, 1026), table.rows.items[0].get("f").?.toInt());
    try std.testing.expectEqual(@as(u64, 1027), table.rows.items[0].get("s").?.toInt());
}

