test "store segment bundle exact-text runs preserve order across chunks" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const bundle_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "bundle" });
    defer std.testing.allocator.free(bundle_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    const node_count = segment_bundle_exact_sort_chunk_records + 17;
    var nodes = std.ArrayList(graph_mod.Node).empty;
    defer nodes.deinit(std.testing.allocator);
    var text_bytes = std.ArrayList(u8).empty;
    defer text_bytes.deinit(std.testing.allocator);
    try nodes.ensureTotalCapacityPrecise(std.testing.allocator, node_count);
    try text_bytes.ensureTotalCapacityPrecise(std.testing.allocator, node_count * 16);

    var text_buf: [32]u8 = undefined;
    for (0..node_count) |index| {
        const id = index + 1;
        const reverse = node_count - index;
        const text = try std.fmt.bufPrint(&text_buf, "node-{d:0>8}", .{reverse});
        const text_offset = text_bytes.items.len;
        try text_bytes.appendSlice(std.testing.allocator, text);
        nodes.appendAssumeCapacity(.{
            .id = .fromInt(@intCast(id)),
            .kind = .file,
            .text = text_bytes.items[text_offset..][0..text.len],
        });
    }
    try store.appendNodesBatch(nodes.items);

    const meta = try store.readIndexMeta();
    try std.Io.Dir.cwd().createDirPath(std.testing.io, bundle_path);
    var runs = try StoreSegmentBundleExactRuns.build(store, bundle_path, meta);
    defer runs.deinit();
    try std.testing.expectEqual(@as(usize, 2), runs.paths.items.len);

    var stream = StoreSegmentBundleExactStream.init(std.testing.allocator, store, runs.paths.items);
    defer stream.deinit();
    var seen: usize = 0;
    while (try stream.next()) |record| {
        try std.testing.expectEqual(core.NodeKind.file, record.kind);
        try std.testing.expectEqual(@as(u64, @intCast(node_count - seen)), record.id.toInt());
        seen += 1;
    }
    try std.testing.expectEqual(node_count, seen);
}

test "store segment bundle exact-text merger reuses current text buffers" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const bundle_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "bundle" });
    defer std.testing.allocator.free(bundle_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNodesBatch(&.{
        .{ .id = .fromInt(1), .kind = .file, .text = "aaaaaaaaaaaaaaaaaaaa" },
        .{ .id = .fromInt(2), .kind = .file, .text = "b" },
    });

    const meta = try store.readIndexMeta();
    try std.Io.Dir.cwd().createDirPath(std.testing.io, bundle_path);
    var runs = try StoreSegmentBundleExactRuns.build(store, bundle_path, meta);
    defer runs.deinit();
    try std.testing.expectEqual(@as(usize, 1), runs.paths.items.len);

    var merger = try SegmentBundleExactRunMerger.init(std.testing.allocator, store, runs.paths.items);
    defer merger.deinit();
    try std.testing.expectEqualStrings("aaaaaaaaaaaaaaaaaaaa", merger.current.items[0].text.items);
    const ptr = merger.current.items[0].text.items.ptr;
    const capacity = merger.current.items[0].text.capacity;

    const first = (try merger.next()) orelse return error.InvalidRecord;
    try std.testing.expectEqual(@as(u64, 1), first.id.toInt());
    try std.testing.expectEqualStrings("b", merger.current.items[0].text.items);
    try std.testing.expectEqual(ptr, merger.current.items[0].text.items.ptr);
    try std.testing.expectEqual(capacity, merger.current.items[0].text.capacity);

    const second = (try merger.next()) orelse return error.InvalidRecord;
    try std.testing.expectEqual(@as(u64, 2), second.id.toInt());
    try std.testing.expectEqual(@as(usize, 0), merger.current.items[0].text.items.len);
    try std.testing.expectEqual(capacity, merger.current.items[0].text.capacity);
    try std.testing.expect((try merger.next()) == null);
}

