    defer std.testing.allocator.free(tail_path_copy);
    try std.testing.expectEqual(@as(usize, 2), tail.count);
    const expected_digest =
        edgeRecordDigest(.{ .edge_id = 1, .src = 3, .rel = @intFromEnum(core.RelKind.defines), .dst = 2 }) ^
        edgeRecordDigest(.{ .edge_id = 2, .src = 1, .rel = @intFromEnum(core.RelKind.defines), .dst = 4 });
    try std.testing.expectEqual(expected_digest, tail.digest);
    try std.testing.expectEqual(@as(u64, 2 * EdgeIndexRecord.encoded_len), try store.fileSizeOrZero(tail_path));

    tail.deinit(store);
    try std.testing.expect(!try store.fileExists(tail_path_copy));
}

test "store reads edge tail single chunk into sorted in-memory streams" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
