        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = "a" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .file, .text = "b.zig" });
    try store.appendNode(.{ .id = .fromInt(4), .kind = .function, .text = "b" });
    const checkpoint = try store.eventBytes();
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(3), .rel = .defines, .dst = .fromInt(2) },
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .defines, .dst = .fromInt(4) },
    });
    const end = try store.eventBytes();

    var tail = try store.readEdgeAppendTailSpool(checkpoint, end);
    defer tail.deinit(store);
    try std.testing.expect(tail.path != null);

    var forward_records = std.ArrayList(EdgeIndexRecord).empty;
    defer forward_records.deinit(std.testing.allocator);
    var reverse_order = std.ArrayList(u32).empty;
    defer reverse_order.deinit(std.testing.allocator);
    try store.readEdgeTailSortedChunksFromSpool(tail.path.?, tail.count, &forward_records, &reverse_order);

    try std.testing.expectEqual(@as(usize, 2), forward_records.items.len);
    try std.testing.expectEqual(@as(usize, 2), reverse_order.items.len);
    try std.testing.expectEqual(@as(u64, 1), forward_records.items[0].src);
    try std.testing.expectEqual(@as(u64, 3), forward_records.items[1].src);
    try std.testing.expectEqual(@as(u64, 2), forward_records.items[@intCast(reverse_order.items[0])].dst);
    try std.testing.expectEqual(@as(u64, 4), forward_records.items[@intCast(reverse_order.items[1])].dst);

    var forward_stream = EdgeSortedRecordSliceStream.init(forward_records.items);
    try forward_stream.reset();
    try std.testing.expectEqual(@as(u64, 2), (try forward_stream.next()).?.edge_id.toInt());
    try std.testing.expectEqual(@as(u64, 1), (try forward_stream.next()).?.edge_id.toInt());
    try std.testing.expect((try forward_stream.next()) == null);

    var reverse_stream = EdgeSortedRecordOrderStream.init(forward_records.items, reverse_order.items);
    try reverse_stream.reset();
    try std.testing.expectEqual(@as(u64, 1), (try reverse_stream.next()).?.edge_id.toInt());
    try std.testing.expectEqual(@as(u64, 2), (try reverse_stream.next()).?.edge_id.toInt());
    try std.testing.expect((try reverse_stream.next()) == null);
}

