    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "src/main.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = "main" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .function, .text = "helper" });
    try store.appendNode(.{ .id = .fromInt(4), .kind = .function, .text = "cleanup" });
    try store.appendEdge(.{ .id = .fromInt(1), .src = .fromInt(1), .rel = .defines, .dst = .fromInt(2) });

    try store.publishSegmentBundle(bundle_path);
    const manifest_dir = try std.fs.path.join(std.testing.allocator, &.{ bundle_path, segment_bundle.manifest_leaf });
    defer std.testing.allocator.free(manifest_dir);
    var manifest_store = try segment_manifest.Store.init(std.testing.allocator, std.testing.io, manifest_dir);
    defer manifest_store.deinit();

    try store.appendEdge(.{ .id = .fromInt(2), .src = .fromInt(1), .rel = .defines, .dst = .fromInt(3) });
    try store.publishSegmentBundle(bundle_path);
    var delta_snapshot = try manifest_store.pinCurrent();
    var delta_snapshot_pinned = true;
    defer if (delta_snapshot_pinned) delta_snapshot.deinit(std.testing.allocator);
    const delta_node_path = (try segmentManifestUniqueEntry(delta_snapshot, .node)).path;
    const delta_edge_entries = try segmentManifestEdgeEntries(std.testing.allocator, delta_snapshot);
    defer std.testing.allocator.free(delta_edge_entries);
    try std.testing.expectEqual(@as(usize, 2), delta_edge_entries.len);

    try store.appendEdge(.{ .id = .fromInt(3), .src = .fromInt(1), .rel = .defines, .dst = .fromInt(4) });
    const compacted_meta = try store.readIndexMeta();
    try store.publishSegmentBundle(bundle_path);
    var compacted_snapshot = try manifest_store.pinCurrent();
    defer compacted_snapshot.deinit(std.testing.allocator);
    const compacted_node_path = (try segmentManifestUniqueEntry(compacted_snapshot, .node)).path;
    const compacted_edge_entries = try segmentManifestEdgeEntries(std.testing.allocator, compacted_snapshot);
    defer std.testing.allocator.free(compacted_edge_entries);
    try std.testing.expectEqualStrings(delta_node_path, compacted_node_path);
    try std.testing.expectEqual(@as(usize, 1), compacted_edge_entries.len);
    try std.testing.expectEqual(compacted_meta.edges, try segmentManifestEdgeCount(compacted_edge_entries));
    try std.testing.expectEqual(compacted_meta.edge_digest, segmentManifestEdgeDigest(compacted_edge_entries));

    var opened = try segment_bundle.openTrusted(std.testing.allocator, std.testing.io, bundle_path);
    defer opened.deinit();
    try std.testing.expectEqual(@as(u64, 3), try opened.edge_segment.edgeCount());

    delta_snapshot.deinit(std.testing.allocator);
    delta_snapshot_pinned = false;
    const gc = try segment_bundle.gcUnpinned(std.testing.allocator, std.testing.io, bundle_path, &.{});
    try std.testing.expectEqual(@as(u64, 2), gc.deleted_manifests);
    try std.testing.expectEqual(@as(u64, 2), gc.deleted_trees);
}

