test "store compacts tombstoned published segment into visible full segment" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const segment_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-segment" });
    defer std.testing.allocator.free(segment_path);
    const compacted_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-compacted-visible" });
    defer std.testing.allocator.free(compacted_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "src/main.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .function, .text = "old" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .function, .text = "live" });
    try store.appendNode(.{ .id = .fromInt(4), .kind = .function, .text = "next" });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(1), .rel = .defines, .dst = .fromInt(2) },
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .defines, .dst = .fromInt(3) },
    });
    try std.testing.expectEqual(@as(u64, 2), try store.publishEdgeAdjacencySegment(segment_path));
    try store.deleteEdge(.fromInt(1));

    var before = (try store.openPublishedEdgeSegmentsForQuery(std.testing.allocator)).?;
    defer before.deinit();
    try std.testing.expectEqual(PublishedEdgeSegmentsCoverage.full, before.coverage);

    try std.testing.expectEqual(@as(u64, 1), try store.compactPublishedEdgeSegments(compacted_path));
    try store.validatePersistentIndexes();

    var manifest = try store.readEdgeSegmentManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    try std.testing.expectEqual(@as(u64, 1), manifest.totalEdgeCount());

    var after = (try store.openPublishedEdgeSegmentsForQuery(std.testing.allocator)).?;
    defer after.deinit();
    try std.testing.expectEqual(PublishedEdgeSegmentsCoverage.visible_full, after.coverage);

    const CollectContext = struct {
        dsts: *std.ArrayList(u64),
        allocator: std.mem.Allocator,
    };
    var dsts = std.ArrayList(u64).empty;
    defer dsts.deinit(std.testing.allocator);
    var context = CollectContext{ .dsts = &dsts, .allocator = std.testing.allocator };
    _ = try after.segments.forEachNeighbor(.forward, .fromInt(1), .defines, 10, &context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);
    try std.testing.expectEqual(@as(usize, 1), dsts.items.len);
    try std.testing.expectEqual(@as(u64, 3), dsts.items[0]);

    try std.testing.expectError(core.Error.InvalidId, store.appendEdge(.{
        .id = .fromInt(1),
        .src = .fromInt(1),
        .rel = .defines,
        .dst = .fromInt(4),
    }));
