test "store soft deletes edge through tombstone and keeps repair consistent" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const segment_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-base" });
    defer std.testing.allocator.free(segment_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    try store.appendNode(.{ .id = .fromInt(1), .kind = .file, .text = "a.zig" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .file, .text = "b.zig" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .file, .text = "c.zig" });
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(2) },
        .{ .id = .fromInt(2), .src = .fromInt(1), .rel = .mentions, .dst = .fromInt(3) },
    });
    try std.testing.expectEqual(@as(u64, 2), try store.publishEdgeAdjacencySegment(segment_path));

    try store.deleteEdge(.fromInt(1));
    const meta = try store.readIndexMeta();
    try std.testing.expectEqual(@as(u64, 1), meta.edges);
    try std.testing.expectEqual(@as(u64, 2), meta.edge_indexed_edges);
    try std.testing.expect(try store.edgeIndexesMatchMeta(meta));
    var published = (try store.openPublishedEdgeSegments(std.testing.allocator)).?;
    published.deinit();
    const CollectContext = struct {
        dsts: *std.ArrayList(u64),
        allocator: std.mem.Allocator,
    };
    var published_dsts = std.ArrayList(u64).empty;
    defer published_dsts.deinit(std.testing.allocator);
    var published_context = CollectContext{ .dsts = &published_dsts, .allocator = std.testing.allocator };
    _ = try store.forEachPublishedEdgeSegmentNeighbor(.forward, .fromInt(1), .mentions, 10, &published_context, struct {
        fn visit(ctx: *CollectContext, edge: segment_mod.EdgeRecord) !bool {
            try ctx.dsts.append(ctx.allocator, edge.dst.toInt());
            return false;
        }
    }.visit);
    try std.testing.expectEqual(@as(usize, 1), published_dsts.items.len);
    try std.testing.expectEqual(@as(u64, 3), published_dsts.items[0]);
    try std.testing.expectEqual(@as(u64, 3), (try store.nextEdgeId()).toInt());
    try std.testing.expectError(core.Error.InvalidId, store.appendEdge(.{ .id = .fromInt(1), .src = .fromInt(2), .rel = .mentions, .dst = .fromInt(3) }));

    var outgoing = try store.readEdgeIndexRecordsByNode(std.testing.allocator, .src, .fromInt(1));
    defer outgoing.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), outgoing.items.len);
    try std.testing.expectEqual(@as(u64, 2), outgoing.items[0].edge_id);
    try std.testing.expectEqual(@as(u64, 3), outgoing.items[0].dst);

    const stats_out = try store.stats();
    try std.testing.expectEqual(@as(usize, 1), stats_out.edges);
    try store.validatePersistentIndexes();

    try store.repairPersistentIndexesFromLog();
    const repaired_meta = try store.readIndexMeta();
    try std.testing.expectEqual(@as(u64, 1), repaired_meta.edges);
    try std.testing.expect(try store.edgeIndexesMatchMeta(repaired_meta));

    var repaired_outgoing = try store.readEdgeIndexRecordsByNode(std.testing.allocator, .src, .fromInt(1));
    defer repaired_outgoing.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), repaired_outgoing.items.len);
    try std.testing.expectEqual(@as(u64, 2), repaired_outgoing.items[0].edge_id);

    var graph = try store.loadGraph();
    defer graph.deinit();
    try std.testing.expectEqual(core.RecordStatus.deleted, graph.edges.items[0].status);
    try std.testing.expectEqual(core.RecordStatus.active, graph.edges.items[1].status);
}

