    const digest = try store.edgeIndexDigest(store.edge_by_id_path, .id, @intCast(count));
    try std.testing.expectEqual(header.edge_digest, digest.digest);
    try std.testing.expectEqual(header.order_digest, digest.order_digest);
    var index_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.edge_by_id_path, .{});
    defer index_file.close(std.testing.io);
    const index_header = try store.readEdgeIndexHeaderFromFile(index_file);
    const first = try store.readEdgeIndexRecordAt(index_file, index_header, 0);
    try std.testing.expectEqual(@as(u64, 1), first.edge_id);
    const last = try store.readEdgeIndexRecordAt(index_file, index_header, @intCast(count - 1));
    try std.testing.expectEqual(@as(u64, @intCast(count)), last.edge_id);
}

