    try store.createEmpty();

    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edges-all.spool" });
    defer std.testing.allocator.free(spool_path);
    const count = edge_repair_sort_chunk_records + 2;
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(std.testing.io);
        var writer = try StorageBufferedWriter.init(std.testing.allocator, std.testing.io, file, storage_write_buffer_bytes);
        defer writer.deinit();
        var id: usize = count;
        var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        while (id != 0) : (id -= 1) {
            const record = EdgeIndexRecord{
                .src = @intCast(count - id + 1),
                .dst = @intCast(id),
                .edge_id = @intCast(id),
                .rel = @intFromEnum(core.RelKind.mentions),
            };
            record.encode(&bytes);
            try writer.append(&bytes);
        }
        try writer.flush();
    }

    try store.writeEdgeIndexesFromRepairSpool(spool_path, count, null);

    const Check = struct {
        fn index(store_: Store, path: []const u8, order: EdgeIndexOrder, count_: usize) !void {
            const header = try store_.readEdgeIndexHeader(path);
            try std.testing.expectEqual(order, header.order);
            try std.testing.expectEqual(@as(u64, @intCast(count_)), header.edge_count);
            const digest = try store_.edgeIndexDigest(path, order, @intCast(count_));
            try std.testing.expectEqual(header.edge_digest, digest.digest);
            try std.testing.expectEqual(header.order_digest, digest.order_digest);

            var file = try std.Io.Dir.cwd().openFile(std.testing.io, path, .{});
            defer file.close(std.testing.io);
            const file_header = try store_.readEdgeIndexHeaderFromFile(file);
            var previous: ?EdgeIndexRecord = null;
            var pos: usize = 0;
            while (pos < count_) : (pos += 1) {
                const record = try store_.readEdgeIndexRecordAt(file, file_header, @intCast(pos));
                if (previous) |prev| try std.testing.expect(edgeIndexLessThan(order, prev, record));
                previous = record;
            }
        }
    };
    try Check.index(store, store.edge_by_id_path, .id, count);
    try Check.index(store, store.edge_by_src_path, .src, count);
    try Check.index(store, store.edge_by_dst_path, .dst, count);

    const TempCheck = struct {
        fn none(store_: Store, path: []const u8, order: EdgeIndexOrder) !void {
            const tmp_path = try store_.tmpPathFor(path);
            defer std.testing.allocator.free(tmp_path);
            try std.testing.expect(!try store_.pathExists(tmp_path));

            var run_index: usize = 0;
            while (run_index < 2) : (run_index += 1) {
                const run_path = try std.fmt.allocPrint(std.testing.allocator, "{s}.repair_run.{c}.{d}.tmp", .{ path, @intFromEnum(order), run_index });
                defer std.testing.allocator.free(run_path);
                try std.testing.expect(!try store_.pathExists(run_path));
            }
        }
    };
    try TempCheck.none(store, store.edge_by_id_path, .id);
    try TempCheck.none(store, store.edge_by_src_path, .src);
    try TempCheck.none(store, store.edge_by_dst_path, .dst);
}

