    const records = [_]EdgeIndexRecord{
        .{ .src = 1, .dst = 2, .edge_id = 10, .rel = @intFromEnum(core.RelKind.mentions) },
        .{ .src = 1, .dst = 2, .edge_id = 14, .rel = @intFromEnum(core.RelKind.mentions) },
        .{ .src = 2, .dst = 3, .edge_id = 20, .rel = @intFromEnum(core.RelKind.mentions) },
        .{ .src = 2, .dst = 3, .edge_id = 24, .rel = @intFromEnum(core.RelKind.mentions) },
        .{ .src = 3, .dst = 4, .edge_id = 30, .rel = @intFromEnum(core.RelKind.mentions) },
    };
    const header = EdgeIndexHeader.withShape(.src, records.len, 0, 0, false, true, true, edgeRecordsDerivedRel(&records));
    try std.testing.expect(!header.hasKeyRuns());
    const expected_size = try edgeIndexFileSizeForHeader(header);

    var file = try std.Io.Dir.cwd().createFile(std.testing.io, index_path, .{
        .read = true,
        .truncate = true,
    });
    defer file.close(std.testing.io);
    try store.writeCompleteEdgeIndexFile(file, header, &records, expected_size);

    const file_scanned = (try store.readSecondaryRepairKeyRunAt(file, header, 0)) orelse return error.InvalidRecord;
    var map = Store.openReadOnlyMemoryMap(std.testing.io, file, expected_size) catch return error.SkipZigTest;
    defer map.destroy(std.testing.io);
    const mapped = (try Store.readSecondaryRepairKeyRunFromMap(header, &map, 0)) orelse return error.InvalidRecord;

    try std.testing.expectEqual(file_scanned.next_pos, mapped.next_pos);
    try std.testing.expectEqual(file_scanned.run.key, mapped.run.key);
    try std.testing.expectEqual(file_scanned.run.start, mapped.run.start);
    try std.testing.expectEqual(file_scanned.run.opposite, mapped.run.opposite);
    try std.testing.expectEqual(file_scanned.run.edge_id_base, mapped.run.edge_id_base);
    try std.testing.expectEqual(file_scanned.run.edge_id_step, mapped.run.edge_id_step);
    try std.testing.expectEqual(@as(u64, 2), mapped.next_pos);
    try std.testing.expectEqual(@as(u64, 4), mapped.run.edge_id_step);
}

test "store repair edge spool preserves compact ring edge indexes" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edges-ring.spool" });
    defer std.testing.allocator.free(spool_path);
    const node_count: usize = (edge_repair_sort_chunk_records / 4) + 2;
    const count: usize = node_count * 4;
    try std.testing.expect(count > edge_repair_sort_chunk_records);
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(std.testing.io);
        var writer = try StorageBufferedWriter.init(std.testing.allocator, std.testing.io, file, storage_write_buffer_bytes);
        defer writer.deinit();
        var id: usize = count;
        var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        while (id != 0) : (id -= 1) {
            const src = ((id - 1) % node_count) + 1;
            const dst = if (src == node_count) 1 else src + 1;
            const record = EdgeIndexRecord{
                .src = @intCast(src),
                .dst = @intCast(dst),
                .edge_id = @intCast(id),
                .rel = @intFromEnum(core.RelKind.mentions),
            };
            record.encode(&bytes);
            try writer.append(&bytes);
        }
        try writer.flush();
    }

    try store.writeEdgeIndexesFromRepairSpool(spool_path, count, null);

    const id_header = try store.readEdgeIndexHeader(store.edge_by_id_path);
    try std.testing.expect(id_header.hasKeyRuns());
    try std.testing.expect(id_header.hasKeyRunConstantOpposite());
    try std.testing.expectEqual(@as(u16, 0), id_header.record_len);
    try std.testing.expect((try store.fileSizeOrZero(store.edge_by_id_path)) < EdgeIndexHeader.encoded_len + 1024);

    var id_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.edge_by_id_path, .{});
    defer id_file.close(std.testing.io);
    const first_id = try store.readEdgeIndexRecordAt(id_file, id_header, 0);
    try std.testing.expectEqual(@as(u64, 1), first_id.edge_id);
    try std.testing.expectEqual(@as(u64, 1), first_id.src);
    try std.testing.expectEqual(@as(u64, 2), first_id.dst);
    const wrap_id = try store.readEdgeIndexRecordAt(id_file, id_header, @intCast(node_count - 1));
    try std.testing.expectEqual(@as(u64, @intCast(node_count)), wrap_id.edge_id);
    try std.testing.expectEqual(@as(u64, @intCast(node_count)), wrap_id.src);
    try std.testing.expectEqual(@as(u64, 1), wrap_id.dst);

    const src_header = try store.readEdgeIndexHeader(store.edge_by_src_path);
    try std.testing.expect(src_header.hasKeyRuns());
    try std.testing.expect(src_header.hasKeyRunRingOpposite());
    try std.testing.expect(src_header.hasKeyRunUniformEdgeIdStep());
    try std.testing.expect(src_header.hasKeyRunDenseSpan());
    try std.testing.expectEqual(@as(u16, 0), src_header.record_len);
    try std.testing.expectEqual(@as(u64, EdgeIndexHeader.encoded_len), try store.fileSizeOrZero(store.edge_by_src_path));

    var src_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.edge_by_src_path, .{});
    defer src_file.close(std.testing.io);
    const first_src = try store.readEdgeIndexRecordAt(src_file, src_header, 0);
    try std.testing.expectEqual(@as(u64, 1), first_src.src);
    try std.testing.expectEqual(@as(u64, 2), first_src.dst);
    try std.testing.expectEqual(@as(u64, 1), first_src.edge_id);
    const last_src = try store.readEdgeIndexRecordAt(src_file, src_header, @intCast(count - 1));
    try std.testing.expectEqual(@as(u64, @intCast(node_count)), last_src.src);
    try std.testing.expectEqual(@as(u64, 1), last_src.dst);
    try std.testing.expectEqual(@as(u64, @intCast(count)), last_src.edge_id);
}

