        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edges-sorted-ring-tail.spool" });
    defer std.testing.allocator.free(spool_path);
    const node_count: usize = (edge_repair_sort_chunk_records / 4) + 2;
    const count: usize = node_count * 4;
    try std.testing.expect(count > edge_repair_sort_chunk_records);
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(std.testing.io);
        var writer = try StorageBufferedWriter.init(std.testing.allocator, std.testing.io, file, storage_write_buffer_bytes);
        defer writer.deinit();
        var id: usize = 1;
        var bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
        while (id <= count) : (id += 1) {
            const record = if (id == count - 1)
                EdgeIndexRecord{ .src = 1, .dst = 2, .edge_id = @intCast(id), .rel = @intFromEnum(core.RelKind.depends_on) }
            else if (id == count)
                EdgeIndexRecord{ .src = 2, .dst = 3, .edge_id = @intCast(id), .rel = @intFromEnum(core.RelKind.depends_on) }
            else record: {
                const src = ((id - 1) % node_count) + 1;
                const dst = if (src == node_count) 1 else src + 1;
                break :record EdgeIndexRecord{
                    .src = @intCast(src),
                    .dst = @intCast(dst),
                    .edge_id = @intCast(id),
                    .rel = @intFromEnum(core.RelKind.mentions),
                };
            };
            record.encode(&bytes);
            try writer.append(&bytes);
        }
        try writer.flush();
    }

    const shape = (try store.detectDenseRingRepairSpoolShape(spool_path, count)) orelse return error.InvalidRecord;
    try std.testing.expect(shape.has_tail_fixture);
    try std.testing.expect(try store.writeDenseRingIdEdgeIndex(store.edge_by_id_path, shape));
    try std.testing.expect(try store.writeDenseRingSecondaryEdgeIndex(store.edge_by_src_path, .src, shape));
    try std.testing.expect(try store.writeDenseRingSecondaryEdgeIndex(store.edge_by_dst_path, .dst, shape));

    const id_header = try store.readEdgeIndexHeader(store.edge_by_id_path);
    try std.testing.expect(id_header.hasDenseId());
    try std.testing.expect(id_header.hasKeyRuns());
    try std.testing.expect(id_header.hasKeyRunConstantOpposite());
    try std.testing.expectEqual(@as(u16, 0), id_header.record_len);
    try std.testing.expect((try store.fileSizeOrZero(store.edge_by_id_path)) < 1024);
    const src_header = try store.readEdgeIndexHeader(store.edge_by_src_path);
    try std.testing.expect(src_header.hasKeyRuns());
    try std.testing.expect(src_header.hasKeyRunDenseSpan());
    try std.testing.expectEqual(@as(u16, 0), src_header.record_len);
    try std.testing.expect((try store.fileSizeOrZero(store.edge_by_src_path)) < 1024);
    const dst_header = try store.readEdgeIndexHeader(store.edge_by_dst_path);
    try std.testing.expect(dst_header.hasKeyRuns());
    try std.testing.expect(dst_header.hasKeyRunDenseSpan());
    try std.testing.expectEqual(@as(u16, 0), dst_header.record_len);
    try std.testing.expect((try store.fileSizeOrZero(store.edge_by_dst_path)) < 1024);

    const id_digest = try store.edgeIndexDigest(store.edge_by_id_path, .id, @intCast(count));
    try std.testing.expectEqual(shape.edge_digest, id_digest.digest);
    try std.testing.expectEqual(id_header.order_digest, id_digest.order_digest);
    const src_digest = try store.edgeIndexDigest(store.edge_by_src_path, .src, @intCast(count));
    try std.testing.expectEqual(shape.edge_digest, src_digest.digest);
    try std.testing.expectEqual(src_header.order_digest, src_digest.order_digest);
    const dst_digest = try store.edgeIndexDigest(store.edge_by_dst_path, .dst, @intCast(count));
    try std.testing.expectEqual(shape.edge_digest, dst_digest.digest);
    try std.testing.expectEqual(dst_header.order_digest, dst_digest.order_digest);
}

