    try std.testing.expectEqual(@as(u64, 3), (try reader.next(store)).?.edge_id);
    try std.testing.expect((try reader.next(store)) == null);
}

test "store edge segment id sidecar external sort merges multiple runs" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const segment_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "segment" });
    defer std.testing.allocator.free(segment_path);
    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge_ids.spool" });
    defer std.testing.allocator.free(spool_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();
    try std.Io.Dir.cwd().createDirPath(std.testing.io, segment_path);

    const count = edge_segment_id_sort_chunk_records + 2;
    var digest: u64 = 0;
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(std.testing.io);
        var writer = try StorageBufferedWriter.init(std.testing.allocator, std.testing.io, file, storage_write_buffer_bytes);
        defer writer.deinit();
        var id: usize = count;
        var bytes: [8]u8 = undefined;
        while (id != 0) : (id -= 1) {
            const edge_id: u64 = @as(u64, @intCast(id)) * 2;
            digest ^= edgeSegmentIdDigest(edge_id);
            std.mem.writeInt(u64, &bytes, edge_id, .little);
            try writer.append(&bytes);
        }
        try writer.flush();
    }

    var runs = try store.buildEdgeSegmentIdSortedRunsFromSpool(segment_path, spool_path, @intCast(count), 1);
    defer runs.deinit();
    try std.testing.expect(runs.paths.items.len > 1);
    const summary = segment_mod.ImmutableAdjacencySegment.EdgeIdSummary{
        .count = @intCast(count),
        .range = .{ .min = 2, .max = @as(u64, @intCast(count)) * 2 },
        .digest = digest,
    };
    const sidecar = try store.writeEdgeSegmentIdIndexFromRunFiles(segment_path, runs.paths.items, summary);
    var expected_order_digest: u64 = 0;
    var order_index: usize = 0;
    while (order_index < count) : (order_index += 1) {
        expected_order_digest ^= edgeSegmentIdIndexOrderDigestAt(order_index, @as(u64, @intCast(order_index + 1)) * 2);
    }
    try std.testing.expectEqual(expected_order_digest, sidecar.edge_id_order_digest);
    try std.testing.expectEqual(@as(u64, 0), sidecar.edge_id_runs.run_count);

    const sidecar_path = try store.edgeSegmentIdIndexPath(segment_path);
    defer std.testing.allocator.free(sidecar_path);
    var sidecar_file = try std.Io.Dir.cwd().openFile(std.testing.io, sidecar_path, .{});
    defer sidecar_file.close(std.testing.io);
    var header_bytes: [EdgeSegmentIdIndex.header_len]u8 = undefined;
    const n = try sidecar_file.readPositionalAll(std.testing.io, &header_bytes, 0);
    if (n != header_bytes.len) return error.InvalidRecord;
    const header = try decodeEdgeSegmentIdIndexHeader(&header_bytes);
    try std.testing.expectEqual(@as(u64, @intCast(count)), header.edge_count);
    try std.testing.expectEqual(digest, header.edge_id_digest);
    try std.testing.expectEqual(sidecar.edge_id_order_digest, header.edge_id_order_digest);
    try std.testing.expectEqual(@as(u64, 2), try store.readEdgeSegmentIdIndexRecordAt(sidecar_file, 0));
    try std.testing.expectEqual(@as(u64, @intCast(count)) * 2, try store.readEdgeSegmentIdIndexRecordAt(sidecar_file, @intCast(count - 1)));
}

