test "store repair node-text spool external sort merges multiple runs" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "texts.spool" });
    defer std.testing.allocator.free(spool_path);
    const count = node_text_repair_sort_chunk_records + 2;
    const texts_bytes = try std.testing.allocator.alloc(u8, count);
    defer std.testing.allocator.free(texts_bytes);
    @memset(texts_bytes, 'x');
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = store.node_texts_path,
        .data = texts_bytes,
        .flags = .{ .truncate = true },
    });
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(std.testing.io);
        var writer = try StorageBufferedWriter.init(std.testing.allocator, std.testing.io, file, storage_write_buffer_bytes);
        defer writer.deinit();
        var id: usize = count;
        var bytes: [NodeTextIndexRecord.encoded_len]u8 = undefined;
        while (id != 0) : (id -= 1) {
            const record = NodeTextIndexRecord{
                .hash = nodeTextHash("x"),
                .id = @intCast(id),
                .kind = @intFromEnum(core.NodeKind.file),
                .text_offset = @intCast(id - 1),
                .text_len = 1,
            };
            try record.encode(&bytes);
            try writer.append(&bytes);
        }
        try writer.flush();
    }

    try store.writeNodeTextIndexFromRepairSpool(spool_path, count, 0, null);
    var index_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.node_by_text_path, .{});
    defer index_file.close(std.testing.io);
    const header = try store.readNodeTextIndexHeaderFromFile(index_file);
    try std.testing.expectEqual(@as(u64, @intCast(count)), header.node_count);
    try std.testing.expectEqual(@as(u64, 0), header.node_digest);

    var order_digest: u64 = 0;
    var pos: u64 = 0;
    var previous: ?NodeTextIndexRecord = null;
    while (pos < header.node_count) : (pos += 1) {
        const record = try store.readNodeTextIndexRecordAt(index_file, pos);
        if (previous) |prev| try std.testing.expect(nodeTextIndexLessThan({}, prev, record));
        previous = record;
        order_digest = nodeTextIndexOrderDigestStep(order_digest, pos, record);
    }
    try std.testing.expectEqual(header.order_digest, order_digest);
    const first = try store.readNodeTextIndexRecordAt(index_file, 0);
    try std.testing.expectEqual(@as(u64, 1), first.id);
    const last = try store.readNodeTextIndexRecordAt(index_file, @intCast(count - 1));
    try std.testing.expectEqual(@as(u64, @intCast(count)), last.id);
}

test "store repair node-text spool single chunk writes index without temp runs" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
