    });
    defer store.deinit();
    try store.createEmpty();

    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "texts-single.spool" });
    defer std.testing.allocator.free(spool_path);
    const count: usize = 4;
    const texts = [_][]const u8{ "a", "a", "a", "a" };
    var node_digest: u64 = 0;
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = store.node_texts_path,
        .data = "aaaa",
        .flags = .{ .truncate = true },
    });
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
