    defer store.deinit();
    try store.createEmpty();

    const spool_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "tombstones-single.spool" });
    defer std.testing.allocator.free(spool_path);
    const count: usize = 4;
    var edge_records: [count]EdgeIndexRecord = undefined;
    var expected_digest: u64 = 0;
    for (&edge_records, 0..) |*record, index| {
        const edge_id: u64 = @intCast(index + 1);
        record.* = .{
            .src = edge_id,
            .dst = edge_id + 10,
            .edge_id = edge_id,
            .rel = @intFromEnum(core.RelKind.mentions),
        };
        expected_digest ^= edgeRecordDigest(record.*);
    }
    try store.writeEdgeIndex(store.edge_by_id_path, &edge_records);
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, spool_path, .{
            .read = true,
            .truncate = true,
        });
        defer file.close(std.testing.io);
        var writer = try StorageBufferedWriter.init(std.testing.allocator, std.testing.io, file, storage_write_buffer_bytes);
        defer writer.deinit();
        var bytes: [EdgeTombstoneRecord.encoded_len]u8 = undefined;
        for ([_]u64{ 4, 1, 3, 2 }) |edge_id| {
            const record = EdgeTombstoneRecord{
                .edge_id = edge_id,
                .edge_digest = edgeRecordDigest(edge_records[@intCast(edge_id - 1)]),
            };
            record.encode(&bytes);
            try writer.append(&bytes);
        }
        try writer.flush();
    }

    const stale_run_dir = try std.fmt.allocPrint(std.testing.allocator, "{s}.repair_run.0.tmp", .{store.edge_tombstones_path});
    defer std.testing.allocator.free(stale_run_dir);
    try std.Io.Dir.createDirPath(.cwd(), std.testing.io, stale_run_dir);

    try store.writeEdgeTombstoneIndexFromRepairSpool(spool_path, count, expected_digest);
    const header = try store.readEdgeTombstoneIndexHeader();
    try std.testing.expectEqual(@as(u64, @intCast(count)), header.count);
    try std.testing.expectEqual(expected_digest, header.digest);

    var tombstone_file = try std.Io.Dir.cwd().openFile(std.testing.io, store.edge_tombstones_path, .{});
    defer tombstone_file.close(std.testing.io);
    const first = try store.readEdgeTombstoneRecordAt(tombstone_file, 0);
    try std.testing.expectEqual(@as(u64, 1), first.edge_id);
    const last = try store.readEdgeTombstoneRecordAt(tombstone_file, @intCast(count - 1));
    try std.testing.expectEqual(@as(u64, 4), last.edge_id);
}

