test "store reads persistent edge index records by source and destination" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();

    var graph = graph_mod.Graph.init(std.testing.allocator);
    defer graph.deinit();
    const file = try graph.addNode(.file, "src/main.zig");
    const func = try graph.addNode(.function, "main");
    const doc = try graph.addNode(.document, "README");
    const concept = try graph.addNode(.concept, "entrypoint");
    const e1 = try graph.addEdgeUnchecked(file, .mentions, doc);
    const e2 = try graph.addEdgeUnchecked(file, .defines, func);
    const e3 = try graph.addEdgeUnchecked(concept, .references, doc);
    for (graph.nodes.items) |node| try store.appendNode(node);
    try store.appendEdge(graph.edges.items[e1.toInt() - 1]);
    try store.appendEdge(graph.edges.items[e2.toInt() - 1]);
    try store.appendEdge(graph.edges.items[e3.toInt() - 1]);

    var snapshot = try store.loadSnapshot();
    defer snapshot.deinit();

    var by_src = try store.readEdgeIndexRecordsByNode(std.testing.allocator, .src, file);
    defer by_src.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), by_src.items.len);
    try std.testing.expectEqual(@intFromEnum(core.RelKind.defines), by_src.items[0].rel);
    try std.testing.expectEqual(func.toInt(), by_src.items[0].dst);
    try std.testing.expectEqual(@intFromEnum(core.RelKind.mentions), by_src.items[1].rel);
    try std.testing.expectEqual(doc.toInt(), by_src.items[1].dst);

    var by_dst = try store.readEdgeIndexRecordsByNode(std.testing.allocator, .dst, doc);
    defer by_dst.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 2), by_dst.items.len);
    try std.testing.expectEqual(file.toInt(), by_dst.items[0].src);
    try std.testing.expectEqual(concept.toInt(), by_dst.items[1].src);

    var iter = try store.edgeIndexRecordsByNodeIterator(.src, file);
    defer iter.deinit();
    const first = (try iter.next()).?;
    try std.testing.expectEqual(by_src.items[0].edge_id, first.edge_id);
    const second = (try iter.next()).?;
    try std.testing.expectEqual(by_src.items[1].edge_id, second.edge_id);
    try std.testing.expectEqual(@as(?EdgeIndexRecord, null), try iter.next());

    var defines_iter = try store.edgeIndexRecordsByNodeAndRelationIterator(.src, file, .defines);
    defer defines_iter.deinit();
    const defines = (try defines_iter.next()).?;
    try std.testing.expectEqual(@intFromEnum(core.RelKind.defines), defines.rel);
    try std.testing.expectEqual(func.toInt(), defines.dst);
    try std.testing.expectEqual(@as(?EdgeIndexRecord, null), try defines_iter.next());

    var mentions_iter = try store.edgeIndexRecordsByNodeAndRelationIterator(.src, file, .mentions);
    defer mentions_iter.deinit();
    const mentions = (try mentions_iter.next()).?;
    try std.testing.expectEqual(@intFromEnum(core.RelKind.mentions), mentions.rel);
    try std.testing.expectEqual(doc.toInt(), mentions.dst);
    try std.testing.expectEqual(@as(?EdgeIndexRecord, null), try mentions_iter.next());

    var empty_iter = try store.edgeIndexRecordsByNodeIterator(.src, doc);
    defer empty_iter.deinit();
    try std.testing.expectEqual(@as(?EdgeIndexRecord, null), try empty_iter.next());

    var empty_rel_iter = try store.edgeIndexRecordsByNodeAndRelationIterator(.src, file, .contains);
    defer empty_rel_iter.deinit();
    try std.testing.expectEqual(@as(?EdgeIndexRecord, null), try empty_rel_iter.next());
}

