test "store ordered edge traversal includes compacted segment delta edges" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);
    const compacted_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "edge-segments", "compacted" });
    defer std.testing.allocator.free(compacted_path);

    var store = try Store.initWithOptions(std.testing.allocator, std.testing.io, store_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    defer store.deinit();
    try store.createEmpty();

    const src = core.NodeId.fromInt(1);
    try store.appendNode(.{ .id = src, .kind = .document, .text = "doc" });
    try store.appendNode(.{ .id = .fromInt(2), .kind = .observation, .text = "base" });
    try store.appendNode(.{ .id = .fromInt(3), .kind = .observation, .text = "delta-a" });
    try store.appendNode(.{ .id = .fromInt(4), .kind = .observation, .text = "delta-b" });

    var base_edges = std.ArrayList(graph_mod.Edge).empty;
    defer base_edges.deinit(std.testing.allocator);
    try base_edges.ensureTotalCapacity(std.testing.allocator, 1024);
    var edge_id: u64 = 1;
    while (edge_id <= 1024) : (edge_id += 1) {
        base_edges.appendAssumeCapacity(.{
            .id = .fromInt(edge_id),
            .src = src,
            .rel = .mentions,
            .dst = .fromInt(2),
        });
    }
    try store.appendEdgesBatch(base_edges.items);
    try store.appendEdgesBatch(&.{
        .{ .id = .fromInt(1025), .src = src, .rel = .mentions, .dst = .fromInt(3) },
        .{ .id = .fromInt(1026), .src = src, .rel = .mentions, .dst = .fromInt(4) },
    });

    try std.testing.expectEqual(@as(u64, 1026), try store.compactPublishedEdgeSegments(compacted_path));

    var manifest = try store.readEdgeSegmentManifest(std.testing.allocator);
    defer manifest.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1), manifest.entries.items.len);
    try std.testing.expect(manifest.entries.items[0].path.len != 0);

    var indexed_only = try store.readEdgeIndexRecordsByNode(std.testing.allocator, .src, src);
    defer indexed_only.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1024), indexed_only.items.len);

    var ordered = try store.readEdgeIndexRecordsByNodeOrdered(std.testing.allocator, src);
    defer ordered.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(usize, 1026), ordered.items.len);
    try std.testing.expectEqual(@as(u64, 1), ordered.items[0].edge_id);
    try std.testing.expectEqual(@as(u64, 1025), ordered.items[1024].edge_id);
    try std.testing.expectEqual(@as(u64, 1026), ordered.items[1025].edge_id);
}

