test "store rejects malformed persistent edge index records" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const root_path = path_buf[0..root_len];
    const store_path = try std.fs.path.join(std.testing.allocator, &.{ root_path, "kg" });
    defer std.testing.allocator.free(store_path);

    var store = try Store.init(std.testing.allocator, std.testing.io, store_path);
    defer store.deinit();
    try store.createEmpty();

    var record = EdgeIndexRecord{ .src = 1, .dst = 2, .edge_id = 1, .rel = @intFromEnum(core.RelKind.defines) };
    var record_bytes: [EdgeIndexRecord.encoded_len]u8 = undefined;
    record.encode(&record_bytes);
    std.mem.writeInt(u16, record_bytes[24..26], std.math.maxInt(u16), .little);
    var header_bytes: [EdgeIndexHeader.encoded_len]u8 = undefined;
    const header = EdgeIndexHeader{ .order = .src, .edge_count = 1 };
    header.encode(&header_bytes);

    var file = try std.Io.Dir.cwd().createFile(std.testing.io, store.edge_by_src_path, .{ .truncate = true });
    defer file.close(std.testing.io);
    try file.writePositionalAll(std.testing.io, &header_bytes, 0);
    try file.writePositionalAll(std.testing.io, &record_bytes, EdgeIndexHeader.encoded_len);

    try std.testing.expectError(
        error.InvalidRecord,
        store.readEdgeIndexRecordsByNode(std.testing.allocator, .src, core.NodeId.fromInt(1)),
    );
}

