    const old_meta = IndexMeta{
        .nodes = old_header.node_count,
        .node_digest = old_header.node_digest,
        .node_by_text_order_digest = old_header.order_digest,
    };
    var batch = [_]NodeTextIndexRecord{
        records[1],
        records[2],
    };
    const batch_digest = try store.nodeTextIndexRecordDigest(batch[0]) ^
        try store.nodeTextIndexRecordDigest(batch[1]);
