    defer text_index_file.close(std.testing.io);
    const header = try store.readNodeTextIndexHeaderFromFile(text_index_file);
    try std.testing.expectEqual(@as(u64, 3), header.node_count);
    try std.testing.expectEqual(next_digest, header.node_digest);
    try std.testing.expectEqual(@as(u64, 1), (try store.readNodeTextIndexRecordAt(text_index_file, 0)).id);
    try std.testing.expectEqual(@as(u64, 2), (try store.readNodeTextIndexRecordAt(text_index_file, 1)).id);
    try std.testing.expectEqual(@as(u64, 3), (try store.readNodeTextIndexRecordAt(text_index_file, 2)).id);
}

