test "fixed edge binary encoder matches generic event encoder" {
    const edge: graph_mod.Edge = .{ .id = .fromInt(7), .src = .fromInt(3), .dst = .fromInt(9), .rel = .mentions };

    var payload = std.ArrayList(u8).empty;
    defer payload.deinit(std.testing.allocator);
    try appendU64(&payload, std.testing.allocator, edge.id.toInt());
    try appendU64(&payload, std.testing.allocator, edge.src.toInt());
    try appendU16(&payload, std.testing.allocator, @intFromEnum(edge.rel));
    try appendU64(&payload, std.testing.allocator, edge.dst.toInt());
    var generic = std.ArrayList(u8).empty;
    defer generic.deinit(std.testing.allocator);
    try appendBinaryRecord(&generic, std.testing.allocator, .edge, payload.items);

    var fixed: [binary_edge_record_len]u8 = undefined;
    encodeBinaryEdgeRecord(&fixed, edge);
    try std.testing.expectEqualSlices(u8, generic.items, &fixed);

    const header = try BinaryRecordHeader.decode(fixed[0..BinaryRecordHeader.encoded_len]);
    try validateBinaryChecksum(header, fixed[BinaryRecordHeader.encoded_len..]);
    const parsed = try validateBinaryEdgePayload(fixed[BinaryRecordHeader.encoded_len..]);
    try std.testing.expectEqual(edge.id.toInt(), parsed.id);
    try std.testing.expectEqual(edge.src.toInt(), parsed.src);
    try std.testing.expectEqual(edge.dst.toInt(), parsed.dst);
    try std.testing.expectEqual(edge.rel, parsed.rel);
}

test "fixed node binary helpers match generic event encoder" {
    const node: graph_mod.Node = .{ .id = .fromInt(11), .kind = .task, .text = "src/node-batch.zig" };

